    \label{fig:dnspqc}
\end{figure}

\vspace{1em}
\noindent\textbf{Phase 1: Establishing PQC-Secure TLS 1.3 Session}

Let $T_{\text{Phase1}}$ be the total time to establish a post-quantum secure TLS session. We define:

\begin{equation}
T_{\text{Phase1}} = T_{\text{CH}} + T_{\text{SH}} + T_{\text{KEM}} + T_{\text{SIG}} + T_{\text{KDF}} + T_{\text{FIN}} + T_{\text{TERM}}
\end{equation}

% \Comment{
% \noindent where:
% \begin{itemize}
%   \item $T_{\text{CH}}$: ClientHello preparation with PQC key share (e.g., MLKEM).
%   \item $T_{\text{SH}}$: ServerHello with PQC certificate (e.g., MLDSA).
%   \item $T_{\text{KEM}}$: Key encapsulation/decapsulation time.
%   \item $T_{\text{SIG}}$: Digital signature generation/verification.
%   \item $T_{\text{KDF}}$: Derivation of symmetric session keys.
%   \item $T_{\text{FIN}}$: Finished message exchanges.
%   \item $T_{\text{TERM}}$: TLS session closure or reinitialization.
% \end{itemize}
% }
\noindent This handshake ensures post-quantum confidentiality and mutual authentication prior to DNS exchange.
\vspace{1em}

\noindent\textbf{Phase 2: Encrypted Recursive DNS Resolution}

Once TLS is established, DNS queries traverse the traditional recursive path under encryption. The total time for DNS query resolution is:

\begin{equation}
T_{\text{Phase2}} = \sum_{i=1}^{n} (T_{\text{query},i} + T_{\text{response},i}) + \delta_{\text{DNSSEC}} \cdot \sum_{i=1}^{n} T_{\text{DNSSEC},i} + T_{\text{return}}
\end{equation}

\noindent The variables appearing in these equations are defined in Table~\ref{tab:notation}.
