\begin{algorithm}[htp!]
\caption{Post-Quantum Secure DNS Evaluation}
\label{alg1}
\begin{algorithmic}[1]

\Procedure{EvaluateSecureDNS}{$\mathsf{KEM}, \mathsf{DS}, \mathsf{Domain}, N$}

  \State \textbf{// Step 1: TLS Configuration}
  \State Open $\mathsf{openssl.cnf}$
  \State Locate section $\mathsf{[system\_default\_sect]}$
  \State Update $\mathsf{Groups}$ parameter to $\mathsf{KEM}$

  %\Statex
  \State \textbf{// Step 2: Metrics CSV Initialization}
  \State Create CSV with columns:
  \Statex \hspace{1.2em} \{$t$, $l$, $b$, $c$, $r$\}, where:
  \Statex \hspace{1.2em} $t$ = timestamp,\quad $l$ = latency (ms)
  \Statex \hspace{1.2em} $b$ = bandwidth (KB),\quad $c$ = CPU (\%),\quad $r$ = RAM (\%)

  %\Statex
  \State \textbf{// Step 3: Start Traffic Capture}
  \State Launch $\mathsf{tshark}$ on interface $\mathsf{eth0}$
  \State Apply filter: $\mathsf{tcp\ port\ 853}$
  \State Save output to file $\mathsf{dot\_\{KEM\}\_\{DS\}.pcapng}$

  %\Statex
  \State \textbf{// Step 4: Execute DNS Queries}
  \For{$i \gets 1$ to $N$}
    \State $B_{\text{pre}} \gets$ Network I/O snapshot
    \State $T_{\text{start}} \gets$ System time
    \State Execute $\mathsf{dig\ +tls\ @DS\ Domain}$
    \State $T_{\text{end}} \gets$ System time
    \State $B_{\text{post}} \gets$ Network I/O snapshot

    \State $l \gets (T_{\text{end}} - T_{\text{start}}) \times 1000$
    \State $b \gets (B_{\text{post}} - B_{\text{pre}}) / 1024$
    \State $c \gets$ CPU usage from \texttt{/usr/bin/time}
    \State $r \gets$ Peak RSS divided by container memory

    \State Append $\{t, l, b, c, r\}$ to CSV
  \EndFor

  %\Statex
  \State \textbf{// Step 5: Stop Traffic Capture}
  \State Terminate $\mathsf{tshark}$ process

  %\Statex
  \State \textbf{// Step 6: Summary Metric Computation}
  \State Read all records from CSV
  \State Compute: $\bar{l}$, $\bar{b}$, $\bar{c}$, $\bar{r}$
  \State Display summary statistics

  %\Statex
  \State \textbf{// Step 7: TLS Handshake Validation}
  \State Run $\mathsf{tshark -r\ <pcap\_file>}$
  \If{``failure'' in output}
    \State Report TLS handshake error
  \Else
    \State Report handshake success
  \EndIf

  %\Statex
  \State \textbf{// Step 8: Log Final Results}
  \State Append $\{\mathsf{KEM}, \mathsf{DS}, \bar{l}, \bar{b}, \bar{c}, \bar{r}\}$ to:
  \Statex \hspace{1.2em} $\mathsf{dot\_comparison\_results.csv}$

\EndProcedure

\end{algorithmic}
\end{algorithm}
