\begin{thn:k.by.l}
  That in each of \Cref{item:thn:k.by.l:k0.act}-\Cref{item:thn:k.by.l:k0.act.etor} the two respective versions are equivalent is clear from the invariance of the sets in question under left multiplication by $\bK_0$, $\left(\bK_0^{\sigma}\right)_0$ or $\left(\bT^{\sigma}\right)_0$.

  \begin{enumerate}[label={},wide]
  \item\textbf{\Cref{item:thn:k.by.l:ell.dns} $\Leftrightarrow$ \Cref{item:thn:k.by.l:k.act}:} \cite[Lemma 1.7]{2506.09642v1} and the concluding portion of the proof of \cite[Theorem A]{2506.09642v1} combine to prove the equivalence, for the connectedness of $\bK$ is not essential in those arguments.

  \item\textbf{\Cref{item:thn:k.by.l:k.act} $\Leftrightarrow$ \Cref{item:thn:k.by.l:k0.act}:} This is immediate when $\bK$ is Lie (so a finite union of its connected components), which we can always assume by passing to a Lie quotient by a compact normal subgroup of $\bG$.

  \item\textbf{\Cref{item:thn:k.by.l:k0.act.etor} $\Rightarrow$ \Cref{item:thn:k.by.l:k0.act.comm} $\Rightarrow$ \Cref{item:thn:k.by.l:k0.act}} are formal.

  \item\textbf{\Cref{item:thn:k.by.l:k0.act.utor} $\Rightarrow$ \Cref{item:thn:k.by.l:k0.act.etor}:} This follows from the fact that there always are $s$-invariant maximal pro-tori in $\bK_0$:
    \begin{itemize}[wide]
    \item \cite[Theorem 7.5]{stein_endo} gives a linear-algebraic version;

    \item that transports over to compact Lie groups by the correspondence \cite[Chapter VI, \S VIII, Definition 3]{chev_lie-bk_1946} between these and complex linear algebraic groups;

    \item whence the general claim by the usual \cite[Corollary 2.36]{hm5} device of passing to a limit. 
    \end{itemize}

  \item\textbf{\Cref{item:thn:k.by.l:k0.act} $\Rightarrow$ \Cref{item:thn:k.by.l:k0.act.utor}:} The claim is an entirely representation-theoretic one, relegated to \Cref{le:s.cent.tor} below with that statement's $V$ in place of the original $\fl$.  \qedhere
  \end{enumerate}
\end{thn:k.by.l}

In particular, and much as \cite[Lemma 2.9]{MR1044968} suggests, in assessing whether or not an almost-connected locally compact group $\bG$ has a dense set of elliptic elements on e need only consider subgroups of the form $\bG_0\cdot \bD$ for \emph{monothetic} (i.e. \cite[p.254]{zbMATH03104699} topologically cyclic) compact $\bD\le \bG$.

\begin{corollary}\label{cor:mnth.sbgp}
  Let $\bG$ be an almost-connected locally compact group. The set of elliptic elements is dense in $\bG$ if and only if this is so for every closed subgroup of the form $\bG_0\cdot\Braket{d}$ for arbitrary $d\in \bG$. 
\end{corollary}
\begin{proof}
  The discussion on \cite[p.869]{MR1044968} explains how the problem reduces to the semidirect products covered by \Cref{thn:k.by.l} (indeed, to \emph{Lie} semidirect products of that form), and in the latter's context the claim is plain. Note also that we do not need the full force of \Cref{thn:k.by.l}: the equivalence \Cref{item:thn:k.by.l:k.act} $\Leftrightarrow$ \Cref{item:thn:k.by.l:k0.act} suffices.
\end{proof}

The preceding result notwithstanding, \Cref{ex:semidir.z2} illustrates why one cannot generally reduce almost-ellipticity even further to $\bG_0$ alone: there is a qualitative difference between $\bG_0$ and semidirect products $\bG_0\rtimes \left(\bZ/d\right)$. 

The following auxiliary observation effectively proves the implication \Cref{item:thn:k.by.l:k0.act} $\Rightarrow$ \Cref{item:thn:k.by.l:k0.act.comm} of \Cref{thn:k.by.l}, and will be used in proving the formally stronger \Cref{item:thn:k.by.l:k0.act} $\Rightarrow$ \Cref{item:thn:k.by.l:k0.act.utor}. 

\begin{lemma}\label{le:s.cent}
  For a finite-dimensional representation $\bK\xrightarrow{\rho}\mathrm{GL}(V)$ of the compact group $\bK$ we have 
  \begin{equation*}
    \overline{\left\{s\in \bK\ :\ V^s=\{0\}\right\}}
    =
    \bK
    \xRightarrow{\quad}
    \forall\left(\sigma\in \bK\right)
    \left(
      \overline{\left\{s\in \left(\bK_0^{\sigma}\right)_0\ :\ V^{s\sigma}=\{0\}\right\}}
      =
      \left(\bK_0^{\sigma}\right)_0
    \right).
  \end{equation*}
\end{lemma}
\begin{proof}
  there is no harm in assuming all groups in sight Lie. The equivalence \Cref{item:thn:k.by.l:k.act} $\Leftrightarrow$ \Cref{item:thn:k.by.l:k0.act} of \Cref{thn:k.by.l} will also be taken for granted, so that the hypothesis can be phrased as either one of these conditions, as convenient.

  We are assuming $\sigma\in \bK$ arbitrarily approximable by elements $s \sigma\in \bK$ with no 1-eigenvectors in $V$ and $s\in \bK_0$. The claim is that the $s$ can in fact be chosen in the smaller subgroup $\left(\bK_0^{\sigma}\right)_0$ instead. To see this, observe that because
  \begin{equation*}
    \ker\left(1-\Ad_{\sigma}\right)
    =
    \fk^{\sigma}
    =
    Lie\left(\bK_0^{\sigma}\right)_0
  \end{equation*}
  we have 
  \begin{equation*}
    \fk:=Lie(\bK)
    =
    \fk^{\sigma}\oplus \im\left(1-\Ad_{\sigma}\right). 
  \end{equation*}
  It follows that the map
  \begin{equation}\label{eq:tw.ad}
    \bK_0\times \bK_0^{\sigma}
    \ni
    (t,u)
    \xmapsto{\quad}
    t^{-1} \cdot u\cdot \Ad_{\sigma}(t)
    \in \bK_0
  \end{equation}
  is a \emph{submersion} \cite[p.78]{lee2013introduction} at $(1,1)$. it follows \cite[Theorem 4.26]{lee2013introduction} that \Cref{eq:tw.ad} splits locally around $1\in \bK_0$ via some smooth map $(t_{\bullet},u_{\bullet})$:
  \begin{equation*}
    \forall\left(1\sim s\in \bK_0\right)
    \quad:\quad
    t_s^{-1} \cdot u_s\cdot \Ad_{\sigma}(t_s)=s, 
  \end{equation*}
  with `$\sim$' meaning ``close to''. We can now conclude: $s\sigma$ with $1\sim s$ is $t_s$-conjugate to $u_s \sigma$ with $1\sim u_s\in\left(\bK^{\sigma}_0\right)_0$. 
\end{proof}

\begin{lemma}\label{le:s.cent.tor}
  Let $\bK\xrightarrow{\rho}\mathrm{GL}(V)$ be a finite-dimensional representation of the compact group $\bK$. If
  \begin{equation*}
    \overline{\left\{s\in \bK\ :\ V^s=\{0\}\right\}}
    =
    \bK
  \end{equation*}
  then for every $s\in \bK$ and $s$-invariant maximal pro-torus $\bT\le \bK_0$ the set \Cref{eq:etor} with $V$ in place of $\fl$ is dense in $(\bT^s)_0$.
\end{lemma}
\begin{proof}
  $\bK$ will again be Lie. If $\sigma\in \bK$ leaves $\bT$ invariant it also permutes the summands of the corresponding \emph{root-space decomposition} \cite[post Proposition 6.44]{hm5} of $\fk$. It follows that $\bT$ normalizes $\left(\bK_0^{\sigma}\right)_0$, so centralizes (and hence contains) a maximal torus therein.

  There is thus no loss of generality in substituting $\left(\bK_0^{\sigma}\right)_0\cdot \overline{\Braket{\sigma}}$ for $\bK$ and hence assuming $\sigma$ central in $\bK$. Now, though, there is little left to prove: the elements $s\sigma$, $s\in \bK_0$ with no 1-eigenvectors and approximating $\sigma$ arbitrarily are (by the centrality of $\sigma$) $\bK_0$-conjugate to analogous products with $s\in \bT$ instead simply because the conjugates of $\bT$ cover $\bK_0$ \cite[Theorem 9.32]{hm5}. 
\end{proof}

\begin{remarks}\label{res:inv.pro.tor}
  \begin{enumerate}[(1),wide]
  \item\label{item:res:inv.pro.tor:fp} There are other routes to the observation, made in passing in the course of the proof of \Cref{thn:k.by.l}, that a monothetic compact automorphism group of a compact group $\bK$ (which may as well be assumed connected) always leaves invariant some maximal pro-torus $\bT\le \bK$. A number of observations coalesce to confirm this.

    \begin{enumerate}[(I),wide]
    \item The mutual conjugacy \cite[Theorem 9.32]{hm5} of the maximal pro-tori gives the identification
      \begin{equation*}
        \cT(\bK):=\left(\left\{\text{maximal pro-tori}\right\},\ \text{\emph{Vietoris topology} \cite[\S 1.2]{ct_vietoris}}\right)
        \quad
        \cong
        \quad
        \bK/N_{\bK}(\bT),
      \end{equation*}
      with $\bT\le \bK$ a fixed maximal pro-torus and $N_{\bK}(\bullet)$ denoting normalizers.

    \item For compact $\bL\le \Aut(\bK)$ one can always recover 
      \begin{equation*}
        \begin{aligned}
          \bK
          &\cong
            \varprojlim_{\substack{\bM\trianglelefteq \bK\\\bM\text{ is $\bL$-invariant}}}\left(\text{Lie quotient }\bK/\bM\right)
          \quad\text{and}\\
          \cT(\bK)
          &\cong
            \varprojlim_{\substack{\bM\trianglelefteq \bK\\\bM\text{ is $\bL$-invariant}}}\cT\left(\bK/\bM\right)
          \quad
          \text{\cite[Lemma 9.31]{hm5}}
        \end{aligned}    
      \end{equation*}
      simply apply the usual \cite[Corollary 2.36]{hm5} Lie-group approximation result to the semidirect product $\bK\rtimes \bL$. It thus suffices to assume
      \begin{equation*}
        \bK\ \text{and}\ \bL\text{ Lie}
        \quad
        \xRightarrow[\quad\bL\text{ monothetic}\quad]{\quad\text{\cite[Theorem 4.2.4]{de}}\quad}
        \quad
        \bL\cong \bT^d\times \bZ/k.
      \end{equation*}


    \item The quotient space $\cT(\bK)\cong \bK/N_{\bK}(T)$ is \emph{$\bQ$-acyclic} in the sense of \cite[Definition IV.5.11]{bred_gt_1997}. \cite[Lemma 2, pp.50-51]{MR2624762} argues this for unitary groups $\bK:=U(n)$, and the central ingredients are present generally by \cite[Proposition 1.2]{bgg_schubert_en}: 
      \begin{itemize}
      \item the rational cohomology of $\bK/\bT$ is all even;
      \item its dimension (and hence the \emph{Euler characteristic} \cite[Theorem 2.44]{hatch_at} $\chi(\bK/\bT)$) equals
        \begin{equation*}
          |W|
          ,\quad
          W
          :=
          W_{\bK}(\bT)
          :=
          N_{\bK}(\bT)/\bT
          \quad
          \left(\text{\emph{Weyl group} \cite[Definitions 9.30]{hm5} of $\bK$}\right);
        \end{equation*}
      \item and $W$ acts on $\bK/\bT$ freely with quotient $\bK/N_{\bK}(\bT)$, so the latter must have 1-dimensional rational cohomology. 
      \end{itemize}

    \item The fixed-point set $\cT(\bK)^{\bL_0}$ is then again $\bQ$-acyclic \cite[Lemma 1, p.48]{MR2624762}.

    \item And finally, the fixed-point set
      \begin{equation*}
        \cT(\bK)^{\bL}
        =
        \left(\cT(\bK)^{\bL_0}\right)^{\bL/\bL_0}
        =
        \left(\cT(\bK)^{\bL_0}\right)^{\bZ/n}      
      \end{equation*}
      has Euler characteristic 1 (so cannot be empty) by \cite[Lemma 1]{zbMATH03476353}. 
    \end{enumerate}

  \item\label{item:res:inv.pro.tor:lie} When $\bK$ is compact and Lie one need not require the monothetic group $\bL$ to be compact: arbitrary automorphisms of $\bK$ have invariant maximal tori. Indeed, as all maximal tori contain the connected center $Z_0(\bK):=Z(\bK)_0$, we can quotient it out and hence \cite[Theorem 9.24(iv)]{hm5} assume $\bK$ semisimple. In that case, though, its automorphism group is in any case compact \cite[Theorem 6.61(vi)]{hm5}.

    This same observation, it turns out, applies to arbitrary compact groups (though the argument itself does not without some supplementation): per \Cref{th:all.autos.fix.pro-tori}, every automorphism of a compact group leaves invariant some maximal pro-torus.
  \end{enumerate}
\end{remarks}

It turns out that \emph{arbitrary} (possibly non-elliptic) automorphisms of compact connected groups have invariant maximal pro-tori.

\begin{theorem}\label{th:all.autos.fix.pro-tori}
  An automorphism of a compact group $\bK$ leaves invariant some maximal pro-torus $\bT\le \bK_0$. 
\end{theorem}
\begin{proof}
  We will harmlessly assume $\bK$ connected throughout, as well as \emph{semisimple} (in the sense of \cite[Definition 9.5]{hm5}): this has no effect on the argument, as observed in \Cref{res:inv.pro.tor}\Cref{item:res:inv.pro.tor:lie}. An automorphism of $\bK$ will induce one on its \emph{pro-Lie algebra} 
  \begin{equation*}
    \fk:=Lie(\bK)
    \overset{\text{\cite[\S 2]{hm_pro-lie-struct}}}{\cong}
    \prod_{j\in J}\fs_j
    ,\quad
    \text{simple compact Lie algebras }\fs_j
  \end{equation*}
  and hence on the product $\widetilde{\bK}\cong \prod_j \bS_j$ of compact, simple, simply-connected Lie groups $\bS_j$ equipped with a profinite-kernel surjection
  \begin{equation*}
    \widetilde{\bK}
    \xrightarrowdbl{\quad}
    \bK
    \quad
    \left(\text{\cite[Corollary 9.25]{hm5}, where $\widetilde{\bK}$ would be $\bK^*$}\right).
  \end{equation*}
  Because images of maximal pro-tori through surjections are again such \cite[Lemma 9.31]{hm5}, it is enough to assume $\bK$ of the form $\prod_j \bS_j$. 

  An automorphism $\alpha\in \Aut(\bK)$ will then permute the factors $\bS_j$ \cite[Proposition 3.1 and Theorem 2.10]{hm_pro-lie-struct}, hence an induced permutation $\alpha\circlearrowright J$ (denoted abusively by the same symbol as the original automorphism) and an $\alpha$-invariant decomposition
  \begin{equation*}
    \bK=\bK_{\infty} \times \bK_{<\infty}
    \quad\text{where}\quad
    \begin{aligned}
      \bK_{\infty}
      &:=
        \prod_{|\alpha j|=\aleph_0}\prod_{j'\in \alpha_j}\bS_{j'}\\
      \bK_{<\infty}
      &:=
        \prod_{|\alpha j|<\infty}\prod_{j'\in \alpha_j}\bS_{j'}.
    \end{aligned}
  \end{equation*}
  The two factors can be handled separately, and the conclusion follows.
  \begin{itemize}[wide]
  \item On $\bK_{<\infty}$ the automorphism $\alpha$ is elliptic \cite[Lemma 2.6(ii)]{hm_pro-lie-struct} so the preceding discussion (e.g. \Cref{res:inv.pro.tor}\Cref{item:res:inv.pro.tor:fp}) applies.

  \item On the other hand, $\bK_{\infty}$ plainly has an $\alpha$-invariant maximal pro-torus: $\prod_j \bT_j$, where $\bT_j\le \bS_j$ is a fixed maximal pro-torus selected arbitrarily for $j$ ranging over a system of representatives for the infinite orbits of $\alpha$ and $\bT_{\alpha j}:=\alpha \bT_j$ for all infinite-orbit $j$. 
  \end{itemize}
\end{proof}



