\section{A formula for the second derivative of marginals} \label{sec:comp}

In this section, we present a formula for the second derivative of marginals using the $L_2$ method.  Our computation relies on a mixture of the methods of Nguyen \cite[Theorem~1.1]{Ngu14a} and Kolesnikov--Milman \cite[Section~3.1]{KM18}, albeit with several substantial modifications which are necessary to treat the combination of the functional and geometric settings treated here.

%-------------------------------------------------------------------------------------------------------------------

\subsection{Perturbations of convex sets} Before proceeding to the actual computation, we present some preliminaries related to the variation of measures of convex sets under small perturbations.  Let $\{\Omega_t\}_{t\in(-\eta,\eta)}$ be a family of bounded convex sets in $\R^n$ with nonempty interiors and assume that each $\Omega_t$ is strictly convex with $C^2$ boundary $\Sigma_t$. Moreover, let $g:(-\eta,\eta)\times\Sigma_0\to\R$ be such that
\begin{equation} \label{eq:defn-g}
\forall \ (t,y)\in(-\eta,\eta)\times\Sigma_0,\qquad h_{\Omega_t} \big(\hat{\nu}_{\Sigma_0}(y)\big) = g(t,y),
\end{equation}
where as usual we denote by $h_L:\mb{S}^{n-1}\to\R$ the support function of a convex body $L$ in $\R^n$ and by $\hat{\nu}_L:\partial L\to\mb{S}^{n-1}$ its outward pointing unit normal vector.  We shall assume that $g$ is jointly $C^2$ smooth. Moreover, consider the mapping $F:(-\eta,\eta)\times \Sigma_0  \to \R^n$ given by
\begin{equation} \label{eq:defn-F}
\forall \ (t,y)\in(-\eta,\eta)\times\Sigma_0,\qquad F(t,y) = \hat{\nu}_{\Sigma_t}^{-1} \circ \hat{\nu}_{\Sigma_0}(y).
\end{equation}
Observe that due to the strict convexity and regularity assumptions imposed on $\Omega_t$,  $F_0\eqdef F(0,\cdot) \equiv \mathrm{Id}$ and each $F_t \eqdef F(t,\cdot): \Sigma_0\to\Sigma_t$ is a diffeomorphism that satisfies the compatibility equation
\begin{equation} \label{eq:compat}
\forall \ (t,y)\in(-\eta,\eta)\times\Sigma_0,\qquad \hat{\nu}_{\Sigma_t} \big( F(t,y) \big) = \hat{\nu}_{\Sigma_0}(y).
\end{equation}  
Its $t$-derivative is calculated in the following lemma which builds upon \cite[Proposition~6.3]{KM18}, where the special case $\Omega_t = K+tL$,  where $t\in(0,\infty)$, was treated.

\begin{lemma} \label{lem:Minkowski-var}
Under the preceding regularity assumptions on $\{\Omega_t\}_{t\in(-\eta,\eta)}$, we have
\begin{equation} \label{eq:Minkowski-var}
\forall \ (t,y)\in(-\eta,\eta)\times\Sigma_0, \qquad \frac{\partial}{\partial t}F(t,y) = \psi_t(y) \hat\nu_{\Sigma_0}(y) + \mr{I\!I}_{\Sigma_0}^{-1}(y) \nabla_{\Sigma_0} \psi_t(y),
\end{equation}
where $\psi_t:\Sigma_0\to\R$ is given by $\psi_t(y) = \frac{\partial}{\partial t}g(t,y)$.
\end{lemma}

\begin{proof}
By the definition \eqref{eq:defn-g} of $g$ and the chain rule, we have
\begin{equation}
\nabla_{\Sigma_0}g(t,y) = \nabla_{\Sigma_0} \big( h_{\Omega_t}\circ \hat{\nu}_{\Sigma_0}\big)(y) = \nabla_{\Sigma_0} \hat{\nu}_{\Sigma_0}(y)  \nabla_{\mb{S}^{n-1}} h_{\Omega_t}\big( \hat{\nu}_{\Sigma_0}(y)\big) = \mr{I\!I}_{\Sigma_0}(y) \nabla_{\mb{S}^{n-1}} h_{\Omega_t}\big( \hat{\nu}_{\Sigma_0}(y)\big).
\end{equation}
On the other hand, for an arbitrary strictly convex body $L$,  we have (see, e.g., \cite[Proposition~6.3]{KM18})
\begin{equation}
\forall \ \theta\in\mb{S}^{n-1},\qquad \nabla_{\mb{S}^{n-1}} h_{L}(\theta) = \hat{\nu}_{\partial L}^{-1}(\theta) - \langle \hat{\nu}_{\partial L}^{-1}(\theta),\theta\rangle\theta = \hat{\nu}_{\partial L}^{-1}(\theta) - h_L(\theta)\theta.
\end{equation}
Therefore, combining the above, we derive
\begin{equation}
\nabla_{\Sigma_0}g(t,y) =  \mr{I\!I}_{\Sigma_0}(y) \big\{ \hat{\nu}_{\Sigma_t}^{-1} \circ\hat{\nu}_{\Sigma_0}(y) - h_{\Omega_t}\big(\hat{\nu}_{\Sigma_0}(y)\big) \hat{\nu}_{\Sigma_0}(y)\big\} = \mr{I\!I}_{\Sigma_0}(y) \big\{  F(t,y) - g(t,y) \hat{\nu}_{\Sigma_0}(y) \big\},
\end{equation}
which can be equivalently rewritten as
\begin{equation}
F(t,y) = g(t,y) \hat{\nu}_{\Sigma_0}(y) + \mr{I\!I}_{\Sigma_0}^{-1}(y) \nabla_{\Sigma_0}g(t,y). 
\end{equation}
Taking a derivative in $t$, we readily see that since $g$ is $C^2$,
\begin{equation}
\frac{\partial}{\partial t} F(t,y) = \frac{\partial }{\partial t} g(t,y) \hat{\nu}_{\Sigma_0}(y) + \mr{I\!I}_{\Sigma_0}^{-1}(y) \nabla_{\Sigma_0} \frac{\partial}{\partial t} g(t,y),
\end{equation}
which coincides with \eqref{eq:Minkowski-var} by the definition of $\psi_t$.
\end{proof}

Having computed the $t$-derivative of the parametrization $F_t:\Sigma_0\to\Sigma_t$, we can also derive formulas for the evolution of the measure of the convex sets $\{\Omega_t\}_{t\in(-\eta,\eta)}$.

\begin{lemma}
Let $\diff\rho(x) = e^{-U(x)}\,\diff x$ be an absolutely continuous finite measure on $\R^n$ with $C^1$ smooth density. Under the preceding regularity assumptions on $\{\Omega_t\}_{t\in(-\eta,\eta)}$, we have
\begin{equation} \label{eq:first-var}
\forall \ t\in(-\eta,\eta),\qquad \frac{\diff}{\diff t} \rho(\Omega_t)= \rmint_{\Sigma_t} \psi_t\big(F_t^{-1}(x)\big) \, \diff\rho(x) = \rmint_{\Sigma_0} \psi_t(y) e^{-U(F(t,y))} \mr{Jac} F_t(y)\, \diff y
\end{equation}
and
\begin{equation} \label{eq:second-var}
\frac{\diff^2}{\diff t^2}\bigg|_{t=0} \rho(\Omega_t) = \rmint_{\Sigma_0} \frac{\partial}{\partial t}\bigg|_{t=0}\psi_t \,\diff\rho +\rmint_{\Sigma_0} \msf{H}_{\Sigma_0,\rho} \cdot \psi_0^2 - \langle \mr{I\!I}_{\Sigma_0}^{-1} \nabla_{\Sigma_0} \psi_0, \nabla_{\Sigma_0}\psi_0\rangle\,\diff\rho.
\end{equation}
\end{lemma}

\begin{proof}
The first variation of $\rho(\Omega_t)$ only depends on the normal component of the derivative of the parametrization $F(t,\cdot)$ around the identity $F(0,\cdot)$, and thus
\begin{equation}
\frac{\diff}{\diff t} \bigg|_{t=0} \rho(\Omega_t) = \rmint_{\Sigma_0} \psi_0 \,\diff \rho,
\end{equation}
which coincides with \eqref{eq:first-var} at $t=0$.  To derive the formula in general, fix $T\in(-\eta,\eta)$ and notice that we also have
\begin{equation}
\forall \ (t,x)\in (-\eta,\eta)\times\Sigma_T,\qquad h_{\Omega_t} \big( \hat{\nu}_{\Sigma_T}(x)\big) = h_{\Omega_t}\big(\hat{\nu}_{\Sigma_0}\big(F_T^{-1}(x)\big)\big) = g\big(t, F_T^{-1}(x)\big).
\end{equation}
Therefore,  the same reasoning for the function $(t,x)\mapsto g(t,F_T^{-1}(x))$ around $t=T$ yields
\begin{equation*}
\frac{\diff}{\diff t}\bigg|_{t=T} \rho(\Omega_t) = \rmint_{\Sigma_T} \frac{\partial}{\partial t}\bigg|_{t=T} g\big(t,F_T^{-1}(x)\big)\, \diff \rho(x) = \rmint_{\Sigma_T} \psi_T\circ F_T^{-1}(x) \,\diff \rho(x)
\end{equation*}
and the last equality of \eqref{eq:first-var} follows by the change of variables $x=F_T(y)$. 

For the derivation of \eqref{eq:second-var}, we first use \eqref{eq:first-var} to get
\begin{equation}
\frac{\diff^2}{\diff t^2}\bigg|_{t=0} \rho(\Omega_t) = \rmint_{\Sigma_0} \frac{\partial}{\partial t}\bigg|_{t=0}\psi_t \,\diff\rho +\rmint_{\Sigma_0} \psi_0(y) \frac{\partial}{\partial t}\bigg|_{t=0} \Big\{ e^{-U(F(t,y))} \mr{Jac} F_t(y) \Big\} \,\diff y.
\end{equation}
The derivative of the latter quantity is computed in the proof of \cite[Theorem~6.6]{KM18} and plugging in this expression readily yields the desired identity \eqref{eq:second-var}.
\end{proof}

%-------------------------------------------------------------------------------------------------------------------

\subsection{The second derivative of marginals} Having presented the necessary background material, we can proceed to the proof of our main representation for the second derivative.

\begin{proposition} \label{prop:nguyen}
Fix $\diff\mu(x) = e^{-W(x)}\,\diff x$ a measure on $\R^{n}$, where $W:\R^n\to\R$ is $C^2$ smooth.  Let $\Omega \subseteq\R^{n+1}$ be a bounded open convex set with $C^3$ smooth boundary and for $t\in\R$, denote by $\Omega_t = \{x: \ (t,x)\in\Omega\}$ and $\Sigma_t = \partial\Omega_t$.  Assume that each $\Omega_t$ is strictly convex with nonempty interior for $t\in(-\eta,\eta)$.
Let $\Phi:\overline{\Omega}\to(0,\infty)$ be a function which is $C^{2}$ smooth and positive on $\overline{\Omega}$.  Moreover, for $\beta,\gamma\in\R\setminus\{0\}$,  consider the function $\varphi:(-\eta,\eta) \to\R_+$  given by
\begin{equation} \label{eq:phi}
\forall \ t\in (-\eta,\eta), \qquad \varphi(t) = \Bigg( \rmint_{\Omega_t} \Phi(t,x)^\beta\,\diff\mu(x)\Bigg)^{\gamma},
\end{equation}
Consider the probability measure $\nu$ on $\Omega_0$ given by 
\begin{equation}\label{eq:u}
\forall \ x\in \Omega_0,\qquad \frac{\diff\nu(x)}{\diff\mu(x)} = \frac{\Phi(0,x)^\beta}{\varphi(0)^{1/\gamma}}
\end{equation}
and let $u:\overline{\Omega_0}\to\R$ be a smooth function satisfying
\begin{equation} \label{eq:nguyen-eq}
\forall \ x\in \Omega_0,\qquad \ms{L}_{\nu} u(x) = \frac{\partial_t \Phi(0,x)}{\Phi(0,x)} - \rmint_{\Omega_0} \frac{\partial_t\Phi(0,\cdot)}{\Phi(0,\cdot)} \,\diff\nu - \frac{1}{\beta} \rmint_{\Sigma_0} \psi \,\diff\nu,
\end{equation}
and 
\begin{equation} \label{eq:nguyen-neumann}
\forall \ x\in\Sigma_0,\qquad \frac{\partial u(x)}{\partial \hat{\nu}_{\Sigma_0}} = -\frac{1}{\beta} \psi(x),
\end{equation}
where $\psi\equiv\psi_0:\Sigma_0\to\R$ is the variation appearing in \eqref{eq:Minkowski-var}. Then, we have
\begin{equation} \label{eq:nguyen}
\begin{split}
& \frac{1}{\gamma}\frac{\varphi''(0)}{\varphi(0)}  =  \beta \rmint_{\Omega_0} \frac{\langle\nabla^2_{(t,x)}\Phi(0,\cdot) X,X\rangle}{\Phi(0,\cdot)} \,\diff\nu - \beta^2 \rmint_{\Omega_0} \|\nabla^2 u\|_{\mr{HS}}^2 + \langle \nabla^2W \nabla u, \nabla u\rangle \, \diff\nu 
\\&  - \beta \rmint_{\Omega_0} (\ms{L}_\mu u)^2\,\diff\nu  - \beta(1-\beta\gamma) \Bigg(\rmint_{\Omega_0} \frac{\partial_t \Phi(0,\cdot)}{\Phi(0,\cdot)} \,\diff\nu\Bigg)^2-\Big(\frac{1}{\beta}-\gamma\Big) \Bigg(\rmint_{\Sigma_0} \psi \,\diff\nu\Bigg)^2
\\ & - 2 \beta \Bigg(\rmint_{\Omega_0} \ms{L}_\mu u\,\diff\nu\Bigg) \Bigg( \rmint_{\Omega_0} \frac{\partial_t \Phi(0,\cdot)}{\Phi(0,\cdot)}\,\diff\nu\Bigg) - 2 \Bigg(\rmint_{\Omega_0} \ms{L}_\mu u\,\diff\nu\Bigg) \Bigg(\rmint_{\Sigma_0} \psi \,\diff\nu\Bigg)
\\ & -2\beta\Big(\frac{1}{\beta}-\gamma\Big)  \Bigg( \rmint_{\Omega_0} \frac{\partial_t \Phi(0,\cdot)}{\Phi(0,\cdot)}\,\diff\nu\Bigg)\Bigg(\rmint_{\Sigma_0} \psi \,\diff\nu\Bigg) - \beta\rmint_{\Sigma_0} \frac{\partial_t\Phi(0,\cdot)}{\Phi(0,\cdot)} \cdot \psi\,\diff\nu + \rmint_{\Sigma_0} \frac{\partial}{\partial t}\bigg|_{t=0}\psi_t \,\diff\nu
\\ & - \rmint_{\Sigma_0} \beta^2 \langle \mr{I\!I}_{\Sigma_0}\nabla_{\Sigma_0} u,\nabla_{\Sigma_0} u\rangle +\langle \mr{I\!I}_{\Sigma_0}^{-1}\nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}\psi\rangle + 2\beta \langle \nabla_{\Sigma_0}\psi, \nabla_{\Sigma_0}u\rangle \,\diff\nu,
\end{split}
\end{equation}
where $X$ is the vector field $(1,-\beta\nabla u)$ on $\Omega_0$.
\end{proposition}

\begin{proof}
We shall make a slight abuse of notation by writing $\Phi_0\equiv\Phi(0,\cdot)$, $\partial_t\Phi_0 \equiv \partial_t \Phi(0,\cdot)$ and $\psi\equiv\psi_0$.  Observe that as the boundary $\Sigma$ of $\Omega$ is $C^3$ smooth, the same holds for each $\Sigma_t$.  Additionally, we will prove that the function $g:(-\eta,\eta)\times\Sigma_0\to\R$ defined by \eqref{eq:defn-g} is jointly  $C^2$ smooth.  To see this, observe that \eqref{eq:defn-g} and \eqref{eq:defn-F} readily imply that
\begin{equation}
\forall  \ (t,y)\in(-\eta,\eta)\times \Sigma_0, \qquad g(t,y) = \langle F(t,y) , \hat{\nu}_{\Sigma_0}(y) \rangle,
\end{equation}
so it suffices to prove that $(t,y)\mapsto (t,F_t(y))$ is $C^2$.  By the inverse function theorem, we equivalently need to prove that $\Sigma\cap\{|t|<\eta\} \ni (t,x) \mapsto (t,F_t^{-1}(x))$ is $C^2$ smooth.  
This is indeed true since
\begin{equation}
\forall \ (t,x)\in \Sigma\cap\{|t|<\eta\},\qquad F_t^{-1}(x) = \hat{\nu}_{\Sigma_0}^{-1}\circ \hat{\nu}_{\Sigma_t}(x)
\end{equation}
and
\begin{equation} \label{eq:norm-sec}
\forall \ x\in\Sigma_t, \qquad \hat{\nu}_{\Sigma_t}(x) = \frac{\hat{\nu}_\Sigma(t,x) - \langle \hat{\nu}_\Sigma(t,x), e_{1} \rangle e_1}{|\hat{\nu}_\Sigma(t,x) - \langle \hat{\nu}_\Sigma(t,x), e_{1} \rangle e_1|},
\end{equation}
and $\hat{\nu}_\Sigma$ is jointly $C^2$ smooth.  To justify the last identity, observe that the condition $\Omega_t\neq\emptyset$ for all $t\in(-\eta,\eta)$ implies that the denominator in \eqref{eq:norm-sec} never vanishes. 

Therefore, using Lemma \ref{lem:Minkowski-var} and the product rule, we differentiate under the integral sign to get
\begin{equation}
\frac{1}{\gamma}\varphi'(t) \stackrel{\eqref{eq:first-var}}{=}  \Bigg( \rmint_{\Omega_t} \Phi(t,x)^\beta\,\diff\mu(x)\Bigg)^{\gamma-1}\!\!\! \cdot \Bigg\{ \beta \rmint_{\Omega_t} \Phi(t,\cdot)^{\beta-1}\cdot \partial_t\Phi(t,\cdot)\,\diff\mu + \rmint_{\Sigma_t} \Phi(t,\cdot)^\beta\cdot \psi_t\circ F_t^{-1} \,\diff\mu\Bigg\}
\end{equation}
and similarly, since $F_0$ is the identity,
\begin{equation}
\begin{split}
\frac{1}{\gamma}& \varphi''(0) = (\gamma-1)\Bigg( \rmint_{\Omega_0} \Phi_0^\beta\,\diff\mu\Bigg)^{\gamma-2} \cdot \Bigg\{ \beta \rmint_{\Omega_0} \Phi_0^{\beta-1}\cdot \partial_t\Phi_0\,\diff\mu + \rmint_{\Sigma_0} \Phi_0^\beta\cdot \psi \,\diff\mu\Bigg\}^2
\\ & + \Bigg( \rmint_{\Omega_0} \Phi_0^\beta\,\diff\mu\Bigg)^{\gamma-1} \cdot \frac{\diff }{\diff t} \bigg|_{t=0} \Bigg\{ \beta \rmint_{\Omega_t} \Phi(t,\cdot)^{\beta-1} \cdot \partial_t\Phi(t,\cdot)\,\diff\mu + \rmint_{\Sigma_t} \Phi(t,\cdot)^\beta\cdot \psi_t\circ F_t^{-1} \,\diff\mu\Bigg\}.
\end{split}
\end{equation}
To evaluate the latter derivative, observe that \eqref{eq:first-var} again yields
\begin{equation}
\begin{split}
 \frac{\diff }{\diff t} \bigg|_{t=0}  \beta \rmint_{\Omega_t} \Phi(t,\cdot)^{\beta-1}\cdot \partial_t\Phi(t,\cdot)\,\diff\mu \stackrel{\eqref{eq:first-var}}{=}  \beta  \rmint_{\Omega_0}(\beta-1)\cdot \Phi_0^{\beta-2} \cdot (\partial_t&\Phi_0) ^2 + \Phi_0^{\beta-1}\cdot \partial_{tt}\Phi_0 \,\diff\mu 
 \\ & + \beta \rmint_{\Sigma_0} \Phi_0^{\beta-1}\cdot \partial_t \Phi_0\cdot \psi \,\diff\mu,
 \end{split}
\end{equation}
whereas \eqref{eq:second-var} combined with a change of variables gives
\begin{equation}
\begin{split}
\frac{\diff }{\diff t} \bigg|_{t=0}  \rmint_{\Sigma_t} \Phi(t,\cdot)^\beta  \cdot \psi_t\circ F_t^{-1} &\,\diff\mu  = \frac{\diff }{\diff t} \bigg|_{t=0} \rmint_{\Sigma_0} \psi_t(y) \cdot e^{-W(F(t,y))}\cdot \Phi(t,F(t,y))^\beta \cdot \mathrm{Jac}F_t(y) \, \diff y
\\ & \stackrel{\eqref{eq:second-var}}{=} \rmint_{\Sigma_0} \frac{\partial}{\partial t}\bigg|_{t=0}\psi_t \,\diff\widetilde{\nu} + \rmint_{\Sigma_0} \msf{H}_{\Sigma_0,\widetilde{\nu}}\cdot  \psi^2 - \langle \mr{I\!I}_{\Sigma_0}^{-1}\nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}\psi\rangle \,\diff\widetilde{\nu},
\end{split}
\end{equation}
where we use the ad hoc notation $\diff\widetilde{\nu} \eqdef \Phi_0^\beta\, \diff\mu$. Considering the normalized measure $\nu\equiv\frac{\widetilde{\nu}}{\widetilde{\nu}(\Omega_0)}$ and combining all the above, we derive the formula
\begin{equation} \label{eq:second-derivative}
\begin{split}
\frac{1}{\gamma} \frac{\varphi''(0)}{\varphi(0)}
& =\beta \rmint_{\Omega_0} \frac{\partial_{tt}\Phi_0}{\Phi_0}\,\diff\nu+  \beta(\beta-1)\rmint_{\Omega_0} \left(\frac{\partial_t\Phi_0}{\Phi_0}\right)^2\,\diff\nu +\beta^2(\gamma-1) \Bigg(\rmint_{\Omega_0} \frac{\partial_t \Phi_0}{\Phi_0} \,\diff\nu\Bigg)^2
\\ & +2\beta(\gamma-1) \Bigg(\rmint_{\Omega_0} \frac{\partial_t \Phi_0}{\Phi_0} \,\diff\nu \Bigg)\Bigg( \rmint_{\Sigma_0} \psi \,\diff\nu \Bigg) + (\gamma-1) \Bigg(\rmint_{\Sigma_0} \psi\,\diff\nu\Bigg)^2
\\ & + \beta\rmint_{\Sigma_0} \frac{\partial_t \Phi_0}{\Phi_0} \cdot \psi\,\diff\nu + \rmint_{\Sigma_0} \frac{\partial}{\partial t}\bigg|_{t=0}\psi_t \,\diff\nu+ \rmint_{\Sigma_0} \msf{H}_{\Sigma_0,\nu}\cdot \psi^2 - \langle \mr{I\!I}_{\Sigma_0}^{-1}\nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}\psi\rangle \,\diff \nu
\\ & = \beta \rmint_{\Omega_0} \frac{\partial_{tt}\Phi_0}{\Phi_0}\,\diff\nu + \beta(\beta-1)\mathrm{Var}_{\nu} \Bigg( \frac{\partial_t\Phi_0}{\Phi_0} \Bigg) +\beta(\beta\gamma-1) \Bigg(\rmint_{\Omega_0} \frac{\partial_t \Phi_0}{\Phi_0} \,\diff\nu\Bigg)^2
\\ & +2\beta(\gamma-1) \Bigg(\rmint_{\Omega_0} \frac{\partial_t \Phi_0}{\Phi_0} \,\diff\nu \Bigg)\Bigg( \rmint_{\Sigma_0} \psi \,\diff\nu \Bigg) + (\gamma-1) \Bigg(\rmint_{\Sigma_0} \psi\,\diff\nu\Bigg)^2
\\ & + \beta\rmint_{\Sigma_0} \frac{\partial_t \Phi_0}{\Phi_0} \cdot \psi\,\diff\nu  + \rmint_{\Sigma_0} \frac{\partial}{\partial t}\bigg|_{t=0}\psi_t \,\diff\nu+ \rmint_{\Sigma_0} \msf{H}_{\Sigma_0,\nu}\cdot \psi^2 - \langle \mr{I\!I}_{\Sigma_0}^{-1}\nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}\psi\rangle \,\diff \nu.
\end{split}
\end{equation}
Consider now the function $u:\overline{\Omega_0}\to\R$ solving equation \eqref{eq:nguyen-eq} with Neumann boundary data \eqref{eq:nguyen-neumann}. By the integration by parts formula \eqref{eq:bp}, we can rewrite the variance as
\begin{equation}
\begin{split}
&\mathrm{Var}_{\nu} \Bigg( \frac{\partial_t\Phi_0}{\Phi_0} \Bigg) = \rmint_{\Omega_0} \Bigg( \frac{\partial_t\Phi_0}{\Phi_0} - \rmint_{\Omega_0} \frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu  \Bigg) \ms{L}_\nu u \,\diff \nu
\\ & \stackrel{\eqref{eq:bp}\wedge\eqref{eq:nguyen-neumann}}{=} - \rmint_{\Omega_0} \left\langle \nabla_x \Bigg(\frac{\partial_t\Phi_0}{\Phi_0} \Bigg), \nabla u \right\rangle \,\diff\nu -\frac{1}{\beta} \rmint_{\Sigma_0} \Bigg( \frac{\partial_t\Phi_0}{\Phi_0} - \rmint_{\Omega_0} \frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu  \Bigg) \psi\,\diff\nu
\\ & = - \rmint_{\Omega_0} \left\langle \nabla_x \Bigg(\frac{\partial_t\Phi_0}{\Phi_0} \Bigg), \nabla u \right\rangle \,\diff\nu -\frac{1}{\beta} \rmint_{\Sigma_0}\frac{\partial_t\Phi_0}{\Phi_0} \cdot\psi\,\diff\nu + \frac{1}{\beta} \Bigg( \rmint_{\Omega_0} \frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu \Bigg) \Bigg(\rmint_{\Sigma_0}\psi\,\diff\nu\Bigg).
\end{split}
\end{equation}
Similarly, using again the equation \eqref{eq:nguyen-eq} and the Bochner--Reilly formula \eqref{eq:bochner}, we get
\begin{equation}
\begin{split}
\mathrm{Var}_{\nu} &\Bigg( \frac{\partial_t\Phi_0}{\Phi_0} \Bigg) \stackrel{\eqref{eq:nguyen-eq}}{=} \mathrm{Var}_{\nu} \big( \ms{L}_\nu u \big)  = \rmint_{\Omega_0} \big(\ms{L}_\nu u\big)^2\,\diff\nu - \Bigg( \rmint_{\Omega_0} \ms{L}_\nu u \,\diff\nu \Bigg)^2  
\\ & \stackrel{\eqref{eq:nguyen-eq}}{=}\rmint_{\Omega_0} \big(\ms{L}_\nu u\big)^2\,\diff\nu - \frac{1}{\beta^2} \Bigg(\rmint_{\Sigma_0} \psi\,\diff\nu\Bigg)^2
\\ & \stackrel{\eqref{eq:nguyen-neumann}\wedge\eqref{eq:bochner}}{=} \rmint_{\Omega_0} \|\nabla^2u\|_{\mr{HS}}^2 +  \langle \nabla^2W\nabla u, \nabla u \rangle\!-\! \beta\left\langle\frac{ \nabla^2_x\Phi_0}{\Phi_0} \nabla u,\nabla u\right\rangle + \beta \frac{\langle \nabla_x\Phi_0,\nabla u\rangle^2}{\Phi_0^2}\,\diff\nu
\\ & +\rmint_{\Sigma_0} \frac{1}{\beta^2} \msf{H}_{\Sigma_0,\nu}\cdot \psi^2 + \langle \mr{I\!I}_{\Sigma_0}\nabla_{\Sigma_0}u,\nabla_{\Sigma_0}u\rangle +\frac{2}{\beta}\langle \nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}u\rangle \,\diff\nu- \frac{1}{\beta^2} \Bigg(\rmint_{\Sigma_0} \psi\,\diff\nu\Bigg)^2.
\end{split}
\end{equation}
Therefore, combining the above, we get 
\begin{equation} \label{eq:need-to-replace}
\begin{split}
&\mathrm{Var}_{\nu} \Bigg( \frac{\partial_t\Phi_0}{\Phi_0} \Bigg) = - \rmint_{\Omega_0} \|\nabla^2u\|_{\mr{HS}}^2 +  \langle \nabla^2W\nabla u, \nabla u \rangle\!-\! \beta\left\langle\frac{ \nabla^2_x\Phi_0}{\Phi_0} \nabla u,\nabla u\right\rangle + \beta \underbrace{\frac{\langle \nabla_x\Phi_0,\nabla u\rangle^2}{\Phi_0^2}}_{\raisebox{.5pt}{\textcircled{\raisebox{-.9pt} {I}}} }\,\diff\nu
\\ & -2 \rmint_{\Omega_0} \left\langle \nabla_x \Bigg(\frac{\partial_t\Phi_0}{\Phi_0} \Bigg), \nabla u \right\rangle \,\diff\nu -\frac{2}{\beta} \rmint_{\Sigma_0}\frac{\partial_t\Phi_0}{\Phi_0} \cdot\psi\,\diff\nu + \frac{2}{\beta} \Bigg( \rmint_{\Omega_0} \frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu \Bigg) \Bigg(\rmint_{\Sigma_0}\psi\,\diff\nu\Bigg)
\\ & - \rmint_{\Sigma_0} \frac{1}{\beta^2} \msf{H}_{\Sigma_0,\nu}\cdot\psi^2 + \langle \mr{I\!I}_{\Sigma_0}\nabla_{\Sigma_0}u,\nabla_{\Sigma_0}u\rangle +\frac{2}{\beta}\langle \nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}u\rangle \,\diff\nu+ \frac{1}{\beta^2} \Bigg(\rmint_{\Sigma_0} \psi\,\diff\nu\Bigg)^2.
\end{split}
\end{equation}
We shall now use equations \eqref{eq:nguyen-eq} and \eqref{eq:nguyen-neumann} to rewrite the integral of the term $\raisebox{.5pt}{\textcircled{\raisebox{-.9pt} {I}}}$. Indeed, notice that by the definitions of $\ms{L}_\mu$, $\ms{L}_{\nu}$ and  \eqref{eq:nguyen-eq}, we have
\begin{equation} \label{eq:I}
\begin{split}
\beta^2\rmint_{\Omega_0}\raisebox{.5pt}{\textcircled{\raisebox{-.9pt} {I}}}&\,\diff\nu  = \beta^2 \rmint_{\Omega_0} \frac{\langle \nabla_x\Phi_0,\nabla u\rangle^2}{\Phi_0^2}\,\diff\nu = \rmint_{\Omega_0} \big(\ms{L}_{\nu} u- \ms{L}_\mu u\big)^2\,\diff\nu 
\\ &= \rmint_{\Omega_0} \big(\ms{L}_\mu u\big)^2 +2 \ms{L}_\nu u\cdot (\ms{L}_\nu u -\ms{L}_\mu u )\,\diff\nu - \rmint_{\Omega_0} \big( \ms{L}_\nu u\big)^2\,\diff\nu
\\ & \stackrel{\eqref{eq:nguyen-eq}}{=} \rmint_{\Omega_0} \big(\ms{L}_\mu u\big)^2 + 2\beta\ms{L}_{\nu} u \cdot  \left\langle \frac{\nabla_x\Phi_0}{\Phi_0}, \nabla u\right\rangle \,\diff\nu - \mathrm{Var}_{\nu} \Bigg( \frac{\partial_t\Phi_0}{\Phi_0} \Bigg) - \frac{1}{\beta^2} \Bigg(\rmint_{\Sigma_0} \psi\,\diff\nu\Bigg)^2.
\end{split}
\end{equation}
Therefore, \eqref{eq:need-to-replace} can be rewritten as
\begin{equation*}
\begin{split}
(\beta-1)\mathrm{Var}_{\nu} \Bigg( \frac{\partial_t\Phi_0}{\Phi_0} \Bigg) & = - \beta\rmint_{\Omega_0}\!\! \|\nabla^2u\|_{\mr{HS}}^2 +  \langle \nabla^2W\nabla u, \nabla u \rangle\!-\! \beta\left\langle\frac{ \nabla^2_x\Phi_0}{\Phi_0} \nabla u,\nabla u\right\rangle\,\diff\nu - \!\rmint_{\Omega_0}\!\!\!\big( \ms{L}_\mu u\big)^2\,\diff\nu
\\ & - 2\beta \rmint_{\Omega_0}\underbrace{\left\langle \nabla_x \Bigg(\frac{\partial_t\Phi_0}{\Phi_0} \Bigg), \nabla u \right\rangle}_{\raisebox{.5pt}{\textcircled{\raisebox{-.9pt} {I\!I}}}} + \ms{L}_{\nu} u \cdot  \left\langle \frac{\nabla_x\Phi_0}{\Phi_0}, \nabla u\right\rangle \,\diff\nu  -2 \rmint_{\Sigma_0}\frac{\partial_t\Phi_0}{\Phi_0} \cdot\psi\,\diff\nu
\\ & + 2 \Bigg( \rmint_{\Omega_0} \frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu \Bigg) \Bigg(\rmint_{\Sigma_0}\psi\,\diff\nu\Bigg) + \frac{\beta+1}{\beta^2} \Bigg(\rmint_{\Sigma_0} \psi\,\diff\nu\Bigg)^2
\\ & - \rmint_{\Sigma_0} \frac{1}{\beta} \msf{H}_{\Sigma_0,\nu}\cdot \psi^2 + \beta \langle \mr{I\!I}_{\Sigma_0}\nabla_{\Sigma_0}u,\nabla_{\Sigma_0}u\rangle +2\langle \nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}u\rangle \,\diff\nu.
\end{split}
\end{equation*}
For term $\raisebox{.5pt}{\textcircled{\raisebox{-.9pt} {I\!I}}}$,  employing again \eqref{eq:nguyen-eq}, we can write
    \begin{alignat*}{2}
\beta\rmint_{\Omega_0} \raisebox{.5pt}{\textcircled{\raisebox{-.9pt} {I\!I}}}\,\diff\nu & =\beta \rmint_{\Omega_0} \left\langle \frac{ \nabla_x \partial_t \Phi_0 }{\Phi_0},\nabla u \right\rangle  && - \frac{\partial_t\Phi_0}{\Phi_0} \left\langle \frac{\nabla_x \Phi_0}{\Phi_0}, \nabla u\right\rangle \,\diff\nu
\\ & \stackrel{\eqref{eq:nguyen-eq}}{=} \beta \rmint_{\Omega_0}\left\langle \frac{ \nabla_x \partial_t \Phi_0 }{\Phi_0},\nabla u \right\rangle  && -\ms{L}_{\nu} u\cdot \left\langle \frac{\nabla_x \Phi_0}{\Phi_0}, \nabla u\right\rangle \,\diff\nu 
\\ & &&- \beta \Bigg( \rmint_{\Omega_0}\frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu+\frac{1}{\beta} \rmint_{\Sigma_0} \psi\,\diff\nu \Bigg) \Bigg( \rmint_{\Omega_0}\left\langle \frac{\nabla_x \Phi_0}{\Phi_0}, \nabla u\right\rangle\,\diff\nu \Bigg)
\\ & = \beta \rmint_{\Omega_0}\left\langle \frac{ \nabla_x \partial_t \Phi_0 }{\Phi_0},\nabla u \right\rangle  && -\ms{L}_{\nu} u\cdot \left\langle \frac{\nabla_x \Phi_0}{\Phi_0}, \nabla u\right\rangle \,\diff\nu 
\\ & &&+ \Bigg( \rmint_{\Omega_0}\frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu+\frac{1}{\beta} \rmint_{\Sigma_0} \psi\,\diff\nu \Bigg) \Bigg( \rmint_{\Omega_0} \ms{L}_\mu u \,\diff\nu + \frac{1}{\beta} \rmint_{\Sigma_0} \psi\,\diff\nu \Bigg),
\end{alignat*}
where in the last equality we used again that $\ms{L}_{\nu}u-\ms{L}_\mu u = \beta \left\langle \frac{\nabla_x \Phi_0}{\Phi_0},\nabla u\right\rangle$ and integrated with respect to $\nu$. Putting everything together, we finally derive the variance representation
\begin{equation*}
\begin{split}
(\beta-1)\mathrm{Var}_{\nu}& \Bigg( \frac{\partial_t\Phi_0}{\Phi_0} \Bigg)  = - \beta\rmint_{\Omega_0}\!\! \|\nabla^2u\|_{\mr{HS}}^2 +  \langle \nabla^2W\nabla u, \nabla u \rangle\!-\! \beta\left\langle\frac{ \nabla^2_x\Phi_0}{\Phi_0} \nabla u,\nabla u\right\rangle+2\left\langle \frac{ \nabla_x \partial_t \Phi_0 }{\Phi_0},\nabla u \right\rangle\,\diff\nu 
\\ &- \rmint_{\Omega_0}\big( \ms{L}_\mu u\big)^2\,\diff\nu - 2  \Bigg( \rmint_{\Omega_0}\frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu+\frac{1}{\beta} \rmint_{\Sigma_0} \psi\,\diff\nu \Bigg) \Bigg( \rmint_{\Omega_0} \ms{L}_\mu u \,\diff\nu + \frac{1}{\beta} \rmint_{\Sigma_0} \psi\,\diff\nu \Bigg)
\\ & - 2 \rmint_{\Sigma_0}\frac{\partial_t\Phi_0}{\Phi_0} \cdot\psi\,\diff\nu + 2 \Bigg( \rmint_{\Omega_0} \frac{\partial_t\Phi_0}{\Phi_0}\,\diff\nu \Bigg) \Bigg(\rmint_{\Sigma_0}\psi\,\diff\nu\Bigg) + \frac{\beta+1}{\beta^2} \Bigg(\rmint_{\Sigma_0} \psi\,\diff\nu\Bigg)^2
\\ & - \rmint_{\Sigma_0} \frac{1}{\beta} \msf{H}_{\Sigma_0,\nu}\cdot \psi^2 + \beta \langle \mr{I\!I}_{\Sigma_0}\nabla_{\Sigma_0}u,\nabla_{\Sigma_0}u\rangle +2\langle \nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}u\rangle \,\diff\nu.
\end{split}
\end{equation*}
Finally, substituting this formula for the variance into \eqref{eq:second-derivative} and simplifying, we conclude that 
\begin{equation}
\begin{split}
 \frac{1}{\gamma} & \frac{\varphi''(0)}{\varphi(0)}
 = \beta \rmint_{\Omega_0} \frac{\partial_{tt}\Phi_0}{\Phi_0} - 2\beta\left\langle \frac{\nabla_x\partial_t\Phi_0}{\Phi_0}, \nabla u \right\rangle + \beta^2\left\langle\frac{ \nabla^2_x\Phi_0}{\Phi_0} \nabla u,\nabla u\right\rangle \,\diff\nu
\\ & -\beta^2\rmint_{\Omega_0} \|\nabla^2u\|_{\mr{HS}}^2 +  \langle \nabla^2W\nabla u, \nabla u \rangle\,\diff\nu 
\\ & - \beta \rmint_{\Omega_0} \big(\ms{L}_\mu u\big)^2\,\diff\nu - \beta(1-\beta\gamma) \Bigg(\rmint_{\Omega_0} \frac{\partial_t \Phi_0}{\Phi_0} \,\diff\nu\Bigg)^2-\Big(\frac{1}{\beta}-\gamma\Big) \Bigg(\rmint_{\Sigma_0} \psi \,\diff\nu\Bigg)^2
\\ & - 2 \beta \Bigg(\rmint_{\Omega_0} \ms{L}_\mu u\,\diff\nu\Bigg) \Bigg( \rmint_{\Omega_0} \frac{\partial_t \Phi_0}{\Phi_0}\,\diff\nu\Bigg) - 2 \Bigg(\rmint_{\Omega_0} \ms{L}_\mu u\,\diff\nu\Bigg) \Bigg(\rmint_{\Sigma_0} \psi \,\diff\nu\Bigg)
\\ & -2\beta\Big(\frac{1}{\beta}-\gamma\Big)  \Bigg( \rmint_{\Omega_0} \frac{\partial_t \Phi_0}{\Phi_0}\,\diff\nu\Bigg)\Bigg(\rmint_{\Sigma_0} \psi \,\diff\nu\Bigg) - \beta\rmint_{\Sigma_0} \frac{\partial_t\Phi_0}{\Phi_0} \cdot \psi\,\diff\nu + \rmint_{\Sigma_0} \frac{\partial}{\partial t}\bigg|_{t=0}\psi_t \,\diff\nu
\\ & - \rmint_{\Sigma_0} \beta^2 \langle \mr{I\!I}_{\Sigma_0}\nabla_{\Sigma_0} u,\nabla_{\Sigma_0} u\rangle +\langle \mr{I\!I}_{\Sigma_0}^{-1}\nabla_{\Sigma_0}\psi,\nabla_{\Sigma_0}\psi\rangle + 2\beta \langle \nabla_{\Sigma_0}\psi, \nabla_{\Sigma_0}u\rangle \,\diff\nu.
\end{split}
\end{equation}
The proof of Proposition \ref{prop:nguyen} is now complete if one observes that
\begin{equation*}
  \langle\nabla^2_{(t,x)}\Phi(0,x) X(x),X(x)\rangle=\partial_{tt}\Phi_0(x) - 2\beta\left\langle \nabla_x\partial_t\Phi_0(x), \nabla u(x) \right\rangle + \beta^2\left\langle\nabla^2_x\Phi_0(x)\nabla u(x),\nabla u(x)\right\rangle
\end{equation*}
for the vector field $X(x)=(1,-\beta\nabla u(x))$ on $\Omega_0$.
\end{proof}

