\section{Proof of Theorem \ref{thm:poincare}} \label{sec:poincare}

We will follow a simple approximation argument due to \cite{Ngu14b} to\mbox{ derive Theorem \ref{thm:poincare} from Theorem \ref{thm:bbl}.}

\begin{proof} [Proof of Theorem \ref{thm:poincare}]
By suitable approximation, we shall assume that $C$ is a bounded open convex set and that both $f$ and $\Phi$ are $C^2$ smooth and symmetric in a neighborhood of $\overline{C}$, with $\Phi$ and $-\nabla^2\Phi$ moreover being strictly positive. If $\e>0$, consider the function $\Phi_\e:\R\times C\to\R$ given by
\begin{equation}
\forall \ (t,x)\in\R\times C,\qquad \Phi_\e(t,x) \eqdef \Phi(x) + t g(x) - \frac{t^2}{2} \big\langle \big( -\nabla^2 \Phi(x)\big)^{-1} \nabla g(x), \nabla g(x)\big\rangle - \frac{\e}{2}\big( |x|^2+t^2\big).
\end{equation}
It is clear from its definition and the strict positivity of $\Phi$ and $-\nabla^2\Phi$ that for small enough $\e>0$ and $\eta>0$, the restriction $\Phi_\e|_{(-\eta,\eta)\times C}$ is also strictly positive. Moreover, the Hessian of $\Phi_\e$ satisfies
\begin{equation}
\nabla^2\Phi_\e(0,x) = \begin{pmatrix} - \langle ( -\nabla^2 \Phi(x))^{-1} \nabla g(x), \nabla g(x)\rangle  & \nabla g(x)^* \\ \nabla g(x) & \nabla^2\Phi(x)  \end{pmatrix} - \e \msf{Id}.
\end{equation}
Therefore for $(u_0,\bar{u})\in\R^{n+1}$,
\begin{equation*}
\begin{split}
\big\langle \nabla^2\Phi_\e&(0,x) (u_0,\bar{u}), (u_0,\bar{u})\big\rangle
\\ & = -\big\langle \big( -\nabla^2 \Phi(x)\big)^{-1} u_0 \nabla g(x), u_0 \nabla g(x)\big\rangle + 2 \langle u_0\nabla g(x), \bar{u}\rangle - \big\langle \big(-\nabla^2\Phi(x) \big) \bar{u},\bar{u}\big\rangle - \e\big(u_0^2+|\bar{u}|^2\big) 
\\ & \leq - \e\big(u_0^2+|\bar{u}|^2\big)
\end{split}
\end{equation*}
by the Cauchy--Schwarz inequality $\langle Ma,a\rangle + \langle M^{-1}b,b\rangle \geq 2 \langle a,b\rangle$ which holds for an arbitrary positive definite matrix $M$ and vectors $a,b$. Thus, again by continuity, for sufficiently small $\e>0$ and $\eta>0$, $\Phi_\e|_{(-\eta,\eta)\times C}$ is also concave. Since for each $t$, $\Phi_\e(t,\cdot)$ is clearly even, we can invoke Theorem \ref{thm:bbl} to conclude that the function $\varphi_\e:(-\eta,\eta)\to \R_+$ given by
\begin{equation}
 \varphi_\e(t) \eqdef \Bigg( \rmint_{C} \Phi_\e(t,x)^\beta\,\diff\mu(x)\Bigg)^{\frac{1}{\beta+n}}
\end{equation}
is concave on $(-\eta, \eta)$. In particular, using \eqref{eq:second-derivative}, we derive
\begin{equation*}
\frac{\beta+n}{\beta} \frac{\varphi_\e''(0)}{\varphi_\e(0)} = \rmint_C \frac{\partial_{tt}\Phi_\e(0,\cdot)}{\Phi_\e(0,\cdot)}\,\diff\sigma_\e + (\beta-1)\mathrm{Var}_{\sigma_\e} \Bigg( \frac{\partial_t\Phi_\e(0,\cdot)}{\Phi_\e(0,\cdot)} \Bigg) -\frac{n}{\beta+n} \Bigg(\rmint_C\frac{\partial_t \Phi_\e(0,\cdot)}{\Phi_\e(0,\cdot)} \,\diff\sigma_\e\Bigg)^2 \leq 0,
\end{equation*}
where $\diff\sigma_\e(x)$ is the probability measure with density proportional to $\Phi_\e(0,x)^\beta = \big(\Phi(x)-\frac{\e}{2}|x|^2 \big)^\beta$ with respect to $\diff\mu(x)$. Plugging the formula for $\Phi_\e(0,x)$, along with $\partial_t \Phi_\e(0,x) = g(x)$ and
\begin{equation}
\partial_{tt}\Phi_\e(0,x) = -\big\langle \big( -\nabla^2 \Phi(x)\big)^{-1} \nabla g(x), \nabla g(x)\big\rangle - \e
\end{equation}
and letting $\e\searrow0$ (so that also $\sigma_\e \to\nu_\beta$ weakly), we recover
\begin{equation}
(\beta-1)\mathrm{Var}_{\nu_\beta}\Big( \frac{g}{\Phi}\Big) \leq \rmint_C \frac{\langle (-\nabla^2\Phi)^{-1} \nabla g, \nabla g\rangle }{\Phi} \,\diff\nu_\beta + \frac{n}{\beta+n} \Bigg( \rmint_C \frac{g}{\Phi} \,\diff\nu_\beta\Bigg)^2.
\end{equation}
This coincides with the desired inequality \eqref{eq:new-poin} as $g=f\Phi$.
\end{proof}

