\section{Further remarks and open problems} \label{sec:last}

%-------------------------------------------------------------------------------------------------------------------

\subsection{Hereditary convexity}
The proof of Theorems \ref{thm:bbl} and \ref{cor:prekopa} relied on the functional inequality \eqref{eq:x2} that was proven for rotationally invariant measures in Proposition \ref{prop:x2}. It is clear from our proofs that the validity of such a functional inequality for general even log-concave measures would affirmatively resolve both the B-conjecture and the dimensional Brunn--Minkowski conjecture.  We therefore ask the following natural question.

\begin{question} \label{q:ce}
Let $\mu$ be an even log-concave measure supported on $\R^n$ with $C^2$ smooth density. Is $\mu$ hereditarily convex?
\end{question}

%-------------------------------------------------------------------------------------------------------------------

\subsection{From sets to functions} In \cite{CR20}, it was shown that the B-inequality
\begin{equation}
\forall \ a,b\in\R_+ \mbox{ and } \lambda\in(0,1),\qquad \mu\big(a^\lambda b^{1-\lambda}K\big) \geq\mu(aK)^\lambda \mu(bK)^{1-\lambda},
\end{equation}
where $K,L$ are symmetric convex sets, holds for all even log-concave measures on $\R^n$ for any $n\in\N$ if and only if the functional version of the inequality holds on any $\R^n$, namely if
\begin{equation} \label{eq:def-a-again}
\alpha(t) \eqdef \rmint_{\R^n} e^{-V(e^tx)-W(x)}\,\diff x
\end{equation}
is log-concave on $\R$ for all even convex functions $V,W:\R^n\to\R\cup\{\infty\}$. One could wonder whether a similar transference principle from geometric to functional inequalities also holds in the context of the dimensional Brunn--Minkowski inequality, thus showing that Theorem \ref{thm:bbl} is a formal consequence of the results of \cite{EM21,CR23}. While the multiplicative nature of the B-inequality appears to be what made the result of \cite{CR20} possible,  one can in fact recover concavity principles in the spirit of Theorem \ref{thm:bbl} from geometric inequalities for sets at least for \emph{integer} powers $\beta>0$.

\begin{theorem} \label{thm:transference}
Fix $n\in\N$ and an even log-concave measure $\mu$ on $\R^n$ such that for all $k\in\N$,
\begin{equation} \label{eq:assum-transference}
\forall \ \lambda\in(0,1),\qquad (\mu\otimes m^k)\big(\lambda K+(1-\lambda)L\big)^{\kappa_{n,k}} \geq \lambda(\mu\otimes m^k)(K)^{\kappa_{n,k}}+(1-\lambda)(\mu\otimes m^k)(L)^{\kappa_{n,k}}
\end{equation}
for some $\kappa_{n,k}>0$ and all symmetric convex sets $K, L$ in $\R^{n+k}$, where $m^k$ is the Lebesgue measure on $\R^k$. Moreover, let $\Omega\subseteq \R^{n+1}$ be a convex set such that for each $t\in\R$, the corresponding section $\Omega_t=\{x\in\R^n: \ (t,x)\in\Omega\}$ is symmetric, and $\Phi:\Omega\to\R_+$ a concave function such that for each $t$, the function $\Phi(t,\cdot)$ is even on $\Omega_t$.  Then, for every integer $\beta\in\N$, the function
\begin{equation}
 \varphi(t) \eqdef \Bigg( \rmint_{\Omega_t} \Phi(t,x)^\beta\,\diff\mu(x)\Bigg)^{\kappa_{n,\beta}}
\end{equation}
is concave on its support, provided that the integral converges.
\end{theorem}

\begin{proof}
Since $\beta\in\N$, there exists a positive constant $c_\beta>0$ such that
\begin{equation}
\Phi(t,x)^\beta = c_\beta m^\beta\big( \Phi(t,x) \msf{B}_2^\beta\big),
\end{equation}
where $\msf{B}_2^\beta$ is the unit Euclidean ball in $\R^\beta$. Therefore, we can write
\begin{equation}
\begin{split}
 \varphi(t) = c_\beta^{\kappa_{n,\beta}} (\mu \otimes m^\beta)\big( \underbrace{\big\{ (x,y)\in\R^{n+k}: \ x\in \Omega_t \mbox{ and } |y| \leq \Phi(t,x)\big\}}_{C(t)}\big)^{\kappa_{n,\beta}},
\end{split}
\end{equation}
where $|y|$ is the Euclidean norm of $y$. The conclusion now follows from \eqref{eq:assum-transference} by observing that, by the concavity of $\Phi$,  the sets $\{C(t)\}_{t\in[0,1]}$ are symmetric convex sets in $\R^{n+\beta}$ which satisfy
\begin{equation}
C\big(\lambda t_1 + (1-\lambda) t_2\big) \supseteq \lambda C(t_1) + (1-\lambda) C(t_2)
\end{equation}
for every $t_1,t_2 \in\R$ and $\lambda\in(0,1)$.
\end{proof}

Combining this result with the general bound of Livshyts \cite{Liv23} for the dimensional Brunn--Minkowski inequality for even log-concave measures, we deduce the following corollary.

\begin{corollary} \label{cor:livshyts}
Let $\mu$ be an even log-concave measure on $\R^n$. Moreover, let $\Omega\subseteq \R^{n+1}$ be a convex set such that for each $t\in\R$, the set $\Omega_t=\{x\in\R^n: \ (t,x)\in\Omega\}$ is symmetric, and $\Phi:\Omega\to\R_+$ a concave function such that for each $t$, the function $\Phi(t,\cdot)$ is even on $\Omega_t$.  Then, for every integer $\beta\in\N$, the function
\begin{equation}
 \varphi(t) \eqdef \Bigg( \rmint_{\Omega_t} \Phi(t,x)^\beta\,\diff\mu(x)\Bigg)^{\kappa_{n+\beta}}
\end{equation}
is concave on its support, where $\{\kappa_r\}_{r\in\N}$ is a sequence satisfying $\kappa_r \asymp r^{-4-o(1)}$ as $r\to\infty$.
\end{corollary}

An inspection of the proof of \cite{Liv23} shows that Livshyts in fact obtains the inequality
\begin{equation} 
\rmint_U \|\nabla^2 u\|_{\mr{HS}}^2 + \langle \nabla^2W \nabla u, \nabla u\rangle \, \diff\mu_t \geq \frac{1}{n^{4+o(1)}} \Bigg( \rmint_U \ms{L}_\mu u \,\diff\mu_t\Bigg)^2 
\end{equation}
for every even log-concave measure $\diff\mu(x)=e^{-W(x)}\,\diff x$ and every even $C^2$ function $u:U\to\R$. Therefore, a close inspection of the proof of Theorem \ref{thm:bbl} shows that the statement of Corollary \ref{cor:livshyts} can be extended from $\beta\in\N$ to arbitrary $\beta>0$.

%-------------------------------------------------------------------------------------------------------------------

\subsection{Weighted torsional rigidity} Inequalities of Brunn--Minkowski-type for functionals other than volume have been thoroughly studied throughout analysis. Prime examples from the works of Brascamp--Lieb and Borell include the Brunn--Minkowski inequality for the first eigenvalue of the Laplace operator \cite{BL76,Bor00}, for Newtonian \cite{Bor83} and logarithmic capacity \cite{Bor84} and for torsional rigidity \cite{Bor85}. For a unified perspective to these inequalities, we refer the reader to \cite{Col05}.

Let $K$ be a convex set in $\R^n$ with nonempty interior.  The \emph{torsional rigidity} $\tau(K)$ is defined by
\begin{equation} \label{eq:tor}
\frac{1}{\tau(K)} \eqdef\inf \Bigg\{ \frac{\rmint_K |\nabla u(x)|^2\,\diff x}{\big(\rmint_K |u(x)|\,\diff x\big)^2}: \ u \mbox{ is smooth and nonconstant in } K \mbox{ with } u\big|_{\partial K}\equiv 0 \Bigg\}.
\end{equation}
In \cite{Bor85}, Borell showed that for any convex sets $K,L$ in $\R^n$ with nonempty interior,
\begin{equation} \label{eq:borelll}
\forall \ \lambda\in(0,1),\qquad \tau\big( \lambda K+(1-\lambda)L\big)^{1/(n+2)} \geq \lambda \tau(K)^{1/(n+2)}+(1-\lambda)\tau(L)^{1/(n+2)}.
\end{equation}
In his argument, he made crucial use of an expression for $\tau(\cdot)$ in terms of the solution of an elliptic boundary-value problem. Namely, if $u:K\to\R$ is the unique solution of
\begin{equation} \label{eq:bvp}
\begin{cases}
\Delta u = -1, \quad \mbox{in } \mr{int}(K) \\
u \equiv 0, \quad \mbox{on } \partial K
\end{cases},
\end{equation}
then
\begin{equation} \label{eq:tor-for}
\tau(K) = \rmint_K |\nabla u(x)|^2\,\diff x \stackrel{\eqref{eq:bvp}}{=}  \rmint_K u(x)\,\diff x,
\end{equation}
where the second equality follows by integration by parts.
In \cite{Bor85}, Borell proved that if $K,L$ are convex sets in $\R^n$ with nonempty interior and $u(\lambda,\cdot):\lambda K+(1-\lambda)L \to\R$ is a solution to the boundary-value problem \eqref{eq:bvp} on $\lambda K+(1-\lambda)L$, then
the function $\sqrt{u(\lambda,x)}$ is concave in the pair of variables $(\lambda, x)$.  Afterwards, inequality \eqref{eq:borelll} becomes an immediate consequence of \eqref{eq:tor-for} and the concavity principle for the marginal \eqref{eq:varphi} with $\beta=2$.  We refer, for instance, to \cite[Section~4]{Sal15} for a comprehensive study of concavity properties of solutions to more general boundary-value problems.

In view of the recent interest in Brunn--Minkowski inequalities for measures of symmetric convex sets, it is worthwhile to investigate such inequalities for weighted analogues of other analytic functionals in the presence of symmetry.  Given an even probability measure $\mu$ on $\R^n$, the $\mu$-weighted torsional rigidity $\tau_\mu(K)$ of a symmetric convex set $K$ is defined by \eqref{eq:tor}, where all $\diff x$ integrals are replaced by $\diff\mu(x)$.  It can also be rephrased in terms of the solution to the boundary value problem
\begin{equation} \label{eq:bvp2}
\begin{cases}
\ms{L}_\mu u = -1, \quad \mbox{in } \mr{int}(K) \\
u \equiv 0, \quad \mbox{on } \partial K
\end{cases}.
\end{equation}
We refer to \cite{Liv24,HL24} for some recent investigations on the functional $\tau_\mu$. In view of the weighted concavity principle of Theorem \ref{thm:bbl}, an affirmative answer to the following question would prove the weighted analogue of \eqref{eq:borelll} for rotationally invariant log-concave weights.

\begin{question}
Fix an even log-concave measure $\mu$ on $\R^n$ and let $K, L$ be symmetric convex sets in $\R^n$.  Let also $u(\lambda,\cdot):\lambda K+(1-\lambda)L \to\R$ be the unique solution to \eqref{eq:bvp2} on $\lambda K+(1-\lambda)L$, where $\lambda\in[0,1]$.  Is the function $\sqrt{u(\lambda,x)}$ a concave function of the pair of variables $(\lambda, x)$?
\end{question}

A related result on the log-concavity of the first eigenfunction and eigenvalue of the Ornstein--Uhlenbeck operator $\ms{L}_{\gamma_n}$ was recently proven by Colesanti, Francini, Livshyts and Salani in \cite{CFLS24}.

%-------------------------------------------------------------------------------------------------------------------

\subsection{Negative exponents} Throughout this paper, we have studied the concavity  of the weighted marginal function \eqref{eq:varphi} for $\beta>0$, where $\Phi:\Omega\to\R$ is a concave function. This corresponds to the study of $\kappa$-concave measures in Borell's hierarchy \cite{Bor75}, where $\kappa\in(0,\tfrac{1}{n})$.  We pose the following question regarding weighted marginals of even $\kappa$-concave measures for $\kappa<0$.

\begin{question} \label{q:convex}
Let $\mu$ be an even log-concave measure on $\R^n$. Moreover, let $\Omega\subseteq \R^{n+1}$ be a convex set such that for each $t\in\R$, the set $\Omega_t=\{x\in\R^n: \ (t,x)\in\Omega\}$ is symmetric, and $\Phi:\Omega\to\R_+$ a convex function such that for each $t$, the function $\Phi(t,\cdot)$ is even on $\Omega_t$.  Is the function given by 
\begin{equation}
 \varphi(t) \eqdef \Bigg( \rmint_{\Omega_t} \Phi(t,x)^{-\beta}\,\diff\mu(x)\Bigg)^{-\frac{1}{\beta-n}}
\end{equation}
convex, for every $\beta>n$?
\end{question}

Similarly to the regime $\beta>0$ discussed in the introduction, when $\mu=\diff x$ is the Lebesgue measure, a positive answer to this question without any symmetry assumptions follows from~\eqref{eq:bbl2} applied to convex functions
(see also \cite{Ngu14a} for a local proof).  We note in passing that we are not aware of any examples of even $\kappa$-concave measures with $\kappa<0$ not satisfying the B-inequality or the dimensional Brunn--Minkowski inequality for symmetric convex sets. On the contrary, in \cite{CR23} it was shown that a broad family of such measures in fact satisfy both these inequalities.

We note also that our proof of Theorem \ref{thm:bbl} heavily used that the measure $\Phi(t,\cdot)^\beta \, \diff\mu$ is more log-concave than $\mu$, via the result of \cite{CR23}, so we expect some new ideas (perhaps in the form of new spectral inequalities) to be needed in order to answer Question \ref{q:convex} affirmatively.

