\section*{Appendix.  Brascamp and Lieb's proof of the Gaussian B-theorem} \label{App}

As proposed in Remark~\ref{rem:B-BL} above, we end this paper by presenting the beautiful argument of Brascamp and Lieb \cite{BL75}, proving the strong version of the Gaussian B-theorem. In its functional form, this asserts that for every $n\times n$ diagonal matrix $D$ and every even convex function $V:\R^n\to\R\cup\{\infty\}$, the function given by
\begin{equation}
\forall \ t\in\R,\qquad \alpha(t) \eqdef \rmint_{\R^n} e^{-V(e^{tD}x) - |x|^2/2}\,\frac{\diff x}{(2\pi)^{n/2}}
\end{equation}
is log-concave on $\R$. Performing a change of variables, this is equivalent to the log-concavity of
\begin{equation}
\forall \ t\in\R,\qquad \beta(t)  \eqdef \rmint_{\R^n} e^{-|e^{-tD}x|^2/2-V(x)} \,\diff x,
\end{equation}
which, in turn, by scaling is equivalent to the local inequality $\beta'(0)^2\geq \beta(0)\beta''(0)$. Direct computation (see, e.g., \cite[pp.~413--414]{CFM04}) shows that this inequality can be written compactly as
\begin{equation} \label{eq:local-b}
\rmint_{\R^n} \langle x, Dx\rangle^2\,\diff\mu(x) - \Bigg( \rmint_{\R^n} \langle x,Dx\rangle\,\diff\mu(x)\Bigg)^2 \leq 2\rmint_{\R^n} \langle x,D^2x\rangle\,\diff\mu(x),
\end{equation}
where $\diff\mu(x)$ is the even probability measure with density \mbox{proportional to $e^{-V(x)}$ with respect to $\gamma_n$.}

\begin{proof} [Brascamp and Lieb's proof of \eqref{eq:local-b}]
Starting from the left-hand side, if $q(x) = \langle x,Dx\rangle$,
\begin{equation}
\mathrm{Var}_\mu( q) = \frac{1}{2Z^2} \rmint_{\R^n\times\R^n} \big( \langle x,Dx\rangle - \langle y,Dy\rangle \big)^2\ e^{-V(x)-V(y)} \,\diff\gamma_{2n}(x,y),
\end{equation}
where $Z=\rmint_{\R^n} e^{-V}\,\diff\gamma_n$ is a normalizing constant. The orthogonal transformation
\begin{equation} \label{eq:rotate}
(x,y) = \Big(\frac{u+v}{\sqrt{2}},\frac{u-v}{\sqrt{2}}\Big)
\end{equation}
preserves the $2n$-dimensional Gaussian measure, and thus we can rewrite the variance as
\begin{equation} \label{eq:apply-rot}
\begin{split}
\mathrm{Var}_\mu(q) & = \frac{2}{Z^2} \rmint_{\R^n\times\R^n}  \langle u,Dv\rangle^2 \ e^{-V(\frac{u+v}{\sqrt{2}})-V(\frac{u-v}{\sqrt{2}})} \,\diff\gamma_{2n}(u,v) 
\\ & = \frac{2}{Z^2} \rmint_{\R^n}\Bigg( \rmint_{\R^n}  \langle u,Dv\rangle^2 \, \diff \nu_v(u) \Bigg) Z(v) \,\diff\gamma_n(v),
\end{split}
\end{equation}
where $\diff\nu_v(u)$ is the probability measure on $\R^n$ with density proportional to $\exp(-V(\frac{u+v}{\sqrt{2}})-V(\frac{u-v}{\sqrt{2}}))$ with respect to $\diff\gamma_{n}(u)$ and $Z(v) = \rmint_{\R^n}\exp(-V(\frac{u+v}{\sqrt{2}})-V(\frac{u-v}{\sqrt{2}}))\,\diff\gamma_n(u)$ is a normalizing constant. Clearly every $\nu_v$ is an even measure on $\R^n$ and moreover, direct computation of the Hessian of the potential shows that $\nu_v$ is log-concave with respect to $\gamma_{n}$. Therefore, applying the Brascamp--Lieb inequality \eqref{eq:bl-var} to the odd function $\ell_v(u) = \langle u,Dv\rangle$, for every $v\in\R^n$, we have the inequality
\begin{equation}
\rmint_{\R^n}  \langle u,Dv\rangle^2 \, \diff \nu_v(u) = \mathrm{Var}_{\nu_v}(\ell_v) \leq \rmint_{\R^n} |\nabla \ell_v|^2 \,\diff\nu_v = |Dv|^2.
\end{equation}
Plugging this bound back into \eqref{eq:apply-rot} and using the definition of $Z(v)$, we finally get
\begin{equation} \label{eq:used-BL}
\begin{split}
\mathrm{Var}_\mu(q) & \leq \frac{2}{Z^2} \rmint_{\R^n\times\R^n}  |Dv|^2 \ e^{-V(\frac{u+v}{\sqrt{2}})-V(\frac{u-v}{\sqrt{2}})} \,\diff\gamma_{2n}(u,v)
\\ & =  \frac{2}{Z^2} \rmint_{\R^n\times\R^n}  \langle v,D^2v\rangle \ e^{-V(\frac{u+v}{\sqrt{2}})-V(\frac{u-v}{\sqrt{2}})} \,\diff\gamma_{2n}(u,v).
\end{split}
\end{equation}
Applying again the change of variables \eqref{eq:rotate} for which $v=\frac{x-y}{\sqrt{2}}$, we can rewrite \eqref{eq:used-BL} as
\begin{equation}
\begin{split}
\mathrm{Var}_\mu(q) & \leq \frac{2}{Z^2} \rmint_{\R^n\times\R^n} \frac{1}{2} \big( \langle x,D^2x\rangle + \langle y, D^2y\rangle - \langle x, D^2y\rangle-\langle y,D^2 x\rangle \big)\ e^{-V(x)-V(y)} \,\diff\gamma_{2n}(x,y)
\\ & = 2\rmint_{\R^n} \langle x,D^2x\rangle\,\diff\mu(x),
\end{split}
\end{equation}
where in the last equality we used that $\rmint_{\R^n} \langle x,D^2y\rangle \, \diff\mu(y) = 0$ for every $x\in\R^n$.
\end{proof}

