	\centering
	\caption{Résultats de la requête SPARQL : Extraction des compétences et niveaux pour différents individus}
	\label{tab:competences_individus}
	\begin{tabular}{|c|c|c|}
		\hline
		\textbf{Individu} & \textbf{Compétence} & \textbf{Niveau} \\ 
		\hline
		Louis Le  & Python 01               & Basique       \\ 
		\hline
