\noindent\textbf{Transmitter Antenna Gain Model:} Based on the 3GPP TR 37.840 5G specifications, the overall transmitter antenna gain can be modeled as 
\begin{equation}\label{antenna_gain}
    G_{5 \mathrm{G}}\left(\theta, \phi\right)=A_E\left(\theta, \phi\right)+A_V\left(\theta, \phi\right),
\end{equation}
where $A_E\left(\theta, \phi\right)$ and $A_V\left(\theta, \phi\right)$ are the antenna element gain and array gain in dBi unit, respectively. The directional pattern of antenna elements $A_E(\theta,\phi)$ are represented as follows:
\begin{equation}
A_E(\theta,\phi) = G_{E,\text{max}} - \min\{-[A_{E,V}(\theta) + A_{E,H}(\phi)], A_m\}.
\end{equation}
Here, 
\begin{equation}
A_{E,V}(\theta) = -\min\left\{12\left(\frac{\theta - 90^\circ}{\theta_{3\text{dB}}}\right)^2, SL_{A,V}\right\},
\end{equation}
and
\begin{equation}
A_{E,H}(\phi) = -\min\left\{12\left(\frac{\phi}{\phi_{3\text{dB}}}\right)^2, A_m\right\}.
\end{equation}
Moreover, the array beam forming directional pattern gain $A_V(\theta,\phi)$ can be modeled as
\begin{equation}
A_V\left(\theta, \phi\right)=10 \log _{10}\left(\left|\mathbf{V}^H\left(\theta, \phi\right) \mathbf{W}\left(\phi_{\text {scan }}\right)\right|^2\right),
\end{equation}
where $\mathbf{V}^H\left(\theta, \phi\right)$ and $\mathbf{W}\left(\phi_{\text {scan }, i}\right)$ are $N_H \times N_V$-long steering and beamforming vectors, respectively, and $\phi_{\text {scan }}$ is the scanning angle. The ($m,n$)-th elements of $\mathbf{V}^H\left(\theta, \phi\right)$ and $\mathbf{W}\left(\phi_{\text {scan }}\right)$ are expressed as
% \begin{multline}
% \mathbf{V}^H_{m,n} = \exp\Big[j\frac{2\pi}{\lambda}\left((m-1)d_H\sin(\theta)\sin(\phi) + (n-1)\\ d_V\cos(\theta)\right)\Big]
% \end{multline}
%%
% \begin{align}
% \mathbf{V}^H_{m,n} &= \exp\Big[j \frac{2\pi}{\lambda} \left( (m-1)d_H \sin(\theta)\sin(\phi) \right. \nonumber \\
% &\quad \left. + (n-1)d_V \cos(\theta) \right)\Big],
% \end{align}
\begin{equation}
\mathbf{V}^H_{m,n} = \exp\left[\frac{2\pi j}{\lambda} \left((m{-}1)d_H \sin\theta \sin\phi + (n{-}1)d_V \cos\theta\right)\right],
\end{equation}

and
\begin{multline}
\mathbf{W}^H_{m,n} = \frac{1}{\sqrt{N_H N_V}} \exp\Bigg[-j\frac{2\pi}{\lambda}\Big( (m-1)d_H\sin(\phi_{\text{SCAN}})\\ \cos(\theta_{\text{TILT}}) - (n-1)d_V\sin(\theta_{\text{TILT}}) \Big)\Bigg],
\end{multline}
respectively. Here, $N_H$ and $N_V$ denote the number of horizontal and vertical antenna elements, respectively. Furthermore, $d_H$ and $d_V$ represent the horizontal and vertical antenna element spacing, respectively, and $\lambda$ denotes the wavelength. The horizontal beam steering scan angle is represented by $\phi_{\text{SCAN}}$, and $\theta_{\text{TILT}}$ denotes the downtilt beam steering tilt angle. These parameters collectively determine the beam forming characteristics of the antenna array in our UAV communication system.

