\section{Proof of Proposition~\ref{prop:update}}
\label{app:update}

The proof is delivered in three parts. First, we derive the form of the thresholding function. Second, we derive the gradient for $\beta_k$. Third, we derive the gradient for $\gamma_k$.

\paragraph{Thresholding Function}

Observe that \eqref{eq:bdlemma}, the upper bound on the negative log-likelihood, treated as a function of block $k$, satisfies
\begin{equation*}
\begin{split}
\bar{l}_{\bar{L}_k}(\boldsymbol{\beta},\boldsymbol{\gamma};\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})&=l(\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})+\nabla l(\tilde{\beta}_k)^\top(\beta_k-\tilde{\beta}_k)+\nabla l(\tilde{\gamma}_k)^\top(\gamma_k-\tilde{\gamma}_k) \\
&\hspace{2.5in}+\frac{\bar{L}_k}{2}\left\{(\beta_k-\tilde{\beta}_k)^2+(\gamma_k-\tilde{\gamma}_k)^2\right\} \\
&=\frac{\bar{L}_k}{2}\biggl\{\beta_k-\underbrace{\left(\tilde{\beta}_k-\frac{1}{\bar{L}_k}\nabla l(\tilde{\beta}_k)\right)}_{\hat{\beta}_k}\biggr\}^2+\frac{\bar{L}_k}{2}\biggl\{\gamma_k-\underbrace{\left(\tilde{\gamma}_k-\frac{1}{\bar{L}_k}\nabla l(\tilde{\gamma}_k)\right)}_{\hat{\gamma}_k}\biggr\}^2+\mathrm{const.} \\
&=\frac{\bar{L}_k}{2}(\beta_k-\hat{\beta}_k)^2+\frac{\bar{L}_k}{2}(\gamma_k-\hat{\gamma}_k)^2+\mathrm{const.},
\end{split}
\end{equation*}
where $\mathrm{const.}$ represents terms independent of $\beta_k$ and $\gamma_k$. It immediately follows that \eqref{eq:obj}, the upper bound on the objective function, satisfies
\begin{equation*}
\bar{f}_{\bar{L}_k}(\boldsymbol{\beta},\boldsymbol{\gamma};\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})=\frac{\bar{L}_k}{2}(\beta_k-\hat{\beta}_k)^2+\frac{\bar{L}_k}{2}(\gamma_k-\hat{\gamma}_k)^2+\lambda\alpha1\{\beta_k\neq0\}+\lambda(1-\alpha)1\{\gamma_k\neq0\}+\mathrm{const.}
\end{equation*}
Hence, to minimize \eqref{eq:obj} as a function of block $k$, we need only minimize the right-hand side of the above function:
\begin{equation*}
\min_{\substack{\beta\in\mathbb{R},\gamma\in\mathbb{R}_+ \\ \beta=0\Rightarrow\gamma=0}}\;\frac{\bar{L}}{2}(\beta-\hat{\beta})^2+\frac{\bar{L}}{2}(\gamma-\hat{\gamma})^2+\lambda\alpha1\{\beta\neq0\}+\lambda(1-\alpha)1\{\gamma\neq0\}
\end{equation*}
or equivalently
\begin{equation*}
\min_{\substack{\beta\in\mathbb{R},\gamma\in\mathbb{R} \\ \beta=0\Rightarrow\gamma=0}}\;\frac{\bar{L}}{2}(\beta-\hat{\beta})^2+\frac{\bar{L}}{2}(\gamma-\hat{\gamma}_+)^2+\lambda\alpha1\{\beta\neq0\}+\lambda(1-\alpha)1\{\gamma\neq0\},
\end{equation*}
where $\hat{\gamma}_+=\max(\hat{\gamma},0)$ and we drop the subscript $k$ to simplify notation. The hierarchy constraint gives rise to three possible cases for the optimal solutions $\beta^\star$ and $\gamma^\star$:
\begin{enumerate}
\item $\beta^\star=0$ and $\gamma^\star=0$, so the optimal objective value is $f_1^\star=\bar{L}/2\hat{\beta}^2+\bar{L}/2\hat{\gamma}_+^2$;
\item $\beta^\star=\hat{\beta}$ and $\gamma^\star=0$, so the optimal objective value is $f_2^\star=\bar{L}/2\hat{\gamma}_+^2+\lambda\alpha$; and
\item $\beta^\star=\hat{\beta}$ and $\gamma^\star=\hat{\gamma}_+$, so the optimal objective value is $f_3^\star=\lambda$.
\end{enumerate}
It is straightforward to check that
\begin{enumerate}
\item $f_1^\star$ is less than $f_2^\star$ and $f_3^\star$ if $\hat{\beta}^2<2\lambda\alpha/\bar{L}$ and $\hat{\beta}^2+\hat{\gamma}_+^2<2\lambda/\bar{L}$;
\item $f_2^\star$ is less than $f_1^\star$ and $f_3^\star$ if $\hat{\beta}^2>2\lambda\alpha/\bar{L}$ and $\hat{\gamma}_+^2<2\lambda(1-\alpha)/\bar{L}$; and
\item $f_3^\star$ is less than $f_1^\star$ and $f_2^\star$ if $\hat{\beta}^2+\hat{\gamma}_+^2>2\lambda/\bar{L}$ and $\hat{\gamma}_+^2>2\lambda(1-\alpha)/\bar{L}$.
\end{enumerate}
Combining these conditions, we have
\begin{equation*}
(\beta^\star,\gamma^\star)=
\begin{dcases}
(0,0)&\text{if }\hat{\beta}^2<\frac{2\lambda\alpha}{\bar{L}}\text{ and }\hat{\beta}^2+\hat{\gamma}_+^2<\frac{2\lambda}{\bar{L}} \\
(\hat{\beta},0)&\text{if }\hat{\gamma}_+^2<\frac{2\lambda(1-\alpha)}{\bar{L}} \\
(\hat{\beta},\hat{\gamma}_+)&\text{otherwise}.
\end{dcases}
\end{equation*}

\paragraph{Gradient for $\beta_k$}

Consider the gradient of $l$ with respect to $\beta_k$. Since $\mathbf{V}_i(\boldsymbol{\gamma})$ does not depend on $\beta_k$, we have
\begin{equation*}
\nabla_{\beta_k}l(\boldsymbol{\beta},\boldsymbol{\gamma})=n\nabla_{\beta_k}\log\{S(\boldsymbol{\beta},\boldsymbol{\gamma})\},
\end{equation*}
where
\begin{equation*}
S(\boldsymbol{\beta},\boldsymbol{\gamma})=\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}).
\end{equation*}
The chain rule gives
\begin{equation*}
\nabla_{\beta_k}\log\{S(\boldsymbol{\beta},\boldsymbol{\gamma})\}=\frac{\nabla_{\beta_k}S(\boldsymbol{\beta},\boldsymbol{\gamma})}{S(\boldsymbol{\beta},\boldsymbol{\gamma})},
\end{equation*}
with the gradient on the right-hand side being
\begin{equation*}
\nabla_{\beta_k}S(\boldsymbol{\beta},\boldsymbol{\gamma})=-2\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}).
\end{equation*}
The gradient claimed by the proposition immediately follows as
\begin{equation*}
\nabla_{\beta_k}l(\boldsymbol{\beta},\boldsymbol{\gamma})=-2n\frac{\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})}{\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})}.
\end{equation*}

\paragraph{Gradient for $\gamma_k$}

Consider now the gradient of $l$ with respect to $\gamma_k$. It holds
\begin{equation}
\label{eq:gammaderiv}
\nabla_{\gamma_k}l(\boldsymbol{\beta},\boldsymbol{\gamma})=\sum_{i=1}^m\nabla_{\gamma_k}\log\det\{\mathbf{V}_i(\boldsymbol{\gamma})\}+n\nabla_{\gamma_k}\log\{S(\boldsymbol{\beta},\boldsymbol{\gamma})\}.
\end{equation}
Using the standard matrix calculus result that $\nabla\log\det\{\mathbf{A}(x)\}=\operatorname{tr}\{\mathbf{A}^{-1}(x)\nabla\mathbf{A}(x)\}$, the first term on the right-hand side of \eqref{eq:gammaderiv} evaluates to
\begin{equation}
\label{eq:gammaderiv1}
\nabla_{\gamma_k}\log\det\{\mathbf{V}_i(\boldsymbol{\gamma})\}=\operatorname{tr}\left(\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}\mathbf{x}_{ik}^\top\right)=\operatorname{tr}\left(\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}\right)=\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik},
\end{equation}
which follows from the cyclic property of the trace function and the final term being a scalar. For the second term on the right-hand side of \eqref{eq:gammaderiv}, we have
\begin{equation*}
\nabla_{\gamma_k}\log\{S(\boldsymbol{\beta},\boldsymbol{\gamma})\}=\frac{\nabla_{\gamma_k}S(\boldsymbol{\beta},\boldsymbol{\gamma})}{S(\boldsymbol{\beta},\boldsymbol{\gamma})}.
\end{equation*}
Applying the standard matrix calculus results that $\nabla(\mathbf{z}^\top\mathbf{A}^{-1}(x)\mathbf{z})=\mathbf{z}^\top\nabla\mathbf{A}^{-1}(x)\mathbf{z}$ and $\nabla\mathbf{A}^{-1}(x)=-\mathbf{A}^{-1}(x)\nabla\mathbf{A}(x)\mathbf{A}^{-1}(x)$ gives
\begin{equation*}
\begin{split}
\nabla_{\gamma_k} S(\boldsymbol{\beta},\boldsymbol{\gamma})&=-\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\nabla_{\gamma_k}\mathbf{V}_i(\boldsymbol{\gamma})\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}) \\
&=-\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}) \\
&=-\sum_{i=1}^m\left\{\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right\}^2,
\end{split}
\end{equation*}
where the final equality follows from the fact that $\mathbf{z}^\top(\mathbf{u}\mathbf{u}^\top)\mathbf{z}=(\mathbf{u}^\top\mathbf{z})^2$. We now have
\begin{equation}
\label{eq:gammaderiv2}
\nabla_{\gamma_k}\log\{S(\boldsymbol{\beta},\boldsymbol{\gamma})\}=-\frac{\sum_{i=1}^m\left\{\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right\}^2}{\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})}.
\end{equation}
Finally, substituting \eqref{eq:gammaderiv2} and \eqref{eq:gammaderiv1} into \eqref{eq:gammaderiv} yields the claimed gradient as
\begin{equation*}
\nabla_{\gamma_k}l(\boldsymbol{\beta},\boldsymbol{\gamma})=\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}-n\frac{\sum_{i=1}^m\left\{\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right\}^2}{\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})}.
\end{equation*}

\section{Coordinate Descent Heuristics}
\label{app:heuristics}

Our implementation of Algorithm~\ref{alg:cd} adopts three heuristics that accelerate its convergence.

\paragraph{Gradient Screening}

Prior to running coordinate descent, the predictors are designated strong or weak. Strong predictors are those whose gradients are among (say) the 100 largest in magnitude. The remaining predictors are weak predictors. Coordinate descent is then run on the strong set until convergence. At that point, we do one cycle over the weak predictors. If the active set is unchanged, we stop. Otherwise, if any weak predictors become active, they are shifted from the weak set to the strong set, and coordinate descent is run again.

\paragraph{Gradient Sorting}

Before running coordinate descent, the predictors are sorted in descending order according to the magnitude of their gradients. This sorting ensures that predictors with the greatest potential impact are considered first, usually leading to faster convergence.

\paragraph{Active Set Updates}

After several iterations of coordinate descent, the active set usually stabilizes, with subsequent iterations simply polishing the estimates of the nonzero parameters. For this reason, we restrict the coordinate descent updates solely to the active set once it has stabilized (e.g., after three cycles with no changes). After convergence on the active set, one additional cycle through the inactive predictors is performed to confirm overall convergence.

\section{Proof of Theorem~\ref{thrm:converge}}
\label{app:converge}

\subsection{Preliminary Lemmas}

The proof requires two technical lemmas which we state and prove in turn. The first lemma ensures the negative log-likelihood \eqref{eq:ll} is bounded below. The second lemma ensures the gradients \eqref{eq:gradbeta} and \eqref{eq:gradgamma} of the negative log-likelihood are Lipschitz continuous.

\begin{lemma}
\label{lemma:bounded}
Suppose $\mathbf{y}$ does not lie in the column space of $\mathbf{X}$. Then there exists $c\in\mathbb{R}$ such that the negative log-likelihood $l(\boldsymbol{\beta},\boldsymbol{\gamma})$ given in \eqref{eq:ll} satisfies $l(\boldsymbol{\beta},\boldsymbol{\gamma})\geq c$ for all $\boldsymbol{\beta}\in\mathbb{R}^p$ and $\boldsymbol{\gamma}\in\mathbb{R}_+^p$ such that $\|\boldsymbol{\gamma}\|_\infty\leq\bar{\gamma}$.
\end{lemma}
\begin{proof}
Recall that the negative log-likelihood is
\begin{equation}
\label{eq:ll2}
l(\boldsymbol{\beta},\boldsymbol{\gamma})=\sum_{i=1}^m\log\det\{\mathbf{V}_i(\boldsymbol{\gamma})\}+n\log\left\{\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right\},
\end{equation}
where
\begin{equation*}
\mathbf{V}_i(\boldsymbol{\gamma})=\mathbf{I}+\mathbf{X}_i\operatorname{diag}(\boldsymbol{\gamma})\mathbf{X}_i^\top.
\end{equation*}
Begin by choosing any $\boldsymbol{\beta}\in\mathbb{R}^p$ and $\boldsymbol{\gamma}\in\mathbb{R}_+^p$ such that $\|\boldsymbol{\gamma}\|_\infty\leq\bar{\gamma}$. Consider the first term $\sum_{i=1}^m\log\det\{\mathbf{V}_i(\boldsymbol{\gamma})\}$ on the right-hand side of \eqref{eq:ll2}. Since $\operatorname{diag}(\boldsymbol{\gamma})$ is positive semi-definite (because $\gamma_k\geq0$ for all $k$), the product $\mathbf{X}_i\operatorname{diag}(\boldsymbol{\gamma})\mathbf{X}_i^\top$ must also be positive semi-definite. Hence, $\mathbf{V}_i(\boldsymbol{\gamma})$ must be positive definite and its minimal eigenvalue $\lambda_\mathrm{min}$ must satisfy
\begin{equation*}
\lambda_\mathrm{min}\{\mathbf{V}_i(\boldsymbol{\gamma})\}=\lambda_\mathrm{min}(\mathbf{I}+\mathbf{X}_i\operatorname{diag}(\boldsymbol{\gamma})\mathbf{X}_i^\top)\geq\lambda_\mathrm{min}(\mathbf{I})=1.
\end{equation*}
It follows immediately from the property of determinants that $\det\{\mathbf{V}_i(\boldsymbol{\gamma})\}\geq1$ and hence
\begin{equation}
\label{eq:lb1}
\sum_{i=1}^m\log\det\{\mathbf{V}_i(\boldsymbol{\gamma})\}\geq0.
\end{equation}
Consider now the second term $n\log\{\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\}$ on the right-hand side of \eqref{eq:ll2}. The maximal eigenvalue $\lambda_\mathrm{max}$ of $\mathbf{V}_i(\boldsymbol{\gamma})$ satisfies
\begin{equation*}
\lambda_\mathrm{max}\{\mathbf{V}_i(\boldsymbol{\gamma})\}=\lambda_\mathrm{max}(\mathbf{I}+\mathbf{X}_i\operatorname{diag}(\boldsymbol{\gamma})\mathbf{X}_i^\top)\leq1+\bar{\gamma}\lambda_\mathrm{max}(\mathbf{X}_i\mathbf{X}_i^\top)\leq c_1:=1+\bar{\gamma}\lambda_\mathrm{max}(\mathbf{X}\mathbf{X}^\top)>0,
\end{equation*}
and hence the minimal eigenvalue of $\mathbf{V}_i^{-1}(\boldsymbol{\gamma})$ satisfies
\begin{equation*}
\lambda_\mathrm{min}\{\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\}=\frac{1}{\lambda_\mathrm{max}\{\mathbf{V}_i(\boldsymbol{\gamma})\}}\geq\frac{1}{c_1}.
\end{equation*}
It follows from the property of eigenvalues that
\begin{equation*}
\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\geq \sum_{i=1}^m\frac{1}{c_1}\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}\|_2^2=\frac{1}{c_1}\|\mathbf{y}-\mathbf{X}\boldsymbol{\beta}\|_2^2.
\end{equation*}
By assumption, $\mathbf{y}$ is not in the column space spanned by $\mathbf{X}$, so there is a $c_2>0$ such that
\begin{equation*}
\|\mathbf{y}-\mathbf{X}\boldsymbol{\beta}\|_2^2\geq c_2.
\end{equation*}
Thus, we have
\begin{equation*}
\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\geq\frac{c_2}{c_1},
\end{equation*}
and hence
\begin{equation}
\label{eq:lb2}
n\log\left\{\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right\}\geq c:=n\log\left(\frac{c_2}{c_1}\right).
\end{equation}
Combining \eqref{eq:lb1} and \eqref{eq:lb2} yields the result of the lemma.
\end{proof}

\begin{lemma}
\label{lemma:lipschitz}
Suppose $\mathbf{y}$ does not lie in the column space of $\mathbf{X}$ and that $\boldsymbol{\beta}\in\mathbb{R}^p$ and $\boldsymbol{\gamma}\in\mathbb{R}_+^p$ satisfy $\|\boldsymbol{\beta}\|_\infty\leq\bar{\beta}$ and $\|\boldsymbol{\gamma}\|_\infty\leq\bar{\gamma}$. Then the negative log-likelihood gradients \eqref{eq:gradbeta} and \eqref{eq:gradgamma} are Lipschitz continuous in the $k$th block of coordinates.
\end{lemma}
\begin{proof}
To facilitate exposition, define the functions
\begin{equation*}
A(\boldsymbol{\beta},\boldsymbol{\gamma})=\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})
\end{equation*}
and
\begin{equation*}
B(\boldsymbol{\beta},\boldsymbol{\gamma})=\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}).
\end{equation*}
Consider first the gradient \eqref{eq:gradbeta} of the negative log-likelihood with respect to $\beta_k$, which can be written in terms of $A(\boldsymbol{\beta},\boldsymbol{\gamma})$ and $B(\boldsymbol{\beta},\boldsymbol{\gamma})$ as
\begin{equation*}
\nabla_{\beta_k}l(\boldsymbol{\beta},\boldsymbol{\gamma})=-2n\frac{A(\boldsymbol{\beta},\boldsymbol{\gamma})}{B(\boldsymbol{\beta},\boldsymbol{\gamma})}.
\end{equation*}
Our task is to show that $\nabla_{\beta_k}l(\boldsymbol{\beta},\boldsymbol{\gamma})$ is Lipschitz continuous in block $k$, i.e., that there exists a constant $L_{\beta_k}\geq0$ such that
\begin{equation*}
|\nabla_{\beta_k}l(\boldsymbol{\beta}^{(1)},\boldsymbol{\gamma}^{(1)})-\nabla_{\beta_k}l(\boldsymbol{\beta}^{(2)},\boldsymbol{\gamma}^{(2)})|\leq L_{\beta_k}\left(|\beta_k^{(1)}-\beta_k^{(2)}|+|\gamma_k^{(1)}-\gamma_k^{(2)}|\right),
\end{equation*}
for any feasible $\boldsymbol{\beta}^{(1)}$ and $\boldsymbol{\beta}^{(2)}$ and any feasible $\boldsymbol{\gamma}^{(1)}$ and $\boldsymbol{\gamma}^{(2)}$ differing only in coordinate $k$. Hereafter, we use the shorthand $A^{(1)}$ and $B^{(1)}$ for $A(\boldsymbol{\beta}^{(1)},\boldsymbol{\gamma}^{(1)})$ and $B(\boldsymbol{\beta}^{(1)},\boldsymbol{\gamma}^{(1)})$, and similarly for $A^{(2)}$ and $B^{(2)}$. First, observe that
\begin{equation*}
\begin{split}
|\nabla_{\beta_k}l(\boldsymbol{\beta}^{(1)},\boldsymbol{\gamma}^{(1)})-\nabla_{\beta_k}l(\boldsymbol{\beta}^{(2)},\boldsymbol{\gamma}^{(2)})|&=2n\left|\frac{A^{(1)}}{B^{(1)}}-\frac{A^{(2)}}{B^{(2)}}\right| \\
&=2n\left|\frac{A^{(1)}B^{(2)}-A^{(2)}B^{(1)}}{B^{(1)}B^{(2)}}\right| \\
&=2n\left|\frac{B^{(1)}(A^{(1)}-A^{(2)})-A^{(1)}(B^{(1)}-B^{(2)})}{B^{(1)}B^{(2)}}\right| \\
&\leq\frac{2n}{|B^{(1)}B^{(2)}|}\left(|B^{(1)}||A^{(1)}-A^{(2)}|+|A^{(1)}||B^{(1)}-B^{(2)}|\right).
\end{split}
\end{equation*}
By the same arguments used in the proof of Lemma~\ref{lemma:bounded}, there exists a positive constant (call it $c_1$) independent of $\beta_k$ and $\gamma_k$ that lower bounds $B^{(1)}$ and $B^{(2)}$, and hence $1/|B^{(1)}B^{(2)}|\leq 1/c_1^2$. To upper bound $|A^{(1)}|$ and $|B^{(1)}|$, we use that
\begin{equation*}
\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\|_2=\lambda_\mathrm{max}\{\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\}=\frac{1}{\lambda_\mathrm{min}\{\mathbf{V}_i(\boldsymbol{\gamma})\}}\leq\frac{1}{1}=1
\end{equation*}
and
\begin{equation*}
\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}\|_2\leq\|\mathbf{y}-\mathbf{X}\boldsymbol{\beta}\|_2\leq\|\mathbf{y}\|_2+\|\mathbf{X}\boldsymbol{\beta}\|_2\leq\|\mathbf{y}\|_2+\bar{\beta}\sum_{j=1}^p\|\mathbf{x}_j\|_2\leq c_2:=\|\mathbf{y}\|_2+\bar{\beta}p,
\end{equation*}
since the columns of $\mathbf{X}$ have unit $\ell_2$ norm. It follows from the above two chains of inequalities that
\begin{equation*}
|A^{(1)}|\leq\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})\|_2\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)}\|_2\leq c_2\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2\leq c_2\sqrt{m}
\end{equation*}
and
\begin{equation*}
|B^{(1)}|\leq\sum_{i=1}^m\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)}\|_2\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})\|_2\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)}\|_2\leq c_2^2m.
\end{equation*}
Hence, there exists a constant $c_3\geq0$ such that
\begin{equation*}
|\nabla_{\beta_k}l(\boldsymbol{\beta}^{(1)},\boldsymbol{\gamma}^{(1)})-\nabla_{\beta_k}l(\boldsymbol{\beta}^{(2)},\boldsymbol{\gamma}^{(2)})|\leq c_3\left(|A^{(1)}-A^{(2)}|+|B^{(1)}-B^{(2)}|\right).
\end{equation*}
We now bound $|A^{(1)}-A^{(2)}|$ and $|B^{(1)}-B^{(2)}|$ in terms of $|\beta_k^{(1)}-\beta_k^{(2)}|+|\gamma_k^{(1)}-\gamma_k^{(2)}|$. Towards this end, we use that
\begin{equation*}
\begin{split}
\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})-\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})\|_2&=\left\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})\left[\mathbf{V}_i(\boldsymbol{\gamma}^{(2)})-\mathbf{V}_i(\boldsymbol{\gamma}^{(1)})\right]\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})\right\|_2 \\
&\leq\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})\|_2\|\mathbf{V}_i(\boldsymbol{\gamma}^{(1)})-\mathbf{V}_i(\boldsymbol{\gamma}^{(2)})\|_2\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})\|_2 \\
&\leq\|(\mathbf{I}+\mathbf{X}_i\operatorname{diag}(\boldsymbol{\gamma}^{(1)})\mathbf{X}_i^\top)-(\mathbf{I}+\mathbf{X}_i\operatorname{diag}(\boldsymbol{\gamma}^{(2)})\mathbf{X}_i^\top)\|_2 \\
&=\|\mathbf{x}_{ik}\|_2^2|\gamma_k^{(1)}-\gamma_k^{(2)}| \\
&\leq|\gamma_k^{(1)}-\gamma_k^{(2)}|,
\end{split}
\end{equation*}
since $\|\mathbf{x}_{ik}\|_2\leq 1$, and
\begin{equation*}
\|(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)})-(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(2)})\|_2=\|\mathbf{X}_i(\boldsymbol{\beta}^{(1)}-\boldsymbol{\beta}^{(2)})\|_2=\|\mathbf{x}_{ik}\|_2|\beta_k^{(1)}-\beta_k^{(2)}|\leq|\beta_k^{(1)}-\beta_k^{(2)}|.
\end{equation*}
Using the above two inequalities, we upper bound $|A^{(1)}-A^{(2)}|$ as
\begin{equation*}
\begin{split}
|A^{(1)}-A^{(2)}|&=\left|\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)})-\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(2)})\right| \\
&\leq\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2\left\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)})-\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(2)})\right\|_2 \\
&=\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2\left\|\{\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})-\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})\}(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)})\right. \\
&\hspace{1.5in}\left.+\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})\{(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)})-(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(2)})\}\right\|_2 \\
&\leq\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(1)})-\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})\|_2\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)}\|_2 \\
&\hspace{1in}+\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma}^{(2)})\|_2\|(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(1)})-(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}^{(2)})\|_2 \\
&\leq c_2\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2|\gamma_k^{(1)}-\gamma_k^{(2)}|+\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2|\beta_k^{(1)}-\beta_k^{(2)}| \\
&\leq c_2\sqrt{m}|\gamma_k^{(1)}-\gamma_k^{(2)}|+\sqrt{m}|\beta_k^{(1)}-\beta_k^{(2)}| \\
&\leq c_4(|\beta_k^{(1)}-\beta_k^{(2)}|+|\gamma_k^{(1)}-\gamma_k^{(2)}|),
\end{split}
\end{equation*}
where $c_4:=(1+c_2)\sqrt{m}$. One can upper bound $|B^{(1)}-B^{(2)}|$ by a similar line of working. Call the constant in that upper bound $c_5\geq0$. It follows that
\begin{equation*}
\begin{split}
|\nabla_{\beta_k}l(\boldsymbol{\beta}^{(1)},\boldsymbol{\gamma}^{(1)})-\nabla_{\beta_k}l(\boldsymbol{\beta}^{(2)},\boldsymbol{\gamma}^{(2)})|&\leq c_3\left(|A^{(1)}-A^{(2)}|+|B^{(1)}-B^{(2)}|\right) \\
&\leq c_3\max(c_4,c_5)\left(|\beta_k^{(1)}-\beta_k^{(2)}|+|\gamma_k^{(1)}-\gamma_k^{(2)}|\right).
\end{split}
\end{equation*}
Hence, $\nabla_{\beta_k}l(\boldsymbol{\beta},\boldsymbol{\gamma})$ is Lipschitz with constant $L_{\beta_k}=c_3\max(c_4,c_5)$. The same line of argument, omitted here for brevity, establishes that $\nabla_{\gamma_k}l(\boldsymbol{\beta},\boldsymbol{\gamma})$ is also Lipschitz with constant $L_{\gamma_k}\geq0$. Finally, the proof is completed by taking $L_k=\max(L_{\beta_k},L_{\gamma_k})$.
\end{proof}

\subsection{Proof of Main Results}

With the preliminary lemmas in hand, we can now prove the main results. The proof is presented in two parts: (i) a proof of convergence of the objective value, and (ii) a proof of convergence of the active set. The steps in our proof follow those used in the proof of Theorem 1 in \citet{Dedieu2021}.

\paragraph{Convergence of Objective Value}

Let $(\boldsymbol{\beta}^\star,\boldsymbol{\gamma}^\star)$ be the result of applying the thresholding function \eqref{eq:threshold} to $(\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})$. Since $l(\boldsymbol{\beta},\boldsymbol{\gamma})$ is Lipschitz on a compact set (Lemma~\ref{lemma:lipschitz}), we can invoke inequality \eqref{eq:bdlemma}. Substituting $\boldsymbol{\beta}=\boldsymbol{\beta}^\star$ and $\boldsymbol{\gamma}=\boldsymbol{\gamma}^\star$ into \eqref{eq:obj} gives
\begin{equation*}
\begin{split}
f(\boldsymbol{\beta}^\star,\boldsymbol{\gamma}^\star)&\leq f_{L_k}(\boldsymbol{\beta}^\star,\boldsymbol{\gamma}^\star;\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})=l(\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})+\nabla l(\tilde{\beta}_k)(\beta_k^\star-\tilde{\beta}_k)+\nabla l(\tilde{\gamma}_k)(\gamma_k^\star-\tilde{\gamma}_k) \\
&\hspace{1.2in}+\frac{L_k}{2}\left\{(\beta_k^\star-\tilde{\beta}_k)^2+(\gamma_k^\star-\tilde{\gamma}_k)^2\right\}+\lambda\alpha\|\boldsymbol{\beta}^\star\|_0+\lambda(1-\alpha)\|\boldsymbol{\gamma}^\star\|_0.
\end{split}
\end{equation*}
Next, we add and subtract $\bar{L}_k/2\{(\beta_k^\star-\tilde{\beta}_k)^2+(\gamma_k^\star-\tilde{\gamma}_k)^2\}$ on the right-hand side to get
\begin{equation*}
\begin{split}
f(\boldsymbol{\beta}^\star,\boldsymbol{\gamma}^\star)&\leq l(\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})+\nabla l(\tilde{\beta}_k)(\beta_k^\star-\tilde{\beta}_k)+\nabla l(\tilde{\gamma}_k)(\gamma_k^\star-\tilde{\gamma}_k) \\
&\hspace{0.5in}+\frac{\bar{L}_k}{2}\left\{(\beta_k^\star-\tilde{\beta}_k)^2+(\gamma_k^\star-\tilde{\gamma}_k)^2\right\}+\frac{L_k-\bar{L}_k}{2}\left\{(\beta_k^\star-\tilde{\beta}_k)^2+(\gamma_k^\star-\tilde{\gamma}_k)^2\right\} \\
&\hspace{1in}+\lambda\alpha\|\boldsymbol{\beta}^\star\|_0+\lambda(1-\alpha)\|\boldsymbol{\gamma}^\star\|_0 \\
&=\bar{f}_{\bar{L}_k}(\boldsymbol{\beta}^\star,\boldsymbol{\gamma}^\star;\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})+\frac{L_k-\bar{L}_k}{2}\left\{(\beta_k^\star-\tilde{\beta}_k)^2+(\gamma_k^\star-\tilde{\gamma}_k)^2\right\}.
\end{split}
\end{equation*}
Using that $\bar{f}_{\bar{L}_k}(\boldsymbol{\beta}^\star,\boldsymbol{\gamma}^\star;\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})\leq\bar{f}_{\bar{L}_k}(\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}};\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})=f(\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})$ and rearranging terms, we get
\begin{equation*}
f(\tilde{\boldsymbol{\beta}},\tilde{\boldsymbol{\gamma}})-f(\boldsymbol{\beta}^\star,\boldsymbol{\gamma}^\star)\geq\frac{\bar{L}_k-L_k}{2}\left\{(\tilde{\beta}_k-\beta_k^\star)^2+(\tilde{\gamma}_k-\gamma_k^\star)^2\right\}.
\end{equation*}
Finally, taking $\boldsymbol{\beta}^\star=\boldsymbol{\beta}^{(t+1)}$, $\tilde{\boldsymbol{\beta}}=\boldsymbol{\beta}^{(t)}$, $\boldsymbol{\gamma}^\star=\boldsymbol{\gamma}^{(t+1)}$, and $\tilde{\boldsymbol{\gamma}}=\boldsymbol{\gamma}^{(t)}$, and recalling that all $p$ coordinates are updated in a single cycle of coordinate descent (i.e., $p$ block coordinate updates from iteration $t$ to $t+1$), we have
\begin{equation*}
f(\boldsymbol{\beta}^{(t)},\boldsymbol{\gamma}^{(t)})-f(\boldsymbol{\beta}^{(t+1)},\boldsymbol{\gamma}^{(t+1)})\geq\sum_{k=1}^p\frac{\bar{L}_k-L_k}{2}\left\{(\beta_k^{(t)}-\beta_k^{(t+1)})^2+(\gamma_k^{(t)}-\gamma_k^{(t+1)})^2\right\}.
\end{equation*}
The right-hand side is nonnegative for $\bar{L}_k\geq L_k$. Hence, the sequence $\{f(\boldsymbol{\beta}^{(t)},\boldsymbol{\gamma}^{(t)})\}_{t\in\mathbb{N}}$ is decreasing and, because it is bounded below on a compact set (Lemma~\ref{lemma:bounded}), convergent.

\paragraph{Convergence of Active Set}

We proceed using proof by contradiction. Suppose the active set does not converge in finitely many iterations. Choose $t$ such that $\mathcal{A}^{(t)}\neq\mathcal{A}^{(t+1)}$. Then for some $k=1,\dots,p$ either (i) $\beta_k^{(t)}=0$ and $\beta_k^{(t+1)}\neq0$, or (ii) $\beta_k^{(t)}\neq0$ and $\beta_k^{(t+1)}=0$. Consider case (i). By the previous result we have
\begin{equation*}
f(\boldsymbol{\beta}^{(t)},\boldsymbol{\gamma}^{(t)})-f(\boldsymbol{\beta}^{(t+1)},\boldsymbol{\gamma}^{(t+1)})\geq\frac{\bar{L}_k-L_k}{2}(\beta_k^{(t+1)})^2.
\end{equation*}
Because $\beta_k^{(t+1)}$ is the output of the thresholding function, it holds $\beta_k^{(t+1)}\geq\sqrt{2\lambda\alpha/\bar{L}_k}$, giving
\begin{equation*}
f(\boldsymbol{\beta}^{(t)},\boldsymbol{\gamma}^{(t)})-f(\boldsymbol{\beta}^{(t+1)},\boldsymbol{\gamma}^{(t+1)})\geq\frac{\bar{L}_k-L_k}{\bar{L}_k}\lambda\alpha,
\end{equation*}
which is positive for $\bar{L}_k>L_k$. The same line of working establishes a similar inequality for case (ii). The quantity on the right-hand side is positive, indicating the objective value strictly decreases. If the active set does not converge then the objective value must decrease indefinitely, which contradicts the fact that the objective value is bounded below on a compact set (Lemma~\ref{lemma:bounded}). Therefore, the active set must converge in finitely many iterations.

\section{Proof of Proposition~\ref{prop:lambda}}
\label{app:lambda}

Let $\lambda^{(r)}$ be the current value of the sparsity parameter. Under the conditions of Theorem~\ref{thrm:converge} the active set $\mathcal{A}^{(r)}$ converges in finitely many iterations, meaning that no active predictors are removed from the model by the thresholding function \eqref{eq:threshold} and no inactive predictors are added. Hence, by the first condition on the inactive predictors in \eqref{eq:threshold}, it must hold for all $k\not\in\mathcal{A}^{(r)}$ (i.e., all inactive predictors) that
\begin{equation*}
\begin{split}
\left(\frac{-\nabla l(\beta_k^{(r)})}{\bar{L}_k}\right)^2&<\frac{2\lambda^{(r)}\alpha}{\bar{L}_k} \\
\nabla l(\beta_k^{(r)})^2&<2\lambda^{(r)}\alpha\bar{L}_k \\
\frac{\nabla l(\beta_k^{(r)})^2}{2\alpha\bar{L}_k}&<\lambda^{(r)}.
\end{split}
\end{equation*}
Likewise, by the second condition on the inactive predictors in \eqref{eq:threshold}, we have
\begin{equation*}
\begin{split}
\left(\frac{-\nabla l(\beta_k^{(r)})}{\bar{L}_k}\right)^2+\left(\frac{\max(-\nabla l(\gamma_k^{(r)}),0)}{\bar{L}_k}\right)^2&<\frac{2\lambda^{(r)}}{\bar{L}_k} \\
\nabla l(\beta_k^{(r)})^2+\max(-\nabla l(\gamma_k^{(r)}),0)^2&<2\lambda^{(r)}\bar{L}_k \\
\frac{\nabla l(\beta_k^{(r)})^2+\max(-\nabla l(\gamma_k^{(r)}),0)^2}{2\bar{L}_k}&<\lambda^{(r)}.
\end{split}
\end{equation*}
Hence, if we take $\lambda=\lambda^{(r+1)}$, where
\begin{equation*}
\lambda^{(r+1)}<\max_{k\not\in\mathcal{A}^{(r)}}\;\max\left(\frac{\nabla l(\beta_k^{(r)})^2}{2\alpha\bar{L}_k},\frac{\nabla l(\beta_k^{(r)})^2+\max(-\nabla l(\gamma_k^{(r)}),0)^2}{2\bar{L}_k}\right),
\end{equation*}
then one of the above conditions will be violated and the active set must change.

\section{Proof of Theorem~\ref{thrm:bound}}
\label{app:bound}

\subsection{Preliminary Lemmas}

The proof of the theorem requires several technical lemmas, which we now state and prove. The first two lemmas provide probabilistic upper bounds on important quantities. The last two lemmas ensure the negative log-likelihood and its expectation are Lipschitz continuous.

\begin{lemma}
\label{lemma:prob1}
Let $(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{C}(s)$. Then, for any $t>0$, it holds
\begin{equation*}
\begin{split}
&\Pr\left[\left|\frac{1}{\sigma^2}\sum_{i=1}^m\left[\boldsymbol{\nu}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i-\sigma^2\operatorname{tr}\left\{\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\right\}\right]\right|\geq t\right] \\
&\hspace{2.5in}\leq2\exp\left\{-c\min\left(\frac{t^2}{n(1+\bar{\gamma}s)^2},\frac{t}{1+\bar{\gamma}s}\right)\right\},
\end{split}
\end{equation*}
where $c>0$ is a universal constant.
\end{lemma}

\begin{proof}
Let $\mathbf{h}_i=\sigma^{-1}\mathbf{V}_i^{-\frac{1}{2}}(\boldsymbol{\gamma}^0)\boldsymbol{\nu}_i$ so that $\mathbf{h}_i\sim\mathrm{N}(\mathbf{0},\mathbf{I})$. Additionally, let
\begin{equation*}
\mathbf{A}_i=\mathbf{V}_i^{\frac{1}{2}}(\boldsymbol{\gamma}^0)\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i^{\frac{1}{2}}(\boldsymbol{\gamma}^0).
\end{equation*}
It follows
\begin{equation*}
\frac{1}{\sigma^2}\boldsymbol{\nu}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i=\mathbf{h}_i^\top\mathbf{A}_i\mathbf{h}_i
\end{equation*}
and
\begin{equation*}
\operatorname{tr}\left\{\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\right\}=\operatorname{tr}(\mathbf{A}_i).
\end{equation*}
For any $\mathbf{h}\sim\mathrm{N}(\mathbf{0},\mathbf{I})$, matrix $\mathbf{A}$, and $t>0$, the Hanson-Wright inequality \citep{Rudelson2013} gives
\begin{equation*}
\Pr\left[|\mathbf{h}^\top\mathbf{A}\mathbf{h}-\operatorname{E}[\mathbf{h}^\top\mathbf{A}\mathbf{h}]|\geq t\right]\leq 2\exp\left\{-c\min\left(\frac{t^2}{\|\mathbf{A}\|_F^2},\frac{t}{\|\mathbf{A}\|_2}\right)\right\},
\end{equation*}
for some universal constant $c>0$. Hence, using that $\operatorname{E}\left[\mathbf{h}^\top\mathbf{A}\mathbf{h}\right]=\operatorname{tr}(\mathbf{A})$ for any $\mathbf{h}\sim\mathrm{N}(\mathbf{0},\mathbf{I})$ and matrix $\mathbf{A}$, we have
\begin{equation*}
\Pr\left[|\mathbf{h}_i^\top\mathbf{A}_i\mathbf{h}_i-\operatorname{tr}(\mathbf{A}_i)|\geq t\right]\leq2\exp\left\{-c\min\left(\frac{t^2}{\|\mathbf{A}_i\|_F^2},\frac{t}{\|\mathbf{A}_i\|_2}\right)\right\}.
\end{equation*}
Now, to take the sum over $i=1,\dots,m$, we use that
\begin{equation*}
\sum_{i=1}^m\left\{\mathbf{h}_i^\top\mathbf{A}_i\mathbf{h}_i-\operatorname{tr}(\mathbf{A}_i)\right\}=
\begin{pmatrix}
\mathbf{h}_1 \\ 
\vdots \\
\mathbf{h}_m
\end{pmatrix}^\top
\begin{pmatrix}
\mathbf{A}_1 & \hdots & \mathbf{0} \\
\vdots & \ddots & \vdots \\
\mathbf{0} & \hdots & \mathbf{A}_m
\end{pmatrix}
\begin{pmatrix}
\mathbf{h}_1 \\ 
\vdots \\
\mathbf{h}_m
\end{pmatrix}
-\operatorname{tr}\left\{
\begin{pmatrix}
\mathbf{A}_1 & \hdots & \mathbf{0} \\
\vdots & \ddots & \vdots \\
\mathbf{0} & \hdots & \mathbf{A}_m
\end{pmatrix}
\right\}
\end{equation*}
with
\begin{equation*}
\left\|
\begin{pmatrix}
\mathbf{A}_1 & \hdots & \mathbf{0} \\
\vdots & \ddots & \vdots \\
\mathbf{0} & \hdots & \mathbf{A}_m
\end{pmatrix}
\right\|_F^2=\sum_{i=1}^m\|\mathbf{A}_i\|_F^2
\end{equation*}
and
\begin{equation*}
\left\|
\begin{pmatrix}
\mathbf{A}_1 & \hdots & \mathbf{0} \\
\vdots & \ddots & \vdots \\
\mathbf{0} & \hdots & \mathbf{A}_m
\end{pmatrix}
\right\|_2=\max_{i=1,\dots,m}\|\mathbf{A}_i\|_2.
\end{equation*}
It immediately follows
\begin{equation*}
\Pr\left[\left|\sum_{i=1}^m\left\{\mathbf{h}_i^\top\mathbf{A}_i\mathbf{h}_i-\operatorname{tr}(\mathbf{A}_i)\right\}\right|\geq t\right]\leq 2\exp\left\{-c\min\left(\frac{t^2}{\sum_{i=1}^m\|\mathbf{A}_i\|_F^2},\frac{t}{\underset{i=1,\dots,m}{\max}\|\mathbf{A}_i\|_2}\right)\right\}.
\end{equation*}
We now upper bound the right-hand side by upper bounding the terms in the denominator on the right-hand side. First, we have
\begin{equation*}
\|\mathbf{A}_i\|_2=\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\|_2\leq\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\|_2\|\mathbf{V}_i(\boldsymbol{\gamma}^0)\|_2\leq1+\bar{\gamma}s,
\end{equation*}
where we use that
\begin{equation*}
\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\|_2=\frac{1}{\lambda_\mathrm{min}\{\mathbf{V}_i(\boldsymbol{\gamma})\}}\leq\frac{1}{1}=1,
\end{equation*}
which follows from the lower bound on $\lambda_\mathrm{min}\{\mathbf{V}_i(\boldsymbol{\gamma})\}$ in the proof of Lemma~\ref{lemma:bounded}, and
\begin{equation*}
\|\mathbf{V}_i(\boldsymbol{\gamma}^0)\|_2\leq1+\sum_{k:\gamma_k^0\neq0}\gamma_k^0\|\mathbf{x}_{ik}\|_2^2\leq1+s\bar{\gamma},
\end{equation*}
since the columns of $\mathbf{X}$ have unit $\ell_2$ norm and $\boldsymbol{\gamma}$ has $s$ nonzero components. Next, we use that $\|\mathbf{A}_i\|_F^2\leq n_i\|\mathbf{A}_i\|_2^2$ in tandem with the above result to get
\begin{equation*}
\sum_{i=1}^m\|\mathbf{A}_i\|_F^2\leq\sum_{i=1}^mn_i\|\mathbf{A}_i\|_2^2\leq\sum_{i=1}^mn_i(1+\bar{\gamma}s)^2=n(1+\bar{\gamma}s)^2.
\end{equation*}
Finally, we conclude
\begin{equation*}
\Pr\left[\left|\sum_{i=1}^m\left\{\mathbf{h}_i^\top\mathbf{A}_i\mathbf{h}_i-\operatorname{tr}(\mathbf{A}_i)\right\}\right|\geq t\right]\leq2\exp\left\{-c\min\left(\frac{t^2}{n(1+\bar{\gamma}s)^2},\frac{t}{1+\bar{\gamma}s}\right)\right\}.
\end{equation*}
\end{proof}

\begin{lemma}
\label{lemma:prob2}
Let $(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{C}(s)$. Then, for any $t>0$, it holds
\begin{equation*}
\Pr\left[\left|\frac{1}{\sigma^2}\sum_{i=1}^m2(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{X}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i\right|\geq t\right]\leq2\exp\left(-\frac{t^2}{128\sigma^{-2}(1+\bar{\gamma}s)s^2\bar{\beta}^2}\right).
\end{equation*}
\end{lemma}

\begin{proof}
Let $\mathbf{h}_i=\mathbf{X}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i$ so that
\begin{equation*}
\frac{1}{\sigma^2}\sum_{i=1}^m2(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{X}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i=\frac{1}{\sigma^2}\sum_{i=1}^m2(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{h}_i.
\end{equation*}
Since $\mathbf{X}_i$ and $\mathbf{V}_i^{-1}(\boldsymbol{\gamma})$ are fixed and $\boldsymbol{\nu}_i\sim\mathrm{N}(\mathbf{0},\sigma^2\mathbf{V}_i(\boldsymbol{\gamma}^0))$, it holds
\begin{equation*}
\mathbf{h}_i\sim\mathrm{N}(\mathbf{0},\sigma^2\mathbf{X}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{X}_i).
\end{equation*}
Pre-multiplying $\mathbf{h}_i$ by $2\sigma^{-2}(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top$, which is also a fixed quantity, we get the scalar random variable
\begin{equation*}
\frac{2}{\sigma^2}(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{h}_i\sim\mathrm{N}(0,\nu_i^2),
\end{equation*}
where
\begin{equation*}
\nu_i^2=\frac{4}{\sigma^2}(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{X}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta}).
\end{equation*}
Since $\boldsymbol{\nu}_i$ and $\boldsymbol{\nu}_j$ are independent for all $i\neq j$, we can sum over $i=1,\dots,m$ to get
\begin{equation*}
\frac{1}{\sigma^2}\sum_{i=1}^m2(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{h}_i\sim\mathrm{N}\left(0,\sum_{i=1}^m\nu_i^2\right).
\end{equation*}
We can now invoke the standard Gaussian tail bound $\Pr[|X|>t]\leq 2\exp\{-t^2/(2\nu^2)\}$ for $X\sim\mathrm{N}(0,\nu^2)$ and $t>0$ to get
\begin{equation*}
\Pr\left[\left|\frac{1}{\sigma^2}\sum_{i=1}^m2(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{h}_i\right|\geq t\right]\leq2\exp\left(-\frac{t^2}{2\sum_{i=1}^m\nu_i^2}\right).
\end{equation*}
Now, using that $\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\|_2\leq1$ and $\|\mathbf{V}_i(\boldsymbol{\gamma}^0)\|_2\leq1+\bar{\gamma}s$ as in the proof of Lemma~\ref{lemma:prob1}, we can upper bound the right-hand side by upper bounding the variance term appearing in the denominator as
\begin{equation*}
\begin{split}
\sum_{i=1}^m\nu_i^2&=\sum_{i=1}^m\frac{4}{\sigma^2}(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{X}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta}) \\
&\leq\sum_{i=1}^m\frac{4}{\sigma^2}(1+\bar{\gamma}s)(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{X}_i^\top\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta}) \\
&=\sum_{i=1}^m\frac{4}{\sigma^2}(1+\bar{\gamma}s)\|\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})\|_2^2 \\
&=\frac{4}{\sigma^2}(1+\bar{\gamma}s)\|\mathbf{X}(\boldsymbol{\beta}^0-\boldsymbol{\beta})\|_2^2.
\end{split}
\end{equation*}
Moreover, for any $\boldsymbol{\Delta}$ with $\|\boldsymbol{\Delta}\|_0\leq2s$ and $\|\boldsymbol{\Delta}\|_\infty\leq2\bar{\Delta}$, we have
\begin{equation*}
\|\mathbf{X}\boldsymbol{\Delta}\|_2=\left\|\sum_{k:\Delta_k\neq0}\Delta_k\mathbf{x}_k\right\|_2\leq\sum_{k:\Delta_k\neq0}|\Delta_k|\|\mathbf{x}_k\|_2\leq\sum_{k:\Delta_k\neq0}|\Delta_k|\leq4s\bar{\Delta}
\end{equation*}
and hence
\begin{equation*}
\frac{4}{\sigma^2}(1+\bar{\gamma}s)\|\mathbf{X}(\boldsymbol{\beta}^0-\boldsymbol{\beta})\|_2^2\leq\frac{64}{\sigma^2}(1+\bar{\gamma}s)s^2\bar{\beta}^2.
\end{equation*}
Finally, we conclude
\begin{equation*}
\Pr\left[\left|\frac{1}{\sigma^2}\sum_{i=1}^m2(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{h}_i\right|\geq t\right]\leq2\exp\left(-\frac{t^2}{128\sigma^{-2}(1+\bar{\gamma}s)s^2\bar{\beta}^2}\right).
\end{equation*}
\end{proof}

\begin{lemma}
\label{lemma:lipschitz2}
Let $\mathcal{S}_s$ denote the collection of all sets $\mathcal{A}\subseteq\{1,\dots,p\}$ with cardinality $|\mathcal{A}|\leq s$. Fix any $\mathcal{A}\in\mathcal{S}_s$. Define the constraint set
\begin{equation*}
\mathcal{B}(\mathcal{A}):=\left\{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathbb{R}^p\times\mathbb{R}_+^p:\|\boldsymbol{\beta}\|_\infty\leq\bar{\beta},\|\boldsymbol{\gamma}\|_\infty\leq\bar{\gamma},\operatorname{Supp}(\boldsymbol{\gamma})\subseteq\operatorname{Supp}(\boldsymbol{\beta})\subseteq\mathcal{A}\right\}
\end{equation*}
and its convex hull
\begin{equation*}
\tilde{\mathcal{B}}(\mathcal{A}):=\left\{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathbb{R}^p\times\mathbb{R}_+^p:\|\boldsymbol{\beta}\|_\infty\leq\bar{\beta},\|\boldsymbol{\gamma}\|_\infty\leq\bar{\gamma},\operatorname{Supp}(\boldsymbol{\gamma})\subseteq\mathcal{A},\operatorname{Supp}(\boldsymbol{\beta})\subseteq\mathcal{A}\right\}.
\end{equation*}
Define the random quantity $L_\mathcal{A}(\mathbf{y})$ as
\begin{equation*}
L_\mathcal{A}(\mathbf{y}):=\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\tilde{\mathcal{B}}(\mathcal{A})}\;\|\nabla_{\beta_\mathcal{A},\gamma_\mathcal{A}}l(\boldsymbol{\beta},\boldsymbol{\gamma})\|_2.
\end{equation*}
Then almost surely $L_\mathcal{A}(\mathbf{y})<\infty$ and on that event $l(\boldsymbol{\beta},\boldsymbol{\gamma})$ is Lipschitz continuous on $\mathcal{B}(\mathcal{A})$, i.e., it holds
\begin{equation*}
|l(\boldsymbol{\beta},\boldsymbol{\gamma})-l(\boldsymbol{\beta}',\boldsymbol{\gamma}')|\leq L_\mathcal{A}(\mathbf{y})\sqrt{\|\boldsymbol{\beta}-\boldsymbol{\beta}'\|_2^2+\|\boldsymbol{\gamma}-\boldsymbol{\gamma}'\|_2^2}
\end{equation*}
for any $(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{B}(\mathcal{A})$ and $(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{B}(\mathcal{A})$. Moreover, for any $\delta\in(0,1]$, it holds
\begin{equation*}
\Pr\left[\max_{\mathcal{A}\in\mathcal{S}_s}\;L_\mathcal{A}(\mathbf{y})\leq L(\delta)\right]\geq1-\delta,
\end{equation*}
where $L(\delta)$ is a fixed quantity defined as
\begin{equation*}
L(\delta):=\sqrt{2s}\max\left(\frac{2}{\sigma^2}\{2\bar{\beta}s+g(\delta)\},1+\frac{1}{\sigma^2}\{2\bar{\beta}s+g(\delta)\}^2\right)
\end{equation*}
with
\begin{equation*}
g(\delta):=\sigma\sqrt{1+\bar{\gamma}s}\sqrt{n+2\sqrt{n\log\left(\frac{1}{\delta}\right)}+2\log\left(\frac{1}{\delta}\right)}.
\end{equation*}
\end{lemma}

\begin{proof}
We begin by proving the first claim of the lemma that $l$ is Lipschitz with constant $L_\mathcal{A}(\mathbf{y})$. Towards this end, we evaluate the components of $\nabla_{\beta_\mathcal{A},\gamma_{\mathcal{A}}}l(\boldsymbol{\beta},\boldsymbol{\gamma})$. First, rewrite $l(\boldsymbol{\beta},\boldsymbol{\gamma})=l_1(\boldsymbol{\gamma})+l_2(\boldsymbol{\beta},\boldsymbol{\gamma})$, where
\begin{equation*}
l_1(\boldsymbol{\gamma})=\sum_{i=1}^m\log\det\{\sigma^2\mathbf{V}_i(\boldsymbol{\gamma})\}
\end{equation*}
and
\begin{equation*}
l_2(\boldsymbol{\beta},\boldsymbol{\gamma})=\frac{1}{\sigma^2}\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}).
\end{equation*}
For $l_1$, a routine derivation gives the components of the gradient with respect to $\boldsymbol{\gamma}$ as
\begin{equation*}
\nabla_{\gamma_k}l_1(\boldsymbol{\gamma})=\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}.
\end{equation*}
Likewise, for $l_2$, the components of the gradient with respect to $\boldsymbol{\beta}$ and $\boldsymbol{\gamma}$ are respectively given by
\begin{equation*}
\nabla_{\beta_k}l_2(\boldsymbol{\beta},\boldsymbol{\gamma})=-\frac{1}{\sigma^2}\sum_{i=1}^m2\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})
\end{equation*}
and
\begin{equation*}
\nabla_{\gamma_k}l_2(\boldsymbol{\beta},\boldsymbol{\gamma})=-\frac{1}{\sigma^2}\sum_{i=1}^m\left\{\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right\}^2.
\end{equation*}
All three of the above gradients are continuous and $\tilde{\mathcal{B}}(\mathcal{A})$ is compact. Recall also that $\mathbf{y}\sim\mathrm{N}(\mathbf{X}\boldsymbol{\beta}^0,\sigma^2\mathbf{V}(\boldsymbol{\gamma}^0))$, so all components of $\mathbf{y}$ are almost surely finite. Hence, the gradient norm $\|\nabla_{\beta_\mathcal{A},\gamma_{\mathcal{A}}}l(\boldsymbol{\beta},\boldsymbol{\gamma})\|_2$ attains a maximum and thus
\begin{equation*}
L_\mathcal{A}(\mathbf{y})=\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\tilde{\mathcal{B}}(\mathcal{A})}\;\|\nabla_{\beta_\mathcal{A},\gamma_\mathcal{A}}l(\boldsymbol{\beta},\boldsymbol{\gamma})\|_2<\infty
\end{equation*}
almost surely. Moreover, since $\tilde{\mathcal{B}}(\mathcal{A})$ is convex, we can conclude by the mean value theorem that
\begin{equation*}
|l(\boldsymbol{\beta},\boldsymbol{\gamma})-l(\boldsymbol{\beta}',\boldsymbol{\gamma}')|\leq L_\mathcal{A}(\mathbf{y})\sqrt{\|\boldsymbol{\beta}-\boldsymbol{\beta}'\|_2^2+\|\boldsymbol{\gamma}-\boldsymbol{\gamma}'\|_2^2}
\end{equation*}
for any $\boldsymbol{\beta}'\neq\boldsymbol{\beta}$ and any $\boldsymbol{\gamma}'\neq\boldsymbol{\gamma}$ in $\tilde{\mathcal{B}}(\mathcal{A})$ almost surely. Furthermore, because $\mathcal{B}(\mathcal{A})\subseteq\tilde{\mathcal{B}}(\mathcal{A})$, the above inequality also holds for any $\boldsymbol{\beta}'\neq\boldsymbol{\beta}$ and any $\boldsymbol{\gamma}'\neq\boldsymbol{\gamma}$ in $\mathcal{B}(\mathcal{A})$, thereby establishing the first claim of the lemma that $l(\boldsymbol{\beta},\boldsymbol{\gamma})$ is almost surely $L_\mathcal{A}(\mathbf{y})$ Lipschitz on $\mathcal{B}(\mathcal{A})$. To establish the second claim of the lemma, we bound the components of $L_\mathcal{A}(\mathbf{y})$. Observe that 
\begin{equation*}
|\nabla_{\gamma_k}l_1(\boldsymbol{\gamma})|=\left|\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}\right|\leq\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\|_2\leq\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2=1,
\end{equation*}
where we use that $\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\|_2\leq1$ as in the proof of Lemma~\ref{lemma:prob1} and that the columns of $\mathbf{X}$ have unit $\ell_2$ norm. Next, see that
\begin{equation*}
\begin{split}
|\nabla_{\beta_k}l_2(\boldsymbol{\beta},\boldsymbol{\gamma})|&=\left|-\frac{1}{\sigma^2}\sum_{i=1}^m2\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right| \\
&\leq\frac{1}{\sigma^2}\sum_{i=1}^m2\|\mathbf{x}_{ik}\|_2\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}\|_2 \\
&\leq\frac{2}{\sigma^2}\sqrt{\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2}\sqrt{\sum_{i=1}^m\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}\|_2^2} \\
&=\frac{2}{\sigma^2}\|\mathbf{y}-\mathbf{X}\boldsymbol{\beta}\|_2 \\
&\leq\frac{2}{\sigma^2}(\|\mathbf{y}\|_2+\|\mathbf{X}\boldsymbol{\beta}\|_2) \\
&\leq\frac{2}{\sigma^2}(\|\mathbf{y}\|_2+\bar{\beta}s),
\end{split}
\end{equation*}
where the second inequality follows from the Cauchy-Schwarz inequality and we use that
\begin{equation*}
\|\mathbf{X}\boldsymbol{\beta}\|_2=\|\sum_{k:\beta_k\neq0}\beta_k\mathbf{x}_k\|_2\leq\sum_{k:\beta_k\neq0}|\beta_k|\|\mathbf{x}_k\|_2\leq\sum_{k:\beta_k\neq0}|\beta_k|\leq\bar{\beta}s.
\end{equation*}
Finally, observe that
\begin{equation*}
\begin{split}
|\nabla_{\gamma_k}l_2(\boldsymbol{\beta},\boldsymbol{\gamma})|&=\left|-\frac{1}{\sigma^2}\sum_{i=1}^m\left[\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right]^2\right| \\
&\leq\frac{1}{\sigma^2}\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2\|\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}\|_2^2 \\
&=\frac{1}{\sigma^2}\|\mathbf{y}-\mathbf{X}\boldsymbol{\beta}\|_2^2 \\
&\leq\frac{1}{\sigma^2}(\|\mathbf{y}\|_2+\|\mathbf{X}\boldsymbol{\beta}\|_2)^2 \\
&\leq\frac{1}{\sigma^2}(\|\mathbf{y}\|_2+\bar{\beta}s)^2.
\end{split}
\end{equation*}
Now, to bound $\|\mathbf{y}\|_2$, we use the inequality
\begin{equation*}
\|\mathbf{y}\|_2\leq\|\mathbf{X}\boldsymbol{\beta}^0\|_2+\|\boldsymbol{\nu}\|_2=\|\mathbf{X}\boldsymbol{\beta}^0\|_2+\sigma\|\mathbf{V}^{\frac{1}{2}}(\boldsymbol{\gamma}^0)\mathbf{z}\|_2\leq\bar{\beta}s+\sigma\sqrt{\lambda_{\max}\left\{\mathbf{V}(\boldsymbol{\gamma}^0)\right\}}\|\mathbf{z}\|_2,
\end{equation*}
where $\mathbf{z}\sim\mathrm{N}(\mathbf{0},\mathbf{I})$. As in the proof of Lemma~\ref{lemma:prob1}, it holds
\begin{equation*}
\lambda_{\max}\left\{\mathbf{V}(\boldsymbol{\gamma}^0)\right\}=\max_{i=1,\dots,m}\;\lambda_{\max}\left\{\mathbf{V}_i(\boldsymbol{\gamma}^0)\right\}\leq1+\bar{\gamma}s.
\end{equation*}
Since $\mathbf{z}$ has standard normal components, a Laurent-Massart $\chi^2$ tail bound \citep{Laurent2000} gives
\begin{equation*}
\Pr\left[\|\mathbf{z}\|_2^2\geq n+2\sqrt{nt}+2t\right]\leq\exp(-t).
\end{equation*}
Substituting $t=\log(1/\delta)$ and taking square roots gives
\begin{equation*}
\Pr\left[\|\mathbf{z}\|_2\geq\sqrt{n+2\sqrt{n\log\left(\frac{1}{\delta}\right)}+2\log\left(\frac{1}{\delta}\right)}\right]\leq\delta
\end{equation*}
and hence it holds with probability at least $1-\delta$ that
\begin{equation*}
\|\mathbf{y}\|_2\leq \bar{\beta}s+g(\delta),
\end{equation*}
where
\begin{equation*}
g(\delta)=\sigma\sqrt{1+\bar{\gamma}s}\sqrt{n+2\sqrt{n\log\left(\frac{1}{\delta}\right)}+2\log\left(\frac{1}{\delta}\right)}.
\end{equation*}
Substituting the above result into the gradient bounds and taking the maximum yields
\begin{equation*}
L_\mathcal{A}(\mathbf{y})\leq\sqrt{2s}\max\left(\frac{2}{\sigma^2}\{2\bar{\beta}s+g(\delta)\},1+\frac{1}{\sigma^2}\{2\bar{\beta}s+g(\delta)\}^2\right)=L(\delta)
\end{equation*}
with probability at least $1-\delta$. Finally, since $L(\delta)$ does not depend on $\mathcal{A}$ it holds
\begin{equation*}
\Pr\left[\max_{\mathcal{A}\in\mathcal{S}_s}\;L_\mathcal{A}(\mathbf{y})\leq L(\delta)\right]\geq1-\delta.
\end{equation*}
\end{proof}

\begin{lemma}
\label{lemma:lipschitz3}
Let $\mathcal{S}_s$ denote the collection of all sets $\mathcal{A}\subseteq\{1,\dots,p\}$ with cardinality $|\mathcal{A}|\leq s$. Fix any $\mathcal{A}\in\mathcal{S}_s$. Define the constraint set
\begin{equation*}
\mathcal{B}(\mathcal{A}):=\left\{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathbb{R}^p\times\mathbb{R}_+^p:\|\boldsymbol{\beta}\|_\infty\leq\bar{\beta},\|\boldsymbol{\gamma}\|_\infty\leq\bar{\gamma},\operatorname{Supp}(\boldsymbol{\gamma})\subseteq\operatorname{Supp}(\boldsymbol{\beta})\subseteq\mathcal{A}\right\}
\end{equation*}
and its convex hull
\begin{equation*}
\tilde{\mathcal{B}}(\mathcal{A}):=\left\{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathbb{R}^p\times\mathbb{R}_+^p:\|\boldsymbol{\beta}\|_\infty\leq\bar{\beta},\|\boldsymbol{\gamma}\|_\infty\leq\bar{\gamma},\operatorname{Supp}(\boldsymbol{\gamma})\subseteq\mathcal{A},\operatorname{Supp}(\boldsymbol{\beta})\subseteq\mathcal{A}\right\}.
\end{equation*}
Define the quantity
\begin{equation*}
L_\mathcal{A}:=\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\tilde{\mathcal{B}}(\mathcal{A})}\;\|\nabla_{\beta_\mathcal{A},\gamma_\mathcal{A}}\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]\|_2.
\end{equation*}
Then $L_\mathcal{A}<\infty$ and $E[l(\boldsymbol{\beta},\boldsymbol{\gamma})]$ is Lipschitz continuous on $\mathcal{B}(\mathcal{A})$, i.e., it holds
\begin{equation*}
|E[l(\boldsymbol{\beta},\boldsymbol{\gamma})]-E[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')]|\leq L_\mathcal{A}\sqrt{\|\boldsymbol{\beta}-\boldsymbol{\beta}'\|_2^2+\|\boldsymbol{\gamma}-\boldsymbol{\gamma}'\|_2^2}
\end{equation*}
for any $(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{B}(\mathcal{A})$ and $(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{B}(\mathcal{A})$. Moreover, it holds
\begin{equation*}
\max_{\mathcal{A}\in\mathcal{S}_s}\;L_\mathcal{A}\leq L:=\sqrt{2s}\max\left(\frac{8}{\sigma^2}\bar{\beta}s,2+\frac{16}{\sigma^2}\bar{\beta}^2s^2+\bar{\gamma}s\right).
\end{equation*}
\end{lemma}

\begin{proof}
We start by establishing the first claim of the lemma that the expectation of $l$ is Lipschitz with constant $L_\mathcal{A}$. Towards that end, we consider the components of $\nabla_{\beta_\mathcal{A},\gamma_\mathcal{A}}\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]$. First, rewrite $\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]=\operatorname{E}[l_1(\boldsymbol{\gamma})]+\operatorname{E}[l_2(\boldsymbol{\beta},\boldsymbol{\gamma})]$, where
\begin{equation*}
\operatorname{E}[l_1(\boldsymbol{\gamma})]=\operatorname{E}\left[\sum_{i=1}^m\log\det\{\sigma^2\mathbf{V}_i(\boldsymbol{\gamma})\}\right]=\sum_{i=1}^m\log\det\{\sigma^2\mathbf{V}_i(\boldsymbol{\gamma})\}
\end{equation*}
and
\begin{equation*}
\begin{split}
\operatorname{E}[l_2(\boldsymbol{\beta},\boldsymbol{\gamma})]&=\operatorname{E}\left[\frac{1}{\sigma^2}\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right] \\
&=\frac{1}{\sigma^2}\sum_{i=1}^m\left[(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{X}_i\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})+\sigma^2\operatorname{tr}\left\{\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\right\}\right].
\end{split}
\end{equation*}
For the expectation of $l_1$, some standard calculations give the components of the gradient with respect to $\boldsymbol{\gamma}$ as
\begin{equation*}
\nabla_{\gamma_k}\operatorname{E}[l_1(\boldsymbol{\gamma})]=\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}.
\end{equation*}
Similarly, for the expectation of $l_2$, the components of the gradient with respect to $\boldsymbol{\beta}$ and $\boldsymbol{\gamma}$ are respectively given as
\begin{equation*}
\nabla_{\beta_k}\operatorname{E}[l_2(\boldsymbol{\beta},\boldsymbol{\gamma})]=-\frac{1}{\sigma^2}\sum_{i=1}^m2\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})
\end{equation*}
and
\begin{equation*}
\nabla_{\gamma_k}\operatorname{E}[l_2(\boldsymbol{\beta},\boldsymbol{\gamma})]=-\frac{1}{\sigma^2}\sum_{i=1}^m\left\{\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})\right\}^2-\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}.
\end{equation*}
The above three gradients are continuous and $\tilde{\mathcal{B}}(\mathcal{A})$ is compact. Thus, the gradient norm $\|\nabla_{\beta_\mathcal{A},\gamma_\mathcal{A}}\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]\|_2$ attains a maximum and so it holds
\begin{equation*}
L_\mathcal{A}=\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\tilde{\mathcal{B}}(\mathcal{A})}\;\|\nabla_{\beta_\mathcal{A},\gamma_\mathcal{A}}\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]\|_2<\infty.
\end{equation*}
Furthermore, since $\tilde{\mathcal{B}}(\mathcal{A})$ is convex, we can apply the mean value theorem to get
\begin{equation*}
|\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]-\operatorname{E}[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')]|\leq L_\mathcal{A}\sqrt{\|\boldsymbol{\beta}-\boldsymbol{\beta}'\|_2^2+\|\boldsymbol{\gamma}-\boldsymbol{\gamma}'\|_2^2}
\end{equation*}
for any $\boldsymbol{\beta}'\neq\boldsymbol{\beta}$ and any $\boldsymbol{\gamma}'\neq\boldsymbol{\gamma}$ in $\tilde{\mathcal{B}}(\mathcal{A})$. Moreover, because $\mathcal{B}(\mathcal{A})\subseteq\tilde{\mathcal{B}}(\mathcal{A})$, the above inequality also holds for any $\boldsymbol{\beta}'\neq\boldsymbol{\beta}$ and any $\boldsymbol{\gamma}'\neq\boldsymbol{\gamma}$ in $\mathcal{B}(\mathcal{A})$, thereby proving the first claim of the lemma that $\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]$ is $L_\mathcal{A}$ Lipschitz on $\mathcal{B}(\mathcal{A})$. To prove the second claim of the lemma, we bound the components of $L_\mathcal{A}$. See that 
\begin{equation*}
|\nabla_{\gamma_k}\operatorname{E}[l_1(\boldsymbol{\gamma})]|=\left|\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}\right|\leq\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2\|\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\|_2\leq\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2=1.
\end{equation*}
Next, observe that
\begin{equation*}
\begin{split}
|\nabla_{\beta_k}\operatorname{E}[l_2(\boldsymbol{\beta},\boldsymbol{\gamma})]|&=\left|-\frac{1}{\sigma^2}\sum_{i=1}^m2\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})\right| \\
&\leq\frac{1}{\sigma^2}\sum_{i=1}^m2\|\mathbf{x}_{ik}\|_2\|\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})\|_2 \\
&\leq\frac{2}{\sigma^2}\sqrt{\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2}\sqrt{\sum_{i=1}^m\|\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})\|_2^2} \\
&=\frac{2}{\sigma^2}\|\mathbf{X}(\boldsymbol{\beta}^0-\boldsymbol{\beta})\|_2 \\
&\leq\frac{8}{\sigma^2}\bar{\beta}s,
\end{split}
\end{equation*}
where we employ the same tricks used in the previous lemma. Finally, see that
\begin{equation*}
\begin{split}
|\nabla_{\gamma_k}\operatorname{E}[l_2(\boldsymbol{\beta},\boldsymbol{\gamma})]|&=\left|-\frac{1}{\sigma^2}\sum_{i=1}^m\left\{\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})\right\}^2\right. \\
&\hspace{2in}\left.-\sum_{i=1}^m\mathbf{x}_{ik}^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{x}_{ik}\right| \\
&\leq\frac{1}{\sigma^2}\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2\|\mathbf{X}_i(\boldsymbol{\beta}^0-\boldsymbol{\beta})\|_2^2+\sum_{i=1}^m\|\mathbf{x}_{ik}\|_2^2\|\mathbf{V}_i(\boldsymbol{\gamma}^0)\|_2 \\
&\leq\frac{1}{\sigma^2}\|\mathbf{X}(\boldsymbol{\beta}^0-\boldsymbol{\beta})\|_2^2+1+\bar{\gamma}s \\
&\leq\frac{16}{\sigma^2}\bar{\beta}^2s^2+1+\bar{\gamma}s.
\end{split}
\end{equation*}
Taking the maximum over the gradient bounds yields
\begin{equation*}
L_\mathcal{A}\leq\sqrt{2s}\max\left(\frac{8}{\sigma^2}\bar{\beta}s,2+\frac{16}{\sigma^2}\bar{\beta}^2s^2+\bar{\gamma}s\right)=L,
\end{equation*}
and, since $L$ does not depend on $\mathcal{A}$, it holds
\begin{equation*}
\max_{\mathcal{A}\in\mathcal{S}_s}\;L_\mathcal{A}\leq L.
\end{equation*}
\end{proof}

\subsection{Proof of Main Result}

Since $(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})$ minimizes the negative log-likelihood, we necessarily have
\begin{equation*}
l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})-l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)\leq0.
\end{equation*}
Subtracting and adding $\operatorname{E}[l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})]$ and $\operatorname{E}[l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)]$ on the left-hand side gives
\begin{equation*}
l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})-\operatorname{E}[l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})]+\operatorname{E}[l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})]-\operatorname{E}[l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)]+\operatorname{E}[l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)]-l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)\leq0.
\end{equation*}
Now, isolating $\operatorname{E}[l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})]-\operatorname{E}[l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)]$ on the left-hand side gives the upper bound
\begin{equation}
\label{eq:bound1}
\begin{split}
\operatorname{E}[l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})]-\operatorname{E}[l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)]&\leq\operatorname{E}[l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})]-l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})+l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)-\operatorname{E}[l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)] \\
&\leq\left|\operatorname{E}[l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})]-l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})\right|+\left|l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)-\operatorname{E}[l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)]\right| \\
&\leq2\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{C}(s)}\;\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]\right|.
\end{split}
\end{equation}
We now seek a high-probability upper bound for the supremum on the right-hand side. Towards this end, consider the difference inside the supremum, given by
\begin{equation*}
\begin{split}
&l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]=\sum_{i=1}^m\log\det\{\sigma^2\mathbf{V}_i(\boldsymbol{\gamma})\}+\frac{1}{\sigma^2}\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}) \\
&\hspace{1.2in}-\operatorname{E}\left[\sum_{i=1}^m\log\det\{\sigma^2\mathbf{V}_i(\boldsymbol{\gamma})\}+\frac{1}{\sigma^2}\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right].
\end{split}
\end{equation*}
Since the log determinant terms do not depend on $\boldsymbol{\nu}_i$, which is the only source of randomness, we can simplify the above expression to
\begin{equation*}
\begin{split}
l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]&=\frac{1}{\sigma^2}\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta}) \\
&\hspace{1in}-\operatorname{E}\left[\frac{1}{\sigma^2}\sum_{i=1}^m(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})(\mathbf{y}_i-\mathbf{X}_i\boldsymbol{\beta})\right].
\end{split}
\end{equation*}
Expanding the quadratic terms and evaluating the expectations yields
\begin{equation*}
\begin{split}
l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]&=\frac{1}{\sigma^2}\sum_{i=1}^m\left[\boldsymbol{\nu}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i-\sigma^2\operatorname{tr}\left\{\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\right\}\right] \\
&\hspace{1.5in}+\frac{1}{\sigma^2}\sum_{i=1}^m2(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{X}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i.
\end{split}
\end{equation*}
For the first term on the right-hand side, Lemma~\ref{lemma:prob1} gives the probabilistic upper bound
\begin{equation*}
\begin{split}
&\Pr\left[\left|\frac{1}{\sigma^2}\sum_{i=1}^m\left[\boldsymbol{\nu}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i-\sigma^2\operatorname{tr}\left\{\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\mathbf{V}_i(\boldsymbol{\gamma}^0)\right\}\right]\right|\geq t\right] \\
&\hspace{2.5in}\leq2\exp\left\{-c\min\left(\frac{t^2}{n(1+\bar{\gamma}s)^2},\frac{t}{1+\bar{\gamma}s}\right)\right\},
\end{split}
\end{equation*}
where $c>0$ is a universal constant and $t>0$. Similarly, for the second term, Lemma~\ref{lemma:prob2} gives the probabilistic upper bound
\begin{equation*}
\Pr\left[\left|\frac{1}{\sigma^2}\sum_{i=1}^m2(\boldsymbol{\beta}^0-\boldsymbol{\beta})^\top\mathbf{X}_i^\top\mathbf{V}_i^{-1}(\boldsymbol{\gamma})\boldsymbol{\nu}_i\right|\geq t\right]\leq2\exp\left(-\frac{t^2}{128\sigma^{-2}(1+\bar{\gamma}s)s^2\bar{\beta}^2}\right).
\end{equation*}
These bounds hold for a single fixed $(\boldsymbol{\beta},\boldsymbol{\gamma})$. We now extend them to hold uniformly over $\mathcal{C}(s)$ via an $\epsilon$-net argument. Towards this end, define the set $\mathcal{B}(\mathcal{A})$ as
\begin{equation*}
\mathcal{B}(\mathcal{A}):=\left\{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathbb{R}^p\times\mathbb{R}_+^p:\|\boldsymbol{\beta}\|_\infty\leq\bar{\beta},\|\boldsymbol{\gamma}\|_\infty\leq\bar{\gamma},\operatorname{Supp}(\boldsymbol{\gamma})\subseteq\operatorname{Supp}(\boldsymbol{\beta})\subseteq\mathcal{A}\right\}.
\end{equation*}
Then, letting $\mathcal{S}_s$ be set of all possible active sets $\mathcal{A}$ of size at most $s$, we have
\begin{equation*}
\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{C}(s)}\;\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}\left[l(\boldsymbol{\beta},\boldsymbol{\gamma})\right]\right|=\max_{\mathcal{A}\in\mathcal{S}_s}\;\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{B}(\mathcal{A})}\;\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}\left[l(\boldsymbol{\beta},\boldsymbol{\gamma})\right]\right|.
\end{equation*}
Next, we require a useful inequality. For any $\boldsymbol{\beta}'\neq\boldsymbol{\beta}$ and any $\boldsymbol{\gamma}'\neq\boldsymbol{\gamma}$ in $\mathcal{B}(\mathcal{A})$ it holds
\begin{equation*}
\begin{split}
&\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}\left[l(\boldsymbol{\beta},\boldsymbol{\gamma})\right]\right| \\
&\hspace{0.5in}=\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-l(\boldsymbol{\beta}',\boldsymbol{\gamma}')+l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]+\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]-\operatorname{E}\left[l(\boldsymbol{\beta},\boldsymbol{\gamma})\right]\right| \\
&\hspace{0.5in}\leq\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|+\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right|+\left|\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]-\operatorname{E}\left[l(\boldsymbol{\beta},\boldsymbol{\gamma})\right]\right| \\
&\hspace{0.5in}\leq\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|+(L_\mathcal{A}(\mathbf{y})+L_\mathcal{A})\sqrt{\|\boldsymbol{\beta}-\boldsymbol{\beta}'\|_2^2+\|\boldsymbol{\gamma}-\boldsymbol{\gamma}'\|_2^2},
\end{split}
\end{equation*}
where the last inequality follows from the first results of Lemmas~\ref{lemma:lipschitz2} and \ref{lemma:lipschitz3}, which give that $l(\boldsymbol{\beta},\boldsymbol{\gamma})$ and $\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]$ are Lipschitz on $\mathcal{B}(\mathcal{A})$ with constants $L_\mathcal{A}(\mathbf{y})$ (a random quantity) and $L_\mathcal{A}$ (a fixed quantity), respectively. Now, let $\mathcal{E}(\mathcal{A})$ be an $\epsilon$-net of $\mathcal{B}(\mathcal{A})$ such that for any $(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{B}(\mathcal{A})$ there exists a $(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{E}(\mathcal{A})$ with $\sqrt{\|\boldsymbol{\beta}-\boldsymbol{\beta}'\|_2^2+\|\boldsymbol{\gamma}-\boldsymbol{\gamma}'\|_2^2}\leq\epsilon$. We then have
\begin{equation*}
(L_\mathcal{A}(\mathbf{y})+L_\mathcal{A})\sqrt{\|\boldsymbol{\beta}-\boldsymbol{\beta}'\|_2^2+\|\boldsymbol{\gamma}-\boldsymbol{\gamma}'\|_2^2}\leq(L_\mathcal{A}(\mathbf{y})+L_\mathcal{A})\epsilon\leq2\max(L_\mathcal{A}(\mathbf{y}),L_\mathcal{A})\epsilon,
\end{equation*}
from which it follows
\begin{equation*}
\begin{split}
&\max_{\mathcal{A}\in\mathcal{S}_s}\;\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{B}(\mathcal{A})}\;\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}\left[l(\boldsymbol{\beta},\boldsymbol{\gamma})\right]\right| \\
&\hspace{1in}\leq\max_{\mathcal{A}\in\mathcal{S}_s}\;\max_{(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{E}(\mathcal{A})}\;\left(\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|+2\max(L_\mathcal{A}(\mathbf{y}),L_\mathcal{A})\epsilon\right).
\end{split}
\end{equation*}
Invoking the second result of Lemma~\ref{lemma:lipschitz2} gives the high-probability bound
\begin{equation}
\label{eq:lipschitzprob}
\Pr\left[\max_{\mathcal{A}\in\mathcal{S}_s}\;L_\mathcal{A}(\mathbf{y})\leq L(\delta_1)\right]\geq1-\delta_1
\end{equation}
for $\delta_1\in(0,1]$. Similarly, by the second result of Lemma~\ref{lemma:lipschitz3}, we have the deterministic bound
\begin{equation*}
\max_{\mathcal{A}\in\mathcal{S}_s}\;L_\mathcal{A}\leq L.
\end{equation*}
Both $L(\delta_1)$ and $L$ are deterministic quantities. Define $L^\star(\delta_1)$ to be
\begin{equation*}
L^\star(\delta_1):=\max(L(\delta_1),L).
\end{equation*}
Then, with probability $1-\delta_1$, it holds
\begin{equation*}
\begin{split}
&\max_{\mathcal{A}\in\mathcal{S}_s}\;\max_{(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{E}(\mathcal{A})}\;\left(\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|+2\max(L_\mathcal{A}(\mathbf{y}),L_\mathcal{A})\epsilon\right) \\
&\hspace{1in}\leq\max_{\mathcal{A}\in\mathcal{S}_s}\;\max_{(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{E}(\mathcal{A})}\;\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|+2L^\star(\delta_1)\epsilon.
\end{split}
\end{equation*}
In what follows, every inequality that contains $L^\star(\delta_1)$ is stated on the event in \eqref{eq:lipschitzprob}. We now have
\begin{equation*}
\begin{split}
&\Pr\left[\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{C}(s)}\;\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}\left[l(\boldsymbol{\beta},\boldsymbol{\gamma})\right]\right|\geq t\right] \\
&\hspace{1in}\leq\Pr\left[\max_{\mathcal{A}\in\mathcal{S}_s}\;\max_{(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{E}(\mathcal{A})}\;\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|+2L^\star(\delta_1)\epsilon\geq t\right].
\end{split}
\end{equation*}
Setting $\epsilon=t/[4L^\star(\delta_1)]$ and applying a union bound on the right-hand side gives
\begin{equation*}
\begin{split}
&\Pr\left[\max_{\mathcal{A}\in\mathcal{S}_s}\;\max_{(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{E}(\mathcal{A})}\;\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|\geq\frac{1}{2}t\right] \\
&\hspace{2in}\leq\sum_{\mathcal{A}\in\mathcal{S}_s}\sum_{(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{E}(\mathcal{A})}\Pr\left[\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|\geq\frac{1}{2}t\right].
\end{split}
\end{equation*}
A standard binomial coefficient bound \citep[see, e.g.,][Section 1.2.6, Exercise 67]{Knuth1997} gives
\begin{equation*}
|\mathcal{S}_s|=\binom{p}{s}\leq\left(\frac{ep}{s}\right)^s.
\end{equation*}
Next, since $\|\boldsymbol{\beta}'\|_2\leq\sqrt{s}\bar{\beta}$ and $\|\boldsymbol{\gamma}'\|_2\leq\sqrt{s}\bar{\gamma}$, a standard $\ell_2$ norm $\epsilon$-net cardinality bound \citep[see, e.g.,][Corollary 4.2.13]{Vershynin2018} gives
\begin{equation*}
|\mathcal{E}(\mathcal{A})|\leq\left(1+\frac{2\sqrt{s}\bar{\beta}}{\epsilon}\right)^s\left(1+\frac{2\sqrt{s}\bar{\gamma}}{\epsilon}\right)^s\leq\exp\left(2s\sqrt{s}\frac{\bar{\beta}+\bar{\gamma}}{\epsilon}\right)=\exp\left(8L^\star(\delta_1)s\sqrt{s}\frac{\bar{\beta}+\bar{\gamma}}{t}\right).
\end{equation*}
It now follows that
\begin{equation}
\label{eq:probbound}
\begin{split}
&\sum_{\mathcal{A}\in\mathcal{S}_s}\sum_{(\boldsymbol{\beta}',\boldsymbol{\gamma}')\in\mathcal{E}(\mathcal{A})}\Pr\left[\left|l(\boldsymbol{\beta}',\boldsymbol{\gamma}')-\operatorname{E}\left[l(\boldsymbol{\beta}',\boldsymbol{\gamma}')\right]\right|\geq\frac{1}{2}t\right]\leq\left(\frac{ep}{s}\right)^s\exp\left(8L^\star(\delta_1)s\sqrt{s}\frac{\bar{\beta}+\bar{\gamma}}{t}\right) \\
&\hspace{0.1in}\times2\left[\exp\left\{-c\min\left(\frac{t^2}{4n(1+\bar{\gamma}s)^2},\frac{t}{2(1+\bar{\gamma}s)}\right)\right\}+\exp\left(-\frac{t^2}{512\sigma^{-2}(1+\bar{\gamma}s)s^2\bar{\beta}^2}\right)\right].
\end{split}
\end{equation}
We wish to bound the right-hand side by a user chosen $\delta_2\in(0,1]$. To this end, we solve for a $t$ that simultaneously satisfies
\begin{equation}
\label{eq:t1}
2\left(\frac{ep}{s}\right)^s\exp\left(8L^\star(\delta_1)s\sqrt{s}\frac{\bar{\beta}+\bar{\gamma}}{t}\right)\exp\left\{-c\min\left(\frac{t^2}{4n(1+\bar{\gamma}s)^2},\frac{t}{2(1+\bar{\gamma}s)}\right)\right\}\leq\frac{\delta_2}{2}
\end{equation}
and
\begin{equation}
\label{eq:t2}
2\left(\frac{ep}{s}\right)^s\exp\left(8L^\star(\delta_1)s\sqrt{s}\frac{\bar{\beta}+\bar{\gamma}}{t}\right)\exp\left(-\frac{t^2}{512\sigma^{-2}(1+\bar{\gamma}s)s^2\bar{\beta}^2}\right)\leq\frac{\delta_2}{2}.
\end{equation}
Some routine algebra shows that \eqref{eq:t1} is satisfied whenever
\begin{equation*}
t\geq t_1=(1+\bar{\gamma}s)\max\left(\sqrt{\frac{4n}{c}\Pi},\frac{2}{c}\Pi\right),
\end{equation*}
where
\begin{equation*}
\Pi=s\log\left(\frac{ep}{s}\right)+8L^\star(\delta_1)s\sqrt{s}(\bar{\beta}+\bar{\gamma})+\log\left(\frac{4}{\delta_2}\right).
\end{equation*}
The above holds provided $t\geq1$, which is true for our final choice of $t$. Similarly, some standard derivations give that \eqref{eq:t2} is satisfied if
\begin{equation*}
\begin{split}
t\geq t_2&=\sqrt{512\sigma^{-2}(1+\bar{\gamma}s)s^2\bar{\beta}^2\Pi} \\
&=\frac{s\bar{\beta}}{\sigma}\sqrt{512(1+\bar{\gamma}s)\Pi}.
\end{split}
\end{equation*}
Hence, \eqref{eq:probbound} is guaranteed less than $\delta_2$ provided
\begin{equation*}
t\geq t_0=\max(t_1,t_2).
\end{equation*}
Now, setting $\delta_1=\delta/2$ and $\delta_2=\delta/2$, it follows from the previous inequalities that
\begin{equation}
\label{eq:bound2}
2\sup_{(\boldsymbol{\beta},\boldsymbol{\gamma})\in\mathcal{C}(s)}\;\left|l(\boldsymbol{\beta},\boldsymbol{\gamma})-\operatorname{E}[l(\boldsymbol{\beta},\boldsymbol{\gamma})]\right|\leq 2t_0
\end{equation}
with probability at least $1-\delta$. Finally, by the definition of KL divergence, we have
\begin{equation*}
\begin{split}
2\operatorname{KL}\left[\mathrm{N}\left(\mathbf{X}\boldsymbol{\beta}^0,\sigma^2\mathbf{V}(\boldsymbol{\gamma}^0)\right)\parallel\mathrm{N}\left(\mathbf{X}\hat{\boldsymbol{\beta}},\sigma^2\mathbf{V}(\hat{\boldsymbol{\gamma}})\right)\right]&=\operatorname{E}[-l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)]-\operatorname{E}[-l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})] \\
&=\operatorname{E}[l(\hat{\boldsymbol{\beta}},\hat{\boldsymbol{\gamma}})]-\operatorname{E}[l(\boldsymbol{\beta}^0,\boldsymbol{\gamma}^0)],
\end{split}
\end{equation*}
from which we can combine \eqref{eq:bound1} and \eqref{eq:bound2} to complete the proof.

\section{Implementation Details}
\label{app:implementation}

The configuration of each method is as follows.
\begin{itemize}
\item \texttt{glmmsel} is configured with a sequence of 100 values of $\lambda$ chosen using Proposition~\ref{prop:lambda}, where the first $\lambda$ sets all coefficients to zero. For each value of $\lambda$, we use a sequence of 10 values of $\alpha$ equispaced between $0.1$ and $1$.
\item \texttt{L0Learn} is configured with the $\ell_0$ regularizer and a sequence of 100 values of $\lambda$ chosen using the default method of the package.
\item \texttt{glmnet} is configured with the relaxed $\ell_1$ regularizer and a sequence of 100 values of $\lambda$ chosen using the default method of the package. The relaxation parameter $\gamma=0$.
\item \texttt{pysr3} is configured with the $\ell_0$ regularizer and a grid of $11\times 11$ values of $(k_1,k_2)$ equispaced between $0$ and $10$, where $k_1$ and $k_2$ are the maximum allowable number of nonzeros in the fixed effects and random effects, respectively.
\item \texttt{glmmPen} is configured with the minimax concave penalty and a grid of $10\times 10$ values of $(\lambda_1,\lambda_2)$ chosen using the default method of the package, where $\lambda_1$ and $\lambda_2$ are the penalty parameters for the fixed effects and random effects, respectively. The concavity parameter $\gamma=3$.
\item \texttt{rpql} is configured with the minimax concave penalty and a grid of $30\times 30$ values of $(\lambda_1,\lambda_2)$ chosen using the default method of \texttt{glmmPen}, where $\lambda_1$ and $\lambda_2$ are the penalty parameters for the fixed effects and random effects, respectively. The package uses \texttt{glmmPen}'s grid construction method as it does not provide a method for computing the $\lambda$ sequence. The concavity parameter $\gamma=3$.
\end{itemize}
We remark that \texttt{glmmPen} uses only 10 values each of $\lambda_1$ and $\lambda_2$ because its runtime is significantly longer than the other methods. However, it only runs in the $p=10$ setting where \texttt{glmmsel} also uses at most 10 values of $\lambda$. Indeed, by Proposition~\ref{prop:lambda}, the number of active predictors changes between consecutive values of $\lambda$, and hence there can be at most 10 values when $p=10$.

\section{High-Correlation Experiments}
\label{app:high}

Here, we set the correlation level to $\rho=0.9$ and compare Algorithm~\ref{alg:cd} (coordinate descent) and Algorithm~\ref{alg:ls} (coordinate descent with local search) of \texttt{glmmsel}. We also include the previous baselines for reference and run \texttt{L0Learn} with its CDPSI algorithm, which can handle high correlations similar to our local search routine. Figure~\ref{fig:gaussian-high-corr-1000} presents the results.
\begin{figure}[t]
\centering
\input{Figures/gaussian-high-corr-1000.tex}
\caption{Comparisons on synthetic data with Gaussian response. The number of predictors $p=1,000$ and the correlation level $\rho=0.9$. The averages (points) and standard errors (error bars) are measured over 100 datasets. In the upper right panel, the dashed horizontal line indicates the true number of predictors with nonzero effects.}
