\subsection{Meyer-Neldel Rule}

Returning to the third-order Taylor expansion of the specific free energy around temperature (\(\theta = T- T_0\)) and strain (\(V_{ab}\)) within Schoeck's formalism in  Ref.\cite{schoeck1980entropy} we have:
\begin{equation}
\begin{split}
   f = & f_{0} + f_{T} \theta + f_{ik} V_{ik} + \frac{1}{2} f_{T,T} \theta^{2} + f_{T,ik} \theta V_{ik} + \frac{1}{2} f_{ik,lm} V_{ik} V_{lm} + \frac{1}{6} f_{T,T,T} \theta^{3}\\
   & + \frac{1}{2} f_{T,T,ik} \theta^{2} V_{ik} + \frac{1}{2} f_{T,ik,lm} \theta V_{ik} V_{lm} + \frac{1}{6} f_{ik,lm,pq} V_{ik} V_{lm} V_{pq}
\end{split}
\label{eq:helmholtz}
\end{equation}

From Maxwell relations we know that at constant temperature, the specific enthalpy can be written as:

\begin{equation}
    \Delta h = \Delta f + T \Delta s + \Delta e_p + \Delta e_{el} + \Delta e_{SF}
    \label{eqb2}
\end{equation}
%\begin{equation}
%    \Delta u = [f+Ts]_{T,V} - [f+Ts]_{T,0} = \Delta f + T \Delta s
%    \label{eqb2}
%\end{equation}
where \(\Delta s = -f_{T,ik} V_{ik} - \frac{1}{2} f_{T,ik,lm} V_{ik} V_{lm}\), \(\Delta e_p = \tau_s : ( \vec{b} \otimes \vec{n} ) \rho D\) is the plastic work per unit volume done by the dislocations from the initial configuration to the saddle point, $\rho$ the dislocation density and D its displacement, \(\Delta e_{el} =   \tilde{\tau}_s \tilde{\epsilon}_s - \tilde{\tau}_i \tilde{\epsilon}_i \) is the elastic energy density as a function of stress and strain at saddle and initial states \cite{NAHAVANDIAN2024112954}, and \(\Delta e_{SF}\) is the change in stacking fault energy density between initial and saddle point configurations. In the processes studied here, the last two terms are negligible compared to the plastic energy term. Based on the Meyer-Neldel (MN) compensation rule \cite{meyer1937relation}, we can define \(T_{MN}\) to relate the activation entropy and the activation enthalpy at $T=T_0$:

\begin{equation}
    T_{MN} = \frac{\Delta H}{\Delta S} = \frac{\Delta F}{\Delta S} + T_0 + \frac{\Delta E_p}{\Delta S} =  \frac{T_0 \Delta S + \Delta F +\Delta E_p}{\Delta S}
    \label{eqb3}
\end{equation}

For $\theta \approx 0$ and substituting $\Delta F$ integrating Eq.~\ref{eq:helmholtz} and $\Delta S$ from Eq.~\ref{eq:Schoeck}, we obtain:

\begin{equation}
\begin{split}
  T_{MN} =   \frac{ \int_{\Omega}(-T_0f_{T,ik} V_{ik} - \frac{1}{2} T_0 f_{T,ik,lm} V_{ik} V_{lm} + f_{ik} V_{ik} + \frac{1}{2} f_{ik,lm} V_{ik} V_{lm} + \frac{1}{6} f_{ik,lm,pq} V_{ik} V_{lm} V_{pq} + \Delta e_p)d\Omega}{\int_{\Omega}(-f_{T,ik} V_{ik} - \frac{1}{2} f_{T,ik,lm} V_{ik} V_{lm})d\Omega} 
\end{split}
\label{eqb4}
\end{equation}
Considering the unstressed condition as the reference configuration leads to $f_{ik}=0$. Moreover, following Schoeck, we know \(f_{T,ik} = -f_{ik,lm} \alpha_{lm}\). Further, for cubic materials \(f_{ik,lm} \alpha_{lm} = \alpha_V K \delta _{lm}\) (Eq.(4) in Ref.\cite{schoeck1980entropy}), where $K$ is the bulk modulus and $\alpha _V$ the volumetric thermal expansion coefficient, and \(f_{ik,lm} = C_{iklm}\). Hence
\begin{equation}
\begin{split}
  T_{MN} = \frac{\int_{\Omega}(\alpha_V T_0 K V_{ii} - \frac{1}{2} T_0\frac{\partial C_{iklm}}{\partial T} V_{ik} V_{lm} + \frac{1}{2} C_{iklm} V_{ik} V_{lm} + \frac{1}{6} \frac{\partial C_{iklm}}{\partial V_{pq}}V_{ik} V_{lm} V_{pq} + \Delta e_p) d\Omega}{\int_{\Omega}(\alpha_V K V_{ii} - \frac{1}{2} \frac{\partial C_{iklm}}{\partial T} V_{ik} V_{lm})  d\Omega}
\end{split}
\label{eqb6}
\end{equation}


%%%%%%%%%%%%%%%%%%%%%
\begin{equation}
\left\{
\begin{array}{ll}
   \text{a)}\quad  \alpha_V \to 0: & T_{MN} \approx \frac{\int_{\Omega}( - \frac{1}{2} T_0\frac{\partial C_{iklm}}{\partial T} V_{ik} V_{lm} + \frac{1}{2} C_{iklm} V_{ik} V_{lm} + \frac{1}{6} \frac{\partial C_{iklm}}{\partial V_{pq}}V_{ik} V_{lm} V_{pq} + \Delta e_p) d\Omega}{\int_{\Omega}( - \frac{1}{2} \frac{\partial C_{iklm}}{\partial T} V_{ik} V_{lm})  d\Omega} \\\\[10pt]
   \text{b)}\quad \frac{\partial C_{iklm}}{\partial T} \to 0: & T_{MN} \approx \frac{\int_{\Omega}(\alpha_V T_0 K V_{ii}  + \frac{1}{2} C_{iklm} V_{ik} V_{lm} + \frac{1}{6} \frac{\partial C_{iklm}}{\partial V_{pq}}V_{ik} V_{lm} V_{pq} + \Delta e_p) d\Omega}{\int_{\Omega}(\alpha_V K V_{ii} )  d\Omega} \\\\[10pt]
