\section{Proofs}

\subsection{Lemma \ref{lem:QQ}}

\begin{proof}
    First, note that by Assumption \ref{assum:confounding} and \ref{assum:pos_U}, Assumption \ref{assum:db} implies
    \[\gamma(Y_0^{a = 0}, L)\mid A = 1, L, U \overset{d}{=} Y_1^{a=0} \mid A = 1, L, U.\]
    and 
    \[\gamma(Y_0^{a = 0}, L)\mid A = 0, L, U \overset{d}{=} Y_1^{a=0} \mid A = 0, L, U.\]
  We then apply the theory of optimal transport. By the Brenier-McCann's Theorem \citep{brenier1991polar, mccann1995existence}, Assumption \ref{assum:cc}, and Assumption \ref{assum:ct}(a), $Q_{Y_{1}\mid A=0, L,U}\circ F_{Y_{0}\mid A=0, L,U}\left( \cdot\right)$ is the unique function $f$ monotone in its first argument such that $f(Y_0^{a = 0}, L, U)\mid A = 0, L,U \dequiv  Y_1^{a=0} \mid A = 0,L,U \text{ almost surely.}$ Then, the existence condition by Assumption \ref{assum:db} implies $Q_{Y_{1}\mid A=0, L,U}\circ F_{Y_{0}\mid A=0, L,U}\left( \cdot\right)$ is $\gamma$ and thus 
  does not depend on $U$, almost surely.
\end{proof}

\subsection{Remark \ref{rmk:pt}}

\begin{proof}
    {(I)} We begin by showing that Assumption~\ref{assum:db} implies Equation~\eqref{eq:nlpt}. The argument closely follows the proof of Theorem~\ref{thm:idett}, with minor modifications.
    \begin{equation*}
    \begin{aligned}
        F_{Y_0^{a=0}\mid A = a, L = l}(y) 
        &= \Prob(Y_0^{a = 0} \le y \mid  A = a, L = l)\\
        & \text{(by Assumption \ref{assum:pos_U})}\\ 
        &= \int \Prob(Y_0^{a = 0} \le y \mid  A = a, L = l, U = u) \dx{F_{U\mid A = a, L = l}(u)}\\
        & \text{(by Assumption \ref{assum:ct}(b))}\\ 
        &= \int \Prob(\tgamma(Y_0^{a = 0}, l, u) \le \tgamma(y,l,u) \mid  A = a, L = l, U = u) \dx{F_{U\mid A = a, L = l}(u)}\\
        & \text{(by $\tgamma(Y_0^{a=0}, L, U)\mid A = a, L = l, U = u \sim Y_1^{a = 0}\mid A = a, L = l, U = u$)}\\
        &= \int \Prob(Y_1^{a = 0} \le \tgamma(y,l, u) \mid  A = a, L = l, U = u) \dx{F_{U\mid A = a, L = l}(u)}\\
        &= F_{Y_1^{a = 0}\mid A = a, L = l}(\gamma(y,l)).
    \end{aligned}
    \end{equation*}
    Therefore, 
    \[\gamma(y,l) = Q_{Y_1^{a = 0}\mid A = a, L = l} \circ F_{Y_0^{a=0}\mid A = a, L = l}(y),\]
    for both $a = 0, 1$.

    {(II)} Next, we show that Assumption 3.1, together with the accompanying assumptions in \citet{athey2006identification}, implies Equation~\eqref{eq:nlpt}.
    Assumption 3.1 requires
    \[
    Y_{t}^{a=0}=h\left( U,t\right) 
    \]%
    where $h$ is strictly increasing in $U$ for each $t=0,1$.
    Then we have that 
    \begin{eqnarray*}
    F_{Y_{t}^{a=0}|A=a}\left( y\right)  &=&\Pr \left\{ Y_{t}^{a=0}\leq
    y|A=a\right\}  \\
    &=&\Pr \left\{ h\left( U,t\right) \leq y|A=a\right\}  \\
    &=&\Pr \left\{ U\leq h^{-1}\left( y,t\right) |A=a\right\}  \\
    &=&F_{U|A=a}\left( h^{-1}\left( y,t\right) \right) 
    \end{eqnarray*}%
    and 
    \[
    Q_{Y_{t}^{a=0}|A=a}\left( v\right) =h\left( Q_{U|A=a}\left(
    v\right) ,t\right) 
    \]%
    therefore 
    \begin{eqnarray*}
    &&Q_{Y_{t=1}^{a=0}|A=a}\circ F_{Y_{t=0}^{a=0}|A=a}\left( y\right)  \\
    &=&h\left( Q_{U|A=a}\left( F_{U|A=a}\left( h^{-1}\left( y,t=0\right)
    \right) \right) ,t=1\right)  \\
    &=&h\left( h^{-1}\left( y,t=0\right) ,t=1\right) 
    \end{eqnarray*}%
    for both $a = 0, 1$.

    {(III)} Finally, we show that Equation~\eqref{eq:nlpt}, combined with assumptions that do not involve the unmeasured confounder \(U\)—namely, Assumptions~\ref{assum:cc} and~\ref{assum:na}—suffices to identify the ATT, as given in Equation~\eqref{eq:idett} of Theorem~\ref{thm:idett}. To establish this result, we additionally impose the following weaker continuity condition, which also avoids referencing \(U\): we assume that, almost surely, the conditional distribution functions \(F_{Y_{0} \mid A=0, L}(\cdot)\) and \(F_{Y_{1} \mid A=0, L}(\cdot)\) are continuous. Under these conditions, we have:
    \begin{equation*}
        \begin{aligned}
            &\E\left\{ Y_1 - Q_{Y_1 \mid A=0, L} \circ F_{Y_0 \mid A=0, L}(Y_0) \mid A=1 \right\}\\
            & \phantom{=}\text{  (by Assumption \ref{assum:cc} and \ref{assum:na})}\\
            &= \E[Y_1^{a=1} \mid A = 1] - \E\left\{ Q_{Y_1^{a=0} \mid A=0, L} \circ F_{Y_0^{a=0} \mid A=0, L}(Y_0^{a=0}) \mid A=1 \right\}\\
            & \phantom{=}\text{  (by Equation \eqref{eq:nlpt})}\\
            &= \E[Y_1^{a=1} \mid A = 1] - \E\left\{ Q_{Y_1^{a=0} \mid A=1, L} \circ F_{Y_0^{a=0} \mid A=1, L}(Y_0^{a=0}) \mid A=1 \right\}\\
            & \phantom{=}\text{  (by Continuity condition stated above and Law of Iterated Expectation)}\\
            &= \E[Y_1^{a=1} \mid A = 1] - \E\left\{ Y_1^{a=0} \mid A=1 \right\}\\
            &= \E[Y_1^{a=1} - Y_1^{a=0} \mid A = 1] = \theta,
        \end{aligned}
    \end{equation*}
    proving the identification. The analogous results for Corollary~\ref{cor:id_other} and for Assumption 3.1 of \citet{athey2006identification} follow by similar arguments and are omitted for brevity.
\end{proof}

\subsection{Theorem \ref{thm:idett}}

\begin{proof}
  Let ``$\sim$'' denote ``distributed as'', as a shorthand for ``$\overset{d}{=}$''. 
  By the Probability Integral Transform Theorem and Quantile Transform Theorem \citep{angus1994probability}, we have
  \begin{equation*}
    \begin{aligned}
        &Y_1^{a = 0} \mid A = 1, L,U \\
        & \text{  (by Assumptions \ref{assum:confounding} and \ref{assum:pos_U})}\\
        &\sim Y_1^{a = 0} \mid A = 0, L,U \\
        & \text{  (by transform theorems and Assumption \ref{assum:ct0})}\\
        & \sim Q_{Y_1^{a = 0} \mid A = 0, L,U} \circ F_{Y_0^{a = 0} \mid A = 0, L,U} \left( Y_0^{a = 0} \right) \mid A = 0, L,U\\
        & \text{(by Assumptions \ref{assum:confounding} and \ref{assum:na})}\\
        & \sim Q_{Y_1^{a = 0} \mid A = 0, L,U}\circ F_{Y_0^{a = 0} \mid A = 0, L,U} \left( Y_0^{a = 1} \right) \mid A = 1, L,U\\
        & \text{(by Assumption \ref{assum:cc})}\\
        & \sim Q_{Y_1 \mid A = 0, L,U} \circ F_{Y_0 \mid A = 0, L,U} \left( Y_0 \right) \mid A = 1, L,U\\
    \end{aligned}
\end{equation*}
Denote $\tgamma(y, l, u) \equiv Q_{Y_1 \mid  A = 0, L = l, U = u} \circ F_{Y_0 \mid  A = 0, L = l, U = u} \left( y \right)$.
By Assumption \ref{assum:db} and Lemma \ref{lem:QQ}, there exists a function $\gamma(y,l)$ such that $\gamma(y,l) = \tgamma(y, l, u)$. Therefore,
\begin{equation*}
  \begin{aligned}
    F_{Y_0\mid A = 0, L = l}(y) &= F_{Y_0^{a = 0}\mid A = 0, L = l}(y)\\
    &= \Prob(Y_0^{a = 0} \le y \mid  A = 0, L = l)\\
    & \text{(by Assumption \ref{assum:pos_U})}\\ 
    &= \int \Prob(Y_0^{a = 0} \le y \mid  A = 0, L = l, U = u) \dx{F_{U\mid A = 0, L = l}(u)}\\
    & \text{(by Assumption \ref{assum:ct}(b))}\\ 
    &= \int \Prob(\tgamma(Y_0^{a = 0}, l, u) \le \tgamma(y,l,u) \mid  A = 0, L = l, U = u) \dx{F_{U\mid A = 0, L = l}(u)}\\
    & \text{(by $\tgamma(Y_0^{a=0}, L, U)\mid A = 0, L = l, U = u \sim Y_1^{a = 0}\mid A = 0, L = l, U = u$)}\\
    &= \int \Prob(Y_1^{a = 0} \le \tgamma(y,l, u) \mid  A = 0, L = l, U = u) \dx{F_{U\mid A = 0, L = l}(u)}\\
    &= \int \Prob(Y_1 \le \gamma(y,l) \mid  A = 0, L = l, U = u) \dx{F_{U\mid A = 0, L = l}(u)}\\
    &= F_{Y_1\mid A = 0, L = l}(\gamma(y,l)).
  \end{aligned}
\end{equation*}
Therefore, when $\gamma(y,l)$ is in the support of the conditional law of $Y_1$ given $A = 0, L = l$, we have
\[\gamma(y,l) = Q_{Y_1\mid A = 0, L = l} \circ  F_{Y_0\mid A = 0, L = l}(y),\]
and since $\gamma(Y_0, L) \in \supp(Y_1\mid A = 0, L)$ almost surely, we have
\[ Y_1^{a = 0} \mid  A = 1, L, U \sim Q_{Y_1\mid A = 0, L} \circ  F_{Y_0\mid A = 0, L}(Y_0)\mid  A = 1, L, U.\]
Then,
\begin{equation*}
    \begin{aligned}
        \theta &= \E[Y_1^{a=1} - Y_1^{a = 0}\mid A = 1]\\
        &= \E\left[\E\left\{Y_1 - Y_1^{a = 0}\mid A = 1, L, U\right\}\right]\\
        &= \E\left[\E\left\{Y_1 - Q_{Y_1\mid A = 0, L} \circ  F_{Y_0\mid A = 0, L}(Y_0)\mid A = 1, L, U\right\}\right]\\
        &= \E\left\{Y_1 - Q_{Y_1\mid A = 0, L} \circ  F_{Y_0\mid A = 0, L}(Y_0)\mid A = 1\right\}
    \end{aligned}
\end{equation*}
\end{proof}

\subsection{Corollary \ref{cor:id_other}}

\begin{proof}
  (I) Corollary \ref{cor:idcd}:\\
  By the proof of Theorem \ref{thm:idett}, 
  \[ Y_1^{a = 0} \mid  A = 1, L, U \sim Q_{Y_1\mid A = 0, L} \circ  F_{Y_0\mid A = 0, L}(Y_0)\mid  A = 1, L, U.\] Using this result, we have 
  \begin{equation*}
    \begin{aligned}
      F_{Y^{a=0}_1\mid A = 1}(y) &= \Prob(Y^{a=0}_1 \le y \mid A = 1)\\
      &= \E\{ \Prob(Y^{a=0}_1 \le y \mid A = 1, L, U) \mid A = 1\}\\
      &= \E[ \Prob\{Q_{Y_1\mid A = 0, L} \circ  F_{Y_0\mid A = 0, L}(Y_0) \le y \mid A = 1, L, U\}  \mid A = 1]\\
      &= \Prob\{Q_{Y_1\mid A = 0, L} \circ  F_{Y_0\mid A = 0, L}(Y_0) \le y \mid A = 1\}.
    \end{aligned}
  \end{equation*} 

  (II) Corollary \ref{cor:idq}:\\
  It is a direct result of the definition of quantile treatment effect on the treated and Corollary \ref{cor:idcd}.
\end{proof}

\subsection{Proposition \ref{prop:semitrans1}}
\begin{proposition}
  Example \ref{eg:stm} satisfies Assumptions \ref{assum:setting}, \ref{assum:ct}, and \ref{assum:db}.
  \label{prop:semitrans1}
\end{proposition}

\begin{proof}
  (I) Assumption \ref{assum:confounding}: This is a direct result of $\delta \indep \epsilon_t\mid L,U$. 

  (II) Assumption \ref{assum:ct}: This is implied by the continuity of $F_{\epsilon\mid A = 0,L, U}(\cdot)$.

  (III) Assumption \ref{assum:db}: 
  Since $\beta_t$ is strictly increasing, it has inverse function $\alpha_t \equiv \beta_t^{-1}$.
  By the data-generating process in Example \ref{eg:stm}, we have the following conditional distribution function:
  \begin{equation*}
      \begin{aligned}
          F_{Y_{t}^{a=0}|A=0,L,U}\left( y\right)  &= \Prob \left( Y_{t}^{a=0}\le y|A=0,L,U\right)  \\
          &= \Prob \left\{ \alpha_{t}(Y_{t}^{a=0}) \le \alpha_{t}(y)|A=0,L,U\right\}  \\
          &= \Prob \left\{ m\left( U\right) +\epsilon_{t}+k_{t}(L) \le \alpha_{t}\left( y\right) |A=0,L,U\right\}  \\
          &= \Prob \left\{ \epsilon_{t} \le \alpha_{t}\left( y\right) - m\left( U\right) - k_{t}(L)  |A=0,L,U\right\}  \\
          &= F_{\epsilon |A=0,L,U}\left\{\alpha_{t}\left( y\right) - m\left( U\right) - k_{t}(L) \right\}\\
          &= F_{\epsilon |A=0,L,U}\left\{\beta_{t}^{-1}\left( y\right) - m\left( U\right) - k_{t}(L) \right\}
      \end{aligned}
  \end{equation*}
  This implies \[Q_{Y_{1}|A=0,L, U}\circ F_{Y_{0}|A=0, L,U}\left( y\right)  = \beta_{1}\left( \beta_{0}^{-1}\left(y\right) +k_{1}(L)-k_{0}(L)\right),\]
  which does not depend on $U$.
\end{proof}%

\subsection{Lemma \ref{lem:flat}}
For a nondecreasing real-valued function $g$ defined on $\R$, define \(I_t\) to be the largest open interval such that \(g(x) = t\) for all \(x \in I_t\). We refer to any nonempty such interval \(I_t\) as a \emph{flat spot} of \(g\), representing regions where the function \(g\) is constant.

\begin{lemma} \label{lem:flat}
Let \((\Omega, \mathcal{F}, \mathbb{P})\) be a complete probability space, and let \(X\) be a real-valued random variable. Suppose \(g: \mathbb{R} \rightarrow \mathbb{R}\) is nondecreasing, and \(X\) lies within the closure of flat spots of \(g\) with probability zero. Then, for any integrable random variable \(A\),
\[
\mathbb{E}[A \mid X] = \mathbb{E}[A \mid g(X)] \quad \text{almost surely.}
\]
\end{lemma}

\begin{proof}
Let \(\mathcal{N}\) denote the collection of all \(\mathbb{P}\)-null sets in \(\mathcal{F}\), and let \(\sigma(\mathcal{N})\) denote the \(\sigma\)-algebra they generate. Define \(Z \equiv g(X)\). Because $\sigma(A)\indep \sigma(\N)|\sigma(X), \sigma(A)\indep \sigma(\N)|\sigma(Z)$, we have
\[
\mathbb{E}[A \mid \sigma(X) \vee \sigma(\mathcal{N})] = \mathbb{E}[A \mid X], \quad \mathbb{E}[A \mid \sigma(Z) \vee \sigma(\mathcal{N})] = \mathbb{E}[A \mid Z].
\]

Since \(Z = g(X)\), it follows that \(\sigma(Z) \subseteq \sigma(X)\), and thus \(\sigma(Z) \vee \sigma(\mathcal{N}) \subseteq \sigma(X) \vee \sigma(\mathcal{N})\). We now show the reverse inclusion under the given assumption.

Define the set
\[
\mathfrak{D} \equiv \left\{ \omega \in \Omega : X(\omega) \text{ lies outside the closure of flat spots of } g \right\}.
\]
By assumption, \(\mathbb{P}(\mathfrak{D}) = 1\).

Now consider a generating class for \(\sigma(X)\), namely sets of the form \(B_t = \{x \in \mathbb{R} : x \le t\}\). For any \(t \in \mathbb{R}\),
\[
X^{-1}(B_t) = \left\{ \omega \in \Omega : X(\omega) \le t \right\}.
\]
On the set \(\mathfrak{D}\), where \(g\) is strictly increasing in a neighborhood of \(X(\omega)\), we have 
\[
\left\{ \omega \in \mathfrak{D} : X(\omega) \le t \right\} = \left\{ \omega \in \mathfrak{D} : Z(\omega) \le g(t) \right\}.
\]
Therefore,
\[
X^{-1}(B_t) = \left( \mathfrak{D} \cap \{Z \le g(t)\} \right) \cup \left( \mathfrak{D}^c \cap \{X \le t\} \right).
\]
The first term belongs to \(\sigma(Z) \vee \sigma(\mathcal{N})\), and the second to \(\sigma(\mathcal{N})\) since \(\mathbb{P}(\mathfrak{D}^c) = 0\). Thus, \(X^{-1}(B_t) \in \sigma(Z) \vee \sigma(\mathcal{N})\) for all \(t\), which implies \(\sigma(X) \subseteq \sigma(Z) \vee \sigma(\mathcal{N})\).

Hence,
\[
\sigma(X) \vee \sigma(\mathcal{N}) = \sigma(Z) \vee \sigma(\mathcal{N}),
\]
and the conditional expectations agree almost surely:
\[
\mathbb{E}[A \mid X] = \mathbb{E}[A \mid Z].
\]
\end{proof}


\subsection{Theorem \ref{thm:eif}}

\begin{proof}
  We derive the efficient influence function of the functional of observed data distribution defined by the identification formula in Equation \eqref{eq:idett}.\\
  (I) We first characterize the tangent space and its closure.

  Suppose the observable data $W \equiv (A, L, Y_0, Y_1) \sim P$, and define a regular parametric submodel $\mathcal{P}_\lam \equiv \{P_\lam: \lam \in (-\tilde{\lam},\tilde{\lam})\}$, with $\tilde{\lam}$ a small positive number, such that the true DGP $P = P_0$ and
  \[\log \dd{P_\lam}{P}(W) = \lam \score(W) - a(\lam),\]
  where $\score(W) \in \R$ is an arbitrary mean-zero and bounded (score) function under $P_0$, and $ a(\lam)$ is a normalizing constant with $a(\lam) = \log\E_{P_0}\left[ \exp\left\{ \lam \score(W) \right\} \right]$, $\dot{a}(\lam) = \E_{P_\lam}\left\{\score(W)\right\}$, and $\ddot{a}(\lam) = \Var_{P_\lam}\left\{\score(W)\right\}$. Evaluating at $\lam = 0$, $a(0) = \dot{a}(0) = 0, \ddot{a}(0) = \E_{P_0}\{\score(W)^2\}$. The true DGP $P_0$ satisfies Assumptions \ref{assum:setting} -- \ref{assum:db}; in fact, the whole path of $P_\lam$ for each $\lam$ and each $\score(W)$ defined above satisfies these assumptions by the boundedness of $\score$ and mutual absolute continuity between $P_\lam$ to $P_0$. This can be seen from the following:

  (i) Assumption \ref{assum:setting}: First, note that Assumption \ref{assum:cc}, \ref{assum:confounding}, and \ref{assum:na} do not restrict observable data. What remains is Assumption \ref{assum:pos_U}, as positivity conditional on $L,U$ implies positivity conditional on $L$ alone. 

  First, by the equivalent relation between $P_0$ and $P_\lam$, and boundedness of $\score$ and $\lam$, we have 
  \[m < \dd{P_\lam}{P_0} < M.\]
  Also, by Assumption \ref{assum:pos_U}, we have 
  \[P(A = 1\mid L) \in (\delta,1 - \delta). \]
  The above two bounds imply that there exists positive number $\eta$ such that for all $\score, \lam$, 
  \[P_\lam(A = 1\mid L) \in (\eta,1 - \eta).\]


  (ii) Assumption \ref{assum:ct}: this is a direct result of continuity under $P_0$ and equivalence of (conditional) measures. Note that $F_{Y_{0}\mid A=0, L,U}\left( \cdot\right)$ being a continuous function implies $F_{Y_{0}\mid A=0, L}\left( \cdot\right)$ is a continuous function. By the boundedness conditions above, we know that the conditional density ratios are also bounded. Therefore, for a measurable set $B$, whenever conditional measure of $\{Y_0 \in B\}$ is zero given $A = 0, L$, $P_\lam(Y_0 \in B \mid A = 0, L)$ is also zero. 

  (iii) Assumption \ref{assum:db}: This condition does not restrict observable data.

  Therefore, since bounded measurable functions are dense in $L_2(P_0)$, the mean-square closure of the linear span of all $\score$ defined above is the entire Hilbert space of $P_0$-mean-zero measurable functions of $W$ with finite second moments equipped with the inner product $\langle h_1, h_2 \rangle = \E_{P_0}\left\{ h_1(W)h_2(W) \right\}$. In other words, our statistical model is nonparametric, and thus there is at most one influence function, and if there exists one, it is the efficient influence function.\\

  (II) We derive below the efficient influence function (EIF) for $\theta = \theta_1 - \theta_2$ as a pathwise derivative, where
  \begin{equation*}
    \begin{aligned}
      \theta_1 &= \E\left\{ Y_{1}\mid A=1\right\},\\
      \theta_2 &= \E\left\{ Q_{Y_{1}\mid A=0, L}\circ F_{Y_{0}\mid A=0, L}\left( Y_{0}\right)\mid A=1\right\}. 
    \end{aligned}
  \end{equation*}
  The EIF for $\theta$, denoted by $\IF{\theta}$, is the difference of the EIFs for $\theta_1$ and $\theta_2$, i.e. $\IF{\theta_1}$ and $\IF{\theta_2}$.
  It is well known that 
  \[\IF{\theta_1} = \ff{\I{A = 1}}{P(A = 1)}(Y_1 - \theta_1) = \ff{A}{P(A = 1)}(Y_1 - \theta_1),\]
  where $\I{\cdot}$ is the indicator function. Next, we focus on $\IF{\theta_2}$. 


  For ease of notation, let 
  $h(y,l) \equiv Q_{Y_{1}\mid A=0,L = l}(y)$, $ g(y,l) \equiv F_{Y_{0}\mid A=0,L = l}(y) $, and $\gamma(y,l) = h(g(y,l),l)$. Then, under $P_\lam$, we have $\gamma_\lam(y,l) = h_\lam(g_\lam(y,l),l) \equiv Q_{\lam,Y_{1}\mid A=0, L = l} \circ  F_{\lam, Y_{0}\mid A=0, L = l}(y)$, and
  \begin{equation*}
    \begin{aligned}
      \theta_{2, \lam} &= \E_{P_\lam}\left\{ \gamma_\lam(Y_0, L) \mid  A = 1\right\} \\
      &= \int \gamma_\lam(y_0, l) f_\lam(y_0, l\mid A = 1) \dy{y_0}\dy{l} \\
      &= \int \gamma_\lam(y_0, l) \ff{f_\lam(y_0, l, A = 1)}{P_\lam(A = 1)} \dy{y_0}\dy{l}.
    \end{aligned}
  \end{equation*}
  Let $\score(\cdot)$ denote the score function. Then, the pathwise derivative is
  \begin{equation*}
    \begin{aligned}
      \plam\theta_{2, \lam}\midl &= 
      \int \pp{}{\lam}\gamma_\lam(y_0, l)\bmidl \ff{f(y_0, l, A = 1)}{P(A = 1)} \dy{y_0}\dy{l} 
      + \int \gamma(y_0,l) \pp{}{\lam}\left[\ff{f_\lam(y_0,l, A = 1)}{P_\lam(A = 1)} \right]\bmidl\dy{y_0}\dy{l}\\
      &= \E\left[\pp{}{\lam}\gamma_\lam(Y_0,L)\bmidl \bigg| A = 1\right] + \E[\score(Y_0, L|A = 1)\gamma(Y_0,L)|A = 1]
    \end{aligned}
  \end{equation*}
  Next, we will focus on $\E\left[\pp{}{\lam}\gamma_\lam(Y_0, L)\bmidl \bigg| A = 1\right]$. By Assumption \ref{assum:confounding} and \ref{assum:pos_U} and measure changing, we have
  \begin{equation*}
    \begin{aligned}
      \E\left[\pp{}{\lam}\gamma_\lam(Y_0, L)\bmidl \bigg| A = 1\right] &= \ff{P(A = 0)}{P(A = 1)}\E\left[\plam\gamma_\lam(Y_0, L)\cdot \ff{P(A = 1|Y_0, L)}{P(A = 0|Y_0, L)} \bigg| A = 0\right]\\
      &= \ff{P(A = 0)}{P(A = 1)}\E\left[\E\left\{\plam\gamma_\lam(Y_0, L)\cdot \ff{P(A = 1|Y_0, L)}{P(A = 0|Y_0, L)}\bigg| A = 0, L\right\} \bigg| A = 0\right]
    \end{aligned}
  \end{equation*}
  Since under $P_\lam$, we have
  \[\gamma_\lam(Y_0, L)|A = 0,L \sim Y_1|A = 0, L.\]
  Therefore, for an arbitrary measurable function $\rho(x,l)$, we have the identity
  \[0 = \E_\lam[\rho(\gamma_\lam(Y_0, L), L) - \rho(Y_1, L)|A = 0, L].\]
  Taking partial derivative with respect to $\lam$ on both sides, we have
  \begin{equation}
  0 = \E[\score(Y_1, Y_0|A = 0, L)\{\rho(\gamma(Y_0,L), L) - \rho(Y_1, L)\}|A = 0, L] + \E[\partial_x\rho(\gamma(Y_0, L), L)\cdot \plam \gamma_\lam(Y_0, L)|A = 0, L].
  \label{eq:eqdiff}
  \end{equation}
  %
  Then, given $L = l$, for an arbitrary random variable $X$, we have \[\E[X|\gamma(Y_0, l), L = l] = \E[X|F_{Y_0|A = 0, L = l}(Y_0), L = l] = \E[X|Y_0, L = l],\]
  where the first equality is by the strict monotonicity of $Q_{Y_1\mid A = 0, L = l}$, and the second equality is by Lemma \ref{lem:flat}.

  %
  Then, by choosing an $\rho$ whose partial derivative with respect to its first argument $x$ is
  \[\nu(x,l) \equiv \partial_x\rho(x,l) \equiv  \ff{P(A = 1|\gamma(Y_0, l) = x, L = l)}{P(A = 0|\gamma(Y_0, l) = x, L = l)}, \] and applying Equation \eqref{eq:eqdiff}, we have
  \begin{equation*}
  \begin{aligned}
      \E\left[\pp{}{\lam}\gamma_\lam(Y_0)\bmidl \bigg| A = 1\right]
      &= \ff{P(A = 0)}{P(A = 1)}\E\left[\E\left\{\plam\gamma_\lam(Y_0, L)\cdot \ff{P(A = 1|Y_0, L)}{P(A = 0|Y_0, L)}\bigg| A = 0, L\right\} \bigg| A = 0\right]\\
      &= \ff{P(A = 0)}{P(A = 1)}\E\left[-\E[\score(Y_1, Y_0|A = 0, L)\{\rho(\gamma(Y_0,L), L) - \rho(Y_1, L)\}|A = 0, L]\bigg| A = 0\right]\\ 
      &= -\ff{P(A = 0)}{P(A = 1)}\E\left[\E\left\{\score(Y_1, Y_0|A = 0, L)\left(\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\bigg|A = 0, L\right\}\bigg| A = 0\right]\\
      &= -\ff{P(A = 0)}{P(A = 1)}\E\left[\score(Y_1, Y_0|A = 0, L)\left(\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\bigg| A = 0\right]\\
      &= \E\left[\score(Y_1, Y_0|A = 0, L)\left(\ff{A - 1}{P(A = 1)}\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\right].
  \end{aligned}
  \end{equation*}
  Therefore,
  \begin{equation*}
    \begin{aligned}
      \plam\theta_{2, \lam}\midl 
      &= \E\left[\score(Y_1, Y_0|A = 0, L)\left(\ff{A - 1}{P(A = 1)}\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\right] + \E\left[\score(Y_0, L|A = 1)\gamma(Y_0,L)\ff{A}{P(A = 1)}\right]
    \end{aligned}
  \end{equation*}
  Then, we have 
  \begin{equation*}
  \begin{aligned}
      & \E\left[\score(Y_1, Y_0|A = 0, L)\left(\ff{A - 1}{P(A = 1)}\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\right] \\
      &= -\ff{P(A = 0)}{P(A = 1)}\E\left[\score(Y_1, Y_0|A, L)\left(\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\bigg| A = 0\right]\\
      &= -\ff{P(A = 0)}{P(A = 1)}\E\left[(\score(Y_1, Y_0|A, L) + \score(A, L))\left(\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\bigg| A = 0\right]\\
      &= -\ff{P(A = 0)}{P(A = 1)}\E\left[\score(Y_1, Y_0, A, L)\left(\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\bigg| A = 0\right]\\
      &= \E\left[\score(Y_1, Y_0, A, L)\left(\int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\right)\ff{A - 1}{P(A = 1)}\right]
  \end{aligned}
  \end{equation*}   


  \begin{equation*}
    \begin{aligned}
      & \E[\score(Y_0, L|A = 1)\gamma(Y_0, L)|A = 1] \\
      &= \E\left[\score(Y_0, L|A = 1)\gamma(Y_0, L)\ff{A}{P(A = 1)}\right] \\
      &= \E\left[\score(Y_0, L|A)\gamma(Y_0, L)\ff{A}{P(A = 1)}\right] \\
      &= \E\left[\score(Y_0, L|A)\{\gamma(Y_0, L) - \E[\gamma(Y_0, L)|A]\}\ff{A}{P(A = 1)}\right] \\
      &= \E\left[\left\{\score(Y_0, L|A) + \score(Y_1|Y_0,A, L)\right\}\{\gamma(Y_0, L) - \E[\gamma(Y_0, L)|A]\}\ff{A}{P(A = 1)}\right] \\
      &= \E\left[\left\{\score(Y_1, Y_0, L|A) + \score(A)\right\}\{\gamma(Y_0, L) - \E[\gamma(Y_0, L)|A]\}\ff{A}{P(A = 1)}\right] \\
      &= \E\left[\score(Y_1, Y_0, L, A) \{\gamma(Y_0, L) - \E[\gamma(Y_0, L)|A]\}\ff{A}{P(A = 1)}\right] \\
      &= \E\left[\score(Y_1, Y_0, L, A) \{\gamma(Y_0, L) - \E[\gamma(Y_0, L)|A = 1]\}\ff{A}{P(A = 1)}\right]
    \end{aligned}
  \end{equation*}
  Then,
  \begin{equation*}
    \begin{aligned}
      \plam\theta_{2, \lam}\midl
      &= \E\left[\score(Y_1, Y_0, L, A) \left(\{\gamma(Y_0, L) - \E[\gamma(Y_0, L)|A = 1]\}\ff{A}{P(A = 1)} + \int_{Y_1}^{\gamma(Y_0, L)} \nu(x,L) \dy{x}\ff{A - 1}{P(A = 1)}\right)\right]\\
      &= \E\left[\ff{\score(Y_1, Y_0, L, A) }{P(A = 1)}\left\{ A(\gamma(Y_0, L) - \theta_2) - (1-A)\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\dx{x}\right\}\right].
    \end{aligned}
  \end{equation*}
  Since our model is nonparametric, the EIF for $\theta_2$ is
  \[\IF{\theta_2} = \ff{1}{P(A = 1)}\left\{ A(\gamma(Y_0, L) - \theta_2) - (1-A)\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\dx{x}\right\},\]
  and the EIF for $\theta$ is
  \begin{equation*}
    \begin{aligned}
      \IF{\theta} = \ff{A}{P(A = 1)}[\{Y_1 - \gamma(Y_0, L)\} - \theta] + \ff{1 - A}{P(A = 1)}\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\dx{x}.
    \end{aligned}
  \end{equation*}

(III) Therefore, the semiparametric efficiency bound is $\Var(\IF{\theta}) = \E(\IF{\theta}^2)$.

\end{proof}

\subsection{Theorem \ref{thm:eif_gen}}


\begin{proof}
  (I) Tangent Space: 

  The mean-square closure of the tangent space remains the nonparametric model, as in the proof of Theorem \ref{thm:eif}, thus omitted. In particular, we still adopt the same set of parametric submodels: 
  \[\log \dd{P_\lam}{P}(W) = \lam \score(W) - a(\lam).\]

  (II) Efficient Influence Function (EIF):

  Since $\E_{P_0}[g(W;\vartheta, \gamma) \mid A = 1] = 0$, in a submodel $\mathcal{P}_\lam \equiv \{P_\lam: \lam \in (-\tilde{\lam},\tilde{\lam})\}$, we have the identity $0 =\E_{\lam}[g(W;\vartheta_\lam, \gamma_\lam)\mid A = 1]$. In this proof, all the partial derivative with respect to $\lam$ is evaluated at $\lam = 0$ and we thus omit this for notational convenience. Taking derivative on both sides, we have
  \begin{equation*}
    \begin{aligned}
      0 &= \pd{\lam}\E_{\lam}[g(W;\vartheta_\lam, \gamma_\lam)\mid A = 1]\\
      &= \E[g(W;\vartheta, \gamma)\score(W\mid A = 1)\mid A = 1] + \pd{\vartheta}\E[g(W;\vartheta, \gamma)\mid A = 1]\cdot \pd{\lam}\vartheta_\lam \\
      & \phantom{=} + \pd{\lam}\E[g(W;\vartheta, \gamma_\lam)\mid A = 1]
    \end{aligned}
  \end{equation*}
  Therefore, 
  \[\pd{\lam}\vartheta_\lam = \ff{\E[g(W;\vartheta, \gamma)\score(W\mid A = 1)\mid A = 1] + \pd{\lam}\E[g(W;\vartheta, \gamma_\lam)\mid A = 1] }{-\pd{\vartheta}\E[g(W;\vartheta, \gamma)\mid A = 1]}.\]
  In the following we change the numerator into the form of a pathwise derivative.

  (i) $\pd{\lam}\E[g(W;\vartheta, \gamma_\lam)\mid A = 1]$: 

  We will use the identity again previously shown in the proof of Theorem \ref{thm:eif}:
  \begin{equation*}
    0 = \E[\score(Y_1, Y_0|A = 0, L)\{\rho(\gamma(Y_0,L), L) - \rho(Y_1, L)\}|A = 0] + \E[\partial_x\rho(\gamma(Y_0, L), L)\cdot \plam \gamma_\lam(Y_0, L)|A = 0].
  \end{equation*}
  %
  Denote $\pi(Y_0, L) \equiv \Prob_0(A = 1 \mid Y_0, L)$, and recall that\[\nu(x,l) \equiv \ff{P(A = 1|\gamma(Y_0, l) = x, L = l)}{P(A = 0|\gamma(Y_0, l) = x, L = l)}.\] Then, we have 
  \begin{equation*}
    \begin{aligned}
      &\pd{\lam}\E[g(W;\vartheta, \gamma_\lam)\mid A = 1]\\
      &= \pd{\lam}\E[\tilde{g}(\gamma_\lam(Y_0, L),\vartheta)\mid A = 1]\\
      &= \E\left[\pd{\gamma}\tilde{g}(\gamma(Y_0, L),\vartheta) \cdot \pd{\lam}\gamma_\lam(Y_0, L) \mid A = 1\right]\\
      &= \ff{1 - \pi}{\pi}\E\left[\pd{\gamma}\tilde{g}(\gamma(Y_0, L),\vartheta) \cdot \ff{\pi(Y_0,L)}{1 - \pi(Y_0,L)} \cdot \pd{\lam}\gamma_\lam(Y_0, L) \mid A = 0\right]\\
      &= \ff{1 - \pi}{\pi}\E\left[\pd{\gamma}\tilde{g}(\gamma(Y_0, L),\vartheta) \cdot \nu\{\gamma(Y_0,L), L\} \cdot \pd{\lam}\gamma_\lam(Y_0, L) \mid A = 0\right]\\
      &= \ff{1 - \pi}{-\pi}\E\left[\score(Y_1, Y_0|A = 0, L)\int_{Y_1}^{\gamma(Y_0, L)} \pd{x}\tilde{g}(x,\vartheta) \cdot \nu(x, L) \dx{x} \bigg| A = 0\right]\\
      &= \ff{1 - \pi}{-\pi}\E\left[\score(Y_1, Y_0, A, L)\int_{Y_1}^{\gamma(Y_0, L)} \pd{x}\tilde{g}(x,\vartheta) \cdot \nu(x, L) \dx{x} \bigg| A = 0\right]\\
      &= \E\left[\score(Y_1, Y_0, A, L) \cdot \ff{A - 1}{\pi}\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\dx_x{\tilde{g}(x,\vartheta)} \right]
    \end{aligned}
  \end{equation*}


  (ii) $\E[g(W;\vartheta, \gamma)\score(W\mid A = 1)\mid A = 1] = \E[\ff{A}{\pi}g(W;\vartheta, \gamma)\score(W)]$.

  (III) Summary:

  Therefore, the EIF for $\vartheta$ is
  \[\IF{\vartheta} = \ff{\ff{A}{\pi}g(W;\vartheta, \gamma) + \ff{A - 1}{\pi}\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\dx_x{\tilde{g}(x,\vartheta)} }{-\pd{\vartheta}\E[g(W;\vartheta, \gamma)]}.\]
  And by the semiparametric theory, the semiparametric efficiency bound for $\vartheta$ is $\E\left\{\IF{\vartheta}^2\right\}$.

\end{proof}

\subsection{Corollary \ref{cor:eif_other}}

\begin{proof}
  (a) $\vartheta^{CDT,y}$:

  Recall that $g(W;\vartheta, \gamma) = \tilde{g}(\gamma(Y_0, L), \vartheta) = \I{\gamma(Y_0, L) < y}- \vartheta$, and therefore $ \pd{\vartheta}g(W;\vartheta, \gamma) = -1$, and $ \pd{x}\tilde{g}(x,\vartheta) = -\delta_y(x)$, where $\delta_y(\cdot) \equiv \delta(\cdot - y)$ and $\delta(\cdot)$ is the Dirac delta function.

  Then, the denominator $-\pd{\vartheta}\E[g(W;\vartheta, \gamma)] = 1$, and 
  \begin{equation*}
    \begin{aligned}
      &\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\dx_x{\tilde{g}(x,\vartheta)}\\
      &= -\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\delta_y(x) \dy{x}\\
      &= \nu(y, L) \chi(y, W; \gamma)
    \end{aligned}
  \end{equation*}

  Therefore, we have
  \begin{equation*}
    \begin{aligned}
      \IF{\vartheta^{CDT,y}} &= \ff{A}{\pi}\left[\I{\gamma(Y_0, L) < y}- \vartheta^{CDT,y}\right] + \ff{A - 1}{\pi} \nu(y, L) \chi(y, W; \gamma).
    \end{aligned}
  \end{equation*}

  (b) $\vartheta^{QTT,\tau}$:

  (I) First, note that the additional condition that $Q_{Y^{a}_1\mid A = 1}(\tau)$ is unique and $Y^{a}_1\mid A = 1$ does not have point mass at $Q_{Y^{a}_1\mid A = 1}(\tau)$ for $a = 0,1$ does not change the closure of the tangent space, by Assumption \ref{assum:pos_U} and \ref{assum:ct}. Therefore, we will continue to work with the nonparametric model.

  (II) The EIF of $\vartheta^{QTT,\tau}$ is the difference between $\IF{\vartheta_1}$ and $\IF{\vartheta_2}$, where the first one is well-known in the literature, e.g. \citet{firpo2007efficient}, to be 
  \[\IF{\vartheta_1} = -\ff{A}{\pi}\ff{\I{Y_1 \le \vartheta_1} - \tau}{f_{Y_1\mid A = 1}(\vartheta_1)}.\] 

  In the following, we focus on deriving $\IF{\vartheta_2}$ by applying Theorem \ref{thm:eif_gen}. We may choose $g(W;\vartheta_2, \gamma)  = \tilde{g}(\gamma(Y_0,L);\vartheta_2) = \I{\gamma(Y_0, L) < \vartheta_2} - \tau$. Then, we have $\pd{\vartheta_2}\E [g \mid A = 1] = f_{\gamma(Y_0,L)\mid A = 1}(\vartheta_2)$, and $\pd{x}\tilde{g}(x,\vartheta_2) = -\delta_{\vartheta_2}(x)$. Therefore, 
  \begin{equation*}
    \begin{aligned}
      &\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\dx_x{\tilde{g}(x,\vartheta_2)}\\
      &= -\int_{Y_1}^{\gamma(Y_0, L)} \nu(x, L)\delta_{\vartheta_2}(x) \dy{x}\\
      &=  \nu(\vartheta_2, L) \chi(\vartheta_2, W; \gamma).
    \end{aligned}
  \end{equation*}
  Therefore,
  \begin{equation*}
    \begin{aligned}
      \IF{\vartheta_2} &= \ff{\ff{A}{\pi}\left[\I{\gamma(Y_0, L) < \vartheta_2} - \tau\right] + \ff{A - 1}{\pi}\nu(\vartheta_2, L) \chi(\vartheta_2, W; \gamma)}{-f_{\gamma(Y_0,L)\mid A = 1}(\vartheta_2)}.
    \end{aligned}
  \end{equation*}
  To conclude, $\IF{\vartheta^{QTT,\tau}} = \IF{\vartheta_1} -  \IF{\vartheta_2}$.

\end{proof}

\subsection{Lemma \ref{lem:bias}}

\begin{proof}
Recall that
\[
\psi(\theta,\eta_\lambda)
= \pi_\lambda^{-1}
  \Bigl[
    A\bigl(Y_1 - \gamma_\lambda(Y_0,L) - \theta\bigr)
    + (1-A)\!\int_{Y_1}^{\gamma_\lambda(Y_0,L)}\!\!\nu_\lambda(x,L)\,dx
  \Bigr].
\]
Set
\[
S_\lambda
:= A\bigl(Y_1 - \gamma_\lambda(Y_0,L) - \theta\bigr)
   + (1-A)\!\int_{Y_1}^{\gamma_\lambda(Y_0,L)}\!\!\nu_\lambda(x,L)\,dx,
\]
so that
\[
\Phi(\lambda)
:= \E\bigl[\psi(\theta,\eta_\lambda)\bigr]
= \pi_\lambda^{-1}\,\E\bigl[S_\lambda\bigr]
= \pi_\lambda^{-1}\,g(\lambda),
\quad
g(\lambda):=\E\bigl[S_\lambda\bigr].
\]

Let $u_\lambda := \gamma_\lambda(Y_0,L)$.  Then by the chain and Leibniz rules,
\begin{align*}
S_\lambda'
&= A\bigl[-\Delta\gamma(Y_0,L)\bigr]
  + (1-A)\,\frac{d}{d\lambda}\!\int_{Y_1}^{u_\lambda}\!\!\nu_\lambda(x,L)\,dx \\[4pt]
&= -\,A\,\Delta\gamma(Y_0,L)
   + (1-A)\Bigl[
       \Delta\gamma(Y_0,L)\,\nu_\lambda(u_\lambda,L)
       + \int_{Y_1}^{u_\lambda}\!\!\Delta\nu(x,L)\,dx
     \Bigr],\\[6pt]
S_\lambda''
&= -\,A\cdot 0
   + (1-A)\,\frac{d}{d\lambda}\Bigl[
       \Delta\gamma\,\nu_\lambda(u_\lambda,L)
       + \int_{Y_1}^{u_\lambda}\!\!\Delta\nu(x,L)\,dx
     \Bigr]\\
&= (1-A)\Bigl[
     2\,\Delta\gamma(Y_0,L)\,\Delta\nu\bigl(u_\lambda,L\bigr)
     + \bigl[\Delta\gamma(Y_0,L)\bigr]^2
       \,\partial_x\nu_\lambda\bigl(u_\lambda,L\bigr)
   \Bigr].
\end{align*}

Since $\pi_\lambda'=\Delta\pi$, $\pi_\lambda''=0$, we get
\begin{align*}
\Phi'(\lambda)
&= \frac{d}{d\lambda}\Bigl[\pi_\lambda^{-1}\,g(\lambda)\Bigr]\\
&= -\,\frac{\Delta\pi}{\pi_\lambda^2}\,g(\lambda)
   + \frac{1}{\pi_\lambda}\,g'(\lambda)
= \frac{1}{\pi_\lambda}\,\E\bigl[S_\lambda'\bigr]
  \;-\;\frac{\Delta\pi}{\pi_\lambda^2}\,\E\bigl[S_\lambda\bigr],\\[6pt]
\Phi''(\lambda)
&= \frac{d}{d\lambda}\Bigl[\Phi'(\lambda)\Bigr]\\
&= \frac{1}{\pi_\lambda}\,g''(\lambda)
  -2\,\frac{\Delta\pi}{\pi_\lambda^2}\,g'(\lambda)
  +2\,\frac{(\Delta\pi)^2}{\pi_\lambda^3}\,g(\lambda)\\
&= \frac{1}{\pi_\lambda}\,\E\bigl[S_\lambda''\bigr]
  -2\,\frac{\Delta\pi}{\pi_\lambda^2}\,\E\bigl[S_\lambda'\bigr]
  +2\,\frac{(\Delta\pi)^2}{\pi_\lambda^3}\,\E\bigl[S_\lambda\bigr].
\end{align*}
Therefore,
\begin{equation}\label{eq:second-diff}
    \Phi''(\lambda) = \frac{1}{\pi_\lambda}\,\E\bigl[S_\lambda''\bigr]
  -2\,\frac{\Delta\pi}{\pi_\lambda^2}\,\E\bigl[S_\lambda'\bigr]
  +2\,\frac{(\Delta\pi)^2}{\pi_\lambda^3}\,\E\bigl[S_\lambda\bigr],
\end{equation}
which is a continuous function in $\lam$ by Assumption \ref{assum:nu}.

Therefore, when evaluated at $\lam = 0$, we have 
\[\Phi'(0)  = 0\] by the properties of efficient influence function \citep{newey1994asymptotic}. Alternatively, one can evaluate $\Phi'(\lambda)$ above and reach the same conclusion:

\[
\Phi'(0)
= \frac{1}{\pi}\,\E\bigl[S_0'\bigr].
\]


Let $u_0=\gamma(Y_0,L)$, then
\[
S_0'
= -A\,\Delta\gamma(Y_0,L)
  + (1-A)\Bigl[
       \Delta\gamma(Y_0,L)\,\nu\bigl(\gamma(Y_0,L),L\bigr)
       + \int_{Y_1}^{\gamma(Y_0,L)} \Delta\nu(x,L) \,dx
    \Bigr].
\]


\[
\Phi'(0)
= \frac{1}{\pi}
  \E\Bigl[
    -A\,\Delta\gamma(Y_0,L)
    + (1-A)\Bigl(
        \Delta\gamma(Y_0,L)\,\nu\bigl(\gamma(Y_0,L),L\bigr)
        + \int_{Y_1}^{\gamma(Y_0,L)} \Delta\nu(x,L)\,dx
      \Bigr)
  \Bigr].
\]

\[
\E[S_0']
= \E[-A\,\Delta\gamma(Y_0,L)]
  + \E[(1-A)\bigl(\Delta\gamma(Y_0,L)\,\nu(\gamma(Y_0,L),L)
               + \int_{Y_1}^{\gamma(Y_0,L)}\Delta\nu(x,L)\,dx\bigr)].
\]

\[
\E[-A\,\Delta\gamma]
  = -\pi\,\E[\Delta\gamma(Y_0,L)\mid A=1],
\quad
\E[(1-A)\Delta\gamma\,\nu]
  = (1-\pi)\,\E[\Delta\gamma(Y_0,L)\,\nu(\gamma(Y_0,L),L)\mid A=0].
\]

\[
\E[S_0']
= -\pi\,\E[\Delta\gamma\mid A=1]
  + (1-\pi)\,\E[\Delta\gamma\,\nu\mid A=0].
\]

\[
\E[\Delta\gamma(Y_0,L)\mid A=1]
= \frac{1-\pi}{\pi}\,
  \E[\Delta\gamma(Y_0,L)\,\nu(\gamma(Y_0,L),L)\mid A=0].
\]


\[
\E[S_0']
= -\pi\frac{1-\pi}{\pi}\,\E[\Delta\gamma\,\nu\mid A=0]
  + (1-\pi)\,\E[\Delta\gamma\,\nu\mid A=0]
=0.
\]


\end{proof}

\subsection{Theorem \ref{thm:asymptotic}}

\begin{proof}
The asymptotic properties stated in Theorem~\ref{thm:asymptotic} follow from Theorems 3.1 and 3.2, and Corollaries 3.1–3.3 of \citet{chernozhukov2018double}. To apply these results, we verify that the key conditions—Assumptions 3.1 and 3.2 in their framework—are satisfied in our setting.

We begin with Assumption 3.1 of \citet{chernozhukov2018double}. Conditions (a), (b), (d), and (e) are directly satisfied by standard properties of the efficient influence function; see, e.g., \citet{newey1990semiparametric, newey1994asymptotic}. Condition (c) follows from the second derivative characterization in Equation~\eqref{eq:second-diff} of the proof of Lemma~\ref{lem:bias}.

Next, we verify Assumption 3.2. Conditions (a), (b), and (c) are implied by the convergence rate assumption on the nuisance estimators stated in Assumption~\ref{assum:rate}. Condition (d) is trivially satisfied.

This completes the verification of the required assumptions.
\end{proof}




