\section{Weak Error for Particle 
Schemes with Nonparametric Estimators for Conditional Expectation}\label{Sec_Particles}


In this section we
still work with an approximation of conditional expectation, but this time there is no closed formula available. This leads us to studying non-parametric methods and to quantify the weak approximation error when using these methods.

For a parameter $\varepsilon \in (0,1)$ we introduce a Kernel function $K_\eps$ for our non-parametric estimation. Similar as above we introduce a parameter $\delta\in (0,1)$ to define the regularised Nadaraya-Watson estimator for conditional expectation:
\begin{definition}\label{Def_hEepsdelta}
    Let $X,\xi$ be two random variables, such that $\xi$ is square integrable. Let $\eps,\delta\in(0,1/2)$ and $K_\eps$ some Kernel satisfying Assumption \ref{Ass:kernel} below. 
    If $\mathbb{V}(X)>0$ define the estimator $\hE_\delta^\eps$ of the conditional expectation as
    \begin{align}\label{Eq:EhatEpsDelta}
        \hE_\delta^\eps\bigl[\xi^2\big|X\bigr]=\frac{
        \E\bigl[ \xi^2 K_\eps\bigl(x-X\bigr)\bigr]\big|_{x=X}+\delta
        }{{\E\bigl[ K_\eps\bigl(x-X\bigr)\bigr]\big|_{x=X}}+\delta }.
    \end{align}
    as well as $ \hE^\eps\bigl[\xi^2\big|X\bigr]= \hE^\eps_0\bigl[\xi^2\big|X\bigr]$.
    In case $\mathbb{V}(X)=0$ set $\hE_\delta^\eps\bigl[\xi^2\big|X\bigr]=\hE^\eps\bigl[\xi^2\big|X\bigr]=\E[\xi^2]$.
\end{definition}
    As we saw in previous sections, this estimator of the conditional expectation 
    can again be understood as a function $ \hE_\delta^\eps \bigl[ \xi_{jh}^2|\tiX^{h,\eps,\delta}_{jh}=x\bigr]\equiv \hPsi_j(x,\mathcal{L}(\xi_{jh},\tiX_{jh}^{h,\eps,\delta})) $, where for measures $\mu$ on $\mathbb{R}^2$ and $j \ge 1$
    the function $\hPsi_j$ is defined via 
    \begin{align}\label{Eq:PsiHat_Def}
        \hPsi_j(x,\mu)= \frac{\int_{\mathbb{R}\times\mathbb{R}}y^2K_{\eps}(x-z)
        \,d\mu(y,z)+\delta}{\int_{\mathbb{R}\times\mathbb{R}}K_{\eps}(x-z)
        \,d\mu(y,z)+\delta}.
    \end{align}
    For $j=0$ we set $\hPsi_0(x,\mu)=\int_{\mathbb{R}^2} y^2 \mu(dy,dz)$.



As done previously, we introduce an interacting particle system.
For this we denote by $\bigl( W^{(i)})_{i=1}^N$ independent Brownian motions. 
For $j\in \{0,\dots,\frac Th-1\}$,  we consider the following Euler scheme:
\begin{align}\label{Eq:Sec7}
    \hX_{jh+h}^{h,(i),N,\eps,\delta}&=\hX_{jh}^{h,(i),N,\eps,\delta}+ \sigma(jh,\hX_{jh}^{h,(i),N,\eps,\delta})\xi_{jh}^{(i)} \hPsi_j^{-\frac12}\bigl(\hX_{jh}^{h,(i),N,\eps,\delta},\mu^N_{jh}\bigr)\bigl( W_{jh+h}^{(i)}- W_{jh}^{(i)}\bigr),
    \\
    \hX_0^{h,(i),N,\eps,\delta}&=x_0,\nonumber
\end{align}
where, for $j\ge 0$ we denote by $\mu_{jh}^N$  the empirical measure of the interacting particle system. More precisely $\mu_{jh}^N(dx,dy)=\frac1N \sum_{j=1}^N \delta_{\xi_{jh}^{(i)},\hX_{jh}^{h,(i),N,\eps,\delta}}(dy,dx)$. 
Then we can show the following.


\begin{theorem}\label{Thm_Particle_Rate2}
    Let Assumption  \ref{Ass:Half_Step} as well as Assumption \ref{Aspt_new} hold and $h,T$ such that $\frac Th \in \mathbb{N}$. Let $K$  satisfy Assumption \ref{Ass:kernel} below and $f$ be three times weakly differentiable with derivatives of polynomial growth. Then for $h,\eps,\delta\in(0,1/2)$ 
    satisfying $\eps \lesssim h$ there is some $C>0$, such that
    \begin{align*}
         \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,(1),N,\eps,\delta}\bigr)\bigr]\Bigr|
        &\lesssim 
        h + \eps h^{-1} + \delta^{1-}  
        %\\        &
        + \frac1{\sqrt{N}}
        \eps
        \exp\Bigl(
        \frac T{2}h^{-1} \log\bigl( C h \delta^{-2}\eps^{-4}\bigr)\Bigr).
    \end{align*}
\end{theorem}

Note  that the weak error rate observed in Theorem \ref{Thm_Particle_Rate2} is worse than the one observed in Theorem \ref{Thm_Particle_Rate}.
Indeed, choosing $p\approx 1$, $\delta =h$ and  $ \varepsilon = h^2 $ in the latter (so that $h + \varepsilon h^{- 1} \sim h$) we see $h^{- 3 / 2}$ in the ``log-exponent'' for the half-step scheme, compared with $h^{- 9}$ without half-step. 



The remaining sections focus on proving Theorem \ref{Thm_Particle_Rate2}: 
Section \ref{Sec:Cond_exp_estim} establishes the convergence speed of the Nadaraya-Watson estimator for conditional expectation. This is then extended by showing convergence with the additional regularisation parameter. Finally, in Section \ref{Sec:POC} we show propagation of chaos and convergence to the target process, using results from previous sections.



\subsection{Nonparametric Estimator for Conditional Expectation}\label{Sec:Cond_Exp_Estimators}


Following up on the discussion in Section \ref{Approximation} above we now propose a method for a suitable estimator $\hE$ for conditional expectation. 
Let $\bigl(W^{(i)},\xi^{(i)}\bigr)_{i=1,\dots,N}$ be independent copies of $(W,\xi)$. Assume that, under a simplified notation, $\hX_{jh}^{h,(i)}$ is already defined via some interacting particle system, as in Equation \eqref{Eq:Sec7}. Let $K_\varepsilon:\mathbb{R}\rightarrow\mathbb{R}$ be a kernel function parameterized by $\varepsilon$ such that $K_\eps$ converges to the Dirac distribution $\delta_0$ as $\eps\rightarrow 0$. 
Then we define for $j\ge 1$
\begin{align}\label{eq_hEeps}
    \hE^{\eps,N}\bigl[\bigl(\xi_{jh}^{(i)}\bigr)^2\big|\hX_{jh}^{h,(i)}\bigr]=
    \begin{cases}
        \frac{\sum_{k=1}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(\hX_{jh}^{h,(i)}-\hX_{jh}^{h,(k)}\bigr)}{\sum_{k=1}^N  K_\eps\bigl(\hX_{jh}^{h,(i)}-\hX_{jh}^{h,(k)}\bigr)} & \text{for } j \ge 1,
        \\
        \E[\bigl(\xi_{0}^{(i)}\bigr)^2\bigr]
        & \text{for } j=0
    \end{cases}.
\end{align}
This estimator is also referred to as Nadaraya-Watson estimator. It has the great advantage that the approximation of the conditional expectation depends smoothly on the condition $\hX_{jh}^{h,(i)}.$ To balance the singularities of the fraction, similarly to Section \ref{Sec:Half_Step}, we reintroduce the regularisation parameter $\delta>0$ for the estimator 
\begin{align}\label{eq_hEepsdelta}
    \hE_{\delta}^{\eps,N}\bigl[\bigl(\xi^{(i)}_{jh}\bigr)^2\big|\hX_{jh}^{h,(i)}\bigr]=
    \begin{cases}
        \frac{\frac1N\sum_{k=1}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(\hX_{jh}^{h,(i)}-\hX_{jh}^{h,(k)}\bigr)+\delta}{\frac1N\sum_{k=1}^N  K_\eps\bigl(\hX_{jh}^{h,(i)}-\hX_{t}^{h,(k)}\bigr)+\delta} & \text{for } j \ge 1,
        \\
         \E[\bigl(\xi_{0}^{(i)}\bigr)^2\bigr]
        & \text{for } j=0
    \end{cases}.
\end{align}
Note that for $j=0$ we have the equality $  \hE^{\eps,N}\bigl[\bigl(\xi_{0}^{(i)}\bigr)^2\big|\hX_{0}^{h,(i)}\bigr]= \hE^{\eps,N}_\delta\bigl[\bigl(\xi_{0}^{(i)}\bigr)^2\big|\hX_{0}^{h,(i)}\bigr]=\hE[\bigl(\xi_{0}^{(i)}\bigr)^2\bigr]$.
This method was also proposed in \cite{GuyonHL2013}, where the authors introduced this method for a practical audience and has been further developed in \cite{Muguruza2019}, where the author proposes a similar algorithm but the kernels $K_\eps$ also depend on the particles.

The computation time is of order $N^2$, which makes good simulations computationally expensive. In other applications, comparable to estimating at just one single time point the so-called \emph{one-fifth-rule}, see for example \cite[Section 2.2.1]{LiScott07}, is used, i.e.\ one chooses $\eps \approx N^{-1/5}$.
 For the Kernel $K_\eps$ we have the following
 \pagebreak[2]
\begin{assumption}\label{Ass:kernel}
    For $\eps>0$ we define a function $K_\eps: \mathbb{R}\rightarrow [0,\infty)$ satisfying the following properties:
    \begin{enumerate}
        \item \emph{$L^1$-Scaling:} $K_\eps(\cdot)=\frac1\eps K_1\bigl(\frac\cdot\eps\bigr)$,
        \item \emph{Compact support:} $\operatorname{supp} K_1 \subseteq [-1,1]$,
        \item \emph{Regularity:}
        $K_1 \in C_1$,
        \item \emph{Stability near zero:} There is a constant $c$ such that $K_1 \ge c\one_{(-\frac12,\frac12)}$.
    \end{enumerate}
\end{assumption}
\begin{example}
    The function 
    \begin{align*}
        K_1(x)=\max\Bigl\{\bigl( 1- x^2\bigr),0\Bigr\}^2
    \end{align*}
satisfies Assumption \ref{Ass:kernel}, 2.-4.\end{example}




\begin{remark}[Kernel Method]
    In  \cite{BayerEtal2022} the authors introduced a kernel method for approximating conditional expectation: similar to the particle method the idea is to approximate the function determined by the conditional expectation and not the (stochastic) random variable by itself. 
Recall that for $\xi,X \in L^1$ the conditional expectation is given by $\E\bigl[\xi\big|X\bigr]=f\bigl(X\bigr)$ where
\begin{align*}
    f=\operatorname*{argmin}_{g \in \mathcal{L}^0} \E\bigl[\bigl(g(X)-\xi\bigr)^2 \bigr].
\end{align*}
Here $\mathcal{L}^0$ denotes the class of measurable functions $g:\mathbb{R}\rightarrow \mathbb{R}$. The authors then introduced a class of functions $\mathcal{H}$, corresponding to a reproducing kernel Hilbert space endowed with a scalar product $\langle .,. \rangle_{\mathcal{H}}$ as well as a regularizing parameter $\theta>0$. They then proposed the ridge regression
\begin{align*}
    f\approx \operatorname*{argmin}_{g \in \mathcal{H}} \Bigl\{ \E\bigl[\bigl(g(X)-\xi\bigr)^2 \bigr] + \theta \|g\|_{\mathcal{H}}\Bigr\}.
\end{align*}
If the function of the conditional expectation is already in the reproducing kernel Hilbert space, then this yields a very good approximation. For more general functions, that are not element in the RKHS, one can obtain good approximations if the function is in the completion of the RKHS w.r.t.\ a suitable metric.
\end{remark}


\subsection{Approximation: Kernel Method and Regularisation}\label{Sec:Cond_exp_estim}


We start this section by showing $L^p$ convergence for the Nadaraya-Watson estimator.



We define the regularized Euler scheme for some arbitrary $\eps,\delta \in (0,1)$
\begin{gather}\label{eq_Xhepsdelta} 
\begin{aligned}
    \hX_{jh+h}^{h,\eps,\delta}&=\hX_{jh}^{h,\eps,\delta}+\frac{\xi_{jh}\sigma\bigl(jh,\hX_{jh}^{h,\eps,\delta}\bigr)}{\sqrt{\hE_\delta^\eps\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}} \bigl(W_{jh+h}-W_{jh}\bigr),
    \\
    \hX_0^{h,\eps,\delta}&=x_0.
\end{aligned}
\end{gather}
\begin{remark}
    Due to the ellipticity assumption the condition $\mathbb{V}(\hX_{jh}^{h,\eps,\delta})=0$ in Definition \ref{Def_hEepsdelta} is satisfied if and only if $j=0$, making the choice of the estimator similar to the one for the particle system in Equation \eqref{eq_hEepsdelta} above.
\end{remark}
Similar to Theorem \ref{thm_HScondExp_err} above we can now quantify the error introduced by the estimator $\hE_\delta^\eps$ in the following theorem.
\begin{theorem}\label{thm_condExp_err}
        Suppose Assumptions \ref{Ass:Half_Step} and \ref{Aspt_new} hold. Let $K_\eps$ satisfy Assumption \ref{Ass:kernel}. Let $h,T>0$ such that $T/h\in{\mathbb N}$, $\eps,\delta \in (0,1)$ and $ \hX_{jh}^{h,\eps,\delta}$ be defined in Equation \eqref{eq_Xhepsdelta} for $j\in \{0,\dots,\frac Th\}$. Recall $\lambda$ from Equation \eqref{Eq_lambda}.
        Let $f$ be three times differentiable with derivatives of polynomial growth, then it holds for any $p>1$ that
        \begin{align}\label{Eq:CondExp_Err_2}
            \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,\eps,\delta}\bigr)\bigr]\Bigr|\lesssim h + \eps h^{-1} e^{\frac {\eps^2}{\lambda}} + \delta^{\frac1p}.
        \end{align}
         Here the hidden constant explodes as $p\rightarrow 1$ or $p \rightarrow \infty$.
\end{theorem}


\begin{remark}
    The proof of Lemma \ref{Lem:FrakCBound} and the definition of $\lambda$ shows that the second term explodes as $\rhobar \rightarrow 0$. As $\lambda$ linearly depends on $h$, the exponential in the second term is no issue as one would choose $\eps\lesssim h$ anyway to have small contribution from the term $\eps h^{-1}$. 
\end{remark}


\begin{lemma}\label{Lem_regular_kernel} Assume the setting of Theorem \ref{thm_condExp_err} and recall $\hE^\eps_\delta$ from Definition \ref{Def_hEepsdelta}. 
    Then for any $p\ge 1$ it holds that 
    %
    \begin{align*}
        \Bigl\| \hE_\delta^\eps\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr]-\hE^\eps\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr] \Bigr\|_{L^p} \lesssim 
        \Bigl(\delta \sqrt{-\log(\delta)}\Bigr)^{\frac1p}.
    \end{align*}
\end{lemma}
\begin{proof}
    The proof is the same as the proof as Lemma \ref{Lem_regularisation}, with $K_\eps=\varphi_\lambda$ and by replacing $\sqrt{\lambda}$ by $\varepsilon$. 
    Note that  Assumption \ref{Ass:kernel} tells us, that for any positive function $f$ it holds that 
    \begin{align*}
         \int_{-1}^{1} K_1({y}) f(x+\eps y)\,dy 
       \gtrsim \int_{-\frac12}^{\frac12} f(x+\eps y)\,dy.
    \end{align*}
\end{proof}


      \begin{lemma}\label{Lem:FrakCBound}
          Assume the setting of Theorem \ref{thm_condExp_err} and recall $\hE^\eps_\delta$ from Definition \ref{Def_hEepsdelta}. It holds for  $j \in \{1,\dots,\frac Th\}$ that
          \begin{align*}
               \Bigl\| \E\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr]-\hE^\eps\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr] \Bigr\|_{L^p}
               \lesssim \eps h^{-1} e^{\frac {\eps^2}{\lambda}}
          \end{align*}
      \end{lemma}
      \begin{proof}
            We fix some index $j \in \{1,\dots,T/h\}$. 
            Under Assumption \ref{Ass:Half_Step} we can write 
            \begin{align*}
                \hX_{jh}^{h,\eps,\delta}&=\hX_{jh-h}^{h,\eps,\delta}+\frac{\xi_{jh-h}\sigma\bigl(jh-h,\hX_{jh-h}^{h,\eps,\delta}\bigr)}{\sqrt{\hE_\delta^\eps\bigl[\xi_{jh-h}^2\big|\hX_{jh-h}^{h,\eps,\delta}\bigr]}} 
                \rho
                \bigl(B_{jh}-B_{jh-h}\bigr)
                \\
                &\qquad \qquad + \frac{\xi_{jh-h}\sigma\bigl(jh-h,\hX_{jh-h}^{h,\eps,\delta}\bigr)}{\sqrt{\hE_\delta^\eps\bigl[\xi_{jh-h}^2\big|\hX_{jh-h}^{h,\eps,\delta}\bigr]}} 
                \rhobar
                \bigl(\bB_{jh}-\bB_{jh-h}\bigr),
            \end{align*}
            for two independent Brownian motions $B$ and $\bB$ such that $\xi$ and $\bB$ are independent.


           We can apply Lemma \ref{Lem:Density} with $Z_1= \hX_{jh}^{h,\eps,\delta}$, $\eta=\rhobar \frac{\xi_{jh-h}\sigma(jh-h,\hX_{jh-h}^{h,\eps,\delta})}{\sqrt{\hE_\delta^\eps[\xi_{jh-h}^2|\hX_{jh-h}^{h,\eps,\delta}]}}$ 
           and $Z_0=\hX_{jh-h}^{h,\eps,\delta}+\rho \frac{\xi_{jh-h}\sigma(jh-h,\hX_{jh-h}^{h,\eps,\delta})}{\sqrt{\hE_\delta^\eps[\xi_{jh-h}^2|\hX_{jh-h}^{h,\eps,\delta}]}}(B_{jh}-B_{jh-h})$. 
           Note that $\eta >\rhobar c_{min}$.
           %
           We denote $Z_1=\hX_{jh}^{h,\eps,\delta}$ and $\xi\coloneqq \xi_{jh-h}$.
           By independence of $(Z_0,\xi)$ and $\Delta \bB_{jh-h}\coloneqq (\bB_{jh}-\bB_{jh-h}\bigr)$, the density of $Z_1$ with respect to the Lebesgue measure is 
           $f_{Z_1}(x)=\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr) \Bigr]$ and for $\psi:\R\to\R$ measurable and bounded,
           \begin{align*}
               \E\bigl[ \xi^2\psi(Z_1)\bigr]=\E\Bigl[\int_\R\xi^2\psi(Z_0+x)\varphi_{h\eta^2}\bigl(x\bigr)dx\Bigr]=\int_\R \E\Bigl[\xi^2\varphi_{h\eta^2}\bigl(x-Z_0\bigr) \Bigr]\psi(x)dx
           \end{align*}
           so that
           \begin{align*}\E\bigl[ \xi^2|Z_1\bigr]&=m(Z_1)\mbox{ with}\\
        m(x)&:= \frac1{f_{Z_1}(x)}\E\Bigl[\xi^2 \varphi_{h\eta^2}\bigl(x-Z_0\bigr) \Bigr].
    \end{align*}





        We use the tower property of conditional expectation and see by the support properties in Assumption \ref{Ass:kernel} that there is some ($\mathcal{F}_{jh}$-measurable) $x^*$ taking values in $(x-\eps,x+\eps)$ such that
\begin{align*}
        \E\bigl[\xi^2\big|Z_1\bigr]-\frac{\E\bigl[K_\eps(Z_1-x)\xi^2]}{\E\bigl[K_\eps(Z_1-x)]}\bigg|_{x=Z_1}
        \\&=
        \frac{\E\bigl[m(x)K_\eps(Z_1-x)\bigr]-\E\Bigl[K_\eps(Z_1-x)\E\bigl[\xi^2\big|Z_1\bigr]\Bigr]}{\E\bigl[K_\eps(Z_1-x)]}\bigg|_{x=Z_1}
        \\&=
        \frac{\E\bigl[m(x)K_\eps(Z_1-x)\bigr]-\E\bigl[K_\eps(Z_1-x)m(Z_1)\bigr]}{\E\bigl[K_\eps(Z_1-x)]}\bigg|_{x=Z_1}
        \\
        &=\frac{\E\bigl[\bigl(Z_1-x\bigr)m'\bigl(x^*\bigr)K_\eps(Z_1-x)\bigr]}{\E\bigl[K_\eps(Z_1-x)]}\bigg|_{x=Z_1}
        \\
        &\le \eps\sup_{z \in (Z_1-\eps,Z_1+\eps)}|m'(z)|.
    \end{align*}
    By the chain rule the derivative is given by
    \begin{align*}
        m'(x)=\frac1{f_{Z_1}(x)} \E\Bigl[\xi^2 \partial_x \varphi_{h\eta^2}\bigl(x-Z_0\bigr) \Bigr] - \frac1{f_{Z_1}^2(x)}\E\Bigl[\xi^2 \varphi_{h\eta^2}\bigl(x-Z_0\bigr) \Bigr]\E\Bigl[\partial_x\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr]. 
    \end{align*}
    Recall that $\xi^2$ is bounded and that for $\lambda>0$, $\partial_x \varphi_\lambda(x)=-\frac x\lambda \varphi_\lambda(x)$.  The fact that $\eta$ is bounded from below and the boundedness of $m(x)=\frac1{f_{Z_1}(x)}\E\bigl[\xi^2 \varphi_{h\eta^2}\bigl(x-Z_0\bigr) \bigr]$ imply that
    \begin{align*}
        \bigl|m'(x)\bigr|\lesssim \frac{2}{h} \frac{\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\bigl|x-Z_0\bigr|\Bigr]}{\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr]}.
    \end{align*}


    We now want to find an upper bound of the r.h.s.\
    whose $p$-th power is integrable w.r.t.\ the density of $Z_1$. We introduce an auxiliary parameter $\gamma\in(0,1)$ such that $\gamma \le \frac1{2p}$.
    By Lemma \ref{Lem:Gauss_facts} and Jensen's inequality, as well as the boundedness of $\eta$ from below,
    \begin{align*}
        \bigl|m'(x)\bigr|\lesssim h^{-1+1/2-\gamma/2} \gamma^{-1/2} \frac{\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)^{1-\gamma}\Bigr]}{\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr]}
        \lesssim h^{
        -\frac{1+\gamma}2} \gamma^{-\frac12} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr]^{-\gamma}.
    \end{align*}
    Lemma \ref{Lem:Gauss_facts} furthermore tells us that, recalling $h\eta^2 \ge \lambda$ with $\lambda$ defined in \eqref{Eq_lambda},
    \begin{align*}
        \sup_{z \in (x-\eps,x+\eps)}|m'(z)| &\lesssim  h^{
        -\frac{1+\gamma}2} \gamma^{-\frac12}\Bigl(e^{\frac{\eps^2}{\gamma \lambda}} \sqrt{h}^{-\gamma}\Bigr)^{\gamma}\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)^{1+\gamma}\Bigr]^{-\gamma}
        \\
        &\lesssim  \underbrace{h^{
        -\frac{1+\gamma+\gamma^2}2} \gamma^{-\frac12}e^{\frac{\eps^2}{ \lambda}}}_{C_{h,\gamma}} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)^{1+\gamma}\Bigr]^{-\gamma}.
    \end{align*}
    Using our representation of $f_{Z_1}$, Jensen's inequality and once more Lemma \ref{Lem:Gauss_facts} imply
    \begin{align*}
    \Bigl\| \E\bigl[\xi_{}^2| Z_1 \bigr]-\hE^\eps\bigl[\xi_{}^2| Z_1 \bigr] \Bigr\|_{L^p}^p
    &\lesssim
    \eps^p
        \Bigl\|
        \sup_{z \in (Z_1-\eps,Z_1+\eps)}m'(z)
        \Bigr\|_{L^p}^p 
        \\
        &\lesssim \eps^p C_{h,\gamma}^p \int_{\mathbb{R}} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)^{1+\gamma}\Bigr]^{-\gamma p} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr] \,dx
        \\
        &\lesssim \eps^p
        C_{h,\gamma}^p \int_{\mathbb{R}} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)^{1+\gamma}\Bigr]^{\frac{1}{1+\gamma}-\gamma p}  \,dx
        \\
        &\lesssim \eps^p
        C_{h,\gamma}^p {h}^{-\frac\gamma2\bigl(\frac{1}{1+\gamma}-\gamma p\bigr)}\int_{\mathbb{R}} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr]^{\frac{1}{1+\gamma}-\gamma p}  \,dx.
    \end{align*}
    We now try to find a value for $\gamma$, that can depend on $p$, such that the last integral remains finite. 
    Denoting $\beta_{\gamma,p}=\frac{1}{1+\gamma}-\gamma p \in (0,1),$ it follows from H\"older's inequality that
    \begin{align*}
        \int_{\mathbb{R}} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)&\Bigr]^{\beta_{\gamma,p}}  \,dx =\int_{\mathbb{R}} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr]^{\beta_{\gamma,p}} \frac{1+x^2}{1+x^2} \,dx 
        \\
        &\le \biggl(\int_{\mathbb{R}} \E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr] \bigl({1+x^2}\bigr)^{\frac{1}{\beta_{\gamma,p}}} \,dx\biggr)^{\beta_{\gamma,p}} \biggl(\int_{\mathbb{R}}\Bigl(\frac{1}{1+x^2}\Bigr)^{\frac1{1-\beta_{\gamma,p}}} \,dx \biggr)^{1-\beta_{\gamma,p}}.
    \end{align*}
    We choose $\gamma = \frac 1{4p}$, ensuring that $\frac14\le \beta_{1/(4p),p} \le \frac34$, meaning that we have bounds that do not depend on $p$.
    Lemma \ref{lem:Tail_estim} guarantees the boundedness of
    \begin{align*}
       \biggl(\int_{\mathbb{R}} &\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr)\Bigr] \bigl({1+x^2}\bigr)^{\frac{1}{\beta_{1/(4p),p}}} \,dx\biggr)^{\frac{\beta_{1/(4p),p}}{p}} \biggl(\int_{\mathbb{R}}\Bigl(\frac{1}{1+x^2}\Bigr)^{\frac1{1-\beta_{1/(4p),p}}} \,dx \biggr)^{\frac{1-\beta_{1/(4p),p}}{p}}
       \\
        &\lesssim \E\Bigl[ \bigl(1+Z_1^2\bigr)^4 \Bigr].
    \end{align*}
    Basic algebra tells us that
    \begin{align*}
        C_{h,\gamma}{h}^{-\frac\gamma{2p}\bigl(\frac{1}{1+\gamma}-\gamma p\bigr)}&=
        C_{h,1/(4p)}{h}^{-\frac1{8p^2}\beta_{1/(4p),p}}
        \\
        &=
        \exp\Bigl(\log(h)\Bigl( 
        -\frac{1+\frac1{4p}+\frac1{16p^2}}2 -\frac1{8p^2}\beta_{1/(4p),p}\Bigr)\Bigr) (4p)^{\frac12}e^{\frac{\eps^2}{ \lambda}}
        \\
        &\lesssim \exp\Bigl(\log(h)\Bigl( 
        -\frac12-\frac1{p}\Bigl(\frac18+\frac1{32p}+\frac1{8p}\times\frac34
        \Bigr)
        \Bigr)\Bigr) \sqrt{p} e^{\frac{\eps^2}{ \lambda}}
        \\
        & \lesssim h^{-1} e^{\frac {\eps^2}{\lambda}}.
    \end{align*}
    Combining everything and substituting back we see that
    \begin{align*}
         \Bigl\| \E\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr]-\hE^\eps\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr] \Bigr\|_{L^p}
         \lesssim \eps h^{-1} e^{\frac {\eps^2}{\lambda}}.
    \end{align*}

      \end{proof}


\begin{proof}[Proof of Theorem \ref{thm_condExp_err}]
        Theorem \ref{Thm:Rate_CondExp} tells us that
        \begin{align*}
        \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f(\hX_T^{h,\eps,\delta})\bigr]\Bigr|\lesssim h+\sup_{j\in\{0,\dots,\frac Th\}} \bigl\| {\hE_\eps^\delta\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}
        -{\E\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}\bigr\|_{L^p}.
    \end{align*}
    For $j=0$, by definition ${\hE_\eps^\delta\bigl[\xi_{0}^2\big|\hX_{0}^{h,\eps,\delta}\bigr]}
        ={\E\bigl[\xi_{0}^2\big|\hX_{0}^{h,\eps,\delta}\bigr]}=\E[\xi_0^2]$, hence the difference above is equal to $0$.
    Let $q$ such that $1< q<p$. Basic triangle inequality tells us that
    \begin{align*}
            \bigl\| {\hE^\eps_\delta\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}
        -{\E\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}\bigr\|_{L^q}
        &\le  
         \bigl\| {\hE^\eps\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}
        -{\hE_\delta^\eps\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}\bigr\|_{L^q}
        \\
        &\qquad + 
        \bigl\| {\hE^\eps\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}
        -{\E\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}\bigr\|_{L^q} .
        \end{align*}
        Lemma  \ref{Lem_regular_kernel} tells us, uniformly for all $j \in \{1,\dots,\frac Th\}$
        \begin{align*}
             \bigl\| {\hE^\eps\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}
        -{\hE_\delta^\eps\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}\bigr\|_{L^q}
        \lesssim
        \Bigl(\delta \sqrt{-\log(\delta)}\Bigr)^{\frac1 q}.
        \end{align*}
        By Lemma  \ref{Lem:FrakCBound} we observe that, again uniformly for all $j \in \{1,\dots,\frac Th\}$
        \begin{align*}
             \bigl\| {\hE^\eps\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}
        -{\E\bigl[\xi_{jh}^2\big|\hX_{jh}^{h,\eps,\delta}\bigr]}\bigr\|_{L^q} 
        \lesssim 
        \eps h^{-1} e^{\frac {\eps^2}{\lambda}}
        .
        \end{align*}
        The claim then follows by combining these estimates and from the fact that $\bigl(\delta \sqrt{-\log(\delta)}\bigr)^{\frac1q}\lesssim \delta^{\frac1p}$ as well as the monotonicity of $L^p$ norms.
    \end{proof}

\subsection{Propagation of Chaos for Euler Scheme}\label{Sec:POC}
In this section we fix the stepsize $h$, as well as the regularisation parameters $\eps,\delta\in(0,1)$. For $i \in \{1,\dots,N\}$ we will denote the $i$-th particle by the superscript $(i)$. 
Let $\bigl( W^{(i)})_{i=1}^N$ be independent Brownian motions. Let $\Delta W^{(i)}_{jh}=W^{(i)}_{jh+h}-W^{(i)}_{jh}$ and assume that $\frac Th\in \mathbb{N}$. Let $\mu_{jh}=\mathcal{L}\bigl({\xi_{jh},\hX_{jh}^{h,(1),\eps,\delta}}\bigr)$ and recall the notation $\hPsi_j$ from \eqref{Eq:PsiHat_Def}. For $j\in \{0,\dots,\frac Th-1\}$,  we consider independent copies of the following non-interacting particle scheme 
\begin{align*}
    \hX_{jh+h}^{h,(i),\eps,\delta}&=\hX_{jh}^{h,(i),\eps,\delta}+ \sigma(jh,\hX_{jh}^{h,(i),\eps,\delta})\xi_{jh}^{(i)}  \hPsi_j^{-\frac12}\bigl(\hX_{jh}^{h,(i),\eps,\delta},\mu_{jh}\bigr)\Delta W_{jh}^{(i)},
    \\
    \hX_0^{h,(i),\eps,\delta}&=x_0,
    \\
    \mu_{jh}&=\mathcal{L}\bigl({\xi_{jh},\hX_{jh}^{h,(1),\eps,\delta}}\bigr).
\end{align*}
Furthermore we recall the interacting particle scheme
\begin{align}\label{Eq:XhatEpsN}
    \hX_{jh+h}^{h,(i),N,\eps,\delta}&=\hX_{jh}^{h,(i),N,\eps,\delta}+ \sigma(jh,\hX_{jh}^{h,(i),N,\eps,\delta})\xi_{jh}^{(i)} \hPsi_j^{-\frac12}\bigl(\hX_{jh}^{h,(i),N,\eps,\delta},\mu^N_{jh}\bigr)\Delta W_{jh}^{(i)},
    \\
    \hX_0^{h,(i),N,\eps,\delta}&=x_0,\nonumber
\end{align}
where, for $j\ge 1$ we denote by $\mu_{jh}^N$  the empirical measure of the interacting particle system, $\mu_{jh}^N(dx,dy)=\frac1N \sum_{j=1}^N \delta_{\xi_{jh}^{(i)},\hX_{jh}^{h,(i),N,\eps,\delta}}(dy,dx)$ and for consistency we set $\mu_0^N=\mu_0$. 
\begin{remark}\label{Rem_PsiHat}
    Recall that, for $j\ge 1$, by definition the function $\hPsi_j$ depends on $\eps$ and $\delta$ via
    \begin{align*}
        \hPsi_j^{-1}\bigl(y,\mu^N_{jh} \bigr)&=\frac
        {
        \frac1N \sum_{k=1}^N   K_\eps\bigl( y-\hX_{jh}^{h,(k),N,\eps,\delta} \bigr)+\delta
        }
        { {\frac1N \sum_{k=1}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl( y-\hX_{jh}^{h,(k),N,\eps,\delta}\bigr)}+\delta},        
        \\
        \hPsi_j^{-1}\bigl(y,\mu_{jh}\bigr)&= \frac{
        \E\bigl[ K_\eps\bigl(y-\hX_{jh}^{h,(1),\eps,\delta}\bigr)\bigr]+\delta
        }{{\E\bigl[ \bigl(\xi_{jh}^{(1)}\bigr)^2K_\eps\bigl(y-\hX_{jh}^{h,(1),\eps,\delta}\bigr)\bigr]}+\delta }.
    \end{align*}
    Also, by convention
    \begin{align*}
        \hPsi_0^{-1}\bigl(y,\mu_{0} \bigr)=\hPsi_0^{-1}\bigl(y,\mu^N_{0} \bigr)=\frac1{\E[\xi_0^2]}.
    \end{align*}
    In particular the function $\hPsi_j$ satisfies $\hPsi_j( \hX_{jh}^{h,(i),N,\eps,\delta},\mu_{jh}^N)=\hE_\delta^{\eps,N}[(\xi_{jh}^{(i)})^2| \hX_{jh}^{h,(i),N,\eps,\delta}]$ for $\hE_\delta^{\eps,N}$ defined in  Equation \eqref{eq_hEepsdelta} above.
\end{remark}
\begin{theorem}\label{Lem:Prop_of_chaos}
    Under Assumption \ref{Aspt_new} and \ref{Ass:kernel} the following hold:
    \begin{enumerate}[(i)]
        \item   There is a constant $C>0$ such that
        \begin{align*}
        \Bigl\| \hX_T^{h,(1),\eps,\delta} - \hX_T^{h,(1),N,\eps,\delta} \Bigr\|_{L^2} \lesssim \eps
        \exp\Bigl(C \delta^{-2} \eps^{-4}\Bigr)  N^{-1/2}.
    \end{align*}
    \item  If $\eps\lesssim h$ there is a constant $\tilde C$ such that
    \begin{align*}
         \Bigl\| \hX_T^{h,(1),\eps,\delta} - \hX_T^{h,(1),N,\eps,\delta} \Bigr\|_{L^2} 
        &\lesssim \eps
        \exp\Bigl(\frac T2h^{-1}
        \log\bigl( \tilde C h \delta^{-2}\eps^{-4}\bigr)\Bigr)N^{-1/2}.
    \end{align*}
    \end{enumerate}


\end{theorem}

\begin{proof}[Proof of Theorem \ref{Thm_Particle_Rate2}]
    We distribute the error
    \begin{align*}
        \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,(1),N,\eps,\delta}\bigr)\bigr]\Bigr| 
        &\le 
        \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,\eps,\delta}\bigr)\bigr]\Bigr|
        \\&+
        \Bigl|\E\bigl[ f(\hX_T^{h,\eps,\delta})\bigr]-\E\bigl[f\bigl(\hX_T^{h,(1),N,\eps,\delta}\bigr)\bigr]\Bigr|.
    \end{align*}
    There now exists for all $p>1$ a constant $C>0$ such that
    \begin{align*}
        \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,\eps,\delta}\bigr)\bigr]\Bigr|
        &\lesssim  h +  \eps h^{-1} e^{\frac {\eps^2}{\lambda}}
        + \delta^{\frac1p} &
        \text{ due to Theorem \ref{thm_condExp_err},}
          \\
        \Bigl|\E\bigl[ f(\hX_T^{h,\eps,\delta})\bigr]-\E\bigl[f\bigl(\hX_T^{h,(1),N,\eps,\delta}\bigr)\bigr]\Bigr| &\lesssim  \eps
        \exp\Bigl(
        \frac T{2}h^{-1} \log\bigl( C h \delta^{-2}\eps^{-4}\bigr)\Bigr)N^{-1/2} \hspace{-5pt}&
        \text{ due to Theorem \ref{Lem:Prop_of_chaos}.}
    \end{align*} 
    For the second inequality we also used the fact that $f$ is locally Lipschitz-continuous with derivative of polynomial growth.
    Recalling $\lambda=h\rhobar^2 c_{min}^2$ and using the assumption that  $\eps\lesssim h$ we observe that $e^{\eps^2/\lambda}\lesssim 1$.
    Summing up these terms and choosing $p$ arbitrarily close to $1$ completes the proof.
\end{proof}

\begin{remark}\label{Rem:Rate}
    Theorem \ref{Thm_Particle_Rate2} above provides a manual how to choose the parameters in order to achieve any desired error.
    Let $\gamma>0$ and suppose we want an error of order $\gamma$, i.e. 
    \begin{align*}
        \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,(i),N,\eps,\delta}\bigr)\bigr]\Bigr|
        \lesssim 
        \gamma.
    \end{align*}
    One would choose stepsize $h \approx \gamma$, kernel bandwidth $\eps \approx \gamma^{2}$, regularisation $\delta \approx \gamma$ and particle size $N \approx \gamma^{2}\exp\bigl(T\gamma^{-1} \log(C \gamma^{-9} )\bigr)$. 
\end{remark}

\begin{remark}\label{Remark_Correlation}
Let us briefly sketch how to derive a weak error rate in the style of Theorem \ref{Thm_Particle_Rate2} without Assumption \ref{Ass:Half_Step}, under the (admittedly hard to verify) assumption that the function
$x\mapsto \E[ \xi_{jh}| \hX_{jh}^{h,\eps,\delta}=x]$ is $\alpha$-Hölder continuous uniformly for all $j \in \{1,\dots, \frac Th\}$ as well as $\eps, \delta \in (0,1/2)$. In this case
    \begin{align*}
        \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,(1),N,\eps,\delta}\bigr)\bigr]\Bigr|
        &\lesssim 
        h +  \eps^\alpha  + \delta^{\frac1p}  
        + \frac1{\sqrt{N}}\eps^{-1}
        \exp\Bigl(\frac T2
        h^{-1} \log\bigl(  C h \delta^{-2}\eps^{-4}\bigr)\Bigr).
    \end{align*}
Indeed, using H\"older regularity, it is not hard to
show (essentially using compact support of $K_\eps$) that
    \begin{align*}
         \Bigl\| \E\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr]-\hE^\eps\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr] \Bigr\|_{L^\infty} \lesssim 
        \eps^\alpha,
    \end{align*}
    which should be compared with Lemma \ref{Lem:FrakCBound} (which also provides an estimate for the left-hand side above). One can then copy the proof of Theorem \ref{Thm_Particle_Rate2} by replacing  the right-hand side provided in the said lemma with $\eps^\alpha$ above.
    \end{remark}




\begin{lemma}\label{Lem:G_deriv}
    Let $\eps,\delta \in (0,1)$ and $\mu\in \mathcal{P}_2(\mathbb{R}\times\mathbb{R})$  induced by some random variables $(\xi,X)$ such that $\xi$ is bounded from above and below, similar to Assumption \ref{Aspt_new}.  Let $K_\eps$ satisfy Assumption \ref{Ass:kernel}, $j \ge 0$ and $\hPsi_j$ with its dependence on $\eps$ and $\delta$ be as in Equation \eqref{Eq:PsiHat_Def}. Then the map $y \mapsto \hPsi_j^{-\frac12}(y,\mu)$ is Lipschitz with constant
    \begin{align*}
        \|\hPsi^{-\frac12}\|_{Lip}\le \frac{1}{\delta} \|K_\eps'\|_{\infty}.
    \end{align*}
\end{lemma}
\begin{proof}
    Recall that that $\xi$ is bounded and bounded away from $0$. For $j=0$ the function $\hPsi_0$ does not depend on $y$, hence the statement is correct.

    Assume now $j \ge 1$.
      Chain rule implies that
    \begin{align*}
        \frac{\partial}{\partial y} \hPsi_j^{-\frac12}(y,\mu)&=\frac12\sqrt{ \frac{{\E\bigl[ \xi^2K_\eps\bigl(y-X\bigr)\bigr]}+\delta }{
        \E\bigl[ K_\eps\bigl(y-X\bigr)\bigr]+\delta
        }
        }
        \Biggl(
        \frac{
        \E\bigl[ K_\eps'\bigl(y-X\bigr)\bigr] 
        \Bigl(
        \E\bigl[ \xi^2K_\eps\bigl(y-X\bigr)\bigr]+\delta
        \Bigr)      }
        {
        \Bigl({{\E\bigl[ \xi^2K_\eps\bigl(y-X\bigr)\bigr]}+\delta }\Bigr)^2}
        \\
        & \qquad \qquad \qquad 
        - 
        \frac{
        \Bigl(\E\bigl[ K_\eps\bigl(y-X\bigr)\bigr] +\delta\Bigr)
        \E\bigl[ \xi^2K_\eps'\bigl(y-X\bigr)\bigr]
        }
        {
        \Bigl({{\E\bigl[ \xi^2K_\eps\bigl(y-X\bigr)\bigr]}+\delta }\Bigr)^2}
        \Biggr)
        \\
        &\lesssim \frac{\|K_\eps\|_{C_1}}{\delta}.
    \end{align*}
    For the last inequality we used that $\xi$ is bounded from above by assumption.
\end{proof}
Being provided with Lipschitz continuity of $\hPsi$ we are now able to show propagation of chaos.

\begin{proof}[Proof of Theorem \ref{Lem:Prop_of_chaos}]




For the rest of this proof we simplify the notation by writing $X_{jh}^{(i)}=\hX_{jh}^{h,(i),\eps,\delta}$ and $X_{jh}^{(i),N}=\hX_{jh}^{h,(i),N,\eps,\delta}$.
First note that by definition $X_0^{(i)}=X_0^{(i),N}$ and by Remark \ref{Rem_PsiHat} as well as the definition of the Euler schemes $X_h^{(i)}=X_h^{(i),N}$ for all $i \in \{1,\dots,N\}$.


    We now fix some index $i \in \{1,\dots,N\}$ and some index $j\in \{1,\dots,\frac Th-1\}$ and study the difference $X_{jh+h}^{(i)}-X_{jh+h}^{(i),N}$. Then
    \begin{align*}
        X_{jh+h}^{(i)}-X_{jh+h}^{(i),N}&=X_{jh}^{(i)}-X_{jh}^{(i),N} \\
        &\qquad + \Bigl(\sigma(jh,X_{jh}^{(i)})-\sigma(jh,X_{jh}^{(i),N})\Bigr)\xi_{jh}^i\hPsi_j^{-\frac12}\bigl(X_{jh}^{(i),N},\mu^N_{jh}
        \bigr)\,\Delta W_{jh}^{(i)} &\eqqcolon (1)
        \\ 
        &\qquad + \sigma(jh,X_{jh}^{(i)})\xi_{jh}^{(i)} \Bigl( \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu^N_{jh} \bigr) - \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i),N},\mu^N_{jh}\bigr) \Bigr) \Delta W_{jh}^{(i)} &\eqqcolon (2)
        \\ 
        &\qquad + \sigma(jh,X_{jh}^{(i)})\xi_{jh}^{(i)} \Bigl(
        \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu_{jh}\bigr)
        -
        \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu^N_{jh} \bigr) \Bigr) \Delta W_{jh}^{(i)}
        . &\eqqcolon (3)
    \end{align*}   
    By Lemma \ref{Lem:G_deriv}, we get the estimate
    \begin{gather}
    \begin{aligned}\label{eq:chaosprop_1}
        \E\Bigl[(1)^2+(2)^2 \Bigr]&\lesssim \E\Bigl[(\|\partial_x\sigma\|^2_{L^\infty}+\|\hPsi_j^{-\frac12}\|_{Lip}^2) \Bigl(\Delta W_{jh}^{(i)} \Bigr)^2 \Bigl( X_{jh}^{(i)}-X_{jh}^{(i),N}\Bigr)^2\Bigr]
        \\
        &\lesssim \frac1{\delta^2} \|K_\eps\|_{C_1}^2h \E\Bigl[ \Bigl( X_{jh}^{(i)}-X_{jh}^{(i),N}\Bigr)^2\Bigr].
    \end{aligned}
    \end{gather}
    %
    We now want to estimate the term (3). 
    We start by rewriting
    \begin{align*}
        \hPsi_j^{-\frac12}\bigl(&X_{jh}^{(i)},\mu_{jh}\bigr)
        -
        \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu^N_{jh} \bigr) 
        \\
        &=
        \frac{
        \sqrt{
        \E\bigl[ K_\eps\bigl(y-X_{jh}^{(1)}\bigr)\bigr]+\delta
        }
        }{
        \sqrt{\E\bigl[ \bigl(\xi_{jh}^{(1)}\bigr)^2K_\eps\bigl(y-X_{jh}^{(1)}\bigr)\bigr]+\delta} }\Biggl|_{y=X_{jh}^{(i)}}
        - \frac
        {
        \sqrt{\frac1N \sum_{k=1}^N   K_\eps\bigl( X_{jh}^{(i)}-X_{jh}^{(k)} \bigr)+\delta
        }
        }
        { \sqrt{\frac1N \sum_{k=1}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl( X_{jh}^{(i)}-X_{jh}^{(k)}\bigr)+\delta}}
        \\
        &\quad +
        \frac
        {
        \sqrt{\frac1N \sum_{k=1}^N   K_\eps\bigl( X_{jh}^{(i)}-X_{jh}^{(k)} \bigr)+\delta}
        }
        { \sqrt{\frac1N \sum_{k=1}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl( X_{jh}^{(i)}-X_{jh}^{(k)}\bigr)+\delta}}
        -
        \frac{
        \sqrt{\frac1N \sum_{k=1}^N   K_\eps\bigl( X_{jh}^{(i)}-X_{jh}^{(k),N} \bigr)+\delta}
        }
        { \sqrt{\frac1N \sum_{k=1}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl( X_{jh}^{(i)}-X_{jh}^{(k),N}\bigr)+\delta}}
        \\
        &\eqqcolon \frac{\sqrt{\mathcal{A}_0^i+\delta}}{\sqrt{\mathcal{B}_0^i+\delta}}-\frac{\sqrt{\mathcal{A}^i_1+\delta}}{\sqrt{{\mathcal{B}^i_1}+\delta}}+\frac{\sqrt{\mathcal{A}^i_1+\delta}}{\sqrt{\mathcal{B}^i_1+\delta}}-\frac{\sqrt{\mathcal{A}^i_2+\delta}}{\sqrt{\mathcal{B}^i_2+\delta}}
    \end{align*}
    We can apply Lemma \ref{lem_sqt_estim} and see that
    \begin{align*}
        \E\Bigl[ \Bigl( \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu_{jh}\bigr)
        -
        \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu^N_{jh} \bigr) \Bigr)^2\Bigr] \lesssim \frac{1}{\delta^2}& \Bigl( 
        \E\bigl[ \bigl(\mathcal{A}_0^i-\mathcal{A}_1^i \bigr)^2\bigr]+\E\bigl[ \bigl(\mathcal{B}_0^i-\mathcal{B}_1^i \bigr)^2\bigr]
        \\
        &+\E\bigl[ \bigl(\mathcal{A}_1^i-\mathcal{A}_2^i \bigr)^2\bigr]+\E\bigl[ \bigl(\mathcal{B}_1^i-\mathcal{B}_2^i \bigr)^2\bigr]
        \Bigr).
    \end{align*}
    Note that by exchangeability $\E\bigl[\bigl(\xi_{jh}^{(i)}\bigr)^2K_\eps\bigl(y-X_{jh}^{(i)}\bigr)  \bigr]= \frac1N\sum_{k=1}^N \E\bigl[\bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(y-X_{jh}^{(k)}\bigr)  \bigr]$. We now consider the term $ \E[ (\mathcal{B}_0^i-\mathcal{B}_1^i )^2]$, exclude the $i$-th element which is of order $\|K_\eps\|_{L^\infty}^2N^{-2}$ in the sums that appear and use independence conditional on $X_{jh}^{(i)}$ to see that
    \begin{align*}
        \E\bigl[& \bigl(\mathcal{B}_0^i-\mathcal{B}_1^i \bigr)^2\bigr]=\E\Bigl[ \Bigl(\E\Bigl[ \frac1N\sum_{k=1}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(y-X_{jh}^{(k)}\bigr)  \Bigr]\Big|_{y=X_{jh}^{(i)}}-\frac1N\sum_{k=1}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(X_{jh}^{(i)}-X_{jh}^{(k)}\bigr) 
        \Bigr)^2\Bigr]
        \\
        &\lesssim
        \frac{\|K_\eps\|_{L^\infty}^2}{N^2}+ \E\Bigl[ \Bigl(\E\Bigl[ \frac1N\sum_{\substack{k=1 \\ k \not = i}
        }^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(y-X_{jh}^{(k)}\bigr)  \Bigr]\bigg|_{y=X_{jh}^{(i)}}-\frac1N\sum_{\substack{k=1 \\ k \not = i}}^N \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(X_{jh}^{(i)}-X_{jh}^{(k)}\bigr) 
        \Bigr)^2\Bigr]
        \\
        &\lesssim \frac {\|K_\eps\|_{L^\infty}^2} {N^2}+ \frac1N\E\Bigl[    \frac1N \sum_{\substack{k=1\\ k \not = i}
        }^N \E\Bigl[  \Bigl( \bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(y-X_{jh}^{(k)}\bigr) -\E\bigl[\bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl(y-X_{jh}^{(k)}\bigr) \bigr]\Bigr)^2   \Bigr]\bigg|_{y=X_{jh}^{(i)}}      \Bigr]
        \\
        &\lesssim \frac{\|K_\eps\|_{L^\infty}^2}N.
    \end{align*}
    With similar arguments it follows that $\E\bigl[ \bigl(\mathcal{A}_0^i-\mathcal{A}_1^i \bigr)^2\bigr]\lesssim \frac1N \|K_\eps\|_{L^\infty}^2$.
    The function $K_\eps$ has bounded derivative, therefore
    \begin{align*}
        \bigl(\mathcal{B}_1^i-\mathcal{B}_2^i \bigr)^2&=\biggl(\frac1N\sum_{k=1}^N  \Bigl(\bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl( X_{jh}^{(i)}-X_{jh}^{(k)}\bigr)-\bigl(\xi_{jh}^{(k)}\bigr)^2 K_\eps\bigl( X_{jh}^{(i)}-X_{jh}^{(k),N}\bigr)\Bigr)
        \biggr)^2 
        \\
        &\lesssim \biggl(\frac1N\sum_{k=1}^N\|K_\eps\|_{C_1}\Bigl|X_{jh}^{(k),N}-X_{jh}^{(k)}\Bigr|\biggr)^2
        \\
        &\lesssim \frac1N\sum_{k=1}^N\|K_\eps\|_{C_1}^2\Bigl(X_{jh}^{(k),N}-X_{jh}^{(k)}\Bigr)^2.
    \end{align*}
    For the last inequality we used Jensen's inequality. Similarly it follows that $\bigl(\mathcal{A}_1^i-\mathcal{A}_2^i \bigr)^2\lesssim \frac1N\sum_{k=1}^N\|K_\eps\|_{C_1}^2\Bigl(X_{jh}^{(k),N}-X_{jh}^{(k)}\Bigr)^2$.

    Putting these estimates together we see by independence of the Gaussian increment and boundedness of $\sigma$ that
    \begin{gather}
    \begin{aligned}
        \E\Bigl[ \Bigl(\sigma(jh,X_{jh}^{(i)})\xi_{jh}^{(i)} \Bigl(
        \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu_{jh}\bigr)
        &-
        \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu^N_{jh} \bigr) \Bigr) \Delta W_{jh}^{(i)}\Bigr)^2\Bigr]
        \\
        &\lesssim
        \E\Bigl[ \Bigl(
        \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu_{jh}\bigr)
        -
        \hPsi_j^{-\frac12}\bigl(X_{jh}^{(i)},\mu^N_{jh} \bigr) \Bigr)^2\Bigr] h
        \\
        &\lesssim \frac1N h\delta^{-2}\|K_\eps\|_{L^\infty}^2 + 
        h\delta^{-2}\|K_\eps\|_{C_1}^2 \E\Bigl[\frac1N\sum_{k=1}^N \Bigl(X_{jh}^{(k),N}-X_{jh}^{(k)}\Bigr)^2 \Bigr]\label{eq:chaosprop_2}
        \end{aligned}
    \end{gather}

    Combining \eqref{eq:chaosprop_1} and \eqref{eq:chaosprop_2} we see that there is a constant $C>0$ such that
    \begin{align*}
        \E\Bigl[ \Bigl( X_{jh+h}^{(i)}-X_{jh+h}^{(i),N}  \Bigr)^2   \Bigr]\le \Bigl(1 + &Ch\delta^{-2}\|K_\eps\|_{C_1}^2 \Bigr)\E\Bigl[ \Bigl( X_{jh}^{(i)}-X_{jh}^{(i),N}\Bigr)^2\Bigr] 
         \\
         &+ Ch\delta^{-2}\|K_\eps\|_{C_1}^2
         \E\Bigl[\frac1N\sum_{k=1}^N \Bigl(X_{jh}^{(k),N}-X_{jh}^{(k)}\Bigr)^2 \Bigr]
         +C \frac1Nh\delta^{-2}\|K_\eps\|_{L^\infty}^2.
    \end{align*}
    Summing up over $i$ we conclude that
    \begin{align*}
       \frac1N \sum_{i=1}^N \E\Bigl[ \Bigl( X_{jh+h}^{(i)}-X_{jh+h}^{(i),N}  \Bigr)^2   \Bigr]
       &\le 
       \Bigl(1 + 2Ch\delta^{-2}\|K_\eps\|_{C_1}^2 \Bigr) \E\Bigl[  \frac1N\sum_{i =1}^N \Bigl( X_{jh}^{(i)}-X_{jh}^{(i),N}  \Bigr)^2   \Bigr] 
       \\
       &\qquad+C \frac1Nh\delta^{-2}\|K_\eps\|_{L^\infty}^2.
    \end{align*}
    By Lemma \ref{lem:recurr_relation}  it follows that
    \begin{align*}
         \frac1N\sum_{i =1}^N \E\Bigl[ \Bigl( X_{jh+h}^{(i)}-X_{jh+h}^{(i),N}  \Bigr)^2   \Bigr]&\lesssim \frac1Nh\delta^{-2}\|K_\eps\|_{L^\infty}^2 
         \frac{\exp\Bigl(C {\delta^{-2}} \|K_\eps\|_{C_1}^2\Bigr)}
         {2Ch\delta^{-2}\|K_\eps\|_{C_1}^2}
         \\
         &\lesssim \frac1N
         \frac{\|K_\eps\|_{L^\infty}^2}
         {\|K_\eps\|_{C_1}^2}\exp\Bigl(C {\delta^{-2}} \|K_\eps\|_{C_1}^2\Bigr).
    \end{align*}
    The scaling property from Assumption \ref{Ass:kernel} implies that $\|K_\eps\|_{C_1}\lesssim \eps^{-2}$ as well as $ \frac{\|K_\eps\|_{L^\infty}^2}{\|K_\eps\|_{C_1}^2} \lesssim \eps^{2}$,  therefore the first part of the theorem follows.
    Lemma \ref{lem:recurr_relation} also implies that
    \begin{align*}
        \frac1N\sum_{i =1}^N \E\Bigl[ \Bigl( X_{jh+h}^{(i)}-X_{jh+h}^{(i),N}  \Bigr)^2   \Bigr] 
        &\lesssim \frac1Nh\delta^{-2}\|K_\eps\|_{L^\infty}^2 \sum_{j=1}^{T/h}  
        \Bigl(1+2Ch\delta^{-2}\|K_\eps\|_{C_1}^2\Bigr)^{j-1}
        \\
        &\lesssim  \frac1Nh\delta^{-2}\|K_\eps\|_{L^\infty}^2
        \frac{\Bigl(1+2Ch\delta^{-2}\|K_\eps\|_{C_1}^2\Bigr)^{T/h}}{2Ch\delta^{-2}\|K_\eps\|_{C_1}^2}
        \\
        &\lesssim \frac1N \frac{\|K_\eps\|_{L^\infty}^2}{\|K_\eps\|_{C_1}^2} {\Bigl(1+2Ch\delta^{-2}\|K_\eps\|_{C_1}^2\Bigr)^{T/h}}.
    \end{align*}
    Assuming that $\eps\le h$ it follows from changing the constant $C$ that
    \begin{align*}
         \frac1N\sum_{i =1}^N \E\Bigl[ \Bigl( X_{jh+h}^{(i)}-X_{jh+h}^{(i),N}  \Bigr)^2   \Bigr] 
        &\lesssim \frac1{N} \eps^{2}
        \exp\Bigl(
        Th^{-1} \log\bigl( 2C h \delta^{-2}\eps^{-4}\bigr)\Bigr).
    \end{align*}
\end{proof}



