\subsection[Proof of Lemma 2.5]{Proof of Lemma \ref{Lem_UEstim}}

The following lemma is taken from \cite[Theorem 7, Chapter 9, p. 260]{Friedman1964} and also appears in a more specific setting in \cite[Theorem 2.2]{KonakovMammen2002}.
\begin{lemma}\label{Lem_DensityRegularity}
    Let $t\in[0,T)$, $Y^{t,x}$ be the solution of \eqref{Eq:target} started at time $t$ with $Y_t^{t,x}=x$. Assume that $\sigma$ is four times continuously differentiable with bounded derivatives and uniformly elliptic. Then the law of $Y_T^{t,x}$ admits a density $p(y;t,x)$ with respect to the Lebesgue measure. Furthermore, if $0\le n+m \le 4$ there are constants $0<C<\infty$ such that
    \begin{align*}
       \frac{d^m}{dy^m}\frac{d^n}{dx^n} p(y+x;t,x) \le C \frac{1}{(T-t)^{(m+1)/2}} \exp\Bigl( - \frac{y^2}{C(T-t)}\Bigr).
    \end{align*}
\end{lemma}
\begin{remark}
    In the notation of \cite{Friedman1964} we have $p(y;t,x)=\Gamma^*(x,T;y,t)=\Gamma(y,t;x,T)$.
\end{remark}


\begin{proof}[Proof of Lemma \ref{Lem_UEstim}]
    By construction $u$ solves the Feynman-Kac PDE \eqref{Eq:FeynmanKac}, implying that
    \begin{align*}
        \partial_t\partial_x^j u(t,x) &= \frac12\partial_x^j \Bigl(\sigma^2(t,x) \partial_x^{2} u(t,x) \Bigr),
        \\
        \partial_t^2 u(t,x) &= \frac14\sigma^2(t,x) \partial_x^{2}(\sigma^2(t,x)\partial_x^{2} u(t,x)) + \sigma(t,x) \partial_t \sigma(t,x) \partial_x^{2} u(t,x).
    \end{align*}
    By Assumption \ref{Aspt_new} on $\sigma$ and the product rule it is sufficient to find bounds for $\partial_x^j u(t,x)$. We treat the case $j=4$, the other cases work similar.

    We can write $u(t,x)=\int_{\mathbb{R}} f(y)p(y;t,x)\,dy=\int_{\mathbb{R}} f(y+x)p(y+x;t,x)\,dy$. Assume first that $f$ is four times continuously differentiable with bounded derivatives, then by Leibniz rule
    \begin{align*}
        \partial_x^4 u(t,x)&=\int_\mathbb{R} \frac{d^4}{dx^4} \bigl( f(y+x) p(y+x;t,x)\bigr)\,dy= \sum_{k=0}^4 \binom{4}{k} \int_\mathbb{R} f^{(k)}(y+x) \frac{d^{4-k}}{dx^{4-k}}p(y+x;t,x)\,dy
    \end{align*}
    If $k\le l$ we can use Lemma \ref{Lem_DensityRegularity} and observe
    \begin{align*}
        \biggl|\int_\mathbb{R} f^{(k)}(y+x) \frac{d^{4-k}}{dx^{4-k}}p(y+x;t,x)\,dy \biggr| &\le \int_\mathbb{R} \bigl|f^{(k)}(x+y)\bigr| C (T-t)^{-1/2} \exp\Bigl(-\frac{y^2}{2C(T-t)} \Bigr)\,dy 
    \end{align*}
    If $k>l$ we use partial integration to see that
    \begin{align*}
        \int_\mathbb{R} f^{(k)}(y+x) \frac{d^{4-k}}{dx^{4-k}}p(y+x;t,x)\,dy= (-1)^{k-l} \int_\mathbb{R} f^{(l)}(y+x)\frac{d^{k-l}}{dy^{k-l}} \frac{d^{4-k}}{dx^{4-k}}p(y+x;t,x)\,dy.
    \end{align*}
    The estimate from Lemma \ref{Lem_DensityRegularity} tells us
    \begin{align*}
        \biggl|\int_\mathbb{R} f^{(l)}(y+x)^{k-l} \frac{d^{4-k}}{dx^{4-k}}p(y+x;t,x)\,dy \biggr|&\le \int_\mathbb{R} \bigl|f^{(l)}(y+x)\bigr| C (T-t)^{-\frac{(k-l+1)}2} \exp\Bigl(-\frac{y^2}{2C(T-t)} \Bigr)\,dy.
    \end{align*}
    Altogether there is a constant $\hat C$ such that
    \begin{align*}
        \partial_x^4 u(t,x)\le \hat C \sum_{k=l}^4 \int_\mathbb{R} \bigl|f^{(k)}(y+x)\bigr| C (T-t)^{-(k-l+1)/2} \exp\Bigl(-\frac{y^2}{2C(T-t)} \Bigr)\,dy.
    \end{align*}
    As the right hand side only depends on the $l$ weak derivatives of $f$, we can also plug in some $f$ satisfying the assumptions of the lemma. Thus it follows from the polynomial growth condition on $f$, the fact that $(k-l+1)\le (4-l+1)$, Gaussian integration (treating the term $(T-t)^{-1/2}$), that there is a constant $0<\tilde C < \infty$ and some $N \in \mathbb{N}$ such that
    \begin{align*}
        \partial_x^4 u(t,x) &\le 
            \tilde C(T-t)^{-(4-l)/2} \bigl(1+|x|^N\bigr)
    \end{align*}
    As we saw that all estimates eventually only depend on the polynomial growth of $f^{(k)}$ for $k\le l$ the claim follows.
\end{proof}


\subsection{Gaussian Calculations}
\begin{lemma}\label{lem:Tail_estim}
    Let $h,T>0$ such that $\frac Th\in \mathbb{N}$.  For $k\in \{1,\dots,\frac Th\}$ let $\tilde \beta_k$ and $\beta_k$ be $\mathcal{F}_{kh}$ adapted and uniformly bounded by some $b>0$.
    Assume that a recursion scheme is given by
    \begin{align*}
        X_{kh+t}=X_{kh}+\beta_k \bigl(B_{kh+t}-B_{kh}\bigr)+\tilde\beta_k \bigl(\bB_{kh+t}-\bB_{kh}\bigr) \qquad t \in [0,h].
    \end{align*}
    Then it holds that
    \begin{align*}
        \Prob\bigl( \sup_{t \in [0,T]} |X_t| >M \bigr) \le \exp\Bigl(-\frac{M^2}{4b^2T}\Bigr).
    \end{align*}
    In particular for any $\lambda>0$ 
    \begin{align*}
        \E\Bigl[\exp(\lambda |X_T|)\Bigr]<\infty.
    \end{align*}
\end{lemma}
\begin{proof}
    By assumption the quadratic variation of $X$ satisfies $\langle X\rangle_t\le 2b^2t$. Then the first part is a standard result from stochastic analysis, see for example \cite[Exercise 3.16, p. 153]{RevuzYor99}.

    The second part follows from the fact that $\int_0^\infty e^{c x-d x^2}\,dx<\infty$ for all $c,d>0$.
\end{proof}


\begin{lemma}\label{Lem:Density}
    Let $Z_0,\eta$ be random variables such that $\Prob(\eta=0)=0$. Let $\Delta W$ be Gaussian with mean $0$ and variance $h$ such that $\Delta W$ is independent of $Z_0$ and $\eta$. Assume that 
    \begin{align*}
        Z_1=Z_0+\eta \Delta W.
    \end{align*} 
    Then $Z_{1}$ has a density given by a convolution-type formula: 
    \begin{align*}
        f_{Z_{1}}(x)=\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr) \Bigr]
    \end{align*}
    \end{lemma}

    \begin{proof}
        This follows immediately from the fact that $\Delta W$ is independent of $(Z_0,\eta)$ and has variance $h$.
    \end{proof}

\begin{lemma}\label{Lem_Cond_exp_gauss}
    Let $X,Y,Z$ be random variables and
    define
    $\zeta=X+ Z$.
    Assume that $Z$ has a strictly positive and bounded density $f_Z$ and that $Z$ is independent of $(X,Y)$.
\begin{enumerate}[(i)]
\item 
For any measurable and bounded function $\psi:\mathbb{R}\times\mathbb{R} \rightarrow\mathbb{R}$ such that $\psi(\zeta,Y)$ is integrable,
we have that 
\begin{align*}
    \E\bigl[\psi(\zeta,Y)\bigr]= \int_{\mathbb{R}} \E\bigl[ \psi(x,Y)f_Z(x-X)]\,dx
\end{align*}
\item Let $Y$ be integrable, then almost surely it holds that \begin{align*}
        \E\bigl[ Y \big|\zeta \bigr]=\frac{\E\bigl[
        Y f_{Z}( x-X)
        \bigr]\Big|_{x=\zeta}}
        {\E\bigl[
        f_{Z}( x-X)
        \bigr]\Big|_{x=\zeta}}.
    \end{align*}
    \end{enumerate}    
\end{lemma}

\begin{proof}
Let $\psi:\mathbb{R}\times\mathbb{R} \rightarrow\mathbb{R}$
be a measurable and bounded function. As $Z$ is independent of $\left(X,Y\right)$,
we have by Fubini's theorem
\begin{align*}
    \E\bigl[\psi(\zeta,Y)\bigr]&= \E\bigl[\psi(X+ Z,Y)\bigr]=\E\biggl[
    \int_{\mathbb{R}} \psi(X+z,Y)f_Z(z)\,dz
    \biggr]
    =\E\biggl[
    \int_{\mathbb{R}} \psi(x,Y)f_Z(x-X)\,dx
    \biggr]
\end{align*}
where we made the change of variable $x:=X+z$, and this proves
$(i)$.


Let $F$ be measurable, bounded and with compact support. Then by point $(i)$
\begin{align*}
    \E\biggl[F(\zeta) \frac{\E[Yf_Z(x-X)]\big|_{x=\zeta}}{\E[f_Z(x-X)]\big|_{x=\zeta}}
    \biggr]
     &=
     \int_{\mathbb{R}} 
    \E\biggl[F(x) \frac{\E[Yf_Z(x-X)]}{\E[f_Z(x-X)]}
    f_Z(x-X) \biggr]\,dx
    \\
    &=
    \int_{\mathbb{R}} 
    \E[F(x)Yf_Z(x-X)]
    \,dx
    \\
    &=\E\bigl[F(\zeta)Y\bigr].
\end{align*}
For the last equality we applied $(i)$ a second time. By definition of the conditional expectation, the claim follows. 
\end{proof}


\subsection{Auxiliary Lemmas}

\begin{lemma}\label{Lem:Gauss_facts}
    Let $\lambda>0$ and let $\varphi_\lambda(x)=\frac{1}{\sqrt{2\pi\lambda}}e^{-\frac{x^2}{2\lambda}}$ be the density of a centered Gaussian with variance $\lambda$. 
        \begin{enumerate}
        \item \label{Lem:Gauss_fact1}$\forall x\in\mathbb{R},\;\forall \gamma\in(0,1],\; |x|\varphi_\lambda(x)\le (e\gamma)^{-\frac12} \lambda^{\frac{1-\gamma}{2}} \varphi_\lambda^{1-\gamma}(x)$,
            \item $\forall x,y \in \mathbb{R}\mbox{ with }|x-y|<\eps,\;\forall \gamma\in(0,1],\;\varphi_\lambda(y) \ge (2\pi\lambda)^{\frac\gamma2}\varphi_\lambda(x)^{1+\gamma} e^{-\frac{\eps^2}{\gamma \lambda}} $,
        \item $\forall x\in\mathbb{R},\;\forall \gamma>0,\; \varphi_\lambda^{1+\gamma}(x)\le {(2\pi\lambda)}^{-\frac\gamma2} \varphi_\lambda(x).$
        \end{enumerate}
\end{lemma}


\begin{proof}
    \textbf{(1):} 
    We use the fact that
    $\mathbb{R}\ni y\mapsto |y|e^{-\frac{y^2}{2}}$ is bounded by $e^{-\frac12}$ and see that for $x>0$
    \begin{align*}
        x\varphi_\lambda(x)= x e^{-\frac{x^2\gamma}{2\lambda}} \Bigl(\frac{1}{\sqrt{2\pi \lambda}}\Bigr)^\gamma \varphi_\lambda^{1-\gamma} 
        = 
        x\frac{\sqrt{\gamma}}{\sqrt{\lambda}} e^{-\frac{x^2\gamma}{2\lambda}} {\lambda}^{\frac{1-\gamma}2}\gamma^{-\frac12}\frac{1}{\sqrt{2\pi}^{\gamma}}\varphi_\lambda^{1-\gamma}\le (e\gamma)^{-\frac12} {\lambda}^{\frac{1-\gamma}2} \varphi_\lambda^{1-\gamma}.  
    \end{align*}
    By symmetry the first claim follows.

    \textbf{(2):} Simple calculation shows
    \begin{align*}
        \varphi_\lambda(y)=\frac{1}{\sqrt{2\pi \lambda}}e^{-\frac{(x+y-x)^2}{2\lambda}}=\frac{1}{\sqrt{2\pi \lambda}}e^{-\frac{x^2(1+\gamma)}{2\lambda}}e^{\frac{x^2\gamma-2x(y-x)-(y-x)^2}{2\lambda}}.
    \end{align*}
    The claim then follows from the fact that 
    \begin{align*}
        x^2\gamma -2x(y-x)-(y-x)^2\ge x^2\gamma -2 |x|\eps-\eps^2 \ge -\frac{\eps^2}{\gamma}-\eps^2\ge -2\frac{\eps^2}{\gamma}.
    \end{align*}

    \textbf{(3):} Can be seen directly:
    \begin{align*}
        \varphi_\lambda^{1+\gamma}(x)={\bigl(2\pi\lambda\bigr)}^{-\frac\gamma2} \frac{1}{\sqrt{2\pi\lambda}} e^{-\frac{x^2(1+\gamma)}{2\lambda}}\le \bigl(2\pi\lambda\bigr)^{-\frac\gamma2} \frac{1}{\sqrt{2\pi\lambda}} e^{-\frac{x^2}{2\lambda}}.
    \end{align*}

\end{proof}

\begin{lemma}\label{lem:recurr_relation}
    Let $h,\gamma,\lambda>0$ and  $T>0$ such that $n\coloneqq T/h\in\mathbb{N}$. Assume that there is a recurrence relation of the form 
    \begin{align*}
        f_{j+1}\le \bigl(1+ h\gamma \bigr)f_j+\lambda \qquad j=0,\dots,Tn-1
    \end{align*}
    such that $f_0=0$. Then it follows that
    \begin{align*}
        f_j\le \lambda \sum_{k=1}^j (1+h \gamma )^{k-1} .
    \end{align*}
    In particular $f_j\le \frac\lambda{h\gamma}  e^{T\gamma}$.
\end{lemma}
\begin{proof}
    It can follows from induction that
    \begin{align*}
    g_j=\lambda \sum_{k=1}^j (1+h\gamma)^{k-1}.
    \end{align*}
    is a solution to $g_{j+1}=(1+h\gamma)g_j+\lambda$ with $g_0=0$. We can check by induction on $j$ that $f_j\le g_j$.
    Properties of the geometric series
    imply that
    \begin{align*}
        g_j=\lambda \frac{1}{h\gamma} \Bigl( \bigl(1+h\gamma\bigr)^j-1\Bigr)\le \frac{\lambda}{h\gamma} \Bigl( \bigl(1+h\gamma \bigr)^{T/h}-1\Bigr).
    \end{align*}
    By monotonicity and the definition of the Euler number $e$ it follows that
    \begin{align*}
        g_j \le \frac\lambda{h\gamma}e^{T\gamma}. 
    \end{align*}
\end{proof}


\begin{lemma}\label{lem_sqt_estim}
    Let $a_0,a_1,b_0,b_1>0$ be positive numbers and let $\delta \in (0,1)$. Assume that there is some $0<c\le 1\le C<\infty$ such that
    \begin{align*}
        c\le \frac{a_0}{b_0}\le C \text{ and } c\le \frac{a_1}{b_1}\le C.
    \end{align*}
    Then it follows that
    \begin{align*}
        \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}\Bigr|\lesssim \frac1\delta \Bigl(|a_0-a_1|+|b_0-b_1|\Bigr).
    \end{align*}
    Furthermore, it holds that
    \begin{align*}
        \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}\Bigr|^2 
        \le
        \frac{\sqrt{C}}{\sqrt{c}}\Bigl|\frac{{a_0+\delta}}{{b_0+\delta}}-\frac{{a_1+\delta}}{{b_1+\delta}}\Bigr|.
    \end{align*}
\end{lemma}
\begin{proof}
    We begin by rewriting
    \begin{align*}
        \frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}
        =
        \frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_0+\delta}}+\frac{\sqrt{a_1+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}.
    \end{align*}
    By the fact that $a_0,a_1,b_0>0$ and Taylor formula 
    \begin{align*}
        \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_0+\delta}}\Bigr|\le  \frac1{\sqrt{\delta}}\frac{1}{2\sqrt{\delta}} \bigl|a_0-a_1\bigr|.
    \end{align*}
    By the fundamental theorem of calculus for $0<x\le y$ we have that $x^{-1/2}-y^{-1/2}=\frac12 \int_x^y z^{-3/2}\,dz\le |y-x|\frac12x^{-3/2}$. Therefore
    \begin{align*}
        \Bigl|
        \frac{\sqrt{a_1+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}
        \Bigr|
        \le 
        \frac1{2} \cdot\frac{\sqrt{a_1+\delta}\cdot |b_0-b_1|}{(b_0+\delta)^{3/2}\wedge (b_1+\delta)^{3/2}}
        \le 
        \frac1{2\delta} \cdot\frac{\sqrt{a_1+\delta}\cdot |b_0-b_1|}{\sqrt{b_0+\delta}\wedge \sqrt{b_1+\delta}}.
    \end{align*}
    Summing up both estimates it follows that
    \begin{align*}
         \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}\Bigr|\le \frac1{2\delta}\Bigl( |a_0-a_1|+\frac{\sqrt{a_1+\delta}\cdot |b_0-b_1|}{\sqrt{b_0+\delta}\wedge \sqrt{b_1+\delta}}\Bigr).
    \end{align*}
    Similarly, by rewriting
    \begin{align*}
        \frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}
        =
        \frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_0+\delta}}{\sqrt{b_1+\delta}}+\frac{\sqrt{a_0+\delta}}{\sqrt{b_1+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}},
    \end{align*}
    it follows from the same arguments that
     \begin{align*}
         \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}\Bigr|\le \frac1{2\delta}\Bigl( |a_0-a_1|+\frac{\sqrt{a_0+\delta}\cdot |b_0-b_1|}{\sqrt{b_0+\delta}\wedge \sqrt{b_1+\delta}}\Bigr).
    \end{align*}
    By combining these estimates we see that
     \begin{align*}
         \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}\Bigr|&\le \frac1{2\delta}\Bigl( |a_0-a_1|+|b_0-b_1|\frac{\sqrt{a_0+\delta}\wedge \sqrt{a_0+\delta}}{\sqrt{b_0+\delta}\wedge \sqrt{b_1+\delta}}\Bigr)
         \\
         &\le \frac1{2\delta}\Bigl( |a_0-a_1|+|b_0-b_1|C\Bigr).
    \end{align*}
    For the second claim observe that by Taylor formula applied to $x\mapsto \sqrt{x}$ again
    \begin{align*}
        \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}\Bigr|&\le \frac12 \min\Bigl( 
        \frac{\sqrt{b_0+\delta}}{\sqrt{a_0+\delta}},\frac{\sqrt{b_1+\delta}}{\sqrt{a_1+\delta}}
        \Bigr)  \Bigl|\frac{{a_0+\delta}}{{b_0+\delta}}-\frac{{a_1+\delta}}{{b_1+\delta}}\Bigr|
        \\
        &\le \frac1{2\sqrt{c}} \Bigl|\frac{{a_0+\delta}}{{b_0+\delta}}-\frac{{a_1+\delta}}{{b_1+\delta}}\Bigr|.
    \end{align*}
\end{proof}


\begin{lemma}\label{lem:estim_AB}
    Let $(\alpha_k)_{k=1}^n,(\beta_k)_{k=1}^n,(\gamma_k)_{k=1}^n$ and $(\Delta_k)_{k=1}^n$ be positive sequences and assume that $\alpha_k \le A$ as well as $a\le \gamma_k \le b$ for some $a\le 1\le A,b$. 

    Let $\delta > 0$ and assume that $|\alpha_k-\beta_k|\le C \max\bigl\{\alpha_k^p,\beta_k^p \bigr\} \Delta_k$ for some $C>0$ and $1/2\le p\le 1$. Then it holds that
   {
    \begin{align*}
    \Bigl|\frac{\frac1n\sum_{k=1}^n \alpha_k +\delta}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta}-\frac{\frac1n\sum_{k=1}^n \beta_k +\delta}{\frac1n\sum_{k=1}^n \beta_k\gamma_k +\delta}
        \Bigr|
        \lesssim C \max_{j=1,\dots,n}\max\{\alpha_j,\beta_j\}^{p-\frac1{2}} \delta^{-1/2} \sqrt{\frac1n \sum_{k=1}^n \Delta_k^2}
        \end{align*}
    }
\end{lemma}
\begin{proof}
    By symmetry we assume without loss of generality that $\sum_{k=1}^n \beta_k^{2p} \le \sum_{k=1}^n \alpha_k^{2p}$ implying in particular $\sum_{k=1}^n \max\bigl\{\alpha_k^{2p},\beta_k^{2p} \bigr\}\le 2 \sum_{k=1}^n \alpha_k^{2p}$.
    We then rewrite
    \begin{align*}
        \frac{\frac1n\sum_{k=1}^n \alpha_k +\delta}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta}-\frac{\frac1n\sum_{k=1}^n \beta_k +\delta}{\frac1n\sum_{k=1}^n \beta_k\gamma_k +\delta}
        &=
        \frac{\frac1n\sum_{k=1}^n \bigl(\alpha_k-\beta_k\bigr)}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta}
        \\
        &\qquad+
        \frac{\bigl(\frac1n\sum_{k=1}^n \beta_k+\delta\bigr)\frac1n\sum_{k=1}^n \gamma_k\bigl(\beta_k-\alpha_k\bigr)}{\bigl(\frac1n\sum_{k=1}^n \alpha_k\gamma_k+\delta\bigr)\bigl(\frac1n\sum_{k=1}^n \beta_k\gamma_k+\delta\bigr)} 
    \end{align*}
    By our assumption
    \begin{align*}
        \Bigl| \frac{\bigl(\frac1n\sum_{k=1}^n \beta_k+\delta\bigr)\frac1n\sum_{k=1}^n \gamma_k\bigl(\beta_k-\alpha_k\bigr)}{\bigl(\frac1n\sum_{k=1}^n \beta_k\gamma_k+\delta\bigr)\bigl(\frac1n\sum_{k=1}^n \alpha_k\gamma_k+\delta\bigr)} \Bigr|
        \le 
        \frac1a \cdot \Bigl| \frac{\frac1n\sum_{k=1}^n \gamma_k\bigl(\beta_k-\alpha_k\bigr)}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k+\delta}\Bigr|\le\frac ba \cdot \frac{\frac1n\sum_{k=1}^n \bigl|\beta_k-\alpha_k\bigr|}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k+\delta}.
    \end{align*}
    By the assumptions and the Cauchy-Schwarz inequality, we see that
    \begin{align*}
        \Bigl|
        \frac{\frac1n\sum_{k=1}^n \bigl|\alpha_k-\beta_k\bigr|}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta}
        \Bigr|
        \le
        C\frac{\frac1n\sum_{k=1}^n \max\bigl\{\alpha_k^p,\beta_k^p \bigr\} \Delta_k}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta}
        \le
        C\frac{\sqrt{\frac1n\sum_{k=1}^n \max\bigl\{\alpha_k^{2p},\beta_k^{2p} \bigr\}} }{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta}\sqrt{
        \frac1n \sum_{k=1}^n \Delta_k^2
        }
    \end{align*}
    { 
    Our assumption at the beginning of the proof implies that
    \begin{align*}
        \frac{\sqrt{\frac1n\sum_{k=1}^n \max\bigl\{\alpha_k^{2p},\beta_k^{2p} \bigr\}} }{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta} \le
        \frac2a \cdot 
        \frac{\sqrt{\frac1n\sum_{k=1}^n \alpha_k^{2p}}}{\frac1n\sum_{k=1}^n \alpha_k +\delta}
        \le 
        \frac{2\max_{j=1}^n\alpha_k^{p-\frac1{2}}}a \cdot
        \frac{\Bigl(\frac1n\sum_{k=1}^n \alpha_k\Bigr)^{\frac{1}{2}}
        }{\Bigl(\frac1n\sum_{k=1}^n \alpha_k\Bigr) +\delta}.
    \end{align*}
    }
    {
    The last factor can be described by the function $y\mapsto \frac{\sqrt{y}}{y+\delta}$ on $\mathbb{R}^+$, which is bounded by $\delta^{-1/2}/2$. By combining everything, we see that
    \begin{align*}
         \Bigl|\frac{\frac1n\sum_{k=1}^n \alpha_k +\delta}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta}-\frac{\frac1n\sum_{k=1}^n \beta_k +\delta}{\frac1n\sum_{k=1}^n \beta_k\gamma_k +\delta}
        \Bigr|
        \le \bigl(1+\frac ba\bigr)\frac1a 
        \max_{j=1,\dots,n}\alpha_j^{p-\frac1{2}} \delta^{-1/2}C \sqrt{
        \frac1n \sum_{k=1}^n \Delta_k^2
        }.
    \end{align*}
    }
\end{proof}

