\section{Properties of Riemann sequences}\label{sproperties}  

In what follows we assume that we have a Riemann sequence $(\alpha)$  and try to get information about it. 

\begin{proposition}\label{simpleboundN}
Let $(\alpha_n)$ be a Riemann sequence, and for $x>0$ let $N(x)$ be the number of terms with $\Re\alpha_n\le x$, then $N(x)\le Cx\log (x+1)$ for some  constant $C$, and  therefore $\sum_\alpha |\alpha|^{-1-\varepsilon}<+\infty$ for any $\varepsilon>0$.
\end{proposition}
\begin{proof}
For $x> 1$ and $\alpha=\gamma+i\beta$ with $|\beta|<C$ (by condition (c) of the definition of Riemann sequences) and $\gamma\le x$. When $\beta=0$
\[\frac{2x}{x^2+\gamma^2}\ge \frac{1}{x},\]
and when $\beta>0$, with $\beta\le\gamma$ by condition (d) of the definition of Riemann sequence 
\[\frac{2x}{x^2+\alpha^2}+\frac{2x}{x^2+\overline{\alpha}^2}=2\frac{2x(x^2+\gamma^2-\beta^2)}{(x^2+\gamma^2-\beta^2)^2+4\beta^2\gamma^2}\ge2\frac{2x}{5(x^2+\gamma^2-\beta^2)}\ge 2\frac{2x}{5x^2}\ge 2\frac{2}{5x}.\]
Therefore for $x>x_0$ we have
\[N(x)\frac{2}{5x}\le \sum_{\alpha}\frac{2x}{x^2+\alpha^2}\le \log x.\]
Hence for $x>x_0$ we have $N(x)\le 3x\log x$, and then there is a constant with $N(x)\le Cx\log (x+1)$ for $x>1$.
\end{proof}

It follows that the series in the definition of a Riemann sequence converges uniformly on compact sets of  $\C\smallsetminus\{\pm i \alpha_n\colon n\in \N\}$, and defines a meromorphic function with poles at the points $\pm i\alpha_n$.

\begin{theorem} Let $(\alpha_n)$ be a Riemann sequence. 
There exists a real  constant $B$ such that
\begin{equation}\label{eq17}
\sum_{\alpha}\log\Bigl(1+\frac{z^2}{\alpha^2}\Bigr)\simeq
\frac{z}{2}\log\frac{z}{2\pi}-\frac{z}{2}+\frac{7}{4}\log z+B-
\sum_{n=1}^{\infty}\frac{a_{n+1}}{n z^n},
\end{equation}
\end{theorem}

\begin{proof}
It is well known that from \eqref{mainalpha} it follows
\begin{equation}\label{E:28}
-\int_z^\infty\Bigl\{\sum_{\alpha}\frac{2t}{t^2+\alpha^2}-\frac12\log\frac{t}{2\pi}
+\frac{a_1}{t}\Bigr\}\,dt\simeq -\sum_{n=2}^\infty \frac{a_n}{(n-1)z^{n-1}}
\end{equation}
But the left hand side of \eqref{E:28} and
\begin{equation}
\sum_{\alpha}\log\Bigl(1+\frac{z^2}{\alpha^2}\Bigr)-
\frac{z}{2}\log\frac{z}{2\pi}+\frac{z}{2}+a_1\log z
\end{equation}
are two primitives of the integrand, so that they differ on  a constant $B$. Therefore
\begin{equation*}
\sum_{\alpha}\log\Bigl(1+\frac{z^2}{\alpha^2}\Bigr)-
\frac{z}{2}\log\frac{z}{2\pi}+\frac{z}{2}+a_1\log z-B\simeq-
\sum_{n=1}^{\infty}\frac{a_{n+1}}{n z^n}.
\end{equation*}

From the above we get 
\begin{equation}
B=\lim_{x\to+\infty}\sum_{\alpha}\log\Bigl(1+\frac{x^2}{\alpha^2}\Bigr)-
\frac{x}{2}\log\frac{x}{2\pi}+\frac{x}{2}-\frac74\log x.
\end{equation}
This combined with the fact that the multiplicities satisfies $\nu(\alpha)=\nu(\overline{\alpha})$ implies that $B$ is real.
\end{proof}



Given a Riemann sequence $(\alpha_n)$ we are going to define two associated functions $\zeta_\alpha(s)$ and $\Xi_\alpha(t)$ similar to the 
functions $\zeta(s)$ and $\Xi(s)$. We define $\Xi_\alpha(0)$ by the equation 
\begin{equation}
B=\frac14\log\frac{\pi}{2}-\log\Xi_\alpha(0)
\end{equation} 
(compare the value of $A$ in Theorem 
\ref{one}). Then define
\begin{align}\label{defxizeta}
\Xi_\alpha(t)&=\Xi_\alpha(0)\prod_{\alpha}\Bigl(1-\frac{t^2}{\alpha^2}\Bigr),\\
\zeta_\alpha(s)&=\Xi_\alpha(0)\frac{\pi^{\frac{s}{2}}}{(s-1)\Gamma(1+s/2)}\prod_\alpha
\Bigl(1+\frac{(s-1/2)^2}{\alpha^2}\Bigr)\label{defzeta}
\end{align}

These functions depend on the sequence $(\alpha)$ and when $(\alpha)=(\tau)$ we get the familiar $\zeta(s)$ and $\Xi(t)$.

\begin{theorem}
$\Xi_\alpha(t)$ is an even entire function 
of order  $1$.  Its zeros are the numbers $\alpha_n$ and $-\alpha_n$. 
$\Xi_\alpha(t)$ is real for $t$ real and for $t$ purely imaginary. 
\end{theorem}

\begin{proof}
Since $(\alpha_n)$ is a Riemann sequence $\sum_\alpha|\alpha|^{-2}<\infty$. Hence the product in \eqref
{defxizeta}  converges uniformly on compact sets and define an entire function.

Let $|t|\le r$,  is clear that for each factor with $\alpha\in\R$, we have $\Bigl|1-\frac{t^2}{\alpha^2}\Bigr|\le (1+\frac{r^2}{\alpha^2})$ when $\alpha$ is real. In the case of a complex $\alpha$, we may 
associate the factors for $\alpha$ and $\overline{\alpha}$. By condition (d) of the definition of Riemann sequence $|\arg(\alpha_n)|<\pi/4$ and therefore $\Re(\alpha_n^{-2})>0$. It follows that for $n\ge n_0$, 
\begin{multline*}
\Bigl|\Bigl(1-\frac{t^2}{\alpha^2}\Bigr)\Bigl(1-\frac{t^2}{\overline{\alpha}^2}\Bigr)
\Bigr|=\Bigl|1+\frac{t^4}{|\alpha|^4}-2t^2\Re\frac{1}{\alpha^2}\Bigr|\le 
1+\frac{r^4}{|\alpha|^4}+2r^2\Re\frac{1}{\alpha^2}=\\
=\Bigl(1+\frac{r^2}{\alpha^2}\Bigr)\Bigl(1+\frac{r^2}{\overline{\alpha}^2}\Bigr).
\end{multline*}

Then for $|t|\le r$
\[|\Xi(\alpha)|=\Bigl|\Xi_\alpha(0)\prod_\alpha\Bigl(1-\frac{t^2}{\alpha^2}\Bigr)\Bigr|\le |\Xi_\alpha(0)|\prod_\alpha\Bigl(1+\frac{r^2}{\alpha^2}\Bigr)=|\Xi(ir)|.\]

It follows that $|\Xi_\alpha(t)|\le  |\Xi_\alpha(ir)|$. Then by \eqref{eq17} we get 
\begin{equation}\label{boundlogM}
\log M(r)\sim \frac12 r\log r\qquad r\to+\infty.
\end{equation}
This proves that the order of $\Xi_\alpha(t)$ is $1$. 

By  definition the function $\Xi_\alpha(t)$ is even.  The 
order of multiplicity  $\nu(\alpha)=\nu(\overline{\alpha})$, hence the factors in the definition of $\Xi_\alpha(t)$ may be paired so that the product is real for $t$ real or 
purely imaginary, since we know that $\Xi_\alpha(0)$ is real we get the reality of 
$\Xi(x)$ and $\Xi(ix)$ for $x\in\R$.
\end{proof}

\begin{corollary}\label{expconv}
The exponent of convergence of a Riemann sequence $(\alpha)$ is $1$. The series 
$\sum_n|\alpha_n|^r$ converges for all $r>1$ but diverges for $0\le r\le1$.
\end{corollary}

\begin{proof} Since the order of $\Xi_\alpha(t)$ is $1$ the series converges for all $r>1$. Being $\Xi_\alpha(t)$ an even function with  $\int_2^\infty r^{-2}\log M(r)\,dr=+\infty$,  it follows that $\sum_n|\alpha_n|^{-1}=\infty$. (Cfr. Boas \cite{B}*{Thm.~2.11.1 applied to $\Xi_\alpha(\sqrt{t})$}.)
\end{proof}


\begin{theorem}
$\zeta_\alpha(s)$ is a meromorphic function on $\C$ with a unique simple pole at the 
point $s=1$ with residue 
\begin{equation}
\Res_{s=1}\zeta_\alpha(s)=2\,\Xi_\alpha(0)\prod_\alpha\Bigl(1+\frac{1}{4\alpha^2}\Bigr).
\end{equation}
Its zeros are the even negative integers $-2$, $-4$, $-6$, \dots and the numbers
$\tfrac12+i\alpha$, $\tfrac12-i\alpha$. These last zeros (the non trivial zeros) are 
contained on the `critical strip' $|\sigma-\frac12|<C$.

Also $\zeta_\alpha(s)$ satisfies the same  functional equation as the Riemann zeta function. 
\begin{equation}
\pi^{-\frac{s}{2}}\Gamma(s/2)\zeta_\alpha(s)=\pi^{-\frac{1-s}{2}}\Gamma
\bigl((1-s)/2\bigr)\zeta_\alpha(1-s).
\end{equation}
\end{theorem}

\begin{proof}
All the assertions are easily obtained from the definition \eqref{defxizeta}. The functional equation is equivalent to the assertion that $\Xi_\alpha(t)$ is an even function. 
\end{proof}

\begin{theorem}
We have
\begin{equation}
\log\zeta_\alpha(s)\simeq 0,\qquad \zeta_\alpha(s)\simeq1.
\end{equation}
\end{theorem}

\begin{proof}
Taking log on the definition \eqref{defzeta} and applying \eqref{defxizeta} we get 
\begin{multline}\label{logonalldos}
\log\zeta_\alpha(\tfrac12+z)=\\
\sum_\alpha\log\Bigl(1+\frac{z^2}{\alpha^2}\Bigr)+
\Bigl(\frac{z}{2}+\frac14\Bigr)
\log\pi-\log\Bigl(z-\frac12\Bigr)-\log\Gamma\Bigl(\frac{z}{2}+\frac{5}{4}\Bigr)+
\log\Xi_\alpha(0)
\end{multline}
this is similar to \eqref{logonall}. Now we may apply \eqref{eq7}, \eqref{eq8} and 
\eqref{eq17} to get exactly that $\log\zeta_\alpha(\tfrac12+z)\simeq0$. 

Observe that $\log\zeta_\alpha(\tfrac12+z)\simeq0$ is equivalent to say that on each angle
$|\arg z|\le \theta<\frac{\pi}{2}$ and for each natural number $N$ we have
\begin{equation}
\lim_{z\to\infty}z^N \log\zeta_\alpha(\tfrac12+z)=0
\end{equation}
It is clear that this implies that for each $N$ there is a value of $R>1$  such that 
\begin{equation}
|\arg z|\le \theta \quad\text{and}\quad |z|>R \qquad \Longrightarrow\qquad\bigl|z^N \log\zeta_\alpha(\tfrac12+z)|\le 1
\end{equation}
Then we will have $|\zeta_\alpha(\tfrac12+z)-1|\le C|z|^{-N}$ for $|\arg z|\le \theta$ and $|z|>R$.
It follows that $\zeta_\alpha(\tfrac12+z)\simeq1$

Finally $\zeta_\alpha(s)\simeq1$ and $\zeta_\alpha(\tfrac12+s)\simeq1$ are equivalent assertions.
\end{proof}

\section{The function \texorpdfstring{$Z_\alpha$.}{Za.}}


\begin{definition}
Given a Riemann sequence $(\alpha_n)$ and for $\Re z>0$ we define
\begin{equation}
f(z):=\sum_{n=1}^\infty e^{-\alpha_n^2z}.
\end{equation}
The function $f$ is holomorphic in $\Re z>0$.
\end{definition}

\begin{proof}
We must show that the series converges uniformly in compact sets of $\Re z>0$. 
Let $K$ such  a compact. There exists $\delta>0$ and $M<\infty$ 
such that $\Re z\ge \delta>0$ and $|z|\le M$ for $z\in K$. 

Put $\alpha_n=a_n+ib_n$,  its real and imaginary parts and $z=x+iy\in K$. Then we have
\begin{displaymath}
|e^{-\alpha_n^2z}|= e^{-(a_n^2-b_n^2)x+2a_nb_n y }\le e^{-a_n^2 \delta+Mb_n^2+2Ma_n|b_n|}
\end{displaymath}
By condition (c) of the definition of Riemann sequence $|b_n|\le C$ we get for $n$  big enough
\begin{displaymath}
|e^{-\alpha_n^2z}|\le c e^{-a_n^2 \delta+ C Ma_n}\le c' e^{-\frac{\delta}{2}a_n^2}.
\end{displaymath}
Finally the numerical series $\sum e^{-\frac{\delta}{2}a_n^2}<+\infty$. This follows from Proposition \ref{simpleboundN} by partial summation.
\end{proof}

\begin{proposition}
For $|\arg(t)|<\frac{\pi}{4}$ we have
\begin{equation}
\int_0^\infty f(x)e^{-xt^2}\,dx=\sum_{n=1}^\infty\frac{1}{t^2+\alpha_n^2}
\end{equation}
\end{proposition}

\begin{proof}
Condition (d) in Definition \ref{D:RS} implies  $\Re(\alpha_n^2)>0$, so that each integral \[\int_0^\infty e^{-\alpha_n^2x}e^{-xt^2}\,dx=(t^2+\alpha_n^2)^{-1}\] is convergent. 

Since $\Re(\alpha_n)\to+\infty$ and $|\Im(\alpha_n)|\le C$, there is some $n_0$ such that $\Re(\alpha_n)>2|\Im(\alpha_n)|$ for $n\ge n_0$. With the same notation as before $\alpha_n=a_n+ib_n$ and for $t=u+iv$ with $\delta=u^2-v^2>0$, we have 
\[|e^{-\alpha_n^2 x}e^{-xt^2}|=e^{-(a_n^2-b_n^2)x-(u^2-v^2)x}\le e^{-(\frac34a_n^2+\delta)x},\qquad n\ge n_0,\quad x>0.\]
Therefore,
\[\int_0^\infty\Bigl|\sum_{n\ge n_0}e^{-\alpha_n^2} e^{-xt^2}\Bigr|\,dx\le \sum_{n=n_0}^\infty\int_0^\infty e^{-(\frac34a_n^2+\delta)x}\,dx=\sum_{n\ge n_0}\frac{1}{\frac34 a_n^2+\delta}<+\infty.\]

So the integration term by term is allowed and we get for $\Re t^2>0$,
\begin{equation}
\int_0^\infty f(x)e^{-xt^2}\,dx=\sum_{n=1}^\infty \int_0^\infty e^{-\alpha_n^2x}e^{-xt^2}\,dx=\sum_{n=1}^\infty \frac{1}{t^2+\alpha_n^2}.
\end{equation}
The restriction $\Re t^2>0$ is equivalent to $|\arg(t)|<\frac{\pi}{4}$.
\end{proof}

Now we may get the behavior of $f(x)$ when $x>0$ tends to $0$. 

\begin{theorem}
When $x$ real and $x\to0^+$ we have the asymptotic expansion
\begin{equation}\label{expasym}
2\sum_\alpha e^{-\alpha^2x}\sim \frac{1}{4\sqrt{\pi x}}\log\frac{e^{-C_0}}
{16\pi^2 x}
+\sum_{n=0}^\infty \frac{a_{n+1}}{\Gamma(1+n/2)}x^{n/2},\qquad x>0,\quad x\to0.
\end{equation}
\end{theorem}

\begin{proof}
Combining two entries of the Table of Integral Transform of Bateman \cite{Ba}*{4.3(1) p.~137 and 4.6(9) p.~148} we obtain\footnote{Beware that the second formula in the Bateman tables is not correct. Gradshteyn and Ryzhik tables \cite{GR}*{17.13.92} gives the same erroneous value.}
the following integral
\begin{equation}
\int_0^{+\infty} \frac{1}{4\sqrt{\pi x}}\log\frac{e^{-C_0}}{16\pi^2 x}e^{-x t^2}
\,dx=\frac{1}{2t}\log\frac{t}{2\pi},\qquad |\arg(t)|<\frac{\pi}{4}.
\end{equation}

Hence for $N\ge1$ we have
\begin{multline}
\int_0^{+\infty}\Bigl\{\frac{1}{4\sqrt{\pi x}}\log\frac{e^{-C_0}}{16\pi^2 x}+
\frac74
+\sum_{n=1}^{N-1} \frac{a_{n+1}}{\Gamma(1+n/2)}x^{n/2}\Bigr\}e^{-xt^2}\,dx=\\
=\frac{1}{2t}\log\frac{t}{2\pi}+\frac{7}{4t^2}+\sum_{n=1}^{N-1} \frac{a_{n+1}}{t^{n+2}}.
\end{multline}
Put
\begin{equation} \label{defgN}
g_N(x):=2f(x)-\Bigl\{\frac{1}{4\sqrt{\pi x}}\log\frac{e^{-C_0}}{16\pi^2 x}+
\frac74
+\sum_{n=1}^{N-1} \frac{a_{n+1}}{\Gamma(1+n/2)}x^{n/2}\Bigr\}
\end{equation}
Then 
\begin{equation}
G_N(t):=\int_0^\infty g_N(x)e^{-xt^2}\,dx
\end{equation}
is defined for $|\arg(t)|<\frac{\pi}{4}$ and is equal to 
\begin{equation}
G_N(t)=\sum_{n=1}^\infty \frac{2}{t^2+\alpha_n^2}-\frac{1}{2t}\log\frac{t}{2\pi}-\frac{7}{4t^2}-\sum_{n=1}^{N-1} \frac{a_{n+1}}{t^{n+2}}.
\end{equation}
Therefore $G_N(t)$ extends to an analytic function on $\Re t>\frac12$ and verifies
\begin{equation}
G_N(t)\simeq -\sum_{N+1}^\infty\frac{a_n}{t^{n+1}}
\end{equation}

In particular for each $0<\theta<\frac{\pi}{2}$  
\[
G_N(t)\quad\text{extends to $\Re t>\tfrac12$ and } G_N(t)\sim -\frac{a_{N+1}}{t^{N+2}}
\quad\text{when $t\to\infty$ in $|\arg(t)|\le \theta$.}
\]
Changing variable $s:=t^2$, it follows that
for any $0<\varphi<\pi$ 
\begin{equation}\label{hyp}
\int_0^\infty g_N(x)e^{-sx}\,dx
\end{equation}
extends to an analytic function $H_N(s)$ on the region $V=\{(x,y):x+y^2>1/4\}$ and for any $0<\varphi<\pi$
\begin{equation}
H_N(s)\sim -\frac{a_{N+1}}{s^{1+\frac{N}{2}}} \quad\text{when $s\to\infty$ in $|\arg(s)|\le \varphi,\quad s\in V$.}
\end{equation}


Now we apply a classical Theorem  (see Doetsch \cite{Do}*{p.~503--504 Satz 3}) to get from \eqref{hyp} that 
\begin{equation}\label{ordergN}
g_N(x)\sim-\frac{a_{N+1}}{\Gamma(1+\frac{N}{2})}x^{\frac{N}{2}},\qquad x>0,\quad x\to0.
\end{equation}
But that this is true for all $N$ is just  the meaning of \eqref{expasym}.
\end{proof}


For $\Re s>1$ we define
\begin{equation}
Z_\alpha(s):=\sum_{n=1}^\infty \frac{1}{\alpha_n^s},\qquad \Re s>1.
\end{equation}

By definition of Riemann sequence $\Re\alpha_n\ge\Re\alpha_1>1$ and $|\arg(\alpha_n)|\le\frac{\pi}{4}$. Hence $\alpha_n^{-s}$ has a well defined sense, taking the principal value of $\log\alpha_n$.  It follows that  $|\alpha_n^{-s}|=e^{-\sigma\log|\alpha_n|+t\arg(\alpha_n)}\le e^{\frac{\pi}{4}|t|}|\alpha_n|^{-\sigma}$. So 
by Corollary \ref{expconv} the series $\sum_n\alpha_n^{-s}$ is uniformly convergent 
on compact sets of $\Re s>1$. 

It follows that $Z_\alpha(s)$ is a holomorphic function on $\Re s>1$. 

\begin{theorem}\label{T:intZ}
For $\Re s>1$ we have
\begin{equation}\label{modexp}
\Gamma(s/2)Z_\alpha(s)=\int_0^{+\infty}f(x)x^{\frac{s}{2}}\frac{dx}{x}.
\end{equation}
\end{theorem}

\begin{proof}
By definition of Riemann sequence $|\arg(\alpha_n)|<\pi/4$, therefore $\Re(\alpha_n^2)>0$ and each integral
\begin{equation}
\int_0^\infty e^{-\alpha_n^2 x}x^{\frac{s}{2}}\frac{dx}{x}=\frac{\Gamma(s/2)}{\alpha_n^s},\qquad \sigma>0,
\end{equation}
is convergent.
By condition (c) of the definition of Riemann sequence $|\Im(\alpha_n)|\le C$, then $\Re(\alpha_n)\to+\infty$ and we have $|\Im(\alpha_n)|\le \frac12\Re(\alpha_n)$ for $n\ge n_0$. It follows that $|\alpha_n|^2\le \frac54\Re(\alpha_n)^2$ and 
\[\Re(\alpha_n^2)=\Re(\alpha_n)^2-\Im(\alpha_n)^2\ge \tfrac34\Re(\alpha_n)^2\ge \frac35|\alpha_n|^2.\]
Therefore, for $\sigma>1$
\[\Bigl|\sum_{n\ge n_0}\int_0^\infty e^{-\alpha_n^2 x}x^{\frac{s}{2}}\frac{dx}{x}\Bigr|\le \sum_{n\ge n_0}\int_0^\infty e^{-\frac35|\alpha_n|^2 x}x^{\frac{\sigma}{2}}\frac{dx}{x}=\sum_{n\ge n_0}\frac{\Gamma(\sigma/2)}{(3/5)^{\sigma/2}|\alpha_n|^\sigma}<+\infty.\]
This justify the interchange of sum and integral and we get 
\begin{equation}
\int_0^\infty f(x)x^{\frac{s}{2}}\frac{dx}{x}=\sum_{n=1}^\infty
\int_0^\infty e^{-\alpha_n^2 x}x^{\frac{s}{2}}\frac{dx}{x}=\Gamma(s/2)Z_\alpha(s).\qedhere
\end{equation}
\end{proof}


\begin{theorem}
The function $Z_\alpha(s)$ extends to a meromorphic function on $\C$. 

The function $Z_\alpha(s)$ has a double pole at $s=1$ with residue $-\frac{\log2\pi}{2\pi}$ and main part
\begin{equation}
\frac{1}{2\pi(s-1)^2}-\frac{\log2\pi}{2\pi(s-1)}.
\end{equation}
It has simple poles at the odd negative integers with main part
\begin{equation}
(-1)^{n}\frac{  a_{2n}}{\pi(s+2n-1)} = (-1)^n\frac{(1-2^{1-2n})}{2\pi}\frac{B_{2n}}
{2n}\frac{1}{s+2n-1}.
\end{equation}
The function $Z_\alpha(s)$ has no other poles.

Finally we have 
\begin{equation}\label{Zvalue}
Z_\alpha(-2n)=(-1)^{n}\frac{a_{2n+1}}{2}=(-1)^n\frac{8-E_{2n}}{2^{2n+3}}.
\end{equation}
\end{theorem}

\begin{proof}
First notice that there is a constant $\delta>0$ such that $|f(x)|\le Ce^{-\delta x}$ for all $x>1$. As in the proof of Theorem \ref{T:intZ} there is some $n_0$ such that for $n\ge n_0$ $|e^{-\alpha_n^2x}|\le e^{-\frac35|\alpha_n|^2x}$, and for each $n<n_0$ we have $|e^{-\alpha_n^2x}|\le e^{-(\Re(\alpha_n)^2-\Im(\alpha_n)^2)x}=e^{-\delta_nx}$ with $\delta_n>0$. Since $\Re(\alpha_n)^2\to+\infty$ there is some $\delta>0$ such that it is the minimum of all these exponents. Therefore, for $x>1$
\begin{equation}\label{boundf}
|f(x)|\le e^{-\delta x}\Bigl(\sum_{n<n_0}e^{-(\delta_n-\delta)x}+\sum_{n=n_0}^\infty e^{-(\frac35|\alpha_n|^2-\delta)x}\Bigr)\le Ce^{-\delta x}.
\end{equation}

For $x\to0^+$  \eqref{expasym} gives us the behavior of $f(x)$. 

For $\Re s>0$ by \eqref{modexp}
\begin{equation}
\Gamma(s/2)Z_\alpha(s)=\int_0^1f(x)x^{\frac{s}{2}}\frac{dx}{x}+
\int_1^\infty f(x)x^{\frac{s}{2}}\frac{dx}{x}:=H_1(s)+H_2(s).
\end{equation}
By \eqref{boundf} $H_2(s)$ is an entire function. 

On the other hand by \eqref{defgN}  
\begin{multline}
H_1(s)=\frac12\int_0^1\Bigl\{\frac{1}{4\sqrt{\pi x}}\log\frac{e^{-C_0}}{16\pi^2 x}+
\frac74
+\sum_{n=1}^{N-1} \frac{a_{n+1}}{\Gamma(1+n/2)}x^{n/2}\Bigr\}x^{\frac{s}{2}}
\frac{dx}{x}+\\
+\frac12\int_0^1 g_N(x)x^{\frac{s}{2}}\frac{dx}{x}
\end{multline}
When $\Re s>1$ we may compute some of the integrals so that
\begin{multline}\label{H1eq}
H_1(s)=\frac{1}{4\sqrt{\pi}}\Bigl\{\frac{2}{(s-1)^2}+\frac{1}{s-1}\log\frac{e^{-C_0}}{16\pi^2}
\Bigr\}+\sum_{n=0}^{N-1} \frac{a_{n+1}}{\Gamma(1+n/2)}\frac{1}{n+s}+\\
+\frac12\int_0^1 g_N(x)x^{\frac{s}{2}}\frac{dx}{x}
\end{multline}
But due to \eqref{ordergN} the last integral defines an analytic function for 
$\Re s>-N$. Hence  \eqref{H1eq} implies that $H_1(s)$ extends to a meromorphic function on $\Re s>N$.

It follows that $\Gamma(s/2)Z_\alpha(s)$ extends to a meromorphic function on  
$\Re s>-N$ for all natural numbers.  Hence $Z_\alpha(s)$ extends to a meromorphic
function on $\C$. 

The function $\Gamma(s/2)Z_\alpha(s)$ has a pole of order $2$ at $s=1$ and poles 
at the points $s=-n$ for $n=0$, $1$, $2$, \dots From \eqref{H1eq} we know the main 
part at  these poles. It follows easily that $Z_\alpha(s)$ has a pole of order $2$ at
$s=1$ and simple poles at the odd negative integers $s=-1$, $s=-3$, \dots 

Finally near $s=1$ we have 
\begin{multline}
Z_\alpha(s)=\frac{1}{\Gamma(s/2)}
\frac{1}{4\sqrt{\pi}}\Bigl\{\frac{2}{(s-1)^2}+\log\frac{e^{-C_0}}{16\pi^2}
\frac{1}{s-1}+\sum_{n=0}^\infty c_n(s-1)^n\Bigr\}=\\
=\Bigl\{\frac{1}{4\pi}+\frac{C_0+\log4}{8\pi}(s-1)+\dots\Bigr\}
\Bigl\{\frac{2}{(s-1)^2}+\log\frac{e^{-C_0}}{16\pi^2}
\frac{1}{s-1}+\dots\Bigr\}=\\
=\frac{1}{2\pi}\Bigl\{\frac{1}{(s-1)^2}-\frac{\log2\pi}{(s-1)}+\cdots\Bigr\}.
\end{multline}
So the function $Z_\alpha(s)$ has a double pole at $s=1$ with residue $-\frac{\log2\pi}{2\pi}$ and main part  given above.

In the same way near $s=-2n$ with $n=0$, $1$, \dots 
\begin{multline}
Z_\alpha(s)=\Bigl\{(-1)^n \,n!	\frac12(s+2n)+\cdots\Bigr\}
\Bigl\{\frac{a_{2n+1}}{\Gamma(1+n)}\frac{1}{2n+s}+\cdots\Bigr\}=\\
(-1)^{n}\frac{a_{2n+1}}{2}+\Orden(s+2n).
\end{multline}
This is equivalent to \eqref{Zvalue}. 

And near the point $s=-(2n-1)$ with $n=1$, $2$, \dots  
\begin{multline}
Z_\alpha(s)=\Bigl\{\frac{1}{\Gamma(-n+\tfrac12)}+\cdots\Bigr\}\Bigl\{
\frac{a_{2n}}{\Gamma(n+\frac12)}\frac{1}{s+2n-1}+\cdots\Bigr\}=\\
=(-1)^{n}\frac{  a_{2n}}{\pi(s+2n-1)}+\cdots\qedhere
\end{multline}
\end{proof}




