\section{Dyson Series for Commuting Matrices}\label{app:dyson commute}
If the Hamiltonian commutes with itself at different times, i.e., $[H(t), H(t')] = 0$ for all $t, t'$, the time-ordering becomes trivial, and the Dyson series reduces to the matrix exponential
\begin{equation}
    U(t) = \exp\left( \int_0^t H(t')\, \mathrm{d}t' \right)\,.
\end{equation}
This follows by noting that the $k$th term of the Dyson series becomes
\begin{equation}
    U^{(k)}(t) = \frac{1}{k!} \left( \int_0^t H(t')\, \mathrm{d}t' \right)^k,
\end{equation}
as all integrals are over symmetric domains in which permutations of the integrand commute.

However, this simplification does not apply to our problem. The system matrix $H_\mp(t)$ does not commute at different times
\begin{align*}
    [H_\mp(t), H_\mp(t')] = (\alpha_\mp(t') - \alpha_\mp(t)) 
    \begin{bmatrix}
        1 & 0 \\ 0 & -1
    \end{bmatrix} \neq 0.
\end{align*}



\section{Detailed Calculation of the Floquet Hamiltonian for Kapitza's Pendulum}\label{app:details}
To compute $\widetilde{H}_\pm$ we compute the individual terms. Starting with $\Omega^{(1)}_\mp$ We have
\begin{align}
    \Omega^{(1)}_\mp 
    = \int_0^T 
    \begin{bmatrix}
        0 & 1 \\
        \alpha_\mp(t') & 0
    \end{bmatrix}\;\d t'
        = T\begin{bmatrix}
    0 & 1 \\
    \mp \omega_0^2 & 0
\end{bmatrix}\,,
\end{align}
where we used
\begin{equation*}
    \mp\int_0^T \ddot{y}_\mathrm{P}(t') \;\d t' = 0\,,
\end{equation*}
as we integrate over one period of oscillation. Next we compute $\Omega^{(2)}_\mp$ via
\begin{align*}
    \Omega^{(2)}_\mp &= U_\mp^{(2)} - (\Omega_\mp^{(1)})^2 / 2\\
    &= \int_0^T\d t_1 \int_0^{t_1}\d t_2 
    \begin{bmatrix}
        0 & 1 \\
        \alpha_\mp(t_1) & 0
    \end{bmatrix}
    \begin{bmatrix}
        0 & 1 \\
        \alpha_\mp(t_2) & 0
    \end{bmatrix} 
    - \frac{T^2}{2} 
    \begin{bmatrix}
        \mp \omega_0^2 & 0 \\ 0 & \mp\omega_0^2
    \end{bmatrix} \\
    &= \int_0^T\d t_1 \int_0^{t_1}\d t_2
    \begin{bmatrix}
        \alpha_\mp(t_2) & 0 \\
        0 & \alpha_\mp(t_1)
    \end{bmatrix}
    \pm \frac{T^2\omega_0^2}{2}
    \begin{bmatrix}
    1 & 0 \\ 0 & 1    
    \end{bmatrix}\,.
\end{align*}
And with
\begin{align*}
    \int_0^T\d t_1 \int_0^{t_1}\d t_2 \; \alpha_\mp(t_2) 
    &=  \int_0^T\d t_1 \int_0^{t_1}\d t_2 \; \left( \pm\frac{A\omega}{\ell} \cos(\omega t_2) \mp \omega_0^2 \right) \\
    &= \pm\int_0^T\d t_1\; \left( \frac{A}{\ell} \sin(\omega t_1) - t_1 \omega_0^2 \right)
    = \mp \frac{T^2\omega_0^2}{2}\,,
\end{align*}
where the first integral vanishes, and
\begin{align*}
    \int_0^T\d t_1 \int_0^{t_1}\d t_2 \; \alpha_\mp(t_1) 
    & = \int_0^T\d t_1 \; t_1 \alpha_\mp(t_1) \\
    &=  \pm\int_0^T\d t_1\; \left( \frac{A\omega}{\ell} t_1\cos(\omega t_1) - t_1\omega_0^2 \right)
    = \mp \frac{T^2\omega_0^2}{2}\,,
\end{align*}
where again the first integral vanishes, we get
\begin{equation}
    \Omega^{(2)}_\mp = 0\,.
\end{equation}
So we only have $U^{(3)}(T)$ left to calculate, which is given by
\begin{align*}
    U^{(3)}(T) 
    &= \int_0^T\d t_1 \int_0^{t_1}\d t_2 \int_0^{t_2}\d t_3
    \begin{bmatrix}
        0 & 1 \\ \alpha_\pm(t_1) & 0
    \end{bmatrix}
    \begin{bmatrix}
        0 & 1 \\ \alpha_\pm(t_2) & 0
    \end{bmatrix}
    \begin{bmatrix}
        0 & 1 \\ \alpha_\pm(t_3) & 0
    \end{bmatrix} \\
    &= \int_0^T\d t_1 \int_0^{t_1}\d t_2 \int_0^{t_2}\d t_3
    \begin{bmatrix}
        0 & \alpha_\pm(t_2) \\ \alpha_\pm(t_3) \alpha_\pm(t_1) & 0
    \end{bmatrix}\,.
\end{align*}
And we have
\begin{align*}
    \int_0^T\d t_1 \int_0^{t_1}\d t_2 \int_0^{t_2}\d t_3\; \alpha_\mp(t_2)  
    &= \int_0^T\d t_1 \int_0^{t_1}\d t_2 \; t_2 \alpha_\pm(t_2) \\
    &= \pm\int_0^T\d t_1 \int_0^{t_1}\d t_2 \; t_2 \left( \frac{A\omega^2}{\ell} \cos(\omega t_2) - \omega_0^2\right) \\
    &= \pm \frac{A\omega^2}{\ell} \int_0^T \d t_1 \underbrace{ \int_0^{t_1} \d t_2\; t_2\cos(\omega t_2)}_{\frac{t_1\sin(\omega t_1)}{\omega} + \frac{\cos(\omega t_1)}{\omega^2} -\frac{1}{\omega^2} } \mp \frac{\omega_0^2 T^3}{6} \\
    &=  \mp \frac{\omega_0^2 T^3}{6} \mp \frac{2A T}{\ell}\,,
\end{align*}
where we used that $\int_0^T\d t_1 \frac{t_1 \sin(\omega t_1)}{\omega} = -\frac{T}{\omega^2}$.
For the other term we get
\begin{align*}
    \int_0^T&\d t_1 \int_0^{t_1}\d t_2 \int_0^{t_2}\d t_3\;\alpha_\mp(t_1) \alpha_\mp(t_3) \\
    &= \int_0^T\d t_1 \; \left( \pm \frac{A\omega^2}{\ell}\cos(\omega t_1) \mp \omega_0^2 \right) \overbrace{\int_0^{t_1} \d t_2 \int_0^{t_2}\d t_3 \left( \pm \frac{A\omega^2}{\ell}\cos(\omega t_3) \mp \omega_0^2 \right)}^{\mp \frac{A}{\ell} \cos(\omega t_1) \pm \frac{A}{\ell} \mp \frac{\omega_0^2 t_1^2}{2}} \\
    &= - \frac{A^2\omega^2 T}{2\ell^2} - \frac{2A\omega_0^2 T}{\ell} + \frac{\omega_0^4 T^3}{6}\,,
\end{align*}
With that we have everything together and calculate
\begin{align*}
    \Omega^{(3)} 
    &= U^{(3)} - \frac{1}{6}(\Omega^{(1)})^3 \\
    &= 
    \begin{bmatrix}
        0 & \mp \frac{\omega_0^2 T^3}{6} \mp \frac{2AT}{\ell} \\
        - \frac{A^2\omega^2 T}{2\ell^2} - \frac{2A\omega_0^2 T}{\ell} + \frac{\omega_0^4 T^3}{6} & 0
    \end{bmatrix}
    - \frac{1}{6}
    \begin{bmatrix}
        0 & T \\ \mp \omega_0^2 T & 0
    \end{bmatrix}^3 \\
    &= 
    \begin{bmatrix}
        0 & \mp \frac{\omega_0^2 T^3}{6} \mp \frac{2AT}{\ell} \\
        - \frac{A^2\omega^2 T}{2\ell^2} - \frac{2A\omega_0^2 T}{\ell} + \frac{\omega_0^4 T^3}{6} & 0
    \end{bmatrix}
    - \frac{1}{6}
    \begin{bmatrix}
        0 & \mp \omega_0^2 T^3 \\ \omega_0^4 T^3 & 0
    \end{bmatrix} \\
    &=
    \begin{bmatrix}
        0 & \mp \frac{2AT}{\ell} \\
        - \frac{A^2\omega^2 T}{2\ell^2} - \frac{2A\omega_0^2 T}{\ell} & 0
    \end{bmatrix}\,.
\end{align*}
In total, we get
\begin{align}
    \widetilde{H}_\mp &\approx \frac{\Omega^{(1)}_\mp + \Omega^{(2)}_\mp + \Omega^{(3)}_\mp}{T}
    =
    \begin{bmatrix}
        0 & 1 \mp \frac{2A}{\ell} \\
        \mp \omega_0^2 - \frac{A^2\omega^2}{2\ell^2} - \frac{2A\omega_0^2}{\ell} & 0
    \end{bmatrix}\,,
\end{align}
which can be further approximated for small amplitude $A\ll 1$ as
\begin{align}
    \widetilde{H}_\mp \approx 
    \begin{bmatrix}
        0 & 1 \\
        - \frac{1}{2}\left(\frac{A\omega}{\ell}\right)^2 \mp \omega_0^2 & 0
    \end{bmatrix}\,.
\end{align}

