\caption{The relation of $B$ and $B^\mu$} \label{fig:matop1}
\end{figure}


By  assumption (ARI1), 
$B^\mu$ maps $\ell^{2}$ to $\ell^{2}$, because the constant
weight $1$ is admissible. Since  $B$ is assumed
to be invertible on $\ell^{2}_\mu$ and 
 since all three operators  in the
factorization  $ B^{\mu } = \diag{\mu} \cdot
B \cdot \diag{1/\mu}$   are isomorphisms,
$B^\mu$ is then invertible on $\ell^{2}$. 
Because $B^\mu \in \cA$, we also have 
${\left(B^\mu\right)}^{-1} \in \cA$.

Consider the expected inverse of $B$ of the form $C 
= \diag{1/\mu} \cdot {\left(B^\mu\right)}^{-1} \cdot
\diag{\mu}$. Then, as in \eqref{eq:c8} 
$C$ is bounded on all $\ell^p_{m \mu}$ with $\fatm
\in W$. We compute the product  
$$C \cdot B 
= \diag{1/\mu}\cdot \Big({B^\mu}\Big)^{-1}\cdot \underbrace{\diag{\mu} \cdot B \cdot \diag{1/\mu}}_{B^\mu} \cdot \diag{\mu} = 
\identity{\ell^p_{m \mu}}.$$
Likewise 
\begin{eqnarray*} B \cdot C & = & \diag{1/\mu} \cdot \diag{\mu} \cdot B \cdot \diag{1/\mu} \cdot {\left(B^\mu\right)}^{-1} \cdot \diag{\mu} = \\
& = &
\diag{1/\mu} B^\mu {\left(B^\mu\right)}^{-1} \diag{\mu} = \identity{\ell^p_{m \mu}}.
\end{eqnarray*}
Consequently, $C$ is the inverse of $B$ 
on $\ell^p_{m \mu}$, so $B$ is invertible on
all $\ell^p_{m \mu}$.
\end{proof}


\subsection{$\cA$-Localized Frames  and Coorbit Spaces}
The idea of coorbit spaces is to define  Banach spaces attached to a given frame by
imposing conditions on the (dual) frame coefficients. Informally, 
one can impose a norm
$$
\|f\|_{\hpm} = \Big( \sum _{k\in K} |\langle f, \tilde{\psi_k }\rangle | m_k^p
\Big)^{1/p} = \|C_{\Psi} f \|_{\lpm } \,.
$$
As long as $\lpm \subseteq \ell ^2$, the frame expansion \eqref{eq:1}
makes sense, and then $\HHmp $, defined as those elements where this norm is
finite, is a subspace of $\Hil$. If $\lpm \not \subseteq \ell ^2 $, one
takes an abstract norm completion. 

For a meaningful theory of $\hpm $ one needs the concept of localized
frames~\cite{bacahela06,forngroech1,gr04-1}. These are 
central in all contexts  where frame theory is used to describe
properties of functions and distributions beyond mere Hilbert
space properties \cite{gr04-1,Dahlkeetal10, Balan2011}.
In this section, we review the concept of self-localized frames from \cite{forngroech1}, see also \cite{xxlgro14} for details.


\begin{def.} \label{def:localfram0}
Let $\cA$ be an ARI-algebra. Two frames   $\Psi$ and $\Phi$
in a Hilbert space $\Hil$ are said to be  mutually $\cA
$-localized, if their cross-Gramian matrix  $G_{\Psi,
  \Phi}$ 
	is in
$\cA$. We write  $\Psi \sim_{\cA} 
\Phi$. 

 If $\Psi \sim_{\cA} \Psi$, i.e., $G_{\Psi } \in \cA $,
 then 
 $\Psi $ is called an $\cA$-localized  frame. 
\end{def.}  
We mention that $\sim _{\cA}$ is an equivalence relation on the
collection of all $\cA$-localized frames. 
Let $\Psi $ be a frame with canonical dual frame $\DPsi $. 
Let $\Hil^{0 0}= \mathrm{span} \, \{\psi _k: k\in K\}$ be the subspace
of finite linear combinations of vectors in $\Psi $.

\begin{def.}
The Banach space  $\HHmp(\Psi,\DPsi)$  is defined as  the completion of
$\Hil^{0 0} $  with respect to the norm
$$
\norm{\HHmp}{f} =
\norm{\ell^p_{m}}{C_{\DPsi}(f)}$$ for $1 \le p <
\infty $.

For $p = \infty$ we  consider two  completions. First
$\Hil_{m}^0$ is completion  of $\Hil _{00} $ with
respect to the  norm $
\norm{\ell^\infty_{m}}{C_{\DPsi}(f)}$, and second  
$\Hil_{m}^{\infty}$ is   the completion of $\Hil^{0 0} $ in the weak$^*$-topology
with respect to duality  $\sigma(\Hil,
\Hil^{0 0} )$, such that   $\norm{\Hil_{m}^\infty}{f} =
\norm{\ell^\infty_{m}}{C_{\tilde \psi}(f)}$ is finite. 
\end{def.}
  Alternatively,
$\Hil_{m}^{\infty}$ can be identified with the bidual of
$\Hil _{m}^0$. For the subtleties of
this completion we refer to  \cite{xxlgro14}. 

Since $\hpm $ is defined by a property of the transform $f \mapsto
C_\Psi f $, we call $\hpm $ a \emph{coorbit} space with respect the
the frame $\Psi $, in analogy to the theory of coorbit spaces with
respect to group representations where the transform is a
representation coefficient~\cite{fg89jfa}.

The main theorem about localized frames ~\cite{forngroech1} is the fact that their
canonical  dual frames are also localized.

\begin{theorem}\label{locmain}
  If $\Psi $ is $\cA $-localized, then so is its canonical dual frame
  $\tilde{\Psi}$. The frames $\Psi $ and $\tilde{\Psi}$ are mutually $\cA
  $-localized, i.e., $\Psi \sim_{\cA} \Psi$ $\Longrightarrow$ $\DPsi \sim_{\cA} \DPsi$ and $\DPsi \sim_{\cA} \Psi$.
\end{theorem}
In the language of the Gram matrices this fact is expressed by the
implication
\begin{equation}
  \label{eq:c7}
  G_{\Psi, \Psi } \in \cA \quad \Rightarrow \quad  G_{\tilde{\Psi },
    \tilde{\Psi}  } \in \cA   \quad \text{ and } \,\,  G_{
    \tilde{\Psi},\Psi  } \in \cA  \, .
\end{equation}

It follows  that the synthesis operator
 can be extended to $\lpm $: $D_{\Psi}$ is  bounded  from
 $\ell_{m}^p $ to $ \HHmp$
for all $1 \le p  \leq \infty$ and $p = 0$. This   follows from
Theorem~\ref{locmain}, because for every $\cA $-admissible weight $m$
\begin{equation}
  \label{eq:dbound}
\|D_\Psi c \|_{\hpm } =
\|C_{\tilde{\Psi}} D_\Psi c\|_{\lpm }= \|G_{\tilde{\Psi },\Psi}
  c\|_{\lpm} \leq   C \, \|c\|_{\lpm } \, .  
\end{equation}
Likewise the analysis operator $C_{\Psi } $ can be extended to a
bounded operator from $\hpm $ to $\lpm $ for every $\cA$-admissible
weight $m$. As a consequence \cite{forngroech1,xxlgro14}  the
frame reconstruction formula 
\begin{equation} \label{eq:locreconstr1}
f = \sum \limits_k \Big< f ,  \psi_k\Big> \tilde \psi_k  = \sum \limits_k \left< f , \tilde  \psi_k\right> \psi_k ,
\end{equation}
holds on $\hpm $  for $1 \le p \leq \infty$ and $\cA $-admissible
weight $m$. The convergence is  unconditional  for $1 \le p < \infty$ and weak-* unconditional convergence for $p = \infty$.

Theorem~\ref{locmain} is based strongly on the assumption that the
Gram matrix of $\Psi $ is in an inverse-closed matrix algebra
$\cA$. We consider it our main contribution to have identified those
appropriate abstract conditions on frames  (localization and inverse-closedness)
that  raise the   theory of lifting theorems to this highly abstract level.

Another important consequence of Theorem~\ref{locmain} is the
independence of the coorbit space $\hpm $ of the particular frame.
\begin{prop.}\label{locmain2}
Let $\Phi $ and $\Psi $ be two frames for $\Hil $. Assume that
$\Psi $ is $\cA $-localized and $ \Phi \sim_{\cA} \Psi$. Then the
spaces $\Hil_{m}^p ( \Psi, \DPsi)$, $\Hil_{m}^p (
\DPsi, \Psi)$,   and $ \Hil_{m}^p ( \Phi, \DPhi)$ coincide
and the respective  norms are equivalent, i.e. 
\begin{equation}\label{eq:eqnorm1}
\norm{\HHmp}{f} = \norm{\ell_{m}^p}{C_{\DPsi}f}  \asymp
\norm{\ell_{m}^p}{C_{\Psi} f} \asymp  \norm{\ell_{m}^p}{C_{\Phi}f} \, .
\end{equation}
\end{prop.}
It therefore makes sense to write unambiguously $\HHmp :=
\Hil_{m}^p ( \Psi, \DPsi) =  \Hil_{m}^p (\DPsi,
\Psi)$.  Thus $\hpm $ depends only on the $\sim _{\cA }
$-equivalence class of a  frame. 

The duality of the coorbit spaces is inherited from the $\ell
^p$-spaces:  we have $\left(\Hil_{m}^p\right)' =
\Hil_{1/m}^{p'}$ for $1 \le p < \infty$ with the duality
relation  
\begin{equation} \label{eq:dualrel}
\left< f , g \right>_{
\Hil_{m}^p \times \Hil_{1/m}^{p'}
} = 
\left< C_{\DPsi} f, C_{\Psi} g  \right>_{\ell^p_m \times
  \ell^{p'}_{1/m}} = \sum _{k\in K } \langle f, \tilde{\psi
  _k} \rangle \, \overline{\langle g, \psi _k\rangle} \, .
\end{equation}

By this construction also other properties known for the Hilbert space can be transferred to the coorbit spaces, like the fact that $D_\Psi^* = C_\Psi$, and related to that the following result \cite{xxlgro14}:
\begin{lem.}\label{lem:gramoper1} 
Let  $\Psi$ be a $\cA$-localized frame. 
Then the Gram matrix 
$G_{\Psi,\DPsi}$ is the orthogonal  projection from
$\ell ^2$  onto the range of $C_\Psi$ with kernel
$\kernel{D_{\Psi}}$. The extension of $G_{\Psi,\DPsi}$ is a
bounded projection from $\ell_{m}^p$  onto the range of
$C_\Psi \subseteq \lpm $ with kernel
$\kernel{D_{\Psi}}\subseteq \lpm $. 
In addition, $ \ell_{m}^p = \range{C_{\Psi}} \oplus \kernel{D_{\Psi}}$.
\end{lem.}

We will apply the decisive Proposition~\ref{prop:Greoch0}  to the Gram matrix
$G_\Psi $ of a localized frame. For this we need to know that various
weighted Gram matrices also belong to the same matrix algebra, in some sense an extension of \eqref{eq:c7}.

\begin{prop.} \label{def:multlocal2}
Let $\cA$ be an ARI-algebra, and $\Psi$ an $\cA$-localized frame, with $G_\Psi^\mu \in \cA$, additionally. Then the following Gram matrices are also in the matrix algebra $\cA$: 
 $G_\Psi^{1/\mu}$, $G_{\DPsi}^\mu$, $G_{\DPsi}^{1/\mu}$, $G_{\Psi,\DPsi}^\mu$, and $G_{\Psi,\DPsi}^{1/\mu}$.
\end{prop.} 
\begin{proof}
  First we note that the Gram matrix is self-adjoint, therefore $G_\Psi ^{1/\mu
  } =  (G_\Psi ^\mu )^*$ is in $\cA $ (this is where we
  use that $\cA $ is a $^*$-algebra). 

Note that if $B$ has closed range in $\ell^2_\mu$, so has $B^\mu$ (in $\ell^2$). Indeed consider $c \in \ell^2$, then 
$$ \norm{\ell^2}{B^\mu c} = \norm{\ell^2}{\diag{\mu} \cdot B
  \cdot \diag{\tfrac{1}{\mu}} c} = \norm{\ell^2_\mu}{B
  \cdot \diag{\tfrac{1}{\mu}} c} \ge $$
  $$ \ge m \cdot  \norm{\ell^2_\mu}{\diag{\tfrac{1}{\mu}}c}  =
   m \cdot  \norm{\ell^2}{c}. $$
   Then it is easy to see that the pseudo-inverse of a matrix $B$ with
  closed range  satisfies  
  ${\left(B^{\mu}\right)}^\dagger =
  {\left(B^\dagger\right)}^\mu$. 
  We know that $\cA$ is pseudo-inverse-closed \cite[Thm.~3.4]{forngroech1}, and therefore if $B^\mu \in \cA$ then also $\left(B^\mu\right)^\dagger$. In particular we have $\left(G_\Psi^\mu\right)^\dagger =  \left(G_\Psi^\dagger\right)^\mu = G_{\DPsi}^\mu \in \cA$.
  Since 
  $G_{\Psi,\DPsi} =
  G_{\Psi}^\dagger  G_{\Psi}$ by 
  \eqref{eq:re7}, we obtain
  that  $G_{\Psi,\DPsi}^\mu =
  \big(G_{\Psi}^\dagger \big)^\mu G_{\Psi}^\mu$ is also in $\cA
  $. 
Since $G_{\Psi,\DPsi}^{1/\mu} = \left( G_{\DPsi,\Psi}^\mu \right)^* =  \left( G_{\Psi,\DPsi}^\mu \right)^*$ we are done.

\end{proof}

\subsection{Galerkin-like Representations of Operators} 
To use the power of the underlying matrix algebra, we next represent
operators by their matrix with respect to a frame~\cite{xxlgro14,xxlframoper1}. 

Let $\Psi$ and $\Phi$ be frames with $\Psi \sim_{\cA} \Psi$ and $\Phi\sim_{\cA} \Psi$.
Let $m_1, m_2 \in W$  
and  $1 \le   p_1,p_2 \le \infty$. 
Then for a  bounded linear operator $O :
  \Hil_{m_1}^{p_1} \rightarrow \Hil_{m_2}^{p_2}$ we define the matrix $
  \Mate^{\left(\Phi , \Psi\right)}(O)$ 
by its entries \begin{equation} \label{eq:Galerkin}
{\Matt{\Phi , \Psi}{O}}_{k,l} = 
\left<O \psi_l, \phi_k
\right>_{\Hil^{p_2}_{m_2},\Hil_{1/m_2}^{p_2'}}
\qquad k,l\in K \, . 
\end{equation}
 In the notation of the frame operators the operator correpsonding to this matrix is
 given as
 $$
 \Matt{\Phi , \Psi}{O} = C_\Phi O D_\Psi \, .
 $$
If $O \in \mathcal{B}(  \Hil_{m_1}^{p_1},
\Hil_{m_2}^{p_2})$, then by the mapping properties of
$C_\Phi $ and $D_\Psi $, the matrix $ \Matt{\Phi , \Psi}{O}$  induces a bounded operator from $\ell_{m_1}^{p_1}$ into $\ell_{m_2}^{p_2}$. 
We call $\Matt{\Phi , \Psi}{O}$
 the \emph{(Galerkin) matrix of $O$ with respect to $\Phi$
   and $\Psi$}.
Conversely, every    operator (matrix) 
  $M\in
  \BL{\ell_{m_1}^{p_1},\ell_{m_2}^{p_2}}$ defines an
  operator 
$ {\Ope}^{(\Phi , \Psi)}(M) \in
 \BL{\Hil_{m_1}^{p_1},\Hil_{m_2}^{p_2}}$ by
\begin{equation} \label{sec:opematr2} \left( \Opp{\Phi , \Psi}{M} \right) f = \sum \limits_k  \Big( \sum
    \limits_j M_{k,j} \left<f, \psi_j\right> \Big) \phi_k  = D_\Phi M C_\Psi f,
\end{equation}
for $f \in \Hil_{m_1}^{p_1}$ with unconditional convergence for $1 \le p_i < \infty$ and unconditional weak$*$-convergence otherwise. 
We call $\Opp{\Phi , \Psi}{M}$ the \emph{operator of
  $M$ with respect to $\Phi$ and
  $\Psi$}. Altogether, we obtain a mapping 
$ {\Ope}^{(\Phi , \Psi)}:
\BL{\ell_{m_1}^{p_1},\ell_{m_2}^{p_2}} \to 
 \BL{\Hil_{m_1}^{p_1},\Hil_{m_2}^{p_2}}   $ from matrices to
operators between coorbit spaces.  

In \cite{xxlgro14} it was shown that $\Ope$ is a left-inverse
of $m$ as follows. 
\begin{prop.} \label{sec:propmatropfram1} Let $\Psi$ and $\Phi$
  be $\cA$-localized frames in $\Hil$ satisfying $\Phi\sim
  _{\mathcal{A}} \Psi $ and
  $m_1, m_2\in W$, 
  and $1 \le p_1,p_2 \le
  \infty$ or $p_1,p_2= 0$. Then 
$$ \left( \Op{\Phi , \Psi}{} \circ \Mat{\DPhi, \DPsi}\right)  = \left( {\Op{\DPhi, \DPsi} \circ \Mat{\Phi , \Psi}
}\right) = \identity{\BL{\Hil_{m_1}^{p_1},\Hil_{m_2}^{p_2}}}.$$
\end{prop.}

Within  this formalism,  a frame  multiplier corresponds to a  diagonal
matrix in the sense that
$$
\MM_{m, \Psi, \Phi} = \Opp{\Phi , \Psi}{\diag{m}}
= D_{\Phi } \diag{m} C_{\Psi } 
\, .
$$

\subsection{Invertibility of operators on coorbit spaces.} The factorization 
\sloppy \mbox{$\Matt{\Phi , \Psi}{O}= C_\Phi O D_{\Psi }$} implies that
$\kernel{D_\Psi}  \subseteq  \kernel{\Matt{\Phi , \Psi}{O}}$,  which is always non-trivial for redundant frames. Therefore
$\Matt{\Phi , \Psi}{O}$ can never be  invertible on the whole
sequence space for redundant
frames, but only on the range of the analysis operator. Using the
projection property of $G_{\Psi, \widetilde \Psi}$ from  Lemma
\ref{lem:gramoper1}, the invertibility of an operator on a coorbit
space can be understood  by means of its
Galerkin matrix as follows. 
\begin{lem.}\label{inverse0} Let $\Psi$ and $\Phi$
  be $\cA$-localized frames in $\Hil$ satisfying $\Phi\sim
  _{\mathcal{A}} \Psi $. Let $m$ be 
  an $\mathcal{A}$-admissible weight and $1 \le p \le
  \infty$ or $p= 0$. 
  A bounded operator $O: \Hil_{m}^p \rightarrow \Hil_{m}^p $ is invertible, if and only if the matrix
  $B_O = \Matt{\Psi, \Phi}{O} + \left( \identity{} - G_{\Psi,\DPsi} \right)$ is invertible on $\ell_{m} ^p$. 
\end{lem.}
The proof of this result can be found in \cite{grpfto22}, Lemma 4.10  and
Thm. 4.11., stated there for Gabor frames and pseudodifferential
operators, but using only general frame properties. 
For an alternative proof using the pseudoinverse $M^\dagger$ of a matrix
 $M$ and the formula $\Matt{\Phi , \Psi}{O\inv}= \Matt{\DPsi ,
   \DPhi}{O} ^\dagger $ see~\cite[Lemma~11]{xxlgro14}.

With this approach we can extend the spectral invariance result of
Corollary~\ref{cor:specinv1}  to the level of  Hilbert space, and we
obtain a universal invertibility result  \cite{xxlgro14}:
 \begin{theorem} \label{sec:theorem6} 
Let $\Psi$ and $\Phi$
  be $\cA$-localized frames in $\Hil$ satisfying $\Phi \sim
  _{\mathcal{A}} \Psi $.
  Assume that $O: \Hil \to \Hil $
  is invertible and that $ \Matt{\Psi  , \DPsi}{O}
  \in \mathcal{A}$. Then $O$ is invertible simultaneously on all
  coorbit spaces $\Hil^p_{m}$, $1\leq p \leq \infty $ for all $\cA$-admissible weights 
  $m$ and $1 \le p \le
  \infty$ or $p= 0$.  
 \end{theorem}

\section{Lifting Properties for Localized Multipliers}
\label{sec:mulisom0}


After setting up the theory of localized frames and matrix algebras,
we can  finally provide a rigorous formulation of our main result and
prove 
the  lifting theorem for coorbit spaces. 

\begin{theorem}[Abstract lifting theorem for coorbit
  spaces] \label{th:multrecip} Let $\cA$ be an ARI-algebra and
  $\mu$, $m \sqrt{\mu}$ and
  $\frac{m}{\sqrt{\mu}}$ be $\cA$-admissible weights.  
Let $\Psi$ be $\cA$-localized frame satisfying the additional
conditions that
$  G_{\Psi}^{\mu} \in \cA$. 

 Then the frame multiplier 
$\MM_{\mu, \Psi} $ is an isomorphism   from  $ \Hil_{m
  \sqrt{\mu}}^p$ onto $  \Hil_{m/\sqrt{\mu}}^p$. 
Likewise, $\MM_{1/\mu , \Psi}$ is an isomorphism from $\Hil_{\frac{m}{\sqrt{\mu}}}^p$ onto $\Hil_{m \sqrt{\mu}}^p$.
\end{theorem}

The remainder of this section is devoted to the proof of the main
theorem, which we  split  into lemmas. 

\subsection{Boundedness of the Multiplier}
We first formulate the mapping properties of frame multipliers on
coorbit spaces. Throughout we assume that $\cA$ is an ARI-algebra.  
For this setting one can go beyond the bounded symbol setting  \cite{xxlmult1} to get bounded operators. 
\begin{lem.} \label{lem:boundmul1}  Let $\Psi$ and $\Phi$ be $\cA$-localized frames.
Let ${\mu}$ and $m$  be  weights such that both  ${m
  \sqrt{\mu}}$ and ${m/\sqrt{\mu}}$ are  $\cA$-admissible. 
Then for all $1\le p \le \infty$ and $p= 0$
$$ \MM_{\mu,\Phi,\Psi} \in \BL{\Hil_{m \sqrt{\mu}}^p,\Hil_{\frac{m}{\sqrt{\mu}}}^p} \text{ and } \MM_{1/\mu,\Phi,\Psi}  \in \BL{\Hil_{\\frac{m}{\sqrt{\mu}}}^p,\Hil_{m \sqrt{\mu}}^p}.
$$
\end{lem.}
\begin{proof} Recall that the frame multiplier factorizes as 
$ \MM_{\mu,\Phi,\Psi} = D_\Phi ~ \diag{\mu} ~ C_\Psi$. Since
$\diag{\mu}$ is an isomorphism from   
$\ell_{m \sqrt{\mu}}^p$ onto
$\ell_{\frac{m}{\sqrt{\mu}}}^p$ by
 Lemma~ \ref{lpiso}, and since both  $D_\Phi$ and
$C_{\Psi}$ are bounded by \eqref{eq:dbound}, we obtain the result. 
\end{proof}

\subsection{Coercivity of the Multiplier}

For the next step we use a coercivity argument that is familiar from the theory of
elliptic partial differential operators~\cite{evans}. In the
context of time-frequency analysis a similar argument was used
in~\cite{grochenig2011isomorphism}. 

\begin{theorem} \label{th:coerc} Let $\cA$ be an ARI-algebra. 
Let $\sqrt{\mu}$ be an $\cA$-admissible weight and $\Psi$ be an $\cA$-localized frame.
 Then the frame multiplier 
$$\MM_{\mu, \Psi} : \Hil_{\sqrt{\mu}}^2 \rightarrow  \Hil_{1/\sqrt{\mu}}^2 $$
is an isomorphism.

Likewise, $\MM_{1/\mu, \Psi}$ is an  isomorphism from $\Hil_{1/\sqrt{\mu}}^2 $ onto $\Hil_{\sqrt{\mu}}^2$.
\end{theorem}
\begin{proof}  Using  Lemma \ref{lem:boundmul1} with $m
  \equiv 1$, the frame multiplier  $\MM_{\mu,\Psi} :
  \Hil_{\sqrt{\mu}}^2 \rightarrow \Hil_{1/\sqrt{\mu}}^2$ is
  bounded. As in the case of elliptic differential operators we
  introduce the  sesquilinear form 
  $$[f,g] \isdef \langle \MM_{\mu, \Psi} f,  g\rangle_{\Hil_{1/\sqrt{\mu}}^2 \times \Hil_{\sqrt{\mu}}^2} $$ for $f,g \in \Hil_{\sqrt{\mu}}^2$. 
By the duality relation \eqref{eq:dualrel},  the dual space of
  $\Hil^2_{\sqrt{\mu}}$   is  $ \Hil^2_{1/\sqrt{\mu}}$, consequently
  both brackets above are 
  well-defined. 
  Therefore 
we obtain 
$$\left[ f , f \right] = \left< \MM_{\mu, \Psi} f, f\right>_{\Hil_{1/\sqrt{\mu}}^2 \times
  \Hil_{\sqrt{\mu}}^2} =  \left< \diag{\mu} C_{\Psi} f, C_{\Psi} f\right>_{\ell_{1/\sqrt{\mu}}^2,\ell_{\sqrt{\mu}}^2} $$
$$ = \sum \limits_k \mu_k \left(C_{\Psi} f\right)_k
\overline{\left(C_{\Psi} f\right)_k} = \norm{\ell_{\sqrt{\mu}}^2}{
  C_{\Psi} f }^2 \, .$$ 
Note that the $\Hil ^2_{{\sqrt{\mu}}}\,$-norm of $f$ is defined by
$\|C_\DPsi f\|_{\ell ^2_{\sqrt{\mu}}}$ with respect to the dual
frame. By the main theorem of localized frames
(Proposition~\ref{locmain2}) this norm is equivalent to $\|C_\Psi f
\| _{\ell ^2_{\sqrt{\mu}}}$. Thus we conclude that
$$
[f,f] = \|C_\Psi f \| _{\ell ^2_{\sqrt{\mu}}}^2  
\stackrel{\eqref{eq:eqnorm1}}{\asymp} \|C_\DPsi f\|_{\ell ^2_{\sqrt{\mu}}} = \|f\|^2_{\Hil_{\sqrt{\mu}}^2}
\, .$$
Consequently, if $\MM_{\mu, \Psi} f = 0$ in $\Hil_{\sqrt{\mu}}^2$, then $C_{\Psi} f = 0$, and therefore $f=0$. So $\MM_{\mu, \Psi}$ is injective.

For a converse inequality, we observe that for $f \not=0$
\begin{align*}
   \|\MM_{\mu, \Psi} f \|_{\Hil_{\frac{1}{\sqrt{\mu}}}^2} &= \sup _{\|g\|_{\Hil_{\sqrt{\mu}}^2} =1}
   \big| \langle \MM_{\mu, \Psi} f,  g\rangle_{\Hil_{1/\sqrt{\mu}}^2 \times \Hil_{\sqrt{\mu}}^2}  \big|  \\
 &  \geq \ \big| \Big\langle \MM_{\mu, \Psi} f,  \frac{f}{\| f
     \|_{\Hil_{\sqrt{\mu}}^2}}\Big\rangle_{\Hil_{1/\sqrt{\mu}}^2
     \times \Hil_{\sqrt{\mu}}^2} \big| = \frac{[f,f]}{\| f
     \|_{\Hil_{\sqrt{\mu}}^2}}\asymp 
   \|f\|_{\Hil_{\sqrt{\mu}}^2} \, .
  \end{align*}
     Consequently, $\MM_{\mu,\Psi} : \Hil_{\sqrt{\mu}}^2 \rightarrow \Hil_{1/\sqrt{\mu}}^2$ has
closed  range. By the closed range theorem, its adjoint operator
   $\MM_{\mu,\Psi}^* = \MM_{\mu,\Psi}$ is therefore onto. It
   follows that   $\MM_{\mu,\Psi} $ is an isomorphism between $
   \Hil_{\sqrt{\mu}}^2$and $ \Hil_{1/\sqrt{\mu}}^2$, as  claimed. 
\end{proof}

\subsubsection{The Galerkin Matrix of $\MM_{1/\mu, \Psi} \MM_{\mu, \Psi}$}
As an easy consequence of Theorem \ref{th:coerc}, the  composition of
these two frame multipliers gives an isomorphism of the weighted
Banach spaces into itself.  
\begin{cor.} \label{comp1}  Let 
$\Psi$ be a $\cA$-localized frame and  
 $\sqrt{\mu}$ be an $\cA$-admissible weight.  

(i) The composition $\MM_{1/\mu, \Psi} \MM_{\mu, \Psi}$ is an
  isomorphism on $\Hil_{\sqrt{\mu}}^2$. Likewise,  
   $\MM_{\mu, \Psi} \MM_{1/\mu, \Psi} $ is an isomorphism  on $\Hil_{\frac{1}{\sqrt{\mu}}}^2$. 

   (ii) The matrix associated to $\MM_{\frac{1}{\mu}, \Psi}
   \MM_{\mu, \Psi}$ is given by 
\begin{eqnarray} \label{eq:re5}
   \Matt{\Psi,\Psi}{\MM_{\frac{1}{\mu}, \Psi} \MM_{\mu,
  \Psi}} =  G_{\Psi} G_{\Psi}^{1/\mu} G_{\Psi}. 
\end{eqnarray}
 \end{cor.}


 \begin{proof}
   (i) follows from the mapping properties of
   Lemma~\ref{lem:boundmul1} and from  Theorem~\ref{th:coerc}. 

(ii) The formula of its matrix representation is given by
\begin{eqnarray} \label{eq:matrmul2}
   \Matt{\Psi,\Psi}{\MM_{\frac{1}{\mu}, \Psi} \MM_{\mu, \Psi}} \nonumber
   &=&  C_\Psi \MM_{1/\mu, \Psi} \MM_{\mu, \Psi} D_\Psi \nonumber \\
   &=& C_\Psi D_\Psi \diag{1/\mu} C_\Psi D_\Psi \diag{\mu} C_\Psi D_\Psi \nonumber \\
   &=& G_{\Psi} G_{\Psi}^{1/\mu} G_{\Psi}. 
\end{eqnarray}

 \end{proof}


 \subsection{Proof of the General Lifting Theorem}
 We finally prove the main theorem and show that the frame multiplier 
$\MM_{\mu, \Psi} $ is a (Banach space) isomorphism from $
\Hil_{m \sqrt{\mu}}^p$ onto $
\Hil_{m/\sqrt{\mu}}^p$ whenever all occurring weights are
$\cA$-admissible.  
\begin{proof}[Proof of Theorem~\ref{th:multrecip}]
(i)   We  consider the matrix
	\begin{equation} \label{eq:split1}
  B = \Matt{ \Psi,\Psi}{\MM_{1/\mu,
    \Psi} \MM_{\mu, \Psi}} + \left( \identity{} -
  G_{\Psi,\DPsi}\right)\, .
\end{equation}
Since $\MM_{1/\mu,
    \Psi} \MM_{\mu, \Psi}$ is invertible on $\Hil ^2 _{\mu }$ by
  Corollary~\ref{comp1},  we obtain from Lemma \ref{inverse0}  that
  $B$  is an isomorphism on $\ell_{\sqrt{\mu}}^2$.

(ii) Next we check that $B\in \cA $. Since by assumption  $G_{\Psi
}$ and $G_{\Psi }^\mu$ are in  $\cA $,
Proposition~\ref{def:multlocal2} implies that also  $G_{\Psi }^{1/\mu }\in
\cA $ and $G_{\Psi, \DPsi}  \in \cA $. The
factorization~\eqref{eq:re5} now   
implies  that  $B \in \cA$. 

(iii) We need to  show that also $B^\mu \in \cA$.
A small computation shows that 
\begin{eqnarray*} B^\mu  & = &  \diag{\mu} \cdot B \cdot \diag{1/\mu} \\
& = & \diag{\mu} \left( G_{\Psi} G_{\Psi}^{1/\mu} G_{\Psi}  + \left( \identity{} - G_{\Psi,\DPsi}\right) \right)  \diag{1/\mu}  \\
& = &  G_{\Psi}^{\mu} G_{\Psi}
      G_{\Psi}^{\mu}  +\identity{} -
      G_{\Psi,\DPsi}^{\mu}\, .
\end{eqnarray*}
From Proposition \ref{def:multlocal2} it follows that  $B^\mu \in \cA $ as well.


(iv) Since $B$ is invertible on $\ell ^2_\mu$ and
$B^\mu \in \cA $,  Proposition \ref{prop:Greoch0} implies
that  $B$ is (boundedly)  invertible  on all $\ell^p_{\mu
  w}$ for $1\le p\le\infty$ and $w \in W$.  
By assumption this includes the space $\ell^p_{m\sqrt{\mu}}$.
Therefore, by Lemma \ref{inverse0} again,  $\MM_{1/\mu, \Psi} \MM_{\mu, \Psi}$ is invertible on $\Hil_{m \sqrt{\mu}}^p$. 
Consequently, $\MM_{\mu, \Psi}$ is one-to-one  on $\Hil_{m\sqrt{\mu}}^p$.

(v) We now replace $\mu $ by $1/\mu $ and repeat  the argument for
$\MM_{\mu, \Psi} \MM_{1/\mu, \Psi}$. We conclude the invertibility
of $\MM_{\mu, \Psi} \MM_{1/\mu, \Psi}$ and consequently  $\MM_{\mu, \Psi}$ is surjective  onto
$\Hil_{\frac{m}{\sqrt{\mu}}}^p$,  and the isomorphism
property of $\MM_{\mu, \Psi}$  is shown. 

The preceding arguments show that  $\MM_{1/\mu, \Psi} $ is
one-to-one and onto and thus an isomorphism as well. 
\end{proof}

\begin{rem.} \label{rem:cont1}
{\rm A version of Theorem~\ref{th:multrecip} can also be shown for  continuous frames
\cite{antoin2} and corresponding multipliers \cite{xxlbayasg11}. The
proof structure remains the same, the use of integral operators
instead of matrices requires some technical modifications.} 
\end{rem.}


\section{Gabor Multipliers and Toeplitz Operators} \label{sec:appl0}

In this section we 
make explicit what the abstract lifting  theorems says
for Gabor frames and Toeplitz operators on Fock space. In both
examples we look at a  class of structured frames, then  explain
the meaning of localization, describe the associated coorbit space, and finally formulate a concrete version of the lifting
theorem. By choosing particular inverse-closed matrix algebras from
the literature, one can formulate many new and interesting lifting
theorems for Gabor multipliers and Toeplitz operators. We leave this
exercise to the reader, as they are already contained in Theorem~\ref{th:multrecip}. 

\subsection{Gabor Multipliers} \label{sec:Gabmult1}
We consider Gabor frames since these  were one of the  motivations for the
introduction of  localized frames. Gabor frames are structured frames
that are generated by \tfs s of a single function.
As usual, 
 for $x, \omega ,t \in \rd$ and $\lambda = (x,\omega )\in \rdd $, 
the \emph{time-frequency shift} $\pi \left( \lambda \right)$ is
defined by $\pi (\lambda )f(t)  =  e^{2 \pi i
   \omega t} f(t-x)$.  

 A \emph{Gabor frame}  is a frame consisting of \tfs s   $\Psi = \left\{ \pi
   (\lambda) g : \lambda \in \Lambda\right\}$. Often $\Lambda $ is
 taken to be a lattice in $\rdd $, but for the lifting theorems we
 only need to assume that
 $\Lambda \subseteq \rdd $ is relatively separated.  

The frame multipliers corresponding to a Gabor frame are called  Gabor
multipliers and have already been studied in the context of \tfa
\cite{feinow1,benepfand07,babacofesc22}. Given a symbol $\mu$ on $\Lambda $ and a window
$g$, the
associated  multiplier is defined as
$$
m_\mu f = \sum \limits_{\lambda \in \Lambda} \mu_\lambda \, 
\ip{f}{\pi(\lambda) g}\, \pi(\lambda) g \, .
$$ 

To describe the localization of a Gabor frame operator we use the
Jaffard algebra of Example~\ref{exjaffard} and impose a condition of
polynomial off-diagonal decay on the Gram matrix.  Using the \stft ,
one can find condition such that the Gram matrix  $G$ belongs to the Jaffard
algebra $\cA _s$, i.e. for all $ \lambda  , \lambda ' \in \Lambda $
\begin{align} \label{eq:rev1}
  |G_{\lambda ,\lambda ' } | = |\langle \pi (\lambda ')g, \pi (\lambda
  )g \rangle |
  = | \langle g, \pi (\lambda -\lambda ') \rangle|  \leq C
  (1+|\lambda -\lambda ' |)^{-s} \,
  \, .
\end{align}
We have  already seen that the class of $t$-moderate weights, i.e.,
$m$ satisfies $m(\lambda +\lambda ' ) \leq C (1+|\lambda | )^t
m(\lambda ' )$ for all $\lambda , \lambda '\in \Lambda $, is $\cA _s$
admissible for $t<s-2d $ (note that $\Lambda \subseteq \rdd$).

The coorbit spaces associated to a Gabor frame can be identified with
the class of \modsp s and possess a more explicit
description. To describe these spaces,  we define the \emph{short-time Fourier
  transformation} of a function $f$ with respect to a non-zero   \emph{window}
function  $g\in \LtRd $ to be   
$$ V_g f(x,\omega) = \left< f, \pi(\lambda) g \right>_{\LtRd} = \int \limits_{\rd} f(t) 
      \overline{g(t - x)} e^{-2\pi i \omega t} \, dt \,.$$
Then the \modsp s are defined as follows. 

\begin{def.} Fix a non-zero window $g \in \cS$, a $t$-moderate weight
  function $m$ on $\rdd$ for some $t>0$ and $1\le p\le \infty$. Then the \emph{modulation space}  $\Mpm$  consists of all tempered distributions $f \in \mathcal S' (\rd)$ such that $V_g f \in \Lpm$. The norm on $\Mpm$ is
$$ \norm{\Mpm}{f} = \norm{\Lpm}{V_g f} $$
\end{def.}
It can be shown \cite{gr01} that the spaces defined above do not depend on the
special choice of the non-zero test function $g$, as long as it is
sufficiently well concentrated in the time frequency sense. Different
functions define the same space with equivalent norms. Moreover these
functions spaces are Banach spaces that are invariant under time-frequency
shifts  \cite{gr01}.
 Note that the Gram matrix $G $ of a Gabor frame is in the Jaffard algebra $ \cA
_s$ - see \eqref{eq:rev1} -  if and only if the window $g$ is in the modulation space $
M^\infty _{w_s}$ for the weight function $w_s(z)  = (1+|z|)^s$. Thus
in \tfa\  properties of the Gram matrix can be translated directly
into properties of the underlying window $g$. 

As a first application of localized frames  in~\cite{forngroech1},  the coorbit spaces with respect
to a Gabor frame $\{ \pi (\lambda )g: \lambda \in \Lambda \}$
was shown to be identical to a \modsp . Precisely,  $\Mpm =
\Hil_{\tilde{m}}^p$, where $\tilde{m}$ is the restriction of the
weight $m$ to $\Lambda $. 
So our lifting theorem leads to the following result in the context of
\tfa . 
\begin{theorem} \label{th:liftGab} 
Fix $s >2d$ and let $a>2s-2d$. Let $g \in M_{w_a}^{\infty}
(\rd)$ and  assume that  $\Lambda \subseteq \rd$ be a relatively separated set, such that $\left\{ \pi(\lambda) g \right\}$ is a Gabor frame. 
Assume that $\mu , m\sqrt{\mu }$, and $m/\sqrt{\mu }$ are
$t$-moderate weights for $t<s-2d$. 

Then,  for all $1\le p \le \infty$, the  Gabor multiplier
 $m_\mu$ is an isomorphism from $M_{m \sqrt{\mu}}^p(\rd)$
 onto $M_{\frac{m}{\sqrt{\mu}}}^p(\rd)$. 
\end{theorem}

\begin{proof}
The underlying ARI-algebra is the Jaffard algebra $\cA _s$ discussed
in Example~\ref{exjaffard}.  As the  class of $\cA _s$-admissible
weights we take 
 all $t$-moderate weights with $t<s-2d$, whence comes the
assumption on the weights.

If $g\in M_{w_a}^{\infty} (\rd)$, then the Gram matrix of the frame
satisfies \cite{forngroech1}
$$
  |G_{\lambda ,\lambda ' } | 
  = |V_gg(\lambda -\lambda ' )| \leq C
  (1+|\lambda -\lambda ' |)^{-a} \leq C (1+|\lambda -\lambda ' |)^{-s}  \, \quad \forall \lambda  , \lambda ' \in \Lambda
  \, , 
$$
and consequently $G\in \cA _s$. In view of
Theorem~\ref{th:multrecip} we also need that $ G^{\mu} =
\diag{\mu}  \, \, G\, \, 
 \diag{\tfrac{1}{\mu}}   \,  
    \in \cA _s$. Note that $G^\mu $ has the entries $\frac{\mu
    _\lambda }{ \mu _{\lambda '}} G_{\lambda ,\lambda ' }$
    and that $\mu _\lambda \leq (1+|\lambda - \lambda '|)^t\,  \mu
    _{\lambda '}$ because $\mu $ is $t$-moderate. Therefore
    $$
    \frac{\mu     _\lambda }{\mu _{\lambda '}} \,  |G_{\lambda ,\lambda '
    }|\leq (1+|\lambda - \lambda '|)^{t-a} \qquad \text{ for all }
    \lambda , \lambda ' \in \Lambda \, .
    $$
    Since $a>2s-2d>s + t$  and thus $t-a<-s$ by assumption, we
    conclude that  $G^{\mu} \in \cA
    _s$ and $G^{1/\mu}\in \cA _s$. 

We have verified all hypothesis of Theorem~\ref{th:multrecip} and
conclude that the Gabor multiplier   $m_\mu $ maps  the
space $\Hil ^p_{m\sqrt{\mu } } = M^p_{m\sqrt{\mu } } (\rdd ) $ bijectively
to $\Hil ^p_{m/\sqrt{\mu } }= M^p_{m/\sqrt{\mu }
}$. 
\end{proof}

\textbf{Discussion of the literature.} It is not difficult to see and
was already proved by Feichtinger~\cite{fei83}  that for pure frequency  weights 
$m(x,\omega ) = (1+|\omega |)^s$,  the lifting operator is the
differentiation operator. 
A new generation of lifting theorems covers the class of general
    \modsp s $\Mmpq $ with a weight function $m$ depending on both
    time and frequency. 
    In this case, different
    \modsp s are related by \emph{\tf\ multipliers}, or, in a different
    terminology, by Toeplitz operators with respect to the \stft
    . These  operators are parametrized by a
    symbol $m$ depending on time \emph{and} frequency and are   much  more
    complicated  than Fourier  multipliers. Formally, they are defined
    by the vector-valued integral 
    \begin{equation}
      \label{eq:c9}
    A_\mu^g f = \intrdd \mu(z) V_gf(z) \, \pi (z) g \, dz  \, .  
    \end{equation}
    Generically,   the lifting theorems for
    general \modsp s assert that the \stft\ multiplier $A^g_\mu$ is an
    isomorphism from $M^{p,q}_{m \sqrt{\mu }} $ onto
      $M^{p,q}_{m/\sqrt{\mu }}$. The 
    proofs require a heavy dose of
    \tfa , \psdo\ theory, and abstract Banach algebra
    arguments. Various levels of generality of this lifting theorem
    are recorded ranging from  weights of
    polynomial growth to weights (sub)exponential growth ~\cite{ACT20,BToft05,grto10,grochenig2011isomorphism}% , for

    Theorem~\ref{th:liftGab} adds a further facet to these lifting
    theorems in that the \emph{function} $\mu $ in \eqref{eq:c9} is replaced by a Radon
    measure $\mu = \sum _{\lambda \in \Lambda } \mu _\lambda \delta
    _\lambda $. Theorem~\ref{th:liftGab} could possibly be proved by
    adding more technicalities to the methods
    in~\cite{grto10,grochenig2011isomorphism}, whereas 
    in our set-up the result is  a direct consequence of the abstract
    lifting theorem with localized frames. Extending the result in the current paper to the continuous setting as mentioned in Rem \ref{rem:cont1} would allow to directly show the lifting theorem for the Toeplitz operator $A_\mu^g$ with the techniques used in here.


\subsection{Fock Spaces} 
Fock spaces are Banach spaces of entire functions satisfying certain
integrability conditions. Given a non-negative weight function $m$ on
$\bC $, the Fock space $\cF ^p_m$ consists of all entire functions
with finite  norm
$$
\|F\|_{\cF ^p_m} = \Big( \int _{\bC } |F(z)|^p m(z)^p e^{-\pi p
  |z|^2/2} \, dz \Big) ^{1/p} \, .
$$
For $p=2$ and $m\equiv 1$, $\cF ^2$ is a reproducing kernel Hilbert
space  with the normalized reproducing kernel \cite{folland89,zh12} 
$$\psi _\lambda (z) = e^{\pi \bar{\lambda } z} e^{-\pi |z|^2/2} \, ,$$
so that $f(\lambda) ^{-\pi |\lambda |^2/2}  = \langle f, \psi _\lambda \rangle _{\cF ^2}$. 
The frames of reproducing kernels in $\cF ^2$ are completely
characterized by their density. The Theorem of
Lyubarskii-Seip-Wallst\'en~\cite{lyub92,sewa92} asserts that \emph{\{$ \psi _\lambda
  :\lambda \in \Lambda \}$ is a frame for $\cF ^2$, \fif\  $\Lambda
  $ contains a relatively separated subset $\Lambda '\subseteq \Lambda
  $ with  lower
Beurling $D^-(\Lambda ' ) = \lim _{r\to \infty } \inf _{z\in \bC } \frac{\mathrm{card}\,
  \Lambda \cap B_r(z)}{\pi r^2} >1$}. 
Since
$$
|\langle \psi _{\lambda '}, \psi _\lambda  \rangle |= |e^{\pi
  \bar{\lambda '} \lambda } |  e^{-\pi (|\lambda |^2 + |\lambda '|^2)/2}
=  e^{-\pi |\lambda - \lambda'|^2/2}
$$
has Gaussian decay, the Gramian $G$ of a frame of reproducing
kernels $\{\psi _\lambda \}$ is contained in every known matrix
algebra defined by off-diagonal decay. We can therefore use arbitrary
moderate weights of subexponential decay, i.e., for some $C,\alpha >0$
and $0<\beta <1$, we have
\begin{equation}
  \label{eq:c11}
  m(\lambda +\lambda ') \leq C e^{\alpha
  |z|^\beta } m(\lambda ') \qquad \text{ for all }\lambda , \lambda ' \in \bC \, .\end{equation}

In this context a frame multiplier with multiplier sequence $\mu =
(\mu _\lambda )_{\lambda \in \Lambda }$  takes the form 

$$ M_\mu F (z) = \sum \limits_{\lambda \in \Lambda} \mu_\lambda \,
F(\lambda) e^{\pi \bar{\lambda } z} \,  e^{-\pi
  \left|\lambda\right|^2}\, . $$
As in the case of time-frequency multipliers we note that $M_\mu $ can
be read as a Toeplitz operator on Fock space whose symbol is a Radon
measure in place of a nice function.

For this example the abstract lifting theorem
(Theorem~\ref{th:multrecip}) takes the following incarnation. 

\begin{theorem}
  Assume that $\mu $ is moderate as in \eqref{eq:c11} and that
  $\Lambda \subseteq \bC $ is relatively separated such that 
  $D^-(\Lambda )>1$. Then then $M_\mu$ is an isomorphism from
  $\cF^p_{m \sqrt{\mu }}$ to $\cF^p_{\frac{m}{\sqrt{\mu}}}$.
\end{theorem}

This result seems to be new in
complex analysis. For multivariate versions one must assume that the
reproducing kernels $\{ \psi _\lambda \}$ form a frame, but there is
no characterization via the density. 




