\section{Proofs}\label{AppendixProofs}
\begin{lemma}\label{LemmaUniqueMinInformSecondStage}
Let $A:\mathbb{R}\rightarrow[0,0.5]$ be a conditional error function which is positive on $[\zf,\infty)$, $\zf>0$, and $\delta=\xi\delrel$ for $\xi\geq 0$ be the a priori assumed or true parameter and $I_1>0$, $\alpha,\beta\in(0,0.5)$. By setting $A$ constant to $\alpha$, the non-adaptive design can be considered. We define the sucess probability at $\delta$ by
\begin{align*}
\Succ_A(\itwomin,I_1)&=\mathbb{P}_{\delta}\left( Z_1\geq\zf,\text{reject~}H_0\right)\\
&=\int\limits_{z_f}^{\infty}\left\{1-\Phi\left(\Phi^{-1}(1-A(z_1))-\eta_f{\sqrt{I_2^{A}(z_1)}}/{\sqrt{I_{\delta}}}\right)\right\}\phi(z_1-\sqrt{I_1}\delta)\mathrm{d}z_1
\end{align*}
where 
\begin{align*}I_2^{A}(z_1):=\max\left\{\itwomin,I_1{\left\{\Phi^{-1}(1-\beta)+\Phi^{-1}(1-A(z_1))\right\}^2}/{\zf^2}\right\},~z_1\geq\zf~.
\end{align*}
Let $p>0$ such that $p<\mathbb{P}_{\delta}(Z_1\geq z_f)$, $Z_1=\sqrt{I_1}\estone\sim\mathcal{N}(\delta\sqrt{I_1},1)$. If $\Succ_A(0,I_1)\leq p$, we find a unique $\itwomin\geq 0$ such that $\Succ_A(\itwomin,I_1)=p$.
\end{lemma} 
\begin{proof}
It holds for all $z_1\geq\zf$ that $\sqrt{I_2^{A}(z_1)}\nearrow\infty$ if $\itwomin\nearrow\infty$. Thus, for $\itwomin\nearrow\infty$,
\begin{align*}
    z_1\mapsto 1-\Phi\left(\Phi^{-1}(1-A(z_1))-\eta_f{\sqrt{I_2^{A}(z_1)}}/{\sqrt{I_{\delta}}}\right)
\end{align*}
gives a pointwise non-decreasing sequence of functions which converge pointwise to the constant function $z_1\mapsto 1$. Then, due to the monotone convergence theorem, $\Succ_A(\itwomin,I_1)\nearrow 1\cdot\mathbb{P}_{\delta}(Z_1\geq z_f)>p$ which implies for sufficiently large $\itwomin$ it holds $\Succ_A(\itwomin,I_1)> p$. It remains to show that there exists a unique minimal information such that equality holds. On the one hand, $\Succ_A(\itwomin,I_1)$ strictly increases in $\itwomin$. This follows from the fact that the used sample size formula for z-tests is monotonically decreasing in $z_1$ and converges to zero as $z_1$ approaches infinity. Indeed, this yields if $\itwomin$ increases, $I_2^{A}$ increases strictly on some non-empty interval $(z_i,\infty)$, $z_i\geq \zf$ and thus $\Succ_A(\itwomin,I_1)$ strictly increases. Furthermore, the dominated convergence theorem gives the continuity of $\Succ_A(\itwomin, I_1)$ in $\itwomin$. By putting al that together, we obtain: If $\Succ_A(0,I_1)\leq p$, we find a unique $\itwomin\geq 0$ such that $\Succ_A(\itwomin,I_1)=p$.
\end{proof}
In the main article, we use the previous lemma twice. In the first part of the paper, we consider all $\delta$ and $I_1$ which fulfil $\mathbb{P}_{\delta}(Z_1\geq\zf)>1-\beta$ and thus the lemma can be used for $p:=1-\beta$. In the second part of the paper we use that $\mathbb{P}_{\delta}(\text{reject~}H_0~|~Z_1\geq \zf)=1-\beta$ is equivalent to $\mathbb{P}_{\delta}(\text{reject~}H_0,Z_1\geq\zf)=(1-\beta)\cdot\mathbb{P}_{\delta}(Z_1\geq\zf)$ and set $p:=(1-\beta)\cdot\mathbb{P}_{\delta}(Z_1\geq\zf)$.
\begin{lemma}\label{LemmaMaximumInform}
Let $A:\mathbb{R}\rightarrow(0,0.5]$ be a conditional error function and $\delta=\xi\delrel$ for $\xi>\xi_{\min}=1.43$ be the a priori assumed effect and $I_1>\ionemin$, $\alpha,\beta\in(0,0.5)$. For the adaptive design with conditional error function $A$ and the non-adaptive design, the overall power at $\delta$ is achieved by choosing the required $\itwomin$. To distinguish between the two designs, we use the notations $\itwomin^{A}$ and $\itwomin^{\alpha}$. Furthermore, let $\zf>0$ and the fast-track procedure is terminated if $Z_1<\zf$ is observed after the first stage (binding futility stop). If $A(\zf)>\alpha$, the adaptive design has a lower maximum information of the second stage, i.e.
\begin{align}
\max\nolimits_{z_1\geq z_f}I_2^{A}(z_1) < \max\nolimits_{z_1\geq z_f}I_2^{\alpha}(z_1)  \label{ToShowMaximumInformComp}
\end{align}
and thus a lower maximum sum of information over both stages than the non-adaptive design. 
\end{lemma}
\begin{proof}
It holds 
\begin{align}
        \max_{z_1\geq z_f}I_2^{A}(z_1,\itwomin^{A},I_1)=\max\left\{\itwomin^{A},I_1{\left\{\Phi^{-1}(1-\beta)+\Phi^{-1}(1-A(\zf))\right\}^2}/{\zf^2}\right\}~.\label{TermMaxInformation}
\end{align}
The same holds for the non-adaptive design when replacing $A$ with $\alpha$. The proof is straightforward: If $A(z_f)>\alpha$, then
\begin{align}
    I_1{\left\{\Phi^{-1}(1-\beta)+\Phi^{-1}(1-A(z_f))\right\}^2}/{\zf^2}<I_1{\left\{\Phi^{-1}(1-\beta)+\Phi^{-1}(1-\alpha)\right\}^2}/{\zf^2}\label{FallzahlFormelAdaptKleiner}
\end{align}
holds true. We now must only exclude that
 \begin{align}
        \itwomin^{A}\geq\max\nolimits_{z_1\geq z_f}I_2^{\alpha}(z_1)=\max\left\{\itwomin^{\alpha},{I_1\left\{\Phi^{-1}(1-\beta)+\Phi^{-1}(1-\alpha)\right\}^2}/{\zf^2}\right\}~.\label{WidSpruchCond1} 
\end{align}
If $\itwomin^{A}=0$, (\ref{WidSpruchCond1}) cannot be true because the second part of the maximum in (\ref{WidSpruchCond1}) is greater than $0$ due to our assumptions. Then, (\ref{ToShowMaximumInformComp}) is proven. If $\itwomin^{A}>0$ the overall power at $\delta$ is exactly $1-\beta$, i.e. $\Succ_{A}(\itwomin^{A},I_1)=1-\beta$. If (\ref{WidSpruchCond1}) were true, it would imply because (\ref{FallzahlFormelAdaptKleiner}) that for all $z_1\geq\zf$ it holds $I_2^{A}(z_1)=\itwomin^{A}$. Due to $A(z_f)>\alpha$ and due to the monotonicity of $A$ on $[z_f,\infty)$ which implies $A(z_1)\geq A(\zf)>\alpha$ it holds $\Phi^{-1}(1-A(z_1))<\Phi^{-1}(1-\alpha)$. Together with the fact that we have assumed (\ref{WidSpruchCond1}) and $I_{2}^{\alpha}(z_1)$ is decreasing in $z_1$, it can be concluded that the integrated of $\Succ_A(\itwomin^{A},I_1)$ in (\ref{allgemeineConditionOverallPowerAdaptivD}) is strictly greater than the integrand of $\Succ(\itwomin^{\alpha},I_1)$ in (\ref{IntegralOverallPowerSharperBorder}). Therefore, $\Succ_{A}(\itwomin^{A},I_1)>\Succ(\itwomin^{\alpha},I_1)$. Because $\Succ_A(\itwomin^{A},I_1)=1-\beta$ and $\Succ(\itwomin^{\alpha},I_1)\geq 1-\beta$, we have a contradiction. Thus, (\ref{WidSpruchCond1}) does not hold true, and (\ref{ToShowMaximumInformComp}) is fulfilled. 
\end{proof}
The following example refers to Lemma \ref{LemmaMaximumInform}.
\begin{example}\label{FormalExampleMaimumInformation}
Let $\ac=0.15$, $\alpha=0.025$, $\beta=0.2$ like in the main article. For the inverse normal method it holds for all $\xi>\xi_{\min}$ and all $I_1>\ionemin$ (notice that $z_f$ depends on $I_1$) that $A_{I,z_f}(z_f)\geq A_{I,-\infty}(z_{f,\min})$ where $z_{f,\min}:=\max\{\sqrt{t_{\xi}(\ionemin)}\eta_f/\xi,\Phi^{-1}(1-\ac)\}$ (analogously for $A_{F,z_f}$). It can be calculated that  $c_I(-\infty)=0.0253$, $c_F(-\infty)=0.0044$ and it holds $A_{I,-\infty}(z)>\alpha$ iff $z >0.8041$ and $A_{F,-\infty}(z)>\alpha$ iff $z>0.9382$. For $\xi=1.75$ and $\xi=2$ we have $z_{f,\min}=1.1222$ and $z_{f,\min}= 1.0364$, respectively. This means for both considered $\xi$ for both adaptive designs for all $I_1>\ionemin$ definitely holds $A_{I,\zf}(\zf)>\alpha$ and $A_{F,\zf}(\zf)>\alpha$. Therefore, due to Lemma \ref{LemmaMaximumInform}, both adaptive designs have a lower maximum sum of information than the non-adaptive design. 
\end{example}

\section{Numerical Implementation}
The images were created using the \textsf{R}-software. For the calculations, numerical methods like bisection search and the \texttt{integrate} function from the package \texttt{stats} were used. The \textsf{R}-code can be downloaded from the following link: \url{https://github.com/LianeKluge/Adaptive-Designs-in-Fast-Track-Registration-Processes}.

The following result is required for the numerical calculations in Section \ref{subsectionInvestigationI_2const}.
\begin{lemma}\label{LemmaUesSlepiansLemma}
Let $Z(I_2):=Z(I_1,I_2):=\sqrt{{I_1}/{(I_1+I_2)}} Z_1 +\sqrt{{I_2}/{(I_1+I_2)}} Z_2$ where $Z_k=\hat{\vartheta}_k\sqrt{I_k}\sim\mathcal{N}(\delta\sqrt{I_k},1)$, $k=1,2$, and $\xi\geq 1$, i.e. $\delta\geq\delrel>0$. For $\zf\in\mathbb{R}$ the conditional success probability $\mathbb{P}_{\delta}(Z(I_2)\geq z_{\alpha}|Z_1<\zf)$ where $z_{\alpha}=\Phi^{-1}(1-\alpha)$ is increasing in $I_2$.
\end{lemma}
\begin{proof}
Let $I_{2,1}<I_{2,2}$. We prove $\mathbb{P}_{\delta}(Z_1<\zf,Z(I_{2,1})\geq z_{\alpha})<\mathbb{P}_{\delta}(Z_1<\zf,Z(I_{2,2})\geq z_{\alpha})$ by using Slepian's inequality (see, for instance, \cite[Theorem 5.1.7.]{tong2012multivariate}). Slepian's inequality compares the strength of the dependence of two multivariate normally distributed random vectors with the same mean and the same variance and further assumptions on the covariances. We define $X_1:=Y_1:=Z_1-\delta\sqrt{I_1}$ and $X_2:=-Z(I_{2,1})+\delta\sqrt{I_1+I_{2,1}}$,  $Y_2:=-Z(I_{2,2})+\delta\sqrt{I_1+I_{2,2}}$. Then $X=(X_1,X_2)$ and $Y=(Y_1,Y_2)$ are centered random vectors and all variances equal $1$. Furthermore, $\mathrm{Cov}(X_1,X_2)=-\mathrm{Cov}(Z_1,Z(I_{2,1}))=-\sqrt{I_1/{(I_1+I_{2,1})}}\leq-\sqrt{I_1/{(I_1+I_{2,2})}}=-\mathrm{Cov}(Z_1,Z(I_{2,2}))=\mathrm{Cov}(Y_1,Y_2)$. Slepian's inequality now gives for all $a_1,a_2\in\mathbb{R}$ that $\mathbb{P}_{\delta}(X_1< a_1, X_2\leq a_2)\leq\mathbb{P}_{\delta}(Y_1< a_1, Y_2\leq a_2)$. By setting $a_1=\zf-\delta\sqrt{I_1}$ and $a_2=-z_{\alpha}+\delta\sqrt{I_1+I_{2,1}}$ and using $\delta> 0$ which implies $a_2<-z_{\alpha}+\delta\sqrt{I_1+I_{2,2}}$, we obtain
\begin{align*}
    \mathbb{P}_{\delta}(Z_1<\zf,Z(I_{2,1})\geq z_{\alpha})&=\mathbb{P}_{\delta}(X_1< a_1, X_2\leq a_2)\leq\mathbb{P}_{\delta}(Y_1< a_1, Y_2\leq a_2)\\
    &<\mathbb{P}_{\delta}(Y_1<a_1,Y_2\leq-z_{\alpha}+\delta\sqrt{I_1+I_{2,2}})=\mathbb{P}_{\delta}(Z_1<\zf,Z(I_{2,2})\geq z_{\alpha})~.
\end{align*}
This directly implies the monotonicity of the conditional success probability in $I_2$.
\end{proof}
