In fact, even in the noise-free setting, the MSLE estimator can be used to reduce the variance of the all-observation LE estimator. Theorem~\ref{thm:MSLE-clt-noisefree} provides the explicit form of the asymptotic variance of the MSLE estimator, so that the weights $w_p$ can be chosen to minimize the variance of the estimator.

\section{Main results}\label{sec:results}
\subsection{Central limit theorems for SALE}
We start by establishing the following theorem for the noise-free version of SALE. Specifically, two scenarios for the scale $H_n$ are considered for the noise-free setting: either it is a fixed positive integer $H$, or it goes to infinity as $n \to \infty$. The first scenario is appropriate for finite-sample analysis and includes the all-observation LE estimator as a special case, while the second is suitable for asymptotic analysis.

\begin{theorem}\label{thm:SALE-clt-noisefree}
The normalized error process of the noise-free SALE estimator converges stably to a limiting process on an extension of the original probability space. Specifically, we have the following two results.
\begin{enumerate}
\item %
Suppose $H_n$ is a given positive integer $H$, $k_n = \lfloor \beta \lfloor n/H \rfloor^b \rfloor$ for some $\beta > 0$ and $b \in (0, 1)$. Let $u_n = \sqrt{k_n \land (k_n H \Delta_n)^{-1}}$. We have
\begin{equation}
u_n \Bigl( [X,\sigma^2]_T^{(H)} - \langle X, \sigma\rangle_T \Bigr)
\convst
\int_0^T \zeta_{1,t} \ud W_{1,t},
\end{equation}
as $n \to \infty$, where $(W_{1, t})_{t\geq 0}$ is a standard Brownian motion process independent of $\filt$, and the predictable process $(\zeta_{1, t})_{t\geq 0}$ satisfies
\begin{equation}\label{eq:avar-SALE-clt-noisefree-1}
\int_0^T \zeta_{1,t}^2 \ud t =
\frac{u_n^2}{k_n} \left(\frac{8}{3} + \frac{4}{3H^2}\right) \int_0^T \sigma_s^6 \ud t + 
u_n^2 k_n H \Delta_n \frac{2}{3} \int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t.
\end{equation}

\item %
Suppose $H_n = \lfloor \alpha n^a \rfloor$, $k_n = \lfloor \beta \lfloor n/H_n \rfloor^b \rfloor$ for some $\alpha, \beta > 0$ and $a, b \in (0, 1)$. We have
\begin{equation}
n^{\frac{1}{2}(1-a)(b\land (1-b))} \Bigl([X, \sigma^2]^{(H_n)}_T - \langle X, \sigma^2 \rangle_T \Bigr)
\convst
\int_0^T \zeta_{1, t} \ud W_{1, t},
\end{equation}
as $n \to \infty$, where $(W_{1, t})_{t\geq 0}$ is a standard Brownian motion process independent of $\filt$, and the predictable process $(\zeta_{1, t})_{t\geq 0}$ satisfies
\begin{equation}\label{eq:avar-SALE-clt-noisefree-2}
\int_{0}^{T} \zeta_{1, t}^{2} \ud t
=
\frac{8 \alpha^b}{3 \beta} \int_0^T \sigma_t^6 \ud t
\cdot 1_{(0, 1/2]}(b)
+
\frac{2 \alpha^{1-b} \beta T}{3} \int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t
\cdot 1_{[1/2, 1)}(b).
\end{equation}
\end{enumerate}
\end{theorem}

\begin{remark}
Note that in Theorem~\ref{thm:SALE-clt-noisefree}, if we take $H=1$ in the first scenario, the result is consistent with that of the all-observation estimator, which has the same asymptotic variance as the continuous leverage effect estimator in \cite{aitsahalia2017EstimationContinuousDiscontinuous}.
\end{remark}

\begin{remark}\label{remark:spot-vol-errors}
Similar to existing work on leverage effect estimation such as \cite{wang2014EstimationLeverageEffect}, \cite{aitsahalia2014HighFrequencyFinancialEconometrics}, \cite{aitsahalia2017EstimationContinuousDiscontinuous}, \cite{kalnina2017NonparametricEstimationLeverage} and \cite{yang2023EstimationLeverageEffect}, the convergence rate is determined by the spot volatility estimation, which again consists of two sources of errors. \cite{aitsahalia2017EstimationContinuousDiscontinuous} refers to them as \emph{price variation error} and \emph{volatility variation error}, respectively, corresponding to the first and second terms in Equation~\eqref{eq:avar-SALE-clt-noisefree-1} or Equation~\eqref{eq:avar-SALE-clt-noisefree-2}. Intuitively, increasing $k_n$ leads to a wider spot volatility estimation window and thus a larger sample for that estimation, which reduces the price variation error. However, this also increases the volatility variation error, because the estimated volatility becomes less ``local''. The optimal choice of $k_n$ is a trade-off between these two sources of error. This can be achieved by setting $b=1/2$ in the asymptotic scenario, and by estimating and minimizing the asymptotic variance in the finite-sample scenario.
\end{remark}

Next, we establish the following theorem for the noisy version of SALE. The convergence rate of the SALE estimator is determined by the variances due to discretization and noise. However, when the scale is fixed at a constant $H$, from an asymptotic perspective, the variance due to noise ends up diverging as $n \to \infty$, according to Proposition~\ref{prop:SALE-noise}. For this reason, we only consider the second scenario in Theorem~\ref{thm:SALE-clt-noisefree} for the following result.

\begin{theorem}\label{thm:SALE-clt-noisy}
Suppose $H_n = \lfloor \alpha n^a \rfloor > 2q$ and $k_n = \lfloor \beta \lfloor n/H_n \rfloor^b \rfloor$ for some $\alpha, \beta > 0$ and $a, b \in (0, 1)$. When $4a+2b-2ab > 3$, the normalized error process of the noisy SALE estimator converges stably to a limiting process on an extension of the original probability space. That is,
\begin{equation}
n^{\frac{1}{2}r}
\Bigl(\widehat{[X, \sigma^2]}^{(H_n)}_{T} - \langle X, \sigma^2 \rangle _{T}\Bigr)
\convst
\int_{0}^{T} \zeta_{2, t} \ud W_{2, t},
\end{equation}
as $n \to \infty$, where $r = [(1-a)(b\land (1-b))] \land [4a+2b-2ab-3]$,
$(W_{2, t})_{t\geq 0}$ is a standard Brownian motion process independent of $\filt$, and the predictable process $(\zeta_{2, t})_{t\geq 0}$ satisfies
\begin{equation}
\begin{aligned}
\int_{0}^{T} \zeta_{2, t}^{2} \ud t
&=
\frac{8 \alpha^{b}}{3 \beta} \int_{0}^{T} \sigma_{t}^{6} \ud t
\cdot 1_{\{r\}}\bigl((1-a)b\bigr)
+
\frac{2 \alpha^{1-b} \beta T}{3} \int_{0}^{T} \sigma_{t}^{2} \ud \langle \sigma^{2}, \sigma^{2} \rangle_t
\cdot 1_{\{r\}}\bigl((1-a)(1-b)\bigr)
\\ & \qquad
+ \frac{1}{\alpha^{4-2b} \beta^2 T^3}
\int_{0}^{T} \Phi \ud t
\cdot 1_{\{r\}}(4a+2b-2ab-3),
\end{aligned}
\end{equation}
with $\Phi$ defined in Equation~\eqref{eq:Phi}.
\end{theorem}

Note that Theorem~\ref{thm:SALE-clt-noisefree} and Theorem~\ref{thm:SALE-clt-noisy} are infeasible CLTs because their asymptotic variances cannot be observed directly. To address this, we proceed to develop feasible versions of these theorems. This can be achieved by constructing consistent estimators for the quantities in asymptotic variances in both the noise-free and noisy settings, including $\int_0^T \sigma_t^6 \ud t$, $\int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t$ as well as $\Phi$. For the noise-free case, the following estimators can be established:
\begin{align}
G_n^{(1)}
&=
\frac{1}{15\Delta_{n}^{2}} \sum_{i=0}^{n-1} ( \Delta X_{i} )^{6}
\convp
\int_{0}^{T} \sigma_{t}^{6} \ud t, \label{eq:G1}
\\
G_n^{(2)}
&=
\frac{1}{k_{n}\Delta_{n}} \sum_{i \in I}
( \Delta X_{i} )^{2}
\Biggl(
\frac{3}{2}(\widehat{\sigma}_{(j+1)+}^2-\widehat{\sigma}_{j-}^2)^2
-
\frac{1}{k_{n}^{2} \Delta_{n}^{2}} \sum_{j\in I^{\pm}(i)} ( \Delta X_{j} )^{4}
\Biggr)
\convp
\int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t. \label{eq:G2}
\end{align}
For the noisy case, we estimate process-related terms and noise-related terms in asymptotic variance separately. For the process-related terms, the pre-averaging technique is applied. A sequence of non-overlapping windows of length $A_n$, satisfying $A_n \to \infty$ as well as $A_n \Delta_n \to \infty$ as $n\to\infty$ (for example, $A_n = \lfloor n^{1/2} \rfloor$), is used to pre-average the noisy observations. The resulting pseudo-observations are denoted as $\bar{X}_i = A_n^{-1} \sum_{j=iA_n}^{(i+1)A_n} Y_j$, with $i=0, 1, \dots, \bar{n}$, where $\bar{n} = \lfloor (n+1)/A_n \rfloor - 1$. We also define $\bar{\Delta}_{n} = A_n\Delta_n$ and other notations, such as $\bar{I}$, $\bar{k}_n$ and $\widehat{\bar{\sigma}}^2$, similarly. The following estimators for process-related terms can be established:
\begin{align}
\widehat{G}_n^{(1)}
&=
\frac{9}{40 \bar{\Delta}_n}
\sum_{i=0}^{\bar{n}-1} ( \bar{\Delta} X_{i} )^{6}
\convp
\int_{0}^{T} \sigma_{t}^{6} \ud t, \\
\widehat{G}_n^{(2)}
&=
\frac{27}{8\bar{k}_{n}\bar{\Delta}_{n}} \sum_{i \in \bar{I}}
( \Delta \bar{X}_{i} )^{2}
\Biggl(
\frac{3}{2}(\widehat{\bar{\sigma}}_{(j+1)+}^2-\widehat{\bar{\sigma}}_{j-}^2)^2
-
\frac{1}{\bar{k}_{n}^{2} \bar{\Delta}_{n}^{2}} \sum_{j\in \bar{I}^{\pm}(i)} ( \Delta \bar{X}_{j} )^{4}
\Biggr)
\convp
\int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t.
\end{align}
For the noise-related terms, we need to estimate $\nu_2$, $\nu_4$, $\rho_2(l)$, $\rho_3(l)$ and $\rho_4(l)$ in Equation~\eqref{eq:Phi}. Existing methods have been established to estimate these quantities, such as \cite{jacod2017StatisticalPropertiesMicrostructure} and \cite{li2022ReMeDIMicrostructureNoise}. Here, the Realized moMents of Disjoint Increments (ReMeDI) approach proposed by \cite{li2022ReMeDIMicrostructureNoise} is used to estimate the moments of MMS noise. Applying their method in our setting, it can be derived that, for any fixed integer $l$, suppose that $k_n'>0$ satisfies $k_n' \to \infty$ and $k_n'\Delta_n \to 0$ as $n \to \infty$, we have
\begin{align}
&\frac{1}{n} \sum_{i=k_n'}^{n-m-k_n'} (Y_{i+l} - Y_{i+l+k_n'}) (Y_{i} - Y_{i-k_n'})
\convp
\E[\eps_{i} \eps_{i+l}], \\
&\frac{1}{n} \sum_{i=2k_n'}^{n-m-k_n'} (Y_{i+l} - Y_{i+l+k_n'}) (Y_{i+l} - Y_{i+l-k_n'}) (Y_{i} - Y_{i-2k_n'})
\convp
\E[\eps_{i} \eps_{i+l}^2], \\
&\frac{1}{n} \sum_{i=3k_n'}^{n-m-k_n'} (Y_{i+l} - Y_{i+l+k_n'}) (Y_{i+l} - Y_{i+l-k_n'}) (Y_{i} - Y_{i-2k_n'}) (Y_{i} - Y_{i-3k_n'})
\convp
\E[\eps_{i}^2 \eps_{i+l}^2].
\end{align}
The estimators for the noise moments $\widehat{\nu}_2$, $\widehat{\nu}_4$ and the generalized acfs $\widehat{\rho}_2(l)$, $\widehat{\rho}_3(l)$, $\widehat{\rho}_4(l)$ can be constructed accordingly. Thus, by plugging these estimators into Equation~\eqref{eq:Phi}, the following estimator for $\Phi$ can be derived:
\begin{equation}\label{eq:Phi-hat}
\widehat{\Phi}_n = 8 \widehat{\nu}_2 (\widehat{\nu}_4 - \widehat{\nu}_2^2) \sum_{l=-q}^{q} \widehat{\rho}_2(l)\widehat{\rho}_4(l)
+ 24 \widehat{\nu}_2^3 \sum_{l=-q}^{q} \widehat{\rho}_2^3(l)
+ 8 \widehat{\nu}_2 (\widehat{\nu}_4 - \widehat{\nu}_2^2) \sum_{l=-q}^{q} \widehat{\rho}_3(l)\widehat{\rho}_3(-l)
\convp \Phi.
\end{equation}
Putting all these estimators together, we can establish the following feasible CLT for SALE.

\begin{theorem}\label{thm:SALE-clt-feasible}
\phantom{text}
\begin{enumerate}
\item %
Suppose $H_n$ is a given positive integer $H$, $k_n = \lfloor \beta \lfloor n/H \rfloor^b \rfloor$ for some $\beta > 0$ and $b \in (0, 1)$. Let $u_n = \sqrt{k_n \land (k_n H \Delta_n)^{-1}}$. The feasible CLT for noise-free SALE is
\begin{equation}
\frac{u_n}{\sqrt{V_{1,n}}} \Bigl( [X,\sigma^2]_T^{(H)} - \langle X, \sigma\rangle_T \Bigr) \convst \normal(0, 1),
\end{equation}
as $n\to\infty$, where the standard normal on the right hand side is independent of $\filt$, and
\begin{equation}
V_{1,n} = 
\frac{u_n^2}{k_n} \left(\frac{8}{3} + \frac{4}{3H^2}\right) G_n^{(1)} + 
u_n^2 k_n H \Delta_n \frac{2}{3} G_n^{(2)}.
\end{equation}
\item %
Suppose $H_n = \lfloor \alpha n^a \rfloor$, $k_n = \lfloor \beta \lfloor n/H_n \rfloor^b \rfloor$ for some $\alpha, \beta > 0$ and $a, b \in (0, 1)$. The feasible CLT for noise-free SALE is
\begin{equation}
\frac{n^{\frac{1}{2}(1-a)(b\land (1-b))}}{\sqrt{V_{1,n}}} \Bigl([X, \sigma^2]^{(H_n)}_T - \langle X, \sigma^2 \rangle_T \Bigr) \convst \normal(0, 1),
\end{equation}
as $n\to\infty$, where the standard normal on the right hand side is independent of $\filt$, and
\begin{equation}
V_{1,n} =
\frac{8 \alpha^b}{3 \beta} G_n^{(1)} \cdot 1_{(0, 1/2]}(b)
+
\frac{2 \alpha^{1-b} \beta T}{3} G_n^{(2)} \cdot 1_{[1/2, 1)}(b).
\end{equation}
When $H_n > 2q$ and $4a+2(1-a)b > 3$, the feasible CLT for noisy SALE is
\begin{equation}
\frac{n^{\frac{1}{2}r}}{\sqrt{V_{2,n}}} \Bigl(\widehat{[X, \sigma^2]}^{(H_n)}_T - [X, \sigma^2]^{(H_n)}_T \Bigr) \convst \normal(0, 1),
\end{equation}
as $n\to\infty$, where $r = [(1-a)(b\land (1-b))] \land [4a+2(1-a)b-3]$, the standard normal on the right hand side is independent of $\filt$ and $(B_t^{(H_n)})_{t\geq 0}$, and
\begin{equation}
\begin{aligned}
V_{2,n} &=
\frac{8 \alpha^{b}}{3 \beta} \widehat{G}_n^{(1)} \cdot 1_{\{r\}}\bigl((1-a)b\bigr)
+
\frac{2 \alpha^{1-b} \beta T}{3} \widehat{G}_n^{(2)} \cdot 1_{\{r\}}\bigl((1-a)(1-b)\bigr)
\\ & \qquad
+ \frac{1}{\alpha^{4-2b} \beta^2 T^3} \int_0^T \widehat{\Phi}_n \ud t \cdot 1_{\{r\}}(4a+2b-2ab-3).
\end{aligned}
\end{equation}
\end{enumerate}
\end{theorem}

\subsection{Central limit theorems for MSLE}

In this section, we consider MSLE, the weighted average of SALEs at different scales. For a general set of scales $1 \leq H_1 < \dotsc < H_{M_n} \leq n^a$ for some $a\in(0,1)$, $M_n>0$. For now, we do not expose any explicit asymptotic assumptions on $M_n$ and $\{H_p\}_{p=1}^{M_n}$. The MSLE estimators, defined as
\begin{equation}
[X, \sigma^2]^{\rm (MS)}_T = \sum_{p=1}^{M_n} w_{p} [X, \sigma^2]^{(H_p)}_T
\quad \text{and} \quad
\widehat{[X, \sigma^2]}^{\rm (MS)}_T = \sum_{p=1}^{M_n} w_{p} \widehat{[X, \sigma^2]}^{(H_p)}_T,
\end{equation}
are specified by a weight vector $\bm w=(w_1, \dotsc, w_{M_n})$ satisfying $\bm w^T \bm 1_{M_n} = 1$ and $\|\bm w\|_\infty$ bounded. The asymptotic variance of MSLE is determined by the asymptotic covariance between SALE estimators at different scales, as the following proposition establishes.

\begin{proposition}\label{prop:SALE-acov-noisefree}
Suppose $k_p = \lfloor \beta \lfloor n / H_p \rfloor^b \rfloor$ holds for all $p \in \{1, \dotsc, M_n\}$, with some constant $\beta > 0$ and $b \in (0, 1)$. For any $1 \leq q \leq p \leq M_n$, the asymptotic covariance between the noise-free version of SALE estimators of scales $H_q$ and $H_p$ is given by
\begin{equation}\label{eq:SALE-acov-disc}
\mathrm{ACOV}_{p,q}^{\mathrm{(disc)}} =
\frac{1}{k_p} \cdot 4 v_{p,q}^{(1)} \frac{H_q}{H_p}
\cdot \int_0^T \sigma_t^6 \ud t
+
k_pH_p\Delta_n \cdot \frac{2}{3} v_{p,q}^{(2)} \left(\frac{k_qH_q}{k_pH_p}\right)^2
\cdot \int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t,
\end{equation}
such that for $u_n = \sqrt{k_p \land (k_p H_p \Delta_n)^{-1}}$, we have
\begin{equation}
u_n \begin{pmatrix}
[X, \sigma^2]^{(H_p)}_T - \langle X, \sigma^2 \rangle_T \\
[X, \sigma^2]^{(H_q)}_T - \langle X, \sigma^2 \rangle_T
\end{pmatrix}
\convd
\normal\left(0,
u_n^2 \begin{bmatrix}
\mathrm{ACOV}_{p,p}^{\mathrm{(disc)}} & \mathrm{ACOV}_{p,q}^{\mathrm{(disc)}} \\
\mathrm{ACOV}_{p,q}^{\mathrm{(disc)}} & \mathrm{ACOV}_{q,q}^{\mathrm{(disc)}}
\end{bmatrix}\right),
\end{equation}
as $n\to \infty$. Here, $v_{p,q}^{(1)}, v_{p,q}^{(2)} \in [0, 1)$ are adjustment factors depending on $p, q, n$, and are defined in Definition~\ref{def:adjustment-factors} in Appendix~\ref{app:MSLE-clt}.
\end{proposition}

\begin{remark}
The non-negative adjustment factors $v_{p,q}^{(1)}$ and $v_{p,q}^{(2)}$ are determined by the grid structures of scales $H_p$ and $H_q$, and correspond to the price variation error and volatility variation error in the spot volatility estimation (Remark~\ref{remark:spot-vol-errors}), respectively. These factors can be interpreted as follows. When the $(\Delta X)$ terms in increments of $H_p$-scaled and $H_q$-scaled SALEs overlap, as defined in Equation~\eqref{eq:SALE-increments}, their cross product contributes a term to the asymptotic covariance. This contribution depends on the overlapping region of their spot volatility estimation windows. Specifically, the price variation error is proportional to the sum of the squares of small segments within the overlapping region. These segments are defined by the grid points of $H_p$ and $H_q$. In contrast, the volatility variation error is proportional to the cubed length of the entire overlapping region. The adjustment factors $v_{p,q}^{(1)}$ and $v_{p,q}^{(2)}$ can thus be thought of as the normalized averages of these respective quantities.
\end{remark}

Although the precise values of adjustment factors $v_{p,q}^{(1)}$ and $v_{p,q}^{(2)}$ can be calculated based on their definitions provided in Definition~\ref{def:adjustment-factors} in Appendix~\ref{app:MSLE-clt}, the following proposition establishes the asymptotic behavior of the $v_{p,q}^{(1)}$ and $v_{p,q}^{(2)}$.

\begin{proposition}\label{prop:adj-factor-asym}
Under the condition of Proposition~\ref{prop:SALE-acov-noisefree}, the asymptotic behavior of $v_{p,q}^{(1)}$ and $v_{p,q}^{(2)}$ is as follows. Specifically, we assume that there are two sequences of scales $H_p$ and $H_q$ indexed by $n$, such that $H_p \geq H_q$ for all $n$, and $H_p, H_q \to \infty$, $H_{q} / H_{p} \to c$ for some constant $c \in (0, 1]$ as $n \to \infty$. We have
\begin{equation}
v_{p,q}^{(1)} \to 1 - \frac{c}{3}
\quad \text{and} \quad
v_{p,q}^{(2)} \to 1,
\quad \text{as } n \to \infty.
\end{equation}
\end{proposition}

\begin{remark}
The asymptotic behavior of the adjustment factors $v_{p,q}^{(1)}$ and $v_{p,q}^{(2)}$ in Proposition~\ref{prop:adj-factor-asym} aligns with the intuition that the asymptotic covariance between SALE estimators at different scales is determined by the overlapping regions of their spot volatility estimation windows. The conditions in Proposition~\ref{prop:adj-factor-asym} guarantee that the spot volatility estimation windows of two scales are of the same order, and their overlapping regions also have the same order. In this case, the adjustment factors turn out to have non-vanishing limits with simple forms.
\end{remark}

\begin{theorem}\label{thm:MSLE-clt-noisefree}
Suppose $1 \leq H_1 < \dotsc < H_{M_n} \leq n^a$ for some $a\in(0,1)$, $k_p = \lfloor \beta \lfloor n/H_p \rfloor^b \rfloor$ holds for all $p \in \{1, \dotsc, M_n\}$ with some $\beta > 0$ and $b \in (0, 1)$, and the weight vector $\bm w=(w_1, \dotsc, w_{M_n})$ satisfies that $\bm w^T \bm 1_{M_n} = 1$ and $\|\bm w\|_\infty$ is bounded. The normalized error process of the noise-free MSLE estimator converges stably to a limiting process on an extension of the original probability space. Specifically, the following two results hold.
\begin{enumerate}
\item %
Without any explicit assumptions on $M_n$ and $\{H_p\}_{p=1}^{M_n}$, we have
\begin{equation}\label{eq:avar-MSLE-clt-noisefree-1}
\frac{[X,\sigma^2]_T^{\rm (MS)} - \langle X, \sigma^2 \rangle_T}
{\sqrt{\sum_{p=1}^{M_n} \sum_{q=1}^{M_n} w_{p} w_{q} \mathrm{ACOV}_{p,q}^{\mathrm{(disc)}}}}
\convst
\normal(0, 1),
\end{equation}
as $n\to\infty$, where $\mathrm{ACOV}_{p,q}^{\mathrm{(disc)}}$ is defined in Equation~\eqref{eq:SALE-acov-disc}, and the standard normal on the right hand side is independent of $\filt$.
\item %
Suppose $H_p = m_n+p$ for all $p \in \{1, \dotsc, M_n\}$. Denote $H_n^*=H_{M_n}=m_n+M_n$, and suppose that $H_n^* / n^a \to \alpha$, $m_n / H_n^* \to c$ for some constant $\alpha > 0$, $a\in(0,1)$, $c\in(0, 1)$ as $n \to \infty$. Moreover, suppose there exists a continuous bounded function $\phi: [c, \infty) \to \R$, such that $\int_c^1 \phi(x) \ud x = 1$, and $w_p = \frac{1-c}{M_n}\phi(c+\frac{p}{H_n^*})$. We have
\begin{equation}
n^{\frac{1}{2}(1-a)(b\land (1-b))} \Bigl([X, \sigma^2]^{\rm (MS)}_T - \langle X, \sigma^2 \rangle_T \Bigr)
\convst
\int_0^T \zeta_{4, t} \ud W_{4, t},
\end{equation}
as $n \to \infty$, where $(W_{4,t})_{t\geq 0}$ is a standard Brownian motion independent of $\filt$, and the predictable process $(\zeta_{4, t})_{t\geq 0}$ satisfies
\begin{equation}\label{eq:avar-MSLE-clt-noisefree-2}
\begin{aligned}
\int_0^T \zeta_{4, t}^{2} \ud t
&=
\frac{8\alpha^b}{\beta} \int_c^1 \int_c^x \phi(x) \phi(y) x^b \left(\frac{y}{x} - \frac{y^2}{3x^2}\right) \ud y \ud x \cdot \int_0^T \sigma_t^6 \ud t \cdot 1_{(0, 1/2]}(b)
\\ & \quad
+ \frac{4\alpha^{1-b}\beta T}{3} \int_c^1 \int_c^x \phi(x) \phi(y) \frac{y^{2(1-b)}}{x^{1-b}} \ud y \ud x \cdot \int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t \cdot 1_{[1/2, 1)}(b).
\end{aligned}
\end{equation}
\end{enumerate}
The feasible version of this theorem can be established with $G_n^{(1)}$ and $G_n^{(2)}$ defined in Equation~\eqref{eq:G1} and Equation~\eqref{eq:G2}.
\end{theorem}

\begin{remark}
Note that in Theorem~\ref{thm:MSLE-clt-noisefree}, the first scenario is a general result without any explicit assumptions on $M_n$ and $\{H_p\}_{p=1}^{M_n}$, while the second scenario is under a specific choice of consecutive scales in $(m_n, m_n+M_n]$, with $m_n \approx c\alpha n^a \gg 1$ as $n \to \infty$. The latter is mainly based on theoretical considerations. This assumption avoids the case in Proposition~\ref{prop:adj-factor-asym} where the asymptotic covariance between widely separated scales may vanish. In such cases, Equation~\eqref{eq:avar-MSLE-clt-noisefree-2} may be inaccurate, particularly for weight functions $\phi(x)$ that concentrate too much density near 0 and 1. However, if the observations are not contaminated by noise, one should start from the scale $H_1=1$ and put more weight on the smaller scales to construct a better estimator, as the convergence rates of these scales are much faster than the larger scales.
\end{remark}

\begin{theorem}\label{thm:MSLE-clt-noisy}
Under the second scenario of Theorem~\ref{thm:MSLE-clt-noisefree}, if the noise is independent, and $5a+2b-2ab > 3$, the normalized error process of the noisy MSLE estimator converges stably to a limiting process on an extension of the original probability space. Specifically,
\begin{equation}
n^{\frac{1}{2}r} \Bigl(\widehat{[X, \sigma^2]}^{\rm (MS)}_T - [X, \sigma^2]^{\rm (MS)}_T \Bigr) \convst \int_0^T \zeta_{5, t} \ud W_{5, t},
\end{equation}
as $n \to \infty$, where $r = [(1-a)(b\land (1-b))] \land [5a+2b-2ab-3]$, $(W_{5,t})_{t\geq 0}$ is a standard Brownian motion independent of $\filt$ and $(\zeta_{5, t})_{t\geq 0}$ satisfies
\begin{equation}\label{eq:avar-MSLE-clt-noisy-2}
\begin{aligned}
\int_0^T \zeta_{5, t}^{2} \ud t
&=
\frac{8\alpha^b}{\beta} \int_c^1 \int_c^x \phi(x) \phi(y) x^b \left(\frac{y}{x} - \frac{y^2}{3x^2}\right) \ud y \ud x \cdot \int_0^T \sigma_t^6 \ud t \cdot 1_{\{r\}}\bigl((1-a)b\bigr)
\\ & \quad
+ \frac{4\alpha^{1-b}\beta T}{3} \int_c^1 \int_c^x \phi(x) \phi(y) \frac{y^{2(1-b)}}{x^{1-b}} \ud y \ud x \cdot \int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t \cdot 1_{\{r\}}\bigl((1-a)(1-b)\bigr)
\\ & \quad
+ \frac{1}{\alpha^{5-2b}\beta^2 T^3} \int_c^1 \phi^2(x) x^{-(4-2b)} \ud x \cdot \int_0^T F_1 \ud t \cdot 1_{\{r\}}(5a+2b-2ab-3)
\\ & \quad
+ \frac{1_{(0, 1/2]}(c)}{2^{2-b}\alpha^{5-2b}\beta^2 T^3} \int_c^{1/2} \phi(x) \phi(2x) x^{-(4-2b)} \ud x \cdot \int_0^T F_2 \ud t \cdot 1_{\{r\}}(5a+2b-2ab-3),
\end{aligned}
\end{equation}
where $F_1 = 8\nu_2\nu_4 + 16\nu_2^3 + 8\nu_3^2$ and $F_2 = 2\nu_2(\nu_4-\nu_2^2)$. The feasible version of this theorem can be established with $\widehat{G}_n^{(1)}$ and $\widehat{G}_n^{(2)}$ defined in Equation~\eqref{eq:G1} and Equation~\eqref{eq:G2}, as well as $\widehat{F}_1$ and $\widehat{F}_2$ constructed similarly as Equation~\eqref{eq:Phi-hat}.
\end{theorem}

\begin{remark}
Although only the second scenario of Theorem~\ref{thm:MSLE-clt-noisefree} is considered in Theorem~\ref{thm:MSLE-clt-noisy}, the CLT for the first scenario can be established similarly. The asymptotic covariance due to noise, denoted by $\mathrm{ACOV}_{p,q}^{\mathrm{(noise)}} = \cov(\widehat{[X,\sigma^2]}_T^{(H_p)}, \widehat{[X,\sigma^2]}_T^{(H_q)} | \filt)$, allows us to establish that
\begin{equation}\label{eq:avar-MSLE-clt-noisy-1}
\frac{\widehat{[X, \sigma^2]}^{\rm (MS)}_T - [X, \sigma^2]^{\rm (MS)}_T}{\sqrt{\sum_{p=1}^{M_n} \sum_{q=1}^{M_n} w_{p} w_{q} (\mathrm{ACOV}_{p,q}^{\mathrm{(disc)}}+\mathrm{ACOV}_{p,q}^{\mathrm{(noise)}})}}
\convst \normal(0, 1),
\end{equation}
where the standard normal on the right hand side is independent of $\filt$. The reason we do not include the first scenario in Theorem~\ref{thm:MSLE-clt-noisy} is that the closed-form expression for $\mathrm{ACOV}_{p,q}^{\mathrm{(noise)}}$ is not provided in this paper when the noise is dependent. As an alternative solution, the variance due to noise can be calculated with the algorithm described in Appendix~\ref{app:MSLE-noise}, as is mentioned in Section~\ref{sec:MSLE}.
\end{remark}

\section{Variance reduction}\label{sec:variance-reduction}
In this section, we consider the important problem of variance reduction for the MSLE estimator. This includes the variance reduction in both noise-free setting and noisy setting. For a given set of scales $1 \leq H_1 < \dotsb < H_{M_n} \ll n$, one can always calculate the optimal weights $\bm{w}^*$ that minimize the asymptotic variance in Equation~\eqref{eq:avar-MSLE-clt-noisefree-1} or Equation~\eqref{eq:avar-MSLE-clt-noisy-1}. Let $\bm{\Sigma} \in \R^{M_n \times M_n}$ denote the total asymptotic covariance matrix between scales, where $\Sigma_{p,q} = \mathrm{ACOV}_{p,q}^{\mathrm{(disc)}} + \mathrm{ACOV}_{p,q}^{\mathrm{(noise)}}$. The optimal weights can be calculated by solving the following optimization problem:
\begin{equation}\label{eq:weight-optimization}
\begin{aligned}
\underset{\bm{w} \in \R^{M_n}}{\text{minimize}} & \quad V(\bm{w}) = \bm{w}^T \bm{\Sigma} \bm{w}, \\
\text{subject to} & \quad \bm{w}^T \bm{1}_{M_n} = 1.
\end{aligned}
\end{equation}
The solution is given by
\begin{equation}\label{eq:weight-optimization-solution}
\bm{w}^* = \frac{1}{\bm{1}_{M_n}^T \bm{\Sigma}^{-1} \bm{1}_{M_n}} \bm{\Sigma}^{-1} \bm{1}_{M_n},
\quad \text{with} \quad
V(\bm{w}^*) = \frac{1}{\bm{1}_{M_n}^T \bm{\Sigma}^{-1} \bm{1}_{M_n}}
= \Biggl(\sum_{p=1}^{M_n}\sum_{q=1}^{M_n} (\bm{\Sigma}^{-1})_{p,q}\Biggr)^{-1}.
\end{equation}
Since the asymptotic covariance matrix $\bm{\Sigma}$ cannot be observed directly, its estimate, $\widehat{\bm{\Sigma}}$, through consistent estimators of quantities, such as $\int_0^T \sigma_t^6 \ud t$, $\int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t$ and $\Phi$, can be used. However, from an asymptotic point of view, the inversion operation of $\bm{\Sigma}$ can be numerically expensive, especially when the number of scales $M_n$ is large, because matrix inversion has a time complexity of $O(M_n^3)$. Moreover, the accurate solution $\bm{w}^*$ can be numerically unstable, exhibiting, for example, zigzagging weights and sensitivity to estimation errors $\widehat{\bm{\Sigma}}$. These issues motivate the development of computationally efficient and numerically stable variance reduction methods.

Therefore, we develop the approximation methods for variance reduction under different settings when $M_n$ is large. We consider a specific set of consecutive scales $H_p = m_n+p$ for all $p \in \{1, \dotsc, M_n\}$, where $H_n^*=m_n+M_n$. We also assume $b=1/2$, so that a medium-sized spot volatility estimation window is adopted in the asymptotic sense. In the noise-free case, the special structure of $\bm{\Sigma}$ allows us to derive a closed-form expression for the optimal weights. In the noisy case, we utilized the Fredholm integral equation of the second kind to approximate the optimal weights.

\subsection{Approximation under noise-free setting}\label{sec:variance-reduction-noisefree}
Under the noise-free setting, the covariance matrix between scales is simply given by $\Sigma_{p,q} = \mathrm{ACOV}_{p,q}^{\mathrm{(disc)}}$. In order to minimize the variance of MSLE, the best choice of scales might be a set of scales that starts from $H_1 = 1$, because the all-observation estimator (which is SALE with $H=1$) has the minimal asymptotic variance. To ensure mathematical tractability, we begin with the first scenario of Proposition~\ref{prop:adj-factor-asym}, so that $v_{p,q}^{(1)} \to 1 - \frac{H_q}{3H_p}$ and $v_{p,q}^{(2)} \to 1$ as $n \to \infty$. In this case, denoting $x_p = H_p / H_n^*$, the asymptotic version of covariance matrix can be written as
\begin{equation}\label{eq:Sigma-disc}
\Sigma_{p,q} = (s_1 + s_2)
(n/H_n^*)^{-1/2} (x_p \lor x_q)^{1/2}
\left[\frac{x_p \land x_q}{x_p \lor x_q} - \frac{s_1}{3(s_1 + s_2)} \left(\frac{x_p \land x_q}{x_p \lor x_q}\right)^2\right],
\end{equation}
where the positive constants $s_1$ and $s_2$ are defined as
\begin{equation}
s_1 = \frac{4}{\beta} \int_0^T \sigma_t^6 \ud t, \quad
s_2 = \frac{2\beta T}{3} \int_0^T \sigma_t^2 \ud \langle \sigma^2, \sigma^2 \rangle_t.
\end{equation}
Although $s_1$ and $s_2$ are process-related stochastic quantities, they are treated as constants in this section for a given sample. The inverse of the matrix $\bm \Sigma$ is approximately a tridiagonal matrix (as can be seen by examining the cofactors), meaning that its elements are approximately zero except for the main diagonal and the two adjacent diagonals. Moreover, we have the following lemma.

\begin{lemma}\label{lem:tridiagonal-inverse}
Let $n > 0$ be an integer, and let $m \in \R$. The matrix $\bm{B} \in \R^{n\times n}$ is defined as
\begin{equation}
\bm{B}_{p,q} = f\bigl((m+p) \lor (m+q)\bigr)
\frac{g\bigl((m+p) \land (m+q)\bigr)}{g\bigl((m+p) \lor (m+q)\bigr)}, \quad
\text{for all } p, q \in \{1, \dotsc, n\},
\end{equation}
where $f, g$ are well-defined functions such that all expressions in this lemma are valid. Define
\begin{equation}
h(p, q) = f(m+p) - \frac{g^2(m+p)}{g^2(m+q)} f(m+q).
\end{equation}
The inverse $\bm{A} = \bm{B}^{-1}$ is tridiagonal. Its superdiagonal and subdiagonal elements are given by
\begin{equation}
\bm{A}_{p,p+1} = \bm{A}_{p+1,p}
=
-\frac{g(m+p)}{g(m+p+1)} \frac{1}{h(p,p+1)},
\quad p = 1, \dotsc, n-1,
\end{equation}
and its main diagonal elements are given by
\begin{align}
A_{1,1} &= \frac{1}{h(1,2)}, \\
A_{p,p} &= \frac{h(p-1, p+1)}{h(p-1, p)h(p, p+1)}, \quad p = 2, \dotsc, n-1, \\
A_{n,n} &= \frac{f(m+n-1)}{f(m+n)}\frac{1}{h(n-1,n)}.
\end{align}
\end{lemma}

Intuitively, since $s_1/(3(s_1+s_2)) \in (0, 1/3)$ and $(x_p \land x_q) / (x_p \lor x_q) \geq (x_p \land x_q)^2 / (x_p \lor x_q)^2$, it is reasonable to expect that the first term in the brackets of Equation~\eqref{eq:Sigma-disc} contributes more significantly than the second term. Therefore, neglecting the second term in the bracket (for now), we obtain
\begin{equation}
\tilde{\bm{\Sigma}}_{p,q} = (s_1 + s_2) (n/H_n^*)^{-1/2} (x_p \lor x_q)^{1/2} \frac{x_p \land x_q}{x_p \lor x_q}
= (s_1 + s_2) n^{-1/2} \bm{B}_{p,q},
\end{equation}
with $\bm{B}_{p,q}$ given in Lemma~\ref{lem:tridiagonal-inverse} with $f(x) = \sqrt{x}$ and $g(x) = x$. With $\bm{\omega} = \bm{B}^{-1} \bm{1}_{M_n}$, the optimal weights obtained by solving Equation~\eqref{eq:weight-optimization} with $\tilde{\bm{\Sigma}}$ are $\bm{w} = (\bm{1}_{M_n}^T \bm{\omega})^{-1} \bm{\omega}$. From Lemma~\ref{lem:tridiagonal-inverse}, it follows that for $p = 2, \dotsc, M_n-1$,
\begin{align}
\omega_1 &= \left(\frac{m_n+2}{m_n+1}\right)^{1/2}
\frac{1}{(m_n+2)^{3/2} - (m_n+1)^{3/2}} \\
\omega_p &= (m_n+p)^{1/2} \left(\frac{(m_n+p)^{1/2}-(m_n+p-1)^{1/2}}{(m_n+p)^{3/2}-(m_n+p-1)^{3/2}} - \frac{(m_n+p+1)^{1/2}-(m_n+p)^{1/2}}{(m_n+p+1)^{3/2}-(m_n+p)^{3/2}}\right), \\
\omega_{M_n} &= (m_n+M_n)^{1/2} \frac{(m_n+M_n)^{1/2}-(m_n+M_n-1)^{1/2}}{(m_n+M_n)^{3/2}-(m_n+M_n-1)^{3/2}}.
\end{align}
As $m_n \to \infty$, these values can be further approximated as
\begin{equation}\label{eq:approx-weight-noisefree}
\omega_1 \to \frac{2}{3(m_n+1)^{1/2}}, \quad
\omega_p \to \frac{1}{3(m_n+p)^{3/2}}, \quad
\omega_{M_n} \to \frac{1}{3(m_n+M_n)^{1/2}}.
\end{equation}
This provides an approximation of the optimal weights in noise-free settings.

