\section{Proofs of propositions on variance due to noise}\label{app:noise}
\subsection{Proof of Proposition~\ref{prop:all-observation-noise}}\label{app:all-observation-noise}
\subsubsection{Notations}
First, we make the following conventions in this section. We first rewrite the noisy all-observation estimator as
\begin{equation}
\widehat{[X, \sigma^{2}]}^{\rm (all)}_T
=
\frac{1}{k_n \Delta_n} \sum_{i \in I} u_i,
\end{equation}
where $u_i$ is the $i$th summand in the estimator, defined as
\begin{equation}
u_i = \left( \Delta Y_i \right)
\left(
\sum_{j\in I^+(i)} \left( \Delta Y_j \right)^2 - \sum_{j\in I^-(i)} \left( \Delta Y_j \right)^2
\right).
\end{equation}
We further decompose $u_i$ as
\begin{equation}
u_i = \left( a_i + A_i \right) \left( b_i + B_i \right),
\end{equation}
by defining
\begin{equation}
\begin{aligned}
\textcolor{blue}{a_i} + \textcolor{red}{A_i} & = (\Delta Y_{i}) =
\textcolor{blue}{(\Delta X_{i})}
+
\textcolor{red}{\langle \theta_{A_i}, \eps \rangle}, \\
\textcolor{blue}{b_i} + \textcolor{red}{B_i} & = \left(
\sum_{j\in I^{+}(i)} (\Delta Y_{j})^{2} - \sum_{j\in I^{-}(i)}(\Delta Y_{j})^{2}
\right) \\
& =
\textcolor{blue}{
\left(
\sum_{j\in I^{+}(i)} (\Delta X_{j})^{2} - \sum_{j\in I^{-}(i)}(\Delta X_{i})^{2}
\right)
}
+ 
\textcolor{red}{
\langle \theta_{B_i}, \eps \rangle
+ \langle \phi_{B_i}, \eps^{2} \rangle
+ \langle \psi_{B_i}, \eps\eps_{+} \rangle
}.
\end{aligned}
\end{equation}
The lowercase letters $a_i$ and $b_i$ represent process-related terms in $u_i$, while the capital letters $A_i$ and $B_i$ represent noise-related terms in $u_i$.

The noise-related terms include three types: $\eps_j$, $\eps_j^2$, and $\eps_j \eps_{j+1}$ for valid $j$ values. For simplicity, we denote the corresponding noise vectors as $\eps$, $\eps^2$, and $\eps\eps_+$. These vectors are defined by
\begin{equation}
(\eps)_{j} = \eps_{j}, \quad (\eps^{2})_{j} = \eps_{j}^{2}, \quad (\eps\eps_{+})_{j} = \eps_{j}\eps_{j+1}I(j \neq n),
\end{equation}
for $j \in \{0, 1, \dotsc, n\}$. The non-zero values of the coefficient vectors $\theta_{A_i}$, $\theta_{B_i}$, $\phi_{B_i}$, and $\psi_{B_i}$ are listed in Table~\ref{tab:coeff-all-observation}. We also adopt the convention that the index of coefficient vectors is written as a superscript, so we have, for instance, $\langle \psi_{B_i}, \eps\eps_+ \rangle = \sum_{j=0}^{n} \psi_{B_i}^{j} \eps_{j}\eps_{j+1}$.

