\subsubsection{Bias due to noise}\label{sec:app-all-observation-noise-bias}
Notice that the noise-free estimator can be written as
\begin{equation}
[X, \sigma^{2}]^{\rm (all)}_T
=
\frac{1}{k_n \Delta_n} \sum_{i \in I} v_i,
\end{equation}
where
\begin{equation}
v_i = \left( \Delta X_i \right)
\left(
\sum_{j\in I^+(i)} \left( \Delta X_j \right)^2 - \sum_{j\in I^-(i)} \left( \Delta X_j \right)^2
\right)
=
a_i b_i.
\end{equation}
We can conclude from Table~\ref{tab:coeff-all-observation} that $A_i \perp B_i | \filt$. We can also conclude that $\E A_i = \E B_i = 0$, because $\E[\eps_j] = \E[\eps_j \eps_{j+1}] = 0$, so that
\begin{equation}
\E \left[\left. \langle \theta_{A_i}, \eps \rangle \right| \filt \right]
=
\E \left[\left. \langle \theta_{B_i}, \eps \rangle \right| \filt \right]
=
\E \left[\left. \langle \psi_{B_i}, \eps\eps_{+} \rangle \right| \filt \right]
= 0;
\end{equation}
and $\sum_{j} \phi_{B_i}^{j} = 0$ so that
\begin{equation}
\E \left[\left. \langle \phi_{B_i}, \eps^{2} \rangle \right| \filt \right] = 0.
\end{equation}
Therefore, each summand of the noisy estimator is unbiased due to noise:
\begin{equation}
\E \left[\left. u_i \right| \filt \right]
=
\E \left[\left. (a_i + A_i) (b_i + B_i) \right| \filt \right]
=
\E \left[\left. a_i b_i \right| \filt \right]
=
v_i,
\end{equation}
so that the unbiasedness of the all-observation estimator follows:
\begin{equation}
\E \left( \left. \widehat{[X, \sigma^{2}]}^{\rm (all)}_T \right| \filt \right) = [X, \sigma^{2}]^{\rm (all)}_T.
\end{equation}

\subsubsection{Variance due to noise}\label{sec:app-all-observation-noise-variance}
Our goal is to derive the variance of the noisy all-observation estimator due to noise, which is given by
\begin{equation}
\begin{aligned}
\var\left(\left. \widehat{[X, \sigma^2]}^{\rm (all)}_T \right| \filt \right)
&=
\E\left(\left. \left(\widehat{[X, \sigma^2]}^{\rm (all)}_T \right)^2 \right| \filt \right)
-
\left[\E\left(\left. \widehat{[X, \sigma^2]}^{\rm (all)}_T \right| \filt \right)\right]^2 \\
&=
\E\left(\left. \left(\widehat{[X, \sigma^2]}^{\rm (all)}_T \right)^2 \right| \filt \right)
-
\left( [X, \sigma^2]^{\rm (all)}_T \right)^2 \\
&=
\frac{1}{k_n^2 \Delta_n^2}
\E\left(\left.
\sum_{k \in I} \sum_{l \in I}
\left( u_k u_l - v_k v_l \right)
\right| \filt \right).
\end{aligned}
\end{equation}
At this stage, we obtain the main decomposition in this proof:
\begin{equation}
\begin{aligned}
&
k_n^2 \Delta_n^2 \var\left(\left. \widehat{[X, \sigma^2]}^{\rm (all)}_T \right| \filt \right) \\
&=
\sum_{k \in I} \sum_{l \in I}
\E\Bigl[
\left( a_k + A_k \right) \left( b_k + B_k \right)
\left( a_l + A_l \right) \left( b_l + B_l \right)
-
a_k b_k a_l b_l
\Big| \filt \Bigr] \\
&=
\sum_{k \in I} \sum_{l \in I}
\E\Bigl[
N_1(k,l) + N_2(k,l) + N_3(k,l) + N_4(k,l)
\Big| \filt \Bigr].
\end{aligned}
\end{equation}
Notice that in the above equation, the pure process-related term $a_k b_k a_l b_l$ vanishes after simplification, while the remaining terms may contain one, two, three, or four noise-related terms. For simplicity, we omit the subscript $k$ in $(a_k, b_k, A_k, B_k)$ and denote $(a_l, b_l, A_l, B_l)$ as $(c, d, C, D)$ when these terms appear inside $\sum_{k,l}$. Thus, we can write
\begin{align}
N_1(k, l) &= \sum_{\rm comb} Abcd = Abcd + aBcd + abCd + abcD, \\
N_2(k, l) &= \sum_{\rm comb} ABcd = ABcd + AbCd + AbcD + aBCd + aBcD + abCD, \\
N_3(k, l) &= \sum_{\rm comb} ABCd = ABCd + ABcD + AbCD + aBCD, \\
N_4(k, l) &= ABCD,
\end{align}
where $\sum_{\rm comb}$ means all possible combinations of the four terms. We further adopt the conventions that, in Section~\ref{sec:app-all-observation-noise-variance}, noise terms in $A, B, C, D$ are indexed by $i, \alpha, j, \beta$ respectively, for example, $A = \langle \theta_{A}, \eps \rangle = \sum_{i=0}^{n} \theta_{A}^{i} \eps_{i}$.

To summarize, the variance due to noise can be calculated by
\begin{equation}\label{all-observation-noise-variance-four-terms}
\var\left(\left. \widehat{[X, \sigma^2]}^{\rm (all)}_T \right| \filt \right)
=
\sum_{m=1}^{4}
\frac{1}{k_n^2 \Delta_n^2}
\sum_{k \in I} \sum_{l \in I}
\E \Bigl(
N_{m}(k, l)
\Big| \filt \Bigr).
\end{equation}
In the following part, we will calculate the summation by looking at the contribution of $m=1, 2, 3, 4$ respectively.

The following lemma, though trivial, will be used in the following calculations.
\begin{lemma}\label{lem:app-noise-prod-expect}
For mean zero, independent and identically distributed random variables $\{X_{i}\}_{i=1}^{l}$, we denote $\nu_{k} = \E[X^{k}]$. It is clear that the expectation of products
\begin{equation}
\E[X_{1}^{k_{1}}X_{2}^{k_{2}}\dotsb X_{l}^{k_{l}}] = \nu_{k_{1}}\nu_{k_{2}}\dotsb \nu_{k_{l}},
\end{equation}
where $k_{i} \geq 1$ for all $i = 1, \dotsc, l$ and the total times of power is $n = \sum_{i=1}^{l} k_{i}$. In order to make sure that the result is non-zero, an additional condition is that
\begin{equation}
k_{i}\geq 2,\quad \forall i = 1, \dotsc, l.
\end{equation}
It also follows that $n \geq 2l$.
\end{lemma}

\paragraph{Contribution of $N_1$}
With the same argument in Section~\ref{sec:app-all-observation-noise-bias}, we can conclude that
\begin{equation}
\E[Abcd | \filt] = bcd\E[A | \filt] = 0.
\end{equation}
Similarly,
\begin{equation}
\E[aBcd | \filt] = \E[abCd | \filt] = \E[abcD | \filt] = 0.
\end{equation}
Therefore, $N_1$ contributes nothing to the variance due to noise.

\paragraph{Contribution of $N_2$}
First, we have the following lemma concerning the noise-related terms in $N_2$.

\begin{lemma}\label{lem:app-all-observation-noise-N2}
For $P, Q \in \{A, B, C, D\}$, $P \neq Q$, we have
\begin{equation}
\begin{aligned}
\E[PQ | \filt] &= \nu_2 \langle\theta_P, \theta_Q\rangle +\nu_4\langle\phi_P, \phi_Q\rangle \\
&\quad +\nu_2^2 \left[-\langle\phi_P, \phi_Q\rangle+\langle\psi_P, \psi_Q\rangle\right] + \nu_3 \left[\langle\theta_P, \phi_Q\rangle+\langle\phi_P, \theta_Q\rangle\right].
\end{aligned}
\end{equation}
\end{lemma}
\begin{proof}
Suppose the error terms are $\eps_{\alpha}$, $\eps_{\alpha}^{2}$, $\eps_{\alpha}\eps_{\alpha+1}$ in $P$, and $\eps_{\beta}$, $\eps_{\beta}^{2}$, $\eps_{\beta}\eps_{\beta+1}$ in $Q$. For all nine possible combination in $PQ$, by Lemma~\ref{lem:app-noise-prod-expect}, the non-zero terms are
\begin{equation}
\begin{aligned}
\E [\eps_{\alpha} \eps_{\beta}] &= \nu_2 \delta_{\alpha\beta}, \\
\E [\eps_{\alpha}^{2} \eps_{\beta}^{2}] &= \nu_4 \delta_{\alpha\beta} + \nu_2^{2} (1 - \delta_{\alpha\beta}), \\
\E [\eps_{\alpha} \eps_{\alpha+1} \eps_{\beta} \eps_{\beta+1}] &= \nu_2^{2} \delta_{\alpha\beta}, \\
\E [\eps_{\alpha} \eps_{\beta}^{2}] &= \nu_3 \delta_{\alpha\beta}, \\
\E [\eps_{\alpha}^{2} \eps_{\beta}] &= \nu_3 \delta_{\alpha\beta}.
\end{aligned}
\end{equation}
Take the coefficients into considerations and notice that
\begin{equation}
\sum_{\alpha, \beta} \phi_{P}^{\alpha} \phi_{Q}^{\beta} = \sum_{\alpha} \phi_{P}^{\alpha} \sum_{\beta} \phi_{Q}^{\beta} = 0,
\end{equation}
so we have
\begin{equation}
\begin{aligned}
\E[PQ | \filt]
&=
\nu_2 \sum_{\alpha, \beta} \theta_{P}^{\alpha} \theta_{Q}^{\beta} \delta_{\alpha \beta}
+ \nu_4 \sum_{\alpha, \beta} \phi_{P}^{\alpha} \phi_{Q}^{\beta} \delta_{\alpha \beta} \\
& \quad
+ \nu_2^{2} \sum_{\alpha, \beta} \left(
\phi_{P}^{\alpha} \phi_{Q}^{\beta} (1 - \delta_{\alpha\beta})
+ \psi_{P}^{\alpha} \psi_{Q}^{\beta} \delta_{\alpha\beta}
\right) \\
& \quad
+ \nu_3 \sum_{\alpha, \beta} \left( 
\theta_{P}^{\alpha} \phi_{Q}^{\beta} \delta_{\alpha \beta}
+ \phi_{P}^{\alpha} \theta_{Q}^{\beta} \delta_{\alpha \beta}
\right) \\
&= \nu_2 \langle\theta_P, \theta_Q\rangle +\nu_4\langle\phi_P, \phi_Q\rangle \\
&\quad +\nu_2^2 \left[-\langle\phi_P, \phi_Q\rangle+\langle\psi_P, \psi_Q\rangle\right] + \nu_3 \left[\langle\theta_P, \phi_Q\rangle+\langle\phi_P, \theta_Q\rangle\right].
\end{aligned}
\end{equation}
The proof is thus completed.
\end{proof}

There are six terms to consider in the contribution of $N_2$. It is obvious that
\begin{equation}
\E [AB | \filt] = \E[CD | \filt] = 0,
\end{equation}
so we only need to calculate
\begin{equation}
\frac{1}{k_n^2 \Delta_n^2}
\sum_{k\in I} \sum_{l\in I}
\E\Bigl(bdAC + bcAD + adBC + acBD \Big| \filt\Bigr).
\end{equation}

Notice that
\begin{equation}
\E[AC | \filt] = \nu_2 \Bigl(2I(k=l) - I(|k-l|=1)\Bigr),
\end{equation}
so
\begin{equation}
\begin{aligned}
\sum_{k\in I}\sum_{l\in I}
\E [bdAC | \filt]
&=
\nu_2 \left(
2 \sum_{k=k_n+1}^{n-k_n-2} b_k^2
- \sum_{k=k_n+2}^{n-k_n-2} b_k b_{k-1}
- \sum_{k=k_n+1}^{n-k_n-3} b_k b_{k+1}
\right) \\
&=
\nu_2 \left(
\sum_{k=k_n+1}^{n-k_n-3} (\Delta b_k)^2
+ b_{k_n+1}^2 + b_{n-k_n-2}^2
\right),
\end{aligned}
\end{equation}
where
\begin{equation}
\begin{aligned}
(\Delta b_k)^2
&=
\left(
\left(\Delta X_{k+k_n+2}\right)^2 - \left(\Delta X_{k+2}\right)^2
- \left(\Delta X_{k-1}\right)^2 + \left(\Delta X_{k-k_n-1}\right)^2
\right)^2,
\end{aligned}
\end{equation}
As \cite{mykland2009InferenceContinuousSemimartingales} point out, the drift terms typically have no impact on the final result in the high-frequency setting, and locally constant approximations can be applied to simplify the analysis of asymptotic results. Therefore, by noticing that
\begin{equation}
\begin{aligned}
(\Delta b_k)^2
&\approx
\Bigl(
\sigma_{k+k_n+2}^2 \left(\Delta W_{k+k_n+2}\right)^2 - \sigma_{k+2}^2 \left(\Delta W_{k+2}\right)^2 \\
&\qquad
- \sigma_{k-1}^2 \left(\Delta W_{k-1}\right)^2 + \sigma_{k-k_n-1}^2\left(\Delta W_{k-k_n-1}\right)^2
\Bigr)^2 \\
&\approx
8\sigma_k^4 \Delta_n^2,
\end{aligned}
\end{equation}
we have
\begin{equation}\label{eq:all-observation-noise-N2-AC}
\Delta_n^{-1}
\sum_{k\in I}\sum_{l\in I}
\E \Bigl(bdAC \Big| \filt\Bigr)
\convp
8\nu_2 \int_{0}^{T} \sigma_{t}^4 \ud t.
\end{equation}

Notice that
\begin{equation}
\begin{aligned}
\E[AD | \filt] 
&= \nu_2 \langle\theta_A, \theta_D\rangle + \nu_3 \langle\theta_A, \phi_D\rangle,
\end{aligned}
\end{equation}
so
\begin{equation}
\begin{aligned}
\sum_{k\in I}\sum_{l\in I}
\E [bcAD | \filt]
&=
\nu_2 \sum_{k\in I}\sum_{l\in I} bc \langle\theta_A, \theta_D\rangle
+ \nu_3 \sum_{k\in I}\sum_{l\in I} bc \langle\theta_A, \phi_D\rangle.
\end{aligned}
\end{equation}
When $\langle\theta_A, \theta_D\rangle$ is not zero, it can be written as $\sum_{r} \eta_r \Delta X_{r}$, where up to four terms are present in this summation. The coefficient $\eta_r$ satisfies $|\eta_r| \leq 3$, and $\langle\theta_A, \theta_D\rangle$ is obviously mean zero as well as independent of $bc$, while $bc$ only includes the linear and cubic terms of $(\Delta X_r)$. Therefore, we can ignore the impact of $\sum_{k\in I}\sum_{l\in I} bc \langle\theta_A, \theta_D\rangle$ as its ``standardized version" (divided by the order of its standard deviation) is asymptotically mean zero and therefore tight. As for $\langle \theta_A, \phi_D\rangle$, one can verify that
\begin{equation}\label{eq:theta_A-phi_D}
\begin{aligned}
\langle \theta_A, \phi_D\rangle
&=
I\Bigl(|k-l| \in \{1,2\}\Bigr) - I\Bigl(|k-l| \in \{k_n+1, k_n+2\}\Bigr),
\end{aligned}
\end{equation}
so for a given $k$, there are up to eight non-zero $\langle \theta_A, \phi_D\rangle$, each with constant absolute value 1. When $\langle \theta_A, \phi_D\rangle$ is non-zero, $bc$ vanishes. Therefore, the ``standardized version" of $\sum_{k\in I}\sum_{l\in I} bc \langle\theta_A, \phi_D\rangle$ is tight as well. The order of variance can be estimated as $O_p(k_n^2 \Delta_n)$ for $\sum_{k\in I}\sum_{l\in I} bc \langle\theta_A, \phi_D\rangle$ and even smaller for $\sum_{k\in I}\sum_{l\in I} bc \langle\theta_A, \theta_D\rangle$. It follows that
\begin{equation}\label{eq:all-observation-noise-N2-AD}
k_n^{-1} \Delta_n^{-1/2}
\sum_{k\in I}\sum_{l\in I}
\E \Bigl(bcAD \Big| \filt\Bigr)
=
O_p(1).
\end{equation}
Moreover, because
\begin{equation}
\sum_{k\in I}\sum_{l\in I} adBC = \sum_{k\in I}\sum_{l\in I} a_k b_l B_k A_l = \sum_{k\in I}\sum_{l\in I} a_l b_k B_l A_k = \sum_{k\in I}\sum_{l\in I} bcAD,
\end{equation}
we also have
\begin{equation}\label{eq:all-observation-noise-N2-BC}
k_n^{-1} \Delta_n^{-1/2}
\sum_{k\in I}\sum_{l\in I}
\E \Bigl(adBC \Big| \filt\Bigr)
=
O_p(1).
\end{equation}

Lastly, notice that
\begin{equation}
\begin{aligned}
\E[BD | \filt] 
&= \nu_2 \langle\theta_B, \theta_D\rangle +\nu_4 \langle\phi_B, \phi_D\rangle \\
&\quad +\nu_2^2 \left[-\langle\phi_B, \phi_D\rangle+\langle\psi_B, \psi_D\rangle\right] + \nu_3 \left[\langle\theta_B, \phi_D\rangle+\langle\phi_B, \theta_D\rangle\right].
\end{aligned}
\end{equation}
Because $ac \approx \sigma_{k}^2 \Delta_n I(k=l)$, and
\begin{equation}
\|\phi_B\|^2 = 8k_n - 4, \quad \|\psi_B\|^2 = 8k_n,
\end{equation}
we can know that, as $n\to\infty$,
\begin{equation}
\begin{aligned}
&
\sum_{k\in I}\sum_{l\in I}
ac \Bigl(
\nu_4 \langle\phi_B, \phi_D\rangle
+\nu_2^2 \left[-\langle\phi_B, \phi_D\rangle + \langle\psi_B, \psi_D\rangle\right]
\Bigr) \\
&\approx
\sum_{k\in I}
\sigma_k^2 \Delta_n \Bigl[
\nu_4 \|\phi_B\|^2
+\nu_2^2 \left(-\|\phi_B\|^2 + \|\psi_B\|^2\right)
\Bigr] \\
&=
\sum_{k\in I}
\sigma_k^2 \Delta_n \Bigl[
(8k_n - 4) (\nu_4 - \nu_2^2)
+ 8k_n \nu_2^2
\Bigr] \\
&\approx
\Bigl[
(8k_n - 4) (\nu_4 - \nu_2^2)
+ 8k_n \nu_2^2
\Bigr]
\int_{0}^{T} \sigma_t^2 \ud t
\\
&\approx
8k_n \nu_4 \int_{0}^{T} \sigma_t^2 \ud t.
\end{aligned}
\end{equation}
For the $ac \langle\theta_B, \theta_D\rangle$ term, when $k \neq l$, only $(a, D)$ and $(c, B)$ can overlap, so $ac \langle\theta_B, \theta_D\rangle$ only contains the cubic terms of $(\Delta X_r)$, and thus vanishes. Therefore, the corresponding summation can be roughly estimated as
\begin{equation}
\begin{aligned}
\sum_{k\in I}\sum_{l\in I}
ac \Bigl(
\nu_2 \langle\theta_B, \theta_D\rangle
\Bigr)
&\approx
\nu_2
\sum_{k\in I}
a^2 \|\theta_B\|^2
\approx
\nu_2
\sum_{k\in I}
\sigma_k^2 \Delta_n \|\theta_B\|^2 \\
&=
\nu_2
\left(\int_{0}^{T} \sigma_t^2 \ud t\right)
O_p(k_n \Delta_n)
=
O_p(k_n \Delta_n).
\end{aligned}
\end{equation}
As for the $ac \langle\theta_B, \phi_D\rangle$ term, notice that
\begin{equation}
\sum_{k\in I}\sum_{l\in I}
ac \langle\theta_B, \phi_D\rangle
=
\sum_{k\in I}
a^2 \langle\theta_B, \phi_B\rangle
+
\sum_{k\in I}\sum_{l\in I}
ac \langle\theta_B, \phi_D\rangle
I(k \neq l).
\end{equation}
The first term vanishes because $\langle\theta_B, \phi_B\rangle$ only contains linear terms of $(\Delta X_r)$ and does not overlap with $a^2$. The second term vanishes because $a$ only contains the linear terms of $(\Delta X_r)$ and does not overlap with $c$ or $\langle\theta_B, \phi_D\rangle$. As a result, the ``standardized version" of $\sum_{k\in I} \sum_{l\in I} ac \langle\theta_B, \phi_D\rangle$ is tight, which is
\begin{equation}
k_n^{-1} \Delta_n^{-3/2}
\sum_{k\in I}\sum_{l\in I}
ac \langle\theta_B, \phi_D\rangle
=
O_p(1).
\end{equation}
The same argument can be applied to the $ac \langle\phi_B, \theta_D\rangle$ term. Therefore, we have
\begin{equation}\label{eq:all-observation-noise-N2-BD}
k_n^{-1}
\sum_{k\in I}\sum_{l\in I}
\E \Bigl(acBD \Big| \filt\Bigr)
\convp
8 \nu_4 \int_{0}^{T} \sigma_t^2 \ud t.
\end{equation}

Therefore, by combining Equation~\eqref{eq:all-observation-noise-N2-AC}, \eqref{eq:all-observation-noise-N2-AD}, \eqref{eq:all-observation-noise-N2-BC}, and \eqref{eq:all-observation-noise-N2-BD}, we can conclude that the contribution of the $N_2$ term to the variance due to noise is
\begin{equation}\label{eq:all-observation-noise-N2}
k_n^{-1}
\sum_{k\in I} \sum_{l\in I}
\E\Bigl(N_2(k, l) \Big| \filt\Bigr)
\convp
8\nu_4 \int_{0}^{T} \sigma_t^2 \ud t.
\end{equation}

\paragraph{Contribution of $N_3$}
The contribution of $N_3$ can be calculated in a similar way as $N_2$. We have the following lemma concerning the noise-related terms in $N_3$.

\begin{lemma}\label{lem:app-all-observation-noise-N3}
For $ABC$ and $ACD$ terms, we have
\begin{equation}
\E\left[ ABC | \filt \right] = \E\left[ ACD | \filt \right] = 0.
\end{equation}
For $ABD$ and $BCD$ terms, we have
\begin{equation}
\begin{aligned}
\E\left[ ABD | \filt \right]
= \sum_{i, \alpha, \beta} \Bigl\{
& \nu_2^{2} \left[ \theta_{A}^{i} \theta_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right) \\
& + \nu_2 \nu_3 \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right)
\Bigr\},
\end{aligned}
\end{equation}
where $\delta_{i\beta}^{(k+1)}$ is defined as $I(i = \beta = k+1)$, and
\begin{equation}
\begin{aligned}
\E\left[ BCD | \filt \right]
= \sum_{j, \alpha, \beta} \Bigl\{
& \nu_2^{2} \left[ \theta_{C}^{j} \theta_{D}^{\beta} \psi_{B}^{\alpha} \right]
\left( \delta_{j\alpha}^{(l+1)} \delta_{\beta, \alpha+1}^{(l+2)} + \delta_{\beta\alpha}^{l} \delta_{j, \alpha+1}^{(l-1)} \right) \\
& + \nu_2 \nu_3 \left[ \theta_{C}^{j} \phi_{D}^{\beta} \psi_{B}^{\alpha} \right]
\left( \delta_{j\alpha}^{(l+1)} \delta_{\beta, \alpha+1}^{(l+2)} + \delta_{\beta\alpha}^{l} \delta_{j, \alpha+1}^{(l-1)} \right)
\Bigr\}.
\end{aligned}
\end{equation}
\end{lemma}

\begin{proof}
Firstly, consider $\E\left[ ABC | X, \sigma \right]$. Notice that
\begin{equation}
ABC
=
\sum_{i,j,\alpha}
\theta_A^i \eps_i
\Bigl(\theta_B^\alpha \eps_\alpha + \phi_B^\alpha \eps_\alpha^2 + \psi_B^\alpha \eps_\alpha \eps_{\alpha+1}\Bigr)
\theta_C^j \eps_j.
\end{equation}
There are three types of possible combinations in $ABC$, the expectations of which are
\begin{equation}
\begin{aligned}
\E [\eps_{i} \eps_{\alpha} \eps_{j}] &= 0, \\
\E [\eps_{i} \eps_{\alpha}^{2} \eps_{j}] &= \nu_2^{2} \delta_{ij}, \\
\E [\eps_{i} \eps_{\alpha} \eps_{\alpha+1} \eps_{j}] &= 0,
\end{aligned}
\end{equation}
according to Lemma~\ref{lem:app-noise-prod-expect}. This is because $i \neq \alpha$ for all terms and $i \neq \alpha+1$ additionally for terms with $\eps_{\alpha}\eps_{\alpha+1}$. Taking their coefficients into consideration, and notice that
\begin{equation}
\sum_{\alpha} \phi_{B}^{\alpha} = 0,
\end{equation}
so we have
\begin{equation}
\E\left[ ABC | X, \sigma \right] 
= \sum_{i, j, \alpha} \nu_2^{2} \left[ 
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \right]\left( \delta_{ij} \right)
= \sum_{i} \nu_2^{2} \left[ 
\theta_{A}^{i} \theta_{C}^{i} \right] \sum_{\alpha} \phi_{B}^{\alpha}
= 0.
\end{equation}
For the same reason, we can conclude that
\begin{equation}
\E\left[ ACD | X, \sigma \right] = 0.
\end{equation}

Next, consider $\E\left[ ABD | X, \sigma \right]$. Notice that
\begin{equation}
ABD
=
\sum_{i,\alpha,\beta}
\theta_A^i \eps_i
\Bigl(\theta_B^\alpha \eps_\alpha + \phi_B^\alpha \eps_\alpha^2 + \psi_B^\alpha \eps_\alpha \eps_{\alpha+1}\Bigr)
\Bigl(\theta_D^\beta \eps_\beta + \phi_D^\beta \eps_\beta^2 + \psi_D^\beta \eps_\beta \eps_{\beta+1}\Bigr).
\end{equation}
There are nine types of possible combinations, among which four types have non-zero expectations, and they are
\begin{equation}
\begin{aligned}
\E \left[ \eps_{i} \eps_{\alpha} \eps_{\beta} \eps_{\beta+1} \right]
&= \nu_2^{2} \left(
\delta_{i\beta} \delta_{\alpha, \beta+1} + \delta_{\alpha\beta} \delta_{i, \beta+1}
\right), \\
\E \left[ \eps_{i} \eps_{\alpha}^{2} \eps_{\beta} \right]
&= \nu_2^{2} \delta_{i\beta}, \\
\E \left[ \eps_{i} \eps_{\alpha}^{2} \eps_{\beta}^{2} \right]
&= \nu_2 \nu_3 \delta_{i\beta}, \\
\E \left[ \eps_{i} \eps_{\alpha}^{2} \eps_{\beta} \eps_{\beta+1} \right]
&= \nu_2 \nu_3 \left(
\delta_{i\beta} \delta_{\alpha, \beta+1} + \delta_{\alpha\beta} \delta_{i, \beta+1}
\right).
\end{aligned}
\end{equation}
Therefore, we have
\begin{equation}
\begin{aligned}
\E\left[ ABD | \filt \right]
= \sum_{i, \alpha, \beta} \Bigl\{
& \nu_2^{2} \left[ \theta_{A}^{i} \theta_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta} \delta_{\alpha, \beta+1} + \delta_{\alpha\beta} \delta_{i, \beta+1} \right) \\
& + \nu_2^{2} \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \theta_{D}^{\beta} \right] \left( \delta_{i\beta} \right)
+ \nu_2 \nu_3 \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \phi_{D}^{\beta} \right] \left( \delta_{i\beta} \right) \\
& + \nu_2 \nu_3 \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \psi_{D}^{\beta} \right] \left( \delta_{i\beta} \delta_{\alpha, \beta+1} + \delta_{\alpha\beta} \delta_{i, \beta+1} \right) \Bigr\} \\
= \sum_{i, \alpha, \beta} \Bigl\{
& \nu_2^{2} \left[ \theta_{A}^{i} \theta_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right) \\
& + \nu_2 \nu_3 \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \psi_{D}^{\beta} \right] \left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right) \Bigr\},
\end{aligned}
\end{equation}
and $\E[BCD|\filt]$ can be calculated in a similar way. Thus, the proof is completed.
\end{proof}

Lemma~\ref{lem:app-all-observation-noise-N3} implies that we need to calculate
\begin{equation}
\frac{1}{k_n^2 \Delta_n^2}
\sum_{k\in I} \sum_{l\in I}
\E\Bigl(cABD + aBCD \Big| \filt\Bigr)
=
\frac{2}{k_n^2 \Delta_n^2}
\sum_{k\in I} \sum_{l\in I}
\E\Bigl(cABD \Big| \filt\Bigr).
\end{equation}

First, notice that
\begin{equation}
\begin{aligned}
&
\sum_{i,\alpha,\beta}
\nu_2^2
\left[ \theta_{A}^{i} \theta_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right) \\
&=
\nu_2^2
\Bigl\{
\theta_A^{k+1} \theta_B^{k+2} \psi_D^{k+1}
+ \theta_A^{k} \theta_B^{k-1} \psi_D^{k-1}
\Bigr\} \\
&=
\nu_2^2
\Bigl\{
(+1) (-2\Delta X_{k+2}) \psi_D^{k+1}
+ (-1) (-2\Delta X_{k-2}) \psi_D^{k-1}
\Bigr\},
\end{aligned}
\end{equation}
and $\psi_D^{k+1}$ as well as $\psi_D^{k-1}$ can be written as
\begin{equation}
\begin{aligned}
\psi_D^{k+1}
&=
+2 I(k+3\leq l \leq k+k_n+2)
-2 I(k-k_n \leq l \leq k-1), \\
\psi_D^{k-1}
&=
+2 I(k+1\leq l \leq k+k_n)
-2 I(k-k_n-2 \leq l \leq k-3),
\end{aligned}
\end{equation}
so
\begin{equation}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
c
\sum_{i,\alpha,\beta}
\nu_2^2
\left[ \theta_{A}^{i} \theta_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right) \\
&=
2\nu_2^2
\Biggl\{
- \sum_{k\in I} \sum_{l\in I}
(\Delta X_l) (\Delta X_{k+2}) \psi_D^{k+1}
+ \sum_{k\in I} \sum_{l\in I}
(\Delta X_l) (\Delta X_{k-2}) \psi_D^{k-1}
\Biggr\} \\
&=
4\nu_2^2
\Biggl\{
- \sum_{k\in I} \sum_{l\in I}
(\Delta X_l) (\Delta X_{k+2}) I(k+3\leq l \leq k+k_n+2) \\
&\qquad\quad\;
+ \sum_{k\in I} \sum_{l\in I}
(\Delta X_l) (\Delta X_{k+2}) I(k-k_n \leq l \leq k-1) \\
&\qquad\quad\;
+ \sum_{k\in I} \sum_{l\in I}
(\Delta X_l) (\Delta X_{k-2}) I(k+1\leq l \leq k+k_n) \\
&\qquad\quad\;
- \sum_{k\in I} \sum_{l\in I}
(\Delta X_l) (\Delta X_{k-2}) I(k-k_n-2 \leq l \leq k-3)
\Biggr\} \\
&=
4\nu_2^2
\sum_{k=k_n+2}^{n-k_n-3}
\Bigl\{
- (\Delta X_{k+2}) (X_{k+k_n+3} - X_{k+3})
+ (\Delta X_{k+2}) (X_{k} - X_{k-k_n}) \\
&\qquad\qquad\qquad\,
+ (\Delta X_{k-2}) (X_{k+k_n+1} - X_{k+1})
- (\Delta X_{k-2}) (X_{k-2} - X_{k-k_n-2})
\Bigr\}\\
&\qquad
+ \text{(edge terms)} \\
&\approx
4\nu_2^2
\sum_{k=k_n+2}^{n-k_n-3}
(\Delta X_k)
\Bigl(
\Delta_2 X_{k+k_n+1} - \Delta_2 X_{k+1} + \Delta_2 X_{k-2} - \Delta_2 X_{k-k_n-2}
\Bigr).
\end{aligned}
\end{equation}
It is clear that the expectation of this term vanishes, for $(\Delta X_k)$ does not overlap with $(\Delta_2 X_{k+k_n+1} - \Delta_2 X_{k+1} + \Delta_2 X_{k-2} - \Delta_2 X_{k-k_n-2})$. In fact, a CLT for $\eta_n = \sum_{k=k_n+2}^{n-k_n-3} (\Delta X_k)(\Delta_2 X_{k+k_n+1} - \Delta_2 X_{k+1} + \Delta_2 X_{k-2} - \Delta_2 X_{k-k_n-2})$ is
\begin{equation}
\Delta_n^{1/2} \eta_n
\convst
\int_0^T 4\sigma_t^2 \ud W_t^{(\eta)}, \quad \text{as }n \to \infty,
\end{equation}
where $(W_{t}^{(\eta)})_{t\geq 0}$ is a Wiener process independent of $(W_t)_{t\geq 0}$, and the convergence mode is stable convergence. As a result,
\begin{equation}\label{eq:all-observation-noise-N3-ABD-1}
\Delta_n^{1/2}
\sum_{k\in I} \sum_{l\in I}
c
\sum_{i,\alpha,\beta}
\nu_2^2
\left[ \theta_{A}^{i} \theta_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right)
=
O_p(1).
\end{equation}

Next, notice that
\begin{equation}
\begin{aligned}
&
\sum_{i, \alpha, \beta}
\nu_2 \nu_3 \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right) \\
&=
\nu_2\nu_3
\Bigl\{
\theta_A^{k+1} \phi_B^{k+2} \psi_D^{k+1}
+ \theta_A^k \phi_B^{k-1} \psi_D^{k-1}
\Bigr\} \\
&=
\nu_2\nu_3
\Bigl\{
(+1) (+1) \psi_D^{k+1}
+ (-1) (-1) \psi_D^{k-1}
\Bigr\} \\
&=
2\nu_2\nu_3
\Bigl\{
I(k+3\leq l \leq k+k_n+2) - I(k-k_n \leq l \leq k-1) \\
&\qquad\qquad\,
+ I(k+1\leq l \leq k+k_n) - I(k-k_n-2 \leq l \leq k-3)
\Bigr\},
\end{aligned}
\end{equation}
so
\begin{equation}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
c
\sum_{i, \alpha, \beta}
\nu_2 \nu_3 \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right) \\
&=
2\nu_2\nu_3
\Biggl\{
\sum_{k\in I} \sum_{l\in I}
(\Delta X_l)
\Bigl[
I(k+3\leq l \leq k+k_n+2) - I(k-k_n \leq l \leq k-1) \\
&\qquad\qquad\qquad\qquad\qquad
+ I(k+1\leq l \leq k+k_n) - I(k-k_n-2 \leq l \leq k-3)
\Bigr]
\Biggr\} \\
&=
2\nu_2\nu_3
\Biggl\{
\sum_{l\in I}
(\Delta X_k)
\sum_{k\in I}
\Bigl[
I(k+3\leq l \leq k+k_n+2) - I(k-k_n \leq l \leq k-1) \\
&\qquad\qquad\qquad\qquad\qquad
+ I(k+1\leq l \leq k+k_n) - I(k-k_n-2 \leq l \leq k-3)
\Bigr]
\Biggr\}.
\end{aligned}
\end{equation}
Different from some other summations in this section, in this summation, the center terms vanishes, while the edge terms dominate the result. After some careful calculation, we have
\begin{equation}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
c
\sum_{i, \alpha, \beta}
\nu_2 \nu_3 \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right) \\
&=
2\nu_2\nu_3
\Biggl\{
\Biggl(
(-2k_n) \Delta X_{k_n+1}
+(-2k_n+1) \Delta X_{k_n+2}
+\sum_{q=1}^{k_n-1} (-2k_n+2q) \Delta X_{k_n+2+q}
\\ &\qquad\qquad\qquad
+(-1) \Delta X_{2k_n+2}
\Biggr)
+
\Biggl(
\Delta X_{n-2k_n-3}
+\sum_{q=1}^{k_n-1} 2q \Delta X_{n-2k_n-3-q}
\\ &\qquad\qquad\qquad
+(2k_n-1) \Delta X_{n-k_n-3}
+2k_n \Delta X_{n-k_n-2}
\Biggr)
\Biggr\}.
\end{aligned}
\end{equation}
Of course, the expression vanishes if we omit the drift terms. However, in this case, it is safer to check it more carefully because of the special structure, where the drift terms at the start and end of the day are compared. Let the term inside the large bracket be denoted as $\xi_n$. The asymptotic mean of $\xi_n$ is given by $(\mu_T - \mu_0) k_n^2 \Delta_n$, and its asymptotic stochastic variance is $4 (\sigma_0^2 + \sigma_T^2) k_n^3 \Delta_n / 3$. Thus, we can conclude that the ``standardized version" of $\xi_n$ is tight. Specifically, we have
\begin{equation}\label{eq:all-observation-noise-N3-ABD-2}
k_n^{-3/2} \Delta_n^{-1/2}
\sum_{k\in I} \sum_{l\in I}
c
\sum_{i, \alpha, \beta}
\nu_2 \nu_3 \left[ \theta_{A}^{i} \phi_{B}^{\alpha} \psi_{D}^{\beta} \right]
\left( \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} + \delta_{\alpha\beta}^{(k)} \delta_{i, \beta+1}^{(k-1)} \right)
=
O_p(1).
\end{equation}

Therefore, by combining Equation~\eqref{eq:all-observation-noise-N3-ABD-1} and \eqref{eq:all-observation-noise-N3-ABD-2}, we can conclude that the contribution of the $N_3$ term to the variance due to noise satisfies
\begin{equation}\label{eq:all-observation-noise-N3}
k_n^{-3/2} \Delta_n^{-1/2}
\sum_{k\in I} \sum_{l\in I}
\E\Bigl(N_3(k, l) \Big| \filt\Bigr)
=
O_p(1).
\end{equation}

\paragraph{Contribution of $N_4$}
Similarly, we have the following lemma.

\begin{lemma}\label{lem:app-all-observation-noise-N4}
For $\E\left[ ABCD | \filt \right]$, we have
\begin{equation}\label{eq:ABCD}
\begin{aligned}
\E\left[ ABCD | \filt \right]
&=
\sum_{i, j, \alpha, \beta} \Bigl\{
\nu_2^{2} \left[
\theta_{A}^{i} \theta_{B}^{\alpha} \theta_{C}^{j} \theta_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta} + \delta_{i\beta} \delta_{\alpha j}
\right)
\\ &\qquad\quad\;\;
+ \nu_2 \nu_3 \left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \theta_{D}^{\beta}
+
\theta_{A}^{i} \theta_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta} + \delta_{i\beta} \delta_{\alpha j}
\right)
\\ &\qquad\quad\;\;
+ \nu_2 \nu_4 \left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta}
\right)
\\ &\qquad\quad\;\;
+ \nu_2^{3} \left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{ij} \left(1 - \delta_{\alpha\beta}\right)
\right)
\\ &\qquad\quad\;\;
+ \nu_3^{2} \left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{i\beta} \delta_{\alpha j}
\right)
\\ &\qquad\quad\;\;
+ \nu_2^{3}  \left[
\theta_{A}^{i} \psi_{B}^{\alpha} \theta_{C}^{j} \psi_{D}^{\beta}
\right] \Bigl(
\delta_{ij} \delta_{\alpha\beta}
+ \delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} \delta_{\alpha+1, j}^{(k+3)}I(l=k+3)
\\ &\qquad\qquad\qquad\qquad\qquad\qquad
+ \delta_{\alpha j}^{(l+1)} \delta_{\alpha+1, \beta}^{(l+2)} \delta_{i, \beta+1}^{(l+3)}I(l=k-3)
\Bigr)
\Bigr\}.
\end{aligned}
\end{equation}
\end{lemma}

\begin{proof}
Notice that
\begin{equation}
ABCD
=
\sum_{i,j,\alpha,\beta}
\theta_A^i \eps_i
\Bigl(\theta_B^\alpha \eps_\alpha + \phi_B^\alpha \eps_\alpha^2 + \psi_B^\alpha \eps_\alpha \eps_{\alpha+1}\Bigr)
\theta_C^j \eps_j
\Bigl(\theta_D^\beta \eps_\beta + \phi_D^\beta \eps_\beta^2 + \psi_D^\beta \eps_\beta \eps_{\beta+1}\Bigr).
\end{equation}
There are nine types of possible combinations of noise terms, among which five types have non-zero expectations, and they are
\begin{equation}
\begin{aligned}
\E[ \eps_{i} \eps_{\alpha} \eps_{j} \eps_{\beta} ]
&= \nu_2^{2} \left(
\delta_{ij} \delta_{\alpha\beta} + \delta_{i\beta} \delta_{\alpha j}
\right), \\
\E[ \eps_{i} \eps_{\alpha}^{2} \eps_{j} \eps_{\beta} ]
&= \nu_2 \nu_3 \left(
\delta_{ij} \delta_{\alpha\beta} + \delta_{i\beta} \delta_{\alpha j}
\right), \\
\E[ \eps_{i} \eps_{\alpha} \eps_{j} \eps_{\beta}^{2} ]
&= \nu_2 \nu_3 \left(
\delta_{ij} \delta_{\alpha\beta} + \delta_{i\beta} \delta_{\alpha j}
\right), \\
\E[ \eps_{i} \eps_{\alpha}^{2} \eps_{j} \eps_{\beta}^{2} ]
&= \nu_2 \nu_4 \left(
\delta_{ij} \delta_{\alpha\beta}
\right) + \nu_2^{3} \left(
\delta_{ij} \left( 1 - \delta_{\alpha\beta} \right)
\right) + \nu_3^{2} \left(
\delta_{i\beta} \delta_{\alpha j}
\right), \\
\E[ \eps_{i} \eps_{\alpha} \eps_{\alpha+1} \eps_{j} \eps_{\beta} \eps_{\beta+1} ]
&= \nu_2^{3} \left(
\delta_{ij} \delta_{\alpha\beta} + \delta_{i\beta} \delta_{\alpha, \beta+1} \delta_{\alpha+1, j} + \delta_{\alpha j} \delta_{\alpha+1, \beta} \delta_{i, \beta+1}
\right).
\end{aligned}
\end{equation}
The proof is completed by taking the coefficients into consideration.
\end{proof}

According to Lemma~\ref{lem:app-all-observation-noise-N4}, we need to calculate
\begin{equation}
\frac{1}{k_n^2 \Delta_n^2}
\sum_{k\in I} \sum_{l\in I}
\E\Bigl(ABCD \Big| \filt\Bigr).
\end{equation}
Before we proceed, it would be helpful to notice that there are two frequently present patterns of coefficients and Kronecker deltas, which imply some conditions on $k$ and $l$, and can be used to help simplify the calculation. Notice that
\begin{equation}\label{eq:all-observation-tAi-tCi-dij}
\begin{aligned}
\sum_{i,j}
\theta_A^i \theta_C^j \delta_{ij}
&=
\sum_{i=k}^{k+1} \sum_{j=l}^{l+1}
\theta_A^i \theta_C^j \delta_{ij} I(|k-l|\leq 1)
\\ &=
(\theta_A^k \theta_C^k + \theta_A^{k+1} \theta_C^{k+1}) I(k=l)
\\ & \quad
+ \theta_A^k \theta_C^k I(l=k-1)
+ \theta_A^{k+1} \theta_C^{k+1} I(l=k+1)
\\ &=
2I(k=l) - I(k=l-1) - I(k=l+1),
\end{aligned}
\end{equation}
so for any coefficient vectors $\xi$ and $\eta$, we have the first typical pattern:
\begin{equation}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\left[\theta_A^i \xi_B^\alpha \theta_C^j \eta_D^\beta\right]
\left(\delta_{ij} \delta_{\alpha\beta}\right)
\\ &=
\sum_{k\in I} \sum_{l\in I}
\Bigl\{
\sum_\alpha \xi_B^\alpha \eta_D^\alpha
\sum_{i,j}
\theta_A^i \theta_C^j \delta_{ij}
\Bigr\}
\\ &=
\sum_{k\in I}
\Bigl\{
2 \langle \xi_B, \eta_B \rangle
- \langle \xi_{B_k}, \eta_{B_{k-1}} \rangle I\bigl((k-1)\in I\bigr)
- \langle \xi_{B_k}, \eta_{B_{k+1}} \rangle I\bigl((k+1)\in I\bigr)
\Bigr\},
\end{aligned}
\end{equation}
The second typical pattern is
\begin{equation}
\begin{aligned}
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\left[\theta_A^i \xi_B^\alpha \theta_C^j \eta_D^\beta\right]
\left(\delta_{i\beta} \delta_{\alpha j}\right)
&=
\sum_{k\in I} \sum_{l\in I}
\Bigl\{
\sum_i \theta_A^i \eta_D^i
\sum_j \theta_C^i \xi_B^i
\Bigr\}
\\ &=
\sum_{k\in I} \sum_{l\in I}
\langle \theta_A, \eta_D \rangle \langle \theta_C, \xi_B \rangle.
\end{aligned}
\end{equation}
These two patterns can be used to simplify the calculation.


First, we analyze the terms without coefficients $\theta_B$ and $\theta_D$, as these terms only include constant coefficients, and thus are easier to handle and there is no need to take the expectation with respect to processes. They are also likely to have larger order than the terms with $\theta_B$ and $\theta_D$. Notice that
\begin{align}
\|\phi_B\|^2 &= 8k_n - 4, &\text{for all } &k \in I, \\
\quad \langle \phi_{B_k}, \phi_{B_{k+1}} \rangle &= 8k_n - 8, &\text{for all } &k, k+1 \in I,
\end{align}
so we have
\begin{equation}\label{eq:all-observation-noise-N4-1}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\nu_2 \nu_4 \left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta}
\right)
\\ &=
\nu_2 \nu_4
\sum_{k\in I}
\Bigl\{
2\|\phi_B\|^2
- \langle \phi_{B_k}, \phi_{B_{k-1}} \rangle I\bigl((k-1)\in I\bigr)
- \langle \phi_{B_k}, \phi_{B_{k+1}} \rangle I\bigl((k+1)\in I\bigr)
\Bigr\}
\\ &=
\nu_2 \nu_4
\sum_{k\in I}
\Bigl\{
2(8k_n - 4)
- (8k_n - 8)
- (8k_n - 8)
\Bigr\}
\\ &=
\nu_2 \nu_4
\Bigl(
(n-2k_n-4)\times 8
+ 2\times 8k_n
\Bigr)
\\ &=
\nu_2 \nu_4
(8n - 32).
\end{aligned}
\end{equation}
Recall that $\sum_\alpha \phi_B^\alpha = 0$, so we have
\begin{equation}\label{eq:all-observation-noise-N4-2}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\nu_2^{3} \left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{ij} \left(1 - \delta_{\alpha\beta}\right)
\right)
\\ &=
\nu_2^{3}
\sum_{k\in I} \sum_{l\in I}
\Bigl\{
\Bigl(\sum_\alpha \phi_B^\alpha\Bigr)
\Bigl(\sum_\beta \phi_D^\beta\Bigr)
\sum_{i,j} \theta_A^i \theta_C^j \delta_{ij}
-
\sum_{i,j,\alpha,\beta}
\left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta}
\right)
\Bigr\}
\\ &=
-\nu_2^{3}
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta}
\right)
\\ &=
-\nu_2^{3}
(8n - 32).
\end{aligned}
\end{equation}
Recall Equation~\eqref{eq:theta_A-phi_D}. Because
\begin{equation}
\langle \theta_A, \phi_D\rangle
=
\langle \theta_C, \phi_B\rangle
=
I\Bigl(|k-l| \in \{1,2\}\Bigr) - I\Bigl(|k-l| \in \{k_n+1, k_n+2\}\Bigr),
\end{equation}
we can know that
\begin{equation}
\langle \theta_A, \phi_D\rangle \langle \theta_C, \phi_B\rangle
=
I\Bigl(|k-l| \in \{1,2,k_n+1, k_n+2\}\Bigr).
\end{equation}
Therefore, we have
\begin{equation}\label{eq:all-observation-noise-N4-3}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\nu_3^{2} \left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{i\beta} \delta_{\alpha j}
\right)
\\ &=
\nu_3^{2}
\sum_{k\in I} \sum_{l\in I}
\langle \theta_A, \phi_D\rangle \langle \theta_C, \phi_B\rangle
\\ &=
\nu_3^{2}
\sum_{k\in I} \sum_{l\in I}
I\Bigl(|k-l| \in \{1,2,k_n+1, k_n+2\}\Bigr)
\\ &=
2 \nu_3^{2}
\sum_{q\in \{1,2,k_n+1, k_n+2\}} (n-2k_n-2-q)
\\ &=
\nu_3^{2}
(8n - 20k_n - 28).
\end{aligned}
\end{equation}
Moreover, notice that
\begin{align}
\|\psi_B\|^2 &= 8k_n, &\text{for all } &k \in I, \\
\quad \langle \psi_{B_k}, \psi_{B_{k+1}} \rangle &= 8k_n - 8, &\text{for all } &k, k+1 \in I,
\end{align}
so we have
\begin{equation}\label{eq:all-observation-noise-N4-4}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\nu_2^{3}  \left[
\theta_{A}^{i} \psi_{B}^{\alpha} \theta_{C}^{j} \psi_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta}
\right)
\\ &=
\nu_2^{3}
\sum_{k\in I}
\Bigl\{
2\|\psi_B\|^2
- \langle \psi_{B_k}, \psi_{B_{k-1}} \rangle I\bigl((k-1)\in I\bigr)
- \langle \psi_{B_k}, \psi_{B_{k+1}} \rangle I\bigl((k+1)\in I\bigr)
\Bigr\}
\\ &=
\nu_2^{3}
\sum_{k\in I}
\Bigl\{
2\times 8k_n
- (8k_n - 8)
- (8k_n - 8)
\Bigr\}
\\ &=
\nu_2^{3}
\Bigl(
(n-2k_n-4)\times 16
+ 2\times (8k_n+8)
\Bigr)
\\ &=
\nu_2^{3}
(16n - 16k_n - 48).
\end{aligned}
\end{equation}
The last term without coefficients $\theta_B$ and $\theta_D$ is
\begin{equation}\label{eq:all-observation-noise-N4-5}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\nu_2^{3}  \left[
\theta_{A}^{i} \psi_{B}^{\alpha} \theta_{C}^{j} \psi_{D}^{\beta}
\right] \Bigl(
\delta_{i\beta}^{(k+1)} \delta_{\alpha, \beta+1}^{(k+2)} \delta_{\alpha+1, j}^{(k+3)}I(l=k+3)
\\ &\qquad\qquad\qquad\qquad\qquad\qquad\qquad
+ \delta_{\alpha j}^{(l+1)} \delta_{\alpha+1, \beta}^{(l+2)} \delta_{i, \beta+1}^{(l+3)}I(l=k-3)
\Bigr)
\\ &=
\nu_2^{3}
\sum_{k\in I} \sum_{l\in I}
\Bigl\{
\theta_A^{k+1} \psi_B^{k+2} \theta_C^{l} \psi_D^{l-2} I(l=k+3)
+ \theta_A^{k} \psi_B^{k-2} \theta_C^{l+1} \psi_D^{l+2} I(l=k-3)
\Bigr\}
\\ &=
4 \nu_2^{3}
\sum_{k\in I} \sum_{l\in I}
I(|k-l| = 3)
=
\nu_2^{3}
(8n - 16k_n - 40).
\end{aligned}
\end{equation}

Next, we consider terms with coefficients $\theta_B$ and $\theta_D$. Notice that
\begin{align}
\|\theta_B\|^2 &\approx 16\sigma_k^2 k_n\Delta_n, &\text{for all } &k \in I, \\
\langle \theta_{B_k}, \theta_{B_{k+1}} \rangle &\approx 16\sigma_k^2 (k_n-1)\Delta_n, &\text{for all } &k, k+1 \in I,
\end{align}
so
\begin{equation}\label{eq:all-observation-noise-N4-6}
\begin{aligned}
&
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\nu_2^{2} \left[
\theta_{A}^{i} \theta_{B}^{\alpha} \theta_{C}^{j} \theta_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta}
\right)
\\ &=
\nu_2^{2}
\sum_{k\in I}
\Bigl\{
2 \|\theta_B\|^2
- \langle \theta_{B_k}, \theta_{B_{k-1}} \rangle I\bigl((k-1)\in I\bigr)
- \langle \theta_{B_k}, \theta_{B_{k+1}} \rangle I\bigl((k+1)\in I\bigr)
\Bigr\}
\\ &\approx
\nu_2^{2}
\sum_{k\in I}
\Bigl\{
2 \times 16\sigma_k^2 k_n\Delta_n
- 16\sigma_k^2 (k_n-1)\Delta_n I\bigl((k-1)\in I\bigr)
\\ &\qquad\qquad\qquad\qquad\qquad\qquad
- 16\sigma_k^2 (k_n-1)\Delta_n I\bigl((k+1)\in I\bigr)
\Bigr\}
\\ &\approx
\nu_2^{2}
\sum_{k\in I}
16\sigma_k^2 k_n\Delta_n
\approx
16 k_n \nu_2^{2} \int_0^T \sigma_t^2 \ud t.
\end{aligned}
\end{equation}
Notice that any of $\langle \theta_A, \theta_D \rangle$ and $\langle \theta_B, \theta_C \rangle$ is a linear combination of $(\Delta X_r)$'s, and the $(\Delta X_r)$'s in two terms never overlap, so the ``standardized version'' vanishes:
\begin{equation}\label{eq:all-observation-noise-N4-7}
k_n^{-1/2} \Delta_n^{-1/2}
\sum_{k\in I} \sum_{l\in I}
\sum_{i,j,\alpha,\beta}
\nu_2^{2} \left[
\theta_{A}^{i} \theta_{B}^{\alpha} \theta_{C}^{j} \theta_{D}^{\beta}
\right] \left(
\delta_{i\beta} \delta_{\alpha j}
\right)
\convp
0.
\end{equation}
For similar reason, because $\langle \phi_B, \theta_D \rangle$, $\langle \theta_B, \phi_D \rangle$, $\langle \theta_A, \phi_D \rangle$ and $\langle \theta_C, \phi_B \rangle$ only contain linear combinations $(\Delta X_r)$'s, we have
\begin{equation}\label{eq:all-observation-noise-N4-8}
k_n^{-1/2}
\sum_{k\in I} \sum_{l\in I}
\nu_2 \nu_3 \left[
\theta_{A}^{i} \phi_{B}^{\alpha} \theta_{C}^{j} \theta_{D}^{\beta}
+
\theta_{A}^{i} \theta_{B}^{\alpha} \theta_{C}^{j} \phi_{D}^{\beta}
\right] \left(
\delta_{ij} \delta_{\alpha\beta} + \delta_{i\beta} \delta_{\alpha j}
\right)
\convp
0.
\end{equation}

Therefore, by combing Equation~\eqref{eq:all-observation-noise-N4-1}, \eqref{eq:all-observation-noise-N4-2}, \eqref{eq:all-observation-noise-N4-3}, \eqref{eq:all-observation-noise-N4-4}, \eqref{eq:all-observation-noise-N4-5}, \eqref{eq:all-observation-noise-N4-6}, \eqref{eq:all-observation-noise-N4-7} and \eqref{eq:all-observation-noise-N4-8}, we can conclude that the contribution of the $N_4$ term to the variance due to noise is
\begin{equation}\label{eq:all-observation-noise-N4}
n^{-1}
\sum_{k\in I} \sum_{l\in I}
\E\Bigl(N_4(k, l) \Big| \filt\Bigr)
\convp
8\nu_2\nu_4 + 16\nu_2^3 + 8\nu_3^2.
\end{equation}

\paragraph{Total variance due to noise}
Finally, by combining Equation~\eqref{eq:all-observation-noise-N2}, \eqref{eq:all-observation-noise-N3} and \eqref{eq:all-observation-noise-N4}, we can see that $N_4$ dominates the variance due to noise, so
\begin{equation}
n^{-1}
\sum_{m=1}^{4}
\sum_{k \in I} \sum_{l \in I}
\E \Bigl(
N_{m}(k, l)
\Big| \filt \Bigr)
\convp
8\nu_2\nu_4 + 16\nu_2^3 + 8\nu_3^2.
\end{equation}
Therefore, according to Equation~\eqref{all-observation-noise-variance-four-terms}, the variance due to noise satisfies
\begin{equation}
\frac
{\var\left(\left. \widehat{[X, \sigma^2]}^{\rm (all)}_T \right| \filt \right)}
{n^3 k_n^{-2}}
\convp
\frac{8\nu_2\nu_4 + 16\nu_2^3 + 8\nu_3^2}{T^2},
\end{equation}
as $n \to \infty$. Using the results above, one can also prove that
\begin{equation}
\frac
{\E \left[
    \var\left(\left. \widehat{[X, \sigma^2]}^{\rm (all)}_T \right| \filt \right)
\right]}
{n^3 k_n^{-2}}
\to
\frac{8\nu_2\nu_4 + 16\nu_2^3 + 8\nu_3^2}{T^2},
\end{equation}
as $n \to \infty$.

\subsubsection{The central limit theorem}
The detailed analysis above shows that, as $n \to \infty$, the process-related terms have no impact on the first and second order behavior of the estimator. Moreover, after ignoring the process-related terms in $u_i$, one can see that the resulting sequence $\{u'_i\}$ is a stationary, mean-zero and $(2k_n+4)$-dependent sequence. According to the central limit theorem for $m$-dependent sequence \citep{lehmann1999ElementsLargesampleTheory}, we can prove the central limit theorem for the estimator which uses $\Delta Y_i = \eps_i$ as its observations. Then, with the continuous mapping theorem as well as the results above, we have the central limit theorem
\begin{equation}
\frac
{\Delta_n^{3/2} k_n (\widehat{[X, \sigma^2]}^{\rm (all)}_t - [X, \sigma^2]^{\rm (all)}_t)}
{\sqrt{8 \nu_2 \nu_4 + 16 \nu_2^3 + 8 \nu_3^2}}
\convd
\normal(0, t),
\quad \text{as }n \to \infty.
\end{equation}
Moreover, notice that the limiting process of the left hand side starts at zero and has independent increments. According to the unbiasedness due to noise, it is also uncorrelated with $\filt$, so the limiting process is a Brownian motion independent of $\filt$. This completes the proof of Proposition~\ref{prop:all-observation-noise}.

\subsubsection{A more precise version}
In fact, the above asymptotic analysis is based on two assumptions: the level of noise is not too small (for example, $\nu_2 \gg 0, \nu_4 \gg 0$), and $n \to \infty$. When the noise is relatively small and the sample size is not large enough, it can be beneficial to use a more precise version of the variance due to noise, which is a by-product of the detailed analysis above. Combining Equation~\eqref{eq:all-observation-noise-N2-AC}, Equation~\eqref{eq:all-observation-noise-N2-BD} and Equation~\eqref{eq:all-observation-noise-N4-6}, we have
\begin{equation}\label{eq:all-observation-noise-variance-corrected}
\frac
{\var\left(\left. \widehat{[X, \sigma^2]}^{\rm (all)}_T \right| \filt \right)}
{n^3 k_n^{-2}}
\convp
T^{-2}
\biggl[
(8\nu_2\nu_4 + 16\nu_2^3 + 8\nu_3^2)
+ \frac{k_n}{n^2} \cdot (8\nu_4 + 16\nu_2^2) \int_0^T \sigma_t^2 \ud t
+ \frac{1}{n^2} \cdot 8T \nu_2 \int_0^T \sigma_t^4 \ud t
\biggr].
\end{equation}
This can be helpful for finite sample analysis, especially when the scale of the noise is relatively small, as Figure~\ref{fig:avar-noise} and Figure~\ref{fig:avar-sources-scale} illustrate.

\subsection{Proof of Proposition~\ref{prop:SALE-noise}}\label{app:SALE-noise}
\subsubsection{Proof}
The unbiasedness of the subsample estimator and the SALE estimator can be directly derived from Proposition~\ref{prop:all-observation-noise}. The variance due to noise for the subsample estimator can also be derived similarly, which is
\begin{equation}
\frac
{\var\left(\left. \widehat{[X, \sigma^2]}^{(H_n, h)}_T \right| \filt \right)}
{n^3 H_n^{-3} k_n^{-2}}
\convp
\frac{8\nu_2\nu_4 + 16\nu_2^3 + 8\nu_3^2}{T^2}, \quad \text{as } n \to \infty.
\end{equation}
In order to derive the variance due to noise for the SALE estimator, we need to further consider the covariance between different subsample estimators:
\begin{equation}
\var\left(\left. \widehat{[X, \sigma^2]}^{(H_n)}_T \right| \filt \right)
=
H_n^{-2} \sum_{h=1}^{H_n} \sum_{g=1}^{H_n}
\cov\left(\left.
    \widehat{[X, \sigma^2]}^{(H_n, h)}_T,
    \widehat{[X, \sigma^2]}^{(H_n, g)}_T
\right| \filt \right).
\end{equation}
When $\{\eps_i\}_{i=0}^{n}$ is independent, it is easy to see that
\begin{equation}
\frac
{\var\left(\left. \widehat{[X, \sigma^2]}^{(H_n)}_T \right| \filt \right)}
{n^3 H_n^{-4} k_n^{-2}}
\convp
\frac{8\nu_2\nu_4 + 16\nu_2^3 + 8\nu_3^2}{T^2}, \quad \text{as } n \to \infty.
\end{equation}
When the noise is not independent, we can still derive the covariance between subsample $(H_n, h)$ and $(H_n, g)$, and the assuming $2q < H_n$ may simplify the calculation. This can be easily done by multiplying the moments of noise to the corresponding ``generalized correlation'' coefficients. In order to express it more explicitly, given a scale $H_n$, consider two subsamples indexed by $h$ and $g$ with $|g-h| < q$. Denoting $I_{H_n} = \cap_{h=1}^{H_n} I_{H_n, h} = \{k_n+1, \dotsc, n_{H_n}-k_n-2\}$, where $n_{H_n} = \lfloor (n+1)/H_n \rfloor - 1$, we can write the subsample estimators as
\begin{align}
\widehat{[X, \sigma^2]}^{(H_n, h)}_T
&=
\frac{1}{k_n H_n \Delta_n}
\sum_{k\in I_{H_n}} u_{k, h}, \\
\widehat{[X, \sigma^2]}^{(H_n, g)}_T
&=
\frac{1}{k_n H_n \Delta_n}
\sum_{l\in I_{H_n}} u_{l, g},
\end{align}
except for up to one end of the day term. The increment can be decomposed similarly as
\begin{equation}\label{eq:SALE-noise-increment-1}
\begin{aligned}
u_{k, h}
&=
(\Delta_{H_n} Y_{k_{h}}) \left(
\sum_{j\in I^{+}(k)} (\Delta_{H_n} Y_{j_{h}})^{2} - \sum_{j\in I^{-}(k)}(\Delta_{H_n} Y_{j_{h}})^{2}
\right) \\
&=
\left( a_{k, h} + A_{k, h} \right) \left( b_{k, h} + B_{k, h} \right),
\end{aligned}
\end{equation}
where
\begin{equation}\label{eq:SALE-noise-increment-2}
\begin{aligned}
\textcolor{blue}{a_{k, h}} + \textcolor{red}{A_{k, h}} & = (\Delta_{H_n} Y_{k_{h}}) =
\textcolor{blue}{(\Delta_{H_n} X_{k_{h}})}
+
\textcolor{red}{\langle \theta_{A_{k, h}}, \eps^{(h)} \rangle}, \\
\textcolor{blue}{b_{k, h}} + \textcolor{red}{B_{k, h}} & = \left(
\sum_{j\in I^{+}(k)} (\Delta_{H_n} Y_{j_{h}})^{2} - \sum_{j\in I^{-}(k)}(\Delta_{H_n} Y_{j_{h}})^{2}
\right) \\
& =
\textcolor{blue}{
\left(
\sum_{j\in I^{+}(k)} (\Delta_{H_n} X_{j_{h}})^{2} - \sum_{j\in I^{-}(k)}(\Delta_{H_n} X_{j_{h}})^{2}
\right)
} \\
&\qquad + 
\textcolor{red}{
\langle \theta_{B_{k, h}}, \eps^{(h)} \rangle
+ \langle \phi_{B_{k, h}}, \eps^{(h)2} \rangle
+ \langle \psi_{B_{k, h}}, \eps\eps^{(h)}_{+} \rangle
}.
\end{aligned}
\end{equation}
Here, the noise vector is defined by
\begin{equation}
(\eps^{(h)})_j = \eps_{j_h}, \quad
(\eps^{(h)2})_j = (\eps_{j_h})^2, \quad
(\eps\eps^{(h)}_{+})_j = \eps_{j_h} \eps_{(j+1)_h}I(j\neq n_{H_n, h}),
\end{equation}
and the non-zero values of $\theta_{A_{i, h}}$, $\theta_{B_{i, h}}$, $\phi_{B_{i, h}}$ and $\psi_{B_{i, h}}$ are listed in Table~\ref{tab:coeff-subgrid}, where the column represents the observation indices in subsample $(H_n, h)$.

\begin{table}[!ht]
\centering
\caption{Values of coefficient vectors in the subsample estimator}
\label{tab:coeff-subgrid}
\resizebox{\textwidth}{!}{
\begin{tabular}{ccccccccccccc}
\toprule
~ & $i-k_n-1$ & $i-k_n$ & $\cdots$ & $i-2$ & $i-1$ & $i$ & $i+1$ & $i+2$ & $i+3$ & $\cdots$ & $i+k_n+1$ & $i+k_n+2$ \\ 
\midrule
$\theta_{A_{i, h}}$ & \textcolor{blue}{$0$} & \textcolor{blue}{$0$} & $\cdots$ & \textcolor{blue}{$0$} & \textcolor{blue}{$0$} & $-1$ & $+1$ & \textcolor{blue}{$0$} & \textcolor{blue}{$0$} & $\cdots$ & \textcolor{blue}{$0$} & \textcolor{blue}{$0$} \\
$\theta_{B_{i, h}}$ & $+2\Delta_{H_n} X_{i-k_n H_n-H_n}$ & 
$+2\Delta_{H_n}^2 X_{i-k_n H_n-H_n}$ & $\cdots$ & 
$+2\Delta_{H_n}^2 X_{i-3 H_n}$ & $-2\Delta_{H_n} X_{i-2H_{n}}$ & \textcolor{blue}{$0$} & \textcolor{blue}{$0$} & $-2\Delta_{H_n} X_{i+2H_{n}}$ & 
$-2\Delta_{H_n}^2 X_{i+2 H_n}$ & $\cdots$ & 
$-2\Delta_{H_n}^2 X_{i+k_n H_n}$ & $+2\Delta_{H_n} X_{i+k_n H_n+H_n}$ \\
$\phi_{B_{i, h}}$ & $-1$ & $-2$ & $\cdots$ & $-2$ & $-1$ & \textcolor{blue}{$0$} & \textcolor{blue}{$0$} & $+1$ & $+2$ & $\cdots$ & $+2$ & $+1$ \\ 
$\psi_{B_{i, h}}$ & $+2$ & $+2$ & $\cdots$ & $+2$ & \textcolor{blue}{$0$} & \textcolor{blue}{$0$} & \textcolor{blue}{$0$} & $-2$ & $-2$ & $\cdots$ & $-2$ & \textcolor{blue}{$0$} \\ 
\bottomrule
\end{tabular}
}
\end{table}

Compared with the proof of Proposition~\ref{prop:all-observation-noise}, there are mainly two differences. First, the coefficient vectors $\theta_{B_{i, h}}$ and $\theta_{B_{i, g}}$ are different, but similar as in Appendix~\ref{app:all-observation-noise}, the corresponding terms are negligible in the final results. Second, for the noise terms in different subsamples, we have
\begin{equation}
\eps_{i_h} \perp \eps_{j_l}, \quad \text{if } i \neq j,
\end{equation}
and when $i=j$, the corresponding moments are corrected by the generalized correlation coefficients defined in Equation~\eqref{eq:general-acf}. For example,
\begin{align}
\E [ \eps_{i_h} \eps_{j_g} ]
&=
\nu_2 \rho_2(g-h) \delta_{ij}, \\
\E [ \eps_{i_h} \eps_{j_g}^{2} ]
&=
\sqrt{\nu_2 \left(\nu_4 - \nu_2^2\right)}
\rho_3(g-h) \delta_{ij}, \\
\E [ \eps_{i_h}^{2} \eps_{j_g}^{2} ]
&=
\nu_2^2 + \left(\nu_4 - \nu_2^2\right) \rho_4(g-h) \delta_{ij}.
\end{align}
In this way, we can derive the covariance between different subsample estimators as
\begin{equation}
\begin{aligned}
&
n^{-3} H_n^3 k_n^2
\cov\left(\left.
    \widehat{[X, \sigma^2]}^{(H_n, h)}_T,
    \widehat{[X, \sigma^2]}^{(H_n, g)}_T
\right| \filt \right) \\
&
\convp
8 \nu_2 \left(\nu_4 - \nu_2^2\right) \rho_2(g-h)\rho_4(g-h)
+ 24 \nu_2^3 \rho_2^3(g-h)
+ 8 \nu_2 \left(\nu_4 - \nu_2^2\right) \rho_3(g-h) \rho_3(h-g),
\end{aligned}
\end{equation}
and therefore
\begin{equation}\label{eq:E-Var-tilde}
\frac
{\var \left(\left. \widehat{[ X, \sigma^{2} ]}^{(H_n)}_T \right| \filt \right)}
{n^3 H_n^{-4}k_n^{-2}}
\\
\convp
\frac{\Phi}{T^2},
\end{equation}
where
\begin{equation}
\Phi = 8 \nu_2 \left(\nu_4 - \nu_2^2\right)
\sum_{l=-q}^{q} \Bigl( \rho_2(l)\rho_4(l) + \rho_3(l) \rho_3(-l) \Bigr)
+ 24 \nu_2^3 \sum_{l=-q}^{q} \rho_2^3(l).
\end{equation}
The rest of the proof is similar. This completes the proof of Proposition~\ref{prop:SALE-noise}.

\subsubsection{A more precise version}
Similarly, a more precise version is given by
\begin{equation}\label{eq:SALE-noise-variance-corrected}
\frac
{\var \left(\left. \widehat{[ X, \sigma^{2} ]}^{(H_n)}_T \right| \filt \right)}
{n^3 H_n^{-4}k_n^{-2}}
\\
\convp
\frac{\Phi'}{T^2},
\end{equation}
where
\begin{equation}
\begin{aligned}
\Phi'
&=
8 \nu_2 \left(\nu_4 - \nu_2^2\right)
\sum_{l=-q}^{q} \Bigl( \rho_2(l)\rho_4(l) + \rho_3(l) \rho_3(-l) \Bigr)
+ 24 \nu_2^3 \sum_{l=-q}^{q} \rho_2^3(l)
\\ & \quad
+ \frac{k_nH_n}{n} \cdot \Biggl[
8 (\nu_4 - \nu_2^2) \int_0^T \sigma_t^2 \ud t
\sum_{l=-q}^{q} \left(1-\frac{|d|}{H_n}\right)
\left(
\rho_4(d) + \frac{\nu_2^2}{\nu_4-\nu_2^2} \Bigl(1-\rho_2^2(d)\Bigr)
\right)
\Biggr]
\\ & \quad
+ \frac{k_nH_n}{n} \cdot \Biggl[
24 \nu_2^2 \int_0^T \sigma_t^2 \ud t
\sum_{l=-q}^{q} \left(1-\frac{|d|}{H_n}\right) \rho_2^2(d)
\Biggr]
\\ & \quad
+ \frac{H_n^2}{n^2} \cdot \Biggl[
8T \nu_2 \int_0^T \sigma_t^4 \ud t
\sum_{l=-q}^{q} \left(1-\frac{|d|}{H_n}\right)^2 \rho_2(d)
\Biggr].
\end{aligned}
\end{equation}

\subsection{On Proposition~\ref{prop:MSLE-noise}}\label{app:MSLE-noise}
\subsubsection{The iid noise setting}
When the noise is independent, the correlation between SALE at different scales are negligible except for a special case when one scale is exactly double the other. This can be established with the same way of calculating the contribution of noise terms as above. The calculation is tedious, so we will only explain the intuition instead of expanding the details. For example, consider the increment from two scales $H_p \geq H_q$.
\begin{align}
\widehat{[X, \sigma^2]}^{(H_p)}_T
&=
\frac{1}{k_p H_p^2 \Delta_n} \sum_{k=(k_p+1)H_p}^{n-(k_p+2)H_p} u_k^{(H_p)}, \\
\widehat{[X, \sigma^2]}^{(H_q)}_T
&=
\frac{1}{k_q H_q^2 \Delta_n} \sum_{l=(k_q+1)H_q}^{n-(k_q+2)H_q} u_l^{(H_q)},
\end{align}
where the increment can be decomposed similarly as before. For example, denote that we decompose $u_k^{(H_p)}$ as $(a_k+A_k)(b_k+B_k)$, and $u_l^{(H_q)}$ as $(c_k+C_k)(d_k+D_k)$. The dominant terms can be established similar as in Lemma~\ref{lem:app-all-observation-noise-N4}, where we only consider terms without $\theta_B$ and $\theta_D$ as they become negligible as $n \to \infty$. However, for $H_p > H_q$, one can conclude after some tedious calculation that the only terms that remain after summation over $l$ is
\begin{equation}
\sum_{l=(k_q+1)H_q}^{n-(k_q+2)H_q}
\sum_{i,j,\alpha,\beta}
\nu_2(\nu_4-\nu_2^2) \left[\theta_A^i \phi_B^\alpha \theta_C^j \phi_B^\beta\right]
(\delta_{ij} \delta_{\alpha\beta})
=
2 \nu_2(\nu_4-\nu_2^2) I(H_p = 2H_q),
\end{equation}
so $H_p = 2H_q$ is a very special situation. The contribution of elements from $\phi_B$ and $\phi_D$ at $l-2,l-1,l+2$, and $l+3$ adds up to 2 in total, while the contribution at $l-m$ and $l+m+1$ for any $m\geq 3$ cancels out. The former distinguishes $H_p = 2H_q$ from any other cases.

For the same reason, shifting the spot volatility estimation window outward by one time interval (shown in Figure~\ref{fig:base-estimators}) can completely eliminate this distribution, so the correlation between different scales become really negligible.

\subsubsection{The dependent noise setting}
Although the closed-form expression of the covariance between different scales is difficult to derive, a multi-scale alternative of Lemma~\ref{lem:app-all-observation-noise-N4} (dropping terms with $\theta_B$ and $\theta_D$) can be used as an algorithm to explicitly calculate the covariance due to noise when the noise is dependent. The idea is very simple. First, for each given pair of $k$ and $l$, the contribution can be calculated with this multi-scale and dependent alternative of Lemma~\ref{lem:app-all-observation-noise-N4}. Second, suppose we have a fixed $k$, and for the summation over $l$, we need to consider all $l$'s that may have potential contribution to the final result. That is, if the dependent level of noise is $\tilde{q}$, we need consider the following $l$'s:
\begin{equation}
l \in \{
k-(k_p+1)H_p-\tilde{q}-(k_q+2)H_q,
\dotsc,
k+(k_p+2)H_p+\tilde{q}+(k_q+1)H_p
\}.
\end{equation}
Third, the summation over $k$ is substituted by simply multiplying $n$. Finally, the result is normalized by $k_p H_p^2 \Delta_n$ and $k_q H_q^2 \Delta_n$. The code has been implemented and utilized in the simulation study.

\section{Proof of the main results}\label{app:main-results}
\subsection{Preliminary results}\label{app:preliminary}
We begin with some preliminary results that will be used in the proof of the main theorems. The following lemma concerns the error distribution of the ``oracle'' leverage effect estimator.


\begin{lemma}\label{lem:err-oracle-leverage}
Suppose there is an interval $[s, t)$ with $t-s \to 0$. We have
\begin{equation}
\E\left[\left.
\left(
\left(X_{t} - X_{s}\right)\left(\sigma_{t}^{2} - \sigma_{s}^{2}\right)
- \int_{s}^{t} 2\sigma_r^{2} f_r \ud r
\right)^{2}
\right| \filt_{s}
\right]
=
4\sigma_{s}^{4} \left(2f_{s}^{2} + g_{s}^{2}\right) (t-s)^{2}
+ O_p\left((t-s)^{5/2}\right).
\end{equation}
\end{lemma}


\begin{proof}
First, notice that $\ud \langle X,\sigma^2 \rangle_r = 2\sigma_r^2 f_r$ and
\begin{equation}
\left(X_{t} - X_{s}\right)\left(\sigma_{t}^{2} - \sigma_{s}^{2}\right)
=
\int_s^t (\sigma_r^2 - \sigma_s^2) \ud X_r
+ \int_s^t (X_r - X_s) \ud \sigma_r^2
+ \int_s^t \ud \langle X, \sigma^2 \rangle_r.
\end{equation}
Therefore, according the It\^{o} isometry, we have
\begin{equation}
\begin{aligned}
&
\E\left[\left.
\left(
\left(X_{t} - X_{s}\right)\left(\sigma_{t}^{2} - \sigma_{s}^{2}\right)
- \int_{s}^{t} 2\sigma_r^{2} f_r \ud r
\right)^{2}
\right| \filt_{s}
\right] \\
&=
\E\left[\left.
\left(
\int_s^t (\sigma_r^2 - \sigma_s^2) \ud X_r
+ \int_s^t (X_r - X_s) \ud \sigma_r^2
\right)^{2}
\right| \filt_{s}
\right] \\
&=
\E\Biggl[
\int_s^t (\sigma_r^2 - \sigma_s^2)^2 \ud \langle X, X \rangle_r
+ \int_s^t (X_r - X_s)^2 \ud \langle \sigma^2, \sigma^2 \rangle_r \\
&\qquad \qquad \qquad
+ 2 \int_s^t (\sigma_r^2 - \sigma_s^2) (X_r - X_s) \ud \langle X, \sigma^2 \rangle_r
\Big| \filt_{s}
\Biggr].
\end{aligned}
\end{equation}
For simplicity, denote $\partial \langle A, B \rangle_t = \frac{\ud \langle A, B \rangle_r}{\ud r}|_{r=t}$ for processes $A$ and $B$. Because
\begin{align}
(X_r - X_s)^2
&= \partial \langle X, X \rangle_s (r-s) + O_p((r-s)^{3/2}), \\
(\sigma_r^2 - \sigma_s^2)^2
&= \partial \langle \sigma^2, \sigma^2 \rangle_s (r-s) + O_p((r-s)^{3/2}), \\
(\sigma_r^2 - \sigma_s^2) (X_r - X_s)
&= \partial \langle X, \sigma^2 \rangle_s (r-s) + O_p((r-s)^{3/2}),
\end{align}
the target term can be simplified as
\begin{equation}
\begin{aligned}
&
\E\Biggl[
\int_s^t \partial \langle \sigma^2, \sigma^2 \rangle_s \partial \langle X, X \rangle_s (r-s) \ud r
+ \int_s^t \partial \langle X, X \rangle_s \partial \langle \sigma^2, \sigma^2 \rangle_s (r-s) \ud r \\
&\qquad \qquad
+ 2 \int_s^t \partial \langle X, \sigma^2 \rangle_s \partial \langle X, \sigma^2 \rangle_s (r-s) \ud r
\Big| \filt_{s}
\Biggr]
+ O_p\left((t-s)^{5/2}\right) \\
&=
\Bigl[
\partial \langle X, X \rangle_s \partial \langle \sigma^2, \sigma^2 \rangle_s
+ \left(\partial \langle X, \sigma^2 \rangle_s\right)^2
\Bigr] (t-s)^2
+ O_p\left((t-s)^{5/2}\right) \\
&=
4\sigma_{s}^{4} \left(2f_{s}^{2} + g_{s}^{2}\right) (t-s)^{2}
+ O_p\left((t-s)^{5/2}\right).
\end{aligned}
\end{equation}
This completes the proof of Lemma~\ref{lem:err-oracle-leverage}.
\end{proof}


The following lemma is about the expectation of the overlapping terms in the integrals of the increments of the process and the volatility. The specific form is induced by the decomposition $(X_b - X_a)^2 = \int_a^b 2(X_r - X_a) \ud X_r + \sigma_r^2 \ud r$.


\begin{lemma}\label{lem:overlap-expectation}
Suppose there are two intervals $[v, s)$ and $[u, t)$, where $v < s$ and $u < t$, and $d = (s-v)\lor(t-u) \to 0$. In the following two situations, we have:
\begin{enumerate}[label=(\alph*)]
\item If $v \leq u < s \leq t$, then the overlapping time interval is $[s, u)$, and
\begin{align}
&\E\left[\left.
    \left( \int_{v}^{s} (X_r - X_v) \ud X_r \right)
    \left( \int_{u}^{t} (X_r - X_u) \ud X_r \right)
\right| \filt_v \right]
=
\frac{1}{2}\sigma_v^4 (s-u)^2 + O_p(d^{5/2}), \\
&\E\left[\left.
    \left( \int_{v}^{s} (\sigma_r^2 - \sigma_v^2) \ud r \right)
    \left( \int_{u}^{t} (\sigma_r^2 - \sigma_u^2) \ud r \right)
\right| \filt_v \right]
=
\frac{1}{3} \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=v} (s-u)^3 + O_p(d^{7/2}).
\end{align}

\item If $v \leq u < t \leq s$, then the overlapping time interval is $[u, t)$, and
\begin{align}
&\E\left[\left.
    \left( \int_{v}^{s} (X_r - X_v) \ud X_r \right)
    \left( \int_{u}^{t} (X_r - X_u) \ud X_r \right)
\right| \filt_v \right]
=
\frac{1}{2}\sigma_v^4 (t-u)^2 + O_p(d^{5/2}), \\
&\E\left[\left.
    \left( \int_{v}^{s} (\sigma_r^2 - \sigma_v^2) \ud r \right)
    \left( \int_{u}^{t} (\sigma_r^2 - \sigma_u^2) \ud r \right)
\right| \filt_v \right]
=
\frac{1}{3} \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=v} (t-u)^3 + O_p(d^{7/2}).
\end{align}
\end{enumerate}
\end{lemma}

\begin{proof}
For $a < b$, according to the Burkholder-Davis-Gundy inequality, there exists positive constant $C_1$ such that
\begin{equation}
\E \Biggl[\left.
    \sup_{a \leq r \leq b} | X_r - X_a |
\right| \filt_a \Biggr]
\leq
C_1
\E \Biggl[\left.
    \left( \int_a^b \sigma_r^2 \ud r \right)^{1/2}
\right| \filt_a \Biggr]
\leq
C_1 \sigma_+ (b-a)^{1/2}.
\end{equation}
Here the impact of drift term is $O_p(b-a)$, so it is ignored. Therefore, we have
\begin{equation}
\E \Biggl[\left.
    \Bigl| \int_a^b (X_r - X_a) \mu_r \ud r \Bigr|
\right| \filt_a \Biggr]
\leq
C_1 \sigma_+ \mu_+ (b-a)^{3/2},
\end{equation}
where $\sigma_+$ and $\mu_+$ are some local upper bounds of $|\sigma_r|$ and $|\mu_r|$. Therefore,
\begin{equation}
\E \Biggl[\left.
    \int_a^b (X_r - X_a) \ud X_r
\right| \filt_a \Biggr]
=
\E \Biggl[\left.
    \int_a^b (X_r - X_a) \mu_r \ud r
\right| \filt_a \Biggr]
=
O_p \left( (b-a)^{3/2} \right).
\end{equation}
Obviously, $\E [X_b - X_a|\filt_a] = O_p(b-a)$. According to the It\^o isometry, we also have
\begin{equation}
\E \Biggl[\left.
    (X_b - X_a) \int_a^b (X_r - X_a) \ud X_r
\right| \filt_a \Biggr]
=
\E \Biggl[\left.
    \int_a^b (X_r - X_a) \sigma_r^2 \ud r
\right| \filt_a \Biggr]
=
O_p \left( (b-a)^{3/2} \right).
\end{equation}
For the first equality in (a), decompose the integral as
\begin{align}
\int_v^s (X_r - X_v) \ud X_r
&=
\int_v^s (X_r - X_v) \ud X_r + (X_u - X_v) (X_s - X_u) + \int_u^s (X_r - X_u) \ud X_r, \\
\int_u^t (X_r - X_u) \ud X_r
&=
\int_u^s (X_r - X_u) \ud X_r + (X_s - X_u) (X_t - X_s) + \int_s^t (X_r - X_s) \ud X_r.
\end{align}
By utilizing the nested property $\E[\cdot|\filt_v] = \E[\E(\E(\cdot|\filt_s)|\filt_u)|\filt_v]$ and applying the previous results, one can verify that the only dominant term turns out to be
\begin{equation}
\begin{aligned}
\E \Biggl[\left.
    \left(\int_u^s (X_r - X_u) \ud X_r\right)^2
\right| \filt_v \Biggr]
&=
\E \Biggl[\left.
    \int_u^s (X_r - X_u)^2 \sigma_r^2 \ud r
\right| \filt_v \Biggr] \\
&=
\sigma_v^4 \int_u^s (r-u) \ud r + O_p\left((s-u)^{5/2}\right) \\
&=
\frac{1}{2}\sigma_v^4 (s-u)^2 + O_p(d^{5/2}),
\end{aligned}
\end{equation}
and all other terms are $O_p(d^{5/2})$. The rest of the proof is similar after utilizing integral by parts:
\begin{equation}
\int_a^b (\sigma_r^2 - \sigma_a^2) \ud r
=
-\int_a^b (\sigma_r^2 - \sigma_b^2) \ud (b - r)
=
\int_a^b (b-r) \ud \sigma_r^2.
\end{equation}
This completes the proof.
\end{proof}


The following lemma is induced by the structure of multi-scale grids. Without loss of generality, we consider grids of two scales, with intervals being $1$ for the larger scale and $l \in (0, 1)$ for the smaller one. For a given larger scale interval, the grids of smaller scale partition the interval into several subintervals, with their lengths denoted as $(\alpha_1, \dotsc, \alpha_p)$. Define $\alpha_1$ as a uniformly distributed random variable on $(0, l]$, so that $p$ is also a random variable related to $\alpha_1$ and $l$. The parameter of interest is the summation of $k$th powers of $\alpha_i$'s as $S_k = S_k(\alpha_1, l) = \sum_{i=1}^{p} \alpha_i^k$, and its expectation with respect to $\alpha_1 \sim \unif (0, l]$ is discussed in the following lemma.
\begin{lemma}\label{lem:grid-integral}
For any integer $k \geq 1$, we have
\begin{equation}
\E_{\alpha_1\sim\unif(0,l]}\Bigl[ S_k (\alpha_1, l) \Bigr]
=
l^{k-1} \left(1 - \frac{k-1}{k+1} l \right)
=
l^{k-1} - \frac{k-1}{k+1} l^k.
\end{equation}
\end{lemma}


\begin{proof}
It is equivalent to prove that
\begin{equation}\label{eq:grid-integral-I}
I(l)
= \int_0^l S_k (\alpha_1, l) \ud \alpha_1
= l^k - \frac{k-1}{k+1} l^{k+1}.
\end{equation}
Denote $(\alpha_1, \alpha_2, \dotsc, \alpha_p) = (x, a_1, \dotsc, a_m)$, where $m = \lceil (1-x) / l \rceil = p - 1$, $x = \alpha_1 \in (0, l]$, $a_1 = \dotsb, = a_{m-1} = l$, and $a_m = 1-x-(m-1)l$. The summation can be rewritten as
\begin{equation}
S_k(\alpha_1, l) = x^k + T_k(x, l), \quad \text{where } T_k(x, l) = \sum_{i=1}^m a_i^k,
\end{equation}
and the target integral is
\begin{equation}
I(l) = \frac{1}{k+1}l^{k+1} + J(l), \quad \text{where } J(l) = \int_0^l T_k(x, l) \ud x.
\end{equation}
Therefore, it is further equivalent to prove that
\begin{equation}\label{eq:grid-integral-J}
J(l)
= \int_0^l T_k(x, l) \ud x
= l^k - \frac{k}{k+1} l^{k+1}.
\end{equation}
It is easy to see that $\lim_{l\to 0^+} J(l) = 0$, which is consistent with Equation~\eqref{eq:grid-integral-J}. According to the Leibniz's rule, the derivative of $J(l)$ is
\begin{equation}\label{eq:grid-integral-J-derivative}
\frac{\ud}{\ud l} J(l)
= T_k(l, l) + \int_0^l \frac{\partial}{\partial l} T_k(x, l) \ud x,
\end{equation}
so we only need to prove that for any $l \in (0, 1)$,
\begin{equation}\label{eq:grid-integral-J-derivative-target}
\frac{\ud}{\ud l} J(l)
= k l^{k-1} - k l^k.
\end{equation}
For the first term in Equation~\eqref{eq:grid-integral-J-derivative}, we have
\begin{equation}
T_k (l, l) = (m-1)l^k + a_m^k.
\end{equation}
For the second term in Equation~\eqref{eq:grid-integral-J-derivative}, we need to derive the detailed form of $\frac{\partial}{\partial l} T_k(x, l)$. For a given $a_m \in (0, l]$, consider an arbitrarily small $\Delta l > 0$, so that $m$ remains unchanged. In this case, $a_i = l \to l + \Delta l$, $\forall i=1,\dotsc, m-1$; while $a_m \to a_m - (m-1)l$. Therefore, the corresponding change in $T_k(x, l)$ is
\begin{equation}
\begin{aligned}
\Delta T_k(x, l)
&=
T_k(x, l+\Delta l) - T_k(x, l) \\
&=
(m-1)\Bigl[ (l+\Delta l)^k - l^k \Bigr] + \Bigl[\left( a_m - (m-1)\Delta l \right)^k - a_m^k\Bigr] \\
&=
(m-1) k (l^{k-1} - a_m^{k-1}) \Delta l + o(\Delta l),
\end{aligned}
\end{equation}
so we have
\begin{equation}\label{eq:grid-integral-derivative-Tk}
\frac{\partial}{\partial l} T_k(x, l)
= (m-1) k \left(l^{k-1} - a_m^{k-1}\right).
\end{equation}
Next, we need to consider the specific value of $a_m$ as $x$ ranges from $0$ to $l$. In fact, for a given $l$, there exists $r = \lceil 1/l \rceil$ and $x_0 = 1-(r-1)l$, such that for $x \in (0, l]$, we have
\begin{equation}
m = \begin{cases}
    r, & \text{if } 0 < x < x_0, \\
    r - 1, & \text{if } x_0 \leq x \leq l, 
\end{cases}
\end{equation}
\begin{equation}
a_m = \begin{cases}
    - x + x_0, & \text{if } 0 < x < x_0, \\
    - x + x_0 + l, & \text{if } x_0 \leq x \leq l, 
\end{cases}
\end{equation}
\begin{equation}
\frac{\partial T_k}{\partial l} = \begin{cases} 
    (r - 1) k \left(l^{k-1} - (x_0 - x)^{k-1}\right), & \text{if } 0 < x < x_0, \\
    (r - 2) k \left(l^{k-1} - (x_0 + l - x)^{k-1}\right), & \text{if } x_0 \leq x \leq l. 
\end{cases}
\end{equation}
As a result, the first term in Equation~\eqref{eq:grid-integral-J-derivative} is
\begin{equation}
T_k (l, l) =  (r-2) l^k + x_0^k,
\end{equation}
and the second term in Equation~\eqref{eq:grid-integral-J-derivative} is
\begin{equation}
\begin{aligned}
\int_0^l \frac{\partial}{\partial l} T_k(x, l) \ud x
&=
\int_0^{x_0} \frac{\partial}{\partial l} T_k(x, l) \ud x
+ \int_{x_0}^l \frac{\partial}{\partial l} T_k(x, l) \ud x \\
&=
(r-1) k \Bigl[ x_0 l^{k-1} - \frac{1}{k} x_0^k \Bigr]
+ (r-2) k \Bigl[ (l-x_0)l^{k-1} - \frac{1}{k} l^k + \frac{1}{k} x_0^k \Bigr] \\
&=
(r-2)(k-1) l^k + kx_0 l^{k-1} - x_0^k.
\end{aligned}
\end{equation}
Therefore, the derivative of $J(l)$ is
\begin{equation}
\begin{aligned}
\frac{\ud}{\ud l} J(l)
&=
T_k(l, l) + \int_0^l \frac{\partial}{\partial l} T_k(x, l) \ud x \\
&=
(r-2) l^k + x_0^k
+ (r-2)(k-1) l^k + kx_0 l^{k-1} - x_0^k \\
&=
(r-2) kl^k + k [1-(r-1)l] l^{k-1} \\
&=
kl^{k-1} - kl^k,
\end{aligned}
\end{equation}
which is the same as Equation~\eqref{eq:grid-integral-J-derivative-target}. This completes the proof of Lemma~\ref{lem:grid-integral}.
\end{proof}





\subsection{Proof of Theorem~\ref{thm:SALE-clt-noisefree}}\label{app:SALE-clt-noisefree}
We use Jacod's central limit theorem for semimartingales \citep{jacod1997ContinuousConditionalGaussian} in the form of Theorem~2.6 in \cite{podolskij2010UnderstandingLimitTheorems}.

Recall that the noise-free SALE estimator includes a double summation over subsamples and observation indices within each subsample. This can be reorganized into a single summation, where each increment term represents a local leverage effect estimator at scale $H_n$, and consecutive terms correspond to moving forward by a time step of $\Delta_n$. Specifically, we have
\begin{equation}
\begin{aligned}
[ X, \sigma^{2} ]^{(H_n)}_T
&=
\frac{1}{H_n} \sum_{h=1}^{H_n} [ X, \sigma^{2} ]^{(H_n, h)}_T
\\ &=
\frac{1}{H_n} \sum_{h=1}^{H_n}
\frac{1}{k_{n}H_{n}\Delta_{n}}
\sum_{i\in I_{H_n,h}} (\Delta_{H_n} X_{i_{h}}) \left[
\sum_{j\in I^{+}(i)} (\Delta_{H_n} X_{j_{h}})^{2} - \sum_{j\in I^{-}(i)}(\Delta_{H_n} X_{j_{h}})^{2}
\right]
\\ &=
\frac{1}{H_n}
\sum_{i=(k_n+1)H_n}^{n-(k_n+2)H_n} (\Delta_{H_n} X_{i}) 
\Bigl(
\widehat{\sigma}_{H_n, i+}^2 - \widehat{\sigma}_{H_n, i-}^2
\Bigr)
\\ &=
\frac{1}{H_n}
\sum_{i=(k_n+1)H_n}^{n-(k_n+2)H_n} V_{H_n, i}.
\end{aligned}
\end{equation}
Here, the increment term at time $i\Delta$ at scale $H_n$ is denoted as
\begin{equation}
V_{H_n, i} = (\Delta_{H_n} X_{i}) 
\Bigl(
\widehat{\sigma}_{H_n, i+}^2 - \widehat{\sigma}_{H_n, i-}^2
\Bigr),
\end{equation}
where $\widehat{\sigma}_{H_n, i+}^2$ and $\widehat{\sigma}_{H_n, i-}^2$ are right-side and left-side spot volatility estimators respectively. Denote $S^+ = \{j - i | j \in I^+(i)\} = \{2, \dotsc, k_n+1\}$, $S^- = \{j - i | j \in I^-(i)\} = \{-k_n-1, \dotsc, -2\}$, and the spot volatility estimators can be written as
\begin{align}
\widehat{\sigma}_{H_n, i+}^2
&=
\frac{1}{k_n H_n \Delta_n}
\sum_{j\in S^+} (\Delta_{H_n} X_{i+jH_n})^{2}, \\
\widehat{\sigma}_{H_n, i-}^2
&=
\frac{1}{k_n H_n \Delta_n}
\sum_{j\in S^-} (\Delta_{H_n} X_{i+jH_n})^{2}.
\end{align}

In order to establish the central limit theorem, we need to study the behavior of its error process, which is defined by $u_n ([ X, \sigma^{2} ]^{(H_n)}_T - \langle X, \sigma^{2} \rangle_T )$ with a normalizing positive number sequence $\{u_n\}$, for which we can take $u_n = \sqrt{k_n \land (k_n H_n \Delta_n)^{-1}}$. Since the estimator is composed of overlapping increment terms, we need to consider the covariance between increment terms within some predefined large blocks. Specifically, we divide the timeline into large blocks of size $L = (K+2k_{n}+3)H_{n}\Delta_{n}$. The time period for the $\nu$th block is $[L\nu, L\nu + L)$, where $\nu = 0, 1, \dotsc, \lfloor T/L \rfloor - 1$. Here, $K$ is an appropriately selected integer that increases with $n$. The division of the $\nu$th large block is illustrated in Figure~\ref{fig:block}.

