\draw[-latex] (-0.5, 0.5) -- (-4, 0.5);
\draw[-latex] (3.5, 0.5) -- (7, 0.5);
\node at (1.5, 0.5) {\footnotesize{$L = (K+2k_{n}+3)H_{n}\Delta_{n}$}};
\foreach \xStart/\xEnd in {-2/4.5, 9/10.5} {
    \fill [fill=blue, opacity=0.2] (\xStart,0.05) -- (\xStart, -0.05) -- (\xEnd, -0.05) -- (\xEnd, 0.05) -- cycle;
}
\foreach \xStart/\xEnd in {-4.5/-2, 4.5/9} {
    \fill [fill=red, opacity=0.2] (\xStart,0.05) -- (\xStart, -0.05) -- (\xEnd, -0.05) -- (\xEnd, 0.05) -- cycle;
}
\end{tikzpicture}
\end{center}
\caption{The block division in the $\nu$th large block}
\label{fig:block}
\end{figure}

In the $\nu$th large block, the blue segment in the middle corresponds to the time period $[L\nu+(k_n+1)H_n\Delta_n, L\nu+(K+k_n+1)H_n\Delta_n)$, with a length of $KH_n\Delta_n$. The red segments on both sides are $(k_n+1)H_n\Delta_n$ and $(k_n+2)H_n\Delta_n$ long, respectively. Within this large block, we only consider the $KH_n$ increment terms $V_i$'s for which the time points $i\Delta_n$ lie within the left-closed, right-open interval shown by the blue segment, and their indices are $J(\nu) = \{L\nu/\Delta_n+(k_n+1)H_n, \dotsc, L\nu/\Delta_n+(K+k_n+1)H_n-1\}$. The reason for this division is that all estimates contained in these $V_i$'s are within the time period $[L\nu, L\nu + L)$ of the $\nu$th large block, meaning they are $\filt_{L(\nu+1)}$-measurable. This measurability is crucial for applying the central limit theorem. Furthermore, to ensure the selection of large blocks is appropriate, we need to ensure that $K$ satisfies two conditions. First, $K/k_n \to \infty$ as $n \to \infty$, so that excluding the $(2k_n+3)H_n$ increment terms $V_i$'s corresponding to the red segments on both sides does not affect the results. Second, $K H_n \Delta_n \to 0$ as $n \to \infty$, ensuring that the time span of each large block is sufficiently short, allowing the use of a local constant approximation for the parameters.

With the large block notations, the SALE estimator is now
\begin{equation}
[ X, \sigma^{2} ]^{(H_n)}_T
=
\frac{1}{H_n}
\sum_{\nu=0}^{\lfloor T/L \rfloor - 1}
\sum_{i\in J(\nu)} V_{H_n, i}
+ \text{(edge terms)},
\end{equation}
where edge terms include the increment terms corresponding to the red segments on both sides of the large block, and also include the increment terms beyond the last large block at the end of the day. Of course, in both cases, these edge terms do not affect the results. If we omit the edge terms, the normalized error process can be written as
\begin{equation}
u_n \Bigl([ X, \sigma^{2} ]^{(H_n)}_T - \langle X, \sigma^{2} \rangle_T \Bigr)
=
\sum_{\nu=0}^{\lfloor T/L \rfloor - 1} U_\nu,
\end{equation}
where the error term in the $\nu$th large block is
\begin{equation}
\begin{aligned}
U_\nu
&=
u_n
\left(
\frac{1}{H_n} \sum_{i\in J(\nu)} V_{H_n, i}
- \int_{L\nu}^{L(\nu+1)} \ud \langle X, \sigma^2 \rangle_t
\right)
- \text{(edge terms)}
\\ &=
\frac{u_n}{H_n}
\sum_{i\in J(\nu)}
\left(
V_{H_n, i}
- \int_{i\Delta_n}^{(i+H_n)\Delta_n} \ud \langle X, \sigma^2 \rangle_t
\right)
\\ &=
U_{\nu, 1} + U_{\nu, 2}.
\end{aligned}
\end{equation}
Here, the edge terms are ignored in the second line, and we define
\begin{align}
U_{\nu, 1} &= \frac{u_n}{H_n} \sum_{i\in J(\nu)} \Bigl( V_{H_n, i} - (\Delta_{H_n} X_i) (\Delta_{H_n} \sigma_i^2) \Bigr), \\
U_{\nu, 2} &= \frac{u_n}{H_n} \sum_{i\in J(\nu)} \left( (\Delta_{H_n} X_i) (\Delta_{H_n} \sigma_i^2) - \int_{i\Delta_n}^{(i+H_n)\Delta_n} \ud \langle X, \sigma^2 \rangle_t \right).
\end{align}
Intuitively, $U_{\nu, 1}$ is the error due to spot volatility estimation, while $U_{\nu, 2}$ is the local error of ``oracle'' leverage estimation. For the error of spot volatility estimation, notice that
\begin{equation}
V_{H_n, i} - (\Delta_{H_n} X_i) (\Delta_{H_n} \sigma_i^2)
=
(\Delta_{H_n} X_i)
\Bigl(
(\widehat{\sigma}_{H_n, i+}^2 - \sigma_{i+H_n}^2)
- (\widehat{\sigma}_{H_n, i-}^2 - \sigma_{i}^2)
\Bigr),
\end{equation}
so we define the error terms of spot volatility estimation as
\begin{equation}\label{eq:error-spot}
e_{H_n, i+} = \widehat{\sigma}_{H_n, i+}^2 - \sigma_{i+H_n}^2, \quad
e_{H_n, i-} = \widehat{\sigma}_{H_n, i-}^2 - \sigma_{i}^2,
\end{equation}
for $i \in J(\nu)$, and we have
\begin{equation}
U_{\nu, 1}
=
\frac{u_n}{H_n} \sum_{i\in J(\nu)}(\Delta_{H_n} X_i) (e_{H_n, i+} - e_{H_n, i-}).
\end{equation}
For these error terms, we have the following lemma.

\begin{lemma}\label{lem:err-spot-volatility}
Suppose that $i, j \in J(\nu)$ and $|i-j| < H_n$. We have
\begin{equation}
\begin{aligned}
\E \Bigl[
e_{H_n, i\pm} e_{H_n, j\pm} 
\Big| \filt_{L\nu} \Bigr]
&=
\left(\frac{1}{k_n}\right) \cdot 2 \left[ \left( \frac{|i-j|}{H_n} \right)^2 + \left( 1 - \frac{|i-j|}{H_n} \right)^2 \right] \sigma_\nu^4 
\\ &\qquad \qquad
+ (k_n H_n \Delta_n) \cdot \frac{1}{3} \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=L\nu} + o_p(k_n^{-1} + k_n H_n \Delta_n),
\\
\E \Bigl[
e_{H_n, i\pm} e_{H_n, j\mp} 
\Big| \filt_{L\nu} \Bigr]
&=
o_p(k_n^{-1} + k_n H_n \Delta_n).
\end{aligned}
\end{equation}
Moreover, with $u_n = \sqrt{k_n \land (k_n H_n \Delta_n)^{-1}}$, we assert that, asymptotically and conditioned on $\filt_{L\nu}$, the expressions $u_n e_{H_n, i+}$ and $u_n e_{H_n, i-}$ are independent of each other and $\filt$, normally distributed, and have mean zero.
\end{lemma}

\begin{proof}
To begin with, denote
\begin{equation}
\begin{aligned}
e_{H_n, i+}
& = (\widehat{\sigma}_{H_n, i+}^2 - \sigma_{i+2H_n}^2) + (\sigma_{i+2H_n}^2 - \sigma_{i+H_n}^2)
= \tilde{e}_{H_n, i+} + \Delta_{H_n} \sigma_{i+H_n}^2, \\
e_{H_n, i-}
& = (\widehat{\sigma}_{H_n, i-}^2 - \sigma_{i-H_n}^2) + (\sigma_{i-H_n}^2 - \sigma_{i}^2)
= \tilde{e}_{H_n, i-} + \Delta_{H_n} \sigma_{i-H_n}^2.
\end{aligned}
\end{equation}
As we will see, $\tilde{e}_{H_n, i\pm}$ are the dominant terms in the expressions. Notice that
\begin{equation}
\begin{aligned}
\tilde{e}_{H_n, i+}
&=
\frac{1}{k_n H_n \Delta_n} \sum_{k\in S^+}
\int_{(i+kH_n)\Delta_n}^{(i+(k+1)H_n)\Delta_n}
2(X_r - X_{i+kH_n}) \ud X_r
+ (\sigma_r^2 - \sigma_{i+2H_n}^2) \ud r
\\ &=
\frac{1}{k_n H_n \Delta_n}
\Biggl[
\Biggl(
\sum_{k\in S^+}
\int_{(i+kH_n)\Delta_n}^{(i+(k+1)H_n)\Delta_n} 2(X_r - X_{i+kH_n}) \ud X_r
\Biggr)
\\ &\qquad \qquad \qquad \qquad \qquad \qquad
+ \int_{(i+2H_n)\Delta_n}^{(i+(k_n+2)H_n)\Delta_n} (\sigma_r^2 - \sigma_{i+2H_n}^2) \ud r
\Biggr]
\\ &=
\frac{1}{k_n H_n \Delta_n}
\Biggl[
\Biggl(
\sum_{k\in S^+} \xi_{i, k}
\Biggr)
+ \eta_{i}
\Biggr].
\end{aligned}
\end{equation}
Without loss of generality, we take $0 \leq j < H_n$, we have
\begin{equation}
\tilde{e}_{H_n, j+}
=
\frac{1}{k_n H_n \Delta_n}
\Biggl[
\Biggl(
\sum_{k\in S^+} \xi_{j, k}
\Biggr)
+ \eta_{j}
\Biggr].
\end{equation}
According to Lemma~\ref{lem:overlap-expectation}, we can see that, for valid indices, the non-trivial terms are
\begin{align}
\E \Bigl[
\xi_{i, k} \xi_{j, k}
\Big| \filt_{(i+kH_n)\Delta_n} \Bigr]
&=
2\sigma_{(i+kH_n)\Delta_n}^4 \left(\left(1 - \frac{j-i}{H_n}\right) H_n \Delta_n\right)^2
+
o_p(H_n^2 \Delta_n^2), \\
\E \Bigl[
\xi_{i, k+1} \xi_{j, k}
\Big| \filt_{(j+kH_n)\Delta_n} \Bigr]
&=
2\sigma_{(j+kH_n)\Delta_n}^4 \left(\left(\frac{j-i}{H_n}\right) H_n \Delta_n\right)^2
+
o_p(H_n^2 \Delta_n^2), \\
\E \Bigl[
\eta_{i} \eta_{j}
\Big| \filt_{(i+2H_n)\Delta_n} \Bigr]
&=
\frac{1}{3} \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=(i+2H_n)\Delta_n} (k_n H_n \Delta_n)^3 + o_p(k_n^3 H_n^3 \Delta_n^3).
\end{align}
As for the negligibility of cross terms such as $\E[\xi_{j, k} \eta_i | \filt_{(i+2H_n)\Delta_n}]$, we have
\begin{equation}
\begin{aligned}
&
\E\Bigl[\xi_{j, k} \eta_i \Big| \filt_{(i+2H_n)\Delta_n}\Bigr]
\\ &=
\E \Biggl[
\Biggl(
\int_{(j+kH_n)\Delta_n}^{(j+(k+1)H_n)\Delta_n} 2(X_r - X_{j+kH_n}) \ud X_r
\Biggr)
\\ &\qquad \qquad
\Biggl(
\int_{(i+2H_n)\Delta_n}^{(i+(k_n+2)H_n)\Delta_n} \Bigl[ (i+(k_n+2)H_n)\Delta_n - r \Bigr] \ud \sigma_r^2
\Biggr)
\Bigg| \filt_{(i+2H_n)\Delta_n} \Biggr]
\\ &\approx
\Bigl[ (i+(k_n+2)H_n)\Delta_n - (j+kH_n)\Delta_n \Bigr]
\left.\frac{\ud \langle X, \sigma^2 \rangle_t}{\ud t}\right|_{t=(i+2H_n)\Delta_n}
\\ &\qquad \qquad
\E \Biggl[
\int_{(j+kH_n)\Delta_n}^{(j+(k+1)H_n)\Delta_n \land (i+(k_n+2)H_n)\Delta_n}
2(X_r - X_{j+kH_n}) \ud r
\Bigg| \filt_{(i+2H_n)\Delta_n} \Biggr]
\\ &=
O_p(k_n H_n \Delta_n \cdot k_n H_n \Delta_n \cdot H_n \Delta_n)
\\ &=
O_p(k_n^2 H_n^3 \Delta_n^3).
\end{aligned}
\end{equation}
Therefore, we have
\begin{equation}
\begin{aligned}
\E \Bigl[
\tilde{e}_{H_n, i+} \tilde{e}_{H_n, j+}
\Big| \filt_{L\nu} \Bigr]
&=
\frac{1}{k_n^2 H_n^2 \Delta_n^2}
\E \Biggl[
\Biggl(\sum_{k\in S^+} \xi_{i, k} + \eta_i\Biggr)
\Biggl(\sum_{l\in S^+} \xi_{j, l} + \eta_j\Biggr)
\Bigg| \filt_{L\nu} \Biggr]
\\ &=
\left(\frac{1}{k_n}\right) \cdot 2 \left[ \left( \frac{j-i}{H_n} \right)^2 + \left( 1 - \frac{j-i}{H_n} \right)^2 \right] \sigma_\nu^4 
\\ &\qquad \qquad
+ (k_n H_n \Delta_n) \cdot \frac{1}{3} \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=L\nu} + o_p(k_n^{-1} + k_n H_n \Delta_n),
\end{aligned}
\end{equation}
On the other hand, because $\E[(\Delta_{H_n} \sigma_{i+H_n}^2)^2 | \filt_{(i+H_n)\Delta_n}] = O_p(H_n \Delta_n)$, we have
\begin{equation}
\begin{aligned}
\E \Bigl[
e_{H_n, i+} e_{H_n, j+}
\Big| \filt_{L\nu} \Bigr]
&=
\left(\frac{1}{k_n}\right) \cdot 2 \left[ \left( \frac{j-i}{H_n} \right)^2 + \left( 1 - \frac{j-i}{H_n} \right)^2 \right] \sigma_\nu^4 
\\ &\qquad \qquad
+ (k_n H_n \Delta_n) \cdot \frac{1}{3} \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=L\nu} + o_p(k_n^{-1} + k_n H_n \Delta_n),
\end{aligned}
\end{equation}
and similar results can be proved for $e_{H_n, i-}$ related terms. The remaining part of the lemma is easy to see under the local constant approximation.
\end{proof}


We need to verify some conditions on the error process to prove the central limit theorem.

\paragraph{Ucp convergence}
First, we need to prove
\begin{equation}\label{eq:SALE-clt-noisefree-ucp}
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1} \E[U_\nu | \filt_{L\nu}] \convucp 0,
\end{equation}
which is equivalent to
\begin{equation}
\sup_{t\in [0,T]}
\left| \sum_{\nu=0}^{\lfloor t/L \rfloor - 1} \E[U_\nu | \filt_{L\nu}] \right|
\convp 0,
\end{equation}
while the left-hand side is bounded by
\begin{equation}
\sup_{t\in [0,T]}
\left| \sum_{\nu=0}^{\lfloor t/L \rfloor - 1} \E[U_\nu | \filt_{L\nu}] \right|
\leq
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1} \Bigl| \E[ U_\nu | \filt_{L\nu} ] \Bigr|
\leq
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\Bigl(
\Bigl| \E[ U_{\nu, 1} | \filt_{L\nu} ] \Bigr|
+ \Bigl| \E[ U_{\nu, 2} | \filt_{L\nu} ] \Bigr|
\Bigr).
\end{equation}
According to Lemma~\ref{lem:err-spot-volatility}, we know that
\begin{equation}
\begin{aligned}
\E [ U_{\nu, 1} | \filt_{L\nu} ]
&=
\frac{u_n}{H_n}
\sum_{i\in J(\nu)}
\E \Bigl[ (\Delta_{H_n} X_i) (e_{H_n, i+} - e_{H_n, i-}) \Big| \filt_{L\nu} \Bigr]
\\ &=
\frac{1}{H_n}
\sum_{i\in J(\nu)}
\E\Bigl[\Delta_{H_n} X_i \Big| \filt_{L\nu}\Bigr]
\E\Bigl[u_n (e_{H_n, i+} - e_{H_n, i-}) \Big| \filt_{L\nu}\Bigr]
\\ &=
\frac{1}{H_n}
\sum_{i\in J(\nu)}
O_p(H_n \Delta_n) o_p(1)
=
o_p(K H_n \Delta_n).
\end{aligned}
\end{equation}
On the other hand, by Lemma~\ref{lem:err-oracle-leverage}, we have
\begin{equation}
\begin{aligned}
\Bigl| \E [ U_{\nu, 2} | \filt_{L\nu} ] \Bigr|
&\leq
\frac{u_n}{H_n}
\sum_{i\in J(\nu)}
\E \Biggl[ \Bigl| (\Delta_{H_n} X_i) (\Delta_{H_n} \sigma_i^2) - \int_{i\Delta_n}^{(i+H_n)\Delta_n} \ud \langle X, \sigma^2 \rangle_t \Bigr| \Bigg| \filt_{L\nu} \Biggr]
\\ &\leq
\frac{u_n}{H_n}
\sum_{i\in J(\nu)}
\sqrt{
\E \Biggl[ \Bigl( (\Delta_{H_n} X_i) (\Delta_{H_n} \sigma_i^2) - \int_{i\Delta_n}^{(i+H_n)\Delta_n} \ud \langle X, \sigma^2 \rangle_t \Bigr)^2 \Bigg| \filt_{L\nu} \Biggr]
}
\\ &=
\frac{u_n}{H_n}
\sum_{i\in J(\nu)}
O_p(H_n \Delta_n)
=
o_p(u_n K H_n \Delta_n).
\end{aligned}
\end{equation}
Therefore, we have
\begin{equation}
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\Bigl(
\Bigl| \E[ U_{\nu, 1} | \filt_{L\nu} ] \Bigr|
+ \Bigl| \E[ U_{\nu, 2} | \filt_{L\nu} ] \Bigr|
\Bigr)
=
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
o_p(K H_n \Delta_n)
+ o_p(u_n K H_n \Delta_n)
=
o_p(t),
\end{equation}
so the ucp convergence is verified.

\paragraph{Quadratic variation}
We need to prove
\begin{equation}\label{eq:SALE-clt-noisefree-qv}
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\Bigl(
    \E[U_\nu^2 | \filt_{L\nu}]
    - \E[U_\nu | \filt_{L\nu}]^2
\Bigr)
\convp
\int_0^t \zeta_s^2 \ud s,
\end{equation}
for some predictable process $(\zeta_s)_{s\geq 0}$. According to previous results, the only non-trivial term in the summand is obviously $\E[U_{\nu, 1}^2 | \filt_{L\nu}]$ here. By Lemma~\ref{lem:err-spot-volatility}, up to the highest order, we have
\begin{equation}\label{eq:SALE-clt-noisefree-qv-Uv1squared}
\begin{aligned}
&
\E[U_{\nu, 1}^2 | \filt_{L\nu}]
\\ &=
\frac{u_n^2}{H_n^2}
\sum_{i\in J(\nu)}
\sum_{j\in J(\nu)}
\E\Bigl[
(\Delta_{H_n} X_i)
(\Delta_{H_n} X_j)
\Big| \filt_{L\nu} \Bigr]
\E\Bigl[
(e_{H_n, i+} - e_{H_n, i-})
(e_{H_n, j+} - e_{H_n, j-})
\Big| \filt_{L\nu} \Bigr]
\\ &=
\frac{u_n^2}{H_n^2}
\sum_{i\in J(\nu)}
\sum_{j\in J(\nu), |i-j|<H_n}
\sigma_\nu^2 \left( 1 - \frac{|i-j|}{H_n} \right) H_n \Delta_n
\E\Bigl[
e_{H_n, i+} e_{H_n, j+} + e_{H_n, i-} e_{H_n, j-}
\Big| \filt_{L\nu} \Bigr]
\\ &=
\frac{u_n^2}{H_n^2}
\sum_{i\in J(\nu)}
\sum_{j\in J(\nu), |i-j|<H_n}
\sigma_\nu^2 \left( 1 - \frac{|i-j|}{H_n} \right) H_n \Delta_n
\\ &\qquad
2 \left\{
\frac{1}{k_n} \cdot 2 \left[ \left( \frac{|i-j|}{H_n} \right)^2 + \left( 1 - \frac{|i-j|}{H_n} \right)^2 \right] \sigma_\nu^4
+ k_n H_n \Delta_n \cdot \frac{1}{3} \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=L\nu}
\right\}
\\ &=
u_n^2
\left(
\frac{1}{k_n} \cdot \left(\frac{8}{3}+\frac{4}{3H_n^2}\right) \sigma_\nu^6 \cdot K H_n \Delta_n
+ k_n H_n \Delta_n \cdot \frac{2}{3} \sigma_\nu^2 \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=L\nu} \cdot K H_n \Delta_n
\right).
\end{aligned}
\end{equation}
Therefore, with $u_n = \sqrt{k_n \land (k_n H_n \Delta_n)^{-1}}$, we have
\begin{equation}
\begin{aligned}
&
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\Bigl(
    \E[U_\nu^2 | \filt_{L\nu}]
    - \E[U_\nu | \filt_{L\nu}]^2
\Bigr)
\\ &=
\frac{u_n^2}{k_n}
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\left(\frac{8}{3}+\frac{4}{3H_n^2}\right) \sigma_\nu^6 \cdot K H_n \Delta_n
+
u_n^2 k_n H_n \Delta_n
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\frac{2}{3} \sigma_\nu^2 \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=L\nu} \cdot K H_n \Delta_n
\\ &\convp
\frac{u_n^2}{k_n} \int_0^t \left(\frac{8}{3}+\frac{4}{3H_n^2}\right) \sigma_s^6 \ud s
+ u_n^2 k_n H_n \Delta_n \int_0^t \frac{2}{3} \sigma_s^2 \ud\langle\sigma^2, \sigma^2\rangle_s.
\end{aligned}
\end{equation}

\paragraph{Quadratic covariation}
We need to prove
\begin{equation}\label{eq:SALE-clt-noisefree-qcv}
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1} \E\Bigl[U_\nu (M_{L(\nu+1)} - M_{L\nu}) \Big| \filt_{L\nu}\Bigr] \convp 0,
\quad \forall M \in \{W, B, N\},
\end{equation}
where $(N_s)_{s\geq 0}$ is an arbitrary bounded $\filt_t$-martingale with $N_0 = 0$ and $\langle W, N\rangle = \langle B, N\rangle = 0$. As before, we omit $U_{\nu, 2}$ for its minor contribution, while for $U_{\nu, 1}$, we have
\begin{equation}
\begin{aligned}
&
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\E\Bigl[U_{\nu, 1} (M_{L(\nu+1)} - M_{L\nu}) \Big| \filt_{L\nu}\Bigr]
\\ &=
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\frac{1}{H_n}
\sum_{i \in J(\nu)}
\E\Bigl[
(\Delta_{H_n} X_i) (M_{L(\nu+1)} - M_{L\nu})
\Big| \filt_{L\nu} \Bigr]
\E\Bigl[
u_n (e_{H_n, i+} - e_{H_n, i-})
\Big| \filt_{L\nu} \Bigr]
\\ &=
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\frac{1}{H_n}
\sum_{i \in J(\nu)}
O_p(H_n \Delta_n) o_p(1)
=
o_p\left(\frac{t}{KH_n\Delta_n} \cdot \frac{1}{H_n} \cdot KH_n \cdot H_n\Delta_n \cdot 1\right)
\\ &=
o_p(t).
\end{aligned}
\end{equation}
This argument holds for any bounded $\filt_t$-martingale.

\paragraph{Lindeberg condition}
We need to prove
\begin{equation}\label{eq:SALE-clt-noisefree-lindeberg}
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1} \E\Bigl[U_\nu^2 1_{\{|U_\nu| > \epsilon\}} \Big| \filt_{L\nu}\Bigr] \convp 0,
\quad \forall \epsilon > 0.
\end{equation}
It is well-known that a sufficient condition for Equation~\eqref{eq:SALE-clt-noisefree-lindeberg} is
\begin{equation}
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1} \E\Bigl[|U_\nu|^{2+\delta} \Big| \filt_{L\nu}\Bigr] \convp 0,
\end{equation}
for any $\delta > 0$. We take $\delta=2$ for simplicity, and omit $U_{\nu, 2}$. The resulting expression is
\begin{equation}
\begin{aligned}
&
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1} \E[U_{\nu, 1}^{4} | \filt_{L\nu}]
\\ &=
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\frac{1}{H_n^4}
\E\Biggl[
\prod_{k=1}^4 \sum_{i_k \in J(\nu)}
(\Delta_{H_n} X_{i_k}) u_n (e_{H_n, i_k+} - e_{H_n, i_k-})
\Bigg| \filt_{L\nu} \Biggr]
\\ &=
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\frac{1}{H_n^4}
\sum_{i_1, i_2, i_3, i_4 \in J(\nu)}
\E\Biggl[
\prod_{k=1}^4
(\Delta_{H_n} X_{i_k})
\Bigg| \filt_{L\nu} \Biggr]
\E\Biggl[
\prod_{k=1}^4
u_n (e_{H_n, i_k+} - e_{H_n, i_k-})
\Bigg| \filt_{L\nu} \Biggr]
\\ &=
\sum_{\nu=0}^{\lfloor t/L \rfloor - 1}
\frac{1}{H_n^4}
O_p((KH_n)^2 H_n^2 \cdot H_n^2 \Delta_n^2 + (KH_n)^4 \cdot H_n^4 \Delta_n^4)
\\ &=
O_p(t KH_n\Delta_n)
= o_p(t).
\end{aligned}
\end{equation}

\paragraph{Final result}
Finally, combine Equation~\eqref{eq:SALE-clt-noisefree-ucp}, Equation~\eqref{eq:SALE-clt-noisefree-qv}, Equation~\eqref{eq:SALE-clt-noisefree-qcv}, and Equation~\eqref{eq:SALE-clt-noisefree-lindeberg}, we can prove Theorem~\ref{thm:SALE-clt-noisefree} with Jacod's semimartingale central limit theorem, and the result is
\begin{equation}\label{eq:SALE-clt-noisefree-convst}
\begin{aligned}
&
u_n \Bigl([ X, \sigma^{2} ]^{(H_n)}_t - \langle X, \sigma^{2} \rangle_t \Bigr)
\\ &\convst
\int_0^t
\sqrt{
\frac{u_n^2}{k_n} \left(\frac{8}{3}+\frac{4}{3H_n^2}\right) \sigma_s^6
+ u_n^2 k_n H_n \Delta_n \frac{2}{3} \sigma_s^2 \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_r}{\ud r}\right|_{r=s}
}
\ud W'_s,
\end{aligned}
\end{equation}
where $(W'_s)_{s\geq 0}$ is a Brownian motion defined on an extension of the original probability space and independent of $\filt$.

\subsection{Proof of Theorem~\ref{thm:SALE-clt-noisy}}\label{app:SALE-clt-noisy}
The proof follows directly from Proposition~\ref{prop:SALE-noise} and Theorem~\ref{thm:SALE-clt-noisefree}. First, according to Proposition~\ref{prop:SALE-noise}, we have
\begin{equation}
\Delta_n^{3/2} H_n^2 k_n \Bigl(\widehat{[X, \sigma^2]}^{(H_n)}_t - [X, \sigma^2]^{(H_n)}_t \Bigr)
\convd
\int_0^t \sqrt{\Phi} \ud B_t^{(H_n)},
\end{equation}
where $(B_t^{H_n})_{t\geq 0}$ is a Brownian motion independent of $\filt$. Next, we apply Jacod's central limit theorem to the normalized error process of noise-free SALE estimator, which is $u_n ([ X, \sigma^{2} ]^{(H_n)}_t - \langle X, \sigma^{2} \rangle_t )$, again, but for Equation~\eqref{eq:SALE-clt-noisefree-qcv}, we need to add that the convergence in probability holds for any bounded $\sigma(B_t^{(H_n)})$-martingale, which is trivial. Thus, we can prove that the stable convergence as shown in Equation~\eqref{eq:SALE-clt-noisefree-convst} still holds, but the corresponding probability space is the product space of $(\Omega, \filt, \pr)$ and the space of the Brownian motion $(B^{(H_n)}_t)_{t\geq 0}$. Thus, according to the property of stable convergence, $\Delta_n^{3/2} H_n^2 k_n (\widehat{[X, \sigma^2]}^{(H_n)}_t - [X, \sigma^2]^{(H_n)}_t )$ and $u_n ([ X, \sigma^{2} ]^{(H_n)}_t - \langle X, \sigma^{2} \rangle_t )$ converges jointly to the corresponding limit processes, so their summation also stably converges to the summation of these limit processes. After that, adjust the convergence rate and corresponding constant coefficients, and we complete the proof of Theorem~\ref{thm:SALE-clt-noisy}.

\subsection{Proof of Theorem~\ref{thm:SALE-clt-feasible}}\label{app:SALE-clt-feasible}
The theorem follows from a property of stable convergence. We explain the construction of $G_n^{(1)}$ and $G_n^{(2)}$ here. According to Theorem~3.4.1 of \cite{jacod2012DiscretizationProcesses}, or Example~3.2 of \cite{podolskij2010UnderstandingLimitTheorems}, it has been established that
\begin{equation}
\Delta_{n} \sum_{i=0}^{\lfloor t/\Delta_{n}\rfloor-1}
\left(
\frac{\Delta X_{i}}{\sqrt{\Delta_{n}}}
\right)^{6}
\convucp
15 \int_{0}^{t} \sigma_{s}^{6} \ud s,
\end{equation}
so we have
\begin{equation}
G_{n}^{(1)}
=
\frac{1}{15\Delta_{n}^{2}} \sum_{i=0}^{n-1} \left( \Delta X_{i} \right)^{6}
\convp
\int_{0}^{T} \sigma_{t}^{6} \ud t.
\end{equation}
According to Theorem~8.11 of \cite{aitsahalia2014HighFrequencyFinancialEconometrics}, or Theorem~2.6 of \cite{vetter2015EstimationIntegratedVolatility}, It has been proved that
\begin{equation}
\frac{1}{k_n} \sum_{i \in I}
\Biggl(
\frac{3}{2}\left(\widehat{\sigma}_{j+}^2-\widehat{\sigma}_{j-}^2\right)^2
-
\frac{1}{k_{n}^{2} \Delta_{n}^{2}} \sum_{j\in I^{\pm}(i)} \left( \Delta X_{j} \right)^{4}
\Biggr)
\convp
\langle\sigma^2, \sigma^2\rangle_{T},
\end{equation}
so we have
\begin{equation}
G_{n}^{(2)}
=
\frac{1}{k_{n}\Delta_{n}} \sum_{i \in I}
\left( \Delta X_{i} \right)^{2}
\Biggl(
\frac{3}{2}\left(\widehat{\sigma}_{j+}^2-\widehat{\sigma}_{j-}^2\right)^2
-
\frac{1}{k_{n}^{2} \Delta_{n}^{2}} \sum_{j\in I^{\pm}(i)} \left( \Delta X_{j} \right)^{4}
\Biggr) \\
\convp
\int_{0}^{T} \sigma_{t}^{2} \ud \langle \sigma^{2}, \sigma^{2} \rangle_{t}.
\end{equation}
The construction of $\widehat{G}_n^{(1)}$ and $\widehat{G}_n^{(2)}$ is based on the pre-averaging correction on $G_n^{(1)}$ and $G_n^{(2)}$.


\subsection{Proof of Proposition~\ref{prop:SALE-acov-noisefree}, Proposition~\ref{prop:adj-factor-asym}, Theorem~\ref{thm:MSLE-clt-noisefree}, and Theorem~\ref{thm:MSLE-clt-noisy}}\label{app:MSLE-clt}
The proof of Theorem~\ref{thm:MSLE-clt-noisefree} is similar as that of Theorem~\ref{thm:SALE-clt-noisefree}. We still use the large block techniques combined with local constant approximation, while we will only present the calculation of asymptotic variance, which is the essential part of the proof, and other tedious verification steps for conditions are omitted.

For each scale $H \in \{H_1, \dotsc, H_{M_n}\}$, the window length for spot volatility estimation (which is $k_n$ in the SALE estimator) varies, so we denote the window length for scale $H_p$ as $k_p$. We use the largest scale $H_{M_n}$ to define the large block in a similar way as in Section~\ref{app:SALE-clt-noisefree}, so that $L \asymp KH_{M_n}\Delta_n$ (here we write $X_n \asymp Y_n$ if $X_n/Y_n \to 1$ as $n \to \infty$), and the $\nu$th large block corresponds to the time interval $[L\nu, L\nu + L)$. After that, we denote the increment term at scale $H$ as $V_{H, i}$, and the index set for $V_{H, i}$ in the $\nu$th large block as $J_H(\nu)$. Although one can observe that $J_H(\nu)$ decreases as $H$ increases, we still have $|J_H(\nu)| \asymp KM_n$ for all $H \in \{H_1, \dotsc, H_{M_n}\}$. On the whole, it is tedious and meaningless to present the detailed operations of the edge terms and the differences of index sets between different scales, because it is only a way to construct some kind of conditional expectation and local approximation in the proof, so we will just stop here and focus on the important things.

With the large block notations, the MSLE estimator can be expressed as
\begin{equation}
[X, \sigma^2]_T^{\rm (MS)}
=
\sum_{p=1}^{M_n} w_p [X, \sigma^2]_T^{H_p}
=
\sum_{\nu=0}^{\lfloor T/L \rfloor - 1}
\sum_{p=1}^{M_n}
\frac{w_p}{H_p} \sum_{i\in J_{H_p}(\nu)} V_{H_p, i}
+ \text{(edge terms)}.
\end{equation}
Here, the increment term is defined as
\begin{equation}
V_{H_p, i} = (\Delta_{H_p} X_i)
\Bigl( \widehat{\sigma}_{H_p, i+}^2 - \widehat{\sigma}_{H_p, i-}^2 \Bigr),
\end{equation}
where the spot volatility estimators are
\begin{align}
\widehat{\sigma}_{H_p, i+}^2
&=
\frac{1}{k_n H_p \Delta_n}
\sum_{j\in S_{H_p}^+} (\Delta_{H_p} X_{i+jH_p})^{2}, \\
\widehat{\sigma}_{H_p, i-}^2
&=
\frac{1}{k_n H_p \Delta_n}
\sum_{j\in S_{H_p}^-} (\Delta_{H_p} X_{i+jH_p})^{2},
\end{align}
and the shifting index sets are $S_{H_p}^+ = \{2, \dotsc, k_p+1\}$ and $S_{H_p}^- = \{-k_p-1, \dotsc, -2\}$.
With a proper positive normalizing sequence $u_n$ (which is different from that in Section~\ref{app:SALE-clt-noisefree}), omitting the edge terms, the normalized error process of the MSLE estimator is
\begin{equation}
u_n \Bigl(
[X, \sigma^2]_T^{\rm (MS)} - \langle X, \sigma^2 \rangle_T
\Bigr)
=
\sum_{\nu=0}^{\lfloor T/L \rfloor - 1} \sum_{p=1}^{M_n} w_p U_{H_p, \nu},
\end{equation}
where the error term at scale $H$ in the $\nu$th large block is
\begin{equation}
U_{H_p, \nu}
=
\frac{u_n}{H_p} \sum_{i\in J_{H_p}(\nu)}
\left(
V_{H_p, i} - \int_{i\Delta_n}^{(i+H_p)\Delta_n} \ud \langle X, \sigma^2 \rangle_t
\right)
=
U_{H_p, \nu, 1} + U_{H_p, \nu, 2}.
\end{equation}
Here, we denote the error caused by spot volatility estimation and by the discretization of quadratic covariation as
\begin{align}
U_{H_p, \nu, 1}
&=
\frac{u_n}{H_p} \sum_{i\in J_{H_p}(\nu)}
\Bigl(
V_{H_p, i} - (\Delta_{H_p} X_i) (\Delta_{H_p} \sigma_i^2)
\Bigr), \\
U_{H_p, \nu, 2}
&=
\frac{u_n}{H_p} \sum_{i\in J_{H_p}(\nu)}
\left(
(\Delta_{H_p} X_i) (\Delta_{H_p} \sigma_i^2)
- \int_{i\Delta_n}^{(i+H_p)\Delta_n} \ud \langle X, \sigma^2 \rangle_t
\right),
\end{align}
respectively. Obviously, $U_{H_p, \nu, 1}$ is the dominant term in the error process.

Before diving into the proof, we need to introduce some notations concerning the adjustment factors in Proposition~\ref{prop:SALE-acov-noisefree}. The definition naturally arises when considering the overlapping situation of the increment terms at different scales.

\begin{definition}\label{def:adjustment-factors}
Suppose $p,q,H_p,H_q,k_p,k_q$ are positive integers that satisfy $p \geq q$ and $H_p \geq H_q$. Define the following discrete function $\mathcal{K}_{p,q}: \Z \to \R$ as
\begin{equation}\label{eq:kernel-Kpq}
\mathcal{K}_{p,q}(d) =
\begin{cases}
\frac{d+H_q}{H_pH_q}, & \text{if } -H_q < d < 0, \\
\frac{1}{H_p}, & \text{if } 0 \leq d \leq H_p-H_q, \\
\frac{-d+H_p}{H_pH_q}, & \text{if } H_p-H_q < d < H_p, \\
0, & \text{otherwise}.
\end{cases}
\end{equation}
One verify that $\sum_{d\in\Z}\mathcal{K}_{p,q}(d) = 1$. For any $i,j\in \Z$, define the following two sets of grid points
\begin{equation}
G_{p}(i) = \{i+kH_p: k\in \Z\} \quad \text{and} \quad G_{q}(j) = \{j+kH_q: k\in \Z\},
\end{equation}
and two points $L_{p,q}(i,j)$ and $R_{p,q}(i,j)$ as
\begin{equation}
L_{p,q}(i,j) = (i+2H_p) \lor (j+2H_q) \quad \text{and} \quad R_{p,q}(i,j) = (i+(k_p+2)H_p) \land (j+(k_q+2)H_q).
\end{equation}
Next, define the \emph{cubed overlapping length} (COL) and its normalized version as
\begin{equation}\label{eq:COL}
\mathrm{COL}_{p,q}(i,j) = \bigl[(R_{p,q}(i,j) - L_{p,q}(i,j))_+\bigr]^3 \quad \text{and} \quad \widetilde{\mathrm{COL}}_{p,q}(i,j) = \frac{\mathrm{COL}_{p,q}(i,j)}{k_q^3H_q^3}.
\end{equation}
Moreover, consider the following steps. Denote a set of points
\begin{equation}
P_{p,q}(i,j) = (G_{p}(i) \cup G_{q}(j)) \cap [L_{p,q}(i,j), R_{p,q}(i,j)],
\end{equation}
and then sort the elements in $P_{p,q}(i,j)$ in ascending order to get a sequence $Q_{p,q}(i,j) = [x_1, \dotsc, x_m]$ with $m \geq 0$, and finally define the \emph{sum of squares of overlapping segments} (SSOS) and its normalized version as
\begin{equation}\label{eq:SSOS}
\mathrm{SSOS}_{p,q}(i,j) = \sum_{k=1}^{m-1} (x_{k+1} - x_k)^2 \quad \text{and} \quad \widetilde{\mathrm{SSOS}}_{p,q}(i,j) = \frac{\mathrm{SSOS}_{p,q}(i,j)}{k_qH_q^2}.
\end{equation}
It is easy to see that both $\mathrm{COL}_{p,q}(i,j)$ and $\mathrm{SSOS}_{p,q}(i,j)$ depend on $i,j$ only through $j-i$. Finally, we define the \emph{adjustment factors} $v_{p,q}^{(1)}$ and $v_{p,q}^{(2)}$ as
\begin{align}
v_{p,q}^{(1)} &= \sum_{d\in\Z} \mathcal{K}_{p,q}(d) \widetilde{\mathrm{SSOS}}_{p,q}(0,d), \\
v_{p,q}^{(2)} &= \sum_{d\in\Z} \mathcal{K}_{p,q}(d) \widetilde{\mathrm{COL}}_{p,q}(0,d).
\end{align}
This definition can also be used as an algorithm to calculate the adjustment factors.
\end{definition}

Note that in the above definition, suppose $k_p = \lfloor \beta \lfloor n / H_p \rfloor^b \rfloor$ holds for all $p \in \{1, \dotsc, M_n\}$, with some constant $\beta > 0$ and $b \in (0, 1)$, we have $v_{p,q}^{(1)}, v_{p,q}^{(2)} \in [0, 1)$.

With the definition above, we first establish the following lemma concerning the covariance of $U_{H_p, \nu, 1}$ and $U_{H_q, \nu, 1}$ within a large block.
\begin{lemma}\label{lem:SALE-increment-block-cov}
We have
\begin{equation}
\begin{aligned}
&\E \Bigl(U_{H_p, \nu, 1} U_{H_q, \nu, 1} \Big| \filt_{L\nu} \Bigr)
\\ &=
\frac{u_n^2}{k_p} \cdot 4 v_{p,q}^{(1)} \frac{H_q}{H_p} \cdot \sigma_\nu^6 L
+ u_n^2 k_pH_p\Delta_n \cdot \frac{2}{3} v_{p,q}^{(2)} \left(\frac{k_qH_q}{k_pH_p}\right)^2 \cdot \sigma_\nu^2 \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=L\nu} L
\\ &\qquad
+ o_p(u_n^2 k_p^{-1} L + u_n^2 k_pH_p\Delta_n L).
\end{aligned}
\end{equation}
\end{lemma}

\begin{proof}
We can rewrite $U_{H_p, \nu, 1}$ as
\begin{equation}
U_{H_p, \nu, 1}
=
\frac{u_n}{H_p} \sum_{i\in J_{H_p}(\nu)}
\Bigl(
V_{H_p, i} - (\Delta_{H_p} X_i) (\Delta_{H_p} \sigma_i^2)
\Bigr)
=
\frac{u_n}{H_p} \sum_{i\in J_{H_p}(\nu)}
(\Delta_{H_p} X_i) (e_{H_p, i+} - e_{H_p, i-}),
\end{equation}
where $e_{H_p,i+} = \widehat{\sigma}_{H_p, i+}^2 - \sigma_{i+H_p}^2$, and $e_{H_p,i-} = \widehat{\sigma}_{H_p, i-}^2 - \sigma_i^2$, and repeat this similarly for $U_{H_q, \nu, 1}$. As a result, we have
\begin{equation}
\begin{aligned}
\E \Bigl(U_{H_p, \nu, 1} U_{H_q, \nu, 1} \Big| \filt_{L\nu} \Bigr)
&=
\frac{u_n^2}{H_p H_q} \sum_{i \in J_{H_p}(\nu)}
\Biggl\{
\sum_{j \in J_{H_q}(\nu)}
\E \Bigl[
(\Delta_{H_p} X_i) (\Delta_{H_q} X_j)
\Big| \filt_{L\nu} \Bigr]
\\ &\qquad \qquad \qquad \qquad
\E \Bigl[
(e_{H_p, i+} - e_{H_p, i-}) (e_{H_q, j+} - e_{H_q, j-})
\Big| \filt_{L\nu} \Bigr]
\Biggr\}.
\end{aligned}
\end{equation}
For the price-related term inside the bracket, we have
\begin{equation}
\E \Bigl[
(\Delta_{H_p} X_i) (\Delta_{H_q} X_j)
\Big| \filt_{L\nu} \Bigr]
=
\sigma_\nu^2 s(i, j) + o_p(H_q \Delta_n),
\end{equation}
where $s(i,j) = H_pH_q\Delta_n \mathcal{K}_{p,q}(j-i)$ describes the overlapping time length of the increments, with $\mathcal{K}_{p,q}$ defined in Equation~\eqref{eq:kernel-Kpq}. For the spot-volatility-related term inside the bracket, we use the similar decomposition as in the proof of Lemma~\ref{lem:err-spot-volatility}. That is, $e_{H_p, i+} = \tilde{e}_{H_p, i+} + \Delta_{H_p} \sigma_{i+H_p}^2$, where the second term is negligible here. For the spot volatility on the right hand side, we have
\begin{equation}
\tilde{e}_{H_p, i+}
=
\frac{1}{k_p H_p \Delta_n}
\left[
\left(\sum_{k \in S_{H_p}^+} \xi_{H_p, i, k} \right)
+ \eta_{H_p, i}^+
\right],
\end{equation}
where
\begin{align}
\xi_{H_p, i, k}
&=
\int_{(i+kH_p)\Delta_n}^{(i+(k+1)H_p)\Delta_n} 2(X_r - X_{i+kH_p}) \ud X_r, \quad
\text{for all } k \in S_{H_p}^+,\\
\eta_{H_p, i}^+
&=
\int_{(i+2H_p)\Delta_n}^{(i+(k_p+2)H_p)\Delta_n} (\sigma_r^2 - \sigma_{i+2H_p}^2) \ud r.
\end{align}
The cross product of these terms are asymptotically negligible as before. Therefore, it suffices to consider
\begin{equation}
\E \Biggl[
\Biggl(\sum_{k \in S_{H_p}^+} \xi_{H_p, i, k} \Biggr)
\Biggl(\sum_{l \in S_{H_q}^+} \xi_{H_q, j, l} \Biggr)
\Bigg| \filt_{L\nu} \Biggr]
\quad \text{and} \quad
\E \Bigl[
\eta_{H_p, i}^+ \eta_{H_q, j}^+
\Big| \filt_{L\nu} \Bigr]
\end{equation}
terms. According to Lemma~\ref{lem:overlap-expectation}, we know that
\begin{equation}
\E \Biggl[
\Biggl(\sum_{k \in S_{H_p}^+} \xi_{H_p, i, k} \Biggr)
\Biggl(\sum_{l \in S_{H_q}^+} \xi_{H_q, j, l} \Biggr)
\Bigg| \filt_{L\nu} \Biggr]
=
2 \sigma_\nu^4 \mathrm{SSOS}_{p,q}(i,j) \Delta_n^2
+ o_p(k_q H_q^2 \Delta_n^2),
\end{equation}
and
\begin{equation}
\E \Bigl[
\eta_{H_p, i}^+ \eta_{H_q, j}^+
\Big| \filt_{L\nu} \Bigr]
=
\frac{1}{3}
\left.\frac{\ud \langle \sigma^2, \sigma^2 \rangle_t}{\ud t}\right|_{t=L\nu}
\mathrm{COL}_{p,q}(i,j) \Delta_n^3
+ o_p(k_q^3 H_q^3 \Delta_n^3).
\end{equation}
Therefore, we have
\begin{equation}
\begin{aligned}
&\frac{u_n^2}{H_p H_q} \sum_{i \in J_{H_p}(\nu)}
\sum_{j \in J_{H_q}(\nu)}
\E \Bigl[
(\Delta_{H_p} X_i) (\Delta_{H_q} X_j)
\Big| \filt_{L\nu} \Bigr]
\E \Bigl[
\tilde{e}_{H_p, i+} \tilde{e}_{H_q, j+} + \tilde{e}_{H_p, i-} \tilde{e}_{H_q, j-}
\Big| \filt_{L\nu} \Bigr]
\\ &\approx
\frac{u_n^2}{H_p H_q} \frac{1}{k_pH_p\Delta_n} \frac{1}{k_qH_q\Delta_n} \sum_{i \in J_{H_p}(\nu)}
\\ & \qquad
\sum_{j \in J_{H_q}(\nu)}
\E \Bigl[
(\Delta_{H_p} X_i) (\Delta_{H_q} X_j)
\Big| \filt_{L\nu} \Bigr]
\E \Biggl[
\Biggl(\sum_{k \in S_{H_p}^+} \xi_{H_p, i, k} \Biggr)
\Biggl(\sum_{l \in S_{H_q}^+} \xi_{H_q, j, l} \Biggr)
+
\eta_{H_p, i}^+ \eta_{H_q, j}^+
\Bigg| \filt_{L\nu} \Biggr]
\times 2
\\ &\approx
\frac{u_n^2}{k_pk_qH_p^2H_q^2\Delta_n^2}
\sum_{i \in J_{H_p}(\nu)}
k_q H_p H_q^3 \Delta_n^3 \cdot 4\sigma_\nu^6 v_{p,q}^{(1)} +
k_q^3 H_p H_q^4 \Delta_n^4
\cdot 
\frac{2}{3} \sigma_\nu^2 \left.\frac{\ud \langle \sigma^2, \sigma^2 \rangle_t}{\ud t}\right|_{t=L\nu} v_{p,q}^{(2)}
\\ &\approx
\frac{u_n^2}{k_p} \cdot 4 v_{p,q}^{(1)} \frac{H_q}{H_p} \cdot \sigma_\nu^6 L
+ u_n^2 k_pH_p\Delta_n \cdot \frac{2}{3} v_{p,q}^{(2)} \left(\frac{k_qH_q}{k_pH_p}\right)^2 \cdot \sigma_\nu^2 \left.\frac{\ud\langle\sigma^2, \sigma^2\rangle_t}{\ud t}\right|_{t=L\nu} L.
\end{aligned}
\end{equation}
This completes the proof of Lemma~\ref{lem:SALE-increment-block-cov}.
\end{proof}

Suppose $k_p = \lfloor \beta \lfloor n / H_p \rfloor^b \rfloor$ holds for all $p \in \{1, \dotsc, M_n\}$, with some constant $\beta > 0$ and $b \in (0, 1)$. Proposition~\ref{prop:SALE-acov-noisefree} is a direct result of Lemma~\ref{lem:SALE-increment-block-cov}, and the first scenario of Theorem~\ref{thm:MSLE-clt-noisefree} follows directly from Proposition~\ref{prop:SALE-acov-noisefree}.

Next, we prove Proposition~\ref{prop:adj-factor-asym} on the asymptotic properties of the adjustment factors.

\begin{proof}[Proof of Proposition~\ref{prop:adj-factor-asym}]
Recall that, there are two sequences of scales $H_p$ and $H_q$ indexed by $n$, such that $H_p \geq H_q$ for all $n$, and $H_p, H_q \to \infty$, $H_{q} / H_{p} \to c$ for some constant $c \in (0, 1]$ as $n \to \infty$. Note the necessary condition for $\mathcal{K}_{p,q}(d) > 0$ is that $-H_q < d < H_p$. It is easy to see that under this condition, we have $\widetilde{\mathrm{COL}}_{p,q}(0,d) \to 1$ as $n\to\infty$, so $v_{p,q}^{(2)} \to 1$ as $n\to\infty$. For $v_{p,q}^{(2)}$, note that asymptotically, the total length of overlapping region contains about
\begin{equation}
N_{p,q} = \frac{k_qH_q}{H_p} \approx \beta c^{1-b} (n/H_p)^b \to \infty
\end{equation}
increments of $H_p$ in $H_p$-grids. In fact, across all $j$ satisfying $i-H_q < j < i+H_p$ for a fixed $i$, the number of $H_p$-intervals in $H_p$-grid, where the segments within it are full-filled and add up to $H_p$, is also about $N_{p,q}$. That is, we can regroup the SSOS defined in Equation~\eqref{eq:SSOS} into approximately $N_{p,q}$ groups, and therefore
\begin{equation}
\mathrm{SSOS}_{p,q}(i,j) \approx \sum_{l=1}^{N_{p,q}} g_{p,q}(l;i,j),
\end{equation}
where $g_{p,q}(l;i,j)$ is the SSOS within group $l$. Thus, we have
\begin{equation}
v_{p,q}^{(1)}
\approx
\frac{1}{k_q H_q^2}
\sum_{d\in\Z} \mathcal{K}_{p,q}(d) \sum_{l=1}^{N_{p,q}} g_{p,q}(l;0,d)
=
\frac{1}{k_q H_q^2} \sum_{l=1}^{N_{p,q}}
\sum_{d\in\Z} \mathcal{K}_{p,q}(d) g_{p,q}(l;0,d).
\end{equation}
Notice that, $g_{p,q}(l;0,d) = g_{p,q}(l;0,d+H_q)$ for any valid $d$, because the pattern of grid points within the $l$th $H_p$-interval repeats itself when $j$ shifts $H_q$. Another important observation is that, through direct calculation, we have
\begin{equation}
\sum_{d\in\Z} \mathcal{K}_{p,q}(d) 1_{\{d\equiv d_0\text{ mod }H_q\}} = \frac{1}{H_q},
\quad \text{for all }d_0 = 0, 1, \dotsc, H_q-1,
\end{equation}
Therefore, we have
\begin{equation}
\begin{aligned}
v_{p,q}^{(1)}
&\approx
\frac{1}{k_q H_q^2} \sum_{l=1}^{N_{p,q}}
\sum_{d\in\Z} \mathcal{K}_{p,q}(d) g_{p,q}(l;0,d)
\\ &=
\frac{1}{k_q H_q^2} \sum_{l=1}^{N_{p,q}}
\sum_{d\in\Z} \mathcal{K}_{p,q}(d) g_{p,q}(l;0,d) \sum_{d_0=0}^{H_q-1} 1_{\{d\equiv d_0\text{ mod }H_q\}}
\\ &=
\frac{1}{k_q H_q^2} \sum_{l=1}^{N_{p,q}}
\sum_{d_0=0}^{H_q-1} g_{p,q}(l;0,d_0)
\sum_{d\in\Z} \mathcal{K}_{p,q}(d) 1_{\{d\equiv d_0\text{ mod }H_q\}}
\\ &=
\frac{1}{k_q H_q^2} \sum_{l=1}^{N_{p,q}}
\frac{1}{H_q} \sum_{d_0=0}^{H_q-1} g_{p,q}(l;0,d_0).
\end{aligned}
\end{equation}
On the other hand, the property of $H_q^{-1}\sum_{d_0=0}^{H_q-1} g_{p,q}(l;0,d_0)$ has been well studied by Lemma~\ref{lem:grid-integral}. That is,
\begin{equation}
\begin{aligned}
\frac{1}{H_q} \sum_{d_0=0}^{H_q-1} g_{p,q}(l;0,d_0)
&=
H_p^2 \E_{\alpha_1\sim \unif\{1/H_q,\dotsc, H_q/H_q\}} \Bigl[S_2(\alpha_1, H_q/H_p)\Bigr]
\\ &\to
H_p^2 \E_{\alpha_1\sim \unif(0,1]} \Bigl[S_2(\alpha_1, H_q/H_p)\Bigr]
\\ &=
H_pH_q \left(1 - \frac{H_q}{3H_p}\right),
\end{aligned}
\end{equation}
as $H_q \to \infty$. Finally, we have
\begin{equation}
v_{p,q}^{(1)}
\to
\frac{1}{k_q H_q^2} \sum_{l=1}^{N_{p,q}} H_pH_q \left(1 - \frac{H_q}{3H_p}\right)
\approx
\frac{1}{k_q H_q^2} \frac{k_qH_q}{H_p} H_p H_q \left(1 - \frac{H_q}{3H_p}\right)
= 1 - \frac{c}{3},
\end{equation}
as $n\to\infty$. This completes the proof of Proposition~\ref{prop:adj-factor-asym}.
\end{proof}

The second scenario of Theorem~\ref{thm:MSLE-clt-noisefree} follows directly from Proposition~\ref{prop:SALE-acov-noisefree}. This completes the proof of Theorem~\ref{thm:MSLE-clt-noisefree}. The proof of Theorem~\ref{thm:MSLE-clt-noisy} follows from Proposition~\ref{prop:MSLE-noise} and Theorem~\ref{thm:MSLE-clt-noisefree} in the exactly same way as in Section~\ref{app:SALE-clt-noisy}, so we omit the details here.

