Although the Forrelation algorithm was initially used to demonstrate theoretical separation between two complexity classes, recent work~\cite{amc} has shown that it can also be leveraged for efficient sampling of different cryptographic spectra of Boolean functions, including the Walsh-Hadamard, crosscorrelation, and autocorrelation spectra. In this regard, we have the following results from~\cite{amc}.
\begin{theorem}[\cite{amc}]
	\label{thm:sample-hadamard}
	Given oracle access to $f\in\mathcal{B}_n$ and a set of points $S\subseteq\mathbb{F}_2^n$, by defining $f_1=f_3=f$ and $f_2=g\in\mathcal{B}_n$, where $g(\var{x})=1$ for $\var{x}\in S$ and $0$ otherwise, the $3$-query $3$-fold Forrelation algorithm (Fig.~\textup{\ref{fig:forr-q3f3}}) measures any state other than the all-zero state with probability of approximately $\frac{4}{2^n}\sum_{\var{x}\in S}|W_f(\var{x})|^2$.
\end{theorem}
\begin{theorem}[\cite{amc}]
	\label{thm:sample-cross}
	Given oracle access to $f,g\in\mathcal{B}_n$,  and a point $\var{y}\in\mathbb{F}_2^n$, the $3$-query $3$-fold Forrelation algorithm (Fig.~\textup{\ref{fig:forr-q3f3}}) measures the all-zero state with probability $2^{-2n} \left(C_{f,g}(\var{y})^2\right)$, by setting $f_1=f$, $f_2=\mathbb{L}_{\var{y}}$, and $f_3=g$, where $\mathbb{L}_{\var{y}}=\var{y}\cdot \var{x}$ is a linear function in $\mathcal{B}_n$.
	With an exact same setup, the $2$-query $3$-fold Forrelation algorithm (Fig.~\textup{\ref{fig:forr-q2f3}}) measures $\ket{0}$ with a probability $\frac{1}{2}\left(1+\frac{C_{f,g}(\var{y})}{2^n}\right)$.
	Additionally, by setting $f=g$, the above results apply to the autocorrelation coefficient $C_{f}(\var{y})$, at the point $\var{y}\in\mathbb{F}_2^n$.
\end{theorem}


Following the Forrelation formulation, the concept of ($3$-fold) nega-Forrelation was introduce in~\cite{dcc}, defined as follows.
\begin{definition}[nega-Forrelation~\cite{dcc}]
	\label{def:nega-forr}
	Given oracle access to $f_1,f_2,f_3\in\mathcal{B}_n$, the $3$-fold nega-Forrelation measures certain kind of correlation between the Boolean function $f_1$, the \nh of $f_2$ and the conjugate \nh of $f_3$, mathematically formulated as
    \allowdisplaybreaks
\begin{align*}
\eta_{f_1,f_2,f_3}&=\frac{1}{2^{n}}\sum_{\var{x}\in\mathbb{F}_2^n}{(-1)^{f_1(\var{x})}N_{f_2}(\var{x})\overline{N}_{f_3}(\var{x})}\\
&=\frac{1}{2^{2n}}\sum_{\var{x_1}, \var{x_2} , \var{x_3}\in\mathbb{F}_2^n} (-1)^{f_1(\var{x_1})} (-1)^{f_2(\var{x_2})\op \var{x_1}\cdot \var{x_2}} (i)^{wt(\var{x_2})} (-1)^{f_3(\var{x_3})\op \var{x_1}\cdot \var{x_3}}(-i)^{wt(\var{x_3})}.
\end{align*}
\end{definition}

In a similar manner, two efficient quantum algorithms were proposed for estimating the $3$-fold nega-Forrelation~\cite{dcc} assuming the oracle access to the Boolean functions $f_1,f_2,f_3 \in\mathcal{B}_n$, one using $3$ sequential queries and the other using $\lceil  \frac{3}{2} \rceil=2$ parallel queries. For a detailed analysis of these algorithms, the readers are referred to~\cite{dcc}. The schematic diagrams of the corresponding quantum algorithms are shown in Fig.~\textup{\ref{fig:nega}}.
