\section{Sampling arbitrary power of Walsh-Hadamard transform using Forrelation}
\label{sec:cont3}
In this section, we present a novel technique for sampling arbitrary powers of the Walsh-Hadamard transform using Forrelation~\cite{aaron}. This generalizes and improves upon the square sampling method discussed in Theorem~\ref{thm:sample-hadamard}. As shown in~\cite{amc}, by setting $f_1=f_3=f$ and $f_2=0$, the expression for $\Phi_{f_1, f_2, f_3}$ simplifies to $\Phi_{f_1,f_2, f_3} =\frac{1}{2^{2n}}\sum_{\var{x_2}}W^2_f(\var{x_2})$. Building on this, we extend the Forrelation framework to support sampling of arbitrary powers of the Walsh-Hadamard transform by employing additional analytical techniques and algorithmic refinements.

\begin{theorem}
\label{thm:walsh-power}
Let $f_1, \ldots,f_{2k+1}\in\mathcal{B}_n$. Then the $(2k+1)$-fold Forrelation, $\Phi_{f_1,\ldots , f_{2k+1}}$ can be written as product of the Walsh-Hadamard transforms of $(k+1)$ many Boolean functions as follows.
$$\Phi_{f_1,\ldots , f_{2k+1}} = \frac{1}{2^{\frac{n}{2}(k+1)}}\sum\limits_{\var{x_2}, \var{x_4},  \ldots , \var{x_{2k}} } W_{f_1}(\var{x_2})W_{f_3}(\var{x_2}\oplus \var{x_4})W_{f_5}(\var{x_4}\oplus \var{x_6}) \ldots W_{f_{2k-1}}(\var{x_{2k-2}} \oplus \var{x_{2k}}) W_{f_{2k+1}}(\var{x_{2k}}).$$
\end{theorem}
\begin{proof}
We begin with the $(2k+1)$-fold Forrelation formulation, 
\begin{align*}
\Phi_{f_1,\ldots , f_{2k+1}} = & \frac{1}{2^{n(k+1)}}\sum\limits_{\var{x_1}, \ldots , \var{x_{2k+1}} \in\mathbb{F}_2^n}
	(-1)^{f_1(\var{x_1})}(-1)^{\var{x_1}\cdot \var{x_2}} (-1)^{f_2(\var{x_2})}  \ldots (-1)^{\var{x_{2k}}\cdot \var{x_{2k+1}}}
	(-1)^{f_{2k+1}(\var{x_{2k+1}})}\\
    = & \frac{1}{2^{n(k+1)}}\sum_{\var{x_{1},\var{x_{2}}}}(-1)^{f_{1}(\var{x_{1}})}(-1)^{\var{x_{1}}\cdot \var{x_{2}}}
	(-1)^{f_{2}(\var{x_{2}})} \sum_{\var{x_{3},\var{x_{4}}}}(-1)^{\var{x_{2}}\cdot \var{x_{3}}}(-1)^{f_{3}(\var{x_{3}})}(-1)^{\var{x_{3}}\cdot \var{x_{4}}}
	(-1)^{f_{4}(\var{x_{4}})} \ldots \\
    & \hspace{2cm} \ldots\sum_{\var{x_{2k-1},\var{x_{2k}}}}(-1)^{\var{x_{2k-2}}\cdot \var{x_{2k-1}}}(-1)^{f_{2k-1}(\var{x_{2k-1}})}(-1)^{\var{x_{2k-1}}\cdot \var{x_{2k}}}
	(-1)^{f_{2k}(\var{x_{2k}})}\\
    & \hspace{8.5cm}\sum_{\var{x_{2k+1}}}(-1)^{\var{x_{2k}}\cdot \var{x_{2k+1}}}
	(-1)^{f_{2k+1}(\var{x_{2k+1}})}.
\end{align*}
Fix $f_2=f_4=\ldots = f_{2k}=0$, constant Boolean functions. Then, the $(2k+1)$-fold Forrelation can be written as
\begin{align*}
\Phi_{f_1,\ldots , f_{2k+1}} = & \frac{1}{2^{n(k+1)}}\sum_{\var{x_{1},\var{x_{2}}}}(-1)^{f_{1}(\var{x_{1}})}(-1)^{\var{x_{1}}\cdot \var{x_{2}}}
     \sum_{\var{x_{3},\var{x_{4}}}}(-1)^{f_{3}(\var{x_{3}})}(-1)^{\var{x_{3}}\cdot \left(\var{x_{2}} \oplus \var{x_{4}}\right)}
	\ldots \\
    & \hspace{1cm} \ldots\sum_{\var{x_{2k-1},\var{x_{2k}}}}(-1)^{f_{2k-1}(\var{x_{2k-1}})}(-1)^{\var{x_{2k-1}}\cdot \left(\var{x_{2k-2}} \oplus \var{x_{2k}}\right)} \sum_{\var{x_{2k+1}}}
	(-1)^{f_{2k+1}(\var{x_{2k+1}})}(-1)^{\var{x_{2k}}\cdot \var{x_{2k+1}}}\\
    = & \frac{1}{2^{\frac{n}{2}(k+1)}} \sum_{\var{x_{2}}}W_{f_1}(\var{x_2})
     \sum_{\var{x_{4}}}W_{f_3}\left(\var{x_{2}} \oplus \var{x_{4}} \right) \ldots \sum_{\var{x_{2k}}}W_{f_{2k-1}}\left(\var{x_{2k-2}} \oplus \var{x_{2k}}\right) W_{f_{2k+1}}(\var{x_{2k}})\\
     = & \frac{1}{2^{\frac{n}{2}(k+1)}}\sum\limits_{\var{x_2}, \var{x_4},  \ldots , \var{x_{2k}} } W_{f_1}(\var{x_2})W_{f_3}(\var{x_2}\oplus \var{x_4}) \ldots W_{f_{2k-1}}(\var{x_{2k-2}}\oplus \var{x_{2k}}) W_{f_{2k+1}}(\var{x_{2k}}).
\end{align*}
\end{proof}

If $f_1=f_3=\ldots =f_{2k+1}=f$, then from Theorem~\ref{thm:walsh-power}, the $(2k+1)$-fold Forrelation can be written as 
$$\Phi_{f_1,\ldots , f_{2k+1}}=\frac{1}{2^{\frac{n}{2}(k+1)}}\sum\limits_{\var{x_2}, \var{x_4},  \ldots , \var{x_{2k}} } W_{f}(\var{x_2})W_{f}(\var{x_2}\oplus \var{x_4}) \ldots W_{f}(\var{x_{2k-2}}\oplus \var{x_{2k}}) W_{f}(\var{x_{2k}}).$$

\begin{remark}
The special cases for different values of $k$ are as follows.
    \begin{itemize}
        \item For $k=1$, $$\Phi_{f,\mathbf{0},f} = \frac{1}{2^n}\sum_{\var{x_2}}W_f(\var{x_2}) W_f(\var{x_2}) = \frac{1}{2^n}\sum_{\var{x}}W^2_f(\var{x}) =1,$$
        as pointed out in~\textup{\cite{amc}}.
        \item For $k=2$,
        \begin{align*}
            \Phi_{f,\mathbf{0},f,\mathbf{0},f} = & \frac{1}{2^{3n/2}}\sum_{\var{x_2},\var{x_4}}W_f(\var{x_2})W_f(\var{x_2}\oplus \var{x_4})W_f(\var{x_4})\\
            = & \frac{1}{2^{3n/2}}\big[W_f^3(0^n)+ 3 W_f(0^n)\sum_{\var{x}\neq 0^n}W_f^2(\var{x}) + 6\sum_{\var{x}\neq \var{y}\neq 0^n}W_f(\var{x})W_f(\var{y})W_f(\var{x}\oplus \var{y})\big].
        \end{align*}
        \item For $k=3$,
        \begin{align*}
        \Phi_{f,\mathbf{0},f,\mathbf{0},f,\mathbf{0},f} = & \frac{1}{2^{2n}}\sum_{\var{x_2},\var{x_4},\var{x_6}}W_f(\var{x_2})W_f(\var{x_2}\oplus \var{x_4})W_f(\var{x_4}\oplus \var{x_6})W_f(\var{x_6})\\
            = & \frac{1}{2^{2n}}\big[\sum_{\var{x}}W_f^4(\var{x}) + 6\sum_{\var{x}\neq \var{y}}W_f^2(\var{x})W_f^2(\var{y}) + 24\sum_{\var{x_1}\neq \var{x_2} \neq \var{x_3}}W_f(\var{x_1})W_f(\var{x_1}\oplus\var{x_2})W_f(\var{x_2}\oplus\var{x_3})W_f(\var{x_3})\big]\\
            = & \frac{1}{2^{2n}}\big[\sum_{\var{x}}W_f^4(\var{x}) + 6\sum_{\var{x}\neq \var{y}}W_f^2(\var{x})W_f^2(\var{y}) + 24\sum_{\var{x}\neq \var{y} \neq \var{z}}W_f(\var{x})W_f(\var{y})W_f(\var{z})W_f(\var{x} \oplus \var{y} \oplus \var{z})\big].
            \end{align*}
            \item For $k=4$,
            \begin{align*}
            & \Phi_{f, \mathbf{0}, f,\mathbf{0}, f, \mathbf{0}, f, \mathbf{0},f}\\
            = & \frac{1}{2^{5n/2}} \sum_{\var{x_2},\var{x_4},\var{x_6},\var{x_8}}W_f(\var{x_2})W_f(\var{x_2}\oplus \var{x_4})W_f(\var{x_4}\oplus \var{x_6})W_f(\var{x_6}\oplus\var{x_8})W_f(\var{x_8})\\
            = & \frac{1}{2^{5n/2}} \big[\sum_{\var{x}}W_f^5(\var{x}) + \sum_{\var{x}\neq \var{y}}W_f(\var{x}) W_f^4(\var{x}) + 6\sum_{\var{x}\neq \var{y}} W_f^2(\var{x})W_f^3(\var{y}) + 6\sum_{\var{x}\neq \var{y}< \var{z}\neq \var{x}}W_f(\var{x})W_f^2(\var{y})W_f^2(\var{z})\\
            &\hspace{5cm}+ 96 \sum_{\var{w}\neq \var{x}\neq \var{y} \neq \var{z}}W_f(\var{w})W_f(\var{x})W_f(\var{y})W_f(\var{z})W_f(\var{w}\oplus \var{x} \oplus \var{y} \oplus \var{z})\big].
        \end{align*}
    \end{itemize}
\end{remark}

