\section{Stratified differential spaces}\label{section:stratified_differential_spaces}

\subsection{Differential spaces}

We recall some definitions; for more details see \cite{vector_fields_subcartesian, lusala_sniatycki_2011, sniatycki_book_2013}.

\begin{definition}
    Let $A$ be a topological space. A differential structure (or a smooth structure) on $A$ is a subset $C^\infty(A) \subset C(A,\R)$ of the continuous functions $A\to \R$ satisfying
    \begin{enumerate}
        \item\label{condition:differential_subbasis} The sets $\{f^{-1}((a,b)):\:f\in C^\infty(A)\}$ form a sub-basis for the topology of $A$;
        \item for all $F:\R^n\to \R$ smooth and $f_1,\ldots f_n\in C^\infty(A)$, the composition $F(f_1,\ldots,f_n)$ is in $C^\infty(A)$;
        \item If $f\in C(A,\R)$ is a function such that for all $a\in A$ there exist a neighbourhood $U_a$ and $g_a\in C^\infty(A)$ with $f\big\lvert_{U_a} = g_a\big\lvert_{U_a}$, then $f\in C^\infty(A)$.
\end{enumerate}

    A topological space with a differential structure is a \textbf{differential space}.
\end{definition}
\begin{remark}
    A differential structure determines the topology via condition \cref{condition:differential_subbasis}, so a differential space can be given as a set (without a topology) and a differential structure on it.
\end{remark}

\begin{definition}
    Let $A,B$ be differential spaces. A continuous function $\varphi:A\to B$ is \textbf{smooth} if for all $f\in C^\infty(B)$, the pullback $\varphi^*f:A\to \R$ satisfies $\varphi^*f\in C^\infty(A)$.

    We denote by $C^\infty(A,B)$ the set of all smooth functions from $A$ to $B$.

    A smooth function $\varphi$ is a \textbf{smooth embedding} if it is injective and $\varphi^*:C^\infty(B)\to C^\infty(A)$ is onto. It is a \textbf{diffeomorphism} if it has a smooth inverse.
\end{definition}

\begin{definition}
    Let $B$ be a differential space and let $i:A\to B$ be a topological embedding. The \textbf{induced differential structure} on $A$ is
    \begin{equation*}
        C^\infty(A) \coloneqq i^*\left(C^\infty(B)\right) = \{f\big\lvert_A:\: f\in C^\infty(B) \}.
    \end{equation*}

    With the induced differential structure on $A$, the topological embedding $i:A\to B$ is a smooth embedding. We may omit the embedding $i:A\to B$ and say that $A$ is a \textbf{differential subspace} of $B$.
\end{definition}

Throughout, we implicitly consider manifolds as differential spaces, and may refer to subsets as subspaces in the differential sense.

\begin{definition}
    Let $A$ be a differential space and let $p\in A$. A \textbf{derivation at $\mathbf{p}$} is a linear map $\nu:C^\infty(A)\to \R$ satisfying
    \begin{equation*}
        \nu(fg) = f(p)\nu(g) + g(p)\nu(f).
    \end{equation*}
\end{definition}

\begin{definition}
    The set of all derivations at $p$ is called the \textbf{Zariski tangent of $A$ at $p$} and denoted by $T^Z_pA$. It is a vector space over $\R$.
\end{definition}

Write
\begin{equation*}
    T^ZA \coloneqq \bigcup_{p\in A} T^Z_pA.
\end{equation*}
We want to endow $T^ZA$ with a differential structure. Let $\tau_A:T^ZA\to A$ be the projection
\begin{equation*}
    \tau_A(v) = p, \qquad \forall v\in T^Z_pA
\end{equation*}
and for all $f\in C^\infty(A)$ define $df:T^ZA\to \R$ by
\begin{equation*}
    df(v) = v(f).
\end{equation*}

\begin{definition}[{\cite[Definition~3.3.2]{sniatycki_book_2013}}]\label{definition:Zariski_tangent}
    The \textbf{Zariski tangent $T^ZA$ of $A$} is the differential space given by the set $T^ZA$ with the differential structure generated by
    \begin{equation*}
        \{f\circ \tau_A:\: f\in C^\infty(A)\}
    \end{equation*}
    and
    \begin{equation*}
        \{df:\: f\in C^\infty(A)\}.
    \end{equation*}
\end{definition}


\begin{proposition}[{\cite[Proposition~3.3.3]{sniatycki_book_2013}}]
    The map $\tau_A:T^ZA\to A$ is smooth.
\end{proposition}

\begin{definition}
    Let $A,B$ be differential spaces, $\varphi:A\to B$ a smooth map, and $p\in A$.
    The differential $D^Z_p\varphi:T^Z_pA\to T^Z_{\varphi(p)}B$ of $\varphi$ at $p$ is defined
    \begin{equation*}
        {D^Z_p\varphi}(v)(f) = v(f\circ \varphi), \qquad \forall v\in T^Z_pA,\, f\in C^\infty(B).
    \end{equation*}
    The differential $D^Z\varphi:T^ZA \to T^ZB$ of $\varphi$ is defined point-wise.
\end{definition}

\begin{proposition}
    The differential at a point $D^Z_p\varphi:T^Z_pA\to T^Z_{\varphi(p)}B$ is a linear map.
\end{proposition}

\begin{proposition}[{\cite[Proposition~3.3.7]{sniatycki_book_2013}}]
    The differential $D^Z\varphi:T^ZA \to T^ZB$ of $\varphi$ is a smooth map and the following diagram commutes
    \[\begin{tikzcd}[ampersand replacement=\&]
        {T^ZA} \& {T^ZB} \\
        A \& B
        \arrow["D^Zi"', from=1-1, to=1-2]
        \arrow["{\tau_A}", from=1-1, to=2-1]
        \arrow["{\tau_B}"', from=1-2, to=2-2]
        \arrow["i", from=2-1, to=2-2]
    \end{tikzcd}\]
\end{proposition}

\begin{proposition}\label{proposition:tangent_space_embedding}
    Let $i:A\to B$ be a smooth embedding of differential spaces. Then $D^Zi:T^ZA \to T^ZB$ is also a smooth embedding.
\end{proposition}
\begin{proof}
    We need to show that it is injective and that ${(D^Zi)}^*: C^\infty(T^ZB) \to C^\infty(T^ZA)$ is onto.

    For injectivity, it is enough to show that the differential at points have empty kernels. Let $v\in T^Z_pA$ with $D^Z_pi(v)=0\in T^Z_{i(p)}B$. Then for all $f\in C^\infty(B)$ we have
    \begin{equation*}
        0 = D^Z_pi(v)(f) = v(f\circ i)
    \end{equation*}
    but since all $\tilde{f}\in C^\infty(A)$ are of the form $\tilde{f} = f\circ i$ for some $f\in C^\infty(B)$, we get $v=0$.

    Recall that $C^\infty(T^ZA)$ is generated by $\{\tilde{f}\circ \tau_A,\, d\tilde{f}: \: \tilde{f}\in C^\infty(A)\}$. Again, since all ${\tilde{f}\in C^\infty(A)}$ are of the form $\tilde{f} = f\circ i$ for some $f\in C^\infty(B)$, it is enough to show that the image of $D^Zi$ contains $f\circ i \circ \tau_A$ and $d(f\circ i)$ for all $f\in C^\infty(B)$. Indeed,
    \begin{equation*}
        f\circ i \circ \tau_A = f\circ \tau_B \circ i = {(D^Zi)}^*(f\circ \tau_B)
    \end{equation*}
    and
    \begin{align*}
        d(f\circ i)(v)
        =& v(f\circ i) \\
        =& D^Zi(v)(f) \\
        =& df\left((D^Zi)(v)\right) \\
        =& {(D^Zi)}^*(df)(v).
    \end{align*}
\end{proof}

Let $A_i\subset M_i,\,i=0,1$ with $M_i$ manifolds and $A_i$ differential subspaces. By \Cref{proposition:tangent_space_embedding}, we can view $T^ZA_i\subset TM_i\Big\lvert_{A_i}\subset TM_i$ as differential subspaces of the tangent bundle. For a smooth map $g:A_0\to A_1$, its differential $D^Zg:T^ZA_0\to T^ZA_1$ is then realized as a smooth map of subspaces of $TM_i$ which is fiber-wise linear.

Thorughout the paper we use the following special case of the Whitney Extension Theorem:
\begin{lemma}[Special case of the Whitney Extension Theorem \cite{whitney_extension}]\label{lemma:whitney_extension}
    Let $U \subset \R^n$ be open and $A\subset U$ a closed subset. Consider $A$ and $TU\Big\lvert_{A}$ as differential subspaces of $U$ and $TU$, respectively. Let $g:A\to \R^m$ and $G:TU\Big\lvert_{A} \to T\R^m$ be smooth functions such that $G$ is a fiber-wise linear map over $g$ and $G\big\lvert_{T^ZA} = D^Zg$.
    Then there exists a function $\G:U\to \R^m$ such that
    \begin{enumerate}
        \item $\G\big\lvert_A = g$ and
        \item $D\G$ agrees with $G$ along $A$, i.e., on $TM_0\Big\lvert_{A}$.
    \end{enumerate}
\end{lemma}

\begin{definition}[{\cite[Definition~5.2.1]{sniatycki_book_2013}}]\label{definition:zariski_forms}
    Let $A$ be a differential space. A \textbf{Zariski $\mathbf{k}$-form on $A$} is an alternating $k$-linear smooth map from $TA$ to $\R$.
\end{definition}

Zariski forms admit pullbacks by smooth maps, defined in the same way as pullbacks of forms for manifolds. See \cite[Equation~(5.6)]{sniatycki_book_2013}. For a manifold $M$ and a differential subspace $A\subset M$  that is closed in $M$, the Zariski forms on $A$ are exactly the pullbacks of forms on $M$ by the inclusion \cite[Proposition~5.2.2]{sniatycki_book_2013}.

\subsection{Stratified differential spaces}

For a subset $A\subset B$ of a topological space, we denote its closure by $\overline{A}$.

\begin{definition}\label{def:stratified_space}
    Let $A$ be a Hausdorff, second countable, and paracompact space. A \textbf{stratification} of $A$ is a decomposition
    \begin{equation*}
        A = \bigsqcup_{X\in \S}X
    \end{equation*}
    with the following properties:
    \begin{enumerate}
        \item Each $X\in \S$ carries a structure of a smooth manifold.
        \item The decomposition is locally finite.
        \item \emph{Condition of the frontier} --- for $X,Y\in\S$, if $X\cap \overline{Y} \neq \emptyset$ then $X\subset \overline{Y}$. Equivalently:
        \begin{itemize}
            \item[(3')] The closure of $Y\in \S$ in $A$ is a union of elements from $S$.
        \end{itemize}
    \end{enumerate}
    Each $X\in \S$ is called a \textbf{stratum}. A \textbf{stratified space} is the data $\left(A, \S\right)$.
\end{definition}

\begin{definition}
    Let $X,Y\in\S$ and define the order relation by setting $X<Y$ when $X\subset \overline{Y}$. We say $X,Y$ are \textbf{comparable} when $X<Y$ or $Y<X$.
\end{definition}
\begin{definition}
    With the notation of \Cref{def:stratified_space}, let $C^\infty(A)$ be a differential structure on $A$. The stratification is smooth if the embedding of each stratum into $A$ is smooth. A differential space with a smooth stratification is a \textbf{stratified differential space}.
\end{definition}
\begin{definition}
    Let $\left(A_i, \S_i\right),\,i=0,1$ be stratified differential spaces. A \textbf{stratified diffeomorphism} between them consists of
    \begin{enumerate}
        \item a bijection $s:\S_0\to \S_1$ and
        \item a diffeomorphism $g:A_0\to A_1$,
    \end{enumerate}
    such that $g$ restricted to every $X_0\in\S_0$ is a diffeomorphism onto $s(X_0)$.
\end{definition}

\begin{definition}
    Let $M$ be a manifold. A \textbf{stratified subspace} of $M$ is a smooth embedding $i:A\to M$ of a stratified differential space $(A, \S)$ onto a closed subset of $M$.
\end{definition}

One commonly adds additional regularity assumptions to the definition of embedded stratified subspaces, such as Whitney~(B) regularity (see \cite{mather2012notes}). A desirable property given by such regularity assumptions is that $X<Y$ implies $\dim{X}<\dim{Y}$. We use a stronger regularity condition, given in \Cref{def:smoothly_locally_trivial}, which implies Whitney~(B) and therefore also the monotonicity of dimension.

\begin{notation}\label{notation:manifold_dimension}
    If $N$ is a manifold, the notation $N^k$ means it is of dimension $k$.
\end{notation}

\begin{definition}
    A subset of a vector space is \textbf{conical} if it is invariant under multiplication by $t\in (0,1]$. A subset of a vector bundle is conical if the intersection of the subset with each fiber is conical.
\end{definition}

\begin{definition}[{\cite[Definition~3.6]{zimhony2024commutative}}]\label{def:smoothly_locally_trivial}
    Let $M$ be a manifold of dimension $n$.
    A stratified subspace $(A, \S)$ of a manifold $M$ is \textbf{smoothly locally trivial with conical fibers} if the following holds for each $X^k\in \S$ and $p\in X$.

    There exist a neighbourhood $U_p\subset M$ of $p$, a neighbourhood $W_p\subset \R^k\times \R^{n-k}$, and a diffeomorphism
    \begin{equation*}
        \theta_p:U_p\to W_p
    \end{equation*}
    such that
    \begin{enumerate}
        \item $\theta_p(X\cap U_p) = \left(\R^k\times \{0\}\right)\cap W_p$ and
        \item for each $Y\in\S$ with $X<Y$ there exists a subset $Y_p\subset \R^{n-k}\setminus\{0\}$ which is conical such that
        \begin{equation*}
            \theta_p(Y\cap U_p) = \left(\R^k \times Y_p\right) \cap W_p.
        \end{equation*}
    \end{enumerate}
    A \textbf{conical neighbourhood} of $p$ is the data $(U_p, W_p, \theta_p)$.
\end{definition}

\begin{remark}\label{rem:also_whitney_b}
    A smoothly locally trivial with conical fibers stratified subspace is Whitney~(B) regular. All Whitney~(B) regular stratified subspaces are \emph{topologically locally trivial} \cite[Corollary~10.6]{mather2012notes}, but not necessarily smoothly locally trivial.
\end{remark}

\begin{notation}\label{notation:strata_skeleton}
    Let $(A,\S)$ be a stratified subspace of a manifold $M$. We write
    \begin{align*}
    \S^{<d} &\coloneq \{X\in \S: \dim{X}<d\}, \\
    A^{<d} &\coloneq \bigsqcup_{X\in\S^{<d}}X \\
    \end{align*}
    and similarly for $\S^d, \S^{\geq d}$ and $A^{\geq d}$. Also,
    \begin{equation*}
        M^{\geq d} = M \setminus A^{<d}.
    \end{equation*}
\end{notation}

\begin{remark}
    Recall that we require a stratified subspace $A$ to be closed in $M$.
    If $X<Y$ implies $\dim{X}<\dim{Y}$, as in the case of a Whitney~(B) regular stratified subspace, then both $X^d$ and $A^{\geq d}$ are closed in $M^{\geq d}$. Also, $A^{\leq d}$ are closed in $M$.
\end{remark}

\begin{lemma}\label{lemma:stratified_spaces_locally_diffeo}
    For $i=0,1$, let $M_i$ be manifolds of dimension $n$ and $\left(A_i, \S_i\right)$ stratified subspaces of them, smoothly locally trivial with conical fibers. Let
    \begin{equation*}
        g:\left(A_0, \S_0\right) \to \left(A_1, \S_1\right)
    \end{equation*}
    be a stratified diffeomorphism, $p_0\in A_0$ and $p_1 \coloneq g\left(p_0\right)$.

    Then there exist an open set $W\subset \R^n$ and conical neighbourhoods (\Cref{def:smoothly_locally_trivial})
    \begin{equation*}
        \theta_{p_0}: U_{p_0} \to W, \quad \theta_{p_1}: U_{p_1} \to W,
    \end{equation*}
    of $p_0, p_1$ such that $\theta_{p_1}^{-1} \circ \theta_{p_0}$ restricts to $g$ on $A_0 \cap U_{p_0}$.
\end{lemma}
\begin{proof}
    Let $\theta_{p_i}':U_{p_i} \to W_{p_i}$ be conical neighbourhoods and $A_{p_i} \coloneq \theta_{p_i}\left( A_i\cap U_{p_i}\right)$. Take a local extension
    \begin{equation*}
        g':\vectorspan \{ A_{p_0}\} \cap W_{p_0} \to \vectorspan \{ A_{p_1}\} \cap W_{p_1}
    \end{equation*}
    of $g$. Since $A_{p_0}$ is conical,  $\dim{T^Z_{p_i}A_i} = \dim{\vectorspan \{ A_{p_0}\}}$. Using the fact that $g$ is a diffeomorphism and the inverse function theorem, there exists a small neighbourhood of $0$ in $\vectorspan \{ A_{p_0}\} \cap W_{p_0}$ such that $g'$ restricted to this neighbourhood is a diffeomorphism. We can extend $g'$ to a diffeomorphism \begin{equation*}
        \widetilde{g}:W_{p_0} \to W_{p_1}
    \end{equation*}
    by adding linearly independent linear terms supported in ${\left(\vectorspan \{ A_{p_0}\}\right)^\perp}$ and shrinking the neighbourhood. After possibly shrinking the neighbourhoods again, the data ${W = W_{p_1}}$, ${\theta_{p_1} = \theta_{p_1}'}$ and $\theta_{p_0} = \widetilde{g} \circ \theta_{p_0}'$ satisfies the required properties.
\end{proof}

\subsection{Isotropic and coisotropic stratified subspaces}
\begin{definition}\label{def:isotropic_and_coisotropic}
    Let $(M, \w)$ be a symplectic manifold and $(A, \S)$ a stratified subspace of it.

    The stratified subspace $(A, \S)$ is \textbf{isotropic} if every $X\in \S$ is isotropic.

    The stratified subspace $(A, \S)$ is \textbf{coisotropic} if for each $p\in A$, the Zariski tangent $T^Z_pA \subset T_pM$ is coisotropic.

    The stratified subspace $(A, \S)$ is \textbf{Lagrangian} if it is isotropic and coisotropic.
\end{definition}

\begin{lemma}\label{lemma:lagrangian_stratified_equivalence}
    Let $(M, \w)$ be a symplectic manifold and $(A, \S)$ a stratified subspace of it, smoothly locally trivial with conical fibers. Then $(A, \S)$ is Lagrangian if and only if the union of Lagrangian strata is dense in $A$.
\end{lemma}
\begin{proof}
    Assume the union of Lagrangian strata is dense in $A$. Whitney (A) regularity implies that every stratum is isotropic. For every $p\in A$, by the local model from \Cref{def:smoothly_locally_trivial}, the Zariski tangent $T_p^ZA$ contains a Lagrangian plane and is therefore coisotropic.

    Assume $(A, \S)$ is isotropic and coisotropic. If the union of Lagrangian strata is not dense in $A$, there exists a maximal $k$ and $X\in \S$ of dimension $k$ such that $X$ is not contained in the closure of any Lagrangian stratum. By the assumption that the strata are isotropic, maximality of $k$, and Whitney (B) regularity, we get that there are no $Y\in \S$ with $X<Y$, and therefore for every $p\in X$ we have $T_p^ZA=T_pX$. Define $n\coloneq \frac{1}{2}\dim{M}$. Since $X$ is isotropic, $k=\dim{X} \leq n$. Since $X$ is not Lagrangian, $k<n$. We get a contraction to the assumption that $T_p^ZA= T_pX$ is coisotropic.
\end{proof}

\section{Euler-like vector fields}\label{section:euler_like}

\subsection{Tubular neighbourhoods}\label{subsection:euler_like_and_tubular_neighbourhoods}

\begin{notation}
    Let $M$ be a manifold and let $\E$ be a vector field on $M$. We denote the flow of $\E$ at time $t\in \R$ by $\Phi_\E^t:M\to M$.
\end{notation}

Let $M$ be a manifold and let $N\subset M$ be a submanifold.
Let $\nu^N=\nu(M,N)$ be the normal bundle of $N$ in $M$ and identify $N$ with the zero section of $\nu^N$.

For another manifold $M'$, a submanifold $N'\subset M'$, and a map $f:M\to M'$ taking $N$ to $N'$, let $\nu(f):\nu(M,N)\to\nu(M',N')$ be the \emph{linear approximation} of $f$. In \cite{bursztyn2019splitting} it is shown that if $\E$ is a vector field tangent to $N$, the linear approximation $\nu$ can be used to obtain a vector field $\nu(\E)$ on $\nu^N$ with the property that the local flow of $\nu(\E)$ is the linear approximation of the local flow of $\E$.

\begin{definition}
    A \textbf{tubular neighbourhood} of $N\subset M$ consists of a conical open neighbourhood $O\subset \nu^N$ of the zero section and an embedding $\Psi:O\to M$ taking the zero section $N\subset \nu^N$ to $N\subset M$ such that the induced map
    \begin{equation*}
        \nu(\Psi):\nu^N\simeq \nu(O,N) \to \nu(M,N)=\nu^N
    \end{equation*}
    is the identity.

    A tubular neighbourhood is \textbf{complete} if $O=\nu^N$.
\end{definition}

\begin{definition}
    Let $E\to M$ be a vector bundle and denote the fiberwise multiplication by $t\in \R$ by $m^t:E\to E$. The \textbf{Euler vector field on $E$} is the vector field $\E_E$ with flow
    \begin{equation*}
        \Phi_{\E_E}^t = m_{\exp(t)}:E\to E.
    \end{equation*}
\end{definition}

\begin{definition}[{\cite[Definition~3.1]{MEINRENKEN2021224}}]
    An \textbf{Euler-like vector field along $\mathbf{N}$} is a vector field $\E$, defined on a neighbourhood of $N$ in $M$, tangent to $N$, and such that $\nu(\E)$ is the Euler vector field on $\nu(M,N)$.
\end{definition}

\begin{remark}
    We do not require an Euler-like vector field to be defined on all $M$. We also do not require completeness of $\E$ or completeness of the tubular neighbourhood.
\end{remark}

\begin{thm}[\cite{bursztyn2019splitting,MEINRENKEN2021224}]\label{thm:euler_like_tubular}
    Let $\E_M$ be an Euler-like vector field along $N$. Then there exists a unique maximal tubular neighbourhood embedding $\Psi:O\to M$ such that $\E_M\sim_{\Psi}\E_{\nu^N}$.

    Moreover, the open set $\Psi(O)\subset M$ is given by
    \begin{equation*}
        \{p\in M : \lim_{t\to-\infty}\Phi_{\E_M}^t(p) \text{ exists and is in }N\}.
    \end{equation*}

    If $\E_M$ is complete, then the tubular neighbourhood is complete.
\end{thm}

\begin{remark}\label{remark:maximality_of_tubular_nbhd_induced_by_euler_like}
    The maximality in \Cref{thm:euler_like_tubular} is in the following sense. For another tubular neighbourhood embedding $\Psi':O'\to M$ such that $\E_M\sim_{\Psi'}\E_{\nu^N}$, we have $O'\subset O$ and ${\Psi\big\lvert_{O'} = \Psi'}$.
\end{remark}

\begin{definition}\label{def:induced_multiplication_by_scalar}
    Let $\E$ be an Euler-like vector field along $N$ and let $(O, \Psi)$ be the induced tubular neighbourhood embedding. For all $t\in[0,1]$ define the \textbf{induced multiplication by scalars} $m_{\E}^t:\Psi(O) \to \Psi(O)$ by
    \begin{equation*}
        m_{\E}^t = \Psi \circ m^t \circ \Psi^{-1}.
    \end{equation*}
\end{definition}

\begin{proposition}\label{proposition:m_t_and_log_flow}
    For $t>0$ we have
    \begin{equation*}
        m_{\E}^t = \Phi_{\E}^{\log(t)}.
    \end{equation*}
    Therefore, $\Phi_{\E}^{\log(t)}:\Psi(O) \to \Psi(O)$ can be smoothly extended to $t=0$.
\end{proposition}

\subsection{Constructions with Euler-like vector fields}\label{subsection:constructions_with_euler_likes}

\begin{lemma}\label{lemma:euler_like_deriv}
    A vector field $\E$ being Euler-like is equivalent to the following property --- for all $f\in C^\infty(M)$ vanishing on $N$, the function $f - {\L}_{\E}f$ vanishes to order $2$ on $N$.
\end{lemma}

\Cref{lemma:euler_like_deriv} implies that being Euler-like along $N$ is a local condition at $N$. The following lemma follows from this observation.


\begin{lemma}[Convexity of Euler-like vector fields]\label{lemma:euler_like_convex}
    Let $\E_1,\dots,\E_k$ be Euler-like vector fields along $N$ and let $\varphi_1,\dots,\varphi_k$ be a partition of unity.
    Then $\sum_{i=1}^k \varphi_i\cdot \E_i$ is also Euler-like along $N$.
\end{lemma}

\begin{lemma}\label{lemma:closed_open_sets_euler}
    Let $N\subset M$ be a submanifold, $U\subset M$ an open subset, and $K\subset U$ a closed subset. Let $\E$ be an Euler-like vector field along $N$, inducing a tubular neighbourhood $\Psi:O \to M$.
    Then there exists a smooth function $\varphi:\Psi(O)\to [0,1]$ that is identically $1$ on a neighbourhood of $N$, and such that the vector field $\widetilde{\E}\coloneq \varphi\cdot \E$ satisfies
    \begin{enumerate}
        \item\label{property:closed_open_euler_like} $\widetilde{\E}$ is Euler-like along $N$;
        \item\label{property:closed_open_complete} $\widetilde{\E}$ induces a complete tubular neighbourhood $\widetilde{\Psi}:\nu^N\to M$ with $\widetilde{\Psi}(\nu^N) \subset \Psi(O)$;
        \item\label{property:closed_open_contained} if $K$ intersects a fiber of $m_{\widetilde{\E}}^0:\widetilde{\Psi}(\nu^N) \to N$, then the whole fiber is contained in $U$, i.e.,
        \begin{equation*}
            {\left(m_{\widetilde{\E}}^0\right)}^{-1}\left( m_{\widetilde{\E}}^0\left(K \cap \Psi(\nu^N)\right)\right) \subset U \cap \Psi(\nu^N).
        \end{equation*}
    \end{enumerate}
\end{lemma}

