\begin{proof}
    Let $\norm{\cdot}$ be any fiber-wise norm on $\nu^N$, and for $n\in N$, denote by $B(n, r) \subset \nu^N_n$ the ball of radius $r$ around $n$ in the fiber $\nu^N_n$. Set $U_{\nu^N} \coloneq \Psi^{-1}(U \cap \Psi(O))$ and $K_{\nu^N} \coloneq \Psi^{-1}(K \cap \Psi(O))$.

    Let $f_{N\cap U}:\left(N\cap \Psi^{-1}(U)\right) \to \R_{>0}$ be a smooth function with
    \begin{equation*}
        B\left(n, f_{N \cap U}(n)\right) \subset O \cap U_{\nu^N},\qquad \forall n\in\left(N\cap U_{\nu^N}\right),
    \end{equation*}
    let $f_{N \setminus K}: \left(N \setminus K_{\nu^N}\right) \to \R_{>0}$ be a smooth function with
    \begin{equation*}
        B\left(n, f_{N \setminus K}(n)\right) \subset O \setminus K_{\nu^N}, \qquad \forall n\in\left(N \setminus K_{\nu^N}\right),
    \end{equation*}
    and let $g:N\to [0,1]$ be a smooth bump function with
    \begin{enumerate}[(a)]
        \item $g\lvert_{N\cap K_{\nu^N}} \equiv 1$ and
        \item $g\lvert_{N \setminus U_{\nu^N}} \equiv 0$.
    \end{enumerate}

    Define $f:N \to \R_{>0}$ by
    \begin{equation*}
        f = g\cdot f_{N\cap U} + (1-g)\cdot f_{N \setminus K}
    \end{equation*}
    which is a smooth positive function on $N$. We verify in the following that it satisfies
    \begin{enumerate}
        \item\label{property:contained_in_O} $B(n, f(n)) \subset O$;
        \item\label{property:f_ball} for all $n\in N$, if $K_{\nu^N} \cap B(n, f(n)) \neq \emptyset$ then $B(n, f(n)) \subset U_{\nu^N}$.
    \end{enumerate}

    Property \cref{property:contained_in_O} holds because $f$ is a convex combination $f_{N\cap U}, f_{N \setminus K}$. For the second property, let $q\in K_{\nu^N} \cap B(n, f(n))$. Then either $f_{N \setminus K}(n)$ is not defined, or
    \begin{equation*}
        f_{N \setminus K}(n) < \norm{q} < f(n)
    \end{equation*}
    by definition of $f_{N \setminus K}$. It follows that $f_{N\cap U}(n)$ is defined and
    \begin{equation*}
        \norm{q} < f(n) \leq f_{N\cap U}(n),
    \end{equation*}
    which implies that $B(n, f(n)) \subset B\left(n, f_{N \cap U}(n)\right)$. But by definition of $f_{N \cap U}$ we have
    \begin{equation*}
        B\left(n, f_{N \cap U}(n)\right) \subset U_{\nu^N},
    \end{equation*}
    so $B(n, f(n)) \subset B\left(n, f_{N \cap U}(n)\right) \subset U_{\nu^N}$.

    Now let $h:\R_{\geq 0} \to [0,1]$ be a smooth function that is identically $1$ on $[0,\nicefrac{1}{3}]$ and identically $0$ on $[\nicefrac{2}{3}, \infty)$, and define
    \begin{equation*}
        \varphi_{\nu^N}(q)\coloneq h\left(\frac{\norm{q}}{(f\circ m_0)(q)}\right)
    \end{equation*}
    and
    \begin{equation*}
        \widetilde{\E}_{\nu^N} \coloneq \varphi_{\nu^N} \cdot \E_{\nu^N}.
    \end{equation*}
    The vector field $\widetilde{\E}_{\nu^N}$ is defined on $O$, complete (see \cite[Lemma~2.21]{zimhony2024commutative} for proof of a similar case), Euler-like along $N\subset \nu^N$, and induces a complete tubular neighbourhood embedding $\widetilde{\Psi}_{\nu^N}:\nu^N \to O$ such that for all $n\in N$,
    \begin{equation*}
        \widetilde{\Psi}_{\nu^N}(\nu^N_n) \subset B(n, f(n)) \subset \nu^N_n.
    \end{equation*}
    Property \cref{property:f_ball} of $f$ implies that
    \begin{equation*}
        {\left(m_{\widetilde{\E}_{\nu^N}}^0\right)}^{-1}\left( m_{\widetilde{\E}_{\nu^N}}^0\left(K_{\nu^N} \cap \widetilde{\Psi}_{\nu^N}(\nu^N)\right)\right) \subset U_{\nu^N} \cap \widetilde{\Psi}_{\nu^N}(\nu^N).
    \end{equation*}

    Let $\varphi=\varphi_{\nu^N}\circ \Psi^{-1}$ and note that $\widetilde{\E}\coloneq \varphi\cdot \E$ is the  pushforward of $\widetilde{\E}_{\nu^N}$ by $\Psi$. It is defined on $\Psi(O)$, Euler-like vector along $N\subset M$, and induces a complete tubular neighbourhood $\widetilde{\Psi}:\nu^N\to M$ with
    \begin{equation*}
        \widetilde{\Psi}= \Psi\circ \widetilde{\Psi}_{\nu^N}.
    \end{equation*}
    This proves properties \cref{property:closed_open_euler_like} and \cref{property:closed_open_complete}. Property \cref{property:closed_open_contained} follows from the same property of $\widetilde{\E}_{\nu^N}$ in $\nu^N$ and the fact that $\widetilde{\E}, \widetilde{\E}_{\nu^N}$ are $\Psi$-related.
\end{proof}

\subsection{Concrete tubular neighbourhood}\label{subsection:concrete_tubular_neighbourhood}

\begin{lemma}\label{lemma:normal_bundle_realization}
    Let $\E$ be an Euler-like vector field along $N$, inducing a tubular neighbourhood embedding $\Psi:O\to M$. Let $m^t_{\E}:\Psi(O) \to \Psi(O)$ be the multiplication by scalars as in \Cref{def:induced_multiplication_by_scalar}.
    Then there is an induced isomorphism of vector bundles over $N$
    \begin{equation*}
        \rho:\nu^N \xrightarrow{\sim} \ker\left(Dm_\E^0\Big\lvert_N\right) \subset TM\Big\lvert_N
    \end{equation*}
    and a splitting
    \begin{equation*}
        TM\Big\lvert_{N} = TN \oplus \ker\left(Dm_\E^0\Big\lvert_N\right) \simeq TN \oplus \nu^N.
    \end{equation*}

    Restricted to $O\subset \nu^N$, the map $\rho:\nu^N \to TM\Big\lvert_{N}$ takes the form
    \begin{equation*}
        v \mapsto \frac{d}{dt}\bigg\lvert_0 \left(\left( m_{\E}^t \circ \Psi\right)(v)\right).
    \end{equation*}
\end{lemma}

\begin{proof}
    We use the partition $TE\Big\lvert_N = TN \oplus E$ for a vector bundle $E\to N$ given by
    \begin{equation*}
        v \mapsto \frac{d}{dt}\bigg\lvert_0 m^t(v) = \lim_{t\to 0} \frac{1}{t} \left(\E_E \circ m^t\right)(v)
    \end{equation*}
    and identify $O$ with $\Psi(O)$. Since $\E$ and $\E_{\nu^N}$ are $\Psi$-related, the result follows.

    For $v\notin O$, we first multiply $v$ by a small enough $t$ such that $m^t(v)\in O$, then use the above map and multiply by $\frac{1}{t}$ in $TM\Big\lvert_N$.
\end{proof}

\begin{remark}
    For $v\in O$, we have
    \begin{align*}
        \rho(v) =& D\Psi \left(\frac{d}{dt}\bigg\lvert_0 m^t(v)\right) \\
        =& D\Psi \left(\lim_{t\to 0} \frac{1}{t} \left(\E_{\nu^N} \circ m^t\right)(v)  \right) \\
        =& \frac{d}{dt}\bigg\lvert_0 \left(\left( m_{\E}^t \circ \Psi\right)(v)\right) \\
        =& \lim_{t\to 0} \frac{1}{t} \left(\E \circ m_{\E}^t \circ \Psi\right)(v).
    \end{align*}
\end{remark}

\begin{definition}\label{definition:concrete_tubular_neighbourhood}
    The image $\nu^N_\E \coloneq \rho(\nu^N) = \ker\left(Dm_\E^0\Big\lvert_N\right)\subset TM\Big\lvert_N$ of the embedding $\rho$ from \Cref{lemma:normal_bundle_realization} is the \textbf{concrete normal bundle induced by $\mathbf{\E}$}.

    Let $O_\E = \rho(O) \subset TM\Big\lvert_N$. Define an embedding $\psi:O_\E \to \Psi(O)$ by
    \begin{equation*}
        \psi = \left(\Psi\circ \rho^{-1}\right).
    \end{equation*}
    The pair $(O_\E, \psi)$ is the \textbf{concrete tubular neighbourhood embedding induced by $\mathbf{\E}$}.
\end{definition}
\begin{lemma}\label{lemma:concrete_tubular_inverse}
    The map $\psi^{-1}: \psi(O_\E) \to O_\E$ is given by
    \begin{equation*}
        q \mapsto \frac{d}{dt}\bigg\lvert_0 \left(m_{\E}^t(q)\right) = \lim_{t\to 0} \frac{1}{t} \left(\E \circ m_{\E}^t\right)(q).
    \end{equation*}
\end{lemma}

\begin{remark}
    In \Cref{lemma:differential_of_concrete_tubular_inverse} we give an explicit expression for the differential
    \begin{equation*}
        D\psi^{-1}:T\left(\psi(O_{\E}) \right) \to TO_{\E}
    \end{equation*}
    of $\psi^{-1}$.
\end{remark}

\begin{lemma}\label{lemma:Gamma_related_concrete_diffeomorphism}
    For $i=0,1$, let $N_i\subset M_i$ be submanifolds. Let $\E_i$ be Euler-like vector fields along $N_i$ defined on open sets $U_i$, and let $\psi_i:O_{\E_i}^{N_i}\to U_i$ be the concrete tubular neighbourhood embeddings induced by $\E_i$.
    Let $\G:U_0 \to U_1$ be a diffeomorphism such that
    \begin{enumerate}
        \item $\G(N_0) = N_1$ and
        \item $\E_0, \E_1$ are $\G$-related.
    \end{enumerate}
    Then
    \begin{equation*}
        D\G\big\lvert_{N_0}\left(O_{\E_0}^{N_0}\right) = O_{\E_1}^{N_1}
    \end{equation*}
    and the following diagram commutes, with all arrows diffeomorphisms,
    \[\begin{tikzcd}
        & {\psi_0\left(O_{\E_0}^{N_0}\right)}  && {\psi_1\left(O_{\E_1}^{N_1}\right)} \\
        {TM_0\Big\lvert_{N_0}} & {O_{\E_0}^{N_0}}
        && {O_{\E_1}^{N_1}} & {TM_1\Big\lvert_{N_1}}
        \arrow["{\G}", from=1-2, to=1-4]
        \arrow["{\psi_0^{-1}}", from=1-2, to=2-2]
        \arrow["{\psi_1^{-1}}"', from=1-4, to=2-4]
        \arrow["\supset"{description}, phantom, from=2-2, to=2-1]
        \arrow["{D\G\big\lvert_{N_0}}", from=2-2, to=2-4]
        \arrow["\subset"{description}, phantom, from=2-4, to=2-5].
    \end{tikzcd}\]
\end{lemma}
\begin{proof}
    The assumption that $\G$ is a diffeomorphism and that $\E_0, \E_1$ are $\G$-related implies that for all $t\in[0,1]$ we have
    \begin{equation*}
        m_{\E_1}^t \circ \G = \G \circ m_{\E_0}^t,
    \end{equation*}
    so taking $\frac{d}{dt}\Big\lvert_0$ and using \Cref{lemma:concrete_tubular_inverse} yields the result.
\end{proof}

\begin{lemma}\label{lemma:differential_of_diffeomorphism_from_concrete_tubulars}
    For $i=0,1$ let $N_i\subset M_i$ be submanifolds. Let $\E_i$ be Euler-like vector fields along $N_i$ and let $\psi_i:O_{\E_i}^{N_i}\to M_i$ be the concrete tubular neighbourhood embeddings induced by $\E_i$. Let $g:N_0 \to N_1$ be a diffeomorphism and
    \begin{equation*}
        G_\nu:\nu_{\E_0}^{N_0} \to \nu_{\E_1}^{N_1}
    \end{equation*}
    a vector bundle isomorphism over $g$. Denote by $\G$ the diffeomorphism of neighbourhoods of $N_i$ defined by
    \[\begin{tikzcd}
        & {\psi_0\left(G_\nu^{-1}\left(O_{\E_0}^{N_0}\right)\cap O_{\E_0}^{N_0}\right)} && {\psi_1\left(O_{\E_1}^{N_1}\right)} \\
        {TM_0\Big\lvert_{N_0}} & {G_\nu^{-1}\left(O_{\E_0}^{N_0}\right)\cap O_{\E_0}^{N_0}} && {O_{\E_1}^{N_1}} & {TM_1\Big\lvert_{N_1}}
        \arrow["\G", dashed, from=1-2, to=1-4]
        \arrow["{\psi_0^{-1}}", from=1-2, to=2-2]
        \arrow["\supset"{description}, draw=none, from=2-2, to=2-1]
        \arrow["{G_\nu}", from=2-2, to=2-4]
        \arrow["{\psi_1}"', from=2-4, to=1-4]
        \arrow["\subset"{description}, draw=none, from=2-4, to=2-5].
    \end{tikzcd}\]
    Then $D\G\big\lvert_{N_0} = Dg \oplus G_\nu$.
\end{lemma}
\begin{proof}
    The identity $D\G\big\lvert_{N_0} = Dg \oplus G_\nu$ is local around points in $N_0$ and can be calculated in local coordinates.
\end{proof}

\section{Extending tangent bundle isomorphisms to diffeomorphisms}\label{section:extension_thm_proof}

In this section we prove \Cref{thm:main_diffeomorphism}, as follows.

In \Cref{subsection:diffeo_thm_toppological_lemmas} we state and prove topological lemmas used in the argument. In \Cref{subsection:diffeo_thm_proof_strategy} we reduce the proof of \Cref{thm:main_diffeomorphism} to the construction of an extension to a single higher stratum. In \Cref{subsection:extending_to_stratum} we construct such an extension to a single higher stratum. This construction is based on the key \Cref{proposition:properties_of_constructed_euler_like}, which we prove in \Cref{subsection:flow_prop_proof}.

\subsection{Topological lemmas}\label{subsection:diffeo_thm_toppological_lemmas}

We use Notations \labelcref{notation:manifold_dimension} and \labelcref{notation:strata_skeleton}.

\begin{lemma}[{\cite[Lemma~4.6]{zimhony2024commutative}}]\label{lemma:convenient_open_sets_for_strat}
    Let $(A,\S)\subset M$ be a stratified subspace, smoothly locally trivial with conical fibers. Then there exists a collection of open sets
    \begin{equation*}
        \{W^{X} \subset M\}_{X\in\S}
    \end{equation*}
    satisfying
    \begin{enumerate}
        \item for $X\in\S^d$ we have $X\subset W^{X^d} \subset M^{\geq d}$;
        \item the collection is locally finite;
        \item $W^{X}\cap W^{Y} \neq \emptyset$ if and only if $X,Y$ are comparable;
        \item for $X\in\S^d$, we have $\overline{W^{X}}\cap Y \cap M^{\geq d} \neq\emptyset$ if and only if $X\leq Y$;
        \item for $X\neq Y$ in $\S^d$, we have $\overline{W^{X}}\cap\overline{W^{Y}}\cap M^{\geq d} = \emptyset$.
    \end{enumerate}
\end{lemma}
\begin{notation}
    For topological spaces $A\subset B$, the closure of $A$ in $B$ is denoted $\cl_B(A)$.
\end{notation}

\begin{lemma}\label{lemma:closed_in_open_with_homeo_nbhd}
    For $i=0,1$, let $M_i$ be normal spaces, $U_i \subset M_i$ open subsets, and $Z_i\subset M_i$ closed subsets such that
    \begin{equation*}
        Z_i \subset U_i \subset M_i.
    \end{equation*}
    Let $\G:U_0\to U_1$ be a homeomorphism such that $\G(Z_0) = Z_1$.
    Then there exist neighbourhoods $V_0$ of $Z_0$ and $V_1\coloneq \G(V_0)$ of $Z_1$ such that for $i=0,1$ we have
    \begin{equation*}
        Z_i \subset V_i \subset \cl_{M_i}(V_i) \subset U_i.
    \end{equation*}
    Necessarily, $\cl_{M_1}(V_1) = \G\left(\cl_{M_0}(V_0)\right)$.
\end{lemma}
\begin{proof}
    Using normality of $M_i$, there exists open sets $W_i \subset M_i,\, i=0,1$ with
    \begin{equation*}
        Z_i \subset W_i \subset \cl_{M_i}(W_i) \subset U_i.
    \end{equation*}

    Let
    \begin{equation*}
        V_0 \coloneq W_0 \cap \G^{-1}(W_1)
    \end{equation*}
    and
    \begin{equation*}
        V_1 = \G(V_0) = \G(W_0) \cap W_1.
    \end{equation*}
    Since $\G:U_0\to U_1$ is a homeomorphism, $V_i$ are open neighbourhoods of $Z_i$. By construction $\cl_{M_i}(V_i) \subset \cl_{M_i}(W_i)$ so the closures $\cl_{M_i}(V_i)$ are contained in $U_i$.
    It follows that
    \begin{equation}\label{equation:closure_in_U_i_and_M_i}
        \cl_{M_i}(V_i) = \cl_{U_i}(V_i).
    \end{equation}

    Since $\G:U_0\to U_1$ is a homeomorphism we have
    \begin{equation*}
        \cl_{U_1}(V_1) = \G\left(\cl_{U_0}(V_0)\right)
    \end{equation*}
    so equation~\eqref{equation:closure_in_U_i_and_M_i} implies
    \begin{equation*}
        \cl_{M_1}(V_1) = \G\left(\cl_{M_0}(V_0)\right).
    \end{equation*}
\end{proof}

\subsection{Proof of Theorem~\ref{thm:main_diffeomorphism}}\label{subsection:diffeo_thm_proof_strategy}

Let $\left(A_i, \S_i\right)\subset M_i$ for $i=0,1$ be stratified subspaces of manifolds, smoothly locally trivial with conical fibers. Let $g:\left(A_0, \S_0\right) \to \left(A_1, \S_1\right)$ be a stratified diffeomorphism and let
\begin{equation*}
    G:TM_0\Big\lvert_{A_0} \to TM_1\Big\lvert_{A_1}
\end{equation*}
be a bundle isomorphism over $g$ such that
\begin{equation*}
    G\big\lvert_{T^ZA_0} = D^Zg.
\end{equation*}
We want to construct neighbourhoods $U_i$ of $A_i$ in $M_i$ for $i=0,1$ and a diffeomorphism
\begin{equation*}
    \G:U_0 \to U_1
\end{equation*}
which agrees with $g$ on $A_0$ and whose differential agrees with $G$ along $A_0$, i.e., on $TM_0\Big\lvert_{A_0}$.

Let $\{W_i^{X_i} \subset M_i\}_{X_i\in\S_i}$ for $i=0,1$ be as in \Cref{lemma:convenient_open_sets_for_strat} and denote
\begin{equation*}
    W_i^{\leq d} \coloneq \bigcup_{X_i\in \S_i^{\leq d}}W_i^{X_i}.
\end{equation*}

We construct using ascending recursion on the dimension of strata.

\subsubsection{Assumption for construction step d}\label{subsubsection:construction_assumption_diffeo}

There exist neighbourhoods $U^{\leq (d-1)}_i$ of $A^{\leq (d-1)}_i$ in $W_i^{\leq (d-1)}$ and a diffeomorphism
\begin{equation*}
    \G^{\leq (d-1)}:U^{\leq (d-1)}_0 \to U^{\leq (d-1)}_1
\end{equation*}
which agrees with $g$ on $U^{\leq (d-1)}_0 \cap A_0$ and whose differential agrees with $G$ along $U^{\leq (d-1)}_0 \cap A_0$. Note that these conditions should hold on all $U^{\leq (d-1)}_0 \cap A_0$ and not only on $A^{\leq (d-1)}_0$.

\subsubsection{Construction step d}: If $d=0$, take $U^{\leq -1}_i = \emptyset$.

By \Cref{lemma:closed_in_open_with_homeo_nbhd}, there exists a neighbourhood $V_0^{\leq (d-1)}$ of $A_0^{\leq (d-1)}$ in $M_0$ with
\begin{equation*}
    \overline{V_0^{\leq (d-1)}} \subset U^{\leq (d-1)}_0
\end{equation*}
such that $V_1^{{\leq (d-1)}} \coloneq \G^{\leq (d-1)}\left(V_0^{\leq (d-1)}\right)$ satisfies
\begin{equation*}
    \overline{V_1^{{\leq (d-1)}}} = \G^{\leq (d-1)}\left( \overline{V_0^{\leq (d-1)}} \right),
\end{equation*}
where $\overline{V_i^{{\leq (d-1)}}}$ is the closure in $M_i$. We fix such neighbourhoods $V^{\leq (d-1)}_i$.

\begin{definition}\label{def:extension_for_stratum}
    Let $X^d_0 \in \S_0^d$ and $X_1^d \coloneq g(X^d_0) \in \S_1^d$.

    \textbf{An extension for $\mathbf{\left(U^{\leq (d-1)}_i, V^{\leq (d-1)}_i, \G^{\leq d-1}, g, G \right)}$ to $\mathbf{(X^d_0, X^d_1)}$} consists of
    \begin{enumerate}
        \item neighbourhoods $U^{X^d_i}_i$ of $X^d_i$ in $W_i^{X^d_i}$;
        \item neighbourhoods $U^{\leq (d-1), X^d_i}_i \coloneq  V_i^{\leq (d-1)} \cup U^{X^d_i}_i$ of $A_i^{\leq (d-1)} \cup X_i^d$ in $M_i$;
        \item a diffeomorphism
        \begin{equation*}
            \G^{\leq (d-1), X^d_0}:U^{\leq (d-1), X^d_0}_0 \to U^{\leq (d-1), X^d_1}_1
        \end{equation*}
        that
        \begin{enumerate}
            \item agrees with $\G^{\leq (d-1)}$ on $V_0^{\leq (d-1)}$,
            \item agrees with $g$ on $U_0^{\leq (d-1), X^d_0} \cap A_0$,
            \item whose differential agrees with $G$ along $U_0^{\leq (d-1), X^d_0} \cap A_0$.
        \end{enumerate}
    \end{enumerate}
\end{definition}

Assume we have extensions for $\left(U^{\leq (d-1)}_i, V^{\leq (d-1)}_i, \G^{\leq (d-1)}, g, G\right)$ to $(X^d_0, X^d_1)$ for each $X^d_0 \in \S_0^d$ and $X_1^d \coloneq g(X^d_0) \in \S_1^d$.

Then we can define
\begin{equation*}
    U_i^{\leq d} \coloneq \bigcup_{X^d_i \in \S_i^d}U_i^{\leq (d-1), X^d_i}
\end{equation*}
and extend $\G^{\leq (d-1)}$ to
\begin{equation*}
    \G^{\leq d}: U_0^{\leq d} \to U_1^{\leq d}
\end{equation*}
by $\G^{\leq d}(q) = \G^{\leq (d-1), X^d_0}(q)$ for $q\in U^{\leq (d-1), X^d_0}_0$. This is well defined since strata of the same dimension are not comparable, so $W_i^{X^d_i}\cap W_i^{{X'}^d_i} = \emptyset$ for $X^d_i \neq {X'}^d_i$, which implies
\begin{equation*}
    \left( U^{\leq (d-1), X^d_0}_0 \cap U^{\leq (d-1), {X'}^d_0}_0\right) = V_0^{\leq (d-1)}
\end{equation*}
on which all $\G^{\leq (d-1), X^d_0}$ agree.

Because $\G^{\leq d}$ is a bijection and a local diffeomorphism, it is a diffeomorphism. Moreover, $\G^{\leq d}$ satisfies the recursion assumption for the next step $d+1$.

The following \Cref{thm:extending_to_stratum} constructs such extensions for each $X^d_0 \in \S_0^d$ and ${X_1^d \coloneq g(X^d_0)}$, hence completes the proof of \Cref{thm:main_diffeomorphism}.

\begin{thm}\label{thm:extending_to_stratum}
    With the recursion assumption of \Cref{subsubsection:construction_assumption_diffeo} and a choice of $V_i^{\leq (d-1)}$, there exists an extension
    \begin{equation*}
        \G^{\leq (d-1), X^d_0}:U^{\leq (d-1), X^d_0}_0 \to U^{\leq (d-1), X^d_1}_1
    \end{equation*}
    for $\left(U^{\leq (d-1)}_i, V^{\leq (d-1)}_i, \G^{\leq d-1}, g, G \right)$ to $(X^d_0, X^d_1)$.
\end{thm}

We prove \Cref{thm:extending_to_stratum} in the following \Cref{subsection:extending_to_stratum}.

\subsection{Extending to a single higher stratum}\label{subsection:extending_to_stratum}

Denote $X_i=X_i^d$. Our strategy to prove \Cref{thm:extending_to_stratum} is the following.
\begin{enumerate}
    \item Construct an Euler-like vector field $\E_0$ along $X_0$, tangent to higher strata, and inducing a complete concrete tubular neighbourhood embedding $\psi_0:\nu^{X_0}_{\E_0}\to W_0^{X_0}$.
    \item For $p\in X_1$, use the Whitney Extension Theorem to obtain local extensions $\G^p$ of $g$ and $G$, and define local Euler-like vector fields $\E_1^p$ as pushforwards of $\E_0$ by $\G^p$.
    \item Patch the locally defined $\E_1^p$ to an Euler-like vector field $\E_1$ along $X_1$, inducing a concrete tubular neighbourhood embedding $\psi_1:O^{X_1}_{\E_1}\to W_1^{X_1}$ with certain properties coming from the construction.
    \item Use the composition coming from the diagram
    \[\begin{tikzcd}
        {W_0^{X_0}} & {\psi_0\left(G^{-1}\left(O^{X_1}_{\E_1}\right)\right)} && {\psi_1\left(O^{X_1}_{\E_1}\right)} & {W_1^{X_1}} \\
        {\nu^{X_0}_{\E_0}} & {G^{-1}\left(O^{X_1}_{\E_1}\right)} && {O^{X_1}_{\E_1}} & {\nu^{X_1}_{\E_1}}
        \arrow["\supset"{description}, draw=none, from=1-2, to=1-1]
        \arrow["{\G^{X_0}}", dashed, from=1-2, to=1-4]
        \arrow["{{\left(\psi_0\right)}^{-1}}", from=1-2, to=2-2]
        \arrow["\subset"{description}, draw=none, from=1-4, to=1-5]
        \arrow["\supset"{description}, draw=none, from=2-2, to=2-1]
        \arrow["{G\big\lvert_{X_0}}", from=2-2, to=2-4]
        \arrow["{\psi_1}", from=2-4, to=1-4]
        \arrow["\subset"{description}, draw=none, from=2-4, to=2-5]
    \end{tikzcd}\]
    to construct the extension.
\end{enumerate}

\subsubsection{Euler-like vector field tangent to higher strata in \texorpdfstring{$M_0$}{M0}}\label{subsubsection:euler_like_tangent}

The following lemma is discussed in greater generality in~\cite[Section~4]{zimhony2024commutative}. We give a brief proof here.

\begin{lemma}\label{lemma:tangent_euler_like}
    Let $M$ be a manifold of dimension $n$ and let $(A,\S)\subset M$ be a stratified subspace, smoothly locally trivial with conical fibers. Let $X^d\in \S$ be a stratum.
    Then there exists an Euler-like vector field $\E$ along $X$ that is tangent to higher strata, i.e., $\E(y) \in T_yY$ for $Y>X$ and $y\in Y$ in the domain of $\E$.
\end{lemma}
\begin{proof}
    For each $p\in X$ let $\theta_p:U_p \to W_p$ be a conical neighbourhood of $p$ as in \Cref{def:smoothly_locally_trivial}. Let $(x_1,\ldots, x_d, y_1, \ldots, y_{n-d})$ be coordinates on $W_p$ such that $\theta_p(X\cap U_p) = \{y=0\}\cap W_p$. Write
    \begin{equation*}
        \E^p \coloneq {\left(\theta_p^{-1}\right)}_*\left(\sum_{i=1}^{n-d}y_i\partial y_i\right),
    \end{equation*}
    which is Euler-like along $X\cap U_p$ and tangent to higher strata by the definition of a conical neighbourhood.

    Using paracompactness, there exists a partition of unity $\{\varphi_{p_i}\}$ in
    \begin{equation*}
        U\coloneq \bigcup_{p\in X}U_p,
    \end{equation*}
    with $\supp{\varphi_{p_i}} \subset U_{p_i}$. The vector field
    \begin{equation*}
        \E\coloneq \sum \varphi_{p_i} \E^{p_i}
    \end{equation*}
    is defined on $U$, Euler-like along $N$, and tangent to higher strata by construction.
\end{proof}

Using \Cref{lemma:closed_in_open_with_homeo_nbhd}, there exists a neighbourhood $V_0'$ of $\overline{V_0^{\leq (d-1)}}$ in $M_0$ with
\begin{equation*}
    \overline{V_0^{\leq (d-1)}} \subset V_0' \subset \overline{V_0'} \subset U_0^{\leq (d-1)}
\end{equation*}
such that $V_1' \coloneq \G^{\leq (d-1)}\left(V_0'\right)$ satisfies
\begin{equation*}
    \overline{V_1'} = \G^{\leq (d-1)}\left( \overline{V_0'} \right).
\end{equation*}
In particular $V_1'$ also satisfies
\begin{equation*}
    \overline{V_1^{\leq (d-1)}} \subset V_1' \subset \overline{V_1'} \subset U_1^{\leq (d-1)}.
\end{equation*}
We fix such $V_i'$.

By \Cref{lemma:tangent_euler_like}, there exists an Euler-like vector field along $X_0$ in $W_0^{X_0}$ that is tangent to higher strata. Using \Cref{lemma:closed_open_sets_euler} with $K=\overline{V_0^{\leq(d-1)}}$ and $U=V_0'$, we obtain an Euler-like vector field $\E_0$, inducing a complete concrete tubular neighbourhood $\psi_0:\nu^{X_0}_{\E_0}\to W_0^{X_0}$ and a multiplication by scalars
\begin{equation*}
    m_{\E_0}^t:\psi_0(\nu_{\E_0}^{X_0}) \to \psi_0(\nu_{\E_0}^{X_0}),
\end{equation*}
as in \Cref{def:induced_multiplication_by_scalar}.
It has the following properties.

\begin{proposition}\label{proposition:good_euler_like_in_0}
    The Euler-like vector field $\E_0$ along $X_0$ in $W_0^{X_0}$, described above, satisfies
    \begin{enumerate}
        \item\label{property:euler_like_tanget_in_0} $\E_0$ is tangent to higher strata,
        \item\label{property:euler_like_open_closed} if $\overline{V_0^{\leq(d-1)}}$ intersects a fiber of $m_{\E_0}^0$ in $\psi_0(\nu^{X_0}_{\E_0})$, then the whole fiber is contained in $V_0'$, i.e.,
        \begin{equation*}
            {\left(m_{\E_0}^0\right)}^{-1}\left( m_{\E_0}^0\left(\overline{V_0^{\leq(d-1)}} \cap \psi_0(\nu^{X_0}_{\E_0})\right)\right) \subset V_0' \cap \psi_0(\nu^{X_0}_{\E_0}).
        \end{equation*}
    \end{enumerate}
\end{proposition}
\begin{proof}
    This follows from the construction.
\end{proof}

See \Cref{figure:schematics_neighbourhood} for a schematic drawing of neighbourhoods.

