\subsubsection{Local Euler-like vector fields in \texorpdfstring{$M_1$}{M1}}\label{subsubsection:local_euler_likes_in_M1}

\begin{proposition}\label{proposition:locally_defined_euler_like_in_1}
    Let $p_0\in X_0$ and $p=p_1=g(p_0)\in X_1$. Then there exist
    \begin{enumerate}
        \item neighbourhoods $U_{p_i}$ of $p_i$ in $W_i^{X_i}$ and
        \item a diffeomorphism $\G^p:U_{p_0} \to U_{p_1}$ which agrees with $g$ on $A_0\cap U_{p_0}$ and whose differential $D\G^p$ agrees with $G$ along $A_0\cap U_{p_0}$.
    \end{enumerate}

    The pushforward $\E_1^{p_1} \coloneq \G^p_*\E_0$ of $\E_0\Big\lvert_{U_{p_0}}$ by $\G^p$ is then an Euler-like vector field $\E_1^{p_1}$ along $X_1\cap U_{p_1}$, defined on $U_{p_1}$, that is $\G^p$-related to $\E_0\Big\lvert_{U_{p_0}}$.
\end{proposition}
\begin{proof}
    Let $U_{p_i}$ be neighbourhoods of $p_i$ in $W_i^{X_i}$ that can be identified, using coordinate maps, with open subsets of $\R^n$.

    Using \Cref{lemma:whitney_extension} and possibly shrinking $U_{p_i}$, we obtain a smooth map
    \begin{equation*}
        \G^p:U_{p_0} \to U_{p_1}
    \end{equation*}
    which restricts to $g$ on $A_0\cap U_{p_0}$ and whose differential restricts to $G$ along $A_0\cap U_{p_0}$. Since $D_{p_0}\G^p = G_{p_0}:T_{p_0}M_0 \to T_{p_1}M_1$ is invertible, we can further shrink $U_{p_i}$ so that $\G^p:U_{p_0} \to U_{p_1}$ is a diffeomorphism.
\end{proof}

\subsubsection{Patching to a global Euler-like vector field in \texorpdfstring{$M_1$}{M1}}\label{subsubsection:patching_to_global_euler_like}

Let
\begin{equation*}
    \E_1^{\leq (d-1)} = \G^{\leq (d-1)}_*\E_0
\end{equation*}
be the pushforward of $\E_0$ by $\G^{\leq (d-1)}$, defined on
\begin{equation*}
    \G^{\leq (d-1)}\left(\psi_0(\nu^{X_0}_{\E_0}) \cap U_0^{\leq (d-1)}\right) \subset U_1^{\leq (d-1)},
\end{equation*}
which is a neighbourhood of $X_1\cap U_1^{\leq (d-1)}$ in $U_1^{\leq (d-1)}$.

For each $p_1\in X_1\setminus \overline{V_1'}$ and $p_0 =g^{-1}(p_1)$, use \Cref{proposition:locally_defined_euler_like_in_1} to obtain $\G^{p_1}:U_{p_0}\to U_{p_1}$ and $\E_1^{p_1} = \G^{p_1}_*\E_0$. We can shrink $U_{p_i}$ so that $\overline{V_1'} \cap U_{p_1} = \emptyset$. Note that $\E_1^{p_1}$ is tangent to higher strata by construction.

The collection
\begin{equation*}
    \Big\{\G^{\leq (d-1)}\left(\psi_0(\nu^{X_0}_{\E_0}) \cap U_0^{\leq (d-1)}\right)\Big\}
    \cup {\Big\{U_{p_1}\Big\}}_{p_1\in X_1\setminus \overline{V_1'}}
\end{equation*}
covers $X_1$ in $W_1^{X_1}$. Using paracompactness, there exist a subset $I \subset X_1\setminus \overline{V_1'}$ and a partition of unity
\begin{equation*}
    \{\varphi_{\leq (d-1)}\} \cup {\{\varphi_{p_1}\}}_{p_1 \in I}
\end{equation*}
such that
\begin{enumerate}
    \item each $\varphi_{p_1}$ is supported in $U_{p_1}$, in particular vanishes on $\overline{V_1'}$;
    \item $\varphi_{\leq (d-1)}$ is supported in $U_1^{\leq (d-1)}$, and $\varphi_{\leq (d-1)} \equiv 1$ on $\overline{V_1'}$.
\end{enumerate}

Define
\begin{equation*}
    \E_1 \coloneq \varphi_{\leq (d-1)}\E_1^{\leq (d-1)} + \sum_{p_1\in I}\varphi_{p_1}\E_1^{p_1}.
\end{equation*}
It has the following properties.
\begin{proposition}\label{proposition:E_1_first_properties}
    The vector field $\E_1$, constructed above, is
    \begin{enumerate}
        \item\label{property:E_1_euler_like} Euler-like along $X_1$,
        \item\label{property:E_1_tangent_to_higher_strata} tangent to higher strata,
        \item\label{property:E_1_related_to_E_o_on_V_tag} The restrictions to $V_i'$ of $\E_i$ are $\G^{\leq (d-1)}$-related.
    \end{enumerate}
\end{proposition}
\begin{proof}
    Property \cref{property:E_1_euler_like} follows from \Cref{lemma:euler_like_convex}. Properties \cref{property:E_1_tangent_to_higher_strata} and \cref{property:E_1_related_to_E_o_on_V_tag} follow directly from the construction.
\end{proof}

Let
\begin{equation*}
    \psi_1:O_{\E_1}^{X_1} \to W_1^{X_1}
\end{equation*}
be the concrete tubular neighbourhood embedding induced by $\E_1$ and let
\begin{equation*}
    m_{\E_1}^t:\psi_1(O^{X_1}_{\E_1}) \to \psi_1(O^{X_1}_{\E_1}), \quad t\in[0,1]
\end{equation*}
be the induced multiplication by scalars.

Properties of the locally defined vector fields $\E^{p_1}_1$ from \Cref{proposition:locally_defined_euler_like_in_1} also yield the following.

\begin{proposition}\label{proposition:properties_of_constructed_euler_like}
    Restricting to $A_1 \cap \psi_1(O^{X_1}_{\E_1})$, for all $t\in [0,1]$ we have
    \begin{enumerate}
        \item \label{property:m_1_relation} $m_{\E_1}^t\Big\lvert_{A_1 \cap \psi_1(O^{X_1}_{\E_1})} = g\circ m_{\E_0}^t \circ g^{-1}$,
        \item \label{property:Dm_1_relation} $Dm_{\E_1}^t\Big\lvert_{A_1 \cap \psi_1(O^{X_1}_{\E_1})} = G\circ Dm_{\E_0}^t \circ G^{-1}$,
        \item \label{property:psi_1_relation} $\psi_1^{-1}\Big\lvert_{A_1 \cap \psi_1(O^{X_1}_{\E_1})} = G\circ \psi_0^{-1} \circ g^{-1}$,
        \item \label{property:Dpsi_1_relation} $D\psi_1^{-1}\Big\lvert_{A_1 \cap \psi_1(O^{X_1}_{\E_1})} = D^ZG\circ D\psi_0^{-1} \circ G^{-1}$.
    \end{enumerate}
\end{proposition}

We prove \Cref{proposition:properties_of_constructed_euler_like} in \Cref{subsection:flow_prop_proof}.

\subsubsection{Constructing the extension}\label{subsubsection:constructing_the_extension}

\begin{proposition}\label{proposition:concrete_neighbourhoods_G_related}
    The bundle isomorphism $G\big\lvert_{X_0}:TM_0\Big\lvert_{X_0} \to TM_1\Big\lvert_{X_1}$ restricts to a bundle isomorphism $\nu^{X_0}_{\E_0} \to \nu^{X_1}_{\E_1}$ over $g$. 
\end{proposition}
\begin{proof}
    We need to prove $G^{-1}(\nu^{X_1}_{\E_1}) \subset \nu^{X_0}_{\E_0}$.
    By \Cref{proposition:properties_of_constructed_euler_like}\cref{property:Dm_1_relation},
    \begin{equation*}
        Dm_{\E_1}^0\Big\lvert_{X_1} = G \circ Dm_{\E_0}^0\Big\lvert_{X_0} \circ G^{-1}.
    \end{equation*}
    Since $G\big\lvert_{X_0}:TM_0\Big\lvert_{X_0} \to TM_1\Big\lvert_{X_1}$ is a vector bundle isomorphism, we get
    \begin{equation*}
        G^{-1}\left(\ker\left(Dm_{\E_1}^0\Big\lvert_{X_1}\right)\right) = \ker\left(Dm_{\E_0}^0\Big\lvert_{X_0}\right).
    \end{equation*}
    It follows that
    \begin{equation*}
        G^{-1}(\nu^{X_1}_{\E_1}) = G^{-1}\left(\ker\left(Dm_{\E_1}^0\Big\lvert_{X_1}\right)\right) = \ker\left(Dm_{\E_0}^0\Big\lvert_{X_0}\right) = \nu_{\E_0}^{X_0}.
    \end{equation*}
\end{proof}

Recall that $\G^{\leq (d-1)}:U_0^{\leq (d-1)} \to U_1^{\leq (d-1)}$ is a diffeomorphism that takes $V_0^{\leq(d-1)}$ to $V_1^{\leq(d-1)}$, and the closure $\overline{V_i^{\leq(d-1)}}$ in $M_i$ is contained in $U_i^{\leq (d-1)}$.

\begin{proposition}\label{proposition:q_1_intersects_q_0_intersects}
    Let $q_1 \in U_1^{\leq (d-1)}$ and $q_0 \coloneq {\left(\G^{\leq (d-1)}\right)}^{-1}(q_1)$.
    Then
    \begin{enumerate}
        \item if $q_1\in \overline{V_1^{\leq (d-1)}} \cap \psi_1(O^{X_1}_{\E_1})$, then $q_0 \in \overline{V_0^{\leq (d-1)}} \cap \psi_0(\nu^{X_0}_{\E_0})$;
        \item if $q_1\in V_1^{\leq (d-1)} \cap \psi_1(O^{X_1}_{\E_1})$, then $q_0 \in V_0^{\leq (d-1)} \cap \psi_0(\nu^{X_0}_{\E_0})$.
    \end{enumerate}
\end{proposition}
\begin{proof}
    Assume $q_1\in \overline{V_1^{\leq (d-1)}} \cap \psi_1(O^{X_1}_{\E_1})$. The assumption $q_1\in \psi_1(O^{X_1}_{\E_1})$ implies that $\E_1(q_1)$ is defined, and either $q_1\in X_1$ or $\E_1(q_1) \neq 0$.

    If $q_1\in X_1$, then $q_0 \in X_0 \subset \psi_0(\nu^{X_0}_{\E_0})$ and $q_0\in \overline{V_0^{\leq (d-1)}}$.

    If $\E_1(q_1) \neq 0$, then since $\overline{V_1^{\leq (d-1)}} \subset V_1'$ and $\varphi_{p_i}\equiv 0$ on $\overline{V_i'}$, necessarily $\E_1^{\leq (d-1)}(q_1) \neq 0$. By the construction of $\E_1^{\leq (d-1)}$ it follows that $q_0 \in \psi_0(\nu^{X_0}_{\E_0})$. Finally,
    \begin{equation*}
        {\left(\G^{\leq (d-1)}\right)}^{-1}\left(\overline{V_0^{\leq (d-1)}}\right) = \overline{V_1^{\leq (d-1)}}
    \end{equation*}
    implies
    \begin{equation*}
        q_0 \in \overline{V_0^{\leq (d-1)}} \cap \psi_0(\nu^{X_0}_{\E_0}).
    \end{equation*}

    The proof for $V_i^{\leq (d-1)}$ is similar.
\end{proof}

\begin{proposition}\label{proposition:fibers_Gamma_relation_and_completeness}
    Let $p_1\in X_1$ and $p_0 \coloneq g^{-1}(p_1)$ and suppose that $\overline{V_1^{\leq(d-1)}}$ intersects the fiber ${\left(m_{\E_1}^0\right)}^{-1}(p_1)$ of $m_{\E_1}^0:\psi_1\left(O^{X_1}_{\E_1} \right) \to X_1$ over $p_1$. Then
    \begin{enumerate}
        \item\label{property:fiber_over_intersection_with_V_1_complete} $\nu^{X_1}_{\E_1,p_1} \cap O^{X_1}_{\E_1} = \nu^{X_1}_{\E_1,p_1}$, where $\nu^{X_1}_{\E_1,p_1}$ is the fiber of $m^0:\nu^{X_1}_{\E_1} \to X_1$ over $p_1$;
        \item\label{property:fiber_related_by_G_leq} ${\left(m_{\E_0}^0\right)}^{-1}\left( p_0\right) \subset V_0'$ and
        \begin{equation*}
            \G^{\leq (d-1)}\left({\left(m_{\E_0}^0\right)}^{-1}\left( p_0\right) \right) = {\left(m_{\E_1}^0\right)}^{-1}(p_1).
        \end{equation*}
    \end{enumerate}
\end{proposition}
\begin{proof}
    Because $m^0:O^{X_1}_{\E_1} \to X_1$ and $m^0_{\E_1}:\psi_1\left(O^{X_1}_{\E_1} \right) \to X_1$ are $\psi_1$-related,
    \begin{equation*}
        {\left(m_{\E_1}^0\right)}^{-1}(p_1) =  \psi_1(O^{X_1}_{\E_1} \cap \nu^{X_1}_{\E_1,p_1}).
    \end{equation*}
    Let
    \begin{equation*}
        q_1 \in \overline{V_1^{\leq (d-1)}} \cap \psi_1(O^{X_1}_{\E_1} \cap \nu^{X_1}_{\E_1,p_1}).
    \end{equation*}
    By \Cref{proposition:q_1_intersects_q_0_intersects}, $q_0 \coloneq {\left(\G^{\leq (d-1)}\right)}^{-1}(q_1)$ satisfies
    \begin{equation*}
        q_0 \in \overline{V_0^{\leq (d-1)}} \cap \psi_0(\nu^{X_0}_{\E_0}).
    \end{equation*}
    By \Cref{proposition:good_euler_like_in_0}\cref{property:euler_like_open_closed}, the whole fiber
    \begin{equation*}
        {\left(m_{\E_0}^0\right)}^{-1}\left( m_{\E_0}^0\left(q_0\right)\right) \subset \psi_0(\nu^{X_0}_{\E_0})
    \end{equation*}
    is contained in $V_0'$. Therefore, \Cref{proposition:E_1_first_properties}\cref{property:E_1_related_to_E_o_on_V_tag} implies that for $q_0'\in {\left(m_{\E_0}^0\right)}^{-1}\left( m_{\E_0}^0\left(q_0\right)\right)$, the $\E_0$-flow lines of $q_0'$ are contained in $V_0'$ and
    \begin{equation}\label{equation:flows_relate_intersection_with_V}
        \left(\G^{\leq (d-1)} \circ \Phi_{\E_0}^t\right)(q_0') = \left(\Phi_{\E_1}^t \circ \G^{\leq (d-1)}\right)(q_0'), \qquad q_0'\in {\left(m_{\E_0}^0\right)}^{-1}\left( m_{\E_0}^0\left(q_0\right)\right).
    \end{equation}
    In particular, using \Cref{proposition:m_t_and_log_flow} and taking $t \to -\infty$,
    \begin{equation*}
        g\left(m_{\E_0}^0(q_0)\right) = m_{\E_1}^0\left(\G^{\leq (d-1)}(q_0) \right) = m_{\E_1}^0(q_1) = p_1,
    \end{equation*}
    so that
    \begin{equation}\label{equation:q_0_in_fiber_over_p_0}
        m_{\E_0}^0(q_0) = p_0.
    \end{equation}
    By equation~\eqref{equation:flows_relate_intersection_with_V}, \Cref{thm:euler_like_tubular}, and the maximality of the tubular neighbourhood embedding $\psi_1:O^{X_1}_{\E_1} \to M_1$ (\Cref{remark:maximality_of_tubular_nbhd_induced_by_euler_like}), for every $q_0'\in {\left(m_{\E_0}^0\right)}^{-1}(p_0)$, the image $\G^{\leq (d-1)}(q_0')$ is in $\psi_1(O^{X_1}_{\E_1})$. Using \Cref{proposition:m_t_and_log_flow} and equations~\eqref{equation:flows_relate_intersection_with_V} and \eqref{equation:q_0_in_fiber_over_p_0} we obtain
    \begin{equation}\label{equation:multiplication_by_scalars_on_V_0}
        \left(\G^{\leq (d-1)} \circ m_{\E_0}^t\right)(q_0') = \left(m_{\E_1}^t \circ \G^{\leq (d-1)}\right)(q_0'), \qquad q_0'\in {\left(m_{\E_0}^0\right)}^{-1}(p_0).
    \end{equation}

    Let $u_1\in \nu^{X_1}_{\E_1,p_1}$. By \Cref{thm:euler_like_tubular} and \Cref{lemma:concrete_tubular_inverse}, $u_1\in O^{X_1}_{\E_1}$ if and only if there exists $q_1' \in W_1^{X_1}$ such that
    \begin{enumerate}[(a)]
        \item\label{condition:flows_to_p_1} $\displaystyle{\lim_{t\to 0} \Phi^{\log(t)}_{\E_1}(q_1') = p_1}$ and
        \item\label{condition:direction_of_flow_is_u_1} $\frac{d}{dt}\Big\lvert_0m^t_{\E_1}(q_1') = u_1$.
    \end{enumerate}
    By \Cref{proposition:concrete_neighbourhoods_G_related}, $G^{-1}(u_1)\in \nu^{X_0}_{\E_0}$, and in particular in the domain of $\psi_0$. We claim that
    \begin{equation*}
        q_1' \coloneq \left(\G^{\leq (d-1)} \circ \psi_0 \circ G^{-1} \right)(u_1)
    \end{equation*}
    works, i.e., satisfies conditions \ref{condition:flows_to_p_1} and \ref{condition:direction_of_flow_is_u_1}. Indeed, condition~\ref{condition:flows_to_p_1} follows from equation~\eqref{equation:multiplication_by_scalars_on_V_0} for $q_0' = \left(\psi_0 \circ G^{-1} \right)(u_1)$. For condition~\ref{condition:direction_of_flow_is_u_1}, using \Cref{lemma:concrete_tubular_inverse} and equation~\eqref{equation:multiplication_by_scalars_on_V_0} we obtain
    \begin{align*}
        \frac{d}{dt}\bigg\lvert_0\left(m^t_{\E_1}\circ \G^{\leq (d-1)} \circ \psi_0 \circ G^{-1} \right)(u_1)
        =& \frac{d}{dt}\bigg\lvert_0\left(\G^{\leq (d-1)} \circ m_{\E_0}^t \circ \psi_0 \circ G^{-1} \right)(u_1) \\
        =& \Big( G_{p_0} \circ \underbrace{\frac{d}{dt}\bigg\lvert_0 m_{\E_0}^t}_{\psi_0^{-1}} \circ \psi_0 \circ G^{-1}\Big)(u_1) \\
        =&u_1.
    \end{align*}
    This shows property \cref{property:fiber_over_intersection_with_V_1_complete}.

    Now, each $q_0' \in {\left(m_{\E_0}^0\right)}^{-1}(p_0)$ is of the form $q_0' = \psi_0(u_0)$ for $u_0\in \nu^{X_0}_{\E_0,p_0}$. Using property \cref{property:fiber_over_intersection_with_V_1_complete} and \Cref{proposition:concrete_neighbourhoods_G_related}, $G(u_0) \in O^{X_1}_{\E_1}$. Then, using the same arguments, $q_1' \coloneq \left(\psi_1\circ G\right)(u_0)$ satisfies $\G^{\leq (d-1)}(q_0') = q_1'$ and $m^0_{\E_1}(q_1') = p_1$, which proves the $\subset$ direction of property \cref{property:fiber_related_by_G_leq}. The other direction is similar.
\end{proof}

Set
\begin{align*}
    U_1^{X_1} &\coloneq \psi_1\left(O^{X_1}_{\E_1}\right), \\
    U_0^{X_0} &\coloneq \psi_0\left(G^{-1}\left(O^{X_1}_{\E_1}\right)\right),
\end{align*}
and let $\G^{X_0}:U_0^{X_0} \to U_1^{X_1}$ be the diffeomorphism coming from the composition
\[\begin{tikzcd}
    {W_0^{X_0}} & {\psi_0\left(G^{-1}\left(O^{X_1}_{\E_1}\right)\right)} && {\psi_1\left(O^{X_1}_{\E_1}\right)} & {W_1^{X_1}} \\
    {\nu^{X_0}_{\E_0}} & {G^{-1}\left(O^{X_1}_{\E_1}\right)} && {O^{X_1}_{\E_1}} & {\nu^{X_1}_{\E_1}}
    \arrow["\supset"{description}, draw=none, from=1-2, to=1-1]
    \arrow["{\G^{X_0}}", dashed, from=1-2, to=1-4]
    \arrow["{\psi_0^{-1}}", from=1-2, to=2-2]
    \arrow["\subset"{description}, draw=none, from=1-4, to=1-5]
    \arrow["\supset"{description}, draw=none, from=2-2, to=2-1]
    \arrow["{G\big\lvert_{X_0}}", from=2-2, to=2-4]
    \arrow["{\psi_1}", from=2-4, to=1-4]
    \arrow["\subset"{description}, draw=none, from=2-4, to=2-5].
\end{tikzcd}\]
The left vertical arrow in the diagram is well defined by \Cref{proposition:concrete_neighbourhoods_G_related}.

\begin{proposition}\label{proposition:Gamma_X_agrees_with_Gamma_leq_d}
    The diffeomorphisms $\G^{X_0}$ and $\G^{\leq (d-1)}$ agree on $V_0^{\leq (d-1)} \cap U_0^{X_0}$.
\end{proposition}
\begin{proof}
    Write
    \begin{align*}
        U_0' &\coloneq {\left(m_{\E_0}^0\right)}^{-1}\left(m_{\E_0}^0\left(V_0^{\leq (d-1)} \cap \psi_0(\nu^{X_0}_{\E_0}) \right) \right), \\
        U_1' &\coloneq {\left(m_{\E_1}^0\right)}^{-1}\left(m_{\E_1}^0\left(V_1^{\leq (d-1)} \cap \psi_1(O^{X_1}_{\E_1}) \right) \right).
    \end{align*}
    By \Cref{proposition:fibers_Gamma_relation_and_completeness}\cref{property:fiber_over_intersection_with_V_1_complete} and \Cref{proposition:concrete_neighbourhoods_G_related},
    \begin{equation*}
        V_0^{\leq (d-1)} \cap U_0^{X_0} = V_0^{\leq (d-1)} \cap \psi_0\left(G^{-1}\left(O^{X_1}_{\E_1}\right)\right)
        = V_0^{\leq (d-1)} \cap \psi_0(\nu^{X_0}_{\E_0}).
    \end{equation*}
    By \Cref{proposition:fibers_Gamma_relation_and_completeness}\cref{property:fiber_related_by_G_leq}, $U_0'$ is contained in the domain of $\G^{\leq (d-1)}$ and
    \begin{equation*}
        \G^{\leq (d-1)}(U_0') = U_1'.
    \end{equation*}

    Using \Cref{lemma:Gamma_related_concrete_diffeomorphism} with ${M_i = U_i'},{N_i = m_{\E_i}^0\left(U_i'\right)}$,
    and $\G = \G^{\leq (d-1)}$, we get that $\G^{X_0}$ and $\G^{\leq (d-1)}$ agree on $U_0'$. Since $V_0^{\leq (d-1)} \cap U_0^{X_0} \subset U_0'$, it follows that $\G^{X_0}$ and $\G^{\leq (d-1)}$ agree on $V_0^{\leq (d-1)} \cap U_0^{X_0}$.
\end{proof}

\begin{proposition}\label{proposition:Gamma_X_agrees_with_g_G}
    $\G^{X_0}:U_0^{X_0} \to U_1^{X_1}$ agrees with $g$ on $A_0 \cap U_0^{X_0}$ and $D\G^{X_0}$ agrees with $G$ along $A_0 \cap U_0^{X_0}$.
\end{proposition}
\begin{proof}
    Recall that $\G^{X_0}:U_0^{X_0} \to U_1^{X_1}$ is defined by
    \begin{equation*}
        \G^{X_0} =  \psi_1 \circ G \circ \psi_0^{-1}
    \end{equation*}
    so that
    \begin{equation*}
        D\G^{X_0} = D\psi_1 \circ D^ZG \circ D\psi_0^{-1}.
    \end{equation*}
    \Cref{proposition:properties_of_constructed_euler_like}\cref{property:psi_1_relation} implies
    \begin{equation*}
        \psi_1^{-1}\left(A_1 \cap U_1^{X_1} \right)
        = G\left( \psi_0^{-1}\left(A_0 \cap U_0^{X_0} \right) \right)
    \end{equation*}
    and using \Cref{proposition:properties_of_constructed_euler_like}\cref{property:psi_1_relation}-\cref{property:Dpsi_1_relation} we get that
    \begin{align*}
        \psi_1\Big\lvert_{G\left( \psi_0^{-1}\left(A_0 \cap U_0^{X_0} \right) \right)} &= g \circ \psi_0 \circ G^{-1}, \\
        D\psi_1\Big\lvert_{G\left( \psi_0^{-1}\left(A_0 \cap U_0^{X_0} \right) \right)}
        &= G \circ D\psi_0 \circ D^ZG^{-1}.
    \end{align*}
    Finally,
    \begin{align*}
        \G^{X_0}\Big\lvert_{A_0 \cap U_0^{X_0}}
        &= \psi_1\Big\lvert_{G\left( \psi_0^{-1}\left(A_0 \cap U_0^{X_0} \right) \right)} \circ {\left(G \circ \psi_0^{-1} \right)}\Big\lvert_{A_0 \cap U_0^{X_0}} \\
        &= g \circ \psi_0 \circ G^{-1} \circ G \circ \psi_0^{-1} \\
        &= g
    \end{align*}
    and
    \begin{align*}
        D\G^{X_0}\Big\lvert_{A_0 \cap U_0^{X_0}}
        &= D\psi_1\Big\lvert_{G\left( \psi_0^{-1}\left(A_0 \cap U_0^{X_0} \right) \right)} \circ {\left(D^ZG \circ D\psi_0^{-1} \right)}\Big\lvert_{A_0 \cap U_0^{X_0}} \\
        &= G \circ D\psi_0 \circ D^ZG^{-1} \circ D^ZG \circ D\psi_0^{-1} \\
        &= G.
    \end{align*}
\end{proof}

\begin{proof}[Proof of \Cref{thm:extending_to_stratum}]
Let
\begin{equation*}
    \G^{\leq (d-1), X_0}:V_0^{\leq (d-1)} \cup U_0^{X_0} \to V_1^{\leq (d-1)} \cup U_1^{X_1}
\end{equation*}
be the map defined by $\G^{X_0}$ on $U_0^{X_0}$ on and $\G^{\leq (d-1)}$ on $V_0^{\leq (d-1)}$. \Cref{proposition:Gamma_X_agrees_with_Gamma_leq_d} implies that it is well defined.
It remains to show that $\G^{\leq (d-1), X_0}$ is surjective, injective, and a local diffeomorphism.

The fact that both $\G^{\leq (d-1)}$ and $\G^{X_0}$ are diffeomorphisms implies that $\G^{\leq (d-1), X_0}$ is surjective and a local diffeomorphism.

For injectivity, since both $\G^{\leq (d-1)}$ and $\G^{X_0}$ are injective, it is enough to show the following claim: if $q_0\in V_0^{\leq (d-1)}$ and $q_1 \coloneq \G^{\leq (d-1)}(q_0) \in V_1^{\leq (d-1)} \cap U_1^{X_1}$, then $q_0 \in V_0^{\leq (d-1)} \cap U_0^{X_0}$.

Indeed, let $q_0\in V_0^{\leq (d-1)}$ and $q_1 \coloneq \G^{\leq (d-1)}(q_0)$ with $q_1 \in V_1^{\leq (d-1)} \cap U_1^{X_1}$. \Cref{proposition:q_1_intersects_q_0_intersects} implies that $q_0 \in V_0^{\leq (d-1)} \cap \psi_0(\nu^{X_0}_{\E_0})$ and by \Cref{proposition:fibers_Gamma_relation_and_completeness}\cref{property:fiber_over_intersection_with_V_1_complete} and \Cref{proposition:concrete_neighbourhoods_G_related} we have
\begin{equation*}
    V_0^{\leq (d-1)} \cap \psi_0(\nu^{X_0}_{\E_0})
    = V_0^{\leq (d-1)} \cap \psi_0\left(G^{-1}(O^{X_1}_{\E_1})\right)
    = V_0^{\leq (d-1)} \cap U_0^{X_0},
\end{equation*}
so $q_0\in V_0^{\leq (d-1)} \cap U_0^{X_0}$.
\end{proof}


\subsection{Proof of Proposition~\ref{proposition:properties_of_constructed_euler_like}}\label{subsection:flow_prop_proof}

\subsubsection{The canonical flip}

We recall some definitions and results from \cite[Subsections~(8.12-8.19)]{michor2008topics}, leading to \Cref{lemma:first_variation_vector_flow}.

Let $M$ be a manifold, $\pi_M:TM\to M$ its tangent bundle and
\begin{equation*}
    \pi_{TM}:T(TM)\to TM
\end{equation*}
its second tangent bundle. Given a chart $U\to \R^n$, we denote by $(x)$ the coordinates on $U$, by $(x;\; v_x)$ the coordinates on $TU$ and by $\left(x, v_x;\; u_x, u_{v_x}\right)$ the coordinates on $TTU$. With these coordinates, the projections $\pi_M, \pi_{TM}$ are given by dropping the last terms.

$TTM$ has another structure of a vector bundle over $TM$, with multiplication by scalars given by
\begin{equation*}
    D(m^t):TTM \to TTM
\end{equation*}
where $m^t:TM \to TM$ is the fiberwise multiplication by scalars in $TM$. In local coordinates, the multiplication by scalars takes the form
\begin{equation*}
    D(m^t)\left(x, v_x;\; u_x, u_{v_x}\right) \mapsto \left(x, tv_x;\; u_x, tu_{v_x}\right)
\end{equation*}
and the projection $D(\pi_M):TTM \to TM$ takes the form
\begin{equation*}
    D(\pi_M)\left(x, v_x;\; u_x, u_{v_x}\right) = D(m^0)\left(x, v_x;\; u_x, u_{v_x}\right) = (x;\; u_x).
\end{equation*}

\begin{definition}
    The \textbf{canonical flip} is the smooth map $\kappa_M:TTM \to TTM$ defined locally by
    \begin{equation*}
        (x, v_x;\; u_x, u_{v_x}) \mapsto (x, u_x;\; v_x, u_{v_x}).
    \end{equation*}
\end{definition}

\begin{proposition}
    This definition is well defined, i.e., not dependent on the choice of a chart.
\end{proposition}
\begin{lemma}\label{lemma:canonical_flip_properties}
    The flip $\kappa_M:TTM \to TTM$ has the following properties:
    \begin{enumerate}
        \item $\kappa_N\circ D^2f = D^2f \circ \kappa_M$ for each $f\in C^\infty(M,N)$, with $N$ another manifold.
        \item $\kappa_M\circ \kappa_M = \Id$.
        \item $\kappa_M$ is an isomorphism of vector bundles
        \begin{equation*}
            \kappa_M:(TTM, \pi_{TM}, TM) \to (TTM, D(\pi_{M}), TM).
        \end{equation*}
        \item\label{property:second_derivative_symmetry} $\kappa_M$ is the unique smooth map $TTM\to TTM$ which satisfies
        \begin{equation*}
            \frac{\partial}{\partial t}\frac{\partial}{\partial s}c(t,s) = \kappa_M\left( \frac{\partial}{\partial s}\frac{\partial}{\partial t}c(t,s)\right)
        \end{equation*}
        for $c\in C^\infty(\R^2, M)$.
    \end{enumerate}
\end{lemma}

\begin{remark}\label{remark:double_derivative_flip_relation}
    Let $F:M_1\times M_2 \to N$ be a smooth map. \Cref{lemma:canonical_flip_properties}\cref{property:second_derivative_symmetry} implies that the following diagram commutes:
    \[\begin{tikzcd}
        && TTN \\
        {TM_1\times TM_2} \\
        && TTN
        \arrow["{\kappa_N}", from=1-3, to=3-3]
        \arrow["{(v_1,v_2)\mapsto D_{v_1}D_{v_2}F}", from=2-1, to=1-3]
        \arrow["{(v_1,v_2)\mapsto D_{v_2}D_{v_1}F}"', from=2-1, to=3-3].
    \end{tikzcd}\]
\end{remark}

\begin{lemma}[{\cite[Subsection~8.19]{michor2008topics}} Equation of first variation for a vector field flow]\label{lemma:first_variation_vector_flow}
    Let $M$ be a manifold and let $\E_t$ be a time dependent vector field on $M$. Then the differential of its flow satisfies the differential equation
    \begin{equation*}
        \frac{d}{dt}\bigg\lvert_{t_0}\left(D\Phi_{\E_t}^t(v) \right) = \left(\kappa_M\circ D\E_{t_0} \circ D\Phi_{\E_{t_0}}^{t_0}\right)(v)
    \end{equation*}
    for all $v\in TM$.
\end{lemma}

\subsubsection{Technical lemmas}

\begin{lemma}\label{lemma:differential_of_concrete_tubular_inverse}
    Let $M,N,\E,O_{\E}$ and $\psi$ be as in \Cref{definition:concrete_tubular_neighbourhood}.
    The differential
    \begin{equation*}
        D\psi^{-1}: T\left(\psi(O_\E)\right) \to TO_\E
    \end{equation*}
    of $\psi^{-1}$ is given by
    \begin{equation*}
        v \mapsto \kappa_M \left(\frac{d}{dt}\bigg\lvert_0 \left(Dm_{\E}^t(v)\right)\right) = \lim_{t\to 0} \left( D\left(\frac{1}{t}\right) \circ D\E \circ Dm_{\E}^t\right)(v),
    \end{equation*}
    where $D(\frac{1}{t})$ is the differential of the smooth map
    \begin{equation*}
        \frac{1}{t}:TM\Big\lvert_N \to TM\Big\lvert_N.
    \end{equation*}
\end{lemma}
\begin{proof}
    Take the differential of $\psi^{-1}$ from \Cref{lemma:concrete_tubular_inverse} and use \Cref{remark:double_derivative_flip_relation} with the map ${m_\E:M \times \R \to M}$ to get that
    \begin{equation*}
        D\left( \frac{d}{dt}\bigg\lvert_0m_{\E}^t \right)(v)
        = \kappa_M \left(\frac{d}{dt}\bigg\lvert_0 \left(Dm_{\E}^t(v)\right)\right).
    \end{equation*}
\end{proof}

\begin{lemma}\label{lemma:differential_of_g_G_related_vector_fields}
    Let $N_i \subset M_i,\, i=0,1$ be submanifolds and let
    \begin{equation*}
        G:TM_0\Big\lvert_{N_0} \to TM_1\Big\lvert_{N_1}
    \end{equation*}
    be an isomorphism of vector bundles over a diffeomorphism $g:N_0\to N_1$. Let $U_i\subset M_i$ be neighbourhoods of $N_i$ and let
    \begin{equation*}
        \G:U_0 \to U_1
    \end{equation*}
    be a diffeomorphism that agrees with $g$ on $N_0$ and whose differential agrees with $G$ along $N_0$.
    Let $\E_0$ be a vector field on $U_0$ tangent to $N_0$ and let $\E_1=\G_*\E_0$ be the pushforward of $\E_0$ by $\G$ on $U_1$.
    Then
    \begin{equation*}
        D\E_1\Big\lvert_{N_1} = \kappa_{M_1} \circ DG \circ \kappa_{M_0} \circ D\E_0 \circ G^{-1}.
    \end{equation*}
    In particular, $D\E_1\Big\lvert_{N_1}$ is independent of $\G$.
\end{lemma}
\begin{proof}
    By definition,
    \begin{equation*}
        \E_1 = D\G\circ \E_0 \circ \G^{-1}
    \end{equation*}
    so that
    \begin{equation*}
        D\E_1 = D^2\G\circ D\E_0 \circ D\G^{-1}.
    \end{equation*}
    By the properties of the flip, we have
    \begin{equation*}
        D^2\G = \kappa_{M_1} \circ D^2\G \circ \kappa_{M_0}
    \end{equation*}
    and therefore
    \begin{equation}\label{equation:differential_of_pushforward_with_Gamma}
        D\E_1 = \kappa_{M_1}\circ D^2\G\circ \kappa_{M_0} \circ D\E_0 \circ D\G^{-1}.
    \end{equation}

    Restricting to $N_1$ we have $D\G^{-1} = G^{-1}$, so the right most term in equation~\eqref{equation:differential_of_pushforward_with_Gamma} is $G^{-1}$. It is left to replace $D^2\G$ in equation~\eqref{equation:differential_of_pushforward_with_Gamma} with $DG$.

    Since along $N_0$ we have $D\G = G$, it follows that
    \begin{equation*}
        D^2\G\Big\lvert_{T\left(TM_0\Big\lvert_{N_0}\right)} = DG
    \end{equation*}
    and thus to replace $D^2\G$ with $DG$ it is enough to show that
    \begin{equation*}
        \left(\kappa_{M_0} \circ D\E_0\right)(v) \in T\left(TM_0\Big\lvert_{N_0}\right), \qquad \forall v\in TM_0\Big\lvert_{N_0}.
    \end{equation*}
    Indeed, for a given $v\in TM_0\Big\lvert_{N_0}$, by the assumption that $\E_0$ is tangent to $N_0$, we get that
    \begin{equation*}
        D\Phi_{\E_0}^t(v) \in TM_0\Big\lvert_{N_0}.
    \end{equation*}
    So, we define $ \phi_v: (-\varepsilon, \varepsilon) \to TM_0\Big\lvert_{N_0}$ by
    \begin{equation*}
        \phi_v(t) = D\Phi_{\E_0}^t(v).
    \end{equation*}
    \Cref{lemma:first_variation_vector_flow} now implies
    \begin{align*}
        T\left(TM_0\Big\lvert_{N_0}\right) \ni \frac{d}{dt}\bigg\lvert_0\phi_v
        &= \frac{d}{dt}\bigg\lvert_0\left( D\Phi_{\E_0}^t(v) \right) \\
        &= \left( \kappa_{M_0} \circ D\E_0 \circ D\Phi_{\E_0}^0 \right) v \\
        &= \left( \kappa_{M_0} \circ D\E_0 \right) (v),
    \end{align*}
    which finishes the proof.
\end{proof}

\begin{lemma}\label{lemma:differential_of_partition_of_unity_section}
    Let $E\to M$ be a vector bundle, ${\{s_i:M \to E\}}_{1 \leq i \leq n}$ sections of $E\to M$ and ${\{\varphi_i:M \to \R\}}_{1\leq i \leq n}$ functions with
    \begin{equation*}
        \sum_{i=1}^n\varphi_i(p) = 1, \qquad \forall p\in M.
    \end{equation*}

    Let $p\in M$ with $s_1(p) = s_2(p) = \ldots = s_n(p) = e_0\in E_p$. Then the differential
    \begin{equation*}
        D_p\left(\sum_{i=1}^n \varphi_i s_i\right):T_pM \to T_{e_0}E
    \end{equation*}
    of the section $\sum_{i=1}^n \varphi_i s_i$ at $p$ satisfies
    \begin{equation*}
        D_p\left(\sum_{i=1}^n \varphi_i s_i\right) = \sum_{i=1}^n \varphi_i(p)\cdot D_ps_i.
    \end{equation*}
\end{lemma}

\begin{proof}
    Take a local trivialization $U\times E_p$ with coordinates $(x, e)$ and write $s_i(x) = (x, \tilde{s}_i(x))$. Then in local coordinates $(x, e, v_x, v_e)$ of $TE$ we get
    \begin{equation*}
        D_xs_i(v_x) = \left(x, \tilde{s}_i(x), v_x, D_x\tilde{s}_i(v_x) \right)
    \end{equation*}
    and therefore
    \begin{align*}
        D_p\left(\sum_{i=1}^n \varphi_i s_i\right)(v_x)
        &= \left(p, e_0, v_x, \sum_i\varphi_i(p)D_p\tilde{s}_i(v_x) + \sum_i(D_p\varphi_i(v_x)) \cdot \tilde{s}_i(p)\right) \\
        &= \left(p, e_0, v_x, \sum_i\varphi_i(p)D_p\tilde{s}_i(v_x) + \underbrace{D_p\left( \sum_i\varphi_i\right)}_0 (v_x) \cdot \tilde{s}_1(p)\right) \\
        &= \left(p, e_0, \sum_i \varphi_i(p) v_x, \sum_i\varphi_i(p)D_p\tilde{s}_i(v_x)\right) \\
        &= \left(\sum_{i=1}^n \varphi_i(p)\cdot D_ps_i\right)(v_x).
    \end{align*}
\end{proof}

\subsubsection{Proof of Proposition~\ref{proposition:properties_of_constructed_euler_like}}

\begin{proposition}\label{proposition:E_1_relation_on_A_1}
    \begin{equation*}
        \E_1\Big\lvert_{A_1 \cap U_1^{X_1}} = G \circ \E_0 \circ g^{-1}.
    \end{equation*}
\end{proposition}
\begin{proof}
    This follows from the construction of the local vector fields ${\{\E_1^{p_1}\}}_{p_1 \in I}$ and $\E_1^{\leq (d-1)}$ and the construction of $\E_1$ as their convex combination (\Cref{subsubsection:local_euler_likes_in_M1,subsubsection:patching_to_global_euler_like}).
\end{proof}

\begin{proposition}[\Cref{proposition:properties_of_constructed_euler_like}\cref{property:m_1_relation}]\label{proposition:m_1_relation}
    \begin{equation*}
        m_{\E_1}^t\Big\lvert_{A_1 \cap U_1^{X_1}} = g\circ m_{\E_0}^t \circ g^{-1}.
    \end{equation*}
\end{proposition}
\begin{proof}
    Recall that $m^t_{\E_i} = \Phi^{\log(t)}_{\E_i}$ for $t>0$. If we show that
    \begin{equation*}
        \Phi^s_{\E_1}\Big\lvert_{A_1 \cap U_1^{X_1}} = g \circ \Phi^s_{\E_0} \circ g^{-1}
    \end{equation*}
    for all $s\in \R$, then we can obtain the result by taking $s = \log(t)$ if $t>0$ and by taking the limit $s\to -\infty$ if $t=0$.

    By the uniqueness of the solution of a differential equation, we need to show that
    \begin{equation*}
        \frac{d}{ds}\bigg\lvert_{s_0}\left(g \circ \Phi^s_{\E_0} \circ g^{-1}\right)\Big\lvert_{A_1 \cap U_1^{X_1}}
        = \E_1\circ \left(g \circ \Phi^{s_0}_{\E_0} \circ g^{-1}\right).
    \end{equation*}
    Since $\E_0$ is tangent to strata, $\Phi_{\E_0}^s$ preserves $A_0$, so $g\circ \Phi_{\E_0}^s \circ g^{-1}$ preserves $A_1$. Therefore,
    \begin{align*}
        \frac{d}{ds}\bigg\lvert_{s_0}\left(g\circ \Phi^s_{\E_0} \circ g^{-1}\right)\Big\lvert_{A_1 \cap U_1^{X_1}}
        &= D^Zg \circ \left(\frac{d}{ds}\bigg\lvert_{s_0}\Phi^s_{\E_0}\right) \circ g^{-1} \\
        &= G \circ \E_0 \circ \Phi^{s_0}_{\E_0} \circ g^{-1} \\
        &= \left(G \circ \E_0 \circ g^{-1}\right) \circ \left( g \circ \Phi^{s_0}_{\E_0} \circ g^{-1}\right) \\
        &= \E_1\circ \left(g \circ \Phi^{s_0}_{\E_0} \circ g^{-1}\right).
    \end{align*}
\end{proof}

\begin{proposition}\label{proposition:differential_of_E_1}
    \begin{equation*}
        D\E_1\Big\lvert_{A_1 \cap U_1^{X_1}} = \kappa_{M_1} \circ D^ZG \circ \kappa_{M_0} \circ D\E_0 \circ G^{-1}.
    \end{equation*}
\end{proposition}
\begin{proof}
    For each $Y_1\in \S_1$, apply \Cref{lemma:differential_of_g_G_related_vector_fields} to the local vector fields ${\{\E_1^{p_1}\}}_{p_1 \in I}$ and $\E_1^{\leq (d-1)}$ to get that the differentials of these vector fields at the intersections of $Y_1$ with their domains agrees with
    \begin{equation*}
        \kappa_{M_1} \circ D^ZG \circ \kappa_{M_0} \circ D\E_0 \circ G^{-1}.
    \end{equation*}
    Taking the union over the strata $Y_1\in \S_1$ and using \Cref{lemma:differential_of_partition_of_unity_section} we obtain the result for $\E_1$ on all $A_1 \cap U_1^{X_1}$.
\end{proof}

\begin{proposition}[\Cref{proposition:properties_of_constructed_euler_like}\cref{property:Dm_1_relation}]\label{proposition:Dm_1_relation}
    \begin{equation*}
        Dm_{\E_1}^t\Big\lvert_{A_1 \cap U_1^{X_1}} = G\circ Dm_{\E_0}^t \circ G^{-1}.
    \end{equation*}
\end{proposition}
\begin{proof}
Similarly to the proof of \Cref{proposition:m_1_relation} and using \Cref{lemma:first_variation_vector_flow}, it is enough to prove that
\begin{equation*}
    \frac{d}{ds}\bigg\lvert_{s_0}\left(G\circ D\Phi_{\E_0}^s \circ G^{-1}\right)\Big\lvert_{A_1 \cap U_1^{X_1}}
    = \kappa_{M_1} \circ D\E_1 \circ \left(G\circ D\Phi_{\E_0}^{s_0} \circ G^{-1}\right).
\end{equation*}

Indeed, using the fact that $\Phi_{\E_1}^s$ preserves $A_1$ and \Cref{proposition:differential_of_E_1}, we get
\begin{align*}
    \frac{d}{ds}\bigg\lvert_{s_0}\left(G\circ D\Phi_{\E_0}^s \circ G^{-1}\right)\Big\lvert_{A_1 \cap U_1^{X_1}}
    = &D^ZG \circ \frac{d}{ds}\bigg\lvert_{s_0}D\Phi_{\E_0}^s \circ G^{-1} \\
    = &D^ZG \circ \kappa_{M_0} \circ D\E_0 \circ D\Phi^{s_0}_{\E_0} \circ G^{-1} \\
    = &\kappa_{M_1} \circ \left(\kappa_{M_1} \circ D^ZG \circ \kappa_{M_0} \circ D\E_0 \circ G^{-1}\right) \circ \left(G \circ D\Phi^{s_0}_{\E_0} \circ G^{-1}\right) \\
    = &\kappa_{M_1} \circ D\E_1 \circ \left(G\circ D\Phi_{\E_0}^{s_0} \circ G^{-1}\right).
\end{align*}
\end{proof}

\begin{proposition}[\Cref{proposition:properties_of_constructed_euler_like}\cref{property:psi_1_relation}]\label{proposition:psi_1_relation}
    \begin{equation*}
        \psi_1^{-1}\Big\lvert_{A_1 \cap U_1^{X_1}} = G\circ \psi_0^{-1} \circ g^{-1}.
    \end{equation*}
\end{proposition}
\begin{proof}
    Using \Cref{lemma:concrete_tubular_inverse,proposition:m_1_relation} we get
    \begin{align*}
        \psi_1^{-1}\Big\lvert_{A_1 \cap U_1^{X_1}}
        =& \frac{d}{dt}\bigg\lvert_0m^t_{\E_1} \\
        =& \frac{d}{dt}\bigg\lvert_0\left(g \circ m^t_{\E_0} \circ g^{-1}\right) \\
        =& D^Zg \circ \frac{d}{dt}\bigg\lvert_0m^t_{\E_0} \circ g^{-1} \\
        =& G\circ \psi_0^{-1} \circ g^{-1}.
    \end{align*}
\end{proof}

\begin{proposition}\label{proposition:DG_commutes_with_flip}
    \begin{equation*}
        \left( D^ZG \circ D\psi_0^{-1} \right)\Big\lvert_{A_0 \cap U_0^{X_0}}
        = \kappa_{M_1} \circ D^ZG \circ \kappa_{M_0} \circ D\psi_0^{-1}.
    \end{equation*}
\end{proposition}
\begin{proof}
    Let $q_0\in A_0 \cap U_0^{X_0}$, let $v_0\in T_{q_0}M_0$, let $p_0 = m^0_{\E_0}(q_0)$, and let $p_1 \coloneq g(p_0)$. Use \Cref{proposition:locally_defined_euler_like_in_1} to obtain a neighbourhood $U_{p_0}$ of $p_0$, a neighbourhood $U_{p_1}$ of $p_1$, and a diffeomorphism $\G^p:U_{p_0} \to U_{p_1}$ whose differential restricts to $G$ on $A_0\cap U_{p_0}$. It follows that the second differential $D^2\G^p$ agrees with $D^ZG$ on $T^Z\left(TU_{p_0}\Big\lvert_{A_0\cap U_{p_0}}\right)$, i.e.,
    \begin{equation*}
        D^2\G^p\Big\lvert_{T^Z\left(TU_{p_0}\Big\lvert_{A_0\cap U_{p_0}} \right)} = D^ZG
        :T^Z\left(TU_{p_0}\Big\lvert_{A_0\cap U_{p_0}} \right) \to T^Z\left(TU_{p_1}\Big\lvert_{A_1\cap U_{p_1}} \right).
    \end{equation*}

    By the properties of the canonical flip we have
    \begin{equation*}
        \kappa_{M_1} \circ D^2\G^p \circ \kappa_{M_0} = D^2\G^p.
    \end{equation*}
    If we prove that $\forall v_0\in TM_0\Big\lvert_{A_0 \cap U_0^{X_0}}$, both $D\psi_0^{-1}(v_0)$ and $\kappa_{M_0}\left(D\psi_0^{-1}(v_0)\right)$ are contained in $T^Z\left(TM_0\Big\lvert_{A_0 \cap U_0^{X_0}}\right)$, then we obtain
    \begin{align*}
        \left( D^ZG \circ D\psi_0^{-1} \right)\Big\lvert_{A_0 \cap U_0^{X_0}}
        &= D^2\G^p \circ D\psi_0^{-1} \\
        &= \kappa_{M_1} \circ D^2\G^p \circ \kappa_{M_0} \circ D\psi_0^{-1} \\
        &= \kappa_{M_1} \circ D^ZG \circ \kappa_{M_0} \circ D\psi_0^{-1}
    \end{align*}
    which finishes the proof.

    To show that $D\psi_0^{-1}(v_0) \in T^Z\left(TM_0\Big\lvert_{A_0 \cap U_0^{X_0}}\right)$, note that the image of $\psi_0^{-1}$ is $\nu^{X_0}_{\E_0} \subset TM_0\Big\lvert_{X_0}$ and therefore
    \begin{equation*}
        \Image(D\psi_0^{-1}) \subset T\left(TM_0\Big\lvert_{X_0}\right) \subset T^Z\left(TM_0\Big\lvert_{A_0 \cap U_0^{X_0}}\right).
    \end{equation*}

    To show that $\kappa_{M_0}\left(D\psi_0^{-1}(v_0)\right) \in T^Z\left(TM_0\Big\lvert_{A_0 \cap U_0^{X_0}}\right)$, let $v_0 \in TM_0\Big\lvert_{A_0 \cap \psi_0(\nu^{X_0}_{\E_0})}$. Recall that $\E_0$ is tangent to higher strata and therefore
    \begin{equation*}
        Dm^t_{\E_0}(v_0) \in TM_0\Big\lvert_{A_0 \cap U_0^{X_0}}, \qquad \forall t\in[0,1],
    \end{equation*}
    which implies that
    \begin{equation*}
        \frac{d}{dt}\bigg\lvert_0 \left(Dm^t_{\E_0}(v_0)\right) \in T^Z\left(TM_0\Big\lvert_{A_0 \cap U_0^{X_0}}\right).
    \end{equation*}

    By the properties of the canonical flip and \Cref{lemma:differential_of_concrete_tubular_inverse},
    \begin{align*}
        \kappa_{M_0}\left(D\psi_0^{-1}(v_0)\right)
        &= \kappa_{M_0}\left(D\left(\frac{d}{dt}\bigg\lvert_0 m^t_{\E_0}\right)(v_0)\right) \\
        &= \left(\kappa_{M_0} \circ \kappa_{M_0}\right)\left( \frac{d}{dt}\bigg\lvert_0 \left(Dm^t_{\E_0}(v_0) \right)\right) \\
        &= \frac{d}{dt}\bigg\lvert_0 \left(Dm^t_{\E_0}(v_0) \right),
    \end{align*}
    so
    \begin{equation*}
        \kappa_{M_0}\left(D\psi_0^{-1}(v_0)\right) = \frac{d}{dt}\bigg\lvert_0 \left(Dm^t_{\E_0}(v_0) \right) \in T^Z\left(TM_0\Big\lvert_{A_0 \cap U_0^{X_0}}\right).
    \end{equation*}
\end{proof}


\begin{proposition}[\Cref{proposition:properties_of_constructed_euler_like}\cref{property:Dpsi_1_relation}]
    \begin{equation*}
        D\psi_1^{-1}\Big\lvert_{A_1 \cap U_1^{X_1}} = D^ZG\circ D\psi_0^{-1} \circ G^{-1}.
    \end{equation*}
\end{proposition}
\begin{proof}
    Using \Cref{lemma:differential_of_concrete_tubular_inverse,proposition:Dm_1_relation}, for each $v\in TM_1\Big\lvert_{A_1 \cap U_1^{X_1}}$ we have
    \begin{align*}
        D\psi_1^{-1}(v)
        &= \kappa_{M_1} \left(\frac{d}{dt}\bigg\lvert_0 \left(Dm^t_{\E_1}(v)\right)\right) \\
        &= \kappa_{M_1} \left(\frac{d}{dt}\bigg\lvert_0 \left(G\circ Dm_{\E_0}^t \circ G^{-1}\right)(v)\right) \\
        &= \left(\kappa_{M_1} \circ D^ZG \right)\left(\frac{d}{dt}\bigg\lvert_0Dm_{\E_0}^t\left(G^{-1}(v) \right)\right) \\
        &= \left(\kappa_{M_1} \circ D^ZG \circ \kappa_{M_0}\right)\left(\kappa_{M_0}\left(\frac{d}{dt}\bigg\lvert_0Dm_{\E_0}^t\left(G^{-1}(v) \right)\right)\right) \\
        &= \left(\kappa_{M_1} \circ D^ZG \circ \kappa_{M_0}\right) \circ \left(D\psi_0^{-1} \circ G^{-1}\right)(v).
    \end{align*}
    \Cref{proposition:DG_commutes_with_flip} finishes the proof.
\end{proof}

\section{Relative Poincare Lemma and Moser’s trick}\label{section:moser_trick_proof}
In this section we prove \Cref{thm:moser_trick}, and then use it together with \Cref{thm:main_diffeomorphism} to prove \Cref{thm:main_symplectic}.

\begin{definition}\label{definition:smooth_weak_deformation_retraction}
    Let $M$ be manifold, $A\subset M$ a subset, and $V$ a neighbourhood of $A$ in $M$. A \textbf{smooth weak deformation retraction} of $V$ to $A$ is a smooth map
    \begin{equation*}
        R:[0,1]\times V \to V
    \end{equation*}
    so that the family of functions $r^t = R(t, \cdot)$ satisfies
    \begin{enumerate}
        \item $r^1 = \Id_V$,
        \item $r^0(V) \subset A$,
        \item\label{condition:remains_in_A} $r^t(A) \subset A$ for all $t\in [0,1]$.
    \end{enumerate}
\end{definition}

\begin{remark}\label{remark:strong_vs_weak_deformation_retraction}
    Here the word ``weak'' refers to condition \cref{condition:remains_in_A}, which allows $A$ to move within itself along the deformation. A \textbf{strong} deformation retraction is a weak deformation retraction with $r^t\Big\lvert_A = \Id_A$ for all $t\in[0,1]$.
\end{remark}

\subsection{Constructing primitive 1-forms}

\begin{notation}
    Let $M$ be a manifold. We denote the smooth $k$-forms on $M$ by $\Omega^k\left(M\right)$, the exterior derivative by $d$, the contraction by $X$ by $\i_X$, and the Lie derivative in the direction of $X$ by $\L_X$.
\end{notation}

In this subsection we prove the following lemma.

\begin{lemma}\label{lemma:existence_of_beta_which_vanish_on_B}
    Let $V$ be a manifold and $A\subset B\subset V$ closed subsets. Assume that $V$ admits a smooth weak deformation retraction $R:[0,1]\times V \to V$ to $A$ such that $B$ is an invariant subset of $R$. Let $\w_0, \w_1$ be two symplectic forms on $V$ that agree on $TM\Big\lvert_A$ and on the Zariski tangent $T^ZB$.
    Then there exists a $1$-form $\beta$ on $V$ with
    \begin{enumerate}
        \item $d\beta = \w_0 - \w_1$ and
        \item $\beta$ vanishes along $B$, i.e., $\beta\left(TV\Big\lvert_B\right) = 0$.
    \end{enumerate}
\end{lemma}

To this end, we use a version of the relative Poincar\'e Lemma, \Cref{lemma:relative_poincare}, which works for a general subset of a manifold, provided it admits a smooth weak deformation retraction from a neighbourhood. Cf. \cite{relative_poincare}.
We then use the Whitney Extension Theorem (\Cref{lemma:whitney_extension}) to deform the $1$-form obtained by the relative Poincar\'e Lemma so that it also vanishes along $B$.

\begin{lemma}[Homotopy property of the fiber integration operator {\cite[Lemma~17.9]{lee_smooth_manifolds}}]\label{lemma:homotopy_property_of_fiber_integration}
    Let $V$ be a manifold. Let $i_s:V\to [0,1] \times V$ be the inclusion at the $s$ level, let $\pi_V:[0,1] \times V \to V$ be the projection, and let
    \begin{equation*}
        {\left(\pi_V\right)}_*: \Omega^k\left([0,1] \times V\right) \to \Omega^{k-1}\left(V\right)
    \end{equation*}
    be the fiber integration operator defined by
    \begin{equation*}
        {\left(\pi_V\right)}_*\gamma = \int_{0}^{1}i_t^* \i_{\frac{\partial}{\partial t}}\gamma \,dt
    \end{equation*}
    for all $\gamma \in \Omega^k\left([0,1] \times V\right)$.
    Then for all $\gamma \in \Omega^k\left([0,1] \times V\right)$ we have
    \begin{equation*}
        i_1^*\gamma - i_0^*\gamma = {\left(\pi_V\right)}_*d\gamma + d{\left(\pi_V\right)}_*\gamma.
    \end{equation*}
\end{lemma}

\begin{lemma}[Relative Poincar\'e Lemma]\label{lemma:relative_poincare}
    Let $M$ be a manifold, $A\subset M$ a subset, and $V$ a neighbourhood of $A$ in $M$. Assume there exists a smooth weak deformation retraction $R:[0,1]\times V \to V$ of $V$ to $A$. Let $\alpha \in \Omega^k\left(V\right)$ be a closed $k$-form on $V$ that vanishes along $A$.
    Then the $(k-1)$-form
    \begin{equation*}
        \beta \coloneq {\left(\pi_V\right)}_*R^*\alpha
    \end{equation*}
    vanishes at the points of $A$ and satisfies $d\beta=\alpha$.
\end{lemma}
\begin{proof}
    By assumption, $R\circ i_1 = \Id_V$. Let $r \coloneq R\circ i_0$. For all $\alpha \in \Omega^k\left(V\right)$ we have
    \begin{equation*}
        i_1^*R^*\alpha = \alpha \text{ and } i_0^*R^*\alpha=r^*\alpha.
    \end{equation*}
    Applying \Cref{lemma:homotopy_property_of_fiber_integration} to $\gamma = R^*\alpha$ we obtain
    \begin{equation*}
        \alpha - r^*\alpha = {\left(\pi_V\right)}_*dR^*\alpha + d{\left(\pi_V\right)}_*R^*\alpha.
    \end{equation*}
    Since $\alpha$ is closed, $dR^*\alpha = R^*d\alpha = 0$. Since $\alpha$ vanishes along $A$ and $r(V) \subset A$, we get that $r^*\alpha = 0$. Therefore,
    \begin{equation*}
        \alpha = d{\left(\pi_V\right)}_*R^*\alpha
    \end{equation*}
    and we can take $\beta = {\left(\pi_V\right)}_*R^*\alpha$.

    It is left to prove that $\beta$ vanishes along $A$. This follows from its definition, the fact that $\alpha$ vanishes along $A$, and $R\left([0,1]\times A\right) \subset A$.
\end{proof}

We are now ready to prove \Cref{lemma:existence_of_beta_which_vanish_on_B}.
\begin{proof}[Proof of \Cref{lemma:existence_of_beta_which_vanish_on_B}]
    Applying \Cref{lemma:relative_poincare} to $\alpha \coloneq \w_0 - \w_1$, we obtain a 1-form $\beta'$ that vanishes along $A$ such that $d\beta' = \alpha$. By the formula for $\beta'$ in \Cref{lemma:relative_poincare} and using the facts that $\w_0, \w_1$ agree on $T^ZB$ and $R$ preserves $B$, we obtain $\beta'\Big\lvert_{T^ZB} = 0$.

    If $f:V\to \R$ satisfies $df=\beta'$ along $B$, i.e., on $TV\Big\lvert_{B}$, then
    \begin{equation*}
        \beta \coloneq \beta' - df
    \end{equation*}
    has the required properties. Indeed, $d\beta = d\beta' = \alpha$, and $\beta$ vanishes along $B$ by the assumption on $df$. So, it is left to construct such $f:V\to \R$.

    For every $p\in B$, let $U_p$ be a neighbourhood of $p$ in $V$ diffeomorphic to an open subset of $\R^n$. Define 
    \begin{equation*}
        G_p:TV\Big\lvert_{B\cap U_p} \to T_0\R \simeq \R 
    \end{equation*}
    by
    \begin{equation*}
        G_p(v) = \beta'(v),
    \end{equation*}
    which is a fiber-wise linear smooth map, and define $g_p:B\cap U_p \to \R$ by $g_p \equiv 0$.

    Using $G\big\lvert_{T^ZB} = 0 = D^Zg_p$ and \Cref{lemma:whitney_extension}, there exists $f_p:U_p \to \R$ with $f_p\Big\lvert_{B\cap U_p} \equiv 0$ and $df_p = G_p = \beta'$ along $B\cap U_p$.
    Using paracompactness, there exist a subset $I\subset B$, open sets $U_p' \subset U_p$ for each $p \in I$, and an open subset $U_{V \setminus B} \subset V \setminus B$, such that
    \begin{equation*}
        \{U_{V \setminus B} \} \cup {\{U_p'\}}_{p\in I}
    \end{equation*}
    is a locally finite cover of $V$. Let
    \begin{equation*}
        \{\varphi_{V \setminus B} \} \cup {\{ \varphi_p\}}_{p \in I}
    \end{equation*}
    be a partition of unity subordinate to this cover and define $f:V \to \R$ by
    \begin{equation*}
        f = \sum_{p\in I}\varphi_p f_p.
    \end{equation*}
    Then, at points of $B$, we obtain
    \begin{align*}
        df &= \sum_p\underbrace{f_p}_0d\varphi_p + \sum_p\varphi_p df_p \\
        &= \sum_p\varphi_p\beta' \\
        &= \beta'.
    \end{align*}
\end{proof}

\subsection{Moser's trick}

\begin{lemma}\label{lemma:flow_domain_vanish_neighbourhood}
    Let $M$ be a manifold, $A\subset M$ a subset, and ${\left(X_t\right)}_{t\in [0,1]}$ a time-dependent vector field with local flow
    \begin{equation*}
        \Phi^{t_0}_{(X_t)}:\mathcal{O} \to M,
    \end{equation*}
    where $\mathcal{O} \subset M \times \R$ is the maximal flow domain. Assume that $X_t$ vanishes at the points of $A$ for all $t$.
    Then there exists a neighbourhood $U$ of $A$ such that
    \begin{equation*}
        U \times [0,1] \subset \mathcal{O}.
    \end{equation*}
\end{lemma}
\begin{proof}
    For each $p\in A$, because $X_t$ vanishes along $A$, we have
    \begin{equation*}
        \{p\} \times [0, 1] \subset \mathcal{O}.
    \end{equation*}
    Since $\mathcal{O} \subset M \times [0,1]$ is open and $[0,1]$ is compact, there exists a neighbourhood $U_p$ of $p$ such that
    \begin{equation*}
        U_p \times [0, 1] \subset \mathcal{O}.
    \end{equation*}
    To finish, take $U = \bigcup_{p\in A}U_p$.
\end{proof}

\begin{lemma}\label{lemma:using_beta_for_moser}
    Let $V$ be a manifold, $A \subset V$ a subset, and $\w_0, \w_1$ symplectic forms on $V$. Let $\beta$ be a 1-form with $d\beta = \w_0 - \w_1$. Assume that along $A$ the $1$-form $\beta$ vanishes and $\w_1 = \w_0$.
    Then there exist neighbourhoods $U',U'' \subset V$ of $A$ and a diffeomorphism
    \begin{equation*}
        \G:U'\to U''
    \end{equation*}
    such that
    \begin{enumerate}
        \item\label{property:moser_diff_symplectic_pullback} $\G^*(\w_1) = \w_0$ and
        \item\label{property:moser_vanishes_on_vanishing_beta} $\G$ fixes the subset $\{ \beta = 0\} \cap U'$.
    \end{enumerate}
    In particular, $\G$ fixes $A$.
\end{lemma}
\begin{proof}
    Define
    \begin{equation*}
        \w_t = (1-t)\w_0 + t\w_1.
    \end{equation*}
    Then $\w_t$ is a smooth family of two-forms, non-degenerate along $A$, and hence non-degenerate on a neighbourhood of $A$. Define $\alpha \coloneq \frac{d}{dt}\w_t = \w_0 - \w_1$.

    Let ${\left(X_t\right)}_{t\in [0,1]}$ be the time-dependent vector field satisfying
    \begin{equation*}
        \i_{X_t}\w_t = -\beta
    \end{equation*}
    and let $\Phi^{t_0}_{(X_t)}$ be its flow. By \Cref{lemma:flow_domain_vanish_neighbourhood} there exists a smaller neighbourhood $U' \subset V$ of $A$ on which the map $\Phi^{1}_{(X_t)}$ is well defined. We claim that
    \begin{equation*}
        \G \coloneq \Phi^{1}_{(X_t)}:U' \to U'' \coloneq \G(U')
    \end{equation*}
    satisfies the required properties.

    For property \cref{property:moser_diff_symplectic_pullback}, we differentiate
    \begin{align*}
        \frac{d}{ds}\bigg\lvert_{t_0}{\left(\Phi^{s}_{(X_t)}\right)}^*\w_t
        &= {\left(\Phi^{t_0}_{(X_t)}\right)}^*\left(\frac{d}{dt}\bigg\lvert_{t_0}\w_t + \L_{X_{t_0}}\w_{t_0} \right) \\
        &= {\left(\Phi^{t_0}_{(X_t)}\right)}^*\left(\alpha + d\underbrace{\i_{X_{t_0}}\w_{t_0}}_{-\beta} + \i_{X_{t_0}}\underbrace{d\w_{t_0}}_0\right) \\
        &= 0
    \end{align*}
    to get that ${\left(\Phi^{t_0}_{(X_t)}\right)}^*\w_t = \w_0$ for all $t\in [0,1]$. In particular, ${\left(\Phi^1_{(X_t)}\right)}^*\w_1 = \w_0$.

    Property \cref{property:moser_vanishes_on_vanishing_beta} follows from the fact that $X_t$ vanishes on $\{ \beta = 0\} \cap U'$.
\end{proof}

\subsection{Proof of Theorem \ref{thm:moser_trick}}

\begin{proof}[Proof of \Cref{thm:moser_trick}]
    By \Cref{lemma:existence_of_beta_which_vanish_on_B}, there exists a $1$-form $\beta$ which vanishes along $B$ and such that $d\beta = \w_0 - \w_1$. \Cref{lemma:using_beta_for_moser} therefore gives the required diffeomorphism.
\end{proof}

\begin{remark}\label{remark:mosers_trick_discussion}
    The following \Cref{example:weak_moser_trick_differential} shows that the differential of the diffeomorphism constructed in the proof of \Cref{thm:moser_trick} does not necessarily restrict to the identity along $A$.

    However, if we further assume that the smooth deformation retraction is strong,  then ($A$ is necessarily a submanifold and) we prove in \Cref{appendix:strong_deformation_retraction_moser} that the differential of the diffeomorphism constructed in the proof of \Cref{thm:moser_trick} restricts to the identity along $A$.
\end{remark}

\begin{example}\label{example:weak_moser_trick_differential}
    Let $A=B=\R_x = \{y=0\} \subset \R^2_{x,y}$, and take
    \begin{equation*}
        \w_0 = dx\wedge dy,\quad \w_1 = (1 + y)dx\wedge dy
    \end{equation*}
    so that $\alpha = \w_1 - \w_0 = -ydx\wedge dy$. Take the smooth weak deformation retraction
    \begin{equation*}
        r^t(x,y) = (tx, ty).
    \end{equation*}
    Then the fiber integration construction yields
    \begin{align*}
        \beta(x,y)(v) &= \int_{0}^{1}i_t^*(x,y)\left(\i_{\frac{\partial}{\partial t}}R^*\alpha\right) \,dt \\
        &= \int_{0}^{1} \alpha\left(r^t(x,y)\right)\left(\frac{d}{ds}\bigg\lvert_t r^s(x,y), D_{(x,y)}r^t(v)\right) dt \\
        &= \int_{0}^{1} \left(-ty dx \wedge dy\right)\left(x \partial x + y \partial y, tv\right)dt  \\
        &= \left(\int_{0}^{1}-t^2 dt \right)\left(xy dy - y^2dx\right)(v) \\
        &= \frac{1}{3}\left(y^2 dx - yx dy\right)(v)
    \end{align*}
    with $d\beta = \alpha$ and
    \begin{equation*}
        X_t = \frac{-y}{3(1+ty)} \left(x \partial x  + y \partial y \right).
    \end{equation*}

    We use the identification $T\R^2 \simeq \R^2 \times \R^2$. Define $f(t, y) = \frac{-y}{3(1+ty)}$, so that
    \begin{equation*}
        X_t(x,y) = \begin{pmatrix}
            xf(t,y) \\
            yf(t,y)
        \end{pmatrix}.
    \end{equation*}
    Since $f(t, 0) =0$ and $\frac{\partial f}{\partial y}(t,0)= \frac{-1}{3}$, we obtain
    \begin{equation*}
        D_{(x,0)}X_t
        = \begin{pmatrix}
            f(t,0) & x\frac{\partial f}{\partial y}(t,0) \\
            0 & 0\cdot\frac{\partial f}{\partial y}(t,0) + f(t,0)
        \end{pmatrix}
        = \begin{pmatrix}
            0 & \frac{-x}{3} \\
            0 & 0
        \end{pmatrix}.
    \end{equation*}

    By \Cref{lemma:first_variation_vector_flow} and the identification $T\R^2 \simeq \R^2 \times \R^2$, the differential $D_{(x,0)}\Phi_{(X_t)}^{t_0}$ at $y=0$ needs to satisfy the differential equation
    \begin{equation*}
        \frac{d}{ds}\bigg\lvert_{t_0}\left(D_{(x,0)}\Phi_{(X_t)}^{s}\right) = \begin{pmatrix}
            0 & \frac{-x}{3} \\
            0 & 0
        \end{pmatrix}D_{(x,0)}\Phi_{(X_t)}^{t_0}
    \end{equation*}
    with $D_{(x,0)}\Phi_{(X_t)}^{0} = \Id$. One can check that
    \begin{equation*}
        D_{(x,0)}\Phi_{(X_t)}^{t_0} =
        \begin{pmatrix}
            1 & \frac{-xt_0}{3} \\
            0 & 1
        \end{pmatrix}
    \end{equation*}
    is the unique solution, and in particular $ D_{(x,0)}\Phi_{(X_t)}^1 \neq \Id$ for $t>0$.
\end{example}

\subsection{Proof of Theorem~\ref{thm:main_symplectic}}
\begin{proof}[Proof of \Cref{thm:main_symplectic}]
    Apply \Cref{thm:main_diffeomorphism} with $(g,G)$ to obtain neighbourhoods $U_0,U_1$ of $A_0,A_1$, respectively, and a diffeomorphism
    \begin{equation*}
        \widetilde{\G}:U_0 \to U_1
    \end{equation*}
    that restricts to $g$ on $A_0$ and whose differential restricts to $G$ on $TM\Big\lvert_{A_0}$. Since $G$ is a symplectic bundle isomorphism, the symplectic forms $\w_0$ and $\widetilde{\G}^*\w_1$ agree along $A_0$.

    By assumption, $A_0$ is smoothly locally trivial with conical fibers. Therefore, the results of \cite{zimhony2024commutative} apply, and there exists a neighbourhood $V_0$ of $A_0$ in $U_0$ and a smooth weak deformation retraction of $V_0$ to $A_0$. Applying \Cref{thm:moser_trick} with $A=B= A_0, V= V_0$, and the forms $\w_0$ and ${\widetilde{\G}}^*\w_1$, we obtain neighbourhoods $U', U''\subset V_0$ of $A_0$ and a diffeomorphism $\G':U'\to U''$ with
    \begin{equation*}
        {\G'}^*{\widetilde{\G}}^*\w_1 = \w_0
    \end{equation*}
    and ${\G'}\Big\lvert_{A_0} = \Id$. It follows that
    \begin{equation*}
        \G \coloneq \widetilde{\G} \circ \G':U' \to \widetilde{\G}(U'')
    \end{equation*}
    is a symplectomorphism with $\G\big\lvert_{A_0} = g$.
\end{proof}

\section{Symplectic normal form for coisotropic stratified subspaces}\label{section:coisotropic_theorem}
In this section we prove \Cref{thm:main_coisotropic}. For $i=0,1$, let $\left(M_i, \w_i\right)$ be symplectic manifolds and $\left(A_i, \S_i\right)$ stratified subspaces of them, smoothly locally trivial with conical fibers. Assume that $A_i$ are coisotropic (see \Cref{def:isotropic_and_coisotropic}). Let $g:\left(A_0, \S_0\right) \to \left(A_1, \S_1\right)$ be a stratified diffeomorphism with $g^*\w_1 = \w_0$ as Zariski forms on $A_0$.
We want to construct neighbourhoods $U_i\subset M_i$ of $A_i$ and a symplectomorphism
\begin{equation*}
    \G:(U_0, \w_0) \to (U_1, \w_1)
\end{equation*}
with $\G\big\lvert_{A_0}$ = $g$.

\begin{remark}
    In the proof of \Cref{thm:main_coisotropic} we do not use \Cref{thm:main_symplectic} per se, but rather ideas from its proof. The reason is that in order to use \Cref{thm:main_symplectic} given the assumptions of \Cref{thm:main_coisotropic}, one needs to construct a symplectic bundle isomorphism $G$ over $g$ which restricts to $D^Zg$ on $T^ZA_0$. This can be done, as described below, but the construction already yields a symplectomorphism --- so using \Cref{thm:main_symplectic} is not needed.

    If one could find a simpler way to construct such a symplectic bundle isomorphism for coisotropic stratified subspaces, then it would give an alternative proof for \Cref{thm:main_coisotropic} using \Cref{thm:main_symplectic}.
\end{remark}

\subsection{Proof of Theorem~\ref{thm:main_coisotropic}}
We repeat the construction detailed in \Cref{section:extension_thm_proof} with some modifications.
For $i=0,1$, let $\{W_i^{X_i} \subset M_i\}_{X_i\in\S_i}$ be neighbourhoods of strata as in \Cref{lemma:convenient_open_sets_for_strat}, and write
\begin{equation*}
    W_i^{\leq d} \coloneq \bigcup_{X_i\in \S_i^{\leq d}}W_i^{X_i}.
\end{equation*}

We construct using ascending recursion on the dimension of strata.

\subsubsection{Assumption for construction step d}\label{subsubsection:coistropic_construction_assumption}

There exist neighbourhoods $U^{\leq (d-1)}_i$ of $A^{\leq (d-1)}_i$ in $W_i^{\leq (d-1)}$ and a symplectomorphism
\begin{equation*}
    \G^{\leq (d-1)}:U^{\leq (d-1)}_0 \to U^{\leq (d-1)}_1
\end{equation*}
which restricts to $g$ on $U^{\leq (d-1)}_0 \cap A_0$.

\subsubsection{Construction step d}

If $d=0$, take $U^{\leq -1}_i = \emptyset$. By \Cref{lemma:closed_in_open_with_homeo_nbhd}, there exists a neighbourhood $V_0^{\leq (d-1)}$ of $A_0^{\leq (d-1)}$ with
\begin{equation*}
    \overline{V_0^{\leq (d-1)}} \subset U^{\leq (d-1)}_0
\end{equation*}
such that $V_1^{{\leq (d-1)}} \coloneq \G^{\leq (d-1)}\left(V_0^{\leq (d-1)}\right)$ satisfies
\begin{equation*}
    \overline{V_1^{{\leq (d-1)}}} = \G^{\leq (d-1)}\left( \overline{V_0^{\leq (d-1)}} \right),
\end{equation*}
where the closures are in $M_i$.

\begin{definition}\label{def:symplectic_extension_for_stratum}
    Let $X^d_0 \in \S_0^d$ and $X_1^d \coloneq g(X^d_0) \in \S_1^d$.

    \textbf{A symplectic extension for $\mathbf{\left(U^{\leq (d-1)}_i, V^{\leq (d-1)}_i, \G^{\leq d-1}, g \right)}$ to $\mathbf{(X^d_0, X^d_1)}$} consists of
    \begin{enumerate}
        \item neighbourhoods $U^{X^d_i}_i$ of $X^d_i$ in $W_i^{X^d_i}$;
        \item neighbourhoods $U^{\leq (d-1), X^d_i}_i \coloneq  V_i^{\leq (d-1)} \cup U^{X^d_i}_i$ of $A_i^{\leq (d-1)} \cup X_i^d$ in $M_i$;
        \item a symplectomorphism
        \begin{equation*}
            \G^{\leq (d-1), X^d_0}:U^{\leq (d-1), X^d_0}_0 \to U^{\leq (d-1), X^d_1}_1
        \end{equation*}
        that
        \begin{enumerate}
            \item agrees with $\G^{\leq (d-1)}$ on $V_0^{\leq (d-1)}$ and
            \item agrees with $g$ on $U_0^{\leq (d-1), X^d_0} \cap A_0$.
        \end{enumerate}
    \end{enumerate}
\end{definition}

Like in \Cref{section:extension_thm_proof}, the following \Cref{thm:symplectic_extending_to_stratum} constructs such symplectic extensions for each $X^d_0 \in \S_0^d$ and ${X_1^d \coloneq g(X^d_0)}$, hence completes the proof of \Cref{thm:main_coisotropic}.

\begin{thm}\label{thm:symplectic_extending_to_stratum}
    With the recursion assumption of \Cref{subsubsection:coistropic_construction_assumption} and a choice of $V_i^{\leq (d-1)}$, there exists a symplectic extension
    \begin{equation*}
        \G^{\leq (d-1), X^d_0}:U^{\leq (d-1), X^d_0}_0 \to U^{\leq (d-1), X^d_1}_1
    \end{equation*}
    for $\left(U^{\leq (d-1)}_i, V^{\leq (d-1)}_i, \G^{\leq d-1}, g \right)$ to $(X^d_0, X^d_1)$.
\end{thm}

We prove \Cref{thm:symplectic_extending_to_stratum} in the following \Cref{subsection:symplectic_extending_to_single_stratum}.

\subsection{Extending to a single stratum}\label{subsection:symplectic_extending_to_single_stratum}
Our strategy to prove \Cref{thm:symplectic_extending_to_stratum} is similar to the one used to prove \Cref{thm:extending_to_stratum}, but with the following difference --- we do not have the symplectic bundle isomorphism $G$. This has two consequences:
\begin{enumerate}
    \item When constructing the map, we do not control the differential of it.
    \begin{itemize}
        \item As a result, we cannot use Moser's trick at the end. So, we use it inside the recursion step, and obtain a symplectomorphism instead of a diffeomorphism in each step.
    \end{itemize}
    \item We need an alternative way to obtain a normal bundle isomorphism over $g\Big\lvert_{X_0}$ for some stratum. This is where the coisotropic assumption is used.
\end{enumerate}

For $i=0,1$, let $\left(U^{\leq (d-1)}_i, V^{\leq (d-1)}_i, \G^{\leq d-1}, g \right)$ be as in \Cref{thm:symplectic_extending_to_stratum}. Let $X_i = X_i^d$.

\begin{proposition}
    There exist
    \begin{enumerate}
        \item a neighbourhood $V_0'$ of $\overline{V_0^{\leq (d-1)}}$ with
        \begin{equation*}
            \overline{V_0^{\leq (d-1)}} \subset V_0' \subset \overline{V_0'} \subset U_0^{\leq (d-1)}
        \end{equation*}
        such that $V_1' \coloneq \G^{\leq (d-1)}\left(V_0'\right)$ satisfies
        \begin{equation*}
            \overline{V_1'} = \G^{\leq (d-1)}\left( \overline{V_0'} \right);
        \end{equation*}
        \item an Euler-like vector field $\E_0$ along $X_0$ in $W_0^{X_0}$, inducing a complete concrete tubular neighbourhood
        \begin{equation*}
            \psi_0:\nu^{X_0}_{\E_0}\to W_0^{X_0}
        \end{equation*}
        with multiplication by scalars
        \begin{equation*}
            m_{\E_0}^t:\psi_0(\nu_{\E_0}^{X_0}) \to \psi_0(\nu_{\E_0}^{X_0});
        \end{equation*}
    \end{enumerate}
    such that
    \begin{enumerate}
        \item $\E_0$ is tangent to higher strata and
        \item If $\overline{V_0^{\leq(d-1)}}$ intersects a fiber of $m_{\E_0}^0$ in $\psi_0(\nu^{X_0}_{\E_0})$, then the whole fiber is contained in $V_0'$, i.e.,
        \begin{equation*}
            {\left(m_{\E_0}^0\right)}^{-1}\left( m_{\E_0}^0\left(\overline{V_0^{\leq(d-1)}} \cap \psi_0(\nu^{X_0}_{\E_0})\right)\right) \subset V_0' \cap \psi_0(\nu^{X_0}_{\E_0}).
        \end{equation*}
    \end{enumerate}
\end{proposition}
\begin{proof}
    Use the same arguments as in \Cref{subsubsection:euler_like_tangent}.
\end{proof}

\begin{proposition}
    There exists a symplectic bundle isomorphism
    \begin{equation*}
        G_{X_0}:\left(TM_0\Big\lvert_{X_0}, \w_0 \right) \to \left(TM_1\Big\lvert_{X_1}, \w_1 \right)
    \end{equation*}
    over $g\Big\lvert_{X_0}$ which
    \begin{enumerate}
        \item agrees with $D^Zg$ on $T^ZA_0\Big\lvert_{X_0}$ and
        \item agrees with $D\G^{\leq (d-1)}$ on $TM_0\Big\lvert_{X_0 \cap \overline{V_1'}}$.
    \end{enumerate}
\end{proposition}
\begin{proof}
    For $i=0,1$, the subbundles $T^ZA_i\Big\lvert_{X_i}$ are coisotropic in $TM_i\Big\lvert_{X_i}$. Given compatible almost complex structures $J_i$ on $TM_i$, we obtain decompositions
    \begin{equation*}
        TM_i\Big\lvert_{X_i} = T^ZA_i\Big\lvert_{X_i} \oplus J_i\left( {\left( T^ZA_i\Big\lvert_{X_i}\right)}^{\w_i} \right) \simeq T^ZA_i\Big\lvert_{X_i} \oplus {\left( {\left( T^ZA_i\Big\lvert_{X_i}\right)}^{\w_i} \right)}^*
    \end{equation*}
    and a symplectic bundle isomorphism $TM_0\Big\lvert_{X_0} \to TM_1\Big\lvert_{X_1}$ given by
    \begin{equation*}
        D^Zg \oplus {\left(D^Zg^{-1}\right)}^*: T^ZA_0\Big\lvert_{X_0} \oplus {\left( {\left( T^ZA_0\Big\lvert_{X_0}\right)}^{\w_0} \right)}^* \to T^ZA_1\Big\lvert_{X_1} \oplus {\left( {\left( T^ZA_1\Big\lvert_{X_1}\right)}^{\w_1} \right)}^*.
    \end{equation*}
    In particular, such a symplectic bundle isomorphism agrees with $D^Zg$ on $T^ZA_0\Big\lvert_{X_0}$.

    It remains to find compatible almost complex structures $J_i$ such that $D^Zg \oplus {\left(D^Zg^{-1}\right)}^*$ agrees with $D\G^{\leq (d-1)}$ on $TM_0\Big\lvert_{X_0 \cap \overline{V_1'}}$. Let $J_0$ be a $\w_0$-compatible almost complex structure on $TM_0$. It is enough to find a compatible almost complex structure $J_1$ on $TM_1$ such that
    \begin{equation*}
        J_1 = \G^{\leq (d-1)}_*J_0
    \end{equation*}
    on $\overline{V_1'}$.

    Let $h_0$ be the $\w_0$-compatible metric on $TM_0$ induced by $J_0$. Construct a metric $h_1$ on $TM_1$ such that
    \begin{equation*}
        h_1\Big\lvert_{\overline{V_1'}} = \G^{\leq (d-1)}_*h_0
    \end{equation*}
    and let $J_1$ be the $\w_1$-compatible almost complex structure induced by $h_1$ and the polar decomposition \cite[Lecture~2]{weinstein_lectures}. Since $h_1$ is $w_1$-compatible on $\overline{V_1'}$, the $\w_1$-compatible metric induced by $J_1$ agrees with $h_1$ on that subset. Since $\w_1, h_1$ are $\G^{\leq (d-1)}$-related to $\w_0, h_0$ on $\overline{V_1'}$, it follows that $J_1 = \G^{\leq (d-1)}_*J_0$ on $\overline{V_1'}$.
\end{proof}

The following \Cref{proposition:locally_defined_euler_like_in_1_without_G} is the analog of \Cref{proposition:locally_defined_euler_like_in_1}, which constructs locally defined Euler-like vector fields in $M_1$. The main difference is that in \Cref{proposition:locally_defined_euler_like_in_1} the bundle isomorphism $G$ was defined along $A$, whereas in \Cref{proposition:locally_defined_euler_like_in_1_without_G} we have $G_{X_0}$ that is defined only along $X_0$.

\begin{proposition}\label{proposition:locally_defined_euler_like_in_1_without_G}
    Let $p_0\in X_0$ and $p=p_1=g(p_0)\in X_1$. Then there exist
    \begin{enumerate}
        \item neighbourhoods $U_{p_i}$ of $p_i$ in $W_i^{X_i}$ and
        \item a diffeomorphism $\G^p:U_{p_0} \to U_{p_1}$ which agrees with $g$ on $A_0\cap U_{p_0}$ and whose differential agrees with $G_{X_0}$ along $X_0$.
    \end{enumerate}

    Letting $\E_1^{p_1} \coloneq \G^p_*\E_0$, we obtain an Euler-like vector field $\E_1^{p_1}$ along $X_1\cap U_{p_1}$, defined on $U_{p_1}$, that is $\G^p$-related to $\E_0\Big\lvert_{U_{p_0}}$.
\end{proposition}
\begin{proof}
    Using \Cref{lemma:stratified_spaces_locally_diffeo}, let $\theta_{p_0}:U_{p_0} \to W$ and $\theta_{p_1}:U_{p_1} \to W$ be conical neighbourhoods of $p_0, p_1$ such that $\theta_{p_1}^{-1} \circ \theta_{p_0}$ restricts to $g$ on $A_0 \cap U_{p_0}$. Take
    \begin{equation*}
        X_W \coloneq \theta_{p_0}\left(X_0 \cap U_{p_0} \right) = \theta_{p_1}\left(X_1 \cap U_{p_1} \right),
    \end{equation*}
    which by definition satisfies
    \begin{equation*}
        X_W = \left(\R^k\times \{0\}\right) \cap W \subset \R^k \times \R^{n-k}.
    \end{equation*}

    Let $(x,y)$ be coordinates on $W\subset \R_x^k\times \R_y^{n-k}$ and $(x,y,v_x,v_y)$ be coordinates on $ TW$. Define $\tau:W \to TW\Big\lvert_{X_W}$ by
    \begin{equation*}
        \tau(x,y) = (x, 0, x, y)
    \end{equation*}
    and $\sigma:TW\Big\lvert_{X_W} \to W$ by
    \begin{equation*}
        \sigma(x, 0, v_x, v_y) = (v_x, v_y).
    \end{equation*}
    Let $\G_W:W \to \R^k \times \R^{n-k}$ be the map given by the composition
    \[\begin{tikzcd}
        W & {TW\Big\lvert_{X_W}} & {TM_0\Big\lvert_{X_0}} & {TM_1\Big\lvert_{X_1}} & {TW\Big\lvert_{X_W}} & {\R^k \times \R^{n-k}}
        \arrow["\tau", from=1-1, to=1-2]
        \arrow["{D\theta_{p_0}^{-1}}", from=1-2, to=1-3]
        \arrow["{G_{X_0}}", from=1-3, to=1-4]
        \arrow["{D\theta_{p_1}}", from=1-4, to=1-5]
        \arrow["\sigma", from=1-5, to=1-6].
    \end{tikzcd}\]
    We verify that $\G_W$ has the following properties:
    \begin{enumerate}
        \item\label{property:G_W_differential} $D\G_W = D\theta_{p_1} \circ G_{X_0} \circ D\theta_{p_0}^{-1}$ on $TW\Big\lvert_{X_W}$.
        \item\label{property:G_W_diffeo} After possibly shrinking $W$, the map $\G_W:W \to \G_W(W)$ is a diffeomorphism.
        \item\label{property:G_W_preserves_A_W} $\G_W$ fixes $A_W \coloneq \theta_{p_0}\left(A_0 \cap U_{p_0} \right) = \theta_{p_1}\left(A_1 \cap U_{p_1} \right)$.
    \end{enumerate}

    Property \cref{property:G_W_differential} follows by calculation in local coordinates. Property \cref{property:G_W_diffeo} follows from the inverse function theorem.
    To prove property \cref{property:G_W_preserves_A_W}, note that by the definition of a conical neighbourhood (\Cref{def:smoothly_locally_trivial}), the subset $A_W$ is conical and therefore $\tau(A_W) \subset T^ZA_W\Big\lvert_{X_W}$. Since both $G_{X_0}$ and $D\theta_{p_1}^{-1} \circ D\theta_{p_0}$ restrict to $D^Zg$ on $T^ZA_0$, the bundle isomorphism
    \begin{equation*}
        \left(D\theta_{p_1} \circ G_{X_0} \circ D\theta_{p_0}^{-1}\right):TW\Big\lvert_{X_W} \to TW\Big\lvert_{X_W}
    \end{equation*}
    restricts to the identity on $T^ZA_W\Big\lvert_{X_W}$, and it follows that for $(x,y)\in A_W$ we have
    \begin{align*}
        \G_W(x,y)
        =& \left(\sigma \circ D\theta_{p_1} \circ G_{X_0} \circ D\theta_{p_0}^{-1}\right)\underbrace{(x, 0, x, y)}_{\in T^ZA_W\Big\lvert_{X_W}} \\
        =& \sigma(x,0,x,y) \\
        =& (x,y).
    \end{align*}
    Finally, one can check that $\G^p = \theta_{p_1}^{-1} \circ \G_W \circ \theta_{p_0}$ satisfies the required Properties.
\end{proof}

\begin{proposition}\label{proposition:E_1_properties_coisotropic}
    There exists an Euler-like vector field $\E_1$ along $X_1$, inducing a concrete tubular neighbourhood embedding
    \begin{equation*}
        \psi_1:O^{X_1}_{\E_1}\to W_1^{X_1}
    \end{equation*}
    with multiplication by scalars
    \begin{equation*}
        m_{\E_1}^t:\psi_1\left(O^{X_1}_{\E_1}\right) \to \psi_1\left(O^{X_1}_{\E_1}\right),
    \end{equation*}
    such that the following holds:
    \begin{enumerate}
        \item\label{property:E_1_tangential} $\E_1$ is tangent to higher strata.
        \item\label{property:G_d_minus_1_related} $\E_1$ and $\E_0$ are $\G^{\leq (d-1)}$-related on $V_0'$ and $V_1'$.
        \item\label{property:relation_to_E_0_on_A_1} Restricting to $A_1\cap \psi_1\left(O^{X_1}_{\E_1}\right)$ we have
        \begin{enumerate}
            \item $\E_1 = D^Zg \circ \E_0 \circ g^{-1}$,
            \item $m^t_{\E_1} = g \circ m^t_{\E_0} \circ g^{-1}$,
            \item $\psi_1^{-1} = D^Zg \circ \psi_0 \circ g^{-1}$.
        \end{enumerate}
        \item\label{property:DE_1_relates_to_DE_0} $D\E_1\Big\lvert_{X_1} = \kappa_{M_1} \circ DG_{X_0} \circ \kappa_{M_0} \circ D\E_0 \circ G_{X_0}^{-1}$.
        \item\label{property:Dm_1_relates_to_Dm_0} Restricting to $TM_1\Big\lvert_{X_1}$ we have $Dm_{\E_1}^t = G_{X_0} \circ Dm_{\E_0}^t \circ G_{X_0}^{-1}$ for all $t\in [0,1]$.
        \item\label{property:O_1_G_relates_to_nu_0} The symplectic bundle isomorphism $G_{X_0}:TM_0\Big\lvert_{X_0} \to TM_1\Big\lvert_{X_1}$ restricts to a bundle isomorphism $\nu^{X_0}_{\E_0} \to \nu^{X_1}_{\E_1}$ over $g$.
        \item\label{property:fiber_over_intersection_with_V_1_complete_coisotropic} If $\overline{V_1^{\leq(d-1)}}$ intersects the fiber ${\left(m_{\E_1}^0\right)}^{-1}(p_1)$ of $m_{\E_1}^0:\psi_1\left(O^{X_1}_{\E_1} \right) \to X_1$ over $p_1$ then
        \begin{enumerate}
            \item $\nu^{X_1}_{\E_1,p_1} \cap O^{X_1}_{\E_1} = \nu^{X_1}_{\E_1,p_1}$, where $\nu^{X_1}_{\E_1,p_1}$ is the fiber of $m^0:\nu^{X_1}_{\E_1} \to X_1$ over $p_1$;
            \item ${\left(m_{\E_0}^0\right)}^{-1}\left( g^{-1}(p_1)\right) \subset V_0'$ and
            \begin{equation*}
                \G^{\leq (d-1)}\left({\left(m_{\E_0}^0\right)}^{-1}\left( g^{-1}(p_1)\right) \right) = {\left(m_{\E_1}^0\right)}^{-1}(p_1).
            \end{equation*}
        \end{enumerate}
    \end{enumerate}
\end{proposition}
\begin{proof}
    Construct $\E_1$ in the same way as in \Cref{subsubsection:patching_to_global_euler_like}, replacing \Cref{proposition:locally_defined_euler_like_in_1} with \Cref{proposition:locally_defined_euler_like_in_1_without_G}. The resulting vector field is a convex combination of locally defined Euler-like vector fields along $X_1$, obtained from \Cref{proposition:locally_defined_euler_like_in_1_without_G} and by pushing forward $\E_0$ by $\G^{\leq (d-1)}$ in $V_1'$.

    Properties \cref{property:E_1_tangential} and \cref{property:G_d_minus_1_related} follow directly from the construction.

    The proof of property \cref{property:relation_to_E_0_on_A_1} is the same as the proofs of \Cref{proposition:E_1_relation_on_A_1,proposition:m_1_relation,proposition:psi_1_relation}, replacing $G$ with $D^Zg$ and using property \cref{property:E_1_tangential}.

    The proof of property \cref{property:DE_1_relates_to_DE_0} is the same as the proof of \Cref{proposition:differential_of_E_1}, replacing $A_1$ with $X_1$ and using the fact that the differential of the diffeomorphism from \Cref{proposition:locally_defined_euler_like_in_1_without_G} agrees with $G_{X_0}$ on $TM_0\Big\lvert_{N_0}$. Property \cref{property:Dm_1_relates_to_Dm_0} follows from property \cref{property:DE_1_relates_to_DE_0} as in \Cref{proposition:Dm_1_relation}.

    Property \cref{property:O_1_G_relates_to_nu_0} follows from property \cref{property:Dm_1_relates_to_Dm_0} as in \Cref{proposition:concrete_neighbourhoods_G_related}.

    The proof of property \cref{property:fiber_over_intersection_with_V_1_complete_coisotropic} is the same as the proof of \Cref{proposition:fibers_Gamma_relation_and_completeness}.
\end{proof}

Note that property \cref{property:O_1_G_relates_to_nu_0} implies that $\psi_0$ is defined on $G^{-1}\left(O^{X_1}_{\E_1}\right)$.

\begin{proposition}\label{proposition:diffeomorphism_for_coisotropic}
    Set
    \begin{align*}
        U_1^{X_1} &\coloneq \psi_1\left(O^{X_1}_{\E_1}\right) \\
        U_0^{X_0} &\coloneq \psi_0\left(G^{-1}\left(O^{X_1}_{\E_1}\right)\right)
    \end{align*}
    and let $\widetilde{\G}^{X_0}:U_0^{X_0} \to U_1^{X_1}$ be the diffeomorphism coming from the composition
    \[\begin{tikzcd}
        {W_0^{X_0}} & {\psi_0\left(G_{X_0}^{-1}\left(O^{X_1}_{\E_1}\right)\right)} && {\psi_1\left(O^{X_1}_{\E_1}\right)} & {W_1^{X_1}} \\
        {\nu^{X_0}_{\E_0}} & {G_{X_0}^{-1}\left(O^{X_1}_{\E_1}\right)} && {O^{X_1}_{\E_1}} & {\nu^{X_1}_{\E_1}}
        \arrow["\supset"{description}, draw=none, from=1-2, to=1-1]
        \arrow["{\widetilde{\G}^{X_0}}", dashed, from=1-2, to=1-4]
        \arrow["{\psi_0^{-1}}", from=1-2, to=2-2]
        \arrow["\subset"{description}, draw=none, from=1-4, to=1-5]
        \arrow["\supset"{description}, draw=none, from=2-2, to=2-1]
        \arrow["{G_{X_0}}", from=2-2, to=2-4]
        \arrow["{\psi_1}", from=2-4, to=1-4]
        \arrow["\subset"{description}, draw=none, from=2-4, to=2-5].
    \end{tikzcd}\]
    Then the following holds:
    \begin{enumerate}
        \item\label{property:G_X_0_agrees_with_recursion_assumption} The diffeomorphisms $\widetilde{\G}^{X_0}$ and $\G^{\leq (d-1)}$ agree on
        \begin{equation*}
            {\left(m_{\E_0}^0\right)}^{-1}\left(m_{\E_0}^0\left(\overline{V_0^{\leq (d-1)}} \cap \psi_0(\nu^{X_0}_{\E_0}) \right) \right).
        \end{equation*}
        \item\label{property:G_X_0_restricts_to_g} $\widetilde{\G}^{X_0}$ restricts to $g$ on $A_0 \cap U_0^{X_0}$.
        \item\label{property:differential_of_G_X_0_on_X_0} $D\widetilde{\G}^{X_0}$ restricts to $G_{X_0}$ on $TM_0\Big\lvert_{X_0}$.
    \end{enumerate}
\end{proposition}
\begin{proof}
    Property \cref{property:G_X_0_agrees_with_recursion_assumption} follows from
    \Cref{proposition:E_1_properties_coisotropic}\cref{property:G_d_minus_1_related} and \Cref{proposition:E_1_properties_coisotropic}\cref{property:fiber_over_intersection_with_V_1_complete_coisotropic}, as in \Cref{proposition:Gamma_X_agrees_with_Gamma_leq_d}.

    Property \cref{property:G_X_0_restricts_to_g} follows from \Cref{proposition:E_1_properties_coisotropic}\cref{property:relation_to_E_0_on_A_1}, as in \Cref{proposition:Gamma_X_agrees_with_g_G}.

    Property \cref{property:differential_of_G_X_0_on_X_0} follows from \Cref{lemma:differential_of_diffeomorphism_from_concrete_tubulars}.
\end{proof}

We are now ready to prove \Cref{thm:symplectic_extending_to_stratum}.

\begin{proof}[Proof of \Cref{thm:symplectic_extending_to_stratum}]
    Let $\widetilde{\G}^{X_0}: U_0^{X_0} \to U_1^{X_1}$ be as in \Cref{proposition:diffeomorphism_for_coisotropic}. Set
    \begin{equation*}
        B \coloneq \left( A_0 \cap U_0^{X_0}\right) \cup {\left(m_{\E_0}^0\right)}^{-1}\left(m_{\E_0}^0\left(\overline{V_0^{\leq (d-1)}} \cap \psi_0(\nu^{X_0}_{\E_0}) \right) \right)
    \end{equation*}
    and
    \begin{equation*}
        A \coloneq X_0 \cup {\left(m_{\E_0}^0\right)}^{-1}\left(m_{\E_0}^0\left(\overline{V_0^{\leq (d-1)}} \cap \psi_0(\nu^{X_0}_{\E_0}) \right) \right),
    \end{equation*}
    which are closed subsets of $U_0^{X_0}$. By construction, $A\subset B$ and $B$ is an invariant subset of the smooth weak deformation retraction $R:[0,1]\times U_0^{X_0} \to U_0^{X_0}$ to $A$ given by
    \begin{equation*}
        R(t, v) = m_{\E_1}^t(v).
    \end{equation*}

    By \Cref{proposition:diffeomorphism_for_coisotropic}\cref{property:G_X_0_agrees_with_recursion_assumption}-\cref{property:G_X_0_restricts_to_g} and the assumption $g^*\w_1 = \w_0$, the forms $\w_0$ and ${\left(\widetilde{\G}^{X_0}\right)}^*\w_1$ agree on $T^ZB$. By \Cref{proposition:diffeomorphism_for_coisotropic}\cref{property:differential_of_G_X_0_on_X_0}, they agree on $TM_0\Big\lvert_{A}$.

    Applying \Cref{thm:moser_trick} with $A,B,$ and the forms $\w_0$ and ${\left(\widetilde{\G}^{X_0}\right)}^*\w_1$, we obtain neighbourhoods $U', U''\subset U_0^{X_0}$ of $A$ and a diffeomorphism $\G':U'\to U''$ with
    \begin{equation*}
        {\G'}^*{\left(\widetilde{\G}^{X_0}\right)}^*\w_1 = \w_0
    \end{equation*}
    and ${\G'}\Big\lvert_{B} = \Id$. In particular, $V_0^{\leq (d-1)} \cap \psi_0(\nu^{X_0}_{\E_0}) \subset U'$.

    It follows that
    \begin{equation*}
        \G^{X_0} \coloneq \widetilde{\G}^{X_0} \circ \G':U' \to \widetilde{\G}^{X_0}(U'') \subset U_1^{X_1}
    \end{equation*}
    is a symplectomorphism which
    \begin{enumerate}
        \item restricts to $\G^{\leq (d-1)}$ on $V_0^{\leq (d-1)}$ and
        \item restricts to $g$ on $A_0 \cap U'$.
    \end{enumerate}

    Finally, using the same arguments as in the proof of \Cref{thm:extending_to_stratum} at the end of \Cref{subsubsection:constructing_the_extension}, the map
    \begin{equation*}
        \G^{\leq (d-1), X^d_0}:\left(V_0^{\leq (d-1)} \cup U' \right) \to \left(V_1^{\leq (d-1)}\cup \widetilde{G}^{X_0}(U'') \right)
    \end{equation*}
    given by gluing $\G^{\leq (d-1)}$ and $\G^{X_0}$ along $V_0^{\leq (d-1)} \cap U'$ is a symplectic extension for
    \begin{equation*}
        {\left(U^{\leq (d-1)}_i, V^{\leq (d-1)}_i, \G^{\leq d-1}, g \right)}
    \end{equation*}
    to $(X^d_0, X^d_1)$.
\end{proof}


\section{Exactness for isotropic stratified subspaces}\label{section:exactness_for_isotropic}
Recall that for a symplectic manifold $(M, \w)$ and an isotropic submanifold $A \subset M$, the symplectic form is exact on a tubular neighbourhood of $A$. \Cref{thm:exactness_of_symplectic_form} is an analogue of this assertion for our case, where $A$ is allowed to be singular. In this section, we relax the assumption on $A$ to just Whitney (B) regularity, rather than requiring it to be smoothly locally trivial with conical fibers.

\begin{thm}\label{thm:exactness_of_symplectic_form}
    Let $(V, \w)$ be a symplectic manifold and $(A, \S)$ a Whitney (B) regular isotropic stratified subspace of it. Let $R:[0,1]\times V \to V$ be a smooth weak deformation retraction of $V$ to $A$ (\Cref{definition:smooth_weak_deformation_retraction}).
    Then $\w$ is exact, with a primitive given by
    \begin{equation*}
        {\left(\pi_V\right)}_*R^*\w = \int_{0}^{1}i_t^* \i_{\frac{\partial}{\partial t}}R^*\w \,dt.
    \end{equation*}
\end{thm}

In the proof of \Cref{thm:exactness_of_symplectic_form} we use the following topological lemmas.
For a topological space $V$ and a subset $A$, We denote the interior of $A$ in $V$ by $\interior_V(A)$.

\begin{lemma}\label{lemma:closed_set_interior_complement_dense}
    Let $V$ be a topological space and $A$ a closed subset. Then
    \begin{equation*}
        \left(V\setminus A\right) \cup \interior_V(A)
    \end{equation*}
    is dense in $V$.
\end{lemma}
\begin{proof}
    Immediate from definitions.
\end{proof}

\begin{lemma}\label{lemma:closed_filtration_interiors_dense}
    Let $V$ be a topological space, $N\in \N$ and
    \begin{equation*}
        V = V^{\leq N} \supset V^{\leq (N-1)} \supset \ldots \supset V^{\leq 1} \supset V^{\leq 0} \supset V^{\leq (-1)} = \emptyset
    \end{equation*}
    a descending chain of closed subsets.
    Then
    \begin{equation*}
        \bigcup_{d=0}^N \interior_V\left(V^{\leq d} \setminus V^{\leq (d-1)}\right)
    \end{equation*}
    is dense in $V$.
\end{lemma}
\begin{proof}
    We prove by induction on $N$.

    The base $N=1$ is \Cref{lemma:closed_set_interior_complement_dense}.

    For the induction step $N$, define $V' \coloneq \interior_{V}\left(V^{\leq (N-1)} \right)$ and consider the descending chain
    \begin{equation*}
        V' = \left(V'\cap V^{\leq (N-1)}\right) \supset \ldots \supset \left(V' \cap V^{\leq 1}\right) \supset \left(V' \cap V^{\leq 0}\right) \supset \left(V' \cap V^{\leq (-1)}\right) = \emptyset
    \end{equation*}
    of closed subset in $V'$. By the induction assumption for $N-1$, we get that
    \begin{equation*}
        \bigcup_{d=0}^{N-1} \interior_{V'}\left(\left(V' \cap V^{\leq d}\right) \setminus \left(V' \cap V^{\leq (d-1)}\right)\right)
        = \bigcup_{d=0}^{N-1} \interior_{V'}\left( \left(V^{\leq d} \setminus V^{\leq (d-1)}\right) \cap V'\right)
    \end{equation*}
    is dense in $V'$. Note that since $V'$ is open in $V$ we have
    \begin{equation*}
        \interior_{V'}\left( \left(V^{\leq d} \setminus V^{\leq (d-1)}\right) \cap V'\right) = \interior_{V}\left(V^{\leq d} \setminus V^{\leq (d-1)}\right) \cap V'.
    \end{equation*}
    Therefore,
    \begin{equation*}
        \bigcup_{d=0}^{N-1} \interior_{V}\left(V^{\leq d} \setminus V^{\leq (d-1)}\right) \cap V'
    \end{equation*}
    is dense in $V'$.

    By \Cref{lemma:closed_set_interior_complement_dense} applied to the pair $V=V^{\leq N}, V^{\leq (N-1)}$, we get that
    \begin{equation*}
        \left( V^{\leq N} \setminus V^{\leq (N-1)}\right) \cup \interior_{V}\left(V^{\leq (N-1)} \right) = \left( V^{\leq N} \setminus V^{\leq (N-1)}\right) \cup V'
    \end{equation*}
    is dense in $V$. It follows that
    \begin{equation*}
        \left( V^{\leq N} \setminus V^{\leq (N-1)}\right) \cup \bigcup_{d=0}^{N-1} \interior_{V}\left(V^{\leq d} \setminus V^{\leq (d-1)}\right) \cap V'
    \end{equation*}
    is dense in $V$, which implies the result.
\end{proof}

We are now ready to prove \Cref{thm:exactness_of_symplectic_form}.

\begin{proof}[Proof of \Cref{thm:exactness_of_symplectic_form}]
    As in \Cref{definition:smooth_weak_deformation_retraction}, we write $r^t:=R(t,\cdot)$. Let $r\coloneq r^0$.
    Apply \Cref{lemma:homotopy_property_of_fiber_integration} to $\gamma=R^*\w$. Since $d\w=0$ and $r^1=\Id_V$, we get 
    \begin{equation*}
        \w -r^*\w = d\left( (\pi_V)_*R^*\w \right).
    \end{equation*}
    Thus, it is enough to prove that $r^*\w =0$.

    By Whitney (B) regularity, the subsets $A^{\leq d}$ are closed in $V$ and, by continuity, the subsets $V^{\leq d} \coloneq r^{-1}(A^{\leq d})$ are closed in $V$. By \Cref{lemma:closed_filtration_interiors_dense}, the union
    \begin{equation*}
        \bigcup_{d=0}^N \interior_V\left(V^{\leq d} \setminus V^{\leq (d-1)}\right)
    \end{equation*}
    is dense in $V$. It follows that it is enough to prove that $r^*\w = 0$ on the open subsets $\interior_V\left(V^{\leq d} \setminus V^{\leq (d-1)}\right)$ for every $d$.

    Let $q\in \interior_V\left(V^{\leq d} \setminus V^{\leq (d-1)}\right)$, then $r(q) \in X$ for some $X\in \S^d$. For all $v\in T_qV$ we have
    \begin{equation*}
        D_qr(v) \in T_{r(q)}X
    \end{equation*}
    and the result follows from the assumption that $X$ is isotropic.
\end{proof}

Recall \cite[Remark~11.11]{cieliebak2012stein} that for a closed manifold $L$, there exists a Weinstein structure on the cotangent bundle $T^*L$ such that the zero section is its Lagrangian skeleton. \Cref{thm:exactness_of_symplectic_form} indicates that an analogous phenomenon might happen in our singular setting.

\begin{question}\label{question:Liouville_domain}
    Let $(V, \w)$ be a symplectic manifold and $(A, \S)$ a Lagrangian stratified subspace of it. Assume that $V$ admits a smooth weak deformation retraction to $A$.
    Under what conditions are there a neighbourhood $W$ of $A$ in $V$ with a smooth boundary and a vector field $Z$ such that $\left(W, \w, Z \right)$ is a Liouville domain, i.e., $d\i_Z\w = \w$ and $Z$ is outward pointing along $\partial W$? Furthermore, under what conditions is there a Weinstein structure on $W$?
\end{question}

\begin{question}\label{question:Lagrangian_skeleton}
    Under what conditions is there a Liouville domain $\left(W, \w, Z \right)$ such that $A$ is the Lagrangian skeleton of $W$?
\end{question}

In a future work we intend to study this relation between our construction, Liouville domains, and their Lagrangian skeleta.

