\section{Theorem~\ref{thm:moser_trick} for a strong deformation retraction}\label{appendix:strong_deformation_retraction_moser}

Recall from \Cref{remark:strong_vs_weak_deformation_retraction} the difference between a weak and a strong deformation retraction.

\begin{thm}\label{thm:moser_trick_with_a_strong_deformation_retraction}
    Let $M$ be a manifold, $A\subset M$ a submanifold, and $V$ a neighbourhood of $A$ admitting a smooth \textbf{strong} deformation retraction to $A$. Let $\w_0, \w_1$ be two symplectic forms on $V$ that agree on $TM\Big\lvert_A$.
    Then there exist neighbourhoods $U',U'' \subset V$ of $A$ and a diffeomorphism
    \begin{equation*}
        \G:U'\to U''
    \end{equation*}
    such that
    \begin{enumerate}
        \item $\G\big\lvert_A = \Id_A$,
        \item $\G^*(\w_1) = \w_0$,
        \item\label{property:strong_deformation_id_differential} $\mathbf{D\G\big\lvert_A = \Id}$.
    \end{enumerate}
\end{thm}

Note that in the statement of \Cref{thm:moser_trick_with_a_strong_deformation_retraction} we don't need the assumption that $A$ is a manifold, as a smooth retract of a manifold is a submanifold:

\begin{thm}[{\cite[Theorem~1.15]{michor2008topics}}]
    Let $M$ be a manifold, $A\subset M$ a subset, and $V$ a neighbourhood of $A$ admitting a smooth retraction to $A$.
    Then $A$ is a submanifold of $M$.
\end{thm}

\begin{definition}
    Let $M$ be a manifold and $A$ a submanifold. The \textbf{vanishing ideal of $\mathbf{A}$ in $\mathbf{M}$} is
    \begin{equation*}
        I(M,A) \coloneq \{f\in C^\infty(M):\: f\big\lvert_A \equiv 0 \}.
    \end{equation*}
    Note that this is indeed an ideal of $C^\infty(M)$.

    The \textbf{time-dependent vanishing ideal of $A$ in $M$} is
    \begin{equation*}
        I_{td}(M,A) \coloneq \{f\in C^\infty(\R \times M):\: f\big\lvert_{\R \times A} \equiv 0 \}.
    \end{equation*}
    This is an ideal of $C^\infty(M)$.
\end{definition}

\begin{definition}[{\cite[Definition~2.2]{diff_geom_of_weightings}}]\label{def:order_of_vanishing_filtration}
    Abbreviate $I \coloneq I(M,A)$ and $I_{td} \coloneq I_{td}(M,A)$.

    The \textbf{$\mathbf{I}$-adic filtration of $\mathbf{C^\infty(M)}$} is
    \begin{equation*}
        \ldots \subset I_2 \subset I_1 \subset I_0 = C^\infty(M),
    \end{equation*}
    where $I_j = \left<I^j \right>$ is the ideal generated by $I^j$.

    Similarly, the \textbf{$\mathbf{I_{td}}$-adic filtration of $\mathbf{C^\infty(\R \times M)}$} is
    \begin{equation*}
        \ldots \subset I_{td,2} \subset I_{td,1} \subset I_{td,0} = C^\infty(\R \times M),
    \end{equation*}
    where $I_{td,j} = \left<I_{td}^j \right>$.
\end{definition}

\begin{remark}
    \Cref{def:order_of_vanishing_filtration} gives a sense of order of vanishing of functions without using local coordinates. An equivalent definition is by order of vanishing in some (and thus, in all) local coordinates. The proof of this equivalence uses the existence of a finite atlas, whose domains of charts are not necessarily connected.
\end{remark}

\begin{notation}
    Let $E\to M$ be a vector bundle. We denote the set of smooth sections of $E$ by $\Gamma(E)$ and the set of smooth time-dependent sections of $E$ by $\Gamma_{td}(E)$.
\end{notation}

\begin{definition}\label{def:I_adic_filtration_of_sections}
    Let $E\to M$ be a vector bundle. The \textbf{induced $\mathbf{I}$-adic filtration} of the $C^\infty(M)$-module $\Gamma(E)$ is
    \begin{equation*}
        \ldots \subset I^{\Gamma(E)}_2 \subset I^{\Gamma(E)}_1 \subset I^{\Gamma(E)}_0 = {\Gamma(E)},
    \end{equation*}
    where $I^{\Gamma(E)}_j = \left< I_j \cdot \Gamma(E) \right>$ is the submodule generated by $I_j \cdot \Gamma(E)$.

    Similarly, The \textbf{induced $\mathbf{I_{td}}$-adic filtration} of the $C^\infty(\R \times M)$-module $\Gamma_{td}(E)$ is
    \begin{equation*}
        \ldots \subset I^{\Gamma_{td}(E)}_2 \subset I^{\Gamma_{td}(E)}_1 \subset I^{\Gamma_{td}(E)}_0 = {\Gamma_{td}(E)},
    \end{equation*}
    where $I^{\Gamma_{td}(E)}_j =  \left< I_{td,j} \cdot \Gamma_{td}(E) \right>$.
\end{definition}

\begin{remark}
    Note that with this filtration, the complex $\left(\Omega^\bullet(M), d \right)$ is \emph{not} a filtered complex. Cf. \cite[Subsection~2.3]{diff_geom_of_weightings}.
\end{remark}

\begin{lemma}\label{lemma:integral_over_td_sections_vanish_order}
    Let $\sigma_t \in I_j^{\Gamma_{td}(E)}$. Then $\int_0^1\sigma_t dt \in I_j^{\Gamma(E)}$.
\end{lemma}
\begin{proof}
    This follows by computation in local coordinates.
\end{proof}

\begin{lemma}\label{lemma:pullbacks_preserve_filtrations}
    Let $M, M'$ be manifolds, $A, A'$ submanifolds of them, $I,I'$ the vanishing ideals, and $I_j, I_j'$ the $I,I'$-adic filtrations, respectively. Let $g:M \to M'$ be a smooth map with $g(A) \subset A'$. Let $E' \to M'$ be a vector bundle and $g^*E' \to M$ the pullback bundle.
    Then
    \begin{enumerate}
        \item The pullback of functions $g^*:C^\infty(M') \to C^\infty(M)$,
        \item the pullback of sections $g_s^*:\Gamma(E') \to \Gamma(g^*E')$,
        \item the pullback of forms $g^*:\Omega^i(M') \to \Omega^i(M)$
    \end{enumerate}
    all preserve the respective induced $I,I'$-adic filtrations.
\end{lemma}
\begin{proof}
    This follows by computation in local coordinates.
\end{proof}

\begin{notation}
    Denote by $\mathfrak{X}(M) \coloneq \Gamma(TM)$ the set of smooth vector fields on $M$. Denote by $\mathfrak{X}_{td}(M)$ the set of smooth time-dependent vector fields on $M$.
\end{notation}

\begin{lemma}\label{lemma:vector_field_vanish_to_second_order_differential}
    Let $(X_t)\in \mathfrak{X}_{td}(M)$ and assume that $(X_t)\in I_2^{\mathfrak{X}_{td}(M)}$.
    Then the differential of the flow $D\Phi_{(X_t)}^{t_0}\Big\lvert_A:TM \to TM$ restricts on $A$ to
    \begin{equation*}
        \Id:TM\Big\lvert_A \to TM\Big\lvert_A,
    \end{equation*}
    whenever it is defined.
\end{lemma}
\begin{proof}
    Let $p\in A$ and let $U$ be a neighbourhood of $p$ in $A$, with coordinates $(x,y)$, such that $p$ is identified with $0$ and $U\cap A$ is identified with $\{y=0\}$. Then
    \begin{equation*}
        \left(x,y ;\; v_x, v_y \right)
    \end{equation*}
    are coordinates on $TU$ and
    \begin{equation*}
        \left(x,y, v_x. v_y; u_x;\; u_x, u_{v_x}, u_{v_y}\right)
    \end{equation*}
    are coordinates on $TTU$.

    Now, $X_t(x,y)$ has the form
    \begin{equation*}
        X_t(x,y) = \left(x,y ;\; X_t^x(x,y), X_t^y(x,y) \right),
    \end{equation*}
    where, for all $t$,
    \begin{align*}
        &X_t^x(x,0)=0, &DX_t^x(x,0)= 0, \\
        &X_t^y(x,0)=0, &DX_t^y(x,0)= 0.
    \end{align*}
    It follows that
    \begin{equation*}
        DX_t(x, 0; v_x, v_y) = \left(x, 0, 0, 0;\; v_x, v_y, 0, 0 \right).
    \end{equation*}
    Lastly, we check that
    \begin{equation*}
        \Id:TM\Big\lvert_A \to TM\Big\lvert_A \qquad \forall t_0\in \R
    \end{equation*}
    satisfies the differential equation from \Cref{lemma:first_variation_vector_flow}, which characterizes $D\Phi^{t_0}_{(X_t)}$. Indeed,
    \begin{align*}
        \frac{d}{dt}\bigg\lvert_{t_0}\bigl( \Id\left(x,0;\; v_x, v_y\right)\bigr) &= \frac{d}{dt}\bigg\lvert_{t_0}\left( x,0;\; v_x, v_y\right)\\
        &= \left(x,0,v_x,v_y ;\; 0,0,0,0 \right)
    \end{align*}
    and
    \begin{align*}
        \left(\kappa_M\circ DX_t \circ \Id\right)\left(x,0,v_x,v_y\right) &= \kappa_M\left(x,0,0,0 ;\; v_x,v_y,0,0 \right) \\
        &= \left(x,0,v_x,v_y ;\; 0,0,0,0 \right).
    \end{align*}
\end{proof}

\begin{proof}[Proof of \Cref{thm:moser_trick_with_a_strong_deformation_retraction}]
    We follow the proofs of \Cref{lemma:relative_poincare,lemma:using_beta_for_moser} and use the same notation, with the additional assumption that the deformation retraction $R:[0,1]\times V \to V$ is strong. We want to prove property~\cref{property:strong_deformation_id_differential}, i.e., that the diffeomorphism $\G:U' \to U''$ that we construct in the proofs of these lemmas satisfies $D\G\Big\lvert_A = \Id$.

    Recall that $\G$ is the time one flow of a time-dependent vector field $(X_t)$ defined by ${\i_{X_t}\w_t = \beta}$, where
    \begin{equation*}
        \beta \coloneq \int_0^1 i^*_t \i_{\frac{\partial}{\partial t}} R^* \alpha
    \end{equation*}
    and $\alpha \coloneq \w_0 - \w_1$. We claim that it is enough to prove that $\beta \in I_2^{\Omega^1(V)}$.
    Indeed, $\beta \in I_2^{\Omega^1(V)}$ implies $(X_t)\in I_2^{\mathfrak{X}_{td}(V)}$, and we finish by \Cref{lemma:vector_field_vanish_to_second_order_differential}. 

    Using the formula for $\beta$ and \Cref{lemma:integral_over_td_sections_vanish_order,lemma:pullbacks_preserve_filtrations}, it is enough to show that
    \begin{equation*}
        \i_{\frac{\partial}{\partial t}} R^* \alpha \in I_2^{\Omega^1\bigl((0,1) \times V\bigr)}
    \end{equation*}
    for the induced $I\Bigl((0,1) \times V, (0,1) \times A\Bigr)$-adic filtration.

    Let $p\in A$, $t_0\in (0,1)$ and $v\in T_{(t_0, p)}\Bigl((0,1) \times V \Bigr)$. Then
    \begin{equation}\label{equation:iota_d_dt_R_alpha_expression}
        \begin{aligned}
            \left(\i_{\frac{\partial}{\partial t}} R^* \alpha \right)_{p}(v)
            &= \left(R^* \alpha\right)_{(t_0, p)} \left(\frac{\partial}{\partial t}, v \right) \\
            &= \alpha_{R(t_0, p)}\left(D_{(t_0, p)}R\left(\frac{\partial}{\partial t}\right), D_{(t_0, p)}R (v)\right).
        \end{aligned}
    \end{equation}


    We consider the pullback bundles
    \begin{enumerate}
        \item $R^*\left(\bigwedge^2 T^*V \right) \to (0,1) \times V$,
        \item $R^*\left(TV\right) \to (0,1) \times V$,
        \item $R^*\left(T^*V\right) \to (0,1) \times V$.
    \end{enumerate}
    Since $\alpha \in I_1^{\Omega^2(V)}$, \Cref{lemma:pullbacks_preserve_filtrations} implies that the section $R_s^*\alpha$ of the bundle ${R^*\left(\bigwedge^2 T^*V \right)}$ satisfies
    \begin{equation*}
        R_s^*\alpha \in I_1^{\Gamma\left(R^*\left(\bigwedge^2 T^*V \right)\right)}.
    \end{equation*}
    Since the deformation retraction is strong, the section $DR\left(\frac{\partial}{\partial t} \right)$ of the pullback bundle $R^*\left(TV\right)$ satisfies
    \begin{equation*}
        DR\left(\frac{\partial}{\partial t} \right) \in I_1^{\Gamma\left(R^*\left(TV\right)\right)}.
    \end{equation*}

    The point-wise contraction on the pullback bundles
    \begin{equation*}
        \i:\Gamma\left(R^*\left(\bigwedge^k T^*V \right)\right) \times \Gamma\left(R^*\left(TV\right)\right) \to  \Gamma\left(R^*\left(\bigwedge^{k-1} T^*V\right) \right)
    \end{equation*}
    is $C^\infty\left( (0,1) \times V\right)$-bilinear; it follows that
    \begin{equation*}
        \i\Bigl( I_1^{\Gamma\left(R^*\left(\bigwedge^2 T^*V \right)\right)} \times I_1^{\Gamma\left(R^*\left(TV\right)\right)}\Bigr) \subset I_2^{\Gamma\left(R^*\left(T^*V\right)\right)}.
    \end{equation*}
    In particular,
    \begin{equation*}
        \i\left(R_s^*\alpha, DR\left(\frac{\partial}{\partial t} \right)\right) \in I_2^{\Gamma\left(R^*\left(T^*V\right)\right)}.
    \end{equation*}
    Therefore, for all $\tilde{Y} \in \Gamma\left(R^*\left(TV\right)\right)$, we have
    \begin{equation}\label{equation:double_contraction}
        \begin{aligned}
            \i\left(\i\left(R_s^*\alpha, DR\left(\frac{\partial}{\partial t} \right)\right), \tilde{Y} \right) &= R_s^*\alpha \left(DR\left(\frac{\partial}{\partial t}\right), \tilde{Y} \right) \\
            &\in I_2 \Bigl( (0,1) \times V, (0,1) \times A \Bigr).
        \end{aligned}
    \end{equation}

    For all $Y \in \mathfrak{X}\Bigl((0,1) \times V \Bigr)$ consider $DR\left(Y\right) \in \Gamma\left(R^*\left(TV\right)\right)$. 
    By equation~\eqref{equation:iota_d_dt_R_alpha_expression}, we have 
    \begin{equation*}
        \left(\i_{\frac{\partial}{\partial t}} R^* \alpha\right)(Y) =  R_s^*\alpha \left(DR\left(\frac{\partial}{\partial t}\right), DR\left(Y\right) \right).
    \end{equation*}
    Equation~\eqref{equation:double_contraction} therefore implies that 
    $\left( \i_{\frac{\partial}{\partial t}}R^*\alpha \right)(Y) \in I_2 \left( (0,1) \times V, (0,1) \times A \right)$. 
    Finally, since this holds for all $Y \in \mathfrak{X}\Bigl((0,1) \times V \Bigr)$, we obtain $\i_{\frac{\partial}{\partial t}} R^* \alpha \in I_2^{\Omega^1\bigl((0,1) \times V\bigr)}$.
\end{proof}

