It is convenient at this point to define an abstract alphabet
\[
\XDn = \set{h_{ij}}{\oijn}.
\]
For a word $w = h_{i_1j_1}\cdots h_{i_kj_k}\in\XDn^*$ we write $\ol w = \ol h_{i_1j_1}\cdots \ol h_{i_kj_k}$.  In what follows, we will be interested in a specific family of words over $\D_n$.  In order to define these, we will first extend the~$h_{ij}$ notation, by defining
\[
h_{ii} = \io \AND \ol h_{ii} = 1 \qquad\text{for all $1\leq i\leq n$.}
\]
For a planar equivalence $\eta\in\PEq_n$ we define the word
\[
w_\eta = h_{1k_1}\cdots h_{nk_n}, \WHERE k_x = \suc_\eta(x)\text{ for all $x\in\bn$.}
\]
For example, with $\eta\in\D_8$ as in \eqref{eq:D8}, we have
\begin{equation}\label{eq:D82}
w_\eta = h_{15}h_{23}h_{33}h_{44}h_{56}h_{66}h_{78}h_{88} = h_{15}h_{23}h_{56}h_{78}.
\end{equation}

\begin{lemma}\label{lem:weta}
For any $\eta\in\PEq_n$ we have $d_\eta = \ol w_\eta$.
\end{lemma}

\pf
We use descending induction on $m = |\bn/\eta|$.  When $m=n$, we have $\eta = \De_\bn$, in which case $d_\eta = 1$ and $w_\eta = h_{11}\cdots h_{nn} = \io$, so the result is clear.  We now assume that $m<n$.  Let
\[
i = {\min}\bigset{x\in\bn}{[x]_\eta\not=\{x\}}.
\]
Since each of $1,\ldots,i-1$ belongs to a singleton $\eta$-class, we have $h_{1k_1}=\cdots=h_{i-1,k_{i-1}}=\io$, and so
\[
w_\eta = h_{ik_i}\cdots h_{nk_n}, \WHERE k_x = \suc_\eta(x) \text{ for each $i\leq x\leq n$.}
\]
Let $\mu\in\PEq_n$ be obtained from $\eta$ by replacing the class $[i]_\eta$ by $\{i\}$ and $[i]_\eta\sm\{i\}$.  We then have
\begin{align*}
d_\mu &= \ol w_\mu &&\text{by induction, as $|\bn/\mu|=m+1$}\\
&= \ol h_{i+1,l_{i+1}}\cdots \ol h_{nl_n} &&\text{where each $l_i = \suc_\mu(x)$}\\
&= \ol h_{i+1,k_{i+1}}\cdots \ol h_{nk_n} &&\text{by Lemma \ref{lem:suc}\ref{suc2}, as $\eta=\mu\vee\eta_{ik_i}$.}
\end{align*}
It follows that
\[
\ol w_\eta = \ol h_{ik_i}\cdot\ol h_{i+1,k_{i+1}}\cdots h_{nk_n} = \ol h_{ik_i}d_\mu.
\]
By Lemma \ref{lem:suc}\ref{suc1}, we have $\ol h_{ik_i}d_\mu = d_\nu$, where $\nu = \mu\vee\eta_{pq}$ for 
\[
p = \max[i]_{\wh\mu} =  i \AND q = \min[k_i]_{\wh\mu} = k_i.
\]
But this says exactly that $\nu = \mu\vee\eta_{ik_i} = \eta$, so that $d_\eta = d_\nu = \ol h_{ik_i}d_\mu = \ol w_\eta$, as required.
\epf

