For the next statement, recall that a band $S$ is \emph{right regular} if $xyx=yx$ for all $x,y\in S$.  This is equivalent to $S$ being $\L$-trivial, i.e.~satisfying $x\L y\implies x=y$.

\begin{prop}\label{prop:Dn}
$\D_n$ is a submonoid of $\PPnfd$, and is in fact a right regular band.  Moreover, we have
\[
\D_n = \pres{\ol h_{ij}}{\oijn}.
\]
\end{prop}

\pf
The inclusion $\D_n \sub \pres{\ol h_{ij}}{\oijn}$ follows from Lemma \ref{lem:weta}, and the backward inclusion from Lemma \ref{lem:suc}\ref{suc1} and a simple induction.  Thus $\D_n = \pres{\ol h_{ij}}{\oijn}$, which also of course shows that $\D_n$ is a submonoid of $\PPnfd$.  

To demonstrate $\L$-triviality, let $\eta,\mu\in\PEq_n$.  Then using the analogue of \eqref{eq:RinPn} for the $\L$-relation, we have
\[
d_\eta \L d_\mu \Implies \coker(d_\eta) = \coker(d_\mu) \Implies \eta = \mu \Implies d_\eta = d_\mu.  \qedhere
\]
\epf






\subsection[Presentation for $\D_n$]{\boldmath Presentation for $\D_n$}\label{subsect:presDn}


We continue to fix the alphabet
\[
\XDn = \set{h_{ij}}{\oijn}.
\]
By Proposition \ref{prop:Dn}, we have a surmorphism
\[
\de:\XDn^*\to\D_n:h_{ij}\mt\ol h_{ij}.
\]
We now let $\RDn$ be the set of the following relations over $\XDn$:
\begin{align}
\label{N1} h_{ij}h_{kl} &= h_{kl} &&\text{if $k\leq i<j\leq l$,}\\
\label{N2} h_{ij}h_{kl} &= h_{kl}h_{ij} &&\text{if $i<j\leq k<l$,}\\
\label{N3} h_{ij}h_{jk} = h_{ik}h_{ij} &= h_{ik}h_{jk} &&\text{if $i<j<k$.}
\end{align}
Note that \eqref{N1} includes as a special case the relations
\[
h_{ij}^2 = h_{ij} \qquad\text{for all $\oijn$.}
\]
Our main goal of this section is to prove the following:

\begin{thm}\label{thm:Dn}
The monoid $\D_n$ has presentation $\Mon\pres \XDn \RDn$ via $\de$.
\end{thm}

It is easy to check that $\RDn\sub\ker(\de)$.  For example, we verify relation \eqref{N3} in Figure \ref{fig:N3}.  


