As ever, the inclusion $\ker(\de)\sub\RDn^\sharp$ is harder to establish.
%
We begin by establishing some simple consequences of the relations \eqref{N1}--\eqref{N3}.  Recall the convention that $h_{ii} = \io$ for all $i$.  Throughout this section we write ${\sim}=\RDn^\sharp$.  There should be no confusion with our earlier use of this symbol.


\begin{lemma}\label{lem:N}
For $i,j,k,l\in\bn$ we have
\begin{align}
\label{N1'} h_{ij}h_{kl} &\sim h_{kl} &&\text{if $k\leq i\leq j\leq l$,}\\
\label{N2'} h_{ij}h_{kl} &\sim h_{kl}h_{ij} &&\text{if $i\leq j\leq k\leq l$,}\\
\label{N3'} h_{ij}h_{jk} &\sim h_{ik}h_{ij} \sim h_{ik}h_{jk} &&\text{if $i\leq j\leq k$,}\\
\label{N4} h_{ij}h_{kl} &\sim h_{lj}h_{kl} &&\text{if $k\leq i\leq l\leq j$,}\\
\label{N5} h_{ij}h_{kl} &\sim h_{ik}h_{kl} &&\text{if $i\leq k\leq j\leq l$.}
\end{align}
\end{lemma}

\pf
\firstpfitem{\eqref{N1'}--\eqref{N3'}}  Note that these are just \eqref{N1}--\eqref{N3} with all `$<$' signs replaced with `$\leq$'.  Thus, we just have to check that in cases with equalities of subscripts not covered in \eqref{N1}--\eqref{N3} we have $\sim$-equivalence of the stated words.  This is obvious for~\eqref{N1'} and~\eqref{N2'}.  For \eqref{N3'} it follows from the above-mentioned relations~$h_{ij}^2=h_{ij}$, which are part of \eqref{N1}.


\pfitem{\eqref{N4}}  Here we have $h_{ij}h_{kl} \Nsim1 h_{ij}h_{il}h_{kl} \Nsim3 h_{il}h_{lj}h_{kl} \Nsim2 h_{lj}h_{il}h_{kl} \Nsim1 h_{lj}h_{kl}$.


\pfitem{\eqref{N5}}  This is similar to \eqref{N4}, but a little easier.
\epf





We now prove a series of results concerning the words $w_\eta\in\XDn^*$ ($\eta\in\PEq_n$) defined above, leading up to Corollary \ref{cor:wweta}, which shows that every word over $\XDn$ is $\sim$-equivalent to some $w_\eta$.

So fix some $\eta\in\PEq_n$, and consider the word $w_\eta = h_{1k_1}\cdots h_{nk_n}$, where each $k_x=\suc_\eta(x)$, and let $p\in\bn$ be arbitrary.  Define the sequence 
\[
p_0 = p \COMMA p_1 = k_{p_0} \COMMA p_2 = k_{p_1} \COMMA \ldots,
\]
and suppose this terminates in $p_l = k_{p_l}$, where $p_0,p_1,\ldots,p_l$ are all distinct.  Also set $q = p_l$.



\begin{lemma}\label{lem:orbit}
With the above notation, and with $u = h_{pk_p}\cdots h_{qk_q}$, we have $u \sim h_{pq}u$.
\end{lemma}

\pf
We use induction on $l$.  If $l=0$ then $q=p$, so $h_{pq}=\io$, and the claim is trivial.  So now suppose $l\geq1$.  We then have
\begin{equation}\label{eq:orbit1}
u = h_{pk_p}\cdots h_{qk_q} = h_{p_0k_{p_0}} h_{p_0+1,k_{p_0+1}} \cdots h_{p_1-1,k_{p_1-1}} \cdot v,
\end{equation}
where $v = h_{p_1k_{p_1}}\cdots h_{qk_q}$.  By induction (considering that $p_1,p_2,\ldots,p_l=q$ is a shorter sequence of the relevant form), we have 
\begin{equation}\label{eq:orbit2}
v\sim h_{p_1q}v.
\end{equation}
We then calculate
\begin{align}
\nonumber u &\sim h_{p_0k_{p_0}} h_{p_0+1,k_{p_0+1}} \cdots h_{p_1-1,k_{p_1-1}} \cdot h_{p_1q}v &&\text{by \eqref{eq:orbit1} and \eqref{eq:orbit2}}\\
\label{eq:orbit3} &\sim h_{p_0k_{p_0}} h_{p_1q}\cdot h_{p_0+1,k_{p_0+1}} \cdots h_{p_1-1,k_{p_1-1}} \cdot v &&\text{by \eqref{N2}.}
\intertext{In this last step, relation \eqref{N2} applies because $k_i<p_1$ for all $p_0+1\leq i\leq p_1-1$, since the points $p_0+1,\ldots, p_1-1$ are nested by the block of $\eta$ containing $p_0$ and $p_1=k_{p_0} = \suc_\eta(p_0)$.  Keeping in mind that $k_{p_0}=p_1$, we then continue:}
\nonumber u &\sim h_{p_0p_1} h_{p_1q}\cdot h_{p_0+1,k_{p_0+1}} \cdots h_{p_1-1,k_{p_1-1}} \cdot v &&\text{by \eqref{eq:orbit3}}\\
\nonumber  &\sim h_{p_0q}h_{p_0p_1} \cdot h_{p_0+1,k_{p_0+1}} \cdots h_{p_1-1,k_{p_1-1}} \cdot v &&\text{by \eqref{N3'}}\\
\nonumber  &= h_{pq}h_{p_0k_{p_0}} \cdot h_{p_0+1,k_{p_0+1}} \cdots h_{p_1-1,k_{p_1-1}} \cdot v &&\text{as $p_0=p$ and $p_1=k_{p_0}$}\\
\nonumber &= h_{pq}u,
\end{align}
completing the proof.
\epf

Among other things, the next lemma identifies an important case of Lemma \ref{lem:orbit}.  To state the result, we first introduce some further terminology.  Consider again $\eta\in\PEq_n$, and write
\[
w_\eta = h_{1k_1}\cdots h_{nk_n}
\AND
d_\eta = \begin{partn}{6} A_1&\cdots&A_r& \multicolumn{3}{c}{} \\ \hhline{~|~|~|-|-|-} B_1&\cdots&B_r&C_1&\cdots&C_s\end{partn}.
\]
For each $1\leq i\leq r$, write $A_i = [x_i,y_i]$.  We define the \emph{bricks} of $w_\eta$ to be the words
\[
u_i = h_{x_ik_{x_i}}\cdots h_{y_ik_{y_i}} \qquad\text{for each $1\leq i\leq r$.}
\]

\begin{lemma}\label{lem:brick}
Let $\eta\in\PEq_n$, and let $u_1,\ldots,u_r$ be the bricks of $w_\eta$, as above.  Then
\ben
\item \label{brick1} $w_\eta = u_1\cdots u_r$,
\item \label{brick2} $u_i \in \set{h_{st}}{x_i\leq s\leq t\leq y_i}^*$ for all $i$,
\item \label{brick3} $u_iu_j\sim u_ju_i$ for distinct $i,j$,
\item \label{brick4} $u_i\sim h_{x_iy_i}u_i$ for all $i$.
\een
\end{lemma}

\pf
\firstpfitem{\ref{brick1}}  This follows immediately from the definition.

\pfitem{\ref{brick2}}  We must show that every subscript of every letter of the brick ${u_i = h_{x_ik_{x_i}}\cdots h_{y_ik_{y_i}}}$ belongs to $A_i=[x_i,y_i]$.  This is obviously true of the \emph{first} subscripts.  Now consider $h_{jk_j}$, where $x_i\leq j\leq y_i$.  Since $j\in[x_i,y_i]=A_i$, we see that either:
\bit
\item $j'$ belongs to the transversal $A_i\cup B_i'$ of $d_\eta$, or else
\item $j'$ belongs to a lower-nontransversal $C_t'$ of $d_\eta$ that is nested by $B_i'$.
\eit
But $k_j = \suc_\eta(j)$ also belongs to $B_i$ or $C_t$ (respectively), and since $B_i$ and $C_t$ are both contained in $A_i=[x_i,y_i]$, we are done.



\pfitem{\ref{brick3}}  This follows immediately from part \ref{brick2} and relation \eqref{N2}.


\pfitem{\ref{brick4}}  This is a special case of Lemma \ref{lem:orbit}.
\epf

We are now almost ready to show that every word over $\XDn$ is $\sim$-equivalent to one of the form $w_\eta$.  The next lemma provides the key step in the proof of this fact.

\begin{lemma}\label{lem:aww}
If $\eta\in\PEq_n$ and $\oijn$, then $h_{ij}w_\eta \sim w_\mu$, where $\mu\in\PEq_n$ is as in Lemma \ref{lem:suc}.
\end{lemma}

\pf
Write $d_\eta = \begin{partn}{6} A_1&\cdots&A_r& \multicolumn{3}{c}{} \\ \hhline{~|~|~|-|-|-} B_1&\cdots&B_r&C_1&\cdots&C_s\end{partn}$, assuming that $A_1<\cdots<A_r$, and $i\in A_k$ and $j\in A_l$.  We also write $A_k = [x,p]$ and $A_l = [q,y]$, noting that
\[
p = \max(A_k) = \max[i]_{\wh\eta} \AND q = \min(A_l) = \min[j]_{\wh\eta}
\]
have the same meaning as in Lemma~\ref{lem:suc}.  Also let $u_1,\ldots,u_r$ be the bricks of $w_\eta$.

\pfcase1  Suppose first that $k=l$, and note that $\mu=\eta$ in this case, so we must show that $h_{ij}w_\eta\sim w_\eta$.  Using \eqref{N2} and Lemma \ref{lem:brick}\ref{brick2}, we have
\[
h_{ij}w_\eta = h_{ij}u_1\cdots u_r \sim u_1\cdots u_{k-1}\cdot h_{ij}u_k \cdot u_{k+1}\cdots u_r,
\]
so we can complete the proof in this case by showing that ${h_{ij}u_k\sim u_k}$.  But this follows from Lemma \ref{lem:brick}\ref{brick4} and \eqref{N1}:
\[
h_{ij}u_k \sim h_{ij}h_{xp}u_k \sim h_{xp}u_k \sim u_k.
\]

\pfcase2  Now suppose $k\not=l$, so that $k<l$.  Using Lemma \ref{lem:brick} and \eqref{N2}, we then have
\begin{equation}\label{eq:aww1}
h_{ij}w_\eta = h_{ij} u_1\cdots u_r \sim v\cdot h_{ij}u_ku_l \cdot v',
\end{equation}
where for simplicity we write $v = u_1\cdots u_{k-1}$ and $v' = u_{k+1}\cdots u_{l-1}u_{l+1}\cdots u_r$.  Next we claim that
\begin{equation}\label{eq:aww2}
h_{ij}u_ku_l \sim u_kh_{pq}u_l.
\end{equation}
Indeed, for this we have
\begin{align*}
h_{ij}u_ku_l &\sim h_{ij}\cdot h_{xp}u_k\cdot h_{qy}u_l &&\text{by Lemma \ref{lem:brick}\ref{brick4}}\\
&\sim h_{ij} h_{xp}h_{qy} \cdot u_ku_l &&\text{by \eqref{N2} and Lemma \ref{lem:brick}\ref{brick2}}\\
&\sim h_{pj} h_{xp}h_{qy} \cdot u_ku_l &&\text{by \eqref{N4}}\\
&\sim h_{pj} h_{qy}h_{xp} \cdot u_ku_l &&\text{by \eqref{N2}}\\
&\sim h_{pq} h_{qy}h_{xp} \cdot u_ku_l &&\text{by \eqref{N5}}\\
&\sim h_{pq}  \cdot h_{xp}u_k\cdot h_{qy}u_l &&\text{by \eqref{N2} and Lemma \ref{lem:brick}\ref{brick2}}\\
&\sim h_{pq}  \cdot u_ku_l &&\text{by Lemma \ref{lem:brick}\ref{brick4}}\\
&\sim u_kh_{pq}u_l &&\text{by \eqref{N2} and Lemma \ref{lem:brick}\ref{brick2}.}
\end{align*}
We then continue:
\begin{align*}
h_{ij}w_\eta &\sim v\cdot h_{ij}u_ku_l \cdot v' &&\text{by \eqref{eq:aww1}}\\
&\sim v\cdot u_kh_{pq}u_l \cdot v' &&\text{by \eqref{eq:aww2}}\\
&= u_1\cdots u_{k-1}\cdot u_kh_{pq}u_l \cdot u_{k+1}\cdots u_{l-1}u_{l+1}\cdots u_r \\
&\sim u_1\cdots u_{k-1}\cdot u_kh_{pq} \cdot u_{k+1}\cdots u_{l-1}u_lu_{l+1}\cdots u_r &&\text{by Lemma \ref{lem:brick}\ref{brick3}}\\
&= u_1\cdots u_{k-1}\cdot u_kh_{pq} \cdot u_{k+1}\cdots u_r,
\end{align*}
and we claim that this last word this is precisely $w_\mu$.
%
Now, $w_\eta = u_1\cdots u_{k-1}\cdot u_k \cdot u_{k+1}\cdots u_n$ and, writing $k_i = \suc_\eta(i)$ for each $1\leq i\leq n$, we note that:
\newpage
\bit
\item $u_k = h_{xk_x}\cdots h_{p-1,k_{p-1}}h_{pk_p} = h_{xk_x}\cdots h_{p-1,k_{p-1}}$, as $k_p=p$ (since $p = \max(A_k)=\max(B_k)$), and so
\item $u_kh_{pq} = h_{xk_x}\cdots h_{p-1,k_{p-1}}h_{pq}$.
\eit
It now follows from Lemma \ref{lem:suc}\ref{suc2} that indeed $u_1\cdots u_{k-1}\cdot u_kh_{pq} \cdot u_{k+1}\cdots u_r = w_\mu$.
\epf



\begin{cor}\label{cor:wweta}
For any $w\in \XDn^*$, we have $w\sim w_\eta$, where $\eta = \coker(\ol w)$.
\end{cor}

\pf
It suffices to show that $w\sim w_\eta$ for some $\eta\in\PEq_n$, since it will then follow from Lemma~\ref{lem:weta} that
\[
\eta = \coker(d_\eta) = \coker(\ol w_\eta) = \coker(\ol w).
\]
We do this by induction on $k$, the length of the word $w$.  If $k=0$, then $w=\io = w_{\De_\bn}$, so now suppose $k\geq1$.  We then have $w = h_{ij}w'$ for some $\oijn$, and some $w'\in\XDn^*$ of length $k-1$.  By induction, we have $w'\sim w_\eta$ for some $\eta\in\PEq_n$, and it then follows from Lemma \ref{lem:aww} that 
\[
w = h_{ij}w' \sim h_{ij}w_\eta \sim w_\mu,
\]
for some $\mu\in\PEq_n$.
\epf



\pf[\bf Proof of Theorem \ref{thm:Dn}.]
We have already observed that $\de$ is surjective, and that ${\sim}\sub\ker(\de)$.  For the reverse inclusion, suppose $(u,v)\in\ker(\de)$, so that $u,v\in\XDn^*$ and $\ol u=\ol v$.  By Corollary~\ref{cor:wweta}, we have $u\sim w_\eta$, where $\eta = \coker(\ol u)$.  But since $\ol u=\ol v$, we also have $v\sim w_\eta$ by the same corollary, so $u\sim w_\eta\sim v$.
\epf







\subsection[The action pair $(\D_n,\O_n)$]{\boldmath The action pair $(\D_n,\O_n)$}\label{subsect:DnOn}



We now bring the monoid $\O_n$ back into consideration, aiming to establish that $(\D_n,\O_n)$ is a strong (right) action pair in $\PPnfd$.  We begin with a simple lemma.  The proof uses the $R$ operation from \eqref{eq:DR}, even though $\PPnfd$ is not closed under it.




\begin{lemma}\label{lem:fdeta}
For any $f\in\O_n$ and $\eta\in\PEq_n$, we have $\coker(fd_\eta) = \eta$.
\end{lemma}

\pf
Since $f\in\T_n$ we have $R(f) = 1$, so it follows from Lemma \ref{lem:Rab=Rb} that $R(fd_\eta) = R(d_\eta)$.  But then
\[
\id_{\coker(fd_\eta)} = R(fd_\eta) = R(d_\eta) = \id_{\coker(d_\eta)} = \id_\eta,
\]
which implies the claim.
\epf


\begin{lemma}\label{lem:fdmu}
If $a\in\PPnfd$, and if $\eta=\coker(a)$, then $a=fd_\eta$ for some $f\in\O_n$.
\end{lemma}

\pf
Write $a = \begin{partn}{6} A_1&\cdots&A_r& \multicolumn{3}{c}{} \\ \hhline{~|~|~|-|-|-} B_1&\cdots&B_r&C_1&\cdots&C_t\end{partn}$, where $A_1<\cdots<A_r$ and $B_1<\cdots<B_r$, and note that each $B_i$ is an un-nested $\eta$-class (but some of the $C_i$ might be un-nested as well).  In particular,~$d_\eta$ contains a transversal of the form $D_i\cup B_i'$ for each $1\leq i\leq r$, and by construction we have $D_1<\cdots<D_r$.  Thus, choosing $x_i\in D_i$ for each $i$, it follows that $f = \begin{partn}{3} A_1&\cdots&A_r \\ x_1&\cdots&x_r \end{partn}$ belongs to $\O_n$, and it is easy to see that~${a = fd_\eta\in\O_n\D_n}$.  (See Figure \ref{fig:PP20fd} for an example, with $n=20$.)
\epf




