In the next statement, recall that we write $\ol h_{ii}=1$ for all $1\leq i\leq n$.

\begin{lemma}\label{lem:hfhg}
If $\oijn$ and $1\leq k\leq n-1$, then
\[
\ol h_{ij}\ol f_k = \begin{cases}
\ol f_k\ol h_{i-1,j} &\text{if $k=i-1$,}\\
\ol f_k\ol h_{i,j-1} &\text{if $k=j-1$,}\\
\ol f_k\ol h_{ij} &\text{otherwise,}
\end{cases}
\AND
\ol h_{ij}\ol g_k = \begin{cases}
\ol g_k\ol h_{i+1,j} &\text{if $k=i$,}\\
\ol g_k\ol h_{i,j+1} &\text{if $k=j$,}\\
\ol g_k\ol h_{ij} &\text{otherwise.}
\end{cases}
\]
\end{lemma}

\pf
This can be checked directly by drawing diagrams, similar to Figure \ref{fig:N3}.
\epf


The expressions in Lemma \ref{lem:hfhg} are not the simplest we could give, but will be useful for proving the next result.  For example, we actually have $\ol h_{ij}\ol f_k = \ol h_{i-1,j}$ when $k=i-1$.



\begin{prop}\label{prop:DnOn}\leavevmode
\ben
\item \label{DnOn1} $(\D_n,\O_n)$ is a strong (right) action pair in $\PPnfd$.
\item \label{DnOn2} We have the product decomposition $\PPnfd = \O_n\D_n$.
\een
\end{prop}

\pf
\firstpfitem{\ref{DnOn1}}  For \ref{A1} we need to show that for all $f\in\O_n$ and $u\in\D_n$, we have $uf=fv$ for some $v\in\D_n$.  This can be shown directly, though the argument is a little involved.  But it also follows from Lemma \ref{lem:hfhg}, and the fact that:
\bit
\item $\D_n=\pres{\ol h_{ij}}{\oijn}$, as shown in Proposition \ref{prop:Dn}, and
\item $\O_n=\pres{\ol f_k,\ol g_k}{1\leq k<n}$, as is well known; see for example \cite{Aizenstat1962,Solomon1996}.
\eit
We write $u$ as a product of $\ol h_{ij}$-s and $f$ as a product of $\ol f_k$-s and $\ol g_k$-s, and then use Lemma \ref{lem:hfhg} to move all $\ol f_k$-s and $\ol g_k$-s to the left.

For \ref{A2}, let $f,g\in\O_n$ and $\eta,\mu\in\PEq_n$.  Then using Lemma \ref{lem:fdeta}, we see that
\[
fd_\eta = gd_\mu \Implies \eta = \coker(fd_\eta) = \coker(gd_\mu) = \mu \Implies d_\eta = d_\mu.
\]


\pfitem{\ref{DnOn2}}  The forward inclusion follows from Lemma \ref{lem:fdmu}.  The reverse is clear.
\epf





\subsection[Presentation for $\PPnfd$]{\boldmath Presentation for $\PPnfd$}\label{subsect:presPPnfd}




We now come to the proof of Theorem \ref{thm:PPnfd}, which will be in two stages.  First we apply Theorem~\ref{thm:SU1}, using the action pair $(\D_n,\O_n)$, to obtain an initial presentation for $\PPnfd$.  This will involve the alphabet
\[
\set{f_i,g_i}{1\leq i<n} \cup \set{h_{ij}}{\oijn}.
\]
Then, using an argument similar to (but slightly easier than) that of Section \ref{sect:Pnfd}, we will deduce from this the presentation $\Mon\pres ZO$ stated in Theorem \ref{thm:PPnfd}.




We begin with some lemmas that will enable the application of Theorem \ref{thm:SU1}.  The first involves the left congruences $\th_u$ ($u\in\D_n$).  For a convex partition $\eta$ of $\bn$, with classes $A_1<\cdots<A_r$, let
\[
f_\eta = \begin{partn}{3} A_1&\cdots&A_r \\ x_1&\cdots&x_r \end{partn} \in \O_n, \WHERE x_i = \min(A_i) \text{ for each $1\leq i\leq k$.}
\]

\begin{lemma}\label{lem:thuDn}
For any $u\in\D_n$ we have $\th_u = (1,f_\eta)\lc$, where $\eta = \ker(u)$.
\end{lemma}

\pf
We must have $u=d_\mu$ for some $\mu\in\PEq_n$ with $\eta = \wh\mu$, and it is easy to check that $d_\mu f_\eta = f_\eta$ and $f_\eta d_\mu = d_\mu$.  The result now follows from Lemma~\ref{lem:1s}.
\epf




The next lemma will be used to verify assumption \ref{SU11} in Theorem \ref{thm:SU1}.

\begin{lemma}\label{lem:VDn}
Let $V = \set{\ol h_{i,i+1}}{1\leq i<n}$.  Then for any $u\in\D_n$ we have
\[
\th_u = \bigvee_{v\in V,\atop u\leqR \hspace{0.5mm} v} \th_v.
\]
\end{lemma}

\pf
Fix some $u\in\D_n$, write $\eta = \ker(u)$, and let the $\eta$-classes be $A_1<\cdots<A_r$.  Also let
\[
I = \bn\sm\{\max(A_1),\ldots,\max(A_r)\}
\AND
W = \set{\ol h_{i,i+1}}{i\in I} .
\]
We claim that $W$ consists of precisely the elements of $V$ that are $\geqR$-above $u$.  Indeed, since each $\ol h_{i,i+1}$ ($1\leq i<n$) is an idempotent, we have $u\leqR\ol h_{i,i+1} \iff u = \ol h_{i,i+1}u$, and it is easy to see that this is equivalent to having $i\in I$.  By Lemma \ref{lem:thuDn} we have
\[
\th_u = (1,f_\eta)\lc \AND \th_{\ol h_{i,i+1}} = (1,\ol f_i)\lc.
\]
If $I = \{i_1<\cdots<i_{n-r}\}$, then $f_\eta = \ol f_{i_{n-r}}\cdots\ol f_{i_1} \in \pres{\ol f_i}{i\in I}$, and it follows that assumptions \ref{bigvee1}--\ref{bigvee4} of Lemma \ref{lem:bigvee} are satisfied, and hence $\th_u = \bigvee_{v\in W}\th_v$, as required.
\epf

We are now ready to apply Theorem \ref{thm:SU1}.  We begin with:
\bit
\item the presentation $\Mon\pres\XDn\RDn$ for $\D_n$ from Theorem \ref{thm:Dn},
\item the presentation $\Mon\pres\XOn\ROn$ for $\O_n$, where $\XOn = \set{f_i,g_i}{1\leq i<n}$, and where~$\ROn$ is the set of all relations from $O$ involving only words over $\XOn$, namely \eqref{O2}, \eqref{O3}, \eqref{O5}--\eqref{O7}, \eqref{O10}, \eqref{O11}, and the relevant parts of \eqref{O1}.  This presentation for $\O_n$ is stated in \cite[Section~3]{Lavers1997}, where it was attributed to A\u{\i}zen\v{s}tat \cite{Aizenstat1962}; a more recent proof (in a more general context) can be found in \cite{Solomon1996}.
\eit




\begin{prop}\label{prop:PPnfd}
The monoid $\PPnfd$ has presentation
\[
\Mon\pres{\XOn\cup\XDn}{\ROn\cup\RDn\cup R_1\cup R_2(V)}
\]
via
\[
\Xi:(\XOn\cup\XDn)^*\to\PPnfd:f_i\mt\ol f_i,\ g_i\mt\ol g_i,\ h_{ij}\mt\ol h_{ij},
\]
where $R_1$ consists of relations
\begin{equation}\label{eq:R1PP}
h_{ij}f_k = \begin{cases}
f_kh_{i-1,j} &\text{if $k=i-1$,}\\
f_kh_{i,j-1} &\text{if $k=j-1$,}\\
f_kh_{ij} &\text{otherwise,}
\end{cases}
\AND
h_{ij}g_k = \begin{cases}
g_kh_{i+1,j} &\text{if $k=i$,}\\
g_kh_{i,j+1} &\text{if $k=j$,}\\
g_kh_{ij} &\text{otherwise,}
\end{cases}
\end{equation}
and $R_2(V)$ consists of relations
\begin{equation}\label{eq:R2VPP}
f_ih_{i,i+1} = h_{i,i+1} \qquad\text{for all $1\leq i<n$.}
\end{equation}
\end{prop}

\pf
This follows from Theorem \ref{thm:SU1}, using Lemma \ref{lem:VDn} to verify assumption \ref{SU11} of the theorem, and Lemmas \ref{lem:hfhg}, \ref{lem:thuDn} and \ref{lem:VDn} to verify the forms of the relations $R_1\cup R_2(V)$.
\epf




We now embark on the second stage of our proof of Theorem \ref{thm:PPnfd}, in which we will be aided by Proposition \ref{prop:PPnfd}.  A key role in all that follows will be played by the words
\[
\al_{ij} = h_ig_{i+1}\cdots g_{j-1} \in Z^* \qquad\text{for $\oijn$}.
\]

\begin{lemma}\label{lem:alh}
For any $\oijn$ we have $\al_{ij}\xi = \ol h_{ij} (= h_{ij}\Xi)$.  Consequently, $\xi$ is surjective.
\end{lemma}

\pf
The first assertion is easily checked diagrammatically.  The second follows because $\PPnfd$ is generated by $\set{\ol f_i,\ol g_i}{1\leq i<n}\cup\set{\ol h_{ij}}{\oijn}$, as follows from Proposition \ref{prop:PPnfd}.
\epf

So we now need to show that $\ker(\xi) = O^\sharp$.  As ever, the inclusion $O^\sharp\sub\ker(\xi)$ follows by simply checking diagrammatically that $\xi$ preserves each relation \eqref{O1}--\eqref{O12} from $O$.  The rest of this section is devoted to establishing the inclusion $\ker(\xi)\sub O^\sharp$.  To this end, we write ${\approx} = O^\sharp$.  First we make the following observation, which follows from the fact that $O$ contains the defining relations from the presentation $\Mon\pres{\XOn}{\ROn}$ for $\O_n$.

\begin{lemma}\label{lem:On}
If $u,v\in\XOn^*$ and $u\xi=v\xi$, then $u\approx v$.  
\end{lemma}




We now prove two lemmas involving the words $\al_{ij}$.  It will also be convenient to have an alternative expression for these words.  Specifically, we define
\[
\be_{ij} = h_{j-1}f_{j-2}\cdots f_i \qquad\text{for $\oijn$.}
\]

\begin{lemma}\label{lem:albe}
For any $\oijn$ we have $\al_{ij} \approx \be_{ij}$.
\end{lemma}

\pf
We fix $1\leq i<n$, and use induction on $j\in\{i+1,\ldots,n\}$.  When $j=i+1$, we have $\al_{i,i+1} = h_i = \be_{i,i+1}$.  For $i+2\leq j\leq n$, we use the inductive hypothesis, the definition of the $\al$ and $\be$ words, and the stated relations from $O$, to calculate:
\begin{align*}
\al_{ij} = \al_{i,j-1}\cdot g_{j-1} 
\approx \be_{i,j-1}\cdot g_{j-1} 
=h_{j-2}f_{j-3}\cdots f_i\cdot g_{j-1} 
&\approx_{\eqref{O7}} h_{j-2}g_{j-1}\cdot f_{j-3}\cdots f_i \\
&\approx_{\eqref{O12}} h_{j-1}f_{j-2}\cdot f_{j-3}\cdots f_i 
= \be_{ij}. \ \ \qedhere
\end{align*}
\epf

\begin{lemma}\label{lem:RDn}
For $i,j,k,l\in\bn$ we have
\begin{align}
\label{N1''} \al_{ij}\al_{kl} &\approx \al_{kl} &&\text{if $k\leq i<j\leq l$,}\\
\label{N2''} \al_{ij}\al_{kl} &\approx \al_{kl}\al_{ij} &&\text{if $i<j\leq k<l$,}\\
\label{N3''} \al_{ij}\al_{jk} \approx \al_{ik}\al_{ij} &\approx \al_{ik}\al_{jk} &&\text{if $i<j<k$.}
\end{align}
\end{lemma}

\pf
\firstpfitem{\eqref{N1''}}  First note that by the definition of the $\al$ and $\be$ words, and Lemma \ref{lem:albe}, we have
\[
\al_{kl} = \al_{kj}\cdot g_j\cdots g_{l-1} 
\approx \be_{kj}\cdot g_j\cdots g_{l-1} 
= \be_{ij}\cdot f_{i-1}\cdots f_k\cdot g_j\cdots g_{l-1} .
\]
Thus, it suffices to show that $\al_{ij}\be_{ij} \approx \be_{ij}$.  For $j=i+1$ we have $\al_{i,i+1}\be_{i,i+1} = h_ih_i \approx h_i$ by~\eqref{O1}.  For $j\geq i+2$ we have
\begin{align*}
\al_{ij}\be_{ij} &= \al_{i,j-1}g_{j-1}\cdot h_{j-1}f_{j-2}\cdots f_i \\
&\approx \be_{i,j-1}\cdot h_{j-1}f_{j-2}\cdots f_i &&\text{by Lemma \ref{lem:albe} and \eqref{O1}}\\
&= h_{j-2}\cdot f_{j-3}\cdots f_i\cdot h_{j-1}f_{j-2}\cdots f_i \\
&\approx h_{j-1}h_{j-2}\cdot f_{j-3}\cdots f_i\cdot f_{j-2}\cdots f_i &&\text{by \eqref{O4} and \eqref{O8}}\\
&\approx h_{j-1}h_{j-2}\cdot f_{j-2}\cdots f_i &&\text{by Lemma \ref{lem:On}}\\
&\approx h_{j-1}\cdot f_{j-2}\cdots f_i &&\text{by \eqref{O1}}\\
&= \be_{ij}.
\end{align*}

\pfitem{\eqref{N2''}}  By Lemma \ref{lem:albe}, it suffices to show that $\al_{ij}\be_{kl} \approx \be_{kl}\al_{ij}$ (for $i<j\leq k<l$).  Now,
\[
\al_{ij} = h_ig_{i+1}\cdots g_{j-1} \AND \be_{kl} = h_{l-1}f_{l-2}\cdots f_k,
\]
and relations \eqref{O4} and \eqref{O7}--\eqref{O9} say that each letter appearing in $\al_{ij}$ commutes with each letter appearing in $\be_{kl}$.  To verify this, it is best to consider separate cases in which $l\geq k+2$ and $l=k+1$.  In the latter we have $\be_{kl} = h_{l-1} = h_k$.



\pfitem{\eqref{N3''}}  First note that
\[
\al_{ik}\al_{jk} = \al_{ij}g_j\cdots g_{k-1}\al_{jk},
\]
so we can show that $\al_{ik}\al_{jk} \approx \al_{ij}\al_{jk}$ by showing that $g_j\cdots g_{k-1}\al_{jk}\approx\al_{jk}$, and we do this by induction on $k$.  When $k=j+1$ we have 
\[
g_j\cdots g_{k-1}\al_{jk} = g_j\cdot h_j \approx_{\eqref{O1}} h_j = \al_{jk}.
\]
For $k\geq j+2$ we have
\begin{align*}
g_j\cdots g_{k-2}g_{k-1}\al_{jk} &\approx g_j\cdots g_{k-2}g_{k-1}\be_{jk} &&\text{by Lemma \ref{lem:albe}}\\
&= g_j\cdots g_{k-2}g_{k-1}\cdot h_{k-1}f_{k-2}\cdots f_j \\
&\approx g_j\cdots g_{k-2}\cdot h_{k-1}f_{k-2}\cdots f_j &&\text{by \eqref{O1}}\\
&= g_j\cdots g_{k-2}\cdot \be_{jk} \\
&\approx g_j\cdots g_{k-2}\cdot \al_{jk} &&\text{by Lemma \ref{lem:albe}}\\
&= g_j\cdots g_{k-2}\cdot \al_{j,k-1}g_{k-1} \\
&\approx \al_{j,k-1}g_{k-1} &&\text{by induction}\\
&= \al_{jk}.
\end{align*}
It remains to show that $\al_{ik}\al_{ij} \approx \al_{ij}\al_{jk}$, and since $\al_{ij}\al_{jk}\approx\al_{jk}\al_{ij}$ by \eqref{N2''}, it suffices to show that $\al_{ik}\al_{ij} \approx \al_{jk}\al_{ij}$, which by Lemma \ref{lem:albe} is equivalent to $\be_{ik}\be_{ij} \approx \be_{jk}\be_{ij}$.  But this is done in similar fashion to the proof of $\al_{ik}\al_{jk} \approx \al_{ij}\al_{jk}$ above.  We first note that
\[
\be_{ik}\be_{ij} = \be_{jk}f_{j-1}\cdots f_i\be_{ij},
\]
and then show by induction that $f_{j-1}\cdots f_i\be_{ij} \approx \be_{ij}$.
\epf

\begin{lemma}\label{lem:R1}
For $\oijn$ and $1\leq k<n$ we have
\[
\al_{ij}f_k \approx \begin{cases}
f_k\al_{i-1,j} &\text{if $k=i-1$,}\\
f_k\al_{i,j-1} &\text{if $k=j-1$,}\\
f_k\al_{ij} &\text{otherwise,}
\end{cases}
\AND
\al_{ij}g_k \approx \begin{cases}
g_k\al_{i+1,j} &\text{if $k=i$,}\\
g_k\al_{i,j+1} &\text{if $k=j$,}\\
g_k\al_{ij} &\text{otherwise.}
\end{cases}
\]
\end{lemma}

\pf
We just prove the relations involving $f_k$, as those for $g_k$ are analogous.  


For $k=i-1$ we first use Lemma \ref{lem:albe} to calculate 
\[
\al_{ij}f_{i-1} \approx \be_{ij}f_{i-1} = \be_{i-1,j} \approx \al_{i-1,j}.
\]
Since $\al_{i-1,j} = h_{i-1}g_i\cdots g_{j-1}$, it follows from \eqref{O1} that $\al_{i-1,j}\approx f_{i-1}\al_{i-1,j}$.

For $k=j-1$ we first deal with the $j=i+1$ case.  Here by \eqref{O1} we have
\[
\al_{ij}f_{j-1} = h_if_i \approx f_i = f_ih_{ii} = f_{j-1}h_{i,j-1}.
\]
On the other hand, if $j\geq i+2$ then
\begin{align*}
\al_{ij}f_{j-1} &= h_ig_{i+1}\cdots g_{j-2}g_{j-1}\cdot f_{j-1} \\
&\approx h_ig_{i+1}\cdots g_{j-2}\cdot f_{j-1} &&\text{by \eqref{O1}}\\
&\approx f_{j-1}\cdot h_ig_{i+1}\cdots g_{j-2} &&\text{by \eqref{O7} and \eqref{O8}}\\
&= f_{j-1}\al_{i,j-1}.
\end{align*}

When $k\not=i-1$ and $k\not=j-1$, one of the following holds:
\[
k\leq i-2 \COMMA i\leq k\leq j-2 \qquad\text{or}\qquad k\geq j.
\]
In the first and third cases, \eqref{O7} and \eqref{O8} say that $f_k$ commutes with each letter appearing in $\al_{ij} = h_ig_{i+1}\cdots g_{j-1}$.  This leaves us to deal with the case that $i\leq k\leq j-2$.  Here we first use Lemma~\ref{lem:On} to calculate
\[
\al_{ij}f_k = h_i\cdot g_{i+1}\cdots g_{j-1}f_k \approx h_i\cdot g_{i+1}\cdots g_{j-1} = \al_{ij}.
\]
Thus, it remains to show that $\al_{ij}\approx f_k\al_{ij}$.  This follows from \eqref{O1} when $k=i$, as the first letter of $\al_{ij}$ is $h_i$.  When $i+1\leq k\leq j-2$ we use \eqref{O8} and then Lemma \ref{lem:On} to calculate
\[
f_k\al_{ij} = f_kh_ig_{i+1}\cdots g_{j-1} \approx h_if_kg_{i+1}\cdots g_{j-1} \approx h_ig_{i+1}\cdots g_{j-1} = \al_{ij}.  \qedhere
\]
\epf



We now define a morphism
\[
(\XOn\cup\XDn)^*\to Z^*:w\mt\wh w \BY \wh f_i = f_i \COMMa \wh g_i = g_i \ANd \wh h_{ij} = \al_{ij}.
\]




\begin{lemma}\label{lem:kerXi}
For any $(u,v)\in\ker(\Xi)$, we have $\wh u\approx\wh v$.
\end{lemma}

\pf
Since $\ker(\Xi) = (\ROn\cup\RDn\cup R_1\cup R_2(V))^\sharp$ by Proposition \ref{prop:PPnfd}, we can assume that $(u,v)$ is one of the relations from this set.  We consider the relations of the various forms separately.
\bit
\item  If $(u,v)\in\ROn$, then $\wh u= u \approx v = \wh v$ since $O$ contains~$\ROn$.
\item  If $(u,v)\in\RDn$, then Lemma \ref{lem:RDn} gives $\wh u\approx\wh v$.
\item  Similarly, Lemma \ref{lem:R1} deals with relations from $R_1$.
\item  Finally, if $(u,v)\in R_2(V)$, then $\wh u = f_ih_i \approx h_i = \wh v$ by \eqref{O1}.  \qedhere
\eit
\epf

We are now ready to complete our objective.

\pf[\bf Proof of Theorem \ref{thm:PPnfd}.]
As already observed, it remains to show that $\ker(\xi)\sub{\approx}$, so let $(u,v)\in\ker(\xi)$.  Let $u'$ and $v'$ be the words over $\XOn\cup\XDn$ obtained by replacing any letter $h_i\in Z$ by $h_{i,i+1}\in\XDn$.  By Lemma \ref{lem:alh} we have $u'\Xi = u\xi$ and $v'\Xi = v\xi$.  Since $(u,v)\in\ker(\xi)$, it follows that $(u',v')\in\ker(\Xi)$.  Lemma \ref{lem:kerXi} then gives $\wh u\sgap'\approx\wh v\sgap'$.  But $\wh u\sgap' = u$ and $\wh v\sgap' = v$, and this completes the proof that $u\approx v$.
\epf



\subsection[The structure of $\PPnfd$]{\boldmath The structure of $\PPnfd$}\label{subsect:structurePPnfd}


Our study of the full-domain partition monoid $\Pnfd$ made heavy use of the $D$ and $R$ operations given in \eqref{eq:DR}, which give $\Pnfd$ the structure of a right restriction Ehresmann monoid.  We have already observed that the planar submonoid $\PPnfd$ is closed under $D$ but not $R$, so it does not inherit the property of being a right restriction monoid (or even an Ehresmann monoid).  It does however satisfy some more general conditions with respect to a different unary range operation, which we will denote by $\rho$ to distinguish it from $R$.  Specifically, we define
\[
\rho(a) = d_{\coker(a)} \qquad\text{for $a\in\PPnfd$.}
\]
So $\rho$ is a map $\PPnfd\to\D_n$.  The next result shows that $\PPnfd$ is a so-called \emph{grrac monoid}.  This is the left-right dual of the \emph{glrac monoids} introduced in \cite{BGG2010} and studied further in \cite{Jones2023}.  The acronyms stand for `\emph{g}eneralised \emph{r}ight/\emph{l}eft \emph{r}estriction monoids possessing the \emph{a}mple and \emph{c}ongruence conditions', which are \ref{G8} and \ref{G7}, respectively, in the following list.  In the proof we again make use of the $R$ operation, even though $\PPnfd$ is not closed under it.

\newpage

\begin{prop}\label{prop:grrac}
For all $a,b\in\PPnfd$ we have:
\begin{enumerate}[label=\textup{\textsf{(G\arabic*)}},leftmargin=9mm]\bmc2
\item \label{G1} $a\rho(a) = a$,
\item \label{G2} $\rho(\rho(a)) = \rho(a)$,
\item \label{G5} $\rho(a)\rho(a) = \rho(a)$,
\item \label{G4} $\rho(a)\rho(b)\rho(a) = \rho(b)\rho(a)$,
\item \label{G3} $\rho(\rho(a)\rho(b)) = \rho(a)\rho(b)$,
\item \label{G6} $\rho(ab)\rho(b) = \rho(ab)$,
\item \label{G7} $\rho(ab) = \rho(\rho(a)b)$,
\item \label{G8} $\rho(a)b = b\rho(ab)$.
\emc
\end{enumerate}
\end{prop}

\pf
We begin with some simple observations that be used throughout the proof; these hold for any $a,b\in\PPnfd$.  First, by construction, we have
\begin{equation}\label{eq:cokerrho}
\coker(\rho(a)) = \coker(d_{\coker(a)}) = \coker(a).
\end{equation}
It follows from this that
\begin{equation}\label{eq:Rrho}
R(\rho(a)) = \id_{\coker(\rho(a))} = \id_{\coker(a)} = R(a).
\end{equation}
Combining this with \ref{E3}, it follows that 
\begin{equation}\label{eq:Rrhoab}
R(ab) = R(R(a)b) = R(R(\rho(a))b) = R(\rho(a)b).
\end{equation}

\pfitem{\ref{G1}}  By Lemma \ref{lem:fdmu}, we have $a=fd_\eta$ for some $f\in\O_n $, and where $\eta=\coker(a)$.  Since $d_\eta$ is an idempotent, it follows that $a=ad_\eta = a\rho(a)$.  

\pfitem{\ref{G2}}  Using \eqref{eq:cokerrho}, we have $\rho(\rho(a)) = d_{\coker(\rho(a))} = d_{\coker(a)} = \rho(a)$.

\pfitem{\ref{G5} and \ref{G4}}  These follow from the fact that $\D_n$ is a right regular band (Proposition \ref{prop:Dn}).

\pfitem{\ref{G3}}  Since $\D_n$ is a monoid, we have $\rho(a)\rho(b) = d_\eta$ for some $\eta\in\PEq_n$, so this identity follows from $\rho(d_\eta) = d_{\coker(d_\eta)} = d_\eta$.

\pfitem{\ref{G6}}  Since $\rho(ab)\rho(b)$ and $\rho(ab)$ both belong to $\D_n$ we can show they are equal by showing that they have the same cokernel, and by definition this is equivalent to showing that
\[
R(\rho(ab)\rho(b)) = R(\rho(ab)).
\]
For this we have
\[
R(\rho(ab)\rho(b)) =_{\eqref{eq:Rrhoab}} R(ab\rho(b))
=_{\ref{G1}} R(ab)
=_{\eqref{eq:Rrho}} R(\rho(ab)).
\]

\pfitem{\ref{G7}}  Again, we can establish this by showing that $R(\rho(ab)) = R(\rho(\rho(a)b))$.  By \eqref{eq:Rrho}, this is equivalent to $R(ab) = R(\rho(a)b)$, and this is precisely \eqref{eq:Rrhoab}.

\pfitem{\ref{G8}}  Let $u = \rho(a)$, and note that by \ref{G7}, the identity \ref{G8} is equivalent to $ub = b\rho(ub)$, i.e.~to
\[
ub = bd_\eta, \WHERE \eta = \coker(ub).
\]
Now, by Lemma \ref{lem:fdmu}, we have $b = fd_\mu$ for some $f\in\O_n$, where $\mu = \coker(b)$.  Since $(\D_n,\O_n)$ is a strong action pair (Proposition \ref{prop:DnOn}), it follows from property \ref{A1} that $uf=fv$ for some $v\in\D_n$.  Since $\D_n$ is a right regular band (Proposition \ref{prop:Dn}), we have $vd_\mu = d_\mu vd_\mu$.  Also, since~$\D_n$ is a monoid, we have $vd_\mu = d_\nu$ for some $\nu\in\PEq_n$.  Putting all of this together, it follows that
\begin{equation}\label{eq:ub}
ub = ufd_\mu = fvd_\mu = fd_\mu vd_\mu = bd_\nu.
\end{equation}
So it remains to show that $\nu = \eta$.  But for this we have
\begin{align*}
\nu &= \coker(fd_\nu) &&\text{by Lemma \ref{lem:fdeta}}\\
&= \coker(fvd_\mu) &&\text{by definition of $\nu$}\\
&= \coker(ub) &&\text{by \eqref{eq:ub}}\\
&= \eta.  && \qedhere
\end{align*}
\epf







