\section{Quasi-triangular anti-dendriform bialgebras }
A skew-symmetric solution of the AD-YBE generates 
an (coboundary) anti-dendriform bialgebra. In this section, we examine how solutions of the AD-YBE 
produce anti-dendriform bialgebras without imposing skew-symmetry constraints. 

Let $A$ be a vector space and $r\in A\otimes A$. Define $T_{r}:A^{*}\longrightarrow A$ by
 \begin{equation}\label{To}
\langle T_{r}(\zeta),\eta\rangle=\langle r,\zeta\otimes \eta\rangle,~~\forall~
\zeta,\eta\in A^{*}.
\end{equation}
It is clearly that $T_{r}^{*}=T_{\tau(r)},~T_{r+\tau(r)}^{*}=T_{r+\tau(r)}$.

\begin{defi} \label{In}
 Let $(A,\succ,\prec)$ be an anti-dendriform algebra and $r\in A\otimes A$. We say that $r$ is {\bf invariant} if 
 \begin{align}&\label{IE3}
(R_{\prec}(x)\otimes I+I\otimes L_{\cdot}(x))r=0,
\\&\label{IE4}(R_{\cdot}(x)\otimes I+I\otimes L_{\succ}(x))r=0,~\forall~x\in A.
\end{align}

\end{defi}

 \begin{lem} \label{In1}
 Let $(A,\succ,\prec)$ be an anti-dendriform algebra and $r\in A\otimes A$. Then 
$r$ is invariant if and only if the following equations hold:
  \begin{align}&\label{IE5} R_{\cdot}^{*}(T_{r}(\zeta))\eta=-L_{\prec}^{*}(T_{\tau(r)}(\eta) \zeta,
\\&\label{IE6}R_{\succ}^{*}(T_{r}(\zeta))\eta=-L_{\cdot}^{*}(T_{\tau(r)}(\eta) \zeta,~~\forall~\zeta,\eta\in A^{*}.\end{align}
Moreover, Eqs.~(\ref{IE5})-(\ref{IE6}) are equivalent to the following equations: 
 \begin{align}&\label{IE7}
L_{\cdot}(x) T_{r}(\zeta)=-T_{r}(R_{\prec}^{*}(x)\zeta),\ \ \
 L_{\succ}(x) T_{r}(\zeta) =-T_{r}(R_{\cdot}^{*}(x)\zeta),~~\forall~x\in A,\zeta\in A^{*}.
\end{align}

\end{lem}
\begin{proof} 
For all $~x\in A,\zeta,\eta\in A^{*}$, we have
\begin{align*}
\langle \zeta\otimes\eta,(I\otimes L_{\cdot}(x)+R_{\prec}(x)\otimes I)r
\rangle
&=\langle \zeta\otimes L_{\cdot}^{*}(x)\eta,r\rangle
+\langle \eta\otimes R_{\prec}^{*}(x)\zeta,\tau(r)\rangle
\\&=\langle  T_{r}(\zeta),L_{\cdot}^{*}(x)\eta\rangle
+\langle T_{\tau(r)}(\eta), R_{\prec}^{*}(x)\zeta\rangle
\\&=\langle  x\cdot T_{r}(\zeta),\eta\rangle
+\langle T_{\tau(r)}(\eta)\prec x, \zeta\rangle
\\&=\langle  x,R_{\cdot}^{*}(T_{r}(\zeta))\eta\rangle
+\langle x, L_{\prec}^{*}(T_{\tau(r)}(\eta)) \zeta\rangle,
\end{align*}
Thus, Eq.~(\ref{IE3}) $\Longleftrightarrow$ Eq.~(\ref{IE5}). Similarly,
 Eq.~(\ref{IE4}) $\Longleftrightarrow$ Eq.~(\ref{IE6}), Eqs.~(\ref{IE5})-(\ref{IE6}) 
 hold if and only if Eq.~(\ref{IE7}) holds. 
\end{proof}

\begin{pro} \label{Si}
 Let $(A,\succ,\prec)$ be an anti-dendriform algebra and $r\in A\otimes A$. Then the following
 conditions are equivalent:
  \begin{enumerate}
\item $r+\tau(r)$ is invariant.
\item The following equations hold:
\begin{align}&\label{IE8}
L_{\cdot}(x) T_{r+\tau(r)}(\zeta)=-T_{r+\tau(r)}(R_{\prec}^{*}(x)\zeta),\ \ \ 
L_{\succ}(x) T_{r+\tau(r)}(\zeta) =-T_{r+\tau(r)}(R_{\cdot}^{*}(x)\zeta),~~\forall~x\in A,\zeta\in A^{*}.\end{align}
\item The following equations hold:
\begin{align}&\label{IE9}
T_{r+\tau(r)}(L_{\cdot}^{*}(x)\zeta) =-R_{\prec}(x)T_{r+\tau(r)}(\zeta),\ \ \ 
 T_{r+\tau(r)}L_{\succ}^{*}(x)(\zeta) =-R_{\cdot}(x)T_{r+\tau(r)}(\zeta),~~\forall~x\in A,\zeta\in A^{*}.
\end{align}
\item The following equations hold:
\begin{align}&\label{IE10} R_{\cdot}^{*}(T_{r+\tau(r)}(\zeta))\eta=-L_{\prec}^{*}(T_{r+\tau(r)}(\eta) \zeta, \ \ \
R_{\succ}^{*}(T_{r+\tau(r)}(\zeta))\eta=-L_{\cdot}^{*}(T_{r+\tau(r)}(\eta) \zeta,~~\forall~\zeta,\eta\in A^{*}.\end{align}
\end{enumerate}
 \end{pro}

 \begin{proof} In view of Lemma \ref{In1}, $r+\tau(r)$ is invariant if and only if Eq.~(\ref{IE8}) holds.
 Since $T_{r+\tau(r)}=T_{r+\tau(r)}^{*}$, Eq.~(\ref{IE8}) holds if and only if Eq.~ (\ref{IE9}) holds.
 By Eq.~(\ref{IE5})-(\ref{IE6}), $r+\tau(r)$ is invariant if and only if Eq.~(\ref{IE10}) holds. The proof is completed.
\end{proof}
 Combining Eqs.~(\ref{IE8})-(\ref{IE10}), we obtain for all~$x\in A,~\zeta,\eta\in A^{*}$,
 \begin{align}&\label{IE11}
L_{\prec}(x) T_{r+\tau(r)}(\zeta)=T_{r+\tau(r)}(R_{\succ}^{*}(x)\zeta), 
\\&\label{IE12}T_{r+\tau(r)}(L_{\prec}^{*}(x)\zeta) =R_{\succ}(x)T_{r+\tau(r)}(\zeta),
\\&\label{IE13} R_{\prec}^{*}(T_{r+\tau(r)}(\zeta))\eta=L_{\succ}^{*}(T_{r+\tau(r)}(\eta) \zeta.\end{align}

\begin{pro} \label{Da1}
Let $(A,\succ,\prec,\Delta_{\succ,r},\Delta_{\prec,r})$ be a coboundary anti-dendriform bialgebra and $r\in A\otimes A$, 
where the comultiplications
$\Delta_{\succ,r},\Delta_{\prec,r}$ are defined by Eqs.~(\ref{CD1})-(\ref{CD2}).
 Then the anti-dendriform algebra structure $(\succ_r,\prec_r)$ on $A^{*}$ is
given by 
\begin{align}&\label{IE1}\zeta\succ_{r}\eta=-R_{\cdot}^{*}(T_{r}(\zeta))\eta-L_{\prec}^{*}(T_{\tau(r)}(\eta))\zeta,
\\&\label{IE2}\zeta\prec_{r}\eta=
R_{\succ}^{*}(T_{r}(\zeta))\eta+L_{\cdot}^{*}(T_{\tau(r)}(\eta))\zeta.
\end{align}
And the associative algebra structure on  $\cdot_r$ on $A^{*}$ is
given by 
\begin{align}\label{IE0}\zeta\cdot_{r}\eta=L_{\succ}^{*}(T_{\tau(r)}(\eta))\zeta-R_{\prec}^{*}(T_{r}(\zeta))\eta,
\end{align}
where $\cdot=\succ+\prec,~
 L_{\cdot}=L_{\succ}+L_{\prec},~R_{\cdot}=R_{\succ}+R_{\prec}$.
\end{pro}
\begin{proof} For all $\zeta,\eta\in A^{*}$ and $x\in A$,
\begin{align*}\langle \zeta\succ_{r}\eta,x\rangle
&=\langle \zeta\otimes\eta,\Delta_{\succ,r}(x)\rangle
=-\langle \zeta\otimes\eta,(I\otimes L_{\cdot}(x)+R_{\prec}(x)\otimes I)r
\rangle
\\&=-\langle \zeta\otimes L_{\cdot}^{*}(x)\eta,r\rangle
-\langle \eta\otimes R_{\prec}^{*}(x)\zeta,\tau(r)\rangle
=-\langle T_{r}(\zeta),L_{\cdot}^{*}(x)\eta\rangle
-\langle T_{\tau(r)}(\eta),R_{\prec}^{*}(x)\zeta\rangle
\\&=-\langle x\cdot T_{r}(\zeta),\eta\rangle-
\langle T_{\tau(r)}(\eta)\prec x,\zeta\rangle
=-\langle R_{\cdot}^{*}(T_{r}(\zeta))\eta+L_{\prec}^{*}(T_{\tau(r)}(\eta))\zeta
,x\rangle,
\end{align*}
which indicates that Eq. (\ref{IE1}) holds.
By the same token, Eq. (\ref{IE2}) holds. Using Eqs. (\ref{IE1})-(\ref{IE2}), we get Eq. (\ref{IE0}).
\end{proof}


\begin{thm} Let $(A,\succ,\prec)$ be an anti-dendriform algebra and 
$r=\sum_{i}a_i\otimes b_i\in A\otimes A$. Assume that
$\Delta_{\succ,r},\Delta_{\prec,r}$ given by Eqs.~(\ref{CD1})-(\ref{CD2}). If $r$ is a solution of the 
AD-YBE in $(A,\succ,\prec)$ and $r+\tau(r)$ is invariant.
Then $(A,\succ,\prec,\Delta_{\succ,r},\Delta_{\prec,r})$ is an anti-dendriform bialgebra.
\end{thm}
\begin{proof} Given the invariance of $r+\tau(r)$ is invariant, 
Eqs.~(\ref{IE8})-(\ref{IE13}) hold and
\begin{align*}
(R_{\prec}(x)\otimes I+I\otimes L_{\cdot}(x)) (r+\tau(r))=0, \ \ \ (R_{\cdot}(x)\otimes I+I\otimes L_{\succ}(x)) (r+\tau(r))=0,~\forall~x\in A.
\end{align*}
Thus Eq.~(\ref{CD4}) holds and
\begin{align*}&\langle \zeta\otimes\eta, [L_{\succ}( x)R_{\succ}(y)\otimes I-R_{\succ}(y)\otimes R_{\prec}( x)+I\otimes R_{\prec}(x)L_{\prec}(y)-L_{\succ}(x)\otimes L_{\prec}( y)](r+\tau (r))\rangle
\\=&\langle R_{\succ}^{*}(y)L_{\succ}^{*}( x)\zeta\otimes\eta - R_{\succ}^{*}(y)\zeta\otimes R_{\prec}^{*}( x)\eta
+\zeta\otimes L_{\prec}^{*}(y)R_{\prec}^{*}(x)\eta-L_{\succ}^{*}(x)\zeta\otimes L_{\prec}^{*}( y)\eta, 
r+\tau (r)\rangle
\\=&\langle T_{r+\tau (r)}(R_{\succ}^{*}(y)L_{\succ}^{*}( x)\zeta),\eta\rangle-
\langle T_{r+\tau (r)}(R_{\succ}^{*}(y)\zeta),R_{\prec}^{*}( x)\eta\rangle+
\langle T_{r+\tau (r)}(\zeta),L_{\prec}^{*}(y)R_{\prec}^{*}(x)\eta\rangle
\\&-\langle T_{r+\tau (r)}(L_{\succ}^{*}(x)\zeta),L_{\prec}^{*}(y)\eta\rangle
\\=&\langle - L_{\prec}(y)R_{\cdot}(x)T_{r+\tau (r)}(\zeta)-
 R_{\prec}(x)L_{\prec}(y)T_{r+\tau (r)}(\zeta)+  R_{\prec}(x)L_{\prec}(y)T_{r+\tau (r)}(\zeta)
+ L_{\prec}(y)R_{\cdot}(x)T_{r+\tau (r)}(\zeta),\eta  \rangle
\\=&0,\end{align*}
which implies that Eq.~(\ref{CD3}) holds.
Note that
\begin{align*}&(R_{\prec}(x)\otimes I \otimes I-I\otimes I\otimes L_{\succ}(x))(r_{12}\prec r_{13}+r_{23}\cdot r_{12}+r_{13}\succ r_{23})
\\=&(R_{\prec}(x)\otimes I \otimes I-I\otimes I\otimes L_{\succ}(x))[-\sigma_{123}D(r)
+r_{23}\cdot (r_{12}+r_{21})\\&+(r_{13}+(r_{12}+r_{21})\prec r_{13}+r_{31})\succ r_{23}-r_{21}\prec (r_{13}+r_{31})]
\\=&(R_{\prec}(x)\otimes I \otimes I-I\otimes I\otimes L_{\succ}(x))[
\sum_{i,j}(I\otimes L_{\cdot}(a_i)+R_{\prec}(a_i)\otimes I)(r+\tau(r)) \otimes b_i
\\&+(I\otimes I\otimes R_{\succ}(b_i)-L_{\prec}(b_i)\otimes I\otimes I)(\tau\otimes I)[a_i\otimes (r+\tau(r))]
\\=&0,\end{align*}
which indicates that Eq.~(\ref{CD5}) holds. Analogously, we can prove that Eqs.~(\ref{CD6})-(\ref{CD8}) hold.
Combining Theorem \ref{YE3}, we get the statement.
 \end{proof}

\begin{defi} \label{Qt1}
 Let $(A,\succ,\prec)$ be an anti-dendriform algebra and $r\in A\otimes A$. If $r$ is a solution of the AD-YBE and 
 $r+\tau(r)$ is invariant, then the 
anti-dendriform bialgebra $(A, \succ,\prec,\Delta_{\succ,r},\Delta_{\prec,r})$ induced by $r$ is called
  a {\bf quasi-triangular} anti-dendriform bialgebra. 
 In particular, if $r$ is skew-symmetric, $(A, \succ,\prec,\Delta_{\succ,r},\Delta_{\prec,r})$
is called a {\bf triangular} anti-dendriform bialgebra.
\end{defi}

\begin{pro} \label{Ya} Let $(A,\succ,\prec)$ be an anti-dendriform algebra and
$r\in A\otimes A$. Then  \begin{enumerate}
\item
 $r$ is a solution of the
AD-YBE $ D(r)=r_{12}\cdot r_{13}+r_{23}\succ r_{12}-r_{13}\prec r_{23}=0$ in $(A,\succ,\prec)$
if and only if the following equation holds:
 \begin{equation*}T_{\tau(r)}(\eta)\cdot T_{\tau(r)}(\zeta)=T_{\tau(r)}(R_{\prec}^{*}(T_{r}(\eta))\zeta
-L_{\succ}^{*}(T_{\tau(r)}(\zeta))\eta),~~\forall~\eta,\zeta\in A^{*}.
\end{equation*}
\item
 $r$ is a solution of the
AD-YBE $ D(r)=r_{12}\cdot r_{13}+r_{23}\succ r_{12}-r_{13}\prec r_{23}=0$ 
in $(A,\succ,\prec)$
 if and only if the following equation holds:
 \begin{equation*}T_{r}(\eta)\prec T_{r}(\zeta)=T_{r}(R_{\succ}^{*}(T_{r}(\eta))\zeta+
L_{\cdot}^{*}(T_{\tau(r)}(\zeta))\eta),~~\forall~\eta,\zeta\in A^{*}.
\end{equation*}
\item
 $r$ is a solution of the equation $ D_{1}(r)=r_{23}\cdot r_{12}+r_{13}\succ r_{23}+r_{12}\prec r_{13}=0$ 
 in $(A,\succ,\prec)$
 if and only if the following equation holds:
 \begin{equation*}T_{r}(\eta)\succ T_{r}(\zeta)=-T_{r}(L_{\prec}^{*}(T_{\tau(r)}(\zeta))\eta
+R_{\cdot}^{*}(T_{r}(\eta))\zeta),~~\forall~\eta,\zeta\in A^{*}.
\end{equation*}
\item
 $r$ is a solution of the equation $ D_{1}(r)=r_{23}\cdot r_{12}+r_{13}\succ r_{23}+r_{12}\prec r_{13}=0$
 in $(A,\succ,\prec)$
if and only if the following equation holds:
 \begin{equation*}T_{\tau(r)}(\eta)\prec T_{\tau(r)}(\zeta)=-T_{\tau(r)}(L_{\cdot}^{*}(T_{\tau(r)}(\zeta))\eta
+R_{\succ}^{*}(T_{r}(\eta))\zeta),~~\forall~\eta,\zeta\in A^{*}.
\end{equation*}
\item
 $r$ is a solution of the equation $ D_{2}(r)=r_{13}\cdot r_{23}-r_{12}\succ r_{13}+r_{23}\prec r_{12}=0$
 in $(A,\succ,\prec)$
if and only if the following equation holds:
 \begin{equation*}T_{r}(\eta)\cdot T_{r}(\zeta)=T_{r}(L_{\succ}^{*}(T_{\tau(r)}(\zeta))\eta
-R_{\prec}^{*}(T_{r}(\eta))\zeta),~~\forall~\eta,\zeta\in A^{*}.
\end{equation*}
\item
 $r$ is a solution of the equation $ D_{2}(r)=r_{13}\cdot r_{23}-r_{12}\succ r_{13}+r_{23}\prec r_{12}=0$
 in $(A,\succ,\prec)$
if and only if the following equation holds:
 \begin{equation*}T_{\tau(r)}(\eta)\succ T_{\tau(r)}(\zeta)=T_{\tau(r)}(L_{\prec}^{*}(T_{\tau(r)}(\zeta))\eta
+R_{\cdot}^{*}(T_{r}(\eta))\zeta),~~\forall~\eta,\zeta\in A^{*}.
\end{equation*}

 \end{enumerate}

\end{pro}

\begin{proof} According to Eq.~\eqref{To},  we have for all $\zeta,\eta,\theta\in A^{*}$,
\begin{align*}\langle \zeta\otimes \eta\otimes \theta,r_{12}\cdot r_{13}\rangle
&=\sum_{i,j}\langle \zeta\otimes \eta\otimes \theta,a_i\cdot a_j\otimes b_i\otimes b_j\rangle
\\&=\sum_{i,j}\langle \zeta,a_i\cdot a_j\rangle\langle \eta,b_i\rangle \langle \theta,b_j\rangle 
=\langle \zeta,T_{\tau(r)}(\eta)\cdot T_{\tau(r)}(\theta) \rangle
,\end{align*}
\begin{align*}\langle \zeta\otimes \eta\otimes \theta,r_{13}\prec r_{23}\rangle
&=\sum_{i,j}\langle \zeta\otimes \eta\otimes \theta,a_i \otimes a_j\otimes (b_i\prec b_j)\rangle
\\&=\sum_{i,j}\langle \zeta,a_i\rangle\langle \eta,a_j\rangle \langle \theta,b_i\prec b_j\rangle 
=\langle  \theta,T_{r}(\zeta) \prec T_{r}(\eta)\rangle
\\&=\langle  R_{\prec}^{*}(T_{r}(\eta))\theta,T_{r}(\zeta) \rangle
=\langle \zeta, T_{\tau(r)}(R_{\prec}^{*}(T_{r}(\eta))\theta) \rangle,\end{align*}
 \begin{align*}\langle \zeta\otimes \eta\otimes \theta,r_{23}\succ r_{12}
  \rangle
 &=\sum_{i,j}\langle \zeta\otimes \eta\otimes \theta,a_j \otimes (a_i\succ b_j)\otimes b_i\rangle
 \\& =\sum_{i,j}\langle \zeta,a_j\rangle\langle \eta,a_i\succ b_j\rangle \langle \theta,b_i\rangle 
 =\langle \eta,T_{\tau(r)}(\theta)\succ T_{r}(\zeta) \rangle
  \\&=\langle L_{\succ}^{*}(T_{\tau(r)}(\theta))\eta,T_{r}(\zeta)\rangle
 =\langle \zeta,T_{\tau(r)}(L_{\succ}^{*}(T_{\tau(r)}(\theta))\eta)\rangle.\end{align*}
 Thus, $r$ is a solution of the AD-YBE in $(A,\succ,\prec)$ is equivalent to that
\begin{equation*}T_{\tau(r)}(\eta)\cdot T_{\tau(r)}(\theta)=T_{\tau(r)}(R_{\prec}^{*}(T_{r}(\eta))\theta-L_{\succ}^{*}(T_{\tau(r)}(\theta))\eta).
\end{equation*}Similarly, Items (b)-(f) hold.

\end{proof}

\begin{thm}\label{Ya1} Let $(A,\succ,\prec)$ be an anti-dendriform algebra and
$r\in A\otimes A$. Assume that $r+\tau(r)$ is invariant. Then the following conditions hold:
\begin{enumerate}
\item $r$ is a solution of the AD-YBE $D(r)=0$ if and only if 
$r$ is a solution of the equations $D_1(r)=D_2(r)=0$.
\item $r$ is a solution of $D(r)=0$ if and only if 
$r$ is a solution of the equation $D(\tau(r))=r_{21}\cdot r_{31}+r_{32}\succ r_{21}-r_{31}\prec r_{32}=0$.
\end{enumerate}
\end{thm} 

\begin{proof} 
If $r$ is a solution of $D_1(r)=D_2(r)=0$, then
$r$ is a solution of $D(r)==D_1(r)-D_2(r)=0$. On the other hand, assume that $r$ is a solution of $D(r)=0$. 
In view of Eq.~(\ref{IE12}), for all $\zeta,\eta,\theta\in A^{*}$ we have
\begin{align*} &\langle \zeta\otimes\eta \otimes\theta,\sum_{i}(I\otimes I\otimes R_{\succ}(b_i)-
L_{\prec}(b_i)\otimes I\otimes I)
(\tau\otimes I)[a_i\otimes (r+\tau(r))]\rangle
\\=&\sum_{i}\langle \eta\otimes\zeta\otimes R_{\succ}(b_i)^{*}\theta -\eta\otimes L_{\prec}(b_i)^{*}\zeta\otimes\theta,
a_i\otimes (r+\tau(r)) \rangle
\\=&\langle \zeta\otimes  R_{\succ}^{*}(T_{r}(\eta))\theta-L_{\prec}^{*}(T_{r}(\eta))\zeta\otimes\theta,r+\tau(r) \rangle
 \\=&\langle T_{r+\tau(r)}(\zeta),  R_{\succ}^{*}(T_{r}(\eta))\theta\rangle
 -\langle T_{r+\tau(r)}(L_{\prec}^{*}(T_{r}(\eta))\zeta),\theta\rangle
\\=&\langle R_{\succ}(T_{r}(\eta)) T_{r+\tau(r)}(\zeta)-T_{r+\tau(r)}(L_{\prec}^{*}(T_{r}(\eta))\zeta),  \theta\rangle
\\=&0.
\end{align*} 
Thus,
\begin{align*} D_1(r)=&-\sigma_{123}D(r)+r_{23}\cdot (r_{12}+r_{21})+(r_{13}+r_{31})\succ r_{23}-
r_{21}\prec (r_{31}+r_{13})+(r_{12}-r_{21})\prec r_{13}
\\=&-\sigma_{123}D(r)+\sum_{i}(I\otimes L_{\cdot}(a_i)+R_{\prec}(a_i)\otimes I)(r+\tau(r))\otimes b_i\\&+(I\otimes I\otimes R_{\succ}(b_i)-
L_{\prec}(b_i)\otimes I\otimes I)
(\tau\otimes I)[a_i\otimes (r+\tau(r))]\\=&0.
\end{align*} 
 It follows that $D_2(r)=D_1(r)-D(r)=0.$ In all, Item (a) holds. Similarly, Item (b) holds.
The proof is completed.
\end{proof}

\begin{thm}\label{QB0} Let $(A,\succ,\prec)$ be an anti-dendriform algebra and
$r\in A\otimes A$. Suppose that $r+\tau(r)$ is invariant. Then the following conditions are equivalent:
 \begin{enumerate}
\item $r$ is
a solution of the
AD-YBE in $(A,\succ,\prec)$.
 \item $(A^{*},\cdot_r)$ is an associative algebra and the linear maps
$T_{r},-T_{\tau(r)}$ are both associative algebra
 homomorphisms from $(A^{*},\cdot_r)$ to $(A,\cdot)$.
 \item $(A^{*},\succ_r,\prec_r)$ is an anti-dendriform algebra and the linear maps
$T_{r},-T_{\tau(r)}$ are both anti-dendriform algebra
 homomorphisms from $(A^{*},\succ_r,\prec_r)$ to $(A,\succ,\prec)$.
 \end{enumerate}
\end{thm}
\begin{proof} 
Combining Proposition \ref{Ya}, Theorem \ref{Ya1} and Proposition \ref{Da1}, we deduce
 the conclusion.
\end{proof}

\begin{cor} \label{QB} Let $(A,\succ,\prec,\Delta_{\succ,r},\Delta_{\prec,r})$ be a quasi-triangular anti-dendriform bialgebra.
 Then  \begin{enumerate}
\item $T_{r},-T_{\tau(r)}$ are both associative algebra
 homomorphisms from $(A^{*},\cdot_r)$ to $(A,\cdot)$.
 \item $T_{r},-T_{\tau(r)}$ are anti-dendriform algebra
 homomorphisms from $(A^{*},\succ_r,\prec_r)$ to $(A,\succ,\prec)$.
 \end{enumerate}
\end{cor}

\begin{proof} It follows directly from Theorem \ref{QB0} and Definition \ref{Qt1}.
\end{proof}

