\section{Factorizable anti-dendriform bialgebras}
In this section, we introduce a notion of factorizable 
anti-dendriform bialgebras, which is a special class of quasi-triangular anti-dendriform bialgebras.
We show that the double of an anti-dendriform bialgebra
is naturally a factorizable anti-dendriform bialgebra.

\begin{defi} \label{Qt} A quasi-triangular anti-dendriform bialgebra $(A, \succ,\prec, \Delta_{\succ,r}, \Delta_{\prec,r})$ is
called factorizable if  
  $T_{r+\tau(r)}:A^{*}\longrightarrow A$ given by Eq. (\ref{To}) is a linear isomorphism of vector spaces 
where $\Delta_{\succ,r}, \Delta_{\prec,r}$
are defined by Eqs.~(\ref{CD1})-(\ref{CD2}).\end{defi}

\begin{pro} \label{Qf} Assume that $(A, \succ,\prec, \Delta_{\succ,r}, \Delta_{\prec,r})$ is a quasi-triangular
 (factorizable) anti-dendriform bialgebra. Then $(A, \succ,\prec, \Delta_{\succ,\tau(r)}, \Delta_{\prec,\tau(r)})$
 is also a quasi-triangular
 (factorizable) anti-dendriform bialgebra.\end{pro}
 \begin{proof} This conclusion follows from Theorem \ref{Ya1} and Definition \ref{Qt}.
 \end{proof}

\begin{pro}
Let $(A, \succ,\prec, \Delta_{\succ,r}, \Delta_{\prec,r})$ be a factorizable anti-dendriform bialgebra.
Then $\mathrm{Im}(T_{r}\oplus T_{\tau(r)})$ is an anti-dendriform 
 subalgebra of the direct sum anti-dendriform  
algebra $A\oplus A$,
which is isomorphic to the anti-dendriform algebra $(A^{*},\succ_{r},\prec_{r})$. Furthermore, any $x\in A$ has a unique
decomposition $x=x_1-x_2$, where $(x_1,x_2)\in \mathrm{Im}(T_{r}\oplus T_{\tau(r)})$ and
\begin{equation*}T_{s}\oplus T_{\tau(s)}:A^{*}\longrightarrow A\oplus A, \ \ 
(T_{s}\oplus T_{\tau(s)})(\zeta)=(T_{s}(\zeta), -T_{\tau(s)}(\zeta)),~\forall~\zeta\in A^{*}. \end{equation*}
\end{pro}

\begin{proof} In view of Corollary \ref{QB}, $T_{r},-T_{\tau(r)}$ are anti-dendriform
 algebra 
homomorphisms and 
$T_{r+\tau(r)}$ is a linear isomorphism. It follows that
$\mathrm{Im}(T_{r}\oplus T_{\tau(r)})$ is an anti-dendriform subalgebra of the direct sum anti-dendriform
algebra $A\oplus A$ and $\mathrm{Im}(T_{r}\oplus T_{\tau(r)})\simeq A^{*}$ as anti-dendriform
algebras. Due to $T_{r+\tau(r)}$ being an isomorphism,
we get 
\begin{equation*}T_{r}T_{r+\tau(r)}^{-1}(x)+T_{\tau(r)}T_{r+\tau(r)}^{-1}(x)=T_{r+\tau(r)}T_{r+\tau(r)}^{-1}(x)=x,\end{equation*}
that is, $x=x_1-x_2$ with $x_1=T_{r}T_{r+\tau(r)}^{-1}(x)$ and $x_2=-T_{\tau(r)}T_{r+\tau(r)}^{-1}(x)$. 
The proof is finished.
\end{proof}
\begin{pro}
 Let $(A, \succ,\prec, \Delta_{\succ,r}, \Delta_{\prec,r})$ 
 be a factorizable anti-dendriform bialgebra. Then the double anti-dendriform 
algebra $(D=A\oplus A^{*}, \succ_D,\prec_D)$
is isomorphic to the direct sum $A\oplus A$ of anti-dendriform algebras.
\end{pro}

\begin{proof} By Definition \ref{Qt1} and Definition \ref{Qt}, 
$T_{r+\tau(r)}$ is a linear isomorphism and $r+\tau(r)$ is invariant.
Define $\varphi:A\oplus A^{*}\longrightarrow A\oplus A$ by
\begin{equation}\label{FD1}\varphi(x,\zeta)=(x+T_{r}(\zeta),x-T_{\tau(r)}(\zeta)),~\forall~(x,\zeta)\in A\oplus A^{*}.\end{equation}
It is obvious that $\varphi$ is a bijection.
Eq.~(\ref{IE2}) implies
\begin{align*}&\langle\eta,
T_{r}(-(R_{\prec_A}^{*}+R_{\succ_A}^{*})(x)\zeta)+L_{\prec_A^{*}}^{*}(\zeta)x\rangle
\\=& -\langle T_{\tau(r)}(\eta), (R_{\prec_A}^{*}+R_{\succ_A}^{*})(x)\zeta
\rangle+\langle \zeta\prec_r\eta,x\rangle
\\=&-\langle \zeta,T_{\tau(r)}(\eta)\cdot x\rangle +
\langle L_{\cdot}^{*}(T_{\tau(r)}(\eta))\zeta+
R_{\succ}^{*}(T_{r}(\zeta))\eta,x\rangle
\\=&-\langle \zeta,T_{\tau(r)}(\eta)\cdot x\rangle +
\langle \zeta,T_{\tau(r)}(\eta)\cdot x\rangle+\langle \eta
, x\succ T_{r}(\zeta)\rangle
\\=&\langle \eta, x\succ T_{r}(\zeta)\rangle, 
\end{align*}
which yields that 
\begin{equation}\label{FD2}T_{r}(-(R_{\prec_A}^{*}+R_{\succ_A}^{*})(x)\zeta+L_{\prec_A^{*}}^{*}(\zeta)x
=x\succ T_{r}(\zeta).\end{equation}
Analogously,  
\begin{equation}\label{FD3}T_{\tau(r)}((R_{\prec_A}^{*}+R_{\succ_A}^{*})(x)\zeta+L_{\prec_A^{*}}^{*}(\zeta)x
=-x\succ T_{\tau(r)}(\zeta).\end{equation}
According to Eqs. (\ref{Db1}) and (\ref{FD1})-(\ref{FD3}),
\begin{align*}&\varphi(x\succ_D \zeta)=\varphi(L_{\prec_A^{*}}^{*}(\zeta)x
-(R_{\prec_A}^{*}+R_{\succ_A}^{*})(x)\zeta)\\
=&(T_{r}(-(R_{\prec_A}^{*}+R_{\succ_A}^{*})(x)\zeta)+L_{\prec_A^{*}}^{*}(\zeta)x,
T_{\tau(r)}((R_{\prec_A}^{*}+R_{\succ_A}^{*})(x)\zeta+L_{\prec_A^{*}}^{*}(\zeta)x)
\\=&(x\succ T_{r}(\zeta),-x\succ T_{\tau(r)}(\zeta))
=(x,x)\succ (T_{r}(\zeta),-T_{\tau(r)}(\zeta))
\\=&\varphi(x)\succ \varphi(\zeta).
\end{align*}
By the same token, $\varphi(\zeta\succ_D x)=\varphi(\zeta)\succ \varphi(x) $. Thus,
$\varphi((x,\zeta)\succ_D (y,\eta))=\varphi(x,\zeta)\succ \varphi(y,\eta) $ for all
$(x,\zeta), (y,\eta)\in A\oplus A^{*}$.
Taking the same procedure, we can prove that
$\varphi((x,\zeta)\prec_D (y,\eta))=\varphi(x,\zeta)\prec \varphi(y,\eta) $.
Thus, $\varphi$ is an anti-dendriform algebra isomorphism.
The proof is completed.
\end{proof}

\begin{thm} \label{Ft}
Let $(A, \succ,\prec, \Delta_{\succ}, \Delta_{\prec})$ be an anti-dendriform
bialgebra and $(D=A\oplus A^{*},\succ_{D},\prec_{D})$ be the double anti-dendriform algebra given in Section 2. 
 Assume that $\{e_1,...,e_n\}$ is a basis of $A$ and $\{e^{*}_1,...,e^{*}_n\}$ is the dual basis.
 Let \begin{equation*}r=\sum_{i=1}^{n}e_{i}\otimes e_{i}^{*}\in A\otimes A^{*}\subseteq D\otimes D.\end{equation*}
Then $(D,\succ_D,\prec_D, \Delta_{\succ,r},\Delta_{\prec,r})$ with 
$\Delta_{\succ,r},\Delta_{\prec,r}$ given by Eqs.~(\ref{CD1})-(\ref{CD2})
 is a factorizable anti-dendriform
bialgebra.

\end{thm}
\begin{proof}
Firstly, we prove that $r+\tau(r)=\sum_{i,j=1}^{n}(e_{i}\otimes e_{i}^{*}+e_{j}^{*}\otimes e_{j})$ is invariant. 
By Eqs.~(\ref{Db1}) and (\ref{Db2}), we have for all $x\in A$ 
\begin{align*}&(R_{\cdot_D}(x)\otimes I+I\otimes L_{\succ_D}(x))\sum_{i,j=1}^{n}(e_{i}\otimes e_{i}^{*}+e_{j}^{*}\otimes e_{j})
\\=&\sum_{i,j=1}^{n}e_{i}\cdot_{D} x\otimes e_{i}^{*}+e_{j}^{*}\cdot_{D}x\otimes e_{j}
+e_{i}\otimes x\succ_{D}e_{i}^{*}+e_{j}^{*}\otimes x\succ_De_{j}
\\=&\sum_{i,j=1}^{n}e_{i}\cdot x\otimes e_{i}^{*}-(R_{\prec_{A^*}}^{*}(e_{j}^{*})x+L_{\succ_A}^{*}(x)e_{j}^{*})
\otimes e_{j}
-e_{i}\otimes(R_{\cdot_A}^{*}(x)e_{i}^{*}-L_{\prec_{A^*}}^{*}(e_{i}^{*})x)
+e_{j}^{*}\otimes x\succ e_{j}.
\end{align*}
Note that
\begin{align*}& \sum_{i}^{n}e_{i}\cdot x\otimes e_{i}^{*}-e_{i}\otimes(R_{\cdot_A}^{*}(x)e_{i}^{*})=0,
\\&\sum_{i,j=1}^{n} e_{i}\otimes L_{\prec_{A^*}}^{*}(e_{i}^{*})x-(R_{\prec_{A^*}}^{*}(e_{j}^{*})x)
\otimes e_{j}=0,
\\&\sum_{j=1}^{n}e_{j}^{*}\otimes x\succ e_{j}-L_{\succ_A}^{*}(x)e_{j}^{*}\otimes e_{j}=0.
\end{align*}
Thus, $(R_{\cdot_D}(x)\otimes I+I\otimes L_{\succ_D}(x))(r+\tau(r))=0.$
Similarly, $(I\otimes L_{\cdot}(x)+R_{\prec}(x)\otimes I)(r+\tau(r))=0.$
By duality, we get
\begin{equation*}(R_{\cdot_D}(\zeta)\otimes I+I\otimes L_{\succ_D}(\zeta))(r+\tau(r))=0,
\ \ \
(I\otimes L_{\cdot}(\zeta)+R_{\prec}(\zeta)\otimes I)(r+\tau(r))=0\end{equation*}
for all $\zeta\in A^{*}$. Therefore, according to Definition \ref{In}, $r+\tau(r)$ is invariant.
Secondly, we prove that $r$ is a solution of the AD-YBE in $(D,\succ_D,\prec_D)$.
 From Eqs.~(\ref{Db1}) and (\ref{Db2}), we get
\begin{align*}& r_{12}\cdot_D r_{13}+r_{23}\succ_D r_{12}-r_{13}\prec_D r_{23}
\\=&\sum_{i,j=1}^{n}e_{i}\cdot_D e_{j}\otimes e_{i}^{*}\otimes e_{j}^{*}+e_{j}\otimes e_{i}\succ_D e_{j}^{*} \otimes e_{i}^{*}
-e_{i}\otimes e_j \otimes e_{i}^{*}\prec_D e_{j}^{*}
\\=&\sum_{i,j=1}^{n}e_{i}\cdot e_{j}\otimes e_{i}^{*}\otimes e_{j}^{*}+e_{j}\otimes (L_{\prec_{A^*}}^{*}(e_{j}^{*})e_{i}-R_{\cdot_A}^{*}(e_{i})e_{j}^{*})
 \otimes e_{i}^{*}-e_{i}\otimes e_j \otimes e_{i}^{*}\prec e_{j}^{*}
=0.\end{align*}
In all, $(D,\succ_D,\prec_D, \Delta_{\succ,r},\Delta_{\prec,r})$ is a quasi-triangular anti-dendriform
bialgebra.
Furthermore, the linear maps $T_{r},T_{\tau(r)}:D^{*}\longrightarrow D$ are respectively defined by 
$T_{r}(\zeta,x)=\zeta,~T_{\tau(r)}(\zeta,x)=-x$ for all $x\in A,\zeta\in A^{*}$, 
which yields that
$T_{s+\tau(s)}(\zeta,x)=(\zeta,-x)$ is a linear isomorphism. Therefore, $(D,\succ_D,\prec_D, \Delta_{\succ,r},\Delta_{\prec,r})$
is a factorizable anti-dendriform
bialgebra.

\end{proof}
