\section{Relative Rota-Baxter operators and the AD-YBE}
In this section, we introduce a notion of relative Rota-Baxter operators with 
weights on anti-dendriform algebras, 
which can demonstrates the solutions of the AD-YBE whose symmetric parts are invariant.

\begin{defi} Let $(A,\succ,\prec)$ and $(V,\succ_V,\prec_V)$ be anti-dendriform algebras. Assume that
 $(V,l_{\succ},r_{\succ},$\ \ \ \ $l_{\prec},r_{\prec})$ is a representation of $(A,\succ,\prec)$
 and the following conditions are satisfied:
 \begin{align*}&
 (l_{\succ}(x)a)\prec_V b=l_{\succ}(x)(a\prec_V b),\ \ \ (r_{\succ}(x)a)\prec_V b=a\succ_V(l_{\prec}(x)b)
 ,\ \ \ r_{\prec}(x)(a\succ_V b)=a\succ_V(r_{\prec}(x)b),\\&
 l_{\succ}(x)(a\prec_V b)=-(l_{\cdot}(x)a)\succ_V b=-l_{\prec}(x)(a\cdot_V b)=(l_{\prec}(x)a)\prec_V b, 
 \\&
 a\succ_V(l_{\succ}(x) b)=-(r_{\cdot}(x)a)\succ_V b=-a\prec_V (l_{\cdot}(x)b)
 =(r_{\prec}(x)a)\prec_V b, 
 \\&
 a\succ_V(r_{\succ}(x) b)=-r_{\succ}(x)(a\cdot_V b)=-a\prec_V (r_{\cdot}(x)b)
 =r_{\prec}(x)(a\prec_V b), 
\end{align*}
for all $x\in A$ and $a,b\in V$. Then $(V,\succ_V,\prec_V,l_{\succ},r_{\succ},l_{\prec},r_{\prec})$ is called
  an A-anti-dendriform algebra, where $\cdot=\succ+\prec,~\cdot_V=\succ_V+\prec_V$.
\end{defi}
 It is easy to check that $(V,\succ_V,\prec_V,l_{\succ},r_{\succ},l_{\prec},r_{\prec})$ is an A-anti-dendriform algebra
 if and only if $(A\oplus V,\succeq,\preceq)$ is an anti-dendriform algebra, where
 \begin{align*}&
 (x+a)\succeq (y+b)=x\succ y+l_{\succ}(x)b+r_{\succ}(y)a+a\succ_V b,\\&
 (x+a)\preceq (y+b)=x\prec y+l_{\prec}(x)b+r_{\prec}(y)a+a\prec_V b.
  \end{align*}

 \begin{pro}
Let $(A,\succ,\prec)$ be an anti-dendriform algebra and $r\in A\otimes A$ be skew-symmetric and invariant. 
Define multiplications $\succeq_r,\preceq_r:A^{*}\otimes A^{*}\longrightarrow A^{*}$ by
\begin{align}&\label{AD1} \zeta\succeq_r\eta=-R_{\cdot}^{*}(T_{r}(\zeta))\eta=L_{\prec}^{*}(T_{r}(\eta))\zeta, 
 \\&\label{AD2}\zeta\preceq_r\eta=
R_{\succ}^{*}(T_{r}(\zeta))\eta=L_{\cdot}^{*}(T_{r}(\eta))\zeta+,~~\forall~\zeta,\eta\in A^{*}.
\end{align}
Then $(A^{*},\succeq_r,\preceq_r,-R_{\cdot}^{*},L_{\prec}^{*},R_{\succ}^{*},-L_{\cdot}^{*})$ is an A-anti-dendriform algebra
and $(A^{*},\cdot_r,-R_{\prec}^{*},-L_{\succ}^{*})$ is an A-associative algebra, where
\begin{equation}\label{AD3} \zeta\cdot_r\eta=-R_{\prec}^{*}(T_{r}(\zeta))\eta=L_{\succ}^{*}(T_{r}(\eta))\zeta,~~\forall~\zeta,\eta\in A^{*}.
\end{equation}
\end{pro}

\begin{proof} Using Eqs.~(\ref{R1})-(\ref{R4}), (\ref{IE8})-(\ref{IE13}) 
and (\ref{AD1})-(\ref{AD2}), 
we obtain the conclusion via direct computations.
\end{proof}

\begin{defi} Let $(A,\succ,\prec)$ be an anti-dendriform algebra and 
$(V,\succ_V,\prec_V,l_{\succ},r_{\succ},l_{\prec},r_{\prec})$ be an A-anti-dendriform algebra.
A relative Rota-Baxter operator $T$ of weight $\lambda$ on $(A,\succ,\prec)$ associated with
 $(V,\succ_V,\prec_V,l_{\succ},r_{\succ},l_{\prec},r_{\prec})$
   is a linear map $T:V\longrightarrow A$ satisfying
\begin{align*}&T(u)\succ T(v)=T (l_{\succ}(T(u))v+r_{\succ}(T(v))u+u\succ_V v),\\& 
T(u)\prec T(v)=T (l_{\prec}(T(u))v+r_{\prec}(T(v))u+u\prec_V v),~~\forall~u,v\in V.\end{align*}
When $u\succ_Vv=u\prec_Vv=0$ for all $u,v\in V$, then $T$ is simply a relative Rota-Baxter operator ( $\mathcal O$-operator) on
$(A,\succ,\prec)$ associated with a representation $(V,l_{\succ},r_{\succ},l_{\prec},r_{\prec})$.
In particular, a relative Rota-Baxter operator $P$ on $(A,\succ,\prec )$ associated with
 $(A,\succ,\prec,L_{\succ},R_{\succ},L_{\prec},R_{\prec})$ is called a Rota-Baxter operator of weight $\lambda$, 
 that is, $P:A\longrightarrow A$
is a linear map satisfying 
\begin{align*}&
P(x)\succ P(y)=P(P(x)\succ y)+x\succ P(y)+\lambda x\succ y),\\
 & P(x)\prec P(y)=P(P(x)\prec y)+x\prec P(y)+\lambda x\prec y) \end{align*}
for all $x, y, z \in A$.
$(A,\succ,\prec,P)$ is called a Rota-Baxter anti-dendriform algebra of weight $\lambda$.\end{defi}

Let $(A,\succ,\prec,P)$ be a Rota-Baxter anti-dendriform algebra of weight $\lambda$. 
It is easy to check that
  $(A,\succ,\prec,\tilde{P}=-\lambda I -P)$ is a Rota-Baxter anti-dendriform algebra of weight $\lambda$.

\begin{thm}
Let $(A,\succ,\prec)$ be an anti-dendriform algebra and $r\in A\otimes A$. Assume that $r+\tau(r)$ is invariant.
Then the following
conditions are equivalent.
 \begin{enumerate}
\item $r$ is a solution of the AD-YBE in $(A,\succ,\prec)$
 such that $(A,\succ,\prec,\Delta_{\succ,r},\Delta_{\prec,r})$
with $\Delta_{\succ,r},\Delta_{\prec,r}$ given by Eqs. (\ref{CD1})-(\ref{CD2}) is a quasi-triangular anti-dendriform bialgebra.
\item $T_r$ is a relative Rota–Baxter operator of weight $1$ on $(A,\succ,\prec)$
 associated with the A-anti-dendriform algebra 
 $(A^{*},\succeq_{r+\tau(r)},\preceq_{r+\tau(r)},-R_{\cdot}^{*},L_{\prec}^{*},R_{\succ}^{*},-L_{\cdot}^{*})$,
 that is,
 \begin{align}\label{AD5} &
 T_{r}(\zeta)\succ T_{r}(\eta)= T_{r}(R_{\cdot}^{*}(T_{r}(\zeta))\eta
 -L_{\prec}^{*}(T_{r}(\eta))\zeta+\zeta\succeq_{r+\tau(r)}\eta),\\&
 \label{AD6}T_{r}(\zeta)\prec T_{r}(\eta)=T_{r}(L_{\cdot}^{*}(T_{r}(\eta))\zeta
 -R_{\succ}^{*}(T_{r}(\zeta))\eta+\zeta\preceq_{r+\tau(r)}\eta).
 \end{align}
\item $T_r$ is a relative Rota–Baxter operator of weight $1$ on $(A,\cdot)$
 associated with the A-associative algebra $(A^{*},\cdot_{r+\tau(r)},-R_{\prec}^{*},-L_{\succ}^{*})$, that is,
 \begin{align}\label{AD8} &
 T_{r}(\zeta)\cdot T_{r}(\eta)= T_{r}(R_{\prec}^{*}(T_{r}(\zeta))\eta
 +L_{\succ}^{*}(T_{r}(\eta))\zeta+\zeta\cdot_{r+\tau(r)}\eta),
 \end{align}
  \end{enumerate}
 for all $\zeta,\eta\in A^{*}$, where $\succeq_{r+\tau(r)},\preceq_{r+\tau(r)}$ and $\cdot_{r+\tau(r)}$ are given respectively by 
 Eqs.~ (\ref{AD1})-(\ref{AD3}).

  \end{thm}
 \begin{proof} 
 In the light of Proposition \ref{Ya} and Theorem \ref{Ya1}, if $r+\tau(r)$ is invariant, then
 $r$ is a solution of the AD-YBE in $(A,\succ,\prec)$ if and only if
 \begin{equation*}T_{r}(\eta)\cdot T_{r}(\zeta)=T_{r}(L_{\succ}^{*}(T_{\tau(r)}(\zeta))\eta
-R_{\prec}^{*}(T_{r}(\eta))\zeta),~~\forall~\eta,\zeta\in A^{*}.
\end{equation*}
 Note that
  \begin{align*}T_{r}(\eta)\cdot T_{r}(\zeta)&=T_{r}(-L_{\succ}^{*}(T_{r}(\zeta))\eta
-R_{\prec}^{*}(T_{r}(\eta))\zeta+L_{\succ}^{*}(T_{r+\tau(r)}(\zeta))\eta)\\&=
T_{r}(-L_{\succ}^{*}(T_{r}(\zeta))\eta
-R_{\prec}^{*}(T_{r}(\eta))\zeta+\eta\cdot_{r+\tau(r)}\zeta).
\end{align*}
Thus, Item (a) $\Longleftrightarrow$ Item (c).
By the same token, Item (a) $\Longleftrightarrow$ Item (b). 
  \end{proof}

 If $r\in A\otimes A$ is skew-symmetric, then $r+\tau(r)=0$. The following conclusion is obtained.

 \begin{cor} \cite{030}
Let $(A,\succ,\prec)$ be an anti-dendriform algebra and $r\in A\otimes A$ be skew-symmetric. 
Then the following conditions are equivalent:
\begin{enumerate}
\item $r$ is a solution of the AD-YBE in $(A,\succ,\prec)$.
\item $T_r:A^{*}\longrightarrow A$ is a relative Rota–Baxter operator on $(A,\cdot)$
 associated with the representation $(A^{*},-R_{\prec}^{*},-L_{\succ}^{*})$.
 \item $T_r:A^{*}\longrightarrow A$ is a relative Rota–Baxter operator on $(A,\succ,\prec)$
  associated with the representation $(A^{*},-R_{\cdot}^{*},L_{\prec}^{*},R_{\succ}^{*},-L_{\cdot}^{*})$.
  \end{enumerate}
  \end{cor}


