\section{Characterization of factorizable anti-dendriform bialgebras}
In this section, we first introduce a notion of quadratic Rota-Baxter anti-dendriform algebras. 
Then we characterize the relationship between factorizable anti-dendriform bialgebras
and quadratic Rota-Baxter anti-dendriform algebras.

A bilinear form $\omega$ on an associative algebra $(A,\cdot)$ is invariant if
$\omega(x\cdot y,z)=\omega(x,y\cdot z)$ for all $x,y,z\in A.$

A symmetric bilinear form $\omega$ on an associative algebra $(A,\cdot)$ 
is called a commutative Connes cocycle \cite{16} if the following equation holds:
\begin{equation*}\omega(x\cdot y,z)+\omega(y\cdot z,x)+\omega(z\cdot x,y)=0,~~\forall~x,y,z\in A.\end{equation*}

\begin{defi} Let $(A,\succ,\prec)$ be an anti-dendriform algebra 
and $\omega$ a non-degenerate symmetric bilinear form.
If $\omega$ is invariant, that is,
\begin{equation} \label{C1}\omega (x\succ y,z)=-\omega(y,z\cdot x), \ \ \
\omega (x\prec y,z)=-\omega(x,y\cdot z), ~\forall~x, y,z \in A.\end{equation}
Then $(A,\succ,\prec,\omega)$ is called a \textbf{quadratic anti-dendriform algebra}.
\end{defi}

\begin{thm}\label{Am3} \cite{4} Let $(A,\cdot)$ be an associative algebra
with a commutative Connes cocycle $\omega$.
 Then there exists a compatible anti-dendriform algebra structure $(A,\succ,\prec)$
 on $(A,\cdot)$ defined by Eq.~(\ref{C1}),
such that $(A,\cdot)$ is the associated associative algebra of $(A,\succ,\prec)$. This anti-dendriform algebra is called 
the compatible anti-dendriform algebra of $(A,\cdot,\omega)$. Moreover, $(A,\succ,\prec,\omega)$ is a quadratic anti-dendriform algebra.
Conversely, assume that $(A,\succ,\prec,\omega)$ is a quadratic anti-dendriform algebra.
Then $(A,\cdot)$ is an associative algebra
with a commutative Connes cocycle $\omega$.
\end{thm}

\begin{defi} Assume that $(A,\succ,\prec,P)$ is a Rota-Baxter anti-dendriform algebra of weight $\lambda$
and $(A,\succ,\prec,\omega)$ is a quadratic anti-dendriform algebra. Then $(A,\succ,\prec,P,\omega)$
is called a \textbf{quadratic Rota-Baxter anti-dendriform algebra of weight $\lambda$} if the following condition holds:
\begin{equation} \label{Fs}\omega (P(x),y)+\omega(x, P(y))+\lambda\omega(x,y)=0, ~\forall~x, y \in A.\end{equation}
\end{defi}

\begin{defi} Let $(A,\cdot,P)$ be a Rota-Baxter associative algebra of weight $\lambda$ and
 $\omega $ be a  commutative Connes cocycle. Then $(A,\cdot,P,\omega)$ is called a \textbf{Rota-Baxter associative
algebra of weight $\lambda$ with a commutative Connes cocycle} if the following condition holds: 
 \begin{equation} \label{Fs1}\omega (P(x),y)+\omega(x, P(y))+\lambda\omega(x,y)=0, ~\forall~x, y \in A.\end{equation}
\end{defi}

The following propositions can be formally derived from the equation:
\begin{align*} &\lambda\omega(x,y)+\omega (-\lambda(x)- P(x),y)+\omega(x, -\lambda(y)- P(y))\\=&
-\lambda\omega(x,y)-\omega (P(x),y)-\omega(x,  P(y)), ~\forall~x, y \in A.\end{align*}
 \begin{pro} \label{Fb2} 
Let $(A,\succ,\prec,\omega)$
 be a quadratic anti-dendriform algebra and let $P : A\longrightarrow A$ be a linear
map. Then $(A,\succ,\prec,P,\omega)$ is a
 quadratic Rota–Baxter anti-dendriform algebra of weight $\lambda$ if and only if $(A,\succ,\prec,-P-\lambda I,-\omega)$
 is a quadratic Rota–Baxter anti-dendriform algebra of weight $\lambda$.
\end{pro}

\begin{pro} 
Let $(A,\cdot,\omega)$
 be a quadratic anti-dendriform algebra and let $P: A\longrightarrow A$ be a linear
map. Then $(A,\cdot,P,\omega)$ is a Rota-Baxter associative
algebra of weight $\lambda$ with a commutative Connes cocycle $\omega$
if and only if $(A,\cdot,-P-\lambda I,-\omega)$ is
a Rota-Baxter associative
algebra of weight $\lambda$ with a commutative Connes cocycle $-\omega$.
\end{pro}

\begin{thm}\label{Fb0} Suppose that $(A,\cdot,P,\omega)$ is a Rota-Baxter associative algebra of 
weight $\lambda$ with a commutative Connes cocycle. Then $(A,\succ,\prec,P,\omega)$ is a quadratic Rota-Baxter anti-dendriform
algebra of weight $\lambda$, where $\succ,\prec$ are defined by Eq.~(\ref{C1}).
 On the other hand, let $(A,\succ,\prec,P,\omega)$ be a quadratic Rota-Baxter anti-dendriform
 algebra of weight $\lambda$.
Then $(A,\cdot,P,\omega)$ is a Rota-Baxter associative algebra of weight $\lambda$ with a commutative Connes cocycle, 
where $\cdot=\succ+\prec$.
\end{thm}

\begin{proof} Let $(A,\cdot,P,\omega)$ be a Rota-Baxter associative algebra of 
weight $\lambda$ with a Connes cocycle. By Theorem \ref{Am3}, $(A,\succ,\prec,\omega)$ is a quadratic anti-dendriform algebra.
Using Eqs. (\ref{C1}) and (\ref{Fs1}), for all $x,y,z\in A$, we have
\begin{align*}& \omega( P(x)\succ P(y)-P(P(x)\succ y+x\succ P(y)+\lambda x\succ y),z)
\\=&-\omega( P(y), z\cdot P(x))+
\omega(P(x)\succ y, P(z))+\omega(x\succ P(y), P(z))\\&+\lambda\omega(x\succ y, P(z))+
\lambda\omega(P(x)\succ y, z)
+\lambda\omega(x\succ P(y), z)
+\lambda^{2}\omega(x\succ y, z)
\\=&
-\omega( P(y), z\cdot P(x))-\omega( y, P(z)\cdot P(x))-\omega( P(y), P(z)\cdot x)
-\lambda\omega( y, P(z)\cdot x)
-\lambda\omega( y, z\cdot P(x))
\\&-\lambda\omega( P(y), z\cdot x)
-\lambda^{2}\omega( y, z\cdot x)
\\=&-\omega( y, P(z)\cdot P(x))-\omega( P(y),  P(z)\cdot x+z\cdot P(x))+\lambda z\cdot x)
-\lambda \omega( y,  P(z)\cdot x+z\cdot P(x)+\lambda z\cdot x)
\\=&-\omega( y, P(z)\cdot P(x))+\omega(y, P( P(z)\cdot x+z\cdot P(x)+\lambda z\cdot x))
\\=&0,\end{align*}
which implies that $P(x)\succ P(y)=P(P(x)\succ y+x\succ P(y)+\lambda x\succ y)$.
Analogously, $P(x)\prec P(y)=P(P(x)\prec y+x\prec P(y)+\lambda x\prec y)$.
Thus, $(A,\succ,\prec,P,\omega)$ is a quadratic Rota-Baxter anti-dendriform algebra of weight $\lambda$.
The other hand is apparently.
We complete the proof.
\end{proof}

Let $\omega$ be a non-degenerate bilinear form on a vector space $A$. Then there is an isomorphism
$\omega^{\sharp}:A\longrightarrow A^{*}$ given by
\begin{equation} \omega(x,y)=\langle\omega^{\sharp}(x),y \rangle,~~\forall~x,y\in A.\end{equation}
Define an element $r_{\omega}\in A\otimes A$ with $T_{r_{\omega}}=(\omega^{\sharp})^{-1}$,
that is, 
\begin{equation}\label{Nd1} \langle T_{r_{\omega}}(\zeta),\eta\rangle=\langle r_{\omega},\zeta \otimes\eta\rangle=
\langle (\omega^{\sharp})^{-1}(\zeta), \eta\rangle. \end{equation}

\begin{lem}\label{Fb1} Let $(A, \succ,\prec)$ be an anti-dendriform algebra and $\omega$ be a non-degenerate bilinear form on $A$. Then
$(A, \succ,\prec,\omega)$ is a quadratic anti-dendriform algebra if and only if the corresponding $r_{\omega}\in A\otimes A$ via
Eq.~(\ref{Nd1}) is symmetric and invariant.\end{lem}
\begin{proof}
It is obvious that $\omega$ is skew-symmetric if and only if  $r_{\omega}$ is symmetric. 
For all $x,y\in A$, put $\omega^{\sharp}(x)=\zeta,\omega^{\sharp}(y)=\eta,
\omega^{\sharp}(z)=\theta$ with $\zeta,\eta,\theta\in A^{*}$, we have
\begin{align*} &\omega (x\succ y,z)+\omega(y,z\cdot x)=\omega(x\succ (\omega^{\sharp})^{-1}(\eta),z)+\omega(y,
(\omega^{\sharp})^{-1}(\theta)\cdot x)
\\=&\langle x\succ (\omega^{\sharp})^{-1}(\eta),\theta\rangle+\langle \eta,(\omega^{\sharp})^{-1}(\theta)\cdot x\rangle
\\=&\langle x ,R_{\succ}^{*} ((\omega^{\sharp})^{-1}\eta)\theta\rangle+\langle L_{\cdot}^{*}((\omega^{\sharp})^{-1}\theta)\eta,
x\rangle
\\=& \langle x ,R_{\succ}^{*} (T_{r_{\omega}}(\eta))\theta+L_{\cdot}^{*}(T_{r_{\omega}}(\theta))\eta\rangle,\\ &
\omega (x\prec y,z)+\omega(x,y\cdot z)=\omega (\omega^{\sharp})^{-1}(\zeta)\prec y,z)+\omega(x,y\cdot (\omega^{\sharp})^{-1}(\theta))
\\=&\langle \theta,(\omega^{\sharp})^{-1}(\zeta)\prec y\rangle+\langle \zeta, y\cdot (\omega^{\sharp})^{-1}(\theta)\rangle
\\=&\langle L_{\prec}^{*}((\omega^{\sharp})^{-1}\zeta)\theta, y\rangle+\langle R_{\cdot}^{*}( (\omega^{\sharp})^{-1}\theta)\zeta, y\rangle
\\=&\langle L_{\prec}^{*}(T_{r_{\omega}}(\zeta))\theta+R_{\cdot}^{*} (T_{r_{\omega}}(\theta))\zeta, y\rangle
.\end{align*}
Combining Lemma \ref{In1}, $r_{\omega}\in A\otimes A$ is invariant if and only if $\omega$ satisfies Eq.~(\ref{C1}).
The proof is completed. 
 \end{proof}


\begin{pro} \label{QF1} Let $(A, \succ,\prec,\omega)$ be a quadratic anti-dendriform algebra and $r\in A\otimes A$. 
Assume that $r+\tau(r)$ is invariant. Define a linear map 
\begin{equation}\label{Nd2}P:A\longrightarrow A,\ \ \ P(x)=T_{r}\omega^{\sharp}(x),~~\forall~x\in A.\end{equation}
Then $r$ is a solution of the AD-YBE in $(A, \succ,\prec)$ if and only if $P$ satisfies 
\begin{align}&\label{Nd3}P(x)\succ P(y)= P(P(x)\succ y+x\succ P(y)+x\succ T_{r+\tau(r)}\omega^{\sharp}(y)),
\\&\label{Nd4}P(x)\prec P(y)= P(P(x)\prec y+x\prec P(y)+x\prec T_{r+\tau(r)}\omega^{\sharp}(y)),~~\forall~x,y\in A.
 \end{align}
\end{pro}

\begin{proof} In the light of Lemma \ref{Fb1}, $r_{\omega}$ is symmetric and invariant.
 For all $x,y\in A$, put $\omega^{\sharp}(x)=\zeta,\omega^{\sharp}(y)=\eta$ with 
$\zeta,\eta\in A^{*}$, we get
\begin{align*}& P(x)\succ P(y)=T_{r}\omega^{\sharp}(x)\succ T_{r}\omega^{\sharp}(y)=T_{r}(\zeta)\succ T_{r}(\eta),\\
&P(P(x)\succ y)=T_{r}\omega^{\sharp}(T_{r}(\zeta)\succ T_{r_{\omega}}(\eta))=
T_{r}\omega^{\sharp} T_{r_{\omega}}(R_{\cdot}^{*}(T_{r}(\zeta))\eta)=T_{r}(R_{\cdot}^{*}(T_{r}(\zeta))\eta),
\\
&P(x\succ P(y))=T_{r}\omega^{\sharp}(T_{r_{\omega}}(\zeta)\succ T_{r}(\eta))=
T_{r}\omega^{\sharp}T_{r_{\omega}}(L_{\prec}^{*}(T_{r}(\eta))\zeta)
=-T_{r}(L_{\prec}^{*}(T_{r}(\eta))\zeta),
\\
&P(x\succ T_{r+\tau(r)}\omega^{\sharp}(y))
=T_{r}\omega^{\sharp}(T_{r_{\omega}}(\zeta)\succ T_{r+\tau(r)}(\eta))
=T_{r}(L_{\prec}^{*}(T_{r+\tau(r)}(\eta))\zeta)
=T_{r}(\zeta\succ_{r+\tau(r)}\eta).\end{align*}
 Thus, Eq.~(\ref{Nd3}) holds if and only if Eq.~(\ref{AD5}) holds.
 Analogously, Eq.~(\ref{Nd4}) holds if and only if Eq.~(\ref{AD6}) holds. The proof is finished.
 \end{proof}

\begin{lem} \label{QF2} Let $A$ be a vector space and $\omega$ be a non-degenerate symmetric bilinear form. Let $r\in A\otimes A$,
$\lambda\in k$ and $P$ be given by Eq.~(\ref{Nd2}). Then $r$ satisfies
\begin{equation} \label{Nd5} r+\tau(r)=-\lambda r_{\omega} \end{equation}
if and only if $P$ satisfies Eq.~(\ref{Fs}).
\end{lem}
\begin{proof} For all $x,y\in A$, put $\omega^{\sharp}(x)=\zeta,\omega^{\sharp}(y)=\eta,~~\zeta,\eta\in A^{*}$.
\begin{align*}& \omega(P(x),y)=\omega(y,P(x))=\langle\omega^{\sharp}(y),T_{r}\omega^{\sharp}(x)\rangle
=\langle \eta,T_{r}(\zeta)\rangle
=\langle r,\zeta\otimes\eta\rangle,\\
&\omega(x,P(y))=\langle \omega^{\sharp}(x),T_{r}\omega^{\sharp}(y)\rangle
=\langle \zeta,T_{r}(\eta)\rangle
=\langle r,\eta\otimes\zeta\rangle
=\langle \tau(r),\zeta\otimes\eta\rangle,
\\
&\lambda\omega(x,y)=\lambda\langle \omega(y,x)
=\lambda\langle \omega^{\sharp}(y),(\omega^{\sharp})^{-1}\omega^{\sharp}(x)\rangle
=\lambda\langle r_{\omega},\zeta\otimes\eta\rangle
.\end{align*}
Thus, Eq.~(\ref{Nd5}) holds if and only if Eq.~(\ref{Fs}) holds.
 \end{proof}

\begin{cor} Let $(A, \succ,\prec,P,\omega)$ be a quadratic Rota–Baxter anti-dendriform algebra of weight 0. Then there is a triangular
anti-dendriform bialgebra $(A, \succ,\prec, \Delta_{\succ_r},\Delta_{\prec_r})$ with $\Delta_{\succ,r},\Delta_{\prec,r}$ given
 by Eqs.~(\ref{CD1})-(\ref{CD2}), where $r\in A\otimes A$ given by 
$T_{r}(\zeta)=P(\omega^{\sharp})^{-1}$ for all $\zeta\in A^{*}$.
\end{cor}

 \begin{proof} Note that $r+\tau(r)=\lambda r_{\omega}=0$ and $r$ is skew-symmetric.
Combining Proposition \ref{QF1} and Lemma \ref{QF2}, we finish the proof.
  \end{proof}

\begin{thm} \label{Fb3} Let $(A, \succ,\prec, \Delta_{\succ_r},\Delta_{\prec_r})$ be a
 factorizable anti-dendriform bialgebra
with $r\in A\otimes A$. Then $(A, \succ,\prec,P,\omega)$
 is a quadratic Rota-Baxter anti-dendriform algebra of
  weight $\lambda$ with $P$ given by Eq.~(\ref{Nd2}) and $\omega$ given by
\begin{equation} \label{Nd6} \omega_{T}(x,y)=-\lambda\langle T_{r+\tau(r)}^{-1}(x),y \rangle,~~\forall~x,y\in A.\end{equation}
Conversely, let $(A, \succ,\prec,P,\omega)$ be a quadratic Rota-Baxter anti-dendriform algebra of weight $\lambda~(\lambda\neq 0)$.
Then there is a factorizable anti-dendriform bialgebra $(A, \succ,\prec,\Delta_{\succ,r},\Delta_{\prec,r})$
 with $\Delta_{\succ,r},\Delta_{\prec,r}$ defined by Eqs.~(\ref{CD1})-(\ref{CD2}), where $r\in A\otimes A$ is
given through the operator form $T_r=P(\omega^{\sharp})^{-1}$.
\end{thm}

\begin{proof}  
In view of $(A, \succ,\prec, \Delta_{\succ,r},\Delta_{\prec,r})$ being a factorizable 
anti-dendriform bialgebra, then $r+\tau(r)$ is invariant and $T_{r+\tau(r)}$ is a linear isomorphism. 
By Proposition \ref{QF1} and Lemma \ref{QF2}, we get that $(A, \succ,\prec,P,\omega)$
 is a quadratic Rota-Baxter anti-dendriform algebra of weight $\lambda$,
  where $\omega^{\sharp}=\lambda T_{r+\tau(r)}^{-1}$. 
 On the other hand, suppose that $(A, \succ,\prec,P,\omega)$ is a quadratic
  Rota-Baxter anti-dendriform algebra of weight $\lambda~(\lambda\neq 0)$.
 In the light of Lemma \ref{Fb1}, Lemma \ref{QF2} and Proposition \ref{QF1}, 
 $r+\tau(r)$ is invariant, $T_{r+\tau(r)}=\lambda (\omega^{\sharp})^{-1}$ is a linear isomorphism
 and $r$ is a solution of the AD-YBE in $(A, \succ,\prec)$. Thus,
  $(A, \succ,\prec,\Delta_{\succ,r},\Delta_{\prec,r})$ is a factorizable anti-dendriform bialgebra.
\end{proof}

\begin{pro} Let $(A, \succ,\prec,P)$ be a Rota–Baxter anti-dendriform algebra of weight $\lambda$. Then 
$(A\ltimes A^{*},-\omega,P-(P^{*}+\lambda I))$
is a quadratic Rota–Baxter anti-dendriform algebra of weight $\lambda$, where the bilinear form $\omega$ on $A\oplus A^{*}$
is given by
\begin{equation*} \omega(x+\zeta,y+\eta)=\langle x,\eta\rangle+\langle y,\zeta\rangle,~~\forall~x,y\in A,~\zeta,\eta\in A^{*}.\end{equation*}
Then $(A\ltimes A^{*}, \Delta_{\succ_r},\Delta_{\prec_r})$
is a factorizable anti-dendriform bialgebra
with $\Delta_{\succ_r},\Delta_{\prec_r}$ defined by Eqs.~(\ref{CD1})-(\ref{CD2}) with $r$ given by $T_r=P(\omega^{\sharp})^{-1}$.
  Explicitly, assume that $\{e_1,\cdot\cdot\cdot, e_n\}$
is a basis of $A$ and $\{e_{1}^{*},\cdot\cdot\cdot, e^{*}_n\}$
is the dual basis, where $r=\sum_{i}(P+\lambda I)(e_{i})\otimes e_{i}^{*}+e_{i}^{*}\otimes P(e_{i})$

\end{pro}

\begin{proof} By direct computations, $(A\ltimes A^{*},-\omega,P-(P^{*}+\lambda I))$
is a quadratic Rota–Baxter anti-dendriform algebra of weight $\lambda$.
For all $x\in A$ and $\zeta\in A^{*}$, $\omega^{\sharp}(x+\zeta)=x-\zeta$. By Corollary \ref{Fb3}, we have a linear map
$T_{r}:A\oplus A^{*}\longrightarrow A\oplus A^{*}$ defined by
\begin{equation*} 
T_{r}(x+\zeta)=(P-(P^{*}+\lambda I))(\omega^{\sharp})^{-1}(x+\zeta)=P(x)+(P^{*}+\lambda I)(\zeta).\end{equation*}
Thus, 
\begin{align*}&
\sum_{i,j}\langle r,e_{i}\otimes e_{j}^{*}\rangle=\sum_{i,j}\langle T_{r}(e_{i}), e_{j}^{*}\rangle=\sum_{i,j}\langle P(e_{i}), e_{j}^{*}\rangle
\\&\sum_{i,j}\langle r,e_{i}\otimes e_{j}^{*}\rangle=\sum_{i,j}\langle T_{r}(e_{i}^{*}), e_{j}\rangle=\sum_{i,j}\langle (P^{*}+\lambda I)(e_{i}^{*}), e_{j}\rangle=\sum_{i,j}\langle e_{i}^{*}, (P+\lambda I)(e_{j})\rangle.\end{align*}
Thus, $r=\sum_{i}(P+\lambda I)(e_{i})\otimes e_{i}^{*}+e_{i}^{*}\otimes P(e_{i})$.
\end{proof}

According to Theorem \ref{Fb3}, quadratic Rota-Baxter anti-dendriform algebras of non-zero weight $\lambda$ 
are one to one correspondence to factorizable anti-dendriform bialgebras. Combining Theorem \ref{Fb0}, a
Rota-Baxter associative algebra of weight $\lambda$ with a commutative Connes cocycle 
corresponds to factorizable anti-dendriform bialgebras.

In the light of Proposition \ref{Fb2} and Theorem \ref{Fb3}, 
if $(A,\succ,\prec,P,\omega)$ is a quadratic Rota–Baxter anti-dendriform algebra of non-zero weight corresponds to a 
factorizable anti-dendriform bialgebra, then the quadratic Rota–Baxter anti-dendriform algebra $(A,\succ,\prec,-\lambda I-P,-\omega)$
of non-zero weight is also corresponds to a factorizable anti-dendriform bialgebra.
By Proposition \ref{Qf} and Theorem \ref{Fb3}, if $(A, \succ,\prec, \Delta_{\succ,r},\Delta_{\prec,r})$ is a factorizable 
anti-dendriform bialgebra, then the factorizable 
anti-dendriform bialgebra $(A, \succ,\prec, \Delta_{\succ,\tau(r)},\Delta_{\prec,\tau(r)})$ gives rise to a 
quadratic Rota–Baxter anti-dendriform algebra of non-zero weight $\lambda$.
In fact, we have

\begin{pro}
Let $(A, \succ,\prec, \Delta_{\succ,r},\Delta_{\prec,r})$ be a factorizable 
anti-dendriform bialgebra which corresponds to a quadratic Rota-Baxter anti-dendriform algebras of non-zero weight $\lambda$. 
Then the factorizable 
anti-dendriform bialgebra $(A, \succ,\prec, \Delta_{\succ,\tau(r)},\Delta_{\prec,\tau(r)})$ corresponds to the 
quadratic Rota–Baxter anti-dendriform algebra $(A,\succ,\prec,-\lambda I-P,-\omega)$ of non-zero weight $\lambda$. 
\end{pro}

\begin{proof} 
By Proposition \ref{Qf} and Theorem \ref{Fb1}, the factorizable 
anti-dendriform bialgebra $(A, \succ,\prec, \Delta_{\succ,\tau(r)},\Delta_{\prec,\tau(r)})$ corresponds to a
quadratic Rota-Baxter anti-dendriform algebra $(A,\succ,\prec,P',\omega')$ of non-zero weight $\lambda$.
By Theorem \ref{Fb3},
\begin{equation*} 
\omega'(x,y)=-\lambda\langle T_{r+\tau(r)}^{-1}(x),y \rangle=-\omega(x,y).\end{equation*}
Using Eqs.~(\ref{Nd2}) and (\ref{Nd6}), 
\begin{align*} 
P'(x)= T_{\tau(r)}{\omega^{'}}^{\sharp}(x)=- T_{\tau(r)}\omega^{\sharp}(x)
&=\lambda T_{\tau(r)}T_{r+\tau(r)}^{-1}(x)=\lambda (T_{r}-T_{r+\tau(r)})T_{r+\tau(r)}^{-1}(x)
\\&=\lambda T_{r}T_{r+\tau(r)}^{-1}(x)-\lambda (x)
=-T_{r}\omega^{\sharp}(x)-\lambda (x)=-P(x)-\lambda (x)
.\end{align*}
Thus, the factorizable 
anti-dendriform bialgebra $(A, \succ,\prec, \Delta_{\succ,\tau(r)},\Delta_{\prec,\tau(r)})$ generates a
quadratic Rota-Baxter anti-dendriform algebra $(A,\succ,\prec,-\lambda I-P,-\omega)$ of non-zero weight $\lambda$.
Analogously, the converse part holds.
\end{proof} 


