\section{Code to Generate Comparison CEG}
\label{app:comparisoncode}
\begin{minipage}{\textwidth}
\textcolor{ForestGreen}{\texttt{\#Creating event tree}}\\
\texttt{homicides$\_$ET <- create$\_$event$\_$tree(dataset = homicides, columns = c(\textcolor{blue}{3},\textcolor{blue}{2},\textcolor{blue}{4},\textcolor{blue}{5})))}\\

\textcolor{ForestGreen}{\texttt{\#Colouring fully using AHC algorithm}}\\
\texttt{homicides$\_$AHC <- ahc$\_$colouring(homicides$\_$ET)}\\

\texttt{\textcolor{ForestGreen}{\#Uninformative Uniform priors}\\
priors$\_$AHC <- specify$\_$priors(homicides$\_$AHC,  \textcolor{ForestGreen}{"Uniform"}, ask$\_$edit = \textcolor{Periwinkle}{FALSE})}\\

\textcolor{ForestGreen}{\texttt{\#Adding priors to tree}}\\
\texttt{homicides$\_$ST$\_$AHC <- staged$\_$tree$\_$prior(homicides$\_$AHC, priors$\_$AHC)}\\

\textcolor{ForestGreen}{\texttt{\#Creating CEG}}\\
\texttt{homicides$\_$CEG$\_$AHC <- create$\_$ceg(homicides$\_$ST$\_$AHC, label = \textcolor{ForestGreen}{"posterior$\_$mean"})}\\
\end{minipage}


\section{Code to Generate Spatial CEG} \label{app:spatialcode}
\begin{minipage}{\textwidth}

\textcolor{ForestGreen}{\texttt{\#Takes a while to run as the model is large}}

\textcolor{ForestGreen}{\texttt{\#Creating event tree}}\\
\texttt{homicides$\_$ET$\_$spatial <- create$\_$event$\_$tree(dataset = homicides, columns = c(\textcolor{blue}{6},\textcolor{blue}{3},\textcolor{blue}{2},\textcolor{blue}{4},\textcolor{blue}{5}) , level$\_$separation = \textcolor{blue}{1300}, node$\_$distance = \textcolor{blue}{300}, label$\_$type = \textcolor{ForestGreen}{"both"})}\\

\textcolor{ForestGreen}{\texttt{\#Colouring fully using AHC algorithm}}\\
\texttt{homicides$\_$AHC$\_$spatial <- ahc$\_$colouring(homicides$\_$ET$\_$spatial, level$\_$separation = \textcolor{blue}{1300}, node$\_$distance = \textcolor{blue}{300})}\\

\textcolor{ForestGreen}{\texttt{\#Uninformative priors}}\\
\texttt{priors <- specify$\_$priors(homicides$\_$AHC$\_$spatial, \textcolor{ForestGreen}{"Phantom"}, ask$\_$edit = \textcolor{Periwinkle}{FALSE})}\\

\textcolor{ForestGreen}{\texttt{\#Adding priors to tree}}\\
\texttt{homicides$\_$ST$\_$spatial <- staged$\_$tree$\_$prior(homicides$\_$AHC$\_$spatial, priors, level$\_$separation = \textcolor{blue}{1300}, node$\_$distance = \textcolor{blue}{300})}\\

\textcolor{ForestGreen}{\texttt{\#Creating CEG}}\\
\texttt{homicides$\_$CEG$\_$spatial <- create$\_$ceg(homicides$\_$ST$\_$spatial, view$\_$table = \textcolor{Periwinkle}{TRUE}, label = \textcolor{ForestGreen}{"posterior$\_$mean"}, level$\_$separation = \textcolor{blue}{1500})}
\end{minipage}

