\section*{Methods}

We begin by formulating both the internal and external scalar potentials as boundary integrals of Green’s functions. Based on this formulation, we rigorously establish that, in the limit of infinite magnetic permeability, the internal potential approaches a quasi-equipotential state, while the external potential exhibits a geometric invariance governed solely by the boundary geometry. Finally, we derive integral expressions for the magnetic dipole moment and quadrupole tensor directly from the internal scalar potential.

\subsection {Proof of the quasi-equipotential and geometric invariance}

In the limit of infinite permeability within the region \(\Omega\), the normal derivative of the scalar  potential at the boundary satisfies
\[
\frac{\partial \phi^-}{\partial \mathbf{n}} = \frac{\mu_0}{\mu} \frac{\partial \phi^+}{\partial \mathbf{n}}\to 0,
\]
implying that the problem reduces to an \textit{interior Neumann problem} for the potential \(\phi^-\) with quasi-zero normal derivative on the boundary:
\begin{equation}\label{interior Neumann problem}
	\begin{cases}
		\Delta\phi^-(\mathbf{r})=0,&\mathbf{r}\in\Omega\\
		\frac{\partial\phi^-}{\partial\mathbf{n}}=f(\mathbf{r})\to0,&\mathbf{r}\in\partial\Omega.
	\end{cases}
\end{equation}
given the Neumann Green function which satisfies
\begin{equation}\label{interior Neumann Green function}
	\begin{cases}
		\Delta G(\mathbf{r}-\mathbf{r}^{\prime})=-\delta(\mathbf{r}-\mathbf{r}^{\prime}),&\mathbf{r},\mathbf{r}^{\prime}\in\Omega\\\frac{\partial G(\mathbf{r}-\mathbf{r}^{\prime})}{\partial\mathbf{n}}=-\frac{1}{\mathrm{A}},&\mathbf{r}\in\partial\Omega,\mathbf{r}^{\prime}\in\Omega,
	\end{cases}
\end{equation}
where A denotes the area of the boundary surface \(\partial\Omega\).  The potential in \(\Omega\) is
\begin{equation}\label{formal solution of interior potential}
	\begin{aligned}
		\phi^{-}(\mathbf{r})&=\int_{\partial\Omega}dS^{\prime}G(\mathbf{r}-\mathbf{r}^{\prime})\frac{\partial\phi^-}{\partial\mathbf{n}^{\prime}}-\int_{\partial\Omega}dS^{\prime}\phi^-\frac{\partial G(\mathbf{r}-\mathbf{r}^{\prime})}{\partial\mathbf{n}^{\prime}}\\&=\int_{\partial\Omega}dS^{\prime}G(\mathbf{r}-\mathbf{r}^{\prime})f(\mathbf{r}^{\prime})|_{f(\mathbf{r}^{\prime})\to0}+\frac{1}{\mathrm{A}}\int_{\partial\Omega}dS^{\prime}\phi^{-}(\mathbf{r}^{\prime})\\&\to\phi_{0},
	\end{aligned}
\end{equation}
where 
\[\phi_0=\frac{1}{\mathrm{A}}\int_{\partial\Omega}dS^{\prime}\phi^-(\mathbf{r}^{\prime}).\]

The equations \ref{formal solution of interior potential} show that the internal potential approaches a constant value in the infinite-permeability limit. Note that,the solution to the Laplace equation with Neumann boundary conditions is determined only up to an additive constant, reflecting a global degree of freedom inherent to the problem. Specifically, if $\phi_0$ is a solution, then $\phi_0 + C$, with $C$ constant, is equally valid. In the presence of a background potential field $\phi^{\mathrm{bg}}(\mathbf{r})$, however, this indeterminacy propagates to the background potential. To fix the gauge, we set $\phi_0 = 0$. By continuity, the surface potential $\phi|_{\partial\Omega}$ likewise tends to zero. The resulting exterior problem is thus a Dirichlet problem for the Laplace equation with quasi-zero boundary values on $\partial\Omega^{\mathrm{out}}$:

\begin{equation}\label{exterior Dirichlet problem_Appendixes}
	\begin{cases}
		\Delta\phi^+(\mathbf{r})=0,&\mathbf{r}\in\mathbb{R}^d\setminus\overline{\Omega}\\ \phi^+(\mathbf{r})\to0,&\mathbf{r}\in\partial\Omega^{out}\\\phi^+(\mathbf{r})\to\phi^{bg}(\mathbf{r}),&\left|\mathbf{r}\right|\to\infty.
	\end{cases}
\end{equation}
Let \(\phi^+(\mathbf{r})=u(\mathbf{r})+\phi^{bg}(\mathbf{r})\), the perturbation term \(u(\mathbf{r})\) satisfies
\begin{equation}\label{perturbation term}
	\begin{cases}\Delta u(\mathbf{r})=0,&\mathbf{r}\in\mathbb{R}^d\setminus\overline{\Omega}
		\\u(\mathbf{r})\to-\phi^{bg},&\mathbf{r}\in\partial\Omega^{out}
		\\u(\mathbf{r})\to0,&|\mathbf{r}|\to\infty.
	\end{cases}
\end{equation}
Given the Dirichlet Green function which satisfies
\begin{equation}
	\begin{cases}
		\Delta G(\mathbf{r}-\mathbf{r}^{\prime})=-\delta(\mathbf{r}-\mathbf{r}^{\prime}),\quad\mathbf{r},\mathbf{r}^{\prime}\in\mathbb{R}^d\setminus\overline{\Omega}\\
		G(\mathbf{r}-\mathbf{r}^{\prime})=0,\quad\mathbf{r}\in\partial\Omega^{out},\mathbf{r}^{\prime}\in\mathbb{R}^d\setminus\overline{\Omega}\\
		G(\mathbf{r}-\mathbf{r}^{\prime})\to0,\quad|\mathbf{r}-\mathbf{r}^{\prime}|\to\infty,\mathbf{r}\in\partial\Omega^{out},\mathbf{r}^{\prime}\in\mathbb{R}^d\setminus\overline{\Omega}. &
	\end{cases}
\end{equation}
the formal solution of the equations \ref{perturbation term} can be composed of the integral of Green function on the boundary,

\begin{equation}\label{formal solution of exterior potentia_Appendixes}
	\begin{aligned}
		u(\mathbf{r})&=\int_{\partial\Omega^{out}}dS^{\prime}G(\mathbf{r}-\mathbf{r}^{\prime})\frac{\partial\phi^{+}}{\partial\mathbf{n}^{\prime}}-\int_{\partial\Omega}dS^{\prime}u(\mathbf{r}^{\prime})\frac{\partial G(\mathbf{r}-\mathbf{r}^{\prime})}{\partial\mathbf{n}^{\prime}}
		\\&=-\int_{\partial\Omega^{out}}dS^{\prime}u(\mathbf{r}^{\prime})\frac{\partial G(\mathbf{r}-\mathbf{r}^{\prime})}{\partial\mathbf{n}^{\prime}}
		\\&\to\int_{\partial\Omega^{out}}dS^{\prime}\phi^{bg}(\mathbf{r}^{\prime})\frac{\partial G(\mathbf{r}-\mathbf{r}^{\prime})}{\partial\mathbf{n}^{\prime}}.
	\end{aligned}
\end{equation}
Equation~\ref{formal solution of exterior potentia_Appendixes} shows that the solution to the boundary value problem depends continuously on the boundary condition. Hence, the exterior potential \(\phi^+\) converges to a unique limiting configuration, thereby establishing the geometric invariance discussed in this paper. 

\subsection{Integral expressions for the multipole}
On the other hand, the perturbation term  \(u(\mathbf{r})\) can be expanded in terms of magnetic multipole moments associated with the magnetized body:
\begin{equation}
	u(\mathbf{r})=\phi_{mono}+\phi_{dipole}+\phi_{duadrupole}+...
\end{equation}

The perturbation term \( u(\mathbf{r}) \) is entirely determined by the magnetization distribution within the magnetized body. From the perspective of equivalent magnetic charges, and by direct analogy with the electrostatic problem, \( u(\mathbf{r}) \) arises from the combined contributions of volume magnetic charges and surface magnetic charges on the boundary. 

\subsubsection{3D case}
In the three-dimensional case,
\begin{equation}
	u(\mathbf{r})=\frac{1}{4\pi}\int_{\Omega}dV^{\prime}\frac{\rho_m}{\left|\mathbf{r}-\mathbf{r}^{\prime}\right|}+\frac{1}{4\pi}\int_{\partial\Omega}dS^{\prime}\frac{\sigma_m}{\left|\mathbf{r}-\mathbf{r}^{\prime}\right|}.
\end{equation}
By substituting \(\rho_m=-\nabla \cdot \mathbf{M}(\mathbf{r}) \) and \(\sigma_m=\mathbf{n}\cdot\mathbf{M}\),

\begin{equation}
	\begin{aligned}
		u(\mathbf{r})&=-\frac{1}{4\pi}\int_{\Omega}dV^{\prime}\frac{\nabla^{\prime}\cdot\mathbf{M}(\mathbf{r}^{\prime})}{|\mathbf{r}-\mathbf{r}^{\prime}|}+\frac{1}{4\pi}\int_{\partial\Omega}dS^{\prime}\frac{\mathbf{n}^{\prime}\cdot\mathbf{M}(\mathbf{r}^{\prime})}{|\mathbf{r}-\mathbf{r}^{\prime}|}\\&=\frac{1}{4\pi}\int_{\Omega}dV^{\prime}\mathbf{M}(\mathbf{r}^{\prime})\cdot\nabla^{\prime}\frac{1}{|\mathbf{r}-\mathbf{r}^{\prime}|}.
	\end{aligned}
\end{equation}
Using the expansion
\begin{equation}
	\frac{1}{\left|\mathbf{r}-\mathbf{r}^{\prime}\right|}=\frac{1}{r}-\mathbf{r}^{\prime}\cdot\nabla\frac{1}{r}+\frac{1}{2}\left(\mathbf{r}^{\prime}\cdot\nabla\right)^2\frac{1}{r}+...,
\end{equation}
we can derive the expressions for the multipole terms in \( u(\mathbf{r}) \) as follows.
\begin{equation}
	\phi_{mono}=\frac{1}{4\pi}\int_{\Omega}dV^{\prime}\mathbf{M}(\mathbf{r}^{\prime})\cdot\nabla^{\prime}\frac{1}{r}=0.
\end{equation}

\begin{equation}
	\begin{aligned}
		\phi_{dipole}&=\frac{1}{4\pi}\int_\Omega dV^{\prime}\mathbf{M}(\mathbf{r}^{\prime})\cdot\nabla^{\prime}\left[-\mathbf{r}^{\prime}\cdot\nabla\frac{1}{r}\right]\\&=\frac{1}{4\pi}\int_{\Omega}dV^{\prime}M_{i}(\mathbf{r}^{\prime})\frac{\partial}{\partial r_{i}^{\prime}}\left[-r_{\alpha}^{\prime}\frac{\partial}{\partial r_{\alpha}}\frac{1}{r}\right]\\&=\frac{1}{4\pi}\int_\Omega dV^{\prime}M_i(\mathbf{r}^{\prime})\frac{r_i}{r^3}\\&=\frac{1}{4\pi}\frac{r_i}{r^3}\int_\Omega dV^{\prime}M_i(\mathbf{r}^{\prime})\\&=\frac{1}{4\pi}\frac{r_i}{r^3}m_i\\&=\frac{1}{4\pi}\frac{\mathbf{r}\cdot\mathbf{m}}{r^3},
	\end{aligned}
\end{equation}
where dipole moment 
\begin{equation}
	\mathbf{m}=\int_{\Omega}dV^{\prime}\mathbf{M}(\mathbf{r}^{\prime}),\quad m_i=\int_{\Omega}dV^{\prime}M_i(\mathbf{r}^{\prime}).
\end{equation}

\begin{equation}
	\begin{aligned}
		\phi_{duadrupole}&=\frac{1}{4\pi}\int_{\Omega}dV^{\prime}\mathbf{M}(\mathbf{r}^{\prime})\cdot\nabla^{\prime}\left[\frac{1}{2}\left(\mathbf{r}^{\prime}\cdot\nabla\right)^{2}\frac{1}{r}\right]\\
		&=\frac{1}{4\pi}\int_\Omega dV^{\prime}M_i(\mathbf{r}^{\prime})\frac{\partial}{\partial r_i^{\prime}}\left[\frac{1}{2}r_\alpha^{\prime}r_\beta^{\prime}\frac{\partial^2}{\partial r_\alpha\partial r_\beta}\frac{1}{r}\right]\\
		&=\frac{1}{4\pi}\int_{\Omega}dV^{\prime}M_{i}(\mathbf{r}^{\prime})\frac{\partial}{\partial r_{i}^{\prime}}\left[\frac{1}{2}r_{\alpha}^{\prime}r_{\beta}^{\prime}\left(\frac{3r_{\alpha}r_{\beta}-\delta_{\alpha\beta}r^{2}}{r^{5}}\right)\right]\\
		&=\frac{1}{4\pi}\cdot\frac{1}{2}\left(\frac{3r_\alpha r_\beta-\delta_{\alpha\beta}r^2}{r^5}\right)\int_\Omega dV^{\prime}M_i(\mathbf{r}^{\prime})\frac{\partial}{\partial r_i^{\prime}}\left(r_\alpha^{\prime}r_\beta^{\prime}\right)\\
		&=\frac{1}{4\pi}\cdot\frac{1}{2}\sum_{\alpha,\beta}\left(\frac{3r_{\alpha}r_{\beta}-\delta_{\alpha\beta}r^{2}}{r^{5}}\right)\bar{Q}_{\alpha\beta},
	\end{aligned}
\end{equation}
where 
\[
\begin{aligned}
	\bar{Q}_{\alpha\beta}&=\int_{\Omega}dV^{\prime}M_{i}(\mathbf{r}^{\prime})\frac{\partial}{\partial r_{i}^{\prime}}\left(r_{\alpha}^{\prime}r_{\beta}^{\prime}\right)\\&=\int_{\Omega}dV^{\prime}\left[M_{\alpha}(\mathbf{r}^{\prime})r_{\beta}^{\prime}+M_{\beta}(\mathbf{r}^{\prime})r_{\alpha}^{\prime}\right].
\end{aligned}
\]
The trace of \(\bar{\mathbf{Q}}\) is 
\[
\mathrm{Tr}(\bar{\mathbf{Q}})=2\int_{\Omega}dV^{\prime}\left[\mathbf{M}(\mathbf{r}^{\prime})\cdot\mathbf{r}^{\prime}\right].
\]
Removing the trace from \(\bar{\mathbf{Q}}\) to construct the traceless tensor \(\mathbf{Q}\):

\begin{equation}
	\begin{aligned}
		Q_{ij}&=\bar{Q}_{ij}-\frac{1}{3}\delta_{ij}\mathrm{Tr}(\bar{\mathbf{Q}})\\&=\int_{\Omega}dV^{\prime}\left[M_{i}(\mathbf{r}^{\prime})r_{j}^{\prime}+M_{j}(\mathbf{r}^{\prime})r_{i}^{\prime}-\frac{2}{3}\delta_{ij}\mathbf{M}(\mathbf{r}^{\prime})\cdot\mathbf{r}^{\prime}\right].
	\end{aligned}
\end{equation}
Then
\begin{equation}
	\begin{aligned}
		\phi_{duadrupole}&=\frac{1}{4\pi}\cdot\frac{1}{2}\sum_{i,j}\left(\frac{3r_ir_j-\delta_{ij}r^2}{r^5}\right)\left(Q_{ij}+\frac{1}{3}\delta_{ij}\operatorname{Tr}(\bar{\mathbf{Q}})\right)\\&=\frac{1}{4\pi}\cdot\frac{1}{2}\sum_{i,j}\frac{3r_ir_j}{r^5}Q_{ij}.
	\end{aligned}
\end{equation}
From the above, we obtain
\begin{equation}
	\begin{aligned}
		u(\mathbf{r})&=\phi_{mono}+\phi_{dipole}+\phi_{duadrupole}+...\\&=\quad\frac{1}{4\pi}\left[0+\frac{\mathbf{r}\cdot\mathbf{m}}{r^3}+\frac{1}{2}\sum_{i,j}\frac{3r_ir_j}{r^5}Q_{ij}+...\right].
	\end{aligned}
\end{equation}
Higher-order multipole terms involve increasingly cumbersome expressions and are not presented here for brevity.

\subsubsection{2D case}
In the two-dimensional case,
\begin{equation}
	\begin{aligned}
		u(\mathbf{r})&=-\frac{1}{2\pi}\int_{\Omega}dS^{\prime}\left[-\nabla^{\prime}\cdot\mathbf{M}(\mathbf{r}^{\prime})\right]\ln\left|\mathbf{r}-\mathbf{r}^{\prime}\right|-\frac{1}{2\pi}\int_{\partial\Omega}dl^{\prime}\mathbf{n}^{\prime}\cdot\mathbf{M}(\mathbf{r}^{\prime})\ln\left|\mathbf{r}-\mathbf{r}^{\prime}\right|\\&=-\frac{1}{2\pi}\int_{\Omega}dS^{\prime}\mathbf{M}(\mathbf{r}^{\prime})\cdot\nabla^{\prime}\left[\ln|\mathbf{r}-\mathbf{r}^{\prime}|\right].
	\end{aligned}
\end{equation}
Proceeding similarly, we derive
\begin{equation}
	\begin{aligned}u(\mathbf{r})&=\phi_{mono}+\phi_{dipole}+\phi_{duadrupole}+...\\&=\quad\frac{1}{2\pi}\left[0+\frac{\mathbf{r}\cdot\mathbf{m}}{r^2}+\frac{1}{2}\sum_{i,j}\frac{2r_ir_j}{r^4}Q_{ij}+...\right],
	\end{aligned}
\end{equation}
where 
\[
\mathbf{m}=\int_{\Omega}dS^{\prime}\mathbf{M}(\mathbf{r}^{\prime}),m_i=\int_{\Omega}dS^{\prime}M_i(\mathbf{r}^{\prime}),
\]
and 
\begin{equation}
	Q_{ij}=\int_{\Omega}dS^{\prime}\left[M_i(\mathbf{r}^{\prime})r_j^{\prime}+M_j(\mathbf{r}^{\prime})r_i^{\prime}-\delta_{ij}\mathbf{M}(\mathbf{r}^{\prime})\cdot\mathbf{r}^{\prime}\right].
\end{equation}
Specifically, a symmetric and traceless second-order tensor \(\mathbf{Q}\) in two dimensions has only two degrees of freedom, and can be written as
\[
\mathbf{Q} = \begin{bmatrix} Q_{xx} & Q_{xy} \\ Q_{xy} & -Q_{xx} \end{bmatrix}.
\]



