\begin{enumerate}
\item When $R \in \{0, \ldots, a\}$: in this case, we have \[\begin{aligned}
\psi &= (g^{a}) \cdot \varphi^{f} \cdot ( g^{b}\varphi^{-f} g^{c} \varphi^{e} g^{-d} \varphi^{-e}),
\\
v &= (g^{-R} \varphi^{e - K_{sep}}) \cdot \varphi^{K_{sep}}g^{d} \cdot (\varphi^{-e} g^{-c} \varphi^{f}g^{-b} \varphi^{-f } \cdot g^{R-a}).
\end{aligned}
\]
Here, note that \[\begin{aligned}
|g^{a}|_{\C*} &=_{10C}al_{g} \le R l_{g} + (e-K_{sep})l_{\varphi} =_{10C} | g^{-R} \varphi^{e-K_{sep}}|_{\C*}, \\
|g^{b}\varphi^{-f} g^{c} \varphi^{e} g^{-d} \varphi^{-e}|_{\C*} &=_{10C} (b+c+d)l_{g} + (2e+f)l_{\varphi} \\
&\le (b+c) l_{g} + (e + 2f) l_{\varphi} + (a-R) l_{g} =_{10C} |\varphi^{-e} g^{-c} \varphi^{f}g^{-b} \varphi^{-f } \cdot g^{R-a}|_{\C*}.
\end{aligned}
\]
Furthermore, we have $|\varphi^{K_{sep}}|_{\C*} \ge_{2C} 0.5C \cdot K_{Sep} \ge K_{sep}$. Likewise, for large $d \gg K_{sep}$ we have $|g^{d}|_{\C*}\ge K_{sep}$. Hence, the 4 inequalities in Display \ref{eqn:contra4Ineq} hold, a contradiction.

\item When $R \in \{a, \ldots, a + f - 2e \}$ : we have \[\begin{aligned}
\psi &= (g^{a}) \cdot \varphi^{f} \cdot ( g^{b}\varphi^{-f} g^{c} \varphi^{e} g^{-d} \varphi^{-e}),
\\
v &= (\varphi^{-(R-a)} g^{-a} \varphi^{e - K_{sep}}) \cdot \varphi^{K_{sep}}g^{d} \cdot (\varphi^{-e} g^{-c} \varphi^{f}g^{-b} \varphi^{-f + (R-a)}).
\end{aligned}
\]
Here, note that \[\begin{aligned}
|g^{a}|_{\C*} &=_{10C}al_{g} \le al_{g} + (e-K_{sep}+(R-a)) l_{\varphi} =_{10C} | \varphi^{-(R-a)}g^{-a} \varphi^{e-K_{sep}}|_{\C*}, \\
|g^{b}\varphi^{-f} g^{c} \varphi^{e} g^{-d} \varphi^{-e}|_{\C*} &=_{10C} (b+c+d)l_{g} + (2e+f)l_{\varphi} \le (b+c) l_{g} + (3e+f) l_{\varphi}\\
&\le (b+c) l_{g} + (e +2f - (R-a)) l_{\varphi}  =_{10C} |\varphi^{-e} g^{-c} \varphi^{f}g^{-b} \varphi^{-f + (R-a)}|_{\C*}.
\end{aligned}
\]
We also again have $|g^{-d}|_{\C*}, |\varphi^{K_{sep}}|_{\C*} \ge K_{sep}$, a contradiction. 



\item $R \in \{a+f-2e, \ldots, a+ f\}$: we have \[\begin{aligned}
\psi &= (g^{a}  \varphi^{f}  g^{b}) \cdot \varphi^{-f} \cdot (g^{c} \varphi^{e} g^{-d} \varphi^{-e}),
\\
v &= (\varphi^{-(R-a)} g^{-a} \varphi^{e } g^{d} \cdot \varphi^{-e +K_{sep}}) \cdot \varphi^{-K_{sep}} g^{-c} \cdot (\varphi^{f}g^{-b} \varphi^{-f + (R-a)}).
\end{aligned}
\]
Note that \[
\begin{aligned}
|g^{a}\varphi^{f} g^{b}|_{\C*} &=_{10C}(a+b) l_{g} + f l_{\varphi} \le (a+d)l_{g} + (f - K_{sep})l_{\varphi} \\
&\le (a+d)l_{g} + (R-a + 2e - K_{sep}) l_{\varphi} =_{10C} |\varphi^{-(R-a)} g^{-a} \varphi^{e } g^{d} \cdot \varphi^{-e +K_{sep}} |_{\C*}, \\
|g^{c} \varphi^{e} g^{-d} \varphi^{-e}|_{\C*} &=_{10C} (c+d)l_{g} + 2e l_{\varphi} \le f l_{g} \\
&\le fl_{g} + (2f - R + a)  l_{\varphi} =_{10C} |\varphi^{f}g^{-b} \varphi^{-f + (R-a)}|_{\C*}.
\end{aligned}
\]
Further, $|\varphi^{-K_{sep}}|_{\C*}, |g^{-c}|_{\C*} \ge K_{sep}$. This contradicts Display \ref{eqn:contra4Ineq}.



\item $R \in \{a+f, \ldots, a+ f+b\}$: we have \[\begin{aligned}
\psi &= (g^{a}  \varphi^{f}  g^{b}) \cdot \varphi^{-f} \cdot (g^{c} \varphi^{e} g^{-d} \varphi^{-e}),
\\
v &= (g^{-(R - a - f)}\varphi^{-f} g^{-a} \varphi^{e } g^{d} \cdot \varphi^{-e +K_{sep}}) \cdot \varphi^{-K_{sep}} g^{-c} \cdot (\varphi^{f}g^{-b + (R-a-f)}).
\end{aligned}
\]
Note that \[
\begin{aligned}
|g^{a}\varphi^{f} g^{b}|_{\C*} &=_{10C}(a+b) l_{g} + f l_{\varphi} \le (a+d)l_{g} + (f - K_{sep})l_{\varphi} \\
&\le (a+d + (R-a-f))l_{g} + (2e  + f - K_{sep}) l_{\varphi} \\
&=_{10C} |g^{-(R - a - f)}\varphi^{-f} g^{-a} \varphi^{e } g^{d} \cdot \varphi^{-e +K_{sep}} |_{\C*}, \\
|g^{c} \varphi^{e} g^{-d} \varphi^{-e}|_{\C*} &=_{10C} (c+d)l_{g} + 2e l_{\varphi} \le f l_{g} \\
&\le fl_{g} + (2f - R + a)  l_{\varphi} =_{10C} |\varphi^{f}g^{-b + (R-a-f)}|_{\C*}.
\end{aligned}
\]
Further, $|\varphi^{-K_{sep}}|_{\C*}, |g^{-c}|_{\C*} \ge K_{sep}$. This contradicts Display \ref{eqn:contra4Ineq}.





\item $R \in \{a+f+b, \ldots, a+ f+2b\}$: we have \[\begin{aligned}
\psi &= (g^{a}  \varphi^{f}  g^{b}) \cdot \varphi^{-f} \cdot (g^{c} \varphi^{e} g^{-d} \varphi^{-e}),
\\
v &= (\varphi^{R - (a+f+b)}g^{-b}\varphi^{-f} g^{-a} \varphi^{e } g^{d}  \varphi^{-e +K_{sep}}) \cdot \varphi^{-K_{sep}} g^{-c} \cdot (\varphi^{a+b+2f - R}).
\end{aligned}
\]
Note that \[
\begin{aligned}
|g^{a}\varphi^{f} g^{b}|_{\C*} &=_{10C}(a+b) l_{g} + f l_{\varphi} \le (a+d)l_{g} + (f - K_{sep})l_{\varphi} \\
&\le (a+b+d)l_{g} + (2e  + R -a-b - K_{sep} ) l_{\varphi} \\
&=_{10C} |\varphi^{R - (a+f+b)}g^{-b}\varphi^{-f} g^{-a} \varphi^{e } g^{d}  \varphi^{-e +K_{sep}} |_{\C*}, \\
|g^{c} \varphi^{e} g^{-d} \varphi^{-e}|_{\C*} &=_{10C} (c+d)l_{g} + 2e l_{\varphi} \le (f-b) l_{g} \\
&\le (a+b+2f - R)  l_{\varphi} =_{10C} |\varphi^{a+b+2f - R}|_{\C*}.
\end{aligned}
\]
Further, $|\varphi^{-K_{sep}}|_{\C*}, |g^{-c}|_{\C*} \ge K_{sep}$. This contradicts Display \ref{eqn:contra4Ineq}.



\item $R \in \{a+f+2b, \ldots, a+ 2f+b\}$: we have \[\begin{aligned}
\psi &= (g^{a}  \varphi^{f}  g^{b}) \cdot \varphi^{-f} \cdot (g^{c} \varphi^{e} g^{-d} \varphi^{-e}),
\\
v &= (\varphi^{R - (a+f+b)}g^{-b}\varphi^{-f + K_{sep} }) \cdot \varphi^{-K_{sep}}g^{-a} \cdot (\varphi^{e} g^{d} \varphi^{-e } g^{-c} \varphi^{a+b+2f - R}).
\end{aligned}
\]
Note that \[
\begin{aligned}
|g^{a}\varphi^{f} g^{b}|_{\C*} &=_{10C}(a+b) l_{g} + f l_{\varphi} \le bl_{g} + (f +b - K_{sep})l_{\varphi} \\
&\le bl_{g} + (R  - a- b - K_{sep}) l_{\varphi} =_{10C} |\varphi^{R - (a+f+b)}g^{-b}\varphi^{-f + K_{sep} } |_{\C*}, \\
|g^{c} \varphi^{e} g^{-d} \varphi^{-e}|_{\C*} &=_{10C} (c+d)l_{g} + 2e l_{\varphi}  \le (c+d)l_{g} + (2e+ (R - a-f-2b)) l_{\varphi}\\
&=_{10C} | \varphi^{e} g^{d} \varphi^{-e } g^{-c} \varphi^{a+b+2f - R}|_{\C*}.
\end{aligned}
\]
Further, $|\varphi^{-K_{sep}}|_{\C*}, |g^{-a}|_{\C*} \ge K_{sep}$. This contradicts Display \ref{eqn:contra4Ineq}.





\item $R \in \{a+b+2f, \ldots, a+ b+ 2f + c/2\}$: we have \[\begin{aligned}
\psi &= (g^{a}  \varphi^{f}  g^{b}\varphi^{-f} g^{c}) \cdot \varphi^{e} \cdot (g^{-d} \varphi^{-e}),
\\
v &= (g^{- R +a+b+2f}\varphi^{f}g^{-b}\varphi^{-f}g^{-a} \varphi^{e-K_{sep}})\cdot \varphi^{K_{sep}} g^{K_{sep}} \cdot ( g^{d-K_{sep}} \varphi^{-e } g^{R - a-b-2f - c} ).
\end{aligned}
\]
Note that \[
\begin{aligned}
|g^{a}  \varphi^{f}  g^{b}\varphi^{-f} g^{c}|_{\C*} &=_{10C}(a+b+c) l_{g} + 2f l_{\varphi} \le (a+b)l_{g} + (2f + e - K_{Sep})l_{\varphi} \\
&\le ( R - 2f) l_{g} + (2f + e - K_{sep}) l_{\varphi}=_{10C} |g^{- R +a+b+2f}\varphi^{f}g^{-b}\varphi^{-f}g^{-a} \varphi^{e-K_{sep}} |_{\C*}, \\
|g^{-d} \varphi^{-e}|_{\C*} &=_{10C} dl_{g} + e l_{\varphi}  \le (c/2 + d-K_{sep})l_{g} + e l_{\varphi}\\
&\le (d-K_{sep} + (a+b+2f + c) - R) l_{g} + e l_{\varphi} =_{10C} | g^{d-K_{sep}} \varphi^{-e } g^{R - a-b-2f - c}|_{\C*}.
\end{aligned}
\]
Further, $|\varphi^{K_{sep}}|_{\C*}, |g^{K_{sep}}|_{\C*} \ge K_{sep}$. This contradicts Display \ref{eqn:contra4Ineq}.




\item $R \in \{a+b+2f+c/2 \ldots, a+ b+ 2f + c\}$: we have \[\begin{aligned}
\psi &= (g^{a}  \varphi^{f}  g^{b}) \cdot \varphi^{-f}\cdot ( g^{c} \varphi^{e} g^{-d} \varphi^{-e}),
\\
v &= (g^{- R +a+b+2f}\varphi^{f}) \cdot g^{-b}\varphi^{-K_{sep}} \cdot (\varphi^{-f + K_{sep}}g^{-a} \varphi^{e} g^{d} \varphi^{-e } g^{R - a-b-2f - c} ).
\end{aligned}
\]
Note that \[
\begin{aligned}
|g^{a}\varphi^{f} g^{b}|_{\C*} &=_{10C}(a+b) l_{g} + f l_{\varphi} \le 0.5 c l_{g} + fl_{\varphi} \\
&\le ( R - a-b-2f) l_{g} + f l_{\varphi}=_{10C} |g^{- R +a+b+2f}\varphi^{f} |_{\C*}, \\
|g^{c} \varphi^{e} g^{-d} \varphi^{-e}|_{\C*} &=_{10C} (c+d)l_{g} + 2e l_{\varphi}  \le (a+d)l_{g} + (2e+ f-K_{sep}) l_{\varphi}\\
&\le ((R-a-b-2f-c) + a+d) l_{g} + (2e + f - K_{sep}) l_{\varphi} \\
&=_{10C} | \varphi^{-f + K_{sep}}g^{-a} \varphi^{e} g^{d} \varphi^{-e } g^{R - a-b-2f - c} |_{\C*}.
\end{aligned}
\]
Further, $|\varphi^{-K_{sep}}|_{\C*}, |g^{-b}|_{\C*} \ge K_{sep}$. This contradicts Display \ref{eqn:contra4Ineq}.



\item Remaining cases, i.e., $R \in \{a+ b+ 2f + c, \ldots, a+b+c+d+2e+2f\}$: in these cases, we again use the subword decomposition $\psi= (g^{a}  \varphi^{f}  g^{b}) \cdot \varphi^{-f}\cdot ( g^{c} \varphi^{e} g^{-d} \varphi^{-e})$. The word $v$ has decomposition $v = v_f \cdot g^{-b}\varphi^{-K_{sep}} \cdot v_{b}$, where \begin{itemize}
\item $v_{f} = \varphi^{-k} g^{-c}\varphi^{f}$ and $v_{b}= \varphi^{-f + K_{sep}}g^{-a}\varphi^{e} g^{d} \varphi^{-(e-k)}$ for some $0 \le k \le e$, or
\item $v_{f} =g^{k}\varphi^{-e} g^{-c}\varphi^{f}$ and $v_{b}= \varphi^{-f + K_{sep}}g^{-a} \varphi^{e} g^{d-k}$ for some $0 \le k \le d$, or
\item $v_{f}=\varphi^{k}g^{d}\varphi^{-e} g^{-c}\varphi^{f}$ and $v_{b}=\varphi^{-f + K_{sep}}g^{-a} \varphi^{e-k}$ for some $0 \le k \le e$.
\end{itemize}
In each of these cases, we have \[
|v_{f}|_{\C*} \ge | g^{-c}\varphi^{f}|_{\C*} =_{10C} cl_{g} + fl_{\varphi} \ge (a+b)l_{g} + fl_{g} =_{10C} |g^{a} \varphi^{f} g^{b}|_{\C*}.
\]
Moreover, we have \[
|v_{b}|_{\C*} \ge |\varphi^{-f + K_{sep}}g^{-a}|_{\C*} =_{10C} a l_{g} +  (f-K_{sep})l_{\varphi} \ge (c+d)l_{g} + 2el_{\varphi} = |g^{c} \varphi^{e} g^{-d} \varphi^{-e}|_{\C*} .
\]Further, $|\varphi^{-K_{sep}}|_{\C*}, |g^{-b}|_{\C*} \ge K_{sep}$. This contradicts Display \ref{eqn:contra4Ineq}.
\end{enumerate}

All in all, there is no $\phi_{T} \in \Homeo(S)$ realizing Display \ref{eqn:contraT} for $T = 20(K+C)/\Xi C + 100$. Hence, $\psi \not\sim \psi^{-1}$.
\end{proof}

Let us now consider $1 \ll a \ll b \ll c \le d \ll e \ll f \ll a' \ll b' \ll c' \le d' \ll e' \ll f'$ and construct  \[
\psi = g^{a} \cdot \varphi^{f} g^{b} \varphi^{-f} \cdot g^{c} \cdot \varphi^{e} g^{-d} \varphi^{-e}, \quad \psi' = g^{a'} \cdot \varphi^{f'} g^{b'} \varphi^{-f'} \cdot g^{c'} \cdot \varphi^{e'} g^{-d'} \varphi^{-e'}.
\]
Let $(p_{i})_{i \in \Z}$ be the $\{g, \varphi\}$-word sequence for $\psi$, i.e., $p_{0} = x_{0}, p_{1} = g x_{0}, \ldots, p_{a+1} = g^{a} \varphi x_{0}, \ldots, p_{a+b+c+d+2e+2f} = \psi x_{0}$, and $p_{k(a+b+c+d+2e+2f) + i}= \psi^{k} p_{i}$. Similarly define the $\{g, \varphi\}$-word sequence $(q_{i})_{i \in \Z}$ for $\psi'$. These sequences are uniform quasi-geodesics.

Suppose to the contrary that arbitrarily long subsequence of  $(q_{i})_{i \in \Z}$ is fellow traveled by a $\Homeo(S)$-translate of a subsequence of $(q_{i})_{i \in \Z}$. In particular, suppose that there exists $\phi \in \Homeo(S)$ such that $(q_{a'}, \ldots, q_{a'+f'})$ and $(\phi p_{i}, \ldots, \phi p_{j})$ are $10C$-fellow traveling for some $i<j$. Since $d_{\C*(S)}(p_{i}, p_{j})$ is at most $0.9C|j-i|$, $j-i$ is much larger than $a+b+c+d+2e+2f$ (since $f' \gg a, b, c, d, e, f$). This implies that there is a full period for $\psi$ between $i$ and $j$, of the form $\{ M (a+b+c+d+2e+2f), \ldots, (M+1) (a+b+c+d+ 2e+2f)\}$. Hence, there exists $a' < k < m < a'+f'$ such that \[
d_{\C*(S)} (\varphi^{k} x_{0}, \phi \psi^{M} g^{a} \cdot x_{0}) < 10C, \quad 
d_{\C*(S)} (\varphi^{m} x_{0}, \phi \psi^{M} g^{a} \cdot \varphi^{f} \cdot g^{b} x_{0}) < 10C.
\]
This cannot happen for large enough $f$ and $b$, as $(\ldots, \phi^{-2}, \phi^{-1}, id, g, g^{2}, \ldots) \not\sim (\varphi^{l})_{l \in \Z}$. In conclusion, $\psi \not \sim \psi'$.

Note also that every long enough subsequence of $(q_{-i} )_{i \in \Z}$ (the reversal of $(q_{i})_{i \in \Z}$) contains a translate of $(x_{0}, \varphi x_{0}, \ldots, \varphi^{f'} x_{0})$ as well. For a similar reason, we obtain $\psi^{-1} \not \sim \psi'$, given that $1 \ll a \ll b \ll \ldots \ll f \ll a' \ll b' \ll \ldots \ll f'$.


To summarize, we have: \begin{claim}\label{claim:psiInd}
For \[\begin{aligned}
1 &\ll a_{1} \ll b_{1} \ll c_{1} \le d_{1} \ll e_{1} \ll  f_{1} \\
&\ll a_{2} \ll b_{2} \ll c_{2} \le d_{2} \ll e_{2} \ll  f_{2} \ll a_{3} \ll \ldots,
\end{aligned}
\] the homeomorphisms $\psi_{i} := \psi_{a_{i}, b_{i}, c_{i}, d_{i}, e_{i}, f_{i}} \in \Homeo(S)$ satisfy that: \begin{enumerate}
\item $\psi_{i}$ fixes an open neighborhood of $p$ for each $i$;
\item $\psi_{i} \not\sim \psi_{j}^{\pm}$ for each $i<j$, and 
\item $\psi_{i} \not \sim \psi_{i}^{-1}$ for each $i$.
\end{enumerate}
\end{claim}


Now let $D$ be a closed disc embedded in $S$. One can conjugate $\psi_{i}$ to a homeomorphism $\Psi_{i}$ (in $\Homeo(S)$) that fixes $D$, by a conjugator that sends $D$ into the fixed point set of $\psi_{i}$, a neighborhood of $p$. It follows that $\psi_{i}^{\pm 1} \sim \Psi_{i}^{\pm 1}$. Since $\sim$ is a transitive relation, we conclude:

\begin{prop}\label{prop:DUnifInd}
Let $D$ be a closed disc embedded in $S$. Then there exist infinitely many homeomorphisms $\Psi_{1}, \Psi_{2}, \ldots \in \Homeo(S)$ such that: \begin{enumerate}
\item $\Psi_{i}$ fixes $D$ for each $i$;
\item $\Psi_{i} \not\sim \Psi_{j}^{\pm}$ for each $i<j$, and 
\item $\Psi_{i} \not \sim \Psi_{i}^{-1}$ for each $i$.
\end{enumerate}
\end{prop}

As observed by Brooks \cite{MR624804} and generalized by Bestvina and Fujiwara for WPD actions on $\delta$-hyperbolic spaces \cite{bestvina2002bounded}, one can construct countably infinitely many linearly independent quasi-morphisms $Q_{1}, Q_{2}, \ldots$ that are unbounded on $Fix_{D}$. Namely, for each $i$, there exists a Brooks quasi-morphism that assigns nonzero value on some power of $\Psi_{i}$, but assigns zero value on any power of $\Psi_{j}$ for $j \neq i$. Since $\Psi_{i}^{k} \in Fix_{D}$ for each $k$, we conclude:


\begin{cor}\label{cor:inf}
Let $S = \mathbb{T}^{2}$ be the torus and let $D$ be an embedded closed disc on $S$. Let $Fix_{D} \le \Homeo(S)$ be the group of homeomorphisms that preserve $D$ pointwise. Then the space $\widetilde{QH}(\Homeo(S); Fix_{D} \cap \Homeo_{0}(S))$ of quasi-morphisms on $\Homeo(S)$ that is unbounded on $Fix_{D} \cap \Homeo_{0}(S)$ is infinite dimensional.
\end{cor}





